    switch (type) {
        case 'feature':
            return { icon: Sparkles, color: 'text-blue-600 dark:text-blue-400', bg: 'bg-blue-100 dark:bg-blue-900/30', gradient: 'from-blue-500 to-cyan-500', label: 'Yeni Özellik' };
