        case 'fix':
            return { icon: Bug, color: 'text-amber-600 dark:text-amber-400', bg: 'bg-amber-100 dark:bg-amber-900/30', gradient: 'from-amber-500 to-orange-500', label: 'Düzeltme' };
        case 'security':
