    avatar?: string;
    title?: string;
    isStaff?: boolean;
    reputation: number;
    postCount: number;
    joinedAt: string;
  };
  board: {
    id: string;
    name: string;
    slug: string;
  };
  viewCount: number;
  replyCount: number;
  reactionCount: number;
  isWatching: boolean;
  createdAt: string;
  tags: string[];
}

interface ForumPost {
  id: string;
