                          className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-sm ${
                            reaction.userReacted
                              ? "bg-indigo-100 text-indigo-700"
                              : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                          }`}
                        >
                          {getReactionIcon(reaction.type)}
