import { Metadata } from "next";
import { notFound } from "next/navigation";
import { prisma } from "@/lib/prisma";
import { CmsPageRenderer } from "@/components/cms/CmsPageRenderer";

interface PageProps {
  params: Promise<{ slug: string }>;
}

// Tüm sayfa slurlarını statik oluşturma için getir
export async function generateStaticParams() {
  try {
    const pages = await prisma.page.findMany({
      where: {
        isActive: true,
        status: "PUBLISHED",
      },
      select: { slug: true },
    });

    return pages.map((page: { slug: string }) => ({ slug: page.slug }));
  } catch (error) {
    console.error('[CMS] generateStaticParams database error:', error);
    return [];
  }
}

// Sayfa metadata'larını oluştur
export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  try {
    const { slug } = await params;
    const page = await prisma.page.findUnique({
      where: {
        slug,
        isActive: true,
        status: "PUBLISHED",
      },
    });

    if (!page) {
      return {
        title: "Sayfa Bulunamadı",
      };
    }

    return {
      title: page.metaTitle || page.title,
      description: page.metaDescription || page.description,
      keywords: page.metaKeywords,
      openGraph: page.ogImage
        ? {
            images: [{ url: page.ogImage }],
          }
        : undefined,
      robots: page.noIndex ? { index: false, follow: false } : undefined,
      alternates: page.canonicalUrl
        ? { canonical: page.canonicalUrl }
        : undefined,
    };
  } catch (error) {
    console.error('[CMS] generateMetadata database error:', error);
    return {
      title: "Pazaryonetimi - CMS Sayfası",
    };
  }
}

// Dinamik CMS sayfası
export default async function CmsPage({ params }: PageProps) {
  try {
    const { slug } = await params;
    const page = await prisma.page.findUnique({
      where: {
        slug,
        isActive: true,
        status: "PUBLISHED",
      },
      include: {
        sections: {
          where: { isActive: true },
          orderBy: { sortOrder: "asc" },
          include: {
            blocks: {
              where: { isActive: true },
              orderBy: { sortOrder: "asc" },
            },
          },
        },
      },
    });

    if (!page) {
      notFound();
  }

  // Transform Prisma data to match expected types (convert null to undefined)
  const transformedPage = {
    ...page,
    sections: page.sections.map((section: any) => ({
      ...section,
      blocks: section.blocks.map((block: any) => ({
        ...block,
        customClass: block.customClass ?? undefined,
        name: block.name ?? undefined,
      })),
    })),
  };

  return (
    <main>
      {page.customCss && (
        <style dangerouslySetInnerHTML={{ __html: page.customCss }} />
      )}
      <CmsPageRenderer page={transformedPage} />
    </main>
  );
  } catch (error) {
    console.error('[CMS] CmsPage database error:', error);
    notFound();
  }
}

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";

export async function getInvoices(tenantId: string) {
    try {
        const invoices = await prisma.invoice.findMany({
            where: { tenantId },
            orderBy: { createdAt: 'desc' }
        });

        // Calculate statistics
        const totalAmount = invoices.reduce((acc, inv) => acc + Number(inv.totalAmount || 0), 0);
        const totalTax = invoices.reduce((acc, inv) => acc + Number(inv.taxAmount || 0), 0);

        const statusCounts: Record<string, number> = {};
        invoices.forEach(inv => {
            statusCounts[inv.status] = (statusCounts[inv.status] || 0) + 1;
        });

        const byStatus = Object.keys(statusCounts).map(status => ({
            status,
            count: statusCounts[status]
        }));

        const stats = {
            total: invoices.length,
            totals: { amount: totalAmount, tax: totalTax },
            byStatus
        };

        const serializedInvoices = invoices.map(inv => ({
            id: inv.id,
            invoiceNumber: inv.invoiceNumber,
            invoiceDate: inv.invoiceDate.toISOString(),
            buyerTitle: inv.buyerTitle || 'Bilinmiyor',
            buyerTaxNumber: inv.buyerTaxNumber || '-',
            type: inv.type,
            scenario: inv.scenario,
            status: inv.status,
            totalAmount: Number(inv.totalAmount || 0),
            taxAmount: Number(inv.taxAmount || 0),
            currency: inv.currency,
            gibInvoiceId: inv.gibInvoiceId
        }));

        return { success: true, invoices: serializedInvoices, stats };
    } catch (error) {
        console.error("Error fetching invoices:", error);
        return { success: false, invoices: [], stats: null, error: "Faturalar yüklenemedi." };
    }
}

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";

export async function saveWorkflow(tenantId: string, name: string, nodes: any[]) {
    try {
        if (!nodes || nodes.length < 2) {
            return { success: false, error: "Akış en az bir tetikleyici ve bir aksiyon içermelidir." };
        }

        // The first node is usually the trigger. The rest are actions.
        const triggerNode = nodes[0];
        const actionNodes = nodes.slice(1);

        // Serialize the full node structure into the conditions JSON so we can reconstruct the UI later
        const conditionsJson = JSON.stringify(nodes);

        const automation = await prisma.automation.create({
            data: {
                tenantId,
                name,
                type: "custom-workflow",
                trigger: triggerNode.title, // e.g. 'Sipariş Geldiğinde'
                action: actionNodes.map(n => n.title).join(', '), // e.g. 'SMS At, Fatura Kes'
                conditions: JSON.parse(conditionsJson), // Store the exact UI format
                isActive: true
            }
        });

        revalidatePath('/dashboard/workflow-builder');
        return { success: true, automation };
    } catch (error) {
        console.error("Error saving workflow:", error);
        return { success: false, error: "Akış kaydedilemedi." };
    }
}

export async function getActiveWorkflows(tenantId: string) {
    try {
        const workflows = await prisma.automation.findMany({
            where: { tenantId, type: "custom-workflow" },
            orderBy: { createdAt: 'desc' }
        });
        return workflows;
    } catch (error) {
        console.error("Error fetching workflows:", error);
        return [];
    }
}

