"use client";

import React, { useState, useEffect } from 'react';
import {
  Megaphone, AlertTriangle, Bell, Clock, Send, Trash2, History,
  Power, Eye, Calendar, CheckCircle, XCircle
} from 'lucide-react';

interface Announcement {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'warning' | 'critical';
  targetAudience: 'all' | 'paying' | 'trial';
  createdAt: string;
  expiresAt: string | null;
  sent: boolean;
}

interface MaintenanceMode {
  enabled: boolean;
  message: string;
  expectedEndTime: string | null;
  allowedIps: string[];
  lastUpdated: string;
}

export default function AnnouncementsPage() {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [maintenance, setMaintenance] = useState<MaintenanceMode>({
    enabled: false,
    message: 'Sistemimiz şu anda bakım modundadır. Kısa süre içinde tekrar erişilebilir olacaktır.',
    expectedEndTime: null,
    allowedIps: [],
    lastUpdated: new Date().toISOString(),
  });
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [showNewAnnouncement, setShowNewAnnouncement] = useState(false);
  const [newAnnouncement, setNewAnnouncement] = useState({
    title: '',
    message: '',
    type: 'info' as 'info' | 'warning' | 'critical',
    targetAudience: 'all' as 'all' | 'paying' | 'trial',
    expiresAt: '',
  });
  const [showMaintenanceEdit, setShowMaintenanceEdit] = useState(false);
  const [maintenanceForm, setMaintenanceForm] = useState({ ...maintenance });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [announcementsRes, maintenanceRes] = await Promise.all([
        fetch('/api/admin/announcements'),
        fetch('/api/admin/maintenance'),
      ]);
      if (!announcementsRes.ok || !maintenanceRes.ok) {
        throw new Error('Duyuru veya bakım verisi alınamadı');
      }
      const announcementsData = await announcementsRes.json();
      const maintenanceData = await maintenanceRes.json();
      setAnnouncements(Array.isArray(announcementsData) ? announcementsData : []);
      setMaintenance(maintenanceData);
    } catch (error) {
      console.error('Duyuru verileri yüklenemedi:', error);
      setAnnouncements([]);
    } finally {
      setLoading(false);
    }
  };

  const sendAnnouncement = async () => {
    if (!newAnnouncement.title || !newAnnouncement.message) return;

    setSending(true);
    try {
      const res = await fetch('/api/admin/announcement', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAnnouncement),
      });
      if (!res.ok) throw new Error('Duyuru gönderilemedi');
      const data = await res.json();
      setAnnouncements(prev => [{
        id: data.id || Date.now().toString(),
        ...newAnnouncement,
        createdAt: new Date().toISOString(),
        expiresAt: newAnnouncement.expiresAt || null,
        sent: true,
      }, ...prev]);
    } catch (error) {
      console.error('Duyuru gönderme hatası:', error);
    } finally {
      setSending(false);
      setShowNewAnnouncement(false);
      setNewAnnouncement({ title: '', message: '', type: 'info', targetAudience: 'all', expiresAt: '' });
    }
  };

  const toggleMaintenance = async () => {
    const newEnabled = !maintenance.enabled;
    try {
      const res = await fetch('/api/admin/maintenance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...maintenance, enabled: newEnabled }),
      });
      if (!res.ok) throw new Error('Bakım modu güncellenemedi');
    } catch (error) {
      console.error('Bakım modu güncellenemedi:', error);
      return;
    }
    setMaintenance(prev => ({ ...prev, enabled: newEnabled, lastUpdated: new Date().toISOString() }));
  };

  const updateMaintenance = async () => {
    try {
      const res = await fetch('/api/admin/maintenance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(maintenanceForm),
      });
      if (!res.ok) throw new Error('Bakım ayarları kaydedilemedi');
    } catch (error) {
      console.error('Bakım ayarları kaydedilemedi:', error);
      return;
    }
    setMaintenance({ ...maintenanceForm, lastUpdated: new Date().toISOString() });
    setShowMaintenanceEdit(false);
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('tr-TR', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const typeConfig = {
    info: { label: 'Bilgi', color: 'bg-blue-500/10 text-blue-600', icon: <Bell size={16} /> },
    warning: { label: 'Uyarı', color: 'bg-yellow-500/10 text-yellow-600', icon: <AlertTriangle size={16} /> },
    critical: { label: 'Kritik', color: 'bg-red-500/10 text-red-600', icon: <AlertTriangle size={16} /> },
  };

  const audienceConfig = {
    all: 'Tüm Kullanıcılar',
    paying: 'Ödeme Yapan',
    trial: 'Deneme Sürecinde',
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-500" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-2xl font-black text-foreground flex items-center gap-3">
            <div className="p-2 bg-orange-500/10 rounded-xl">
              <Megaphone className="w-6 h-6 text-orange-500" />
            </div>
            Duyurular & Bakım Modu
          </h1>
          <p className="text-slate-500 mt-1">Platform genelinde duyurular gönderin ve bakım modunu yönetin</p>
        </div>
        <button
          onClick={() => setShowNewAnnouncement(true)}
          className="flex items-center gap-2 px-4 py-2 bg-orange-600 text-white rounded-xl font-bold text-sm hover:bg-orange-700 transition-colors"
        >
          <Send size={16} />
          Yeni Duyuru
        </button>
      </div>

      {/* Maintenance Mode Card */}
      <div className={`rounded-2xl border-2 p-6 ${maintenance.enabled
          ? 'bg-red-50 dark:bg-red-900/10 border-red-300 dark:border-red-500/30'
          : 'bg-white dark:bg-slate-900/50 border-slate-200 dark:border-white/5'
        }`}>
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-4">
            <div className={`p-3 rounded-xl ${maintenance.enabled ? 'bg-red-500 text-white' : 'bg-slate-100 dark:bg-slate-800'}`}>
              <Power size={24} />
            </div>
            <div>
              <h3 className="font-bold text-xl text-foreground flex items-center gap-3">
                Bakım Modu
                <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${maintenance.enabled ? 'bg-red-500 text-white' : 'bg-green-500/10 text-green-600'
                  }`}>
                  {maintenance.enabled ? 'AKTİF' : 'KAPALI'}
                </span>
              </h3>
              <p className="text-slate-500 mt-1">{maintenance.message}</p>
              {maintenance.expectedEndTime && (
                <p className="text-sm text-slate-500 mt-2 flex items-center gap-1">
                  <Clock size={14} />
                  Tahmini bitiş: {formatDate(maintenance.expectedEndTime)}
                </p>
              )}
            </div>
          </div>
          <div className="flex gap-3">
            <button
              onClick={() => { setMaintenanceForm({ ...maintenance }); setShowMaintenanceEdit(true); }}
              className="px-4 py-2 bg-slate-100 dark:bg-slate-800 rounded-lg font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
            >
              Ayarlar
            </button>
            <button
              onClick={toggleMaintenance}
              className={`px-4 py-2 rounded-lg font-bold text-sm transition-colors ${maintenance.enabled
                  ? 'bg-green-600 text-white hover:bg-green-700'
                  : 'bg-red-600 text-white hover:bg-red-700'
                }`}
            >
              {maintenance.enabled ? 'Devre Dışı Bırak' : 'Etkinleştir'}
            </button>
          </div>
        </div>
      </div>

      {/* Announcements List */}
      <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 overflow-hidden">
        <div className="p-4 border-b border-slate-200 dark:border-white/5 flex items-center gap-2">
          <History size={18} />
          <h3 className="font-bold text-foreground">Duyuru Geçmişi</h3>
        </div>
        <div className="divide-y divide-slate-200 dark:divide-white/5">
          {announcements.map((announcement) => (
            <div key={announcement.id} className="p-6">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className={`flex items-center gap-1 text-xs font-bold px-2 py-1 rounded-full ${typeConfig[announcement.type].color}`}>
                      {typeConfig[announcement.type].icon}
                      {typeConfig[announcement.type].label}
                    </span>
                    <span className="text-xs text-slate-500 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-full">
                      {audienceConfig[announcement.targetAudience]}
                    </span>
                    {announcement.sent && (
                      <span className="flex items-center gap-1 text-xs text-green-600">
                        <CheckCircle size={14} />
                        Gönderildi
                      </span>
                    )}
                  </div>
                  <h4 className="font-bold text-foreground">{announcement.title}</h4>
                  <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">{announcement.message}</p>
                  <p className="text-xs text-slate-500 mt-3 flex items-center gap-1">
                    <Calendar size={12} />
                    {formatDate(announcement.createdAt)}
                  </p>
                </div>
              </div>
            </div>
          ))}
          {announcements.length === 0 && (
            <div className="p-12 text-center text-slate-500">
              <Megaphone className="w-12 h-12 mx-auto mb-4 opacity-30" />
              <p>Henüz duyuru gönderilmedi</p>
            </div>
          )}
        </div>
      </div>

      {/* New Announcement Modal */}
      {showNewAnnouncement && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowNewAnnouncement(false)}>
          <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 max-w-lg w-full mx-4" onClick={e => e.stopPropagation()}>
            <h3 className="font-bold text-xl text-foreground mb-6">Yeni Duyuru</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Başlık *</label>
                <input
                  type="text"
                  value={newAnnouncement.title}
                  onChange={(e) => setNewAnnouncement({ ...newAnnouncement, title: e.target.value })}
                  placeholder="Duyuru başlığı..."
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Mesaj *</label>
                <textarea
                  value={newAnnouncement.message}
                  onChange={(e) => setNewAnnouncement({ ...newAnnouncement, message: e.target.value })}
                  placeholder="Duyuru içeriği..."
                  rows={4}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Tür</label>
                  <select
                    value={newAnnouncement.type}
                    onChange={(e) => setNewAnnouncement({ ...newAnnouncement, type: e.target.value as any })}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                  >
                    <option value="info">Bilgi</option>
                    <option value="warning">Uyarı</option>
                    <option value="critical">Kritik</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Hedef</label>
                  <select
                    value={newAnnouncement.targetAudience}
                    onChange={(e) => setNewAnnouncement({ ...newAnnouncement, targetAudience: e.target.value as any })}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                  >
                    <option value="all">Tüm Kullanıcılar</option>
                    <option value="paying">Ödeme Yapanlar</option>
                    <option value="trial">Deneme Sürecinde</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Bitiş Tarihi (opsiyonel)</label>
                <input
                  type="datetime-local"
                  value={newAnnouncement.expiresAt}
                  onChange={(e) => setNewAnnouncement({ ...newAnnouncement, expiresAt: e.target.value })}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setShowNewAnnouncement(false)}
                className="flex-1 py-3 bg-slate-100 dark:bg-slate-800 rounded-xl font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700"
              >
                İptal
              </button>
              <button
                onClick={sendAnnouncement}
                disabled={sending || !newAnnouncement.title || !newAnnouncement.message}
                className="flex-1 py-3 bg-orange-600 text-white rounded-xl font-bold text-sm hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {sending ? (
                  <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent" />
                ) : (
                  <>
                    <Send size={16} />
                    Gönder
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Maintenance Settings Modal */}
      {showMaintenanceEdit && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowMaintenanceEdit(false)}>
          <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 max-w-lg w-full mx-4" onClick={e => e.stopPropagation()}>
            <h3 className="font-bold text-xl text-foreground mb-6">Bakım Modu Ayarları</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Mesaj</label>
                <textarea
                  value={maintenanceForm.message}
                  onChange={(e) => setMaintenanceForm({ ...maintenanceForm, message: e.target.value })}
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">Tahmini Bitiş</label>
                <input
                  type="datetime-local"
                  value={maintenanceForm.expectedEndTime || ''}
                  onChange={(e) => setMaintenanceForm({ ...maintenanceForm, expectedEndTime: e.target.value })}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">İzinli IP&apos;ler (virgülle ayrılmış)</label>
                <input
                  type="text"
                  value={maintenanceForm.allowedIps.join(', ')}
                  onChange={(e) => setMaintenanceForm({ ...maintenanceForm, allowedIps: e.target.value.split(',').map(ip => ip.trim()).filter(Boolean) })}
                  placeholder="192.168.1.1, 10.0.0.1"
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setShowMaintenanceEdit(false)}
                className="flex-1 py-3 bg-slate-100 dark:bg-slate-800 rounded-xl font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700"
              >
                İptal
              </button>
              <button
                onClick={updateMaintenance}
                className="flex-1 py-3 bg-orange-600 text-white rounded-xl font-bold text-sm hover:bg-orange-700"
              >
                Kaydet
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import {
  Activity, BarChart3, AlertTriangle, TrendingUp, Zap, Clock,
  Users, Server, Filter, ChevronDown, ChevronUp
} from 'lucide-react';

interface TenantUsage {
  tenantId: string;
  tenantName: string;
  requests: number;
  limit: number;
  percentage: number;
}

interface HourlyStat {
  hour: number;
  requests: number;
  errors: number;
}

interface EndpointStat {
  endpoint: string;
  count: number;
  avgResponseTime: number;
}

interface AbuseAlert {
  tenantId: string;
  reason: string;
  severity: 'warning' | 'critical';
}

export default function ApiUsagePage() {
  const [data, setData] = useState<{
    tenantUsage: TenantUsage[];
    hourlyStats: HourlyStat[];
    topEndpoints: EndpointStat[];
    totalRequests: number;
    abuseAlerts: AbuseAlert[];
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [sortBy, setSortBy] = useState<'requests' | 'percentage'>('percentage');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const res = await fetch('/api/admin/api-usage');
      if (!res.ok) throw new Error('API kullanım verileri alınamadı');
      const usageData = await res.json();
      setData(usageData);
    } catch (error) {
      console.error('API kullanım verileri yüklenemedi:', error);
      setData({
        tenantUsage: [],
        hourlyStats: [],
        topEndpoints: [],
        totalRequests: 0,
        abuseAlerts: [],
      });
    } finally {
      setLoading(false);
    }
  };

  const formatNumber = (num: number) => {
    return new Intl.NumberFormat('tr-TR').format(num);
  };

  const sortedUsage = data?.tenantUsage.slice().sort((a, b) => {
    const multiplier = sortDir === 'desc' ? -1 : 1;
    return multiplier * (a[sortBy] - b[sortBy]);
  }) || [];

  const toggleSort = (field: 'requests' | 'percentage') => {
    if (sortBy === field) {
      setSortDir(sortDir === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(field);
      setSortDir('desc');
    }
  };

  if (loading || !data) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-black text-foreground flex items-center gap-3">
          <div className="p-2 bg-cyan-500/10 rounded-xl">
            <Activity className="w-6 h-6 text-cyan-500" />
          </div>
          API Kullanım Paneli
        </h1>
        <p className="text-slate-500 mt-1">Tenant bazında API kullanım metrikleri ve limitler</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2 bg-cyan-500/10 rounded-lg">
              <Zap className="w-5 h-5 text-cyan-500" />
            </div>
            <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Toplam İstek</span>
          </div>
          <div className="text-3xl font-black text-foreground">{formatNumber(data.totalRequests)}</div>
          <div className="text-xs text-slate-500 mt-1">Son 24 saat</div>
        </div>

        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2 bg-green-500/10 rounded-lg">
              <TrendingUp className="w-5 h-5 text-green-500" />
            </div>
            <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Ortalama/Saat</span>
          </div>
          <div className="text-3xl font-black text-foreground">{formatNumber(Math.round(data.totalRequests / 24))}</div>
        </div>

        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2 bg-purple-500/10 rounded-lg">
              <Users className="w-5 h-5 text-purple-500" />
            </div>
            <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Aktif Tenant</span>
          </div>
          <div className="text-3xl font-black text-foreground">{data.tenantUsage.length}</div>
        </div>

        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2 bg-red-500/10 rounded-lg">
              <AlertTriangle className="w-5 h-5 text-red-500" />
            </div>
            <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Uyarı</span>
          </div>
          <div className="text-3xl font-black text-red-600">{data.abuseAlerts.length}</div>
        </div>
      </div>

      {/* Abuse Alerts */}
      {data.abuseAlerts.length > 0 && (
        <div className="bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-500/20 rounded-2xl p-6">
          <h3 className="font-bold text-red-700 dark:text-red-400 flex items-center gap-2 mb-4">
            <AlertTriangle className="w-5 h-5" />
            Kullanım Uyarıları
          </h3>
          <div className="space-y-3">
            {data.abuseAlerts.map((alert, idx) => (
              <div
                key={idx}
                className={`flex items-center justify-between p-3 rounded-lg ${alert.severity === 'critical'
                    ? 'bg-red-100 dark:bg-red-900/20'
                    : 'bg-yellow-100 dark:bg-yellow-900/20'
                  }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-2 h-2 rounded-full ${alert.severity === 'critical' ? 'bg-red-500' : 'bg-yellow-500'
                    }`} />
                  <span className="font-medium text-foreground">
                    {data.tenantUsage.find(t => t.tenantId === alert.tenantId)?.tenantName}
                  </span>
                </div>
                <span className={`text-sm ${alert.severity === 'critical' ? 'text-red-600' : 'text-yellow-600'
                  }`}>
                  {alert.reason}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Tenant Usage */}
        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
          <h3 className="font-bold text-foreground flex items-center gap-2 mb-6">
            <Users className="w-5 h-5 text-purple-500" />
            Tenant Kullanımı
          </h3>
          <div className="space-y-4">
            <div className="flex items-center justify-between text-xs font-bold text-slate-500 uppercase tracking-wider pb-2 border-b border-slate-200 dark:border-white/5">
              <span>Tenant</span>
              <div className="flex items-center gap-4">
                <button
                  onClick={() => toggleSort('requests')}
                  className="flex items-center gap-1 hover:text-slate-700"
                >
                  İstek
                  {sortBy === 'requests' && (sortDir === 'desc' ? <ChevronDown size={14} /> : <ChevronUp size={14} />)}
                </button>
                <button
                  onClick={() => toggleSort('percentage')}
                  className="flex items-center gap-1 hover:text-slate-700"
                >
                  Kullanım
                  {sortBy === 'percentage' && (sortDir === 'desc' ? <ChevronDown size={14} /> : <ChevronUp size={14} />)}
                </button>
              </div>
            </div>
            {sortedUsage.map((tenant) => (
              <div key={tenant.tenantId} className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="font-medium text-foreground">{tenant.tenantName}</span>
                  <span className="text-sm text-slate-500">
                    {formatNumber(tenant.requests)} / {formatNumber(tenant.limit)}
                  </span>
                </div>
                <div className="h-2 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                  <div
                    className={`h-full rounded-full transition-all ${tenant.percentage >= 90 ? 'bg-red-500' :
                        tenant.percentage >= 70 ? 'bg-yellow-500' :
                          'bg-green-500'
                      }`}
                    style={{ width: `${tenant.percentage}%` }}
                  />
                </div>
                <div className="text-right text-xs text-slate-500">%{tenant.percentage}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Top Endpoints */}
        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
          <h3 className="font-bold text-foreground flex items-center gap-2 mb-6">
            <Server className="w-5 h-5 text-cyan-500" />
            En Çok Kullanılan Endpoint&apos;ler
          </h3>
          <div className="space-y-4">
            {data.topEndpoints.map((endpoint, idx) => (
              <div
                key={idx}
                className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl"
              >
                <div>
                  <code className="text-sm font-mono text-foreground">{endpoint.endpoint}</code>
                  <div className="text-xs text-slate-500 mt-1">{formatNumber(endpoint.count)} istek</div>
                </div>
                <div className="text-right">
                  <div className={`text-sm font-bold ${endpoint.avgResponseTime > 200 ? 'text-yellow-600' : 'text-green-600'
                    }`}>
                    {endpoint.avgResponseTime}ms
                  </div>
                  <div className="text-xs text-slate-500">ort. yanıt</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Hourly Chart */}
      <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 p-6">
        <h3 className="font-bold text-foreground flex items-center gap-2 mb-6">
          <BarChart3 className="w-5 h-5 text-blue-500" />
          Saatlik Dağılım
        </h3>
        <div className="flex items-end gap-1 h-40">
          {data.hourlyStats.map((stat, idx) => {
            const maxRequests = Math.max(...data.hourlyStats.map(s => s.requests));
            const height = (stat.requests / maxRequests) * 100;
            return (
              <div
                key={idx}
                className="flex-1 group cursor-pointer relative"
              >
                <div
                  className="bg-blue-500 hover:bg-blue-600 rounded-t transition-all"
                  style={{ height: `${height}%` }}
                />
                <div className="opacity-0 group-hover:opacity-100 absolute -top-12 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-xs px-2 py-1 rounded whitespace-nowrap z-10">
                  {stat.hour}:00 - {formatNumber(stat.requests)} istek
                </div>
              </div>
            );
          })}
        </div>
        <div className="flex justify-between text-xs text-slate-500 mt-2">
          <span>00:00</span>
          <span>06:00</span>
          <span>12:00</span>
          <span>18:00</span>
          <span>23:00</span>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { adminApi } from '@/lib/admin-api';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import {
    Database, Clock, Download, Play, Pause, Plus, Save, X,
    CheckCircle, XCircle, Loader2, AlertTriangle, RefreshCw,
    Server, Shield, HardDrive, Calendar, Settings, ChevronRight,
    Archive, RotateCcw, Trash2, Eye, Activity, Zap
} from 'lucide-react';

const scheduleSchema = z.object({
    name: z.string().min(2, 'En az 2 karakter'),
    frequency: z.enum(['daily', 'weekly', 'monthly']),
    retentionDays: z.number().min(1).max(365),
    includeMedia: z.boolean(),
});

type ScheduleFormData = z.infer<typeof scheduleSchema>;

interface Backup {
    id: string;
    status: string;
    type: string;
    size: number;
    createdAt: string;
}

interface Schedule {
    id: string;
    name: string;
    frequency: string;
    retentionDays: number;
    includeMedia: boolean;
    isActive?: boolean;
}

interface DRSettings {
    rpo: string;
    rto: string;
    replicationStatus: string;
    autoFailover: boolean;
    crossRegion: boolean;
    pitr: boolean;
    encrypted: boolean;
}

export default function BackupsPage() {
    const queryClient = useQueryClient();
    const [activeTab, setActiveTab] = useState<'backups' | 'schedules' | 'dr'>('backups');
    const [isCreatingSchedule, setIsCreatingSchedule] = useState(false);
    const [restoreConfirm, setRestoreConfirm] = useState<string | null>(null);

    const { data: backups, isLoading: backupsLoading } = useQuery({
        queryKey: ['admin-backups'],
        queryFn: () => adminApi.getBackups(),
        enabled: activeTab === 'backups',
    });

    const { data: schedules, isLoading: schedulesLoading } = useQuery({
        queryKey: ['backup-schedules'],
        queryFn: () => adminApi.getBackupSchedules(),
        enabled: activeTab === 'schedules',
    });

    const { data: drSettings, isLoading: drLoading } = useQuery({
        queryKey: ['dr-settings'],
        queryFn: () => adminApi.getDrSettings(),
        enabled: activeTab === 'dr',
    });

    const createScheduleMutation = useMutation({
        mutationFn: (data: ScheduleFormData) => adminApi.createBackupSchedule(data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['backup-schedules'] });
            setIsCreatingSchedule(false);
            scheduleForm.reset();
        },
    });

    const restoreMutation = useMutation({
        mutationFn: (id: string) => adminApi.restoreBackup(id, false),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['admin-backups'] });
            setRestoreConfirm(null);
        },
    });

    const scheduleForm = useForm<ScheduleFormData>({
        resolver: zodResolver(scheduleSchema),
        defaultValues: { name: '', frequency: 'daily', retentionDays: 30, includeMedia: true },
    });

    const backupList = (Array.isArray(backups) ? backups : (backups?.backups || [])) as Backup[];
    const scheduleList = (Array.isArray(schedules) ? schedules : (schedules?.schedules || [])) as Schedule[];

    const formatDate = (date: string) =>
        new Date(date).toLocaleDateString('tr-TR', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

    const formatSize = (bytes: number) => {
        if (!bytes) return '—';
        const gb = bytes / (1024 * 1024 * 1024);
        if (gb >= 1) return `${gb.toFixed(1)} GB`;
        const mb = bytes / (1024 * 1024);
        return `${mb.toFixed(0)} MB`;
    };

    const tabs = [
        { key: 'backups', label: 'Yedekler', icon: Database },
        { key: 'schedules', label: 'Zamanlamalar', icon: Clock },
        { key: 'dr', label: 'Felaket Kurtarma', icon: Shield },
    ];

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div>
                <h1 className="text-3xl font-black text-foreground tracking-tight">Yedekleme & Felaket Kurtarma</h1>
                <p className="text-slate-500 dark:text-slate-400 font-medium">Yedekleme işlemleri, zamanlama ve DR politikaları</p>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 bg-white dark:bg-slate-900/50 p-1.5 rounded-2xl border border-slate-200 dark:border-white/5 w-fit shadow-sm">
                {tabs.map(tab => {
                    const TabIcon = tab.icon;
                    return (
                        <button
                            key={tab.key}
                            onClick={() => setActiveTab(tab.key as 'backups' | 'schedules' | 'dr')}
                            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === tab.key
                                ? 'bg-blue-500 text-white shadow-lg shadow-blue-500/20'
                                : 'text-slate-500 hover:text-foreground hover:bg-slate-50 dark:hover:bg-white/5'
                                }`}
                        >
                            <TabIcon size={16} /> {tab.label}
                        </button>
                    );
                })}
            </div>

            {/* BACKUPS TAB */}
            {activeTab === 'backups' && (
                <div className="space-y-4">
                    {/* Stats row */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                        {[
                            { label: 'Toplam Yedek', value: backupList.length, icon: Archive, color: 'blue' },
                            { label: 'Başarılı', value: backupList.filter((b: Backup) => b.status === 'completed' || b.status === 'COMPLETED').length, icon: CheckCircle, color: 'green' },
                            { label: 'Başarısız', value: backupList.filter((b: Backup) => b.status === 'failed' || b.status === 'FAILED').length, icon: XCircle, color: 'red' },
                            { label: 'Toplam Boyut', value: formatSize(backupList.reduce((acc: number, b: Backup) => acc + (b.size || 0), 0)), icon: HardDrive, color: 'purple' },
                        ].map((stat, idx) => (
                            <div key={idx} className="bg-white dark:bg-slate-900/50 p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                                <div className="flex items-center gap-3 mb-2">
                                    <div className={`p-2 rounded-xl bg-${stat.color}-500/10`}>
                                        <stat.icon size={18} className={`text-${stat.color}-500`} />
                                    </div>
                                    <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">{stat.label}</span>
                                </div>
                                <div className="text-2xl font-black text-foreground">{stat.value}</div>
                            </div>
                        ))}
                    </div>

                    {/* Backup List */}
                    <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm overflow-hidden">
                        {backupsLoading ? (
                            <div className="p-12 flex justify-center"><Loader2 className="animate-spin text-blue-500" /></div>
                        ) : (
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-slate-200 dark:border-white/5 bg-slate-50 dark:bg-white/[0.02]">
                                        <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Durum</th>
                                        <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Tür</th>
                                        <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Boyut</th>
                                        <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Tarih</th>
                                        <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest text-right">İşlem</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-200 dark:divide-white/5">
                                    {backupList.map((backup: Backup, idx: number) => {
                                        const isCompleted = backup.status === 'completed' || backup.status === 'COMPLETED';
                                        const isFailed = backup.status === 'failed' || backup.status === 'FAILED';
                                        return (
                                            <tr key={backup.id || idx} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors">
                                                <td className="p-4">
                                                    <span className={`flex items-center gap-1 text-xs font-bold ${isCompleted ? 'text-green-500' : isFailed ? 'text-red-500' : 'text-amber-500'
                                                        }`}>
                                                        {isCompleted ? <CheckCircle size={14} /> : isFailed ? <XCircle size={14} /> : <Loader2 size={14} className="animate-spin" />}
                                                        {isCompleted ? 'Başarılı' : isFailed ? 'Başarısız' : 'Devam Ediyor'}
                                                    </span>
                                                </td>
                                                <td className="p-4 text-sm font-bold text-foreground">{backup.type || 'full'}</td>
                                                <td className="p-4 text-sm text-slate-500">{formatSize(backup.size)}</td>
                                                <td className="p-4 text-sm text-slate-500">{backup.createdAt ? formatDate(backup.createdAt) : '—'}</td>
                                                <td className="p-4 text-right">
                                                    <div className="flex gap-2 justify-end">
                                                        {isCompleted && (
                                                            <button
                                                                onClick={() => setRestoreConfirm(backup.id)}
                                                                className="text-xs font-bold text-blue-500 hover:text-blue-600 flex items-center gap-1"
                                                            >
                                                                <RotateCcw size={14} /> Geri Yükle
                                                            </button>
                                                        )}
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                    {backupList.length === 0 && (
                                        <tr><td colSpan={5} className="p-8 text-center text-slate-400 text-sm">Henüz yedek bulunmuyor</td></tr>
                                    )}
                                </tbody>
                            </table>
                        )}
                    </div>
                </div>
            )}

            {/* SCHEDULES TAB */}
            {activeTab === 'schedules' && (
                <div className="space-y-4">
                    <div className="flex justify-end">
                        <button onClick={() => setIsCreatingSchedule(true)} className="flex items-center gap-2 px-4 py-2.5 bg-blue-500 text-white rounded-xl text-sm font-bold hover:bg-blue-600 shadow-lg shadow-blue-500/20">
                            <Plus size={16} /> Yeni Zamanlama
                        </button>
                    </div>

                    {isCreatingSchedule && (
                        <div className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm overflow-hidden">
                            <div className="p-6 border-b border-slate-200 dark:border-white/5 flex items-center justify-between">
                                <h3 className="font-bold text-foreground flex items-center gap-2"><Clock size={18} className="text-blue-500" /> Yeni Yedekleme Zamanlaması</h3>
                                <button onClick={() => { setIsCreatingSchedule(false); scheduleForm.reset(); }} className="p-2 hover:bg-slate-100 dark:hover:bg-white/5 rounded-lg"><X size={18} /></button>
                            </div>
                            <form onSubmit={scheduleForm.handleSubmit(data => createScheduleMutation.mutate(data))} className="p-6 space-y-4">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Ad *</label>
                                        <input {...scheduleForm.register('name')} placeholder="Günlük Yedek" className="w-full h-10 bg-slate-100 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-4 text-sm font-bold text-foreground outline-none focus:border-blue-500/50" />
                                        {scheduleForm.formState.errors.name && <p className="text-red-500 text-xs mt-1">{scheduleForm.formState.errors.name.message}</p>}
                                    </div>
                                    <div>
                                        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Sıklık</label>
                                        <select {...scheduleForm.register('frequency')} className="w-full h-10 bg-slate-100 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-4 text-sm font-bold text-foreground outline-none">
                                            <option value="daily">Günlük</option>
                                            <option value="weekly">Haftalık</option>
                                            <option value="monthly">Aylık</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Saklama Süresi (gün)</label>
                                        <input type="number" {...scheduleForm.register('retentionDays', { valueAsNumber: true })} className="w-full h-10 bg-slate-100 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-4 text-sm font-bold text-foreground outline-none" />
                                    </div>
                                    <div className="flex items-center gap-3 pt-6">
                                        <input type="checkbox" {...scheduleForm.register('includeMedia')} className="w-4 h-4 rounded border-slate-300 text-blue-500" />
                                        <label className="text-sm font-bold text-foreground">Medya dosyalarını dahil et</label>
                                    </div>
                                </div>
                                <div className="flex gap-3 justify-end pt-4 border-t border-slate-200 dark:border-white/5">
                                    <button type="button" onClick={() => setIsCreatingSchedule(false)} className="px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold hover:bg-surface/80">İptal</button>
                                    <button type="submit" disabled={createScheduleMutation.isPending} className="flex items-center gap-2 px-4 py-2.5 bg-blue-500 text-white rounded-xl text-sm font-bold hover:bg-blue-600 disabled:opacity-50">
                                        {createScheduleMutation.isPending ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />} Oluştur
                                    </button>
                                </div>
                            </form>
                        </div>
                    )}

                    {/* Schedule List */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {schedulesLoading ? (
                            <div className="col-span-full flex justify-center py-20"><Loader2 className="animate-spin text-blue-500" /></div>
                        ) : (
                            <>
                                {scheduleList.map((schedule: Schedule) => (
                                    <div key={schedule.id} className="bg-white dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm p-6 space-y-3">
                                        <div className="flex items-center justify-between">
                                            <h3 className="font-bold text-foreground">{schedule.name || 'Zamanlama'}</h3>
                                            <span className={`text-xs font-bold px-2 py-1 rounded-full ${schedule.isActive !== false ? 'bg-green-500/10 text-green-500' : 'bg-slate-500/10 text-slate-500'}`}>
                                                {schedule.isActive !== false ? 'Aktif' : 'Pasif'}
                                            </span>
                                        </div>
                                        <div className="space-y-2 text-sm">
                                            <div className="flex justify-between"><span className="text-slate-500">Sıklık</span><span className="font-bold text-foreground">{schedule.frequency}</span></div>
                                            <div className="flex justify-between"><span className="text-slate-500">Saklama</span><span className="font-bold text-foreground">{schedule.retentionDays} gün</span></div>
                                            <div className="flex justify-between"><span className="text-slate-500">Medya</span><span className="font-bold text-foreground">{schedule.includeMedia ? 'Dahil' : 'Hariç'}</span></div>
                                        </div>
                                    </div>
                                ))}
                                {scheduleList.length === 0 && !isCreatingSchedule && (
                                    <div className="col-span-full text-center py-12 text-slate-400">
                                        <Clock className="w-12 h-12 mx-auto mb-3 text-slate-300" />
                                        <p className="font-bold">Henüz zamanlama oluşturulmamış</p>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            )}

            {/* DR TAB */}
            {activeTab === 'dr' && (
                <div className="space-y-6">
                    {drLoading ? (
                        <div className="flex items-center justify-center py-20"><Loader2 className="animate-spin text-blue-500" /></div>
                    ) : (
                        <>
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                                    <div className="flex items-center gap-3 mb-4">
                                        <div className="p-2 rounded-xl bg-green-500/10"><Shield size={20} className="text-green-500" /></div>
                                        <h3 className="font-bold text-foreground">RPO (Kurtarma Noktası)</h3>
                                    </div>
                                    <div className="text-3xl font-black text-foreground">{drSettings?.rpo || '1 saat'}</div>
                                    <p className="text-xs text-slate-500 mt-1">Maksimum tolere edilebilir veri kaybı</p>
                                </div>
                                <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                                    <div className="flex items-center gap-3 mb-4">
                                        <div className="p-2 rounded-xl bg-blue-500/10"><Zap size={20} className="text-blue-500" /></div>
                                        <h3 className="font-bold text-foreground">RTO (Kurtarma Süresi)</h3>
                                    </div>
                                    <div className="text-3xl font-black text-foreground">{drSettings?.rto || '4 saat'}</div>
                                    <p className="text-xs text-slate-500 mt-1">Maksimum tolere edilebilir kesinti</p>
                                </div>
                                <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                                    <div className="flex items-center gap-3 mb-4">
                                        <div className="p-2 rounded-xl bg-purple-500/10"><Server size={20} className="text-purple-500" /></div>
                                        <h3 className="font-bold text-foreground">Replikasyon</h3>
                                    </div>
                                    <div className="text-3xl font-black text-foreground">{drSettings?.replicationStatus || 'Aktif'}</div>
                                    <p className="text-xs text-slate-500 mt-1">Veritabanı replikasyon durumu</p>
                                </div>
                            </div>

                            <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                                <h3 className="font-bold text-foreground mb-4 flex items-center gap-2">
                                    <Activity size={18} className="text-blue-500" /> DR Politikaları
                                </h3>
                                <div className="space-y-3">
                                    {[
                                        { label: 'Otomatik Failover', status: drSettings?.autoFailover !== false, desc: 'Bağlantı koptuğunda otomatik geçiş' },
                                        { label: 'Cross-Region Backup', status: drSettings?.crossRegion !== false, desc: 'Farklı bölgede yedek saklama' },
                                        { label: 'Point-in-Time Recovery', status: drSettings?.pitr !== false, desc: 'Belirli bir zamana geri dönüş' },
                                        { label: 'Şifreli Yedekleme', status: drSettings?.encrypted !== false, desc: 'AES-256 ile yedek şifreleme' },
                                    ].map((policy, idx) => (
                                        <div key={idx} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-white/[0.02] rounded-xl">
                                            <div>
                                                <div className="font-bold text-foreground text-sm">{policy.label}</div>
                                                <div className="text-xs text-slate-500">{policy.desc}</div>
                                            </div>
                                            <div className={`px-3 py-1 rounded-full text-xs font-bold ${policy.status ? 'bg-green-500/10 text-green-500' : 'bg-slate-500/10 text-slate-500'}`}>
                                                {policy.status ? 'Aktif' : 'Pasif'}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </>
                    )}
                </div>
            )}

            {/* Restore Confirm Modal */}
            {restoreConfirm && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setRestoreConfirm(null)}>
                    <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-white/10 max-w-md w-full shadow-2xl p-6 space-y-4" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center gap-3">
                            <div className="p-3 rounded-xl bg-amber-500/10"><AlertTriangle size={24} className="text-amber-500" /></div>
                            <div>
                                <h3 className="text-lg font-black text-foreground">Geri Yükleme Onayı</h3>
                                <p className="text-sm text-slate-500">Bu işlem mevcut verilerin üzerine yazacaktır.</p>
                            </div>
                        </div>
                        <div className="flex gap-3 justify-end">
                            <button onClick={() => setRestoreConfirm(null)} className="px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold hover:bg-surface/80">İptal</button>
                            <button
                                onClick={() => restoreMutation.mutate(restoreConfirm)}
                                disabled={restoreMutation.isPending}
                                className="flex items-center gap-2 px-4 py-2.5 bg-amber-500 text-white rounded-xl text-sm font-bold hover:bg-amber-600 disabled:opacity-50"
                            >
                                {restoreMutation.isPending ? <Loader2 size={16} className="animate-spin" /> : <RotateCcw size={16} />} Geri Yükle
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  BarChart3,
  TrendingUp,
  TrendingDown,
  Users,
  Eye,
  Clock,
  MousePointer,
  Share2,
  ThumbsUp,
  MessageSquare,
  Search,
  Globe,
  Monitor,
  Smartphone,
  Tablet,
  Calendar,
  Download,
  Filter,
  ArrowUpRight,
  ArrowDownRight,
  Target,
  Zap,
} from "lucide-react";

interface AnalyticsData {
  overview: {
    totalViews: number;
    uniqueVisitors: number;
    avgReadTime: number;
    bounceRate: number;
    totalPosts: number;
    newSubscribers: number;
    socialShares: number;
  };
  topPosts: {
    id: string;
    title: string;
    views: number;
    readTime: number;
    likes: number;
    comments: number;
    trend: "up" | "down" | "stable";
    trendValue: number;
  }[];
  trafficSources: {
    source: string;
    views: number;
    percentage: number;
  }[];
  devices: {
    device: string;
    views: number;
    percentage: number;
  }[];
  countries: {
    country: string;
    views: number;
    flag: string;
  }[];
  dailyStats: {
    date: string;
    views: number;
    visitors: number;
  }[];
}

export default function BlogAnalyticsPage() {
  const [data, setData] = useState<AnalyticsData>({
    overview: {
      totalViews: 12500,
      uniqueVisitors: 8400,
      avgReadTime: 185,
      bounceRate: 42,
      totalPosts: 48,
      newSubscribers: 156,
      socialShares: 89,
    },
    topPosts: [],
    trafficSources: [
      { source: "Google", views: 8400, percentage: 67 },
      { source: "Direkt", views: 2500, percentage: 20 },
      { source: "Sosyal", views: 1500, percentage: 12 },
      { source: "Diğer", views: 100, percentage: 1 },
    ],
    devices: [
      { device: "Desktop", views: 7500, percentage: 60 },
      { device: "Mobile", views: 4500, percentage: 36 },
      { device: "Tablet", views: 500, percentage: 4 },
    ],
    countries: [
      { country: "Türkiye", views: 10000, flag: "🇹🇷" },
      { country: "Almanya", views: 1500, flag: "🇩🇪" },
      { country: "ABD", views: 800, flag: "🇺🇸" },
