      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">
          Link Metni *
        </label>
        <input
          type="text"
          value={formData.label}
          onChange={(e) => setFormData({ ...formData, label: e.target.value })}
          className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500"
          required
          placeholder="Ana Sayfa, Hakkımızda, İletişim..."
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">
          URL *
        </label>
        <input
          type="text"
          value={formData.url}
          onChange={(e) => setFormData({ ...formData, url: e.target.value })}
          className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500"
          required
          placeholder="/sayfa-url veya https://..."
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-slate-700 mb-1">
          İkon (Lucide)
        </label>
        <input
          type="text"
          value={formData.icon}
          onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
          className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500"
          placeholder="home, mail, phone..."
        />
      </div>

      <div className="flex items-center gap-4">
        <label className="flex items-center gap-2">
          <input
            type="checkbox"
            checked={formData.isExternal}
            onChange={(e) => setFormData({ ...formData, isExternal: e.target.checked })}
            className="rounded border-slate-300"
          />
          <span className="text-sm">Dış Link</span>
        </label>
        <label className="flex items-center gap-2">
          <input
            type="checkbox"
            checked={formData.isActive}
            onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
            className="rounded border-slate-300"
          />
          <span className="text-sm">Aktif</span>
        </label>
      </div>

      <div className="flex gap-3 pt-4">
        <button
          type="submit"
          disabled={isSaving}
          className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50"
        >
          {isSaving ? (
            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
          ) : (
            <Save className="w-4 h-4" />
          )}
          Kaydet
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="px-4 py-2 border border-slate-200 rounded-lg hover:bg-slate-50"
        >
          İptal
        </button>
      </div>
    </form>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { motion } from "framer-motion";
import { ArrowLeft, Save } from "lucide-react";

interface Footer {
  id: string;
  name: string;
  location: string;
  isActive: boolean;
  isDefault: boolean;
  bgColor?: string;
  textColor?: string;
  borderColor?: string;
  logoUrl?: string;
  logoText?: string;
  tagline?: string;
}

export default function EditFooterPage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter();
  const [footer, setFooter] = useState<Footer | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [footerId, setFooterId] = useState<string>("");

  const [formData, setFormData] = useState({
    name: "",
    location: "main",
    isActive: true,
    isDefault: false,
    bgColor: "",
    textColor: "",
    borderColor: "",
    logoUrl: "",
    logoText: "",
    tagline: "",
  });

  useEffect(() => {
    params.then(p => {
      setFooterId(p.id);
    });
  }, [params]);

  useEffect(() => {
    if (footerId) {
      fetchFooter();
    }
  }, [footerId]);

  const fetchFooter = async () => {
    try {
      const response = await fetch(`/api/admin/footers/${footerId}`);
      if (response.ok) {
        const data = await response.json();
        setFooter(data);
        setFormData({
          name: data.name,
          location: data.location,
          isActive: data.isActive,
          isDefault: data.isDefault,
          bgColor: data.bgColor || "",
          textColor: data.textColor || "",
          borderColor: data.borderColor || "",
          logoUrl: data.logoUrl || "",
          logoText: data.logoText || "",
          tagline: data.tagline || "",
        });
      } else {
        setError("Footer yüklenirken bir hata oluştu.");
      }
    } catch (err) {
      setError("Footer yüklenirken bir hata oluştu.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setError(null);

    try {
      const response = await fetch(`/api/admin/footers/${footerId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        router.push("/admin/footers");
      } else {
        const data = await response.json();
        setError(data.error || "Footer güncellenirken bir hata oluştu.");
      }
    } catch (err) {
      setError("Footer güncellenirken bir hata oluştu.");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
