  Package,
  Users,
  TrendingUp,
  Building2,
  Lock,
  Unlock,
  ToggleLeft,
  ToggleRight,
  Zap,
  AlertTriangle,
  Info,
  RefreshCw,
  Download,
  Upload,
  Star,
  Crown,
  Sparkles,
} from 'lucide-react';

// Types
interface MarketplaceConfig {
  id: string;
  name: string;
  region: string;
  country: string;
  countryCode: string;
  minimumPlan: string;
  isActive: boolean;
  isEnabled: boolean;
  totalConnections: number;
  activeConnections: number;
  brandColor: string;
  planOverrides: Record<string, boolean>;
}

// Plan hierarchy
const PLANS = [
  { id: 'FREE', name: 'Ücretsiz', icon: Star, color: 'slate' },
  { id: 'STARTER', name: 'Başlangıç', icon: Zap, color: 'blue' },
  { id: 'PROFESSIONAL', name: 'Profesyonel', icon: Sparkles, color: 'purple' },
  { id: 'ENTERPRISE', name: 'Kurumsal', icon: Crown, color: 'amber' },
];

const REGIONS = [
  { id: 'ALL', name: 'Tüm Bölgeler' },
  { id: 'TURKEY', name: 'Türkiye' },
  { id: 'NORTH_AMERICA', name: 'Kuzey Amerika' },
  { id: 'EUROPE', name: 'Avrupa' },
  { id: 'ASIA_PACIFIC', name: 'Asya Pasifik' },
  { id: 'LATIN_AMERICA', name: 'Latin Amerika' },
  { id: 'GLOBAL', name: 'Global' },
];

export default function AdminIntegrationsPage() {
  const [marketplaces, setMarketplaces] = useState<MarketplaceConfig[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedRegion, setSelectedRegion] = useState('ALL');
  const [selectedPlan, setSelectedPlan] = useState('ALL');
  const [editingMarketplace, setEditingMarketplace] = useState<MarketplaceConfig | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [expandedRows, setExpandedRows] = useState<string[]>([]);

  useEffect(() => {
    const fetchMarketplaces = async () => {
      try {
        const res = await fetch('/api/integrations', { cache: 'no-store' });
        if (!res.ok) throw new Error('Entegrasyonlar alınamadı');
        const data = await res.json();
        const normalized = (Array.isArray(data) ? data : []).map((item: any) => ({
          id: String(item.platform || item.id || ''),
          name: String(item.platform || item.id || 'Bilinmeyen Platform'),
          region: String(item.apiExtra?.region || 'GLOBAL'),
          country: String(item.apiExtra?.country || 'Global'),
          countryCode: String(item.apiExtra?.countryCode || 'GL'),
          minimumPlan: String(item.apiExtra?.minimumPlan || 'FREE'),
          isActive: Boolean(item.isActive),
          isEnabled: Boolean(item.isActive),
          totalConnections: Number(item.apiExtra?.totalConnections || 0),
          activeConnections: Number(item.apiExtra?.activeConnections || 0),
          brandColor: String(item.apiExtra?.brandColor || '#64748b'),
          planOverrides: typeof item.apiExtra?.planOverrides === 'object' && item.apiExtra?.planOverrides !== null
            ? item.apiExtra.planOverrides
            : {},
        })) as MarketplaceConfig[];
        setMarketplaces(normalized);
      } catch (error) {
        console.error('Entegrasyonlar yüklenemedi:', error);
        setMarketplaces([]);
      }
    };

    fetchMarketplaces();
  }, []);

  // Filter with useMemo to avoid setState in effect
  const filteredMarketplaces = React.useMemo(() => {
    let filtered = [...marketplaces];

    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(m =>
        m.name.toLowerCase().includes(query) ||
        m.country.toLowerCase().includes(query)
      );
    }

    if (selectedRegion !== 'ALL') {
      filtered = filtered.filter(m => m.region === selectedRegion);
    }

    if (selectedPlan !== 'ALL') {
      filtered = filtered.filter(m => m.minimumPlan === selectedPlan);
    }

    return filtered;
  }, [marketplaces, searchQuery, selectedRegion, selectedPlan]);

  const toggleEnabled = (id: string) => {
    setMarketplaces(prev =>
      prev.map(m => m.id === id ? { ...m, isEnabled: !m.isEnabled } : m)
    );
  };

  const updateMinimumPlan = (id: string, plan: string) => {
    setMarketplaces(prev =>
      prev.map(m => m.id === id ? { ...m, minimumPlan: plan } : m)
    );
  };

  const togglePlanOverride = (marketplaceId: string, planId: string) => {
    setMarketplaces(prev =>
      prev.map(m => {
        if (m.id === marketplaceId) {
          const newOverrides = { ...m.planOverrides };
          if (newOverrides[planId] === undefined) {
            newOverrides[planId] = false; // Explicitly deny
          } else if (newOverrides[planId] === false) {
            newOverrides[planId] = true; // Explicitly allow
          } else {
            delete newOverrides[planId]; // Use default
          }
          return { ...m, planOverrides: newOverrides };
        }
        return m;
      })
    );
  };

  const toggleExpand = (id: string) => {
    setExpandedRows(prev =>
      prev.includes(id) ? prev.filter(r => r !== id) : [...prev, id]
    );
  };

  const handleSaveAll = async () => {
    setIsSaving(true);
    try {
      const res = await fetch('/api/integrations', { cache: 'no-store' });
      if (!res.ok) throw new Error('Kaydetme doğrulaması başarısız');
    } catch (error) {
      console.error('Entegrasyon ayarları kaydedilemedi:', error);
    }
    setIsSaving(false);
  };

  // Stats
  const totalMarketplaces = marketplaces.length;
  const enabledMarketplaces = marketplaces.filter(m => m.isEnabled).length;
  const totalConnections = marketplaces.reduce((sum, m) => sum + m.totalConnections, 0);
  const activeConnections = marketplaces.reduce((sum, m) => sum + m.activeConnections, 0);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Page Header */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 rounded-xl bg-primary/10">
              <Shield className="text-primary" size={24} />
            </div>
            <h1 className="text-3xl font-black text-foreground tracking-tight">Entegrasyon Yönetimi</h1>
          </div>
          <p className="text-slate-500 font-medium">Pazaryeri erişimlerini ve plan bazlı kısıtlamaları yönetin</p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={handleSaveAll}
            disabled={isSaving}
            className="flex items-center gap-2 px-5 py-2.5 bg-primary text-white rounded-xl text-sm font-bold shadow-lg shadow-primary/25 hover:bg-primary/90 transition-all disabled:opacity-50"
          >
            {isSaving ? (
              <RefreshCw size={16} className="animate-spin" />
            ) : (
              <Save size={16} />
            )}
            Değişiklikleri Kaydet
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="p-5 bg-surface rounded-2xl border border-border"
        >
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-blue-500/10 text-blue-500">
              <Globe size={20} />
            </div>
            <div>
              <div className="text-2xl font-black text-foreground">{totalMarketplaces}</div>
              <div className="text-xs text-slate-500">Toplam Platform</div>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="p-5 bg-surface rounded-2xl border border-border"
        >
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-green-500/10 text-green-500">
              <Check size={20} />
            </div>
            <div>
              <div className="text-2xl font-black text-foreground">{enabledMarketplaces}</div>
              <div className="text-xs text-slate-500">Aktif Platform</div>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="p-5 bg-surface rounded-2xl border border-border"
        >
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-purple-500/10 text-purple-500">
              <Users size={20} />
            </div>
            <div>
              <div className="text-2xl font-black text-foreground">{totalConnections.toLocaleString()}</div>
              <div className="text-xs text-slate-500">Toplam Bağlantı</div>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="p-5 bg-surface rounded-2xl border border-border"
        >
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-orange-500/10 text-orange-500">
              <TrendingUp size={20} />
            </div>
            <div>
              <div className="text-2xl font-black text-foreground">{activeConnections.toLocaleString()}</div>
              <div className="text-xs text-slate-500">Aktif Bağlantı</div>
            </div>
          </div>
        </motion.div>
      </div>

      {/* Filters */}
      <div className="flex flex-col lg:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            placeholder="Platform ara..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-surface border border-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary/20"
          />
        </div>

        <select
          value={selectedRegion}
          onChange={e => setSelectedRegion(e.target.value)}
          className="px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-primary/20"
        >
          {REGIONS.map(region => (
            <option key={region.id} value={region.id}>{region.name}</option>
          ))}
        </select>

        <select
          value={selectedPlan}
          onChange={e => setSelectedPlan(e.target.value)}
          className="px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-primary/20"
        >
          <option value="ALL">Tüm Planlar</option>
          {PLANS.map(plan => (
            <option key={plan.id} value={plan.id}>{plan.name}</option>
          ))}
        </select>
      </div>

      {/* Info Banner */}
      <div className="p-4 bg-blue-500/10 border border-blue-500/20 rounded-xl">
        <div className="flex items-start gap-3">
          <Info className="text-blue-500 mt-0.5" size={18} />
          <div>
            <p className="text-sm font-medium text-foreground">Plan Bazlı Erişim Yönetimi</p>
            <p className="text-xs text-slate-500 mt-1">
              Her platform için minimum plan seviyesi belirleyebilirsiniz. Ayrıca belirli planlar için özel izinler veya kısıtlamalar ekleyebilirsiniz.
            </p>
          </div>
        </div>
      </div>

      {/* Marketplaces Table */}
      <div className="bg-surface rounded-[24px] border border-border overflow-hidden">
        {filteredMarketplaces.length === 0 ? (
          <div className="p-8 text-center text-sm text-slate-500">
            Entegrasyon verisi bulunamadı. API yanıt verdiğinde liste burada görüntülenecek.
          </div>
        ) : (
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-background/50 border-b border-border">
              <tr>
                <th className="text-left p-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Platform</th>
                <th className="text-left p-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Bölge</th>
                <th className="text-center p-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Minimum Plan</th>
                <th className="text-center p-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Bağlantılar</th>
                <th className="text-center p-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Durum</th>
                <th className="text-center p-4 text-xs font-bold text-slate-500 uppercase tracking-widest">İşlemler</th>
              </tr>
            </thead>
            <tbody>
              {filteredMarketplaces.map((marketplace, idx) => (
                <React.Fragment key={marketplace.id}>
                  <motion.tr
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: idx * 0.03 }}
                    className={`border-b border-border hover:bg-background/50 transition-colors ${!marketplace.isEnabled ? 'opacity-60' : ''
                      }`}
                  >
                    <td className="p-4">
                      <div className="flex items-center gap-3">
                        <div
                          className="w-10 h-10 rounded-xl flex items-center justify-center text-white font-bold text-sm"
                          style={{ backgroundColor: marketplace.brandColor }}
                        >
                          {marketplace.name.charAt(0)}
                        </div>
                        <div>
                          <div className="font-bold text-foreground">{marketplace.name}</div>
                          <div className="text-xs text-slate-500">{marketplace.country}</div>
                        </div>
                      </div>
                    </td>
                    <td className="p-4">
                      <span className="px-2.5 py-1 text-xs font-medium bg-slate-500/10 text-slate-500 rounded-lg">
                        {REGIONS.find(r => r.id === marketplace.region)?.name || marketplace.region}
                      </span>
                    </td>
                    <td className="p-4">
                      <div className="flex justify-center">
                        <select
                          value={marketplace.minimumPlan}
                          onChange={e => updateMinimumPlan(marketplace.id, e.target.value)}
                          className={`px-3 py-1.5 text-xs font-bold rounded-lg border focus:outline-none focus:ring-2 focus:ring-primary/20 ${marketplace.minimumPlan === 'FREE' ? 'bg-slate-500/10 text-slate-500 border-slate-500/20' :
                              marketplace.minimumPlan === 'STARTER' ? 'bg-blue-500/10 text-blue-500 border-blue-500/20' :
                                marketplace.minimumPlan === 'PROFESSIONAL' ? 'bg-purple-500/10 text-purple-500 border-purple-500/20' :
                                  'bg-amber-500/10 text-amber-500 border-amber-500/20'
                            }`}
                        >
                          {PLANS.map(plan => (
                            <option key={plan.id} value={plan.id}>{plan.name}</option>
                          ))}
                        </select>
                      </div>
                    </td>
                    <td className="p-4 text-center">
                      <div className="text-sm font-bold text-foreground">{marketplace.activeConnections.toLocaleString()}</div>
                      <div className="text-[10px] text-slate-500">/ {marketplace.totalConnections.toLocaleString()} toplam</div>
                    </td>
                    <td className="p-4">
                      <div className="flex justify-center">
                        <button
                          onClick={() => toggleEnabled(marketplace.id)}
                          className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${marketplace.isEnabled
                              ? 'bg-green-500/10 text-green-500'
                              : 'bg-red-500/10 text-red-500'
                            }`}
                        >
                          {marketplace.isEnabled ? (
                            <>
                              <ToggleRight size={16} />
                              Aktif
                            </>
                          ) : (
                            <>
                              <ToggleLeft size={16} />
                              Pasif
                            </>
                          )}
                        </button>
                      </div>
                    </td>
                    <td className="p-4">
                      <div className="flex justify-center gap-2">
                        <button
                          onClick={() => toggleExpand(marketplace.id)}
                          className="p-2 text-slate-400 hover:text-primary hover:bg-primary/10 rounded-lg transition-all"
                          title="Plan detayları"
                        >
                          <ChevronDown
                            size={18}
                            className={`transition-transform ${expandedRows.includes(marketplace.id) ? 'rotate-180' : ''}`}
                          />
                        </button>
                      </div>
                    </td>
                  </motion.tr>

                  {/* Expanded Row */}
                  <AnimatePresence>
                    {expandedRows.includes(marketplace.id) && (
                      <motion.tr
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="bg-background/30"
                      >
                        <td colSpan={6} className="p-4">
                          <div className="p-4 bg-surface rounded-xl border border-border">
                            <h4 className="text-sm font-bold text-foreground mb-4">Plan Bazlı Erişim Ayarları</h4>
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                              {PLANS.map(plan => {
                                const planIndex = PLANS.findIndex(p => p.id === plan.id);
                                const minPlanIndex = PLANS.findIndex(p => p.id === marketplace.minimumPlan);
                                const hasAccess = planIndex >= minPlanIndex;
                                const override = marketplace.planOverrides[plan.id];

                                const isAllowed = override === true ? true : override === false ? false : hasAccess;

                                return (
                                  <div
                                    key={plan.id}
                                    className={`p-4 rounded-xl border transition-all ${isAllowed
                                        ? 'bg-green-500/5 border-green-500/20'
                                        : 'bg-red-500/5 border-red-500/20'
                                      }`}
                                  >
                                    <div className="flex items-center justify-between mb-3">
                                      <div className="flex items-center gap-2">
                                        <plan.icon size={16} className={`text-${plan.color}-500`} />
                                        <span className="text-sm font-bold text-foreground">{plan.name}</span>
                                      </div>
                                      <button
                                        onClick={() => togglePlanOverride(marketplace.id, plan.id)}
                                        className={`p-1.5 rounded-lg transition-all ${isAllowed
                                            ? 'bg-green-500/20 text-green-500'
                                            : 'bg-red-500/20 text-red-500'
                                          }`}
                                      >
                                        {isAllowed ? <Unlock size={14} /> : <Lock size={14} />}
                                      </button>
                                    </div>
                                    <div className="text-[10px] text-slate-500">
                                      {override === true && (
                                        <span className="text-green-500">✓ Manuel olarak açıldı</span>
                                      )}
                                      {override === false && (
                                        <span className="text-red-500">✕ Manuel olarak kapatıldı</span>
                                      )}
                                      {override === undefined && hasAccess && (
                                        <span className="text-green-500">✓ Varsayılan: Erişebilir</span>
                                      )}
                                      {override === undefined && !hasAccess && (
                                        <span className="text-red-500">✕ Varsayılan: Erişemez</span>
                                      )}
                                    </div>
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        </td>
                      </motion.tr>
                    )}
                  </AnimatePresence>
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
        )}
      </div>

      {/* Bulk Actions */}
      <div className="p-6 bg-surface rounded-[24px] border border-border">
        <h3 className="text-lg font-bold text-foreground mb-4">Toplu İşlemler</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <button className="flex items-center gap-3 p-4 bg-background rounded-xl border border-border hover:border-blue-500/30 transition-all text-left group">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <Download className="text-blue-500" size={18} />
            </div>
            <div>
              <div className="text-sm font-bold text-foreground">Ayarları Dışa Aktar</div>
              <div className="text-xs text-slate-500">JSON olarak indir</div>
            </div>
          </button>

          <button className="flex items-center gap-3 p-4 bg-background rounded-xl border border-border hover:border-green-500/30 transition-all text-left group">
            <div className="p-2 rounded-lg bg-green-500/10">
              <Upload className="text-green-500" size={18} />
            </div>
            <div>
              <div className="text-sm font-bold text-foreground">Ayarları İçe Aktar</div>
              <div className="text-xs text-slate-500">JSON dosyası yükle</div>
            </div>
          </button>

          <button className="flex items-center gap-3 p-4 bg-background rounded-xl border border-border hover:border-orange-500/30 transition-all text-left group">
            <div className="p-2 rounded-lg bg-orange-500/10">
              <RefreshCw className="text-orange-500" size={18} />
            </div>
            <div>
              <div className="text-sm font-bold text-foreground">Varsayılana Sıfırla</div>
              <div className="text-xs text-slate-500">Tüm özel ayarları kaldır</div>
            </div>
          </button>

          <button className="flex items-center gap-3 p-4 bg-background rounded-xl border border-border hover:border-red-500/30 transition-all text-left group">
            <div className="p-2 rounded-lg bg-red-500/10">
              <AlertTriangle className="text-red-500" size={18} />
            </div>
            <div>
              <div className="text-sm font-bold text-foreground">Tümünü Devre Dışı</div>
              <div className="text-xs text-slate-500">Bakım modu</div>
            </div>
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { adminApi } from '@/lib/admin-api';
import {
    ShieldAlert, AlertTriangle, CheckCircle, Search, Calendar,
    User, Terminal, Loader2, ChevronLeft, ChevronRight,
    Download, Filter, Eye, Clock, LucideIcon
} from 'lucide-react';

interface AuditLog {
    id: string;
    action: string;
    resource?: string;
    resourceType?: string;
    userId?: string;
    user?: {
        name?: string;
        email?: string;
    };
    details?: string;
    description?: string;
    ip?: string;
    userAgent?: string;
    createdAt?: string;
    time?: string;
    metadata?: Record<string, unknown>;
}

const SEVERITY_CONFIG: Record<string, { icon: LucideIcon; bgClass: string; textClass: string; label: string }> = {
    high: { icon: ShieldAlert, bgClass: 'bg-red-500/10', textClass: 'text-red-500', label: 'Kritik' },
    critical: { icon: ShieldAlert, bgClass: 'bg-red-500/10', textClass: 'text-red-500', label: 'Kritik' },
    medium: { icon: AlertTriangle, bgClass: 'bg-amber-500/10', textClass: 'text-amber-500', label: 'Uyarı' },
    warning: { icon: AlertTriangle, bgClass: 'bg-amber-500/10', textClass: 'text-amber-500', label: 'Uyarı' },
    low: { icon: Terminal, bgClass: 'bg-blue-500/10', textClass: 'text-blue-500', label: 'Bilgi' },
    info: { icon: Terminal, bgClass: 'bg-blue-500/10', textClass: 'text-blue-500', label: 'Bilgi' },
    success: { icon: CheckCircle, bgClass: 'bg-green-500/10', textClass: 'text-green-500', label: 'Başarılı' },
};

export default function LogsPage() {
    const [search, setSearch] = useState('');
    const [actionFilter, setActionFilter] = useState('');
    const [page, setPage] = useState(1);
    const [selectedLog, setSelectedLog] = useState<AuditLog | null>(null);

    const { data, isLoading, error } = useQuery({
        queryKey: ['admin-audit-logs', { action: actionFilter, page, search }],
        queryFn: () => adminApi.getAuditLogs({
            action: actionFilter || undefined,
            page,
            limit: 20,
        }),
    });

    const logs = data?.logs || data || [];
    const totalPages = data?.totalPages || 1;
    const total = data?.total || (Array.isArray(logs) ? logs.length : 0);

    const formatDate = (date: string) =>
        new Date(date).toLocaleDateString('tr-TR', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

    const getSeverity = (log: AuditLog) => {
        const action = (log.action || '').toLowerCase();
        if (action.includes('delete') || action.includes('fail') || action.includes('error')) return 'high';
        if (action.includes('update') || action.includes('change')) return 'medium';
        if (action.includes('create') || action.includes('login') || action.includes('success')) return 'success';
        return 'low';
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight mb-1">Denetim Kayıtları</h1>
                    <p className="text-slate-500 dark:text-slate-400 font-medium">Sistem güvenliği ve hata izleme merkezi</p>
                </div>
                <div className="flex gap-2">
                    <button className="h-10 px-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-xl flex items-center gap-2 text-slate-600 dark:text-slate-400 font-bold text-sm hover:bg-slate-50 dark:hover:bg-white/5 transition-colors">
                        <Download size={16} /> Dışa Aktar (.csv)
                    </button>
                </div>
            </div>

            {/* Stats Summary */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Kayıt', value: total, icon: Terminal, color: 'blue' },
                    { label: 'Kritik', value: (Array.isArray(logs) ? logs : []).filter((l: AuditLog) => getSeverity(l) === 'high').length, icon: ShieldAlert, color: 'red' },
                    { label: 'Uyarı', value: (Array.isArray(logs) ? logs : []).filter((l: AuditLog) => getSeverity(l) === 'medium').length, icon: AlertTriangle, color: 'amber' },
                    { label: 'Başarılı', value: (Array.isArray(logs) ? logs : []).filter((l: AuditLog) => getSeverity(l) === 'success').length, icon: CheckCircle, color: 'green' },
                ].map((stat, idx) => (
                    <div key={idx} className="bg-white dark:bg-slate-900/50 p-4 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex items-center gap-3">
                        <div className={`p-2 rounded-xl bg-${stat.color}-500/10`}>
                            <stat.icon size={18} className={`text-${stat.color}-500`} />
                        </div>
                        <div>
                            <div className="text-xl font-black text-foreground">{stat.value}</div>
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{stat.label}</div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-slate-900/50 p-4 rounded-2xl border border-slate-200 dark:border-white/5 flex flex-col sm:flex-row gap-4 shadow-sm">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input
                        type="text"
                        placeholder="IP, Kullanıcı veya İşlem ara..."
                        value={search}
                        onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                        className="w-full h-10 bg-slate-100 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl pl-10 pr-4 text-sm font-bold text-foreground placeholder:text-slate-500 outline-none focus:border-blue-500/50"
                    />
                </div>
                <select
                    value={actionFilter}
                    onChange={(e) => { setActionFilter(e.target.value); setPage(1); }}
                    className="h-10 bg-slate-100 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-4 text-sm font-bold text-slate-600 dark:text-slate-400 outline-none focus:border-blue-500/50"
                >
                    <option value="">Tüm İşlemler</option>
                    <option value="CREATE">Oluşturma</option>
                    <option value="UPDATE">Güncelleme</option>
                    <option value="DELETE">Silme</option>
                    <option value="LOGIN">Giriş</option>
                </select>
            </div>

            {/* Table */}
            {isLoading ? (
                <div className="flex items-center justify-center py-20">
                    <Loader2 className="w-8 h-8 animate-spin text-blue-500" />
                </div>
            ) : error ? (
                <div className="text-center py-20">
                    <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
                    <p className="text-red-500 font-bold">Kayıtlar yüklenirken hata oluştu</p>
                </div>
            ) : (
                <div className="bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-white/5 rounded-2xl overflow-hidden shadow-sm">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="border-b border-slate-200 dark:border-white/5 bg-slate-50 dark:bg-white/[0.02]">
                                <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest w-24">Durum</th>
                                <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">İşlem</th>
                                <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Kaynak</th>
                                <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Kullanıcı</th>
                                <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest">Detay</th>
                                <th className="p-4 text-xs font-black text-slate-500 uppercase tracking-widest text-right">Zaman</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-200 dark:divide-white/5">
                            {(Array.isArray(logs) ? logs : []).map((log: AuditLog, i: number) => {
                                const severity = getSeverity(log);
                                const config = SEVERITY_CONFIG[severity] || SEVERITY_CONFIG.low;
                                const SeverityIcon = config.icon;
                                return (
                                    <tr key={log.id || i} className="group hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors text-sm">
                                        <td className="p-4">
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${config.bgClass} ${config.textClass}`}>
                                                <SeverityIcon size={16} />
                                            </div>
                                        </td>
                                        <td className="p-4 font-bold text-foreground tracking-tight">{log.action || '—'}</td>
                                        <td className="p-4 text-slate-500">{log.resource || log.resourceType || '—'}</td>
                                        <td className="p-4 text-slate-500 flex items-center gap-2">
                                            <User size={12} /> {log.user?.name || log.user?.email || log.userId || '—'}
                                        </td>
                                        <td className="p-4 text-slate-500 max-w-[200px] truncate">{log.details || log.description || '—'}</td>
                                        <td className="p-4 text-right text-slate-500 font-bold whitespace-nowrap">
                                            {log.createdAt ? formatDate(log.createdAt) : log.time || '—'}
                                        </td>
                                    </tr>
                                );
                            })}
                            {(!Array.isArray(logs) || logs.length === 0) && (
                                <tr><td colSpan={6} className="p-12 text-center text-slate-400 text-sm">Kayıt bulunamadı</td></tr>
                            )}
                        </tbody>
                    </table>

                    {/* Pagination */}
                    {totalPages > 1 && (
                        <div className="flex items-center justify-between p-4 border-t border-slate-200 dark:border-white/5">
                            <span className="text-xs text-slate-500 font-bold">Sayfa {page} / {totalPages}</span>
                            <div className="flex gap-2">
                                <button disabled={page <= 1} onClick={() => setPage(p => p - 1)} className="p-2 bg-slate-100 dark:bg-white/5 rounded-lg hover:bg-slate-200 disabled:opacity-30">
                                    <ChevronLeft size={16} />
                                </button>
                                <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)} className="p-2 bg-slate-100 dark:bg-white/5 rounded-lg hover:bg-slate-200 disabled:opacity-30">
                                    <ChevronRight size={16} />
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* Log Detail Modal */}
            {selectedLog && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setSelectedLog(null)}>
                    <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-white/10 max-w-lg w-full shadow-2xl p-6 space-y-4" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-between">
                            <h3 className="text-xl font-black text-foreground">Log Detayı</h3>
                            <button onClick={() => setSelectedLog(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-white/5 rounded-lg">✕</button>
                        </div>
                        <pre className="bg-slate-100 dark:bg-black/20 p-4 rounded-xl text-xs overflow-auto max-h-64 font-mono text-foreground">
                            {JSON.stringify(selectedLog, null, 2)}
                        </pre>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { motion, AnimatePresence, Reorder } from "framer-motion";
import {
  Plus,
  Search,
  Menu as MenuIcon,
  Edit2,
  Trash2,
  Eye,
  MoreVertical,
  ArrowLeft,
  LayoutGrid,
  GripVertical,
  ChevronRight,
  ChevronDown,
  CheckCircle,
  X,
  ExternalLink,
  Image,
  Type,
  Columns,
  Move,
  Copy,
  AlertCircle,
  RefreshCw,
} from "lucide-react";

interface MenuItem {
  id: string;
  label: string;
  url?: string;
  type: "LINK" | "DROPDOWN" | "MEGA_MENU" | "DIVIDER" | "LABEL";
