"use client";

import React, { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { adminApi } from '@/lib/admin-api';
import {
    Search, Package, Save, Plus, Trash2,
    AlertCircle, CheckCircle2, Loader2, ChevronRight, Layers
} from 'lucide-react';

interface Product {
    id: string;
    title: string;
    sku: string;
    price: number;
    stock: number;
}

interface Variant {
    id?: string;
    sku: string;
    price: number;
    costPrice: number;
    stock: number;
    options: any; // { "Renk": "Kırmızı", "Beden": "XL" }
}

export default function VariantManagerPage() {
    const queryClient = useQueryClient();
    const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
    const [search, setSearch] = useState('');
    const [localVariants, setLocalVariants] = useState<Variant[]>([]);

    // Fetch products for selection
    const { data: productData, isLoading: productsLoading } = useQuery({
        queryKey: ['admin-products-minimal', search],
        queryFn: () => adminApi.getProducts({ search, limit: 10 }),
        enabled: true,
    });

    // Fetch variants when product selected
    const { data: remoteVariants, isLoading: variantsLoading } = useQuery({
        queryKey: ['admin-product-variants', selectedProduct?.id],
        queryFn: () => adminApi.getProductVariants(selectedProduct!.id),
        enabled: !!selectedProduct,
    });

    useEffect(() => {
        if (remoteVariants) {
            setLocalVariants(remoteVariants);
        }
    }, [remoteVariants]);

    const saveMutation = useMutation({
        mutationFn: () => adminApi.bulkUpdateVariants(selectedProduct!.id, localVariants),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['admin-product-variants', selectedProduct?.id] });
            alert('Varyantlar başarıyla kaydedildi.');
        }
    });

    const handleVariantChange = (index: number, field: keyof Variant, value: any) => {
        const next = [...localVariants];
        next[index] = { ...next[index], [field]: value };
        setLocalVariants(next);
    };

    const addVariant = () => {
        setLocalVariants([...localVariants, {
            id: `new_${Date.now()}`,
            sku: `${selectedProduct?.sku}-VAR-${localVariants.length + 1}`,
            price: selectedProduct?.price || 0,
            costPrice: 0,
            stock: 0,
            options: {}
        }]);
    };

    const removeVariant = (index: number) => {
        if (confirm('Bu varyantı silmek istediğinize emin misiniz?')) {
            const next = localVariants.filter((_, i) => i !== index);
            setLocalVariants(next);
            // Note: Backend currently doesn't handle deletion in the bulk endpoint 
            // but we could extend it if needed.
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Varyant Yöneticisi</h1>
                    <p className="text-slate-500 dark:text-slate-400 font-medium">Ürün varyantlarını (beden, renk vb.) hızlı ve toplu bir şekilde düzenleyin.</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {/* Product Selection sidebar */}
                <div className="lg:col-span-1 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-2xl p-4 shadow-sm">
                        <h3 className="font-bold text-slate-900 dark:text-white mb-3 text-sm flex items-center gap-2">
                            <Package size={16} className="text-purple-500" /> Ürün Seçin
                        </h3>
                        <div className="relative mb-4">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                            <input
                                type="text"
                                placeholder="Ürün ara..."
                                className="w-full pl-9 pr-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl text-xs font-bold outline-none focus:border-purple-500/50"
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                            />
                        </div>

                        <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                            {productData?.products?.map((p: Product) => (
                                <button
                                    key={p.id}
                                    onClick={() => setSelectedProduct(p)}
                                    className={`w-full text-left p-3 rounded-xl border transition-all ${selectedProduct?.id === p.id
                                            ? 'bg-purple-50 border-purple-200 dark:bg-purple-500/10 dark:border-purple-500/30'
                                            : 'bg-white dark:bg-transparent border-transparent hover:bg-slate-50 dark:hover:bg-white/5'
                                        }`}
                                >
                                    <div className="font-bold text-xs text-slate-900 dark:text-white truncate">{p.title}</div>
                                    <div className="text-[10px] text-slate-500 mt-1 font-medium">{p.sku}</div>
                                </button>
                            ))}
                            {productsLoading && <div className="text-center py-4 text-xs text-slate-400">Yükleniyor...</div>}
                        </div>
                    </div>
                </div>

                {/* Variant Editor Area */}
                <div className="lg:col-span-3">
                    {selectedProduct ? (
                        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-2xl shadow-sm overflow-hidden flex flex-col min-h-[500px]">
                            <div className="p-4 border-b border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/[0.02] flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-purple-500/10 rounded-lg">
                                        <Layers size={18} className="text-purple-500" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-slate-900 dark:text-white">{selectedProduct.title}</h3>
                                        <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{selectedProduct.sku}</p>
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    <button
                                        onClick={addVariant}
                                        className="px-3 py-1.5 bg-slate-100 dark:bg-white/5 hover:bg-white dark:hover:bg-white/10 text-slate-700 dark:text-slate-300 rounded-lg text-xs font-bold flex items-center gap-2 transition-all border border-slate-200 dark:border-white/10"
                                    >
                                        <Plus size={14} /> Yeni Varyant
                                    </button>
                                    <button
                                        onClick={() => saveMutation.mutate()}
                                        disabled={saveMutation.isPending}
                                        className="px-4 py-1.5 bg-purple-500 hover:bg-purple-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 transition-all shadow-sm shadow-purple-500/20 disabled:opacity-50"
                                    >
                                        {saveMutation.isPending ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                                        Kaydet
                                    </button>
                                </div>
                            </div>

                            <div className="flex-1 overflow-x-auto">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-slate-50 dark:bg-white/[0.01] border-b border-slate-100 dark:border-white/5">
                                            <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">SKU</th>
                                            <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Özellikler (JSON)</th>
                                            <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Fiyat (₺)</th>
                                            <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Maliyet (₺)</th>
                                            <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Stok</th>
                                            <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">İşlem</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                                        {localVariants.map((v, idx) => (
                                            <tr key={idx} className="group hover:bg-slate-50/50 dark:hover:bg-white/[0.01] transition-colors">
                                                <td className="p-2">
                                                    <input
                                                        type="text"
                                                        className="bg-transparent w-full p-2 border border-transparent group-hover:border-slate-200 dark:group-hover:border-white/10 rounded-lg text-xs font-bold transition-all focus:bg-white dark:focus:bg-slate-800"
                                                        value={v.sku}
                                                        onChange={(e) => handleVariantChange(idx, 'sku', e.target.value)}
                                                    />
                                                </td>
                                                <td className="p-2">
                                                    <input
                                                        type="text"
                                                        className="bg-transparent w-full p-2 border border-transparent group-hover:border-slate-200 dark:group-hover:border-white/10 rounded-lg text-xs font-medium transition-all focus:bg-white dark:focus:bg-slate-800"
                                                        value={JSON.stringify(v.options)}
                                                        onChange={(e) => {
                                                            try {
                                                                handleVariantChange(idx, 'options', JSON.parse(e.target.value));
                                                            } catch (e) { }
                                                        }}
                                                    />
                                                </td>
                                                <td className="p-2 w-28">
                                                    <input
                                                        type="number"
                                                        className="bg-transparent w-full p-2 border border-transparent group-hover:border-slate-200 dark:group-hover:border-white/10 rounded-lg text-xs font-black text-blue-600 dark:text-blue-400 transition-all focus:bg-white dark:focus:bg-slate-800"
                                                        value={v.price}
                                                        onChange={(e) => handleVariantChange(idx, 'price', e.target.value)}
                                                    />
                                                </td>
                                                <td className="p-2 w-28">
                                                    <input
                                                        type="number"
                                                        className="bg-transparent w-full p-2 border border-transparent group-hover:border-slate-200 dark:group-hover:border-white/10 rounded-lg text-xs font-bold text-slate-500 transition-all focus:bg-white dark:focus:bg-slate-800"
                                                        value={v.costPrice}
                                                        onChange={(e) => handleVariantChange(idx, 'costPrice', e.target.value)}
                                                    />
                                                </td>
                                                <td className="p-2 w-24">
                                                    <input
                                                        type="number"
                                                        className="bg-transparent w-full p-2 border border-transparent group-hover:border-slate-200 dark:group-hover:border-white/10 rounded-lg text-xs font-black text-purple-600 transition-all focus:bg-white dark:focus:bg-slate-800 text-center"
                                                        value={v.stock}
                                                        onChange={(e) => handleVariantChange(idx, 'stock', e.target.value)}
                                                    />
                                                </td>
                                                <td className="p-2 text-center">
                                                    <button
                                                        onClick={() => removeVariant(idx)}
                                                        className="p-2 text-slate-300 hover:text-red-500 transition-colors"
                                                    >
                                                        <Trash2 size={14} />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                        {localVariants.length === 0 && !variantsLoading && (
                                            <tr>
                                                <td colSpan={6} className="p-8 text-center text-slate-400 text-sm font-medium">
                                                    Bu ürün için henüz varyant tanımlanmamış.
                                                </td>
                                            </tr>
                                        )}
                                        {variantsLoading && (
                                            <tr>
                                                <td colSpan={6} className="p-8 text-center">
                                                    <Loader2 className="w-6 h-6 animate-spin mx-auto text-purple-500" />
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    ) : (
                        <div className="bg-white dark:bg-slate-900 border border-dashed border-slate-300 dark:border-white/10 rounded-3xl h-[500px] flex flex-col items-center justify-center text-center p-10">
                            <div className="w-16 h-16 bg-slate-50 dark:bg-white/5 rounded-2xl flex items-center justify-center mb-6">
                                <Package size={32} className="text-slate-300" />
                            </div>
                            <h3 className="text-xl font-black text-slate-800 dark:text-white mb-2">Ürün Seçilmedi</h3>
                            <p className="text-slate-500 dark:text-slate-400 max-w-xs font-medium">
                                Varyantlarını düzenlemek istediğiniz ürünü soldaki listeden seçerek başlayın.
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  LineChart, Line, AreaChart, Area, BarChart, Bar, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { Activity, DollarSign, TrendingUp, Users, Target, Package, ArrowUpRight, ArrowDownRight, RefreshCcw } from 'lucide-react';
import { PageTransition } from '@/components/admin/PageTransition';

export default function AnalyticsDashboard() {
  // ═══════════════════════════════════════════════════════════════════
  // DATA FETCHING
  // ═══════════════════════════════════════════════════════════════════

  const { data: pnlData, isLoading: pnlLoading } = useQuery({
    queryKey: ['admin', 'reports', 'pnl'],
    queryFn: async () => {
      const res = await fetch('/api/admin/reports/pnl');
      if (!res.ok) throw new Error('Network response was not ok');
      return res.json();
    }
  });

  const { data: cohortData, isLoading: cohortLoading } = useQuery({
    queryKey: ['admin', 'reports', 'cohort'],
    queryFn: async () => {
      const res = await fetch('/api/admin/reports/cohort');
      if (!res.ok) throw new Error('Network response was not ok');
      return res.json();
    }
  });

  const { data: bestSellers, isLoading: bsLoading } = useQuery({
    queryKey: ['admin', 'reports', 'bestsellers'],
    queryFn: async () => {
      const res = await fetch('/api/admin/reports/bestsellers');
      if (!res.ok) throw new Error('Network response was not ok');
      return res.json();
    }
  });

  const { data: geoData, isLoading: geoLoading } = useQuery({
    queryKey: ['admin', 'reports', 'geo'],
    queryFn: async () => {
      const res = await fetch('/api/admin/reports/geo');
      if (!res.ok) throw new Error('Network response was not ok');
      return res.json();
    }
  });

  // ═══════════════════════════════════════════════════════════════════
  // RENDER HELPERS
  // ═══════════════════════════════════════════════════════════════════

  const formatCurrency = (value: number) => {
    if (value >= 1000000) return `₺${(value / 1000000).toFixed(1)}M`;
    if (value >= 1000) return `₺${(value / 1000).toFixed(1)}K`;
    return `₺${value}`;
  };

  const isLoading = pnlLoading || cohortLoading || bsLoading || geoLoading;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="flex flex-col items-center gap-4 text-slate-500">
          <RefreshCcw className="w-8 h-8 animate-spin" />
          <p className="font-medium animate-pulse">Analiz verileri derleniyor...</p>
        </div>
      </div>
    );
  }

  // Prepare P&L Data for charts (Reverse to show chronological)
  const chartData = pnlData ? [...pnlData].reverse() : [];
  const currentMonthPnl = pnlData?.[0] || { revenue: 0, profit: 0, costs: 0 };
  const prevMonthPnl = pnlData?.[1] || { revenue: 0, profit: 0, costs: 0 };

  const revenueGrowth = prevMonthPnl.revenue ? ((currentMonthPnl.revenue - prevMonthPnl.revenue) / prevMonthPnl.revenue) * 100 : 0;
  const profitGrowth = prevMonthPnl.profit ? ((currentMonthPnl.profit - prevMonthPnl.profit) / prevMonthPnl.profit) * 100 : 0;
  const costGrowth = prevMonthPnl.costs ? ((currentMonthPnl.costs - prevMonthPnl.costs) / prevMonthPnl.costs) * 100 : 0;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-black tracking-tight text-slate-900 dark:text-white">Gelişmiş Analitik</h1>
          <p className="text-sm text-slate-500 mt-1">Platform geneli kar/zarar, müşteri sadakati ve performans metrikleri.</p>
        </div>
        <div className="flex gap-2">
          <button className="px-4 py-2 text-sm font-semibold rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
            PDF Olarak Dışa Aktar
          </button>
          <button className="px-4 py-2 text-sm font-semibold rounded-lg bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-500/20 transition-all">
            Rapor Oluştur
          </button>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard
          title="Bu Ayki Net Ciro"
          value={`₺${currentMonthPnl.revenue.toLocaleString('tr-TR')}`}
          trend={revenueGrowth}
          icon={DollarSign}
          color="blue"
        />
        <MetricCard
          title="Bu Ayki Net Kar"
          value={`₺${currentMonthPnl.profit.toLocaleString('tr-TR')}`}
          trend={profitGrowth}
          icon={TrendingUp}
          color="emerald"
        />
        <MetricCard
          title="Toplam Operasyon Gideri"
          value={`₺${currentMonthPnl.costs.toLocaleString('tr-TR')}`}
          trend={costGrowth}
          icon={Activity}
          color="orange"
          inverseTrend // Higher costs = bad (red arrow)
        />
        <MetricCard
          title="Aktif Cohort Sayısı"
          value={cohortData?.length?.toString() || "0"}
          trend={0}
          icon={Users}
          color="purple"
        />
      </div>

      {/* Main P&L Chart */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-2xl p-6 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="font-bold text-slate-900 dark:text-white">Kar/Zarar (P&L) Trendi</h3>
              <p className="text-xs text-slate-500">Son 6 aylık gelir, maliyet ve kar dağılımı</p>
            </div>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                  </linearGradient>
                  <linearGradient id="colorProfit" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(255,255,255,0.1)" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#64748b' }} dy={10} />
                <YAxis tickFormatter={formatCurrency} axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#64748b' }} dx={-10} />
                <Tooltip
                  contentStyle={{ backgroundColor: 'rgba(15, 23, 42, 0.9)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', color: '#fff' }}
                  itemStyle={{ color: '#e2e8f0', fontSize: '13px' }}
                  formatter={(value: any) => `₺${Number(value).toLocaleString('tr-TR')}`}
                />
                <Legend wrapperStyle={{ fontSize: '12px', paddingTop: '20px' }} />
                <Area type="monotone" name="Brüt Gelir" dataKey="revenue" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorRevenue)" />
                <Area type="monotone" name="Net Kar" dataKey="profit" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorProfit)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Best Sellers Matrix */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-2xl p-6 shadow-sm flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="font-bold text-slate-900 dark:text-white">Çok Satanlar (Hacim)</h3>
              <p className="text-xs text-slate-500">Adet bazında en çok satan ilk 5 ürün</p>
            </div>
          </div>
          <div className="flex-1 space-y-4">
            {bestSellers?.slice(0, 5).map((item: any, idx: number) => (
              <div key={item.id} className="flex items-center gap-4">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${idx === 0 ? 'bg-amber-100 text-amber-600 dark:bg-amber-500/20 dark:text-amber-400' :
                  idx === 1 ? 'bg-slate-100 text-slate-500 dark:bg-slate-700 dark:text-slate-300' :
                    idx === 2 ? 'bg-orange-100 text-orange-700 dark:bg-orange-500/20 dark:text-orange-400' :
                      'bg-blue-50 text-blue-600 dark:bg-blue-500/10 dark:text-blue-400'
                  }`}>
                  #{idx + 1}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold text-slate-800 dark:text-slate-200 truncate">{item.title}</p>
                  <div className="flex items-center gap-3 mt-1 text-xs text-slate-500">
                    <span className="flex items-center gap-1"><Package size={12} /> {item.sales} sat.</span>
                    <span className="flex items-center gap-1 text-red-500"><RotateCcw size={12} /> %{item.returnRate} iade</span>
                  </div>
                </div>
              </div>
            ))}
            {(!bestSellers || bestSellers.length === 0) && (
              <div className="h-full flex items-center justify-center text-sm text-slate-500">Veri bulunamadı</div>
            )}
          </div>
        </div>
      </div>

      {/* Cohort Analysis / Retention Heatmap */}
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-2xl p-6 shadow-sm overflow-x-auto">
        <div className="mb-6">
          <h3 className="font-bold text-slate-900 dark:text-white">Kohort Analizi (Müşteri Sadakati)</h3>
          <p className="text-xs text-slate-500">Sipariş veren müşterilerin sonraki aylardaki geri dönüş (retention) oranları</p>
        </div>
        <table className="w-full text-sm text-left border-collapse">
          <thead>
            <tr className="text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
              <th className="py-3 px-4 font-semibold w-32">Kohort (Ay)</th>
              <th className="py-3 px-4 font-semibold w-24">Boyut</th>
              <th className="py-3 px-4 font-medium text-center">Ay 1</th>
              <th className="py-3 px-4 font-medium text-center">Ay 2</th>
              <th className="py-3 px-4 font-medium text-center">Ay 3</th>
              <th className="py-3 px-4 font-medium text-center">Ay 4</th>
              <th className="py-3 px-4 font-medium text-center">Ay 5</th>
              <th className="py-3 px-4 font-medium text-center">Ay 6</th>
            </tr>
          </thead>
          <tbody>
            {cohortData?.map((row: any, i: number) => (
              <tr key={i} className="border-b border-slate-100 dark:border-white/5 last:border-0 hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors">
                <td className="py-3 px-4 font-medium text-slate-800 dark:text-slate-200">{row.cohort}</td>
                <td className="py-3 px-4 text-slate-500">{row.size} Kş.</td>
                <CohortCell val={row.m1} />
                <CohortCell val={row.m2} />
                <CohortCell val={row.m3} />
                <CohortCell val={row.m4} />
                <CohortCell val={row.m5} />
                <CohortCell val={row.m6} />
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Geographic Distribution (Horizontal Bar / Density) */}
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-2xl p-6 shadow-sm">
        <div className="mb-6">
          <h3 className="font-bold text-slate-900 dark:text-white">Coğrafi Sipariş Dağılımı</h3>
          <p className="text-xs text-slate-500">En çok sipariş alınan şehirler ve sipariş yoğunluğu</p>
        </div>
        <div className="h-[250px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart layout="vertical" data={geoData} margin={{ top: 0, right: 30, left: 30, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="rgba(255,255,255,0.05)" />
              <XAxis type="number" hide />
              <YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 13, fill: '#64748b', fontWeight: 500 }} />
              <Tooltip
                cursor={{ fill: 'rgba(59, 130, 246, 0.1)' }}
                contentStyle={{ backgroundColor: 'rgba(15, 23, 42, 0.9)', border: 'none', borderRadius: '8px', color: '#fff' }}
                formatter={(value: any) => [`${value} Sipariş`, 'Yoğunluk']}
              />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20}>
                {
                  geoData?.map((entry: any, index: number) => (
                    <Cell key={`cell-${index}`} fill={index === 0 ? '#3b82f6' : index === 1 ? '#60a5fa' : index === 2 ? '#93c5fd' : '#bfdbfe'} />
                  ))
                }
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}

