        enabled: activeTab === 'overview' || activeTab === '2fa',
    });

    const blockIpMutation = useMutation({
        mutationFn: ({ ip, reason }: { ip: string; reason: string }) => adminApi.blockIp(ip, reason),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['suspicious-ips'] });
