"use client";

import React, { useState, useEffect } from 'react';
import { MessageSquare, User, Clock, CheckCircle, AlertCircle, Sparkles, Send, MoreVertical, Paperclip } from 'lucide-react';
import { useSupport } from '@/lib/hooks';
import { format } from 'date-fns';
import { tr } from 'date-fns/locale';

interface SupportMessage {
    id?: string;
    content: string;
    senderType: 'AGENT' | 'CUSTOMER';
    createdAt: string;
}

interface SupportTicket {
    id: string;
    subject: string;
    customerName: string;
    company?: string;
    status: 'OPEN' | 'PENDING' | 'RESOLVED';
    priority?: string;
    platform: string;
    updatedAt: string;
    messages?: SupportMessage[];
}

export default function SupportPage() {
    const { getTickets, getTicketDetails, sendMessage, loading } = useSupport();
    const [tickets, setTickets] = useState<SupportTicket[]>([]);
    const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
    const [messages, setMessages] = useState<SupportMessage[]>([]);
    const [newMessage, setNewMessage] = useState("");
    const [searchQuery, setSearchQuery] = useState("");

    const loadTickets = async () => {
        // use demo-tenant-id or admin to get all. In our mock it returns all sorted by date.
        const response = await getTickets('admin') as SupportTicket[];
        if (response) {
            setTickets(response);
        }
    };

    useEffect(() => {
        loadTickets();
    }, []);

    const loadTicketDetails = async (id: string) => {
        const response = await getTicketDetails(id, 'admin') as SupportTicket;
        if (response) {
            setSelectedTicket(response);
            setMessages(response.messages || []);
        }
    };

    const handleSendMessage = async () => {
        if (!newMessage.trim() || !selectedTicket) return;

        const content = newMessage;
        setNewMessage("");

        const response = await sendMessage({
            ticketId: selectedTicket.id,
            content,
            senderType: "AGENT",
            tenantId: 'admin'
        }) as SupportMessage;

        if (response) {
            setMessages(prev => [...prev, response]);
            loadTickets(); // fresh ticket list
        }
    };

    const filteredTickets = tickets.filter(t =>
        t.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
        t.customerName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        t.id.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const openCount = tickets.filter(t => t.status === 'OPEN').length;
    const pendingCount = tickets.filter(t => t.status === 'PENDING').length;
    const closedCount = tickets.filter(t => t.status === 'RESOLVED').length;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 h-[calc(100vh-140px)] flex flex-col">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight mb-1">Destek Merkezi</h1>
                    <p className="text-slate-600 dark:text-slate-500 font-medium">Kullanıcı taleplerini yanıtlayın ve yönetin.</p>
                </div>
                <div className="flex gap-2">
                    <button className="px-4 py-2 bg-blue-500/10 dark:bg-white/5 hover:bg-blue-500/20 dark:hover:bg-white/10 text-blue-600 dark:text-white rounded-xl font-bold text-xs transition-colors border border-blue-500/20 dark:border-white/10">
                        Açık ({openCount})
                    </button>
                    <button className="px-4 py-2 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 rounded-xl font-bold text-xs transition-colors border border-slate-200 dark:border-white/10">
                        Bekleyen ({pendingCount})
                    </button>
                    <button className="px-4 py-2 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 rounded-xl font-bold text-xs transition-colors border border-slate-200 dark:border-white/10">
                        Kapalı ({closedCount})
                    </button>
                </div>
            </div>

            <div className="flex-1 grid grid-cols-12 gap-8 min-h-0">
                {/* Ticket List */}
                <div className="col-span-4 bg-white dark:bg-slate-900/50 rounded-[32px] border border-slate-200 dark:border-white/5 flex flex-col overflow-hidden shadow-sm dark:shadow-none">
                    <div className="p-4 border-b border-slate-200 dark:border-white/5 bg-slate-50 dark:bg-white/[0.02]">
                        <input
                            type="text"
                            placeholder="Talep ara..."
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            className="w-full h-10 bg-slate-100 dark:bg-black/20 rounded-xl px-4 text-xs font-bold text-foreground outline-none border border-transparent focus:border-blue-500/30" />
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 space-y-2">
                        {filteredTickets.map((ticket) => (
                            <div
                                key={ticket.id}
                                onClick={() => loadTicketDetails(ticket.id)}
                                className={`p-4 rounded-2xl border cursor-pointer transition-all hover:bg-slate-50 dark:hover:bg-white/5 ${selectedTicket?.id === ticket.id
                                    ? 'bg-blue-50 dark:bg-blue-600/10 border-blue-500/30 shadow-lg shadow-blue-900/10'
                                    : 'bg-transparent border-slate-200 dark:border-white/5'
                                    }`}
                            >
                                <div className="flex justify-between items-start mb-2">
                                    <div className="flex items-center gap-2">
                                        <div className={`w-2 h-2 rounded-full ${ticket.priority === 'high' ? 'bg-red-500' : ticket.priority === 'medium' ? 'bg-amber-500' : 'bg-blue-500'}`} />
                                        <span className="text-[10px] font-black text-slate-400 uppercase">#{ticket.id}</span>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">
                                        {format(new Date(ticket.updatedAt), 'HH:mm', { locale: tr })}
                                    </span>
                                </div>
                                <h4 className={`text-sm font-bold mb-1 ${selectedTicket?.id === ticket.id ? 'text-foreground' : 'text-slate-700 dark:text-slate-300'}`}>{ticket.subject}</h4>
                                <div className="flex items-center gap-2">
                                    <User size={12} className="text-slate-500" />
                                    <span className="text-xs text-slate-500 font-medium">{ticket.customerName} - {ticket.company || ticket.platform}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Ticket Detail / Chat */}
                <div className="col-span-8 bg-white dark:bg-slate-900/50 rounded-[32px] border border-slate-200 dark:border-white/5 flex flex-col overflow-hidden relative shadow-sm dark:shadow-none">
                    {selectedTicket ? (
                        <>
                            {/* Header */}
                            <div className="p-6 border-b border-slate-200 dark:border-white/5 flex justify-between items-center bg-slate-50 dark:bg-white/[0.02]">
                                <div>
                                    <div className="flex items-center gap-3 mb-1">
                                        <h3 className="text-lg font-bold text-foreground">#{selectedTicket.id} - {selectedTicket.subject}</h3>
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase border ${selectedTicket.priority === 'high' ? 'bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/20' : 'bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20'}`}>
                                            {selectedTicket.priority || 'Normal'} Öncelik
                                        </span>
                                    </div>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 font-medium">{selectedTicket.customerName} • {selectedTicket.company || selectedTicket.platform}</p>
                                </div>
                                <button className="p-2 hover:bg-slate-100 dark:hover:bg-white/10 rounded-lg text-slate-400 hover:text-slate-700 dark:hover:text-white transition-colors">
                                    <MoreVertical size={20} />
                                </button>
                            </div>

                            {/* Chat Area */}
                            <div className="flex-1 overflow-y-auto p-8 space-y-8">
                                {messages.map((msg, idx) => (
                                    <div key={msg.id || idx} className={`flex gap-4 ${msg.senderType === 'AGENT' ? 'flex-row-reverse' : ''}`}>
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${msg.senderType === 'AGENT' ? 'bg-blue-600 text-white' : 'bg-slate-300 dark:bg-slate-700 text-slate-700 dark:text-white'}`}>
                                            {msg.senderType === 'AGENT' ? <Sparkles size={14} className="text-white" /> : (selectedTicket.customerName?.[0] || 'C')}
                                        </div>
                                        <div className={`flex-1 space-y-2 flex flex-col ${msg.senderType === 'AGENT' ? 'items-end' : 'items-start'}`}>
                                            <div className="flex items-center gap-2">
                                                <span className="text-sm font-bold text-foreground">{msg.senderType === 'AGENT' ? 'AI Asistan / Yönetici' : selectedTicket.customerName}</span>
                                                <span className="text-xs text-slate-500">{format(new Date(msg.createdAt), 'HH:mm', { locale: tr })}</span>
                                            </div>
                                            <div className={`p-4 rounded-2xl text-sm leading-relaxed ${msg.senderType === 'AGENT'
                                                ? 'rounded-tr-none bg-blue-50 dark:bg-blue-600/10 border border-blue-200 dark:border-blue-500/20 text-blue-800 dark:text-blue-100'
                                                : 'rounded-tl-none bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/5 text-slate-700 dark:text-slate-300'}`}>
                                                {msg.content}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {/* Input Area */}
                            <div className="p-6 border-t border-slate-200 dark:border-white/5 bg-slate-50 dark:bg-white/[0.02]">
                                <div className="relative">
                                    <textarea
                                        placeholder="Yanıtınızı yazın..."
                                        value={newMessage}
                                        onChange={(e) => setNewMessage(e.target.value)}
                                        onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                                        className="w-full h-32 bg-slate-100 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-foreground outline-none focus:border-blue-500/50 resize-none pr-32" />
                                    <div className="absolute bottom-4 right-4 flex items-center gap-2">
                                        <button className="p-2 hover:bg-slate-200 dark:hover:bg-white/10 rounded-lg text-slate-500 hover:text-slate-700 dark:hover:text-white transition-colors">
                                            <Paperclip size={18} />
                                        </button>
                                        <button
                                            onClick={handleSendMessage}
                                            disabled={loading || !newMessage.trim()}
                                            className="px-4 py-2 bg-blue-600 hover:bg-blue-500 active:scale-95 disabled:opacity-50 text-white rounded-xl font-bold text-sm flex items-center gap-2 transition-all">
                                            Gönder <Send size={14} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                            <MessageSquare size={48} className="mb-4 opacity-20" />
                            <p className="font-bold">Bir talep seçin</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { adminApi } from '@/lib/admin-api';
import {
    Plus, Search, CheckCircle, Clock, AlertTriangle,
    MoreVertical, Calendar, CalendarDays, User, Target, Loader2
} from 'lucide-react';
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd';

interface AdminTask {
    id: string;
    title: string;
    description: string | null;
    status: string; // TODO, IN_PROGRESS, IN_REVIEW, DONE
    priority: string; // LOW, MEDIUM, HIGH, URGENT
    assignee: { id: string; name: string; email: string } | null;
    dueDate: string | null;
    createdAt: string;
}

const COLUMNS = [
    { id: 'TODO', title: 'Yapılacaklar', color: 'border-slate-200 dark:border-white/10' },
    { id: 'IN_PROGRESS', title: 'Devam Eden', color: 'border-blue-500/30' },
    { id: 'IN_REVIEW', title: 'İncelemede', color: 'border-amber-500/30' },
    { id: 'DONE', title: 'Tamamlandı', color: 'border-emerald-500/30' }
];

export default function KanbanTasksPage() {
    const queryClient = useQueryClient();
    const [search, setSearch] = useState('');

    const { data: tasks = [], isLoading } = useQuery({
        queryKey: ['admin-tasks'],
        queryFn: () => adminApi.getTasks(),
    });

    const updateMutation = useMutation({
        mutationFn: ({ id, status }: { id: string; status: string }) => adminApi.updateTask(id, { status }),
        onMutate: async ({ id, status }) => {
            // Optimistic update
            await queryClient.cancelQueries({ queryKey: ['admin-tasks'] });
            const previous = queryClient.getQueryData(['admin-tasks']);
            queryClient.setQueryData(['admin-tasks'], (old: any) => {
                return old?.map((t: any) => t.id === id ? { ...t, status } : t) || [];
            });
            return { previous };
        },
        onError: (err, variables, context) => {
            queryClient.setQueryData(['admin-tasks'], context?.previous);
        },
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: ['admin-tasks'] });
        }
    });

    const onDragEnd = (result: any) => {
        const { destination, source, draggableId } = result;

        if (!destination) return;
        if (destination.droppableId === source.droppableId) return;

        updateMutation.mutate({ id: draggableId, status: destination.droppableId });
    };

    const getPriorityBadge = (p: string) => {
        switch (p) {
            case 'URGENT': return <span className="px-2 py-0.5 text-[10px] uppercase font-black bg-red-100 text-red-600 rounded-lg">Acil</span>;
            case 'HIGH': return <span className="px-2 py-0.5 text-[10px] uppercase font-black bg-amber-100 text-amber-600 rounded-lg">Yüksek</span>;
            case 'MEDIUM': return <span className="px-2 py-0.5 text-[10px] uppercase font-black bg-blue-100 text-blue-600 rounded-lg">Normal</span>;
            default: return <span className="px-2 py-0.5 text-[10px] uppercase font-black bg-slate-100 text-slate-600 rounded-lg">Düşük</span>;
        }
    };

    const filteredTasks = tasks.filter((t: AdminTask) =>
        t.title.toLowerCase().includes(search.toLowerCase()) ||
        (t.description && t.description.toLowerCase().includes(search.toLowerCase()))
    );

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20 h-full flex flex-col">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight leading-tight">Görev Yönetimi</h1>
                    <p className="text-slate-500 dark:text-slate-400 font-medium">Operasyonel görevleri ve ekip süreçlerini Kanban panosu ile takip edin.</p>
                </div>
                <button className="flex items-center gap-2 px-4 py-2.5 bg-blue-500 hover:bg-blue-600 text-white rounded-xl text-sm font-bold transition-all shadow-sm shadow-blue-500/20">
                    <Plus size={16} /> Görev Oluştur
                </button>
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 p-4 rounded-2xl flex flex-col sm:flex-row gap-4 shadow-sm">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input
                        type="text"
                        placeholder="Görev adı veya içeriğinde ara..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="w-full h-10 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-white/10 rounded-xl pl-10 pr-4 text-sm font-bold text-slate-900 dark:text-white placeholder:text-slate-500 outline-none focus:border-blue-500/50"
                    />
                </div>
            </div>

            {/* Kanban Board */}
            {isLoading ? (
                <div className="flex items-center justify-center min-h-[400px]">
                    <Loader2 className="w-10 h-10 animate-spin text-blue-500" />
                </div>
            ) : (
                <DragDropContext onDragEnd={onDragEnd}>
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6 items-start h-full min-h-[600px] overflow-x-auto pb-6">
                        {COLUMNS.map(column => {
                            const columnTasks = filteredTasks.filter((t: AdminTask) => t.status === column.id);

                            return (
                                <div key={column.id} className="flex flex-col h-full bg-slate-50/50 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-white/10 overflow-hidden">
                                    <div className={`p-4 border-b ${column.color} bg-white dark:bg-white/[0.02] flex items-center justify-between shadow-sm z-10`}>
                                        <h3 className="font-black text-slate-700 dark:text-slate-300 text-sm">{column.title}</h3>
                                        <span className="text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">{columnTasks.length}</span>
                                    </div>

                                    <Droppable droppableId={column.id}>
                                        {(provided) => (
                                            <div
                                                ref={provided.innerRef}
                                                {...provided.droppableProps}
                                                className="flex-1 p-3 space-y-3 min-h-[150px] overflow-y-auto"
                                            >
                                                {columnTasks.map((task: AdminTask, index: number) => (
                                                    <Draggable key={task.id} draggableId={task.id} index={index}>
                                                        {(provided, snapshot) => (
                                                            <div
                                                                ref={provided.innerRef}
                                                                {...provided.draggableProps}
                                                                {...provided.dragHandleProps}
                                                                className={`p-4 bg-white dark:bg-slate-800 border ${snapshot.isDragging ? 'border-blue-500 ring-4 ring-blue-500/20' : 'border-slate-200 dark:border-white/10'} rounded-xl shadow-sm hover:shadow transition-all group select-none`}
                                                            >
                                                                <div className="flex items-start justify-between mb-2">
                                                                    {getPriorityBadge(task.priority)}
                                                                    <button className="text-slate-400 hover:text-blue-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                                                        <MoreVertical size={14} />
                                                                    </button>
                                                                </div>
                                                                <h4 className="font-bold text-slate-900 dark:text-white text-sm leading-tight mb-2">
                                                                    {task.title}
                                                                </h4>
                                                                {task.dueDate && (
                                                                    <div className="flex items-center gap-1 text-[11px] font-bold text-slate-500 dark:text-slate-400 mb-4 bg-slate-50 dark:bg-white/5 w-fit px-2 py-1 rounded-lg">
                                                                        <CalendarDays size={12} /> {new Date(task.dueDate).toLocaleDateString('tr-TR', { day: 'numeric', month: 'short' })}
                                                                    </div>
                                                                )}
                                                                <div className="flex items-center justify-between mt-auto">
                                                                    <div className="flex flex-wrap gap-1">
                                                                        <Target size={14} className="text-slate-400" />
                                                                    </div>
                                                                    {task.assignee ? (
                                                                        <div className="flex items-center gap-1.5" title={task.assignee.name}>
                                                                            <div className="w-6 h-6 rounded-full bg-gradient-to-br from-indigo-500 to-blue-500 flex items-center justify-center text-[10px] text-white font-bold shadow-inner border border-white dark:border-slate-700">
                                                                                {task.assignee.name?.charAt(0)?.toUpperCase()}
                                                                            </div>
                                                                        </div>
                                                                    ) : (
                                                                        <div className="w-6 h-6 rounded-full border border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center text-slate-400" title="Atanmadı">
                                                                            <User size={12} />
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            </div>
                                                        )}
                                                    </Draggable>
                                                ))}
                                                {provided.placeholder}
                                            </div>
                                        )}
                                    </Droppable>
                                </div>
                            );
                        })}
                    </div>
                </DragDropContext>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { adminApi } from '@/lib/admin-api';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import {
    ArrowLeft, Building2, Users, ShoppingBag, Package, CreditCard,
    Globe, Calendar, Clock, Edit, Save, X, Trash2, Mail, Phone,
    MapPin, Crown, Sparkles, Tag, CheckCircle, AlertTriangle,
    Activity, ExternalLink, Shield, Settings, BarChart3, Loader2, LucideIcon
} from 'lucide-react';

interface User {
    id: string;
    name: string;
    email: string;
    type: 'SUPERADMIN' | 'ADMIN' | 'USER';
    twoFactorEnabled: boolean;
}

interface Integration {
    id: string;
    platform: string;
    shopName?: string;
    isActive: boolean;
}

const tenantSchema = z.object({
    name: z.string().min(2, 'En az 2 karakter'),
    domain: z.string().optional(),
    plan: z.enum(['FREE', 'PRO', 'ENTERPRISE']),
    taxOffice: z.string().optional(),
    taxNumber: z.string().optional(),
});

type TenantFormData = z.infer<typeof tenantSchema>;

const PLAN_CONFIG = {
    FREE: { label: 'Ücretsiz', color: 'slate', icon: Tag, bgClass: 'bg-slate-500/10', textClass: 'text-slate-400' },
    PRO: { label: 'Pro', color: 'blue', icon: Sparkles, bgClass: 'bg-blue-500/10', textClass: 'text-blue-400' },
    ENTERPRISE: { label: 'Kurumsal', color: 'purple', icon: Crown, bgClass: 'bg-purple-500/10', textClass: 'text-purple-400' },
};

export default function TenantDetailPage() {
    const params = useParams();
    const router = useRouter();
    const queryClient = useQueryClient();
    const tenantIdParam = params?.id;
    const tenantId = Array.isArray(tenantIdParam) ? tenantIdParam[0] : tenantIdParam ?? '';
    const [isEditing, setIsEditing] = useState(false);

    const { data: tenant, isLoading, error } = useQuery({
        queryKey: ['tenant', tenantId],
        queryFn: () => adminApi.getTenantDetail(tenantId),
    });

    const updateMutation = useMutation({
        mutationFn: (data: TenantFormData) => adminApi.updateTenant(tenantId, data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['tenant', tenantId] });
            setIsEditing(false);
        },
    });

    const deleteMutation = useMutation({
        mutationFn: () => adminApi.deleteTenant(tenantId),
        onSuccess: () => router.push('/admin/tenants'),
    });

    const { register, handleSubmit, formState: { errors }, reset } = useForm<TenantFormData>({
        resolver: zodResolver(tenantSchema),
        values: tenant ? {
            name: tenant.name || '',
            domain: tenant.domain || '',
            plan: tenant.plan || 'FREE',
            taxOffice: tenant.taxOffice || '',
            taxNumber: tenant.taxNumber || '',
        } : undefined,
    });

    const onSubmit = (data: TenantFormData) => updateMutation.mutate(data);

    const formatCurrency = (value: number) =>
        new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY', maximumFractionDigits: 0 }).format(value);

    const formatDate = (date: string) =>
        new Date(date).toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="text-center space-y-4">
                    <Loader2 className="w-8 h-8 animate-spin text-blue-500 mx-auto" />
                    <p className="text-slate-500 font-medium">Kiracı bilgileri yükleniyor...</p>
                </div>
            </div>
        );
    }

    if (error || !tenant) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="text-center space-y-4">
                    <AlertTriangle className="w-12 h-12 text-red-500 mx-auto" />
                    <p className="text-red-500 font-bold text-lg">Kiracı bulunamadı</p>
                    <button onClick={() => router.push('/admin/tenants')} className="px-4 py-2 bg-blue-500 text-white rounded-xl font-bold text-sm">
                        Geri Dön
                    </button>
                </div>
            </div>
