    const planConfig = PLAN_CONFIG[tenant.plan as keyof typeof PLAN_CONFIG] || PLAN_CONFIG.FREE;
    const PlanIcon = planConfig.icon;

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
