import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";

// GET /api/admin/menus - Tüm menüleri listele
export async function GET() {
  const session = await auth();

  if (!session?.user || session.user.type !== "SUPERADMIN") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const menus = await prisma.menu.findMany({
      orderBy: [{ isDefault: "desc" }, { sortOrder: "asc" }],
      include: {
        items: {
          where: { parentId: null },
          orderBy: { sortOrder: "asc" },
          include: {
            children: {
              orderBy: { sortOrder: "asc" },
              include: {
                children: { orderBy: { sortOrder: "asc" } },
              },
            },
          },
        },
      },
    });

    return NextResponse.json(menus);
  } catch (error) {
    console.error("Error fetching menus:", error);
    return NextResponse.json(
      { error: "Failed to fetch menus" },
      { status: 500 }
    );
  }
}

// POST /api/admin/menus - Yeni menü oluştur
export async function POST(request: NextRequest) {
  const session = await auth();

  if (!session?.user || session.user.type !== "SUPERADMIN") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const data = await request.json();

    const menu = await prisma.menu.create({
      data: {
        name: data.name,
        type: data.type,
        location: data.location,
        isActive: data.isActive ?? true,
        isDefault: data.isDefault ?? false,
      },
    });

    // Menü öğelerini oluştur
    if (data.items && data.items.length > 0) {
      for (let i = 0; i < data.items.length; i++) {
        const item = data.items[i];
        await createMenuItem(menu.id, item, null, i);
      }
    }

    return NextResponse.json(menu);
  } catch (error) {
    console.error("Error creating menu:", error);
    return NextResponse.json(
      { error: "Failed to create menu" },
      { status: 500 }
    );
  }
}

// Yardımcı fonksiyon: Menü öğelerini recursive oluştur
async function createMenuItem(
  menuId: string,
  item: any,
  parentId: string | null,
  sortOrder: number
) {
  const created = await prisma.menuItem.create({
    data: {
      menuId,
      parentId,
      type: item.type || "LINK",
      label: item.label,
      url: item.url,
      icon: item.icon,
      description: item.description,
      isActive: item.isActive ?? true,
      isHighlighted: item.isHighlighted ?? false,
      highlightColor: item.highlightColor,
      imageUrl: item.imageUrl,
      columns: item.columns || 1,
      sortOrder,
    },
  });

  // Alt öğeleri oluştur
  if (item.children && item.children.length > 0) {
    for (let i = 0; i < item.children.length; i++) {
      await createMenuItem(menuId, item.children[i], created.id, i);
    }
  }

  return created;
}

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";

// GET /api/admin/pages/[id] - Tekil sayfa detayı
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await auth();

  if (!session?.user || session.user.type !== "SUPERADMIN") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await params;
    const page = await prisma.page.findUnique({
      where: { id },
      include: {
        sections: {
          orderBy: { sortOrder: "asc" },
          include: {
            blocks: {
              orderBy: { sortOrder: "asc" },
            },
          },
        },
      },
    });

    if (!page) {
      return NextResponse.json({ error: "Page not found" }, { status: 404 });
    }

    return NextResponse.json(page);
  } catch (error) {
    console.error("Error fetching page:", error);
    return NextResponse.json(
      { error: "Failed to fetch page" },
      { status: 500 }
    );
  }
}

// PUT /api/admin/pages/[id] - Sayfa güncelle
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await auth();

  if (!session?.user || session.user.type !== "SUPERADMIN") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await params;
    const data = await request.json();

    // Slug benzersizlik kontrolü (başka sayfada var mı)
    if (data.slug) {
      const existingPage = await prisma.page.findFirst({
        where: {
          slug: data.slug,
          id: { not: id },
        },
      });

      if (existingPage) {
        return NextResponse.json(
          { error: "A page with this slug already exists" },
          { status: 400 }
        );
      }
    }

    const updateData: any = {
      slug: data.slug,
      title: data.title,
      description: data.description,
      type: data.type,
      status: data.status,
      metaTitle: data.metaTitle,
      metaDescription: data.metaDescription,
      metaKeywords: data.metaKeywords,
      ogImage: data.ogImage,
      canonicalUrl: data.canonicalUrl,
      noIndex: data.noIndex,
      layout: data.layout,
      theme: data.theme,
      customCss: data.customCss,
      isActive: data.isActive,
      sortOrder: data.sortOrder,
      version: { increment: 1 },
    };

    // Yayınlanma tarihi kontrolü
    if (data.status === "PUBLISHED") {
      const currentPage = await prisma.page.findUnique({
        where: { id },
        select: { status: true, publishedAt: true },
      });

      if (currentPage?.status !== "PUBLISHED" && !currentPage?.publishedAt) {
        updateData.publishedAt = new Date();
        updateData.publishedBy = session.user.id;
      }
    }

    const page = await prisma.page.update({
      where: { id },
      data: updateData,
    });

    return NextResponse.json(page);
  } catch (error) {
    console.error("Error updating page:", error);
    return NextResponse.json(
      { error: "Failed to update page" },
      { status: 500 }
    );
  }
}

// DELETE /api/admin/pages/[id] - Sayfa sil
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await auth();

  if (!session?.user || session.user.type !== "SUPERADMIN") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await params;
    const page = await prisma.page.findUnique({
      where: { id },
    });

    if (!page) {
      return NextResponse.json({ error: "Page not found" }, { status: 404 });
    }

    if (page.isHomePage) {
      return NextResponse.json(
        { error: "Cannot delete home page. Set another page as home first." },
        { status: 400 }
      );
    }

    await prisma.page.delete({
      where: { id },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Error deleting page:", error);
    return NextResponse.json(
      { error: "Failed to delete page" },
      { status: 500 }
    );
  }
}

