import { NextRequest, NextResponse } from 'next/server';
import bcrypt from 'bcryptjs';
import { prisma } from "@/lib/prisma";

function generateSlug(name: string): string {
    return name
        .toLowerCase()
        .replace(/[çÇ]/g, 'c')
        .replace(/[ğĞ]/g, 'g')
        .replace(/[ıİ]/g, 'i')
        .replace(/[öÖ]/g, 'o')
        .replace(/[şŞ]/g, 's')
        .replace(/[üÜ]/g, 'u')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .substring(0, 60);
}

export async function POST(request: NextRequest) {
    try {
        const { email, password, firstName, lastName, company, phone, subdomain } = await request.json();

        // Validation
        if (!email || !password) {
            return NextResponse.json(
                { error: 'Email ve şifre gereklidir.' },
                { status: 400 }
            );
        }

        if (password.length < 8) {
            return NextResponse.json(
                { error: 'Şifre en az 8 karakter olmalıdır.' },
                { status: 400 }
            );
        }

        // Check if user already exists in database
        const existingUser = await prisma.user.findUnique({
            where: { email: email.toLowerCase().trim() },
        });

        if (existingUser) {
            return NextResponse.json(
                { error: 'Bu email adresi zaten kayıtlıdır.' },
                { status: 409 }
            );
        }

        // Hash password
        const hashedPassword = await bcrypt.hash(password, 12);

        // Create a NEW tenant for each registered user (multi-tenant SaaS)
        const tenantName = company || `${firstName || email.split('@')[0]}'in Mağazası`;
        const baseSlug = generateSlug(tenantName);

        // Ensure unique slug by appending random suffix if needed
        let slug = baseSlug;
        let slugExists = await prisma.tenant.findFirst({ where: { slug } });
        if (slugExists) {
            slug = `${baseSlug}-${Date.now().toString(36)}`;
        }

        // Use transaction to create tenant + admin role + user atomically
        const result = await prisma.$transaction(async (tx) => {
            // Create tenant
            const tenant = await tx.tenant.create({
                data: {
                    name: tenantName,
                    slug,
                    plan: 'FREE',
                    isOnboarded: false,
                },
            });

            // Create default ADMIN role for this tenant
            // Note: We use connectOrCreate for permissions to avoid duplicates if they exist, 
            // though implicit M-N usually handles this by creating new records in the join table.
            const adminRole = await tx.role.create({
                data: {
                    name: 'Admin',
                    description: 'Mağaza Yöneticisi - Tam Yetki',
                    tenantId: tenant.id,
                    isSystem: true,
                    permissions: {
                        create: [
                            { action: 'manage', resource: 'all' },
                        ],
                    },
                },
            });

            // Create user as ADMIN of their own tenant
            const user = await tx.user.create({
                data: {
                    email: email.toLowerCase().trim(),
                    password: hashedPassword,
                    firstName: firstName || email.split('@')[0],
                    lastName: lastName || '',
                    phone: phone || '',
                    type: 'ADMIN',
                    tenantId: tenant.id,
                    roleId: adminRole.id,
                    status: 'active',
                },
            });

            return { user, tenant };
        }, {
            timeout: 10000 // 10 seconds timeout for the transaction
        });

        return NextResponse.json(
            {
                success: true,
                message: 'Kayıt başarılı. Yönlendiriliyorsunuz...',
                email: result.user.email,
                tenantId: result.tenant.id,
            },
            { status: 201 }
        );
    } catch (error: any) {
        console.error('Register error details:', {
            message: error.message,
            stack: error.stack,
            code: error.code,
            meta: error.meta
        });

        // Check if it's a known Prisma error
        if (error.code === 'P2002') {
            const target = error.meta?.target || [];
            return NextResponse.json(
                { error: `Kayıt başarısız: ${target.join(', ')} alanı benzersiz olmalıdır.` },
                { status: 409 }
            );
        }

        return NextResponse.json(
            { error: error.message || 'Kayıt işlemi sırasında bir hata oluştu.' },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { auth } from "@/auth";

export async function GET(req: NextRequest) {
    try {
        const session = await auth();
        const tenantId = (session?.user as any)?.tenantId as string;
        if (!tenantId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const integrations = await prisma.integration.findMany({
            where: {
                tenantId,
                isActive: true
            }
        });

        // Hide secrets
        const safeIntegrations = integrations.map(int => ({
            id: int.id,
            platform: int.platform,
            apiKey: int.apiKey ? "********" : "",
            apiExtra: int.apiExtra,
            isActive: int.isActive,
            createdAt: int.createdAt,
            updatedAt: int.updatedAt,
        }));

        return NextResponse.json(safeIntegrations);
    } catch (error) {
        console.error("Error fetching integrations:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

export async function POST(req: NextRequest) {
    try {
        const session = await auth();
        const tenantId = (session?.user as any)?.tenantId as string;
        if (!tenantId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const body = await req.json();
        const { platform, apiKey, apiSecret, apiExtra } = body;

        if (!platform || !apiKey || !apiSecret) {
            return NextResponse.json({ error: "Platform, API Key and API Secret are required" }, { status: 400 });
        }

        // Check if integration already exists for this tenant and platform
        const existingIntegration = await prisma.integration.findFirst({
            where: {
                tenantId,
                platform: platform,
            }
        });

        if (existingIntegration) {
            // Update
            const updated = await prisma.integration.update({
                where: { id: existingIntegration.id },
                data: {
                    apiKey,
                    apiSecret,
                    apiExtra: apiExtra || {},
                    isActive: true,
                }
            });
            return NextResponse.json({ success: true, id: updated.id });
        }

        // Create
        const created = await prisma.integration.create({
            data: {
                tenantId,
                platform,
                apiKey,
                apiSecret,
                apiExtra: apiExtra || {},
                isActive: true,
            }
        });

        return NextResponse.json({ success: true, id: created.id }, { status: 201 });

    } catch (error) {
        console.error("Error saving integration:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

export async function DELETE(req: NextRequest) {
    try {
        const session = await auth();
        const tenantId = (session?.user as any)?.tenantId as string;
        if (!tenantId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { searchParams } = new URL(req.url);
        const id = searchParams.get('id');

        if (!id) {
            return NextResponse.json({ error: "Integration ID missing" }, { status: 400 });
        }

        await prisma.integration.delete({
            where: {
                id,
                tenantId, // ensure tenant owns it
            }
        });

        return NextResponse.json({ success: true });
    } catch (error) {
        console.error("Error deleting integration:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";

export async function POST(req: NextRequest) {
    try {
        const session = await auth();
        if (!(session?.user as any)?.tenantId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const body = await req.json();
        const { platform, credentials } = body;

        if (!platform || !credentials) {
            return NextResponse.json({ error: "Platform and credentials are required" }, { status: 400 });
        }

        let connectionSuccess = false;
        let message = "Bağlantı başarılı!";

        try {
            switch (platform.toLowerCase()) {
                case 'trendyol':
                    // Trendyol API connection test
                    const { supplierId, apiKey, apiSecret, isTestMode } = credentials;
                    if (!supplierId || !apiKey || !apiSecret) {
                        return NextResponse.json({ error: "Eksik Trendyol bilgileri" }, { status: 400 });
                    }

                    const trendyolAuth = Buffer.from(`${apiKey}:${apiSecret}`).toString("base64");
                    const baseUrl = isTestMode === 'true' || isTestMode === true
                        ? "https://stageapi.trendyol.com/sapigw"
                        : "https://api.trendyol.com/sapigw";

                    const trendyolRes = await fetch(`${baseUrl}/suppliers/${supplierId}/v2/products?size=1`, {
                        method: "GET",
                        headers: {
                            "Authorization": `Basic ${trendyolAuth}`,
                            "User-Agent": "PazarYonetimi/1.0",
                        },
                    });

                    if (trendyolRes.ok) {
                        connectionSuccess = true;
                        message = "Trendyol API bağlantısı başarılı! Satıcı ID doğrulandı.";
                    } else {
                        const errText = await trendyolRes.text();
                        console.error("Trendyol API Error:", trendyolRes.status, errText);
                        message = `Trendyol API Hatası: Geçersiz yetkilendirme bilgileri (HTTP ${trendyolRes.status}). Lütfen kontrol edip tekrar deneyin.`;
                        connectionSuccess = false;
                    }
                    break;

                case 'hepsiburada':
                    // Hepsiburada API connection test 
                    const hbUsername = credentials.username;
                    const hbPassword = credentials.password;
                    const merchantId = credentials.merchantId;

                    if (!hbUsername || !hbPassword || !merchantId) {
                        return NextResponse.json({ error: "Eksik Hepsiburada bilgileri" }, { status: 400 });
                    }

                    const hbAuth = Buffer.from(`${hbUsername}:${hbPassword}`).toString("base64");

                    const hbRes = await fetch(`https://oms-api.hepsiburada.com/merchants/${merchantId}`, {
                        method: "GET",
                        headers: {
                            "Authorization": `Basic ${hbAuth}`,
                            "Accept": "application/json",
                            "User-Agent": "PazarYonetimi/1.0",
                        }
                    });

                    if (hbRes.ok) {
                        connectionSuccess = true;
                        message = "Hepsiburada API bağlantısı başarılı!";
                    } else if (hbRes.status === 401 || hbRes.status === 403) {
                        message = "Hepsiburada API Hatası: Yetkisiz erişim. Bilgilerinizi kontrol edin.";
                        connectionSuccess = false;
                    } else {
                        connectionSuccess = false;
                        message = `Hepsiburada Hatası: HTTP ${hbRes.status}`;
                    }
                    break;

                default:
                    connectionSuccess = false;
                    message = `${platform} için API bağlantı testi henüz uygulanmadı.`;
                    break;
            }
        } catch (apiError: any) {
            console.error("API Fetch Error:", apiError);
            message = `Bağlantı sırasında bir hata oluştu: ${apiError.message || 'Bilinmeyen hata'}. API sunucuları yanıt vermiyor olabilir.`;
            connectionSuccess = false;
        }

        if (connectionSuccess) {
            return NextResponse.json({ success: true, message });
        } else {
            return NextResponse.json({ error: message, success: false }, { status: 400 });
        }

    } catch (error) {
        console.error("Error testing integration:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import * as cheerio from 'cheerio';

interface ScrapedStoreData {
    storeName: string;
    rating: number;
    followerCount: number;
    productCount: number;
    totalReviews?: number;
    platform?: string;
}

interface ScrapedProductData {
    title: string;
    price: number;
    images: string[];
    rating: number;
    reviewCount: number;
    stockStatus: boolean;
    sellerName?: string;
}

const userAgents = [
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
];

function getRandomUserAgent() {
    return userAgents[Math.floor(Math.random() * userAgents.length)];
}

async function fetchHtml(url: string): Promise<string | null> {
    try {
        const response = await fetch(url, {
            headers: {
                'User-Agent': getRandomUserAgent(),
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'tr-TR,tr;q=0.9,en-US;q=0.8,en;q=0.7',
            },
        });
        if (!response.ok) return null;
        return await response.text();
    } catch {
        return null;
    }
}

async function scrapeAmazonStore(url: string): Promise<ScrapedStoreData | null> {
    const html = await fetchHtml(url);
    if (!html) {
        console.log('[Scrape] No HTML returned from fetch');
        return null;
    }
    console.log(`[Scrape] HTML length: ${html.length}`);
    const $ = cheerio.load(html);

    // Try multiple selectors for store name
    const storeName = $('#bylineInfo').text().trim() ||
                     $('h1').text().trim() ||
                     $('.store-title').text().trim() ||
                     $('[data-testid="store-title"]').text().trim() ||
                     'Amazon Mağazası';

    const ratingText = $('.averageRating').text().trim() ||
                      $('.cr-widget-AverageCustomerRating').text().trim() ||
                      $('[data-hook="rating-out-of-text"]').text().trim();
    const rating = ratingText ? parseFloat(ratingText.replace(',', '.')) : 0;

    const productElements = $('[data-component-type="s-search-result"]');
    const productCount = productElements.length || 0;

    console.log(`[Scrape] Store: ${storeName}, Rating: ${rating}, Products: ${productCount}`);

    return {
        storeName: storeName.replace('Marka: ', '').replace('Ziyaret et: ', ''),
        rating,
        followerCount: 0,
        productCount,
        platform: 'AMAZON',
    };
}

async function scrapeAmazonProducts(url: string): Promise<ScrapedProductData[]> {
    const html = await fetchHtml(url);
    if (!html) return [];
    const $ = cheerio.load(html);
    const products: ScrapedProductData[] = [];

    $('[data-component-type="s-search-result"]').each((_, element) => {
        const $el = $(element);
        const title = $el.find('h2 a span').text().trim() ||
                     $el.find('[data-cy="title-recipe-title"]').text().trim() ||
                     'Ürün';
        const priceText = $el.find('.a-price-whole').text().trim() ||
                         $el.find('.a-price .a-offscreen').text().trim() ||
                         '0';
        const price = parseFloat(priceText.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
        const ratingText = $el.find('.a-icon-alt').text().trim();
        const rating = parseFloat(ratingText.replace(',', '.')) || 0;
        const reviewText = $el.find('.a-size-base').text().trim();
        const reviewCount = parseInt(reviewText.replace(/\D/g, '')) || 0;
        const imageUrl = $el.find('img').attr('src') || '';

        if (title && title !== 'Ürün') {
            products.push({
                title,
                price,
                images: imageUrl ? [imageUrl] : [],
                rating,
                reviewCount,
                stockStatus: true,
            });
        }
    });

    return products.slice(0, 20);
}

async function scrapeHepsiburadaStore(url: string): Promise<ScrapedStoreData | null> {
    const html = await fetchHtml(url);
    if (!html) {
        console.log('[Scrape] No HTML returned from Hepsiburada');
        return null;
    }
    console.log(`[Scrape] Hepsiburada HTML length: ${html.length}`);
