          userId: session.user.id,
          currentStep: "WELCOME",
          completedSteps: [],
          isActive: true,
          isCompleted: false,
        },
      });
    }

    return NextResponse.json(onboarding);
  } catch (error) {
    console.error("Error fetching onboarding:", error);
    return NextResponse.json(
      { error: "Failed to fetch onboarding status" },
      { status: 500 }
    );
  }
