                    { sku: { contains: search } },
                    { barcode: { contains: search } }
                ]
            },
            take: limit,
            orderBy: { updatedAt: 'desc' }
        });

        // Map Prisma DB structure to expected Frontend structure
        // Current UI components expect: id, name, sku, stock, price, status, marketplace
        const mappedProducts = products.map(p => ({
            id: p.id,
            name: p.title,
            sku: p.sku,
            barcode: p.barcode,
            stock: p.stock,
            price: Number(p.price),
            status: p.status, // active, draft, paused
            category: p.category,
            brand: p.brand,
            createdAt: p.createdAt,
            marketplace: "System" // We will map marketplace integrations in a future sprint, currently it's central DB.
        }));

        return NextResponse.json(mappedProducts);

    } catch (error) {
        console.error("Error fetching products:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import * as cheerio from 'cheerio';

export async function POST(request: NextRequest) {
    try {
        const { url } = await request.json();

        if (!url) {
            return NextResponse.json(
                { error: 'URL is required' },
                { status: 400 }
            );
        }

        // 1. Fetch the HTML
        const response = await fetch(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,image/apng,*/*;q=0.8',
                'Accept-Language': 'tr-TR,tr;q=0.9,en-US;q=0.8,en;q=0.7',
            },
        });

        if (!response.ok) {
            return NextResponse.json(
                { error: `Failed to fetch page: ${response.statusText}` },
                { status: response.status }
            );
        }

        const html = await response.text();
        const $ = cheerio.load(html);

        // 2. Extract Store Metadata
        let storeName = '';
        let rating = 0;
        let followers = 0;
        let logo = '';

        // Try to find the initial state JSON
        let merchantData: any = null;

        const tryParseJsObject = (text: string) => {
            // Find first brace and extract balanced object text
            const first = text.indexOf('{');
            if (first === -1) return null;
            let depth = 0;
            let end = -1;
            for (let i = first; i < text.length; i++) {
                const ch = text[i];
                if (ch === '{') depth++;
                else if (ch === '}') {
                    depth--;
                    if (depth === 0) { end = i; break; }
                }
            }
            if (end === -1) return null;
            const objText = text.slice(first, end + 1);

            // Try JSON.parse first
            try {
                return JSON.parse(objText);
            } catch (jsonErr) {
                // Fallback: try to evaluate JS object literal (may have unquoted keys)
                try {
                    // eslint-disable-next-line no-new-func
                    const fn = new Function('return (' + objText + ')');
                    return fn();
                } catch (evalErr) {
                    return null;
                }
            }
        };

        $('script').each((_, element) => {
            const content = $(element).html() || '';
            if (!content) return;

            if (content.includes('window.MCONTENT') || content.includes('MCONTENT')) {
                try {
                    // Try to extract object from the script block robustly
                    const parsed = tryParseJsObject(content);
                    if (parsed) {
                        // If structure is like Object.assign(..., { key: { STATE: ... } }) the parsed object may be the RHS
                        const keys = Object.keys(parsed || {});
                        if (keys.length > 0) {
                            const candidate = parsed[keys[0]]?.STATE || parsed[keys[0]] || parsed;
                            merchantData = candidate;
                        } else {
                            merchantData = parsed;
                        }
                    }
                } catch (e) {
                    console.error('Error parsing merchant script block:', e);
                }
            }
        });

        if (merchantData?.merchant) {
            storeName = merchantData.merchant.legalName || '';
            rating = merchantData.storeRating || 0;
        }

        // DOM Scraping Fallback for Store Info
        if (!storeName) {
            storeName = $('h1.merchant-name').text().trim() ||
                $('.merchant-page-header .title').text().trim() ||
                $('title').text().split('Mağazası')[0].trim();
        }

        if (rating === 0) {
            const ratingText = $('.merchant-rating .rating-score').text().trim() ||
                $('.merchant-header-rating').text().trim();
            rating = parseFloat(ratingText.replace(',', '.')) || 0;
        }

        // Followers - try to find text like "11.854 Takipçi" or similar
        const followersText = $('.merchant-followers').text().trim() ||
            $('div:contains("Takipçi")').last().text().trim();
        if (followersText) {
            const match = followersText.match(/([\d\.,]+)/);
            if (match) {
                followers = parseInt(match[1].replace(/\./g, '').replace(/,/g, '')) || 0;
            }
        }

        // Logo
        logo = $('.merchant-logo img').attr('src') || '';

        // 3. Extract Products
        const products: any[] = [];

        const extractFromMerchantData = (mData: any) => {
            if (!mData) return;
            if (mData.desktopRows) {
                Object.values(mData.desktopRows).forEach((row: any) => {
                    if (row.type === 'product' && row.data) {
                        const items = Array.isArray(row.data) ? row.data : (row.data.items || []);
                        items.forEach((item: any) => {
                            if (item.productId) {
                                products.push({
                                    id: item.productId,
                                    name: item.name,
                                    price: item.priceInfo?.price || 0,
                                    originalPrice: item.priceInfo?.originalPrice || item.priceInfo?.price || 0,
                                    rating: item.customerReviewRating || 0,
                                    reviewCount: item.customerReviewCount || 0,
                                    image: item.variantList?.[0]?.images?.[0]?.link?.replace('{size}', '500') || '',
                                    url: item.url && item.url.startsWith('http') ? item.url : `https://www.hepsiburada.com${item.url}`,
                                    category: item.mainCategory?.name || ''
                                });
                            }
                        });
                    }
                });
            }
        };

        extractFromMerchantData(merchantData);

        // If we didn't find product info via initial HTML+JSON, try a headless-rendered fallback
        if ((products.length === 0 || !merchantData) && typeof process !== 'undefined') {
            try {
                // Dynamically import playwright only when needed
                // eslint-disable-next-line @typescript-eslint/no-var-requires
                const playwright = await import('playwright');
                const browser = await playwright.chromium.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'], headless: true });
                const context = await browser.newContext({ userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36' });
                const page = await context.newPage();
                await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 }).catch(() => null);

                // Try to read a global variable used by Hepsiburada if present
                try {
                    const mcontent = await page.evaluate(() => {
                        const win = window as unknown as { MCONTENT?: { MERCHANTLAYOUT?: unknown } };
                        return win.MCONTENT?.MERCHANTLAYOUT || win.MCONTENT || null;
                    });
                    if (mcontent) {
                        // if evaluation returned an object, try extracting product rows
                        if (typeof mcontent === 'object' && mcontent !== null) {
                            // Cast to any to handle dynamic Hepsiburada structure safely in scraper
                            const normalized = mcontent as any;
                            const keys = Object.keys(normalized);
                            let targetData = normalized;
                            if (keys.length > 0 && normalized[keys[0]]?.STATE) {
                                targetData = normalized[keys[0]].STATE;
                            }
                            extractFromMerchantData(targetData);
                            if (products.length === 0 && targetData?.merchant) {
                                merchantData = targetData;
                            }
                        }
                    }
                } catch (e) {
                    // ignore
                }

                // If still no products, load rendered HTML and parse with cheerio
                if (products.length === 0) {
                    const renderedHtml = await page.content();
                    const $$ = cheerio.load(renderedHtml);

                    // Try to parse product cards from rendered DOM
                    $$('[data-testid="product-card"], .product-card, .search-item, .product-item, .product-list-item').each((_, el) => {
                        try {
                            const name = $$(el).find('h3, .title, .product-title').first().text().trim();
                            const link = $$(el).find('a').first().attr('href') || '';
                            const priceText = $$(el).find('.price, .current-price, .product-price').first().text().replace(/[₺,\.\s]/g, '').trim();
                            const price = parseFloat(priceText) || 0;
                            const img = $$(el).find('img').first().attr('src') || $$(el).find('img').first().attr('data-src') || '';
                            if (name) {
                                products.push({ id: link || name, name, price, image: img, url: link && link.startsWith('http') ? link : `https://www.hepsiburada.com${link}` });
                            }
                        } catch (e) { }
                    });
                }

                await browser.close();
            } catch (err) {
                console.warn('Playwright fallback failed or not installed:', err);
            }
        }

        // 4. Calculate Derived Metrics & Heuristics
        let titleScore = 0;
        let imageScore = 0;
        let priceScore = 0;
        const stockScore = 100; // Default active, can be adjusted if we detect OOS
        let estimatedTurnover = 0;

        if (products.length > 0) {
            // Title Optimization: Ideal length 50-120 chars
            const totalTitleLength = products.reduce((sum, p) => sum + (p.name?.length || 0), 0);
            const avgTitleLength = totalTitleLength / products.length;
            titleScore = Math.min(100, Math.max(0, (avgTitleLength >= 50 && avgTitleLength <= 120) ? 100 : 100 - Math.abs(85 - avgTitleLength)));

            // Image Optimization: Check for high-res images (we already prioritize high-res in scraping)
            // Heuristic: If we found images for all products, score is high.
            const productsWithImages = products.filter(p => p.image && !p.image.includes('default'));
            imageScore = Math.min(100, (productsWithImages.length / products.length) * 100);

            // Price Competitiveness: Variance check (heuristic). 
            // If prices end in .99 or .90, usually optimized.
            const optimizedPrices = products.filter(p => {
                const priceStr = p.price.toString();
                return priceStr.endsWith('9') || priceStr.endsWith('0'); // Simple heuristic
            });
            priceScore = Math.min(100, 50 + ((optimizedPrices.length / products.length) * 50));

            // Turnover Estimation (Heuristic based on reviews)
            // Avg Price * Review Count * Multiplier (assuming 1 review ~= 30-50 sales historically)
            const totalReviews = products.reduce((sum, p) => sum + (p.reviewCount || 0), 0);
            const avgPrice = products.reduce((sum, p) => sum + p.price, 0) / products.length;

            // Monthly turnover estimation heuristic
            // This is a rough guess: (Total Reviews / 12 months) * 40 sales/review * Avg Price
            // Capped/Floored to be realistic
            estimatedTurnover = Math.round((totalReviews / 12) * 40 * avgPrice);
            if (estimatedTurnover === 0 && products.length > 0) estimatedTurnover = 15000; // Minimum for active store
        }

        if (rating === 0 && products.length > 0) {
            const totalRating = products.reduce((sum, p) => sum + p.rating, 0);
            rating = Number((totalRating / products.length).toFixed(1));
        }

        return NextResponse.json({
            storeName: storeName || 'Hepsiburada Mağazası',
            rating,
            followers,
            products: products.slice(0, 50),
            totalProducts: products.length,
            logo,
            heuristics: {
                titleOptimization: Math.round(titleScore),
                imageOptimization: Math.round(imageScore),
                priceCompetitiveness: Math.round(priceScore),
                stockHealth: stockScore,
                estimatedTurnover
            }
        });

    } catch (error) {
        console.error('Hepsiburada Scraper Error:', error);
        return NextResponse.json(
            { error: 'Internal Server Error' },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';

interface TrendyolStoreData {
    storeName: string;
    storeId: string;
    rating: number;
    followers: string;
    followersCount: number;
    products: TrendyolProduct[];
    seoScore: number;
    keywords: string[];
    metrics: {
        storeName: string;
        rating: number;
        followers: number;
        monthlyTurnover: number;
        monthlyTraffic: number;
        responseTime: string;
        totalProducts: number;
        titleOptimization: number;
        imageOptimization: number;
        priceCompetitiveness: number;
        stockHealth: number;
        customerSatisfaction: number;
        responseScore: number;
    };
}

interface TrendyolProduct {
    name: string;
    price: number;
    originalPrice?: number;
    rating: number;
    reviews: number;
    favorites: string;
    stock: number;
    imageUrl?: string;
    hasDiscount: boolean;
    discountRate?: number;
}

// Trendyol API response types
interface TrendyolApiProduct {
    name?: string;
    title?: string;
    price?: {
        sellingPrice?: number;
        discountedPrice?: number;
        originalPrice?: number;
    };
    ratingScore?: {
        averageRating?: number;
        totalRatingCount?: number;
    };
    favoriteCount?: number;
    hasStock?: boolean;
    images?: Array<{ url?: string }>;
}

interface TrendyolApiResponse {
    result?: {
        products?: TrendyolApiProduct[];
        totalCount?: number;
    };
}

export async function POST(request: NextRequest) {
    try {
        const { url } = await request.json();

        if (!url || !url.includes('trendyol.com')) {
            return NextResponse.json({ error: 'Geçersiz Trendyol URL\'si' }, { status: 400 });
        }

        // URL'den mağaza bilgilerini çıkar
        const storeInfo = extractStoreInfo(url);

        // Trendyol public API'den veri çek
        const storeData = await fetchTrendyolStoreData(storeInfo);

        return NextResponse.json(storeData);
    } catch (error: any) {
        console.error('Trendyol scrape error:', error);
        return NextResponse.json(
            { error: error.message || 'Mağaza verileri çekilemedi. Lütfen URL\'yi kontrol edin.' },
            { status: 500 }
        );
    }
}

function extractStoreInfo(url: string): { storeName: string; storeSlug: string; storeId: string } {
    try {
        // Example URL: https://www.trendyol.com/magaza/daily-organics-m-1024688
        const match = url.match(/\/magaza\/([^/?]+)/);
        if (match) {
            const fullSlug = match[1];
            const parts = fullSlug.split('-');
            const storeId = parts.pop() || '';
            const mPart = parts.pop(); // Remove 'm' if exists
            const storeSlug = parts.join('-');
            const storeName = storeSlug
                .split('-')
                .map(word => word.charAt(0).toUpperCase() + word.slice(1))
                .join(' ');
            return { storeName, storeSlug, storeId };
        }
    } catch (e) {
        console.error('Store info extraction error:', e);
    }
    return { storeName: 'Mağaza', storeSlug: 'magaza', storeId: '' };
}

async function fetchTrendyolStoreData(storeInfo: { storeName: string; storeSlug: string; storeId: string }): Promise<TrendyolStoreData> {
    const { storeSlug, storeId } = storeInfo;

    // Trendyol public search API endpoint
    const sellerApiUrl = `https://public.trendyol.com/discovery-web-searchgw-service/v2/api/infinite-scroll/sr?mid=${storeId}&os=1&sk=1&sst=BEST_SELLER&pi=1&culture=tr-TR&userGenderId=1&pId=0&scoringAlgorithmId=2&categoryRelevancyEnabled=false&isLegalRequirementConfirmed=false&searchStrategyType=DEFAULT&productStampType=TypeA`;

    const response = await fetch(sellerApiUrl, {
        headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Accept': 'application/json',
            'Accept-Language': 'tr-TR,tr;q=0.9',
            'Origin': 'https://www.trendyol.com',
            'Referer': `https://www.trendyol.com/magaza/${storeSlug}-m-${storeId}`,
        },
        cache: 'no-store',
    });

    if (!response.ok) {
        throw new Error(`Trendyol API hatası: ${response.status}. Mağaza bilgilerine ulaşılamıyor.`);
    }

    const data = await response.json();

    if (!data?.result || !data.result.products || data.result.products.length === 0) {
        throw new Error('Mağaza bulundu ancak ürün listesi boş veya erişilemez durumda.');
    }

    return parseApiResponse(data, storeInfo);
}

function parseApiResponse(data: TrendyolApiResponse, storeInfo: { storeName: string; storeSlug: string; storeId: string }): TrendyolStoreData {
    const products = data?.result?.products || [];
    const totalCount = data?.result?.totalCount || 0;

    // Parse real products
    const parsedProducts: TrendyolProduct[] = products.slice(0, 10).map((p: TrendyolApiProduct) => ({
        name: p.name || p.title || 'İsimsiz Ürün',
        price: p.price?.sellingPrice || p.price?.discountedPrice || p.price?.originalPrice || 0,
        originalPrice: p.price?.originalPrice,
        rating: p.ratingScore?.averageRating || 0,
        reviews: p.ratingScore?.totalRatingCount || 0,
        favorites: formatNumber(p.favoriteCount || 0),
        stock: p.hasStock ? 1 : 0,
        imageUrl: p.images?.[0]?.url,
        hasDiscount: (p.price?.discountedPrice || 0) < (p.price?.originalPrice || 0),
        discountRate: p.price?.discountedPrice && p.price?.originalPrice
            ? Math.round((1 - p.price.discountedPrice / p.price.originalPrice) * 100)
            : 0,
    }));

    // Calculate aggregated metrics from real data
    const activeProducts = parsedProducts.filter(p => p.rating > 0);
    const avgRating = activeProducts.length > 0
        ? activeProducts.reduce((sum, p) => sum + p.rating, 0) / activeProducts.length
        : 0;

    const totalSampleReviews = parsedProducts.reduce((sum, p) => sum + p.reviews, 0);

    const monthlyTurnover = 0;
    const monthlyTraffic = 0;

    // Extract real keywords from product names
    const keywords = extractKeywords(parsedProducts);

    // Calculate SEO score based on real product titles, images, and ratings
    const seoScore = calculateSEOScore(avgRating, totalSampleReviews, totalCount, parsedProducts);

    return {
        storeName: storeInfo.storeName,
        storeId: storeInfo.storeId,
        rating: Math.round(avgRating * 10) / 10,
        followers: formatNumber(0),
        followersCount: 0,
        products: parsedProducts,
        seoScore,
        keywords,
        metrics: {
            storeName: storeInfo.storeName,
            rating: Math.round(avgRating * 10) / 10,
            followers: 0,
            monthlyTurnover,
            monthlyTraffic,
            responseTime: 'Veri yok',
            totalProducts: totalCount,
            titleOptimization: calculateTitleScore(parsedProducts),
            imageOptimization: calculateImageScore(parsedProducts),
            priceCompetitiveness: calculatePriceScore(parsedProducts),
            stockHealth: calculateStockHealth(parsedProducts),
            customerSatisfaction: Math.round(avgRating * 20),
            responseScore: 0,
        },
    };
}

function extractKeywords(products: TrendyolProduct[]): string[] {
    const wordFreq: Record<string, number> = {};
    const stopWords = new Set(['ve', 'veya', 'için', '-', 'ile', 'en', 'çok', 'bir', 'bu', 'da', 'de', 'ml', 'gr', 'adet', 'paket', 'set']);

    products.forEach(p => {
        const words = p.name.toLocaleLowerCase('tr-TR')
            .replace(/[^\w\sğüşöçı]/g, ' ')
            .split(/\s+/)
            .filter(w => w.length > 2 && !stopWords.has(w));

        words.forEach(w => {
            wordFreq[w] = (wordFreq[w] || 0) + 1;
        });
    });

    return Object.entries(wordFreq)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 6)
        .map(([word]) => word.charAt(0).toUpperCase() + word.slice(1));
}

function calculateSEOScore(rating: number, reviews: number, totalProducts: number, products: TrendyolProduct[]): number {
    let score = 50; // Base score

    // Rating contribution (max +20)
    score += (rating / 5) * 20;

    // Review density (max +15)
    const reviewFactor = Math.min(reviews / 5000, 1);
    score += reviewFactor * 15;

    // Product variety (max +10)
    const varietyFactor = Math.min(totalProducts / 100, 1);
    score += varietyFactor * 10;

    // Title optimization contribution (max +5)
    const titleScore = calculateTitleScore(products);
    score += (titleScore / 100) * 5;

    return Math.min(Math.round(score), 99);
}

function calculateTitleScore(products: TrendyolProduct[]): number {
    if (products.length === 0) return 0;

    let totalScore = 0;
    products.forEach(p => {
        let s = 0;
        const len = p.name.length;
        // Ideal title length for Trendyol SEO is 50-100 characters
        if (len >= 50 && len <= 100) s += 40;
        else if (len >= 30 && len <= 150) s += 25;
        else s += 10;

        // Keywords check (sample)
        if (p.name.includes(' ') && p.name.split(' ').length >= 4) s += 30;

        // Brand/Model check (sample)
        if (/[A-Z]/.test(p.name)) s += 30;

        totalScore += s;
    });

    return Math.round(totalScore / products.length);
}

function calculatePriceScore(products: TrendyolProduct[]): number {
    if (products.length === 0) return 0;

    const discountedCount = products.filter(p => p.hasDiscount).length;
    const avgDiscount = products.reduce((s, p) => s + (p.discountRate || 0), 0) / products.length;

    // Having discounts improves price competitiveness score
    return Math.min(Math.round(65 + (discountedCount / products.length) * 20 + avgDiscount / 3), 98);
}

function calculateStockHealth(products: TrendyolProduct[]): number {
    if (products.length === 0) return 0;
    const inStock = products.filter(p => p.stock > 0).length;
    return Math.round((inStock / products.length) * 100);
}

function calculateImageScore(products: TrendyolProduct[]): number {
    if (products.length === 0) return 0;
    const withImage = products.filter(p => Boolean(p.imageUrl)).length;
    return Math.round((withImage / products.length) * 100);
}

function formatNumber(num: number): string {
    if (num >= 1000000) return `${(num / 1000000).toFixed(1)}M`;
    if (num >= 1000) return `${(num / 1000).toFixed(1)}B`;
    return num.toString();
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { auth } from "@/auth";

export async function POST() {
    try {
        const session = await auth();
        const tenantId = (session?.user as any)?.tenantId as string;

        if (!tenantId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        // Fetch all active integrations for this tenant
        const integrations = await prisma.integration.findMany({
            where: {
                tenantId,
                isActive: true
            }
        });

        if (integrations.length === 0) {
            return NextResponse.json({
                success: true,
                message: "Senkronize edilecek aktif bir pazaryeri bağlantısı bulunamadı.",
                syncedCount: 0
            });
        }

        let totalSynced = 0;
        const results = [];

        for (const integration of integrations) {
            try {
                if (integration.platform === 'TRENDYOL') {
                    const extra = integration.apiExtra as any;
                    const supplierId = extra?.supplierId || extra?.merchantId;

                    if (!supplierId || !integration.apiKey || !integration.apiSecret) {
                        results.push({ platform: 'TRENDYOL', status: 'error', error: 'Eksik API bilgileri' });
                        continue;
                    }

                    const trendyolAuth = Buffer.from(`${integration.apiKey}:${integration.apiSecret}`).toString("base64");

                    // Fetch recent orders from Trendyol
                    const startDate = Date.now() - (7 * 24 * 60 * 60 * 1000); // 7 days ago

                    const response = await fetch(`https://api.trendyol.com/sapigw/suppliers/${supplierId}/orders?startDate=${startDate}&size=50`, {
                        method: "GET",
                        headers: {
                            "Authorization": `Basic ${trendyolAuth}`,
                            "User-Agent": "PazarYonetimi/1.0",
                        }
                    });

                    if (response.ok) {
                        const data = await response.json();
                        const orders = data.content || [];

                        for (const order of orders) {
                            // Upsert each order
                            const existingOrder = await prisma.order.findFirst({
                                where: {
                                    tenantId,
                                    marketplaceOrderId: order.orderNumber.toString(),
                                    platform: 'TRENDYOL'
                                }
                            });

                            if (!existingOrder) {
                                // Create new order
                                await prisma.order.create({
                                    data: {
                                        tenantId,
                                        platform: 'TRENDYOL',
                                        marketplaceOrderId: order.orderNumber.toString(),
                                        customerName: `${order.shipmentAddress.firstName} ${order.shipmentAddress.lastName}`,
                                        customerEmail: order.customerEmail || '',
                                        shippingAddress: order.shipmentAddress.fullAddress || '',
                                        billingAddress: order.invoiceAddress.fullAddress || '',
                                        totalAmount: order.totalPrice || 0,
                                        taxAmount: 0,
                                        status: 'CONFIRMED', // simplifying mapping for demo
                                        paymentStatus: 'PAID',
                                        orderDate: new Date(order.orderDate),
                                    }
                                });
                            }
                        }

                        totalSynced += orders.length;
                        results.push({ platform: 'TRENDYOL', status: 'success', count: orders.length });
                    } else {
                        results.push({ platform: 'TRENDYOL', status: 'error', error: `HTTP ${response.status}` });
                    }
                } else if (integration.platform === 'HEPSIBURADA') {
                    results.push({ platform: 'HEPSIBURADA', status: 'skipped', error: 'Order sync endpoint mevcut degil' });
                }
            } catch (err: any) {
                console.error(`Order Sync error for ${integration.platform}:`, err);
                results.push({ platform: integration.platform, status: 'error', error: err.message });
            }
        }

        return NextResponse.json({
            success: true,
            message: `${totalSynced} sipariş başarıyla senkronize edildi.`,
            syncedCount: totalSynced,
            results
        });

    } catch (error) {
        console.error("Error syncing orders:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { auth } from "@/auth";

export async function POST() {
    try {
        const session = await auth();
        const tenantId = (session?.user as any)?.tenantId as string;

        if (!tenantId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        // Fetch all active integrations for this tenant
        const integrations = await prisma.integration.findMany({
            where: {
                tenantId,
                isActive: true
            }
        });

        if (integrations.length === 0) {
            return NextResponse.json({
                success: true,
                message: "Senkronize edilecek aktif bir pazaryeri bağlantısı bulunamadı.",
                syncedCount: 0
            });
        }

        let totalSynced = 0;
        const results = [];

        for (const integration of integrations) {
            try {
                if (integration.platform === 'TRENDYOL') {
                    const extra = integration.apiExtra as any;
                    const supplierId = extra?.supplierId || extra?.merchantId;

                    if (!supplierId || !integration.apiKey || !integration.apiSecret) {
                        results.push({ platform: 'TRENDYOL', status: 'error', error: 'Eksik API bilgileri' });
                        continue;
                    }

                    const trendyolAuth = Buffer.from(`${integration.apiKey}:${integration.apiSecret}`).toString("base64");
                    // Fetch real products from Trendyol
                    const response = await fetch(`https://api.trendyol.com/sapigw/suppliers/${supplierId}/v2/products?size=50`, {
                        method: "GET",
                        headers: {
                            "Authorization": `Basic ${trendyolAuth}`,
                            "User-Agent": "PazarYonetimi/1.0",
                        }
                    });

                    if (response.ok) {
                        const data = await response.json();
                        const products = data.content || [];

                        for (const product of products) {
                            // Upsert each product into our local database
                            const localProduct = await prisma.product.findFirst({
                                where: {
                                    tenantId,
                                    sku: product.stockCode || product.barcode
                                }
                            });

                            if (localProduct) {
                                // Update existing
                                await prisma.product.update({
                                    where: { id: localProduct.id },
                                    data: {
                                        title: product.title,
                                        price: product.salePrice || product.listPrice || 0,
                                        stock: product.quantity || 0,
                                        brand: product.brand,
                                        barcode: product.barcode,
                                        category: product.categoryName,
                                        updatedAt: new Date()
                                    }
                                });
                            } else {
                                // Create new
                                await prisma.product.create({
                                    data: {
                                        tenantId,
                                        title: product.title || 'İsimsiz Ürün',
                                        sku: product.stockCode || product.barcode || `TY-${Date.now()}`,
                                        barcode: product.barcode,
                                        price: product.salePrice || product.listPrice || 0,
                                        stock: product.quantity || 0,
                                        brand: product.brand,
                                        category: product.categoryName,
                                        status: product.approved ? 'active' : 'draft',
                                    }
                                });
                            }
                        }

                        totalSynced += products.length;
                        results.push({ platform: 'TRENDYOL', status: 'success', count: products.length });

                        // Update integration lastSync timestamp using the 'updatedAt' field implicitly
                        await prisma.integration.update({
                            where: { id: integration.id },
                            data: { isActive: true }
                        });
                    } else {
                        results.push({ platform: 'TRENDYOL', status: 'error', error: `HTTP ${response.status}` });
                    }
                } else if (integration.platform === 'HEPSIBURADA') {
                    results.push({ platform: 'HEPSIBURADA', status: 'skipped', error: 'Product sync endpoint mevcut degil' });
                } else {
                    results.push({ platform: integration.platform, status: 'skipped', error: 'Unimplemented platform sync' });
                }
            } catch (err: any) {
                console.error(`Sync error for ${integration.platform}:`, err);
                results.push({ platform: integration.platform, status: 'error', error: err.message });
            }
        }

        return NextResponse.json({
            success: true,
            message: `${totalSynced} ürün başarıyla senkronize edildi.`,
            syncedCount: totalSynced,
            results
        });

    } catch (error) {
        console.error("Error syncing products:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from "@/lib/prisma";
import { auth } from '../../../../auth';

export async function POST(request: NextRequest) {
    try {
        const session = await auth();
        if (!session?.user) {
            return NextResponse.json({ error: 'Yetkilendirme gerekli.' }, { status: 401 });
        }

        const user = session.user as any;
        const tenantId = user.tenantId;

        if (!tenantId) {
            return NextResponse.json({ error: 'Tenant bilgisi bulunamadı.' }, { status: 400 });
        }

        const body = await request.json();

        // Verify the tenant belongs to the current user
        const tenant = await prisma.tenant.findUnique({
            where: { id: tenantId },
        });

        if (!tenant) {
            return NextResponse.json({ error: 'Tenant bulunamadı.' }, { status: 404 });
        }

        // 1. Update tenant with company information
        await prisma.tenant.update({
            where: { id: tenantId },
            data: {
                name: body.companyName || tenant.name,
                taxOffice: body.taxOffice || null,
                taxNumber: body.taxNumber || null,
                companyType: body.companyType || null,
                address: body.address || null,
                city: body.city || null,
                district: body.district || null,
                postcode: body.postcode || null,
                phone: body.phone || null,
                isOnboarded: true,
            },
        });

        // 2. Create integrations for selected platforms
        const selectedPlatforms: string[] = body.selectedPlatforms || [];
        for (const platform of selectedPlatforms) {
            const existing = await prisma.integration.findFirst({
                where: { tenantId, platform: platform as any },
            });
            if (!existing) {
                await prisma.integration.create({
                    data: {
                        tenantId,
                        platform: platform as any,
                        isActive: false, // User needs to add API keys later
                        apiKey: '',
                        apiSecret: '',
                    },
                });
            }
        }

        // 3. Record selected shipping/payment preferences
        const selectedShipping: string[] = body.selectedShipping || [];
        const selectedPayment: string[] = body.selectedPayment || [];
        const allServices = [...selectedShipping, ...selectedPayment];

        for (const serviceType of allServices) {
            const existing = await prisma.serviceCredential.findFirst({
                where: { tenantId, serviceType: serviceType as any },
            });
            if (!existing) {
                await prisma.serviceCredential.create({
                    data: {
                        tenantId,
                        serviceType: serviceType as any,
                        apiKey: '',
                        isActive: false,
                    },
                });
            }
        }

        return NextResponse.json({
            success: true,
            message: 'Kurulum tamamlandı.',
        });
    } catch (error) {
        console.error('Onboarding error:', error);
        return NextResponse.json(
            { error: 'Kurulum sırasında bir hata oluştu.' },
            { status: 500 }
        );
    }
}

"use client";

