              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.1 }}
              className="bg-slate-100 dark:bg-slate-900/50 backdrop-blur-sm border border-slate-200 dark:border-slate-800 rounded-2xl p-4"
            >
              <div className="text-2xl font-bold text-foreground">{stat.value}</div>
              <div className="text-sm text-slate-600 dark:text-slate-400">{stat.label}</div>
            </motion.div>
          ))}
        </div>

        {/* Filters */}
        <div className="flex flex-col md:flex-row gap-4 mb-6">
          {/* Search */}
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input
              type="text"
              placeholder="Aktivitelerde ara..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-100 dark:bg-slate-900/50 border border-slate-300 dark:border-slate-800 rounded-xl text-foreground placeholder-slate-500 dark:placeholder-slate-400 focus:outline-none focus:border-purple-500 transition-colors"
            />
          </div>

          {/* Type Filter */}
          <div className="relative">
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value as ActivityLog['type'] | 'all')}
              className="appearance-none px-4 py-3 pr-10 bg-slate-900/50 border border-slate-800 rounded-xl text-white focus:outline-none focus:border-purple-500 transition-colors cursor-pointer"
            >
              <option value="all">Tüm İşlemler</option>
              {Object.entries(typeConfig).map(([key, config]) => (
                <option key={key} value={key}>{config.label}</option>
              ))}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>

          {/* Module Filter */}
          <div className="relative">
            <select
              value={moduleFilter}
              onChange={(e) => setModuleFilter(e.target.value as ActivityLog['module'] | 'all')}
              className="appearance-none px-4 py-3 pr-10 bg-slate-900/50 border border-slate-800 rounded-xl text-white focus:outline-none focus:border-purple-500 transition-colors cursor-pointer"
            >
              <option value="all">Tüm Modüller</option>
              {Object.entries(moduleConfig).map(([key, config]) => (
                <option key={key} value={key}>{config.label}</option>
              ))}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>

          {/* Date Range */}
          <div className="relative">
            <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <select
              className="appearance-none pl-10 pr-10 py-3 bg-slate-900/50 border border-slate-800 rounded-xl text-white focus:outline-none focus:border-purple-500 transition-colors cursor-pointer"
            >
              <option value="today">Bugün</option>
              <option value="week">Bu Hafta</option>
              <option value="month">Bu Ay</option>
              <option value="all">Tümü</option>
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
        </div>

        {/* Activity Timeline */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-3">
            <AnimatePresence>
              {filteredLogs.map((log, index) => {
                const TypeIcon = typeConfig[log.type as keyof typeof typeConfig]?.icon ?? Activity;
                const ModuleIcon = moduleConfig[log.module as keyof typeof moduleConfig]?.icon ?? Activity;

                return (
                  <motion.div
                    key={log.id}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ delay: index * 0.05 }}
                    onClick={() => setSelectedLog(log)}
                    className={`group cursor-pointer bg-white dark:bg-slate-900/50 backdrop-blur-sm border rounded-2xl p-4 transition-all hover:border-purple-500/30 ${selectedLog?.id === log.id ? 'border-purple-500' : 'border-slate-300 dark:border-slate-800'
                      }`}
                  >
                    <div className="flex items-start gap-4">
                      {/* Timeline dot */}
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${typeConfig[log.type as keyof typeof typeConfig]?.color ?? 'bg-slate-500'}`}>
                        <TypeIcon className="w-5 h-5" />
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-medium text-foreground">{log.title}</h3>
                          <div className="flex items-center gap-1 px-2 py-0.5 bg-slate-200 dark:bg-slate-800 rounded-lg text-xs text-slate-600 dark:text-slate-400">
                            <ModuleIcon className="w-3 h-3" />
                            {moduleConfig[log.module as keyof typeof moduleConfig]?.label ?? log.module}
                          </div>
                        </div>
                        <p className="text-slate-600 dark:text-slate-400 text-sm">{log.description}</p>

                        <div className="flex items-center gap-4 mt-2">
                          <span className="flex items-center gap-1 text-xs text-slate-500">
                            <User className="w-3 h-3" />
                            {log.user.name}
                          </span>
                          <span className="flex items-center gap-1 text-xs text-slate-500">
                            <Clock className="w-3 h-3" />
                            {formatTime(log.timestamp)}
                          </span>
                          {log.ip && (
                            <span className="flex items-center gap-1 text-xs text-slate-500">
                              <Globe className="w-3 h-3" />
                              {log.ip}
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Arrow */}
                      <ArrowUpRight className="w-4 h-4 text-slate-600 group-hover:text-purple-400 transition-colors" />
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>

          {/* Detail Panel */}
          <div className="lg:col-span-1">
            <AnimatePresence mode="wait">
              {selectedLog ? (
                <motion.div
                  key={selectedLog.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  className="sticky top-6 bg-white dark:bg-slate-900/50 backdrop-blur-sm border border-slate-300 dark:border-slate-800 rounded-2xl p-6"
                >
                  <h3 className="text-lg font-semibold text-foreground mb-4">Detaylar</h3>

                  <div className="space-y-4">
                    {/* Activity Info */}
                    <div className="space-y-3">
                      <div>
                        <label className="text-xs text-slate-600 dark:text-slate-500 uppercase tracking-wide">İşlem</label>
                        <div className="flex items-center gap-2 mt-1">
                          <div className={`w-6 h-6 rounded-lg flex items-center justify-center ${typeConfig[selectedLog.type].color}`}>
                            {(() => {
                              const Icon = typeConfig[selectedLog.type].icon;
                              return <Icon className="w-3 h-3" />;
                            })()}
                          </div>
                          <span className="text-foreground">{typeConfig[selectedLog.type].label}</span>
                        </div>
                      </div>

                      <div>
                        <label className="text-xs text-slate-500 uppercase tracking-wide">Modül</label>
                        <div className="flex items-center gap-2 mt-1">
                          {(() => {
                            const Icon = moduleConfig[selectedLog.module].icon;
                            return <Icon className="w-4 h-4 text-slate-400" />;
                          })()}
                          <span className="text-white">{moduleConfig[selectedLog.module].label}</span>
                        </div>
                      </div>

                      <div>
                        <label className="text-xs text-slate-500 uppercase tracking-wide">Kullanıcı</label>
                        <div className="mt-1">
                          <div className="text-white">{selectedLog.user.name}</div>
                          <div className="text-sm text-slate-400">{selectedLog.user.email}</div>
                        </div>
                      </div>

                      <div>
                        <label className="text-xs text-slate-500 uppercase tracking-wide">Zaman</label>
                        <div className="text-white mt-1">
                          {selectedLog.timestamp.toLocaleString('tr-TR')}
                        </div>
                      </div>

                      {selectedLog.ip && (
                        <div>
                          <label className="text-xs text-slate-500 uppercase tracking-wide">IP Adresi</label>
                          <div className="text-white mt-1">{selectedLog.ip}</div>
                        </div>
                      )}

                      {selectedLog.userAgent && (
                        <div>
                          <label className="text-xs text-slate-500 uppercase tracking-wide">Tarayıcı</label>
                          <div className="text-white mt-1">{selectedLog.userAgent}</div>
                        </div>
                      )}
                    </div>

                    {/* Metadata */}
                    {selectedLog.metadata && (
                      <div>
                        <label className="text-xs text-slate-500 uppercase tracking-wide">Ek Bilgiler</label>
                        <div className="mt-2 bg-slate-800/50 rounded-xl p-3">
                          <pre className="text-xs text-slate-300 overflow-x-auto">
                            {JSON.stringify(selectedLog.metadata, null, 2)}
                          </pre>
                        </div>
                      </div>
                    )}
                  </div>
                </motion.div>
              ) : (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="sticky top-6 bg-white dark:bg-slate-900/50 backdrop-blur-sm border border-slate-300 dark:border-slate-800 rounded-2xl p-6 flex flex-col items-center justify-center text-center"
                  style={{ minHeight: '300px' }}
                >
                  <FileText className="w-12 h-12 text-slate-400 dark:text-slate-600 mb-3" />
                  <h3 className="text-lg font-medium text-slate-600 dark:text-slate-400">Detay Seçilmedi</h3>
                  <p className="text-sm text-slate-500 dark:text-slate-500 mt-1">
                    Detayları görmek için bir aktivite seçin
                  </p>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Megaphone, TrendingUp, BarChart3, Target,
    Zap, Plus, Filter, Search, MoreVertical,
    CheckCircle2, AlertTriangle, Clock, MousePointer2,
    Eye, ShoppingBag, ArrowUpRight, ArrowDownRight,
    RefreshCw, Play, Pause, Trash2, DollarSign
} from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface Campaign {
    id: string;
    name: string;
    platform: 'Trendyol' | 'Hepsiburada' | 'Amazon' | 'N11';
    type: 'Search' | 'Display' | 'Product';
    status: 'active' | 'paused' | 'ended' | 'scheduled';
    budget: number;
    spent: number;
    roas: number;
    ctr: number;
    impressions: number;
    clicks: number;
    sales: number;
    startDate: string;
    endDate?: string;
}

export default function AdCampaignsPage() {
    const [searchQuery, setSearchQuery] = useState('');
    const [loading, setLoading] = useState(true);
    const [campaigns, setCampaigns] = useState<Campaign[]>([]);
    const [filterPlatform, setFilterPlatform] = useState('all');

    useEffect(() => {
        const fetchCampaigns = async () => {
            setLoading(true);
            try {
                const data = await apiClient.getCampaigns() as any[];
                const normalized: Campaign[] = Array.isArray(data)
                    ? data.map((c, i) => ({
                        id: String(c.id ?? i + 1),
                        name: c.name,
                        platform: (Array.isArray(c.platforms) && c.platforms[0]) || c.platform || 'Trendyol',
                        type: c.type || 'Search',
                        status: c.status === 'completed' ? 'ended' : (c.status || 'paused'),
                        budget: Number(c.budget || 0),
                        spent: Number(c.spent || 0),
                        roas: Number(c.roas || 0),
                        ctr: Number(c.ctr || 0),
                        impressions: Number(c.impressions || 0),
                        clicks: Number(c.clicks || 0),
                        sales: Number(c.conversions || c.sales || 0),
                        startDate: c.startDate || '',
                        endDate: c.endDate,
                    }))
                    : [];
                setCampaigns(normalized);
            } catch {
                setCampaigns([]);
            }
            setLoading(false);
        };
        fetchCampaigns();
    }, []);

    const filteredCampaigns = campaigns.filter(c =>
        (filterPlatform === 'all' || c.platform === filterPlatform) &&
        c.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const stats = {
        totalSpent: campaigns.reduce((acc, c) => acc + c.spent, 0),
        avgRoas: campaigns.filter(c => c.roas > 0).length > 0
            ? campaigns.filter(c => c.roas > 0).reduce((acc, c, _, arr) => acc + (c.roas / arr.length), 0)
            : 0,
        totalClicks: campaigns.reduce((acc, c) => acc + c.clicks, 0),
        totalSales: campaigns.reduce((acc, c) => acc + c.sales, 0),
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="flex flex-col items-center gap-4">
                    <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin" />
                    <p className="text-slate-500 font-medium">Reklam verileri analiz ediliyor...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground flex items-center gap-3">
                        <Megaphone className="w-8 h-8 text-orange-500" /> Reklam Kampanyaları
                    </h1>
                    <p className="text-slate-500 mt-1 font-medium">Bütçenizi yönetin ve reklam yatırım getirinizi (ROAS) artırın</p>
                </div>
                <button className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold transition-all shadow-lg shadow-indigo-600/20">
                    <Plus size={18} /> Yeni Kampanya Oluştur
                </button>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Harcama', value: `₺${stats.totalSpent.toLocaleString('tr-TR')}`, icon: DollarSign, color: 'text-blue-500', trend: '+12%', up: true },
                    { label: 'Ortalama ROAS', value: `${stats.avgRoas.toFixed(1)}x`, icon: TrendingUp, color: 'text-emerald-500', trend: '+0.5', up: true },
                    { label: 'Toplam Tıklama', value: stats.totalClicks.toLocaleString('tr-TR'), icon: MousePointer2, color: 'text-purple-500', trend: '-2%', up: false },
                    { label: 'Reklam Kaynaklı Satış', value: stats.totalSales.toLocaleString('tr-TR'), icon: ShoppingBag, color: 'text-orange-500', trend: '+8', up: true },
                ].map((stat, i) => (
                    <motion.div
                        key={stat.label}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: i * 0.1 }}
                        className="bg-surface rounded-2xl border border-border p-5"
                    >
                        <div className="flex items-center justify-between mb-2">
                            <stat.icon size={20} className={stat.color} />
                            <div className={`flex items-center text-[10px] font-black px-1.5 py-0.5 rounded ${stat.up ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
                                {stat.up ? <ArrowUpRight size={10} className="mr-0.5" /> : <ArrowDownRight size={10} className="mr-0.5" />}
                                {stat.trend}
                            </div>
                        </div>
                        <div className="text-2xl font-black text-foreground">{stat.value}</div>
                        <div className="text-xs text-slate-500 font-bold mt-1 uppercase tracking-tight">{stat.label}</div>
                    </motion.div>
                ))}
            </div>

            {/* Filters */}
            <div className="bg-surface p-4 rounded-2xl border border-border flex flex-col md:flex-row gap-4">
                <div className="flex-1 relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input
                        type="text"
                        placeholder="Kampanya adı ara..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-background border border-border rounded-xl py-2.5 pl-10 pr-4 text-sm text-foreground focus:outline-none focus:border-indigo-500/50"
                    />
                </div>
                <div className="flex gap-2">
                    <select
                        value={filterPlatform}
                        onChange={(e) => setFilterPlatform(e.target.value)}
                        className="bg-background border border-border rounded-xl px-4 py-2 text-sm font-bold text-foreground focus:outline-none"
                    >
                        <option value="all">Tüm Platformlar</option>
                        <option value="Trendyol">Trendyol</option>
                        <option value="Hepsiburada">Hepsiburada</option>
                        <option value="Amazon">Amazon</option>
                        <option value="N11">N11</option>
                    </select>
                    <button className="flex items-center gap-2 px-4 py-2 bg-background border border-border rounded-xl text-sm font-bold text-slate-600 hover:text-foreground transition-all">
                        <Filter size={16} /> Filtreler
                    </button>
                </div>
            </div>

            {/* Campaigns Table */}
            <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="bg-background/50 border-b border-border text-[10px] font-black text-slate-500 uppercase tracking-widest">
                                <th className="px-6 py-4 text-left">Kampanya</th>
                                <th className="px-6 py-4 text-left">Durum</th>
                                <th className="px-6 py-4 text-right">Bütçe</th>
                                <th className="px-6 py-4 text-right">Harcama</th>
                                <th className="px-6 py-4 text-right">ROAS</th>
                                <th className="px-6 py-4 text-right">Tıklama/CTR</th>
                                <th className="px-6 py-4 text-right">İşlemler</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {filteredCampaigns.length === 0 && (
                                <tr>
                                    <td className="px-6 py-6 text-sm text-slate-500" colSpan={7}>Reklam kampanya verisi bulunamadı</td>
                                </tr>
                            )}
                            {filteredCampaigns.map((c) => (
                                <tr key={c.id} className="hover:bg-background/20 transition-all group">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-indigo-500/10 flex items-center justify-center text-indigo-500 font-black text-[10px]">
                                                {c.platform[0]}
                                            </div>
                                            <div>
                                                <div className="text-sm font-bold text-foreground">{c.name}</div>
                                                <div className="text-[10px] text-slate-500 font-bold uppercase">{c.platform} • {c.type}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className={`w-2 h-2 rounded-full ${c.status === 'active' ? 'bg-emerald-500' :
                                                c.status === 'paused' ? 'bg-amber-500' : 'bg-slate-400'
                                                }`} />
                                            <span className="text-xs font-black uppercase tracking-tighter text-slate-500">
                                                {c.status === 'active' ? 'AKTİF' : c.status === 'paused' ? 'DURAKLATILDI' : 'TAMAMLANDI'}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="text-sm font-bold text-foreground">₺{c.budget.toLocaleString('tr-TR')}</div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="text-sm font-bold text-foreground">₺{c.spent.toLocaleString('tr-TR')}</div>
                                        <div className="w-20 ml-auto h-1.5 bg-background rounded-full mt-1 overflow-hidden">
                                            <div className="h-full bg-indigo-500" style={{ width: `${(c.spent / c.budget) * 100}%` }} />
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className={`text-sm font-black ${c.roas >= 4 ? 'text-emerald-500' : 'text-slate-500'}`}>
                                            {c.roas > 0 ? `${c.roas.toFixed(1)}x` : '-'}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="text-sm font-bold text-foreground">{c.clicks.toLocaleString('tr-TR')}</div>
                                        <div className="text-[10px] text-slate-500">%{c.ctr.toFixed(1)} CTR</div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex items-center justify-end gap-2 outline-none">
                                            {c.status === 'active' ? (
                                                <button className="p-2 hover:bg-amber-500/10 text-amber-500 rounded-lg transition-all" title="Duraklat">
                                                    <Pause size={14} />
                                                </button>
                                            ) : (
                                                <button className="p-2 hover:bg-emerald-500/10 text-emerald-500 rounded-lg transition-all" title="Başlat">
                                                    <Play size={14} />
                                                </button>
                                            )}
                                            <button className="p-2 hover:bg-red-500/10 text-red-500 rounded-lg transition-all">
                                                <Trash2 size={14} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* AI Insights */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-gradient-to-br from-indigo-600 to-purple-600 rounded-2xl p-6 text-white shadow-xl shadow-indigo-600/20 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-8 opacity-10">
                        <Zap size={120} />
                    </div>
                    <div className="relative z-10 space-y-4">
                        <div className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-indigo-100">
                            <Zap size={14} /> AI Optimizasyon Önerisi
                        </div>
                        <h3 className="text-xl font-black">&quot;Prime Day&quot; Kampanyanızı Ölçeklendirin</h3>
                        <p className="text-indigo-100/90 text-sm font-medium leading-relaxed">
                            Amazon&apos;daki Prime Day hazırlık kampanyanızıb ROAS değeri beklentilerin %40 üzerinde. Bütçeyi ₺5.000 artırmak tahmini ₺32.000 ek satış getirebilir.
                        </p>
                        <button className="px-6 py-2.5 bg-white text-indigo-600 font-black rounded-lg text-sm hover:scale-105 transition-all shadow-lg active:scale-95">
                            Hemen Uygula
                        </button>
                    </div>
                </div>

                <div className="bg-surface rounded-2xl border border-border p-6 space-y-4 shadow-sm">
                    <h3 className="font-bold text-foreground flex items-center gap-2">
                        <Target size={18} className="text-orange-500" /> Kanallara Göre Performans
                    </h3>
                    <div className="space-y-4">
                        {[
                            { name: 'Trendyol', val: 65, color: 'bg-orange-500' },
                            { name: 'Hepsiburada', val: 42, color: 'bg-blue-500' },
                            { name: 'Amazon', val: 88, color: 'bg-indigo-500' },
                            { name: 'N11', val: 24, color: 'bg-red-500' },
                        ].map(platform => (
                            <div key={platform.name} className="space-y-1.5">
                                <div className="flex justify-between text-[10px] font-black text-slate-500">
                                    <span>{platform.name}</span>
                                    <span>%{platform.val} VERİMLİLİK</span>
                                </div>
                                <div className="h-1.5 bg-background rounded-full overflow-hidden">
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${platform.val}%` }}
                                        className={`h-full ${platform.color}`}
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Brain,
    Sparkles,
    TrendingUp,
    TrendingDown,
    Target,
    Lightbulb,
    AlertTriangle,
    CheckCircle,
    ArrowRight,
    Zap,
    BarChart3,
    PieChart,
    LineChart,
    RefreshCw,
    ChevronDown,
    ChevronRight,
    MessageSquare,
    Send,
    Bot,
    User,
    Clock,
    DollarSign,
    Package,
    ShoppingBag,
    Star,
    ThumbsUp,
    ThumbsDown,
    Loader2
} from 'lucide-react';
import { 
    useAiRecommendations, 
    usePerformanceScores, 
    useAiChat,
    AiRecommendation,
    PerformanceScores 
} from '@/lib/hooks';

const quickPrompts = [
    "Satışlarımı nasıl artırabilirim?",
    "Hangi ürünlerimi öne çıkarmalıyım?",
    "Rakip analizi yap",
    "Fiyat optimizasyonu öner"
];

const getIconForType = (type: string) => {
    switch (type) {
        case 'pricing': return <DollarSign size={20} />;
        case 'stock': return <Package size={20} />;
        case 'trend': return <TrendingUp size={20} />;
        case 'seo': return <Target size={20} />;
        case 'competitor': return <BarChart3 size={20} />;
        case 'marketing': return <Sparkles size={20} />;
        default: return <Lightbulb size={20} />;
    }
};

export default function AIAdvisorPage() {
    const { messages, isTyping, sendMessage, clearChat } = useAiChat();
    const [inputMessage, setInputMessage] = useState('');
    const messagesEndRef = useRef<HTMLDivElement>(null);
    
    // Gerçek veriler
    const { data: recommendations, loading: recsLoading, error: recsError, refetch: refetchRecs } = useAiRecommendations();
    const { data: scores, loading: scoresLoading, error: scoresError, refetch: refetchScores } = usePerformanceScores();

    // Scroll to bottom when messages change
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const handleSendMessage = (text: string) => {
        if (!text.trim()) return;
        sendMessage(text);
        setInputMessage('');
    };

    const handleRefresh = async () => {
        await Promise.all([refetchRecs(), refetchScores()]);
    };

    const getPriorityColor = (priority: string) => {
        switch (priority) {
            case 'critical': return 'border-red-500/30 bg-red-500/5';
            case 'high': return 'border-orange-500/30 bg-orange-500/5';
            case 'medium': return 'border-yellow-500/30 bg-yellow-500/5';
            default: return 'border-border bg-surface';
        }
    };

    const getPriorityBadge = (priority: string) => {
        switch (priority) {
            case 'critical': return <span className="px-2 py-1 rounded-lg text-[10px] font-bold bg-red-500/10 text-red-500 border border-red-500/20">KRİTİK</span>;
            case 'high': return <span className="px-2 py-1 rounded-lg text-[10px] font-bold bg-orange-500/10 text-orange-500 border border-orange-500/20">YÜKSEK</span>;
            case 'medium': return <span className="px-2 py-1 rounded-lg text-[10px] font-bold bg-yellow-500/10 text-yellow-500 border border-yellow-500/20">ORTA</span>;
            default: return null;
        }
    };

    // Performance insights from real data
    const performanceInsights = scores ? [
        { label: "Genel Skor", value: scores.overall, change: +5, trend: scores.overall >= 70 ? "up" : "down" },
        { label: "SEO Skoru", value: scores.seo, change: -3, trend: scores.seo >= 60 ? "up" : "down" },
        { label: "Fiyat Rekabeti", value: scores.pricing, change: +8, trend: "up" },
        { label: "Stok Sağlığı", value: scores.stockHealth, change: -12, trend: scores.stockHealth >= 60 ? "up" : "down" }
    ] : [];

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <div className="flex items-center gap-2 mb-1">
                        <h1 className="text-3xl font-black text-foreground tracking-tight">AI Danışman</h1>
                        <span className="px-2 py-1 rounded-lg text-xs font-bold bg-gradient-to-r from-purple-500 to-pink-500 text-white">PRO</span>
                    </div>
                    <p className="text-slate-500 font-medium">Yapay zeka destekli satış optimizasyonu ve öneriler</p>
                </div>
                <div className="flex items-center gap-3">
                    <button 
                        onClick={handleRefresh}
                        disabled={recsLoading || scoresLoading}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all disabled:opacity-50"
                    >
                        <RefreshCw size={16} className={recsLoading || scoresLoading ? 'animate-spin' : ''} /> 
                        Yeniden Analiz Et
                    </button>
                </div>
            </div>

            {/* Performance Scores */}
            {scoresLoading ? (
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                    {[1, 2, 3, 4].map((i) => (
                        <div key={i} className="bg-surface p-4 rounded-2xl border border-border animate-pulse">
                            <div className="h-4 w-20 bg-slate-200 dark:bg-slate-700 rounded mb-2"></div>
                            <div className="h-8 w-16 bg-slate-200 dark:bg-slate-700 rounded mb-2"></div>
                            <div className="h-2 bg-slate-200 dark:bg-slate-700 rounded"></div>
                        </div>
                    ))}
                </div>
            ) : scoresError ? (
                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-4 text-red-600 dark:text-red-400">
                    Performans skorları yüklenemedi. Lütfen tekrar deneyin.
                </div>
            ) : (
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                    {performanceInsights.map((insight, idx) => (
                        <motion.div
                            key={insight.label}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: idx * 0.1 }}
                            className="bg-surface p-4 rounded-2xl border border-border"
                        >
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-xs text-slate-500 font-medium">{insight.label}</span>
                                <div className={`flex items-center gap-1 text-xs font-bold ${insight.trend === 'up' ? 'text-green-500' : 'text-red-500'}`}>
                                    {insight.trend === 'up' ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
                                    {insight.change >= 0 ? '+' : ''}{insight.change}
                                </div>
                            </div>
                            <div className="text-2xl font-black text-foreground mb-2">{insight.value}</div>
                            <div className="h-2 bg-background rounded-full overflow-hidden">
                                <motion.div
                                    initial={{ width: 0 }}
                                    animate={{ width: `${insight.value}%` }}
                                    transition={{ delay: idx * 0.1 + 0.3, duration: 0.5 }}
                                    className={`h-full ${insight.value >= 80 ? 'bg-green-500' : insight.value >= 60 ? 'bg-yellow-500' : 'bg-red-500'}`}
                            />
                        </div>
                    </motion.div>
                ))}
            </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* AI Recommendations */}
                <div className="lg:col-span-2 space-y-4">
                    <h3 className="font-bold text-foreground flex items-center gap-2">
                        <Sparkles size={18} className="text-primary" />
                        AI Önerileri
                        {recommendations && (
                            <span className="text-xs text-slate-500 font-normal">
                                ({recommendations.length} öneri)
                            </span>
                        )}
                    </h3>
                    
                    {recsLoading ? (
                        <div className="space-y-4">
                            {[1, 2, 3].map((i) => (
                                <div key={i} className="rounded-2xl border border-border p-5 animate-pulse">
                                    <div className="flex items-start gap-4">
                                        <div className="w-12 h-12 bg-slate-200 dark:bg-slate-700 rounded-xl"></div>
                                        <div className="flex-1">
                                            <div className="h-5 w-40 bg-slate-200 dark:bg-slate-700 rounded mb-2"></div>
                                            <div className="h-4 w-full bg-slate-200 dark:bg-slate-700 rounded mb-3"></div>
                                            <div className="h-4 w-3/4 bg-slate-200 dark:bg-slate-700 rounded"></div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : recsError ? (
                        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-4 text-red-600 dark:text-red-400">
                            Öneriler yüklenemedi. Lütfen tekrar deneyin.
                        </div>
                    ) : recommendations && recommendations.length > 0 ? (
                        recommendations.map((rec: AiRecommendation, idx: number) => (
                            <motion.div
                                key={rec.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: idx * 0.1 }}
                                className={`rounded-2xl border p-5 ${getPriorityColor(rec.priority)}`}
                            >
                                <div className="flex items-start gap-4">
                                    <div className={`p-3 rounded-xl ${
                                        rec.priority === 'critical' ? 'bg-red-500/10 text-red-500' :
                                        rec.priority === 'high' ? 'bg-orange-500/10 text-orange-500' :
                                        'bg-yellow-500/10 text-yellow-500'
                                    }`}>
                                        {getIconForType(rec.type)}
                                    </div>
                                    <div className="flex-1">
                                        <div className="flex items-center gap-2 mb-1">
                                            <h4 className="font-bold text-foreground">{rec.title}</h4>
                                            {getPriorityBadge(rec.priority)}
                                        </div>
                                        <p className="text-sm text-slate-500 mb-3">{rec.description}</p>
                                        <div className="flex items-center justify-between flex-wrap gap-2">
                                            <div className="flex items-center gap-4">
                                                <div className="flex items-center gap-1">
                                                    <Zap size={14} className="text-green-500" />
                                                    <span className="text-sm font-bold text-green-500">{rec.impact}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <Target size={14} className="text-slate-400" />
                                                    <span className="text-xs text-slate-500">Güven: %{rec.confidence}</span>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                {rec.actions.map((action: string, i: number) => (
                                                    <button
                                                        key={i}
                                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                                                            i === 0 
                                                                ? 'bg-primary text-white hover:bg-primary/90' 
                                                                : 'bg-background border border-border text-foreground hover:bg-surface'
                                                        }`}
                                                    >
                                                        {action}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        ))
                    ) : (
                        <div className="bg-surface border border-border rounded-2xl p-8 text-center">
                            <CheckCircle className="w-12 h-12 text-green-500 mx-auto mb-3" />
                            <h4 className="font-bold text-foreground mb-2">Harika! Her şey yolunda</h4>
                            <p className="text-sm text-slate-500">
                                Şu an için acil bir öneri bulunmuyor. Sistem sürekli olarak mağazanızı analiz ediyor.
                            </p>
                        </div>
                    )}
                </div>

                {/* AI Chat */}
                <div className="bg-surface rounded-2xl border border-border flex flex-col h-[600px]">
                    <div className="p-4 border-b border-border flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500">
                                <Bot size={18} className="text-white" />
                            </div>
                            <div>
                                <div className="font-bold text-foreground text-sm">AI Asistan</div>
                                <div className="flex items-center gap-1 text-xs text-green-500">
                                    <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                                    Çevrimiçi
                                </div>
                            </div>
                        </div>
                        <button 
                            onClick={clearChat}
                            className="text-xs text-slate-500 hover:text-foreground transition-colors"
                        >
                            Temizle
                        </button>
                    </div>

                    {/* Messages */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-4">
                        {messages.map((msg, idx) => (
                            <motion.div
                                key={idx}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                            >
                                <div className={`max-w-[85%] p-3 rounded-2xl ${
                                    msg.role === 'user' 
                                        ? 'bg-primary text-white rounded-br-none' 
                                        : 'bg-background border border-border rounded-bl-none'
                                }`}>
                                    <p className="text-sm whitespace-pre-line">{msg.content}</p>
                                </div>
                            </motion.div>
                        ))}
                        {isTyping && (
                            <div className="flex justify-start">
                                <div className="bg-background border border-border p-3 rounded-2xl rounded-bl-none">
                                    <div className="flex gap-1">
                                        <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce"></span>
                                        <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '0.1s' }}></span>
                                        <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                                    </div>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    {/* Quick Prompts */}
                    <div className="px-4 pb-2">
                        <div className="flex flex-wrap gap-2">
                            {quickPrompts.map((prompt, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => handleSendMessage(prompt)}
                                    className="px-3 py-1.5 bg-background border border-border rounded-full text-xs text-slate-500 hover:text-foreground hover:border-primary/50 transition-all"
                                >
                                    {prompt}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Input */}
                    <div className="p-4 border-t border-border">
                        <div className="flex items-center gap-2">
                            <input
                                type="text"
                                value={inputMessage}
                                onChange={(e) => setInputMessage(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage(inputMessage)}
                                placeholder="Bir soru sorun..."
                                disabled={isTyping}
                                className="flex-1 bg-background border border-border rounded-xl px-4 py-2.5 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:border-primary/50 disabled:opacity-50"
                            />
                            <button
                                onClick={() => handleSendMessage(inputMessage)}
                                disabled={!inputMessage.trim() || isTyping}
                                className="p-2.5 bg-primary text-white rounded-xl hover:bg-primary/90 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isTyping ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Bot, Send, Sparkles, RotateCcw, Copy, ThumbsUp, ThumbsDown,
    MessageSquare, Package, TrendingUp, HelpCircle, Zap, Loader2
} from 'lucide-react';

interface ChatMessage {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    timestamp: Date;
    suggestions?: string[];
}

const SUGGESTED_QUESTIONS = [
    { icon: Package, text: 'En çok satan ürünlerim hangileri?', category: 'Ürünler' },
    { icon: TrendingUp, text: 'Bu ayki satış trendim nasıl?', category: 'Analiz' },
    { icon: HelpCircle, text: 'Stoku azalan ürünlerimi göster', category: 'Stok' },
    { icon: Zap, text: 'Kârlılığımı nasıl artırabilirim?', category: 'Strateji' },
];

export default function AIChatbotPage() {
    const [messages, setMessages] = useState<ChatMessage[]>([
        {
            id: '1',
            role: 'assistant',
            content: 'Merhaba! 👋 Ben PazarYönetimi AI asistanınızım. Satışlarınız, ürünleriniz, stok durumu ve stratejiler hakkında sorular sorabilirsiniz. Size nasıl yardımcı olabilirim?',
            timestamp: new Date(),
            suggestions: SUGGESTED_QUESTIONS.map(q => q.text),
        },
    ]);
    const [input, setInput] = useState('');
    const [isTyping, setIsTyping] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const sendMessage = async (text?: string) => {
        const msgText = text || input;
        if (!msgText.trim()) return;

        const baseTime = 1704110400000; // 2024-01-01 12:00:00
        const userMsg: ChatMessage = {
            id: `u${baseTime + messages.length}`,
            role: 'user',
            content: msgText,
            timestamp: new Date(),
        };
        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setIsTyping(true);

        try {
            const res = await fetch('/api/ai/copilot/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-tenant-id': 'default' },
                body: JSON.stringify({ message: msgText, context: '/dashboard/ai-assistant' }),
            });

            if (!res.ok) {
                const errorData = await res.json().catch(() => ({}));
                throw new Error(errorData?.error || 'Copilot backend kullanilamiyor');
            }

            const data = await res.json();
            const aiMsg: ChatMessage = {
                id: `a${baseTime + messages.length + 1}`,
                role: 'assistant',
                content: data.message || 'Yanit alinamadi',
                timestamp: new Date(),
                suggestions: Array.isArray(data.suggestions) ? data.suggestions : [],
            };
            setMessages(prev => [...prev, aiMsg]);
        } catch (error: any) {
            const aiMsg: ChatMessage = {
                id: `a${baseTime + messages.length + 1}`,
                role: 'assistant',
                content: error?.message || 'Copilot servisine baglanilamadi',
                timestamp: new Date(),
                suggestions: [],
            };
            setMessages(prev => [...prev, aiMsg]);
        } finally {
            setIsTyping(false);
        }
    };

    const copyMessage = (text: string) => {
        navigator.clipboard.writeText(text);
    };

    return (
        <div className="h-[calc(100vh-8rem)] flex flex-col animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex items-center justify-between mb-4">
                <div>
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <div className="p-2 bg-gradient-to-br from-purple-500 to-pink-500 rounded-xl">
                            <Bot className="w-6 h-6 text-white" />
                        </div>
                        AI Asistan
                    </h1>
                    <p className="text-slate-500 mt-1">Verileriniz hakkında sorular sorun, analizler isteyin</p>
                </div>
                <button
                    onClick={() => setMessages([messages[0]])}
                    className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-sm text-slate-300 hover:text-foreground transition-colors"
                >
                    <RotateCcw className="w-4 h-4" />
                    Yeni Sohbet
                </button>
            </div>

            {/* Chat */}
            <div className="flex-1 bg-surface rounded-2xl border border-border flex flex-col overflow-hidden">
                {/* Messages */}
                <div className="flex-1 overflow-y-auto p-6 space-y-6">
                    {messages.map(msg => (
                        <motion.div
                            key={msg.id}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                        >
                            <div className={`max-w-[80%] ${msg.role === 'user' ? '' : ''}`}>
                                <div className="flex items-start gap-3">
                                    {msg.role === 'assistant' && (
                                        <div className="p-2 bg-gradient-to-br from-purple-500 to-pink-500 rounded-xl flex-shrink-0">
                                            <Sparkles className="w-4 h-4 text-white" />
                                        </div>
                                    )}
                                    <div>
                                        <div className={`px-4 py-3 rounded-2xl ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-br-md' : 'bg-background text-foreground rounded-bl-md'}`}>
                                            <div className="text-sm whitespace-pre-wrap leading-relaxed">{msg.content}</div>
                                        </div>
                                        <div className="flex items-center gap-2 mt-1.5 px-1">
                                            <span className="text-[10px] text-slate-500">{msg.timestamp.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })}</span>
                                            {msg.role === 'assistant' && (
                                                <>
                                                    <button onClick={() => copyMessage(msg.content)} className="p-1 hover:bg-background rounded text-slate-500 hover:text-foreground"><Copy className="w-3 h-3" /></button>
                                                    <button className="p-1 hover:bg-background rounded text-slate-500 hover:text-emerald-400"><ThumbsUp className="w-3 h-3" /></button>
                                                    <button className="p-1 hover:bg-background rounded text-slate-500 hover:text-red-400"><ThumbsDown className="w-3 h-3" /></button>
                                                </>
                                            )}
                                        </div>
                                        {/* Suggestions */}
                                        {msg.suggestions && (
                                            <div className="flex flex-wrap gap-2 mt-3">
                                                {msg.suggestions.map((s, i) => (
                                                    <button
                                                        key={i}
                                                        onClick={() => sendMessage(s)}
                                                        className="px-3 py-1.5 text-xs bg-background rounded-full text-slate-300 hover:bg-indigo-500/20 hover:text-indigo-400 transition-colors border border-border"
                                                    >
                                                        {s}
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </motion.div>
                    ))}

                    {isTyping && (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex items-start gap-3">
                            <div className="p-2 bg-gradient-to-br from-purple-500 to-pink-500 rounded-xl">
                                <Sparkles className="w-4 h-4 text-white" />
                            </div>
                            <div className="px-4 py-3 bg-background rounded-2xl rounded-bl-md">
                                <div className="flex items-center gap-2">
                                    <Loader2 className="w-4 h-4 text-indigo-400 animate-spin" />
                                    <span className="text-sm text-slate-400">Analiz ediliyor...</span>
                                </div>
                            </div>
                        </motion.div>
                    )}
                    <div ref={messagesEndRef} />
                </div>

                {/* Quick Questions */}
                {messages.length <= 1 && (
                    <div className="px-6 pb-4">
                        <div className="grid grid-cols-2 gap-3">
