    const mockProcessedImage = 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=800&q=80'; // Clean shoe image
    const finalTitle = 'Premium Erkek Koşu Ayakkabısı - CloudWalker X1';
