                                            <p className="text-slate-500 font-medium">{imageStatus}</p>
                                        </div>
                                    ) : null}

                                    <img 
                                        src={!isProcessingImage ? mockProcessedImage : selectedImage!} 
                                        alt="Processing" 
                                        className="w-full h-full object-cover" 
                                    />

                                    {/* Scanline effect during processing */}
                                    {isProcessingImage && (
                                        <motion.div 
