                                >
                                    <action.icon className="w-5 h-5" />
                                    <span className="text-sm font-medium">{action.name}</span>
                                </motion.button>
                            ))}
                        </div>
                    </div>

                    {/* Recent Operations */}
                    <div className="bg-surface rounded-2xl p-4 border border-border">
                        <h3 className="text-lg font-bold text-foreground mb-4">Son İşlemler</h3>
                        <div className="space-y-3">
                            {recentOperations.map((op) => (
                                <div key={op.id} className="p-3 bg-background rounded-xl border border-border">
                                    <div className="flex items-center justify-between mb-1">
                                        <span className="text-sm font-medium text-foreground">{op.action}</span>
                                        <span className={`text-xs px-2 py-0.5 rounded-full ${
                                            op.status === 'completed'
                                                ? 'bg-green-500/20 text-green-400'
                                                : op.status === 'processing'
                                                ? 'bg-yellow-500/20 text-yellow-400'
                                                : 'bg-red-500/20 text-red-400'
                                        }`}>
                                            {op.status === 'completed' ? 'Tamamlandı' : op.status === 'processing' ? 'İşleniyor' : 'Başarısız'}
                                        </span>
                                    </div>
                                    <div className="text-xs text-slate-500">
                                        {op.products} ürün • {op.date}
                                    </div>
                                    <div className="flex items-center gap-2 mt-2 text-xs">
                                        <span className="text-green-400">✓ {op.success}</span>
                                        {op.failed > 0 && <span className="text-red-400">✗ {op.failed}</span>}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </motion.div>

                {/* Products Table */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="lg:col-span-3 bg-surface rounded-2xl border border-border overflow-hidden"
                >
                    {/* Search and Filters */}
                    <div className="p-4 border-b border-border">
                        <div className="flex items-center gap-4">
                            <div className="flex-1 relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
                                <input
                                    type="text"
                                    placeholder="Ürün ara (isim veya SKU)..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 bg-background rounded-xl text-foreground placeholder-slate-500 border border-border focus:border-indigo-500 focus:outline-none"
                                />
                            </div>
                            <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-slate-600 dark:text-slate-300 hover:text-foreground transition-colors">
                                <RefreshCw className="w-4 h-4" />
                                Yenile
                            </button>
                        </div>
                    </div>

                    {/* Selection Bar */}
                    {selectedProducts.length > 0 && (
                        <motion.div
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 'auto' }}
                            className="px-4 py-3 bg-indigo-500/10 border-b border-indigo-500/30"
                        >
                            <div className="flex items-center justify-between">
                                <span className="text-sm text-indigo-600 dark:text-indigo-300">
                                    <strong>{selectedProducts.length}</strong> ürün seçildi
                                </span>
                                <button
                                    onClick={() => setSelectedProducts([])}
                                    className="text-sm text-indigo-400 hover:text-indigo-300"
                                >
                                    Seçimi Temizle
                                </button>
                            </div>
                        </motion.div>
                    )}

                    {/* Table */}
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-slate-200 dark:bg-slate-800/50">
                                <tr>
                                    <th className="w-12 p-4">
                                        <input
                                            type="checkbox"
                                            checked={selectedProducts.length === products.length}
                                            onChange={toggleAll}
                                            className="w-4 h-4 rounded border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-indigo-500 focus:ring-indigo-500"
                                        />
                                    </th>
                                    <th className="text-left p-4 text-slate-500 text-sm font-bold">Ürün</th>
                                    <th className="text-left p-4 text-slate-500 text-sm font-bold">SKU</th>
                                    <th className="text-right p-4 text-slate-500 text-sm font-bold">Fiyat</th>
                                    <th className="text-right p-4 text-slate-500 text-sm font-bold">Stok</th>
                                    <th className="text-center p-4 text-slate-500 text-sm font-bold">Durum</th>
                                    <th className="text-center p-4 text-slate-500 text-sm font-bold">Platformlar</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {filteredProducts.map((product) => (
                                    <tr
                                        key={product.id}
                                        className={`hover:bg-background/50 transition-colors ${
                                            selectedProducts.includes(product.id) ? 'bg-indigo-500/10' : ''
                                        }`}
                                    >
                                        <td className="p-4">
                                            <input
                                                type="checkbox"
                                                checked={selectedProducts.includes(product.id)}
                                                onChange={() => toggleProduct(product.id)}
                                                className="w-4 h-4 rounded border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-indigo-500 focus:ring-indigo-500"
                                            />
                                        </td>
                                        <td className="p-4">
                                            <span className="text-foreground font-medium">{product.name}</span>
                                        </td>
                                        <td className="p-4">
                                            <span className="text-slate-500 text-sm font-mono">{product.sku}</span>
                                        </td>
                                        <td className="p-4 text-right">
                                            <span className="text-foreground">₺{product.price.toFixed(2)}</span>
                                        </td>
                                        <td className="p-4 text-right">
                                            <span className={`${product.stock < 100 ? 'text-yellow-600 dark:text-yellow-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                                {product.stock}
                                            </span>
                                        </td>
                                        <td className="p-4 text-center">
                                            <span className={`px-2 py-1 rounded-full text-xs font-bold border ${
                                                product.status === 'active'
                                                    ? 'bg-green-500/10 text-green-600 dark:text-green-400 border-green-500/20'
                                                    : product.status === 'paused'
                                                    ? 'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400 border-yellow-500/20'
                                                    : 'bg-slate-500/10 text-slate-600 dark:text-slate-400 border-slate-500/20'
                                            }`}>
                                                {product.status === 'active' ? 'Aktif' : product.status === 'paused' ? 'Pasif' : 'Taslak'}
                                            </span>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex items-center justify-center gap-1">
                                                {product.platforms.map((platform: string) => (
                                                    <span
                                                        key={platform}
                                                        className="px-2 py-0.5 bg-background rounded text-xs text-slate-500 capitalize border border-border"
                                                    >
                                                        {platform.charAt(0).toUpperCase()}
                                                    </span>
                                                ))}
                                                {product.platforms.length === 0 && (
                                                    <span className="text-xs text-slate-400">-</span>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </motion.div>
            </div>

            {/* Action Modal */}
            {showActionModal && selectedAction && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl p-6 w-full max-w-md border border-border"
                    >
                        <h3 className="text-xl font-bold text-foreground mb-4">
                            {bulkActions.find(a => a.id === selectedAction)?.name}
                        </h3>
                        <p className="text-slate-500 text-sm mb-6">
                            {selectedProducts.length} ürün için işlem uygulanacak.
                        </p>

                        {(selectedAction === 'price-update' || selectedAction === 'discount') && (
                            <div className="space-y-4">
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => setActionType('percent')}
                                        className={`flex-1 py-2 rounded-lg text-sm font-medium transition-colors ${
                                            actionType === 'percent'
                                                ? 'bg-indigo-600 text-white'
                                                : 'bg-background text-slate-500 border border-border'
                                        }`}
                                    >
                                        Yüzde (%)
                                    </button>
                                    <button
                                        onClick={() => setActionType('fixed')}
                                        className={`flex-1 py-2 rounded-lg text-sm font-medium transition-colors ${
                                            actionType === 'fixed'
                                                ? 'bg-indigo-600 text-white'
                                                : 'bg-background text-slate-500 border border-border'
                                        }`}
                                    >
                                        Sabit Tutar (₺)
                                    </button>
                                </div>
                                <div className="relative">
                                    <input
                                        type="number"
                                        value={actionValue}
                                        onChange={(e) => setActionValue(e.target.value)}
                                        placeholder={actionType === 'percent' ? 'Örn: 10' : 'Örn: 25.00'}
                                        className="w-full px-4 py-3 bg-background rounded-xl text-foreground placeholder-slate-500 border border-border focus:border-indigo-500 focus:outline-none"
                                    />
                                    <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500">
                                        {actionType === 'percent' ? '%' : '₺'}
                                    </span>
                                </div>
                            </div>
                        )}

                        {selectedAction === 'stock-update' && (
                            <div className="relative">
                                <input
                                    type="number"
                                    value={actionValue}
                                    onChange={(e) => setActionValue(e.target.value)}
                                    placeholder="Yeni stok miktarı"
                                    className="w-full px-4 py-3 bg-background rounded-xl text-foreground placeholder-slate-500 border border-border focus:border-indigo-500 focus:outline-none"
                                />
                            </div>
                        )}

                        {(selectedAction === 'activate' || selectedAction === 'pause' || selectedAction === 'duplicate' || selectedAction === 'delete') && (
                            <div className="p-4 bg-background rounded-xl border border-border">
                                <p className="text-sm text-slate-600 dark:text-slate-300">
                                    {selectedAction === 'activate' && 'Seçili ürünler aktif hale getirilecek ve tüm platformlarda görünür olacak.'}
                                    {selectedAction === 'pause' && 'Seçili ürünler geçici olarak pasifleştirilecek. Satışlar duracak.'}
                                    {selectedAction === 'duplicate' && 'Seçili ürünlerin kopyaları oluşturulacak. Yeni ürünler taslak olarak kaydedilecek.'}
                                    {selectedAction === 'delete' && '⚠️ Seçili ürünler kalıcı olarak silinecek. Bu işlem geri alınamaz!'}
                                </p>
                            </div>
                        )}

                        <div className="flex items-center gap-3 mt-6">
                            <button
                                onClick={() => setShowActionModal(false)}
                                className="flex-1 py-2 bg-background rounded-lg text-slate-600 dark:text-slate-300 hover:text-foreground transition-colors border border-border"
                            >
                                İptal
                            </button>
                            <button
                                onClick={executeAction}
                                disabled={bulkLoading}
                                className={`flex-1 py-2 rounded-lg text-white transition-colors ${
                                    selectedAction === 'delete'
                                        ? 'bg-red-600 hover:bg-red-700'
                                        : 'bg-indigo-600 hover:bg-indigo-700'
                                } ${bulkLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                            >
                                {bulkLoading ? 'İşleniyor...' : 'Uygula'}
                            </button>
                        </div>
                    </motion.div>
                </div>
            )}

            {/* Import Modal */}
            <ImportModal
                isOpen={showImportModal}
                onClose={() => setShowImportModal(false)}
                onImportComplete={() => {
                    // Refresh products after import
                    window.location.reload();
                }}
            />
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    FileText, Download, PlusCircle, Search, Filter, Printer,
    CheckCircle2, Clock, AlertTriangle, Eye, Trash2, Send,
    Building, Calendar, DollarSign, Hash
} from 'lucide-react';

const invoicesData: any[] = [];

const statusConfig: Record<string, { label: string; color: string; bg: string; icon: typeof CheckCircle2 }> = {
    paid: { label: 'Ödendi', color: 'text-emerald-400', bg: 'bg-emerald-500/10', icon: CheckCircle2 },
    pending: { label: 'Bekliyor', color: 'text-amber-400', bg: 'bg-amber-500/10', icon: Clock },
    overdue: { label: 'Gecikmiş', color: 'text-red-400', bg: 'bg-red-500/10', icon: AlertTriangle },
    draft: { label: 'Taslak', color: 'text-slate-400', bg: 'bg-slate-500/10', icon: FileText },
};

export default function BulkInvoicePage() {
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [showCreate, setShowCreate] = useState(false);
    const [selectedIds, setSelectedIds] = useState<string[]>([]);

    const filtered = invoicesData.filter(inv =>
        (statusFilter === 'all' || inv.status === statusFilter) &&
        (inv.customer.toLowerCase().includes(searchTerm.toLowerCase()) || inv.id.toLowerCase().includes(searchTerm.toLowerCase()))
    );

    const totalAmount = invoicesData.reduce((a, i) => a + i.total, 0);
    const paidAmount = invoicesData.filter(i => i.status === 'paid').reduce((a, i) => a + i.total, 0);
    const pendingAmount = invoicesData.filter(i => i.status === 'pending' || i.status === 'overdue').reduce((a, i) => a + i.total, 0);

    const toggleSelect = (id: string) => {
        setSelectedIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
    };
    const toggleAll = () => {
        setSelectedIds(prev => prev.length === filtered.length ? [] : filtered.map(i => i.id));
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                        <FileText className="w-7 h-7 text-indigo-400" /> Toplu Fatura Oluşturucu
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">Faturaları oluşturun, yönetin ve toplu gönderin</p>
                </div>
                <div className="flex gap-2">
                    {selectedIds.length > 0 && (
                        <button className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-sm transition-colors">
                            <Printer className="w-4 h-4" /> {selectedIds.length} Fatura Yazdır
                        </button>
                    )}
                    <button onClick={() => setShowCreate(true)} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm transition-colors">
                        <PlusCircle className="w-4 h-4" /> Yeni Fatura
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Tutar', value: `₺${totalAmount.toLocaleString()}`, icon: DollarSign, color: 'text-blue-400' },
                    { label: 'Ödenen', value: `₺${paidAmount.toLocaleString()}`, icon: CheckCircle2, color: 'text-emerald-400' },
                    { label: 'Bekleyen', value: `₺${pendingAmount.toLocaleString()}`, icon: Clock, color: 'text-amber-400' },
                    { label: 'Toplam Fatura', value: invoicesData.length.toString(), icon: Hash, color: 'text-indigo-400' },
                ].map((stat, i) => (
                    <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                        className="bg-surface rounded-xl border border-border p-5">
                        <stat.icon className={`w-5 h-5 ${stat.color} mb-2`} />
                        <div className="text-2xl font-bold text-foreground">{stat.value}</div>
                        <div className="text-xs text-slate-500">{stat.label}</div>
                    </motion.div>
                ))}
            </div>

            {/* Filters */}
            <div className="flex gap-3">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Fatura veya müşteri ara..."
                        className="w-full pl-10 pr-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                </div>
                <div className="flex gap-1 bg-surface rounded-xl p-1 border border-border">
                    {[{ id: 'all', label: 'Tümü' }, ...Object.entries(statusConfig).map(([id, cfg]) => ({ id, label: cfg.label }))].map(f => (
                        <button key={f.id} onClick={() => setStatusFilter(f.id)}
                            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${statusFilter === f.id ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-foreground'}`}>
                            {f.label}
                        </button>
                    ))}
                </div>
            </div>

            {/* Invoices Table */}
            <div className="bg-surface rounded-xl border border-border overflow-hidden">
                <table className="w-full text-sm">
                    <thead>
                        <tr className="text-slate-500 text-xs border-b border-border">
                            <th className="text-left px-4 py-3">
                                <input type="checkbox" checked={selectedIds.length === filtered.length && filtered.length > 0} onChange={toggleAll}
                                    className="rounded border-border" />
                            </th>
                            <th className="text-left px-4 py-3 font-medium">Fatura No</th>
                            <th className="text-left px-4 py-3 font-medium">Müşteri</th>
                            <th className="text-left px-4 py-3 font-medium">Tarih</th>
                            <th className="text-left px-4 py-3 font-medium">Vade</th>
                            <th className="text-left px-4 py-3 font-medium">Kalem</th>
                            <th className="text-right px-4 py-3 font-medium">Tutar</th>
                            <th className="text-left px-4 py-3 font-medium">Durum</th>
                            <th className="text-right px-4 py-3 font-medium">İşlem</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filtered.length === 0 && (
                            <tr>
                                <td colSpan={9} className="px-4 py-6 text-sm text-slate-500">Fatura verisi bulunamadı</td>
                            </tr>
                        )}
                        {filtered.map((inv, i) => {
                            const cfg = statusConfig[inv.status];
                            return (
                                <motion.tr key={inv.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03 }}
                                    className="border-b border-border/50 hover:bg-background/50">
                                    <td className="px-4 py-3">
                                        <input type="checkbox" checked={selectedIds.includes(inv.id)} onChange={() => toggleSelect(inv.id)}
                                            className="rounded border-border" />
                                    </td>
                                    <td className="px-4 py-3 font-mono text-xs text-indigo-400">{inv.id}</td>
                                    <td className="px-4 py-3">
                                        <div className="text-foreground text-xs">{inv.customer}</div>
                                        <div className="text-[10px] text-slate-500">{inv.company}</div>
                                    </td>
                                    <td className="px-4 py-3 text-xs text-slate-400">{inv.date}</td>
                                    <td className="px-4 py-3 text-xs text-slate-400">{inv.dueDate}</td>
                                    <td className="px-4 py-3 text-xs text-foreground">{inv.items}</td>
                                    <td className="px-4 py-3 text-right">
                                        <div className="text-xs text-foreground font-medium">₺{inv.total.toLocaleString()}</div>
                                        <div className="text-[10px] text-slate-500">KDV: ₺{inv.tax.toLocaleString()}</div>
                                    </td>
                                    <td className="px-4 py-3">
                                        <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs ${cfg.bg} ${cfg.color}`}>
                                            <cfg.icon className="w-3 h-3" /> {cfg.label}
                                        </span>
                                    </td>
                                    <td className="px-4 py-3 text-right">
                                        <div className="flex items-center justify-end gap-1">
                                            <button className="p-1.5 text-slate-500 hover:text-foreground"><Eye className="w-3.5 h-3.5" /></button>
                                            <button className="p-1.5 text-slate-500 hover:text-foreground"><Download className="w-3.5 h-3.5" /></button>
                                            <button className="p-1.5 text-slate-500 hover:text-foreground"><Send className="w-3.5 h-3.5" /></button>
                                        </div>
                                    </td>
                                </motion.tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>

            {/* Create Invoice Modal */}
            {showCreate && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50" onClick={() => setShowCreate(false)}>
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl border border-border p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                        <h3 className="text-lg font-semibold text-foreground mb-4">Yeni Fatura Oluştur</h3>
                        <div className="space-y-3">
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Müşteri Adı</label>
                                    <input placeholder="Ad Soyad" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                                </div>
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Firma</label>
                                    <input placeholder="Firma Adı" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Fatura Tarihi</label>
                                    <input type="date" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border" />
                                </div>
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Vade Tarihi</label>
                                    <input type="date" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border" />
                                </div>
                            </div>
                            <div>
                                <label className="text-xs text-slate-400 block mb-1">Notlar</label>
                                <textarea placeholder="Fatura notu..." rows={2}
                                    className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none resize-none" />
                            </div>
                        </div>
                        <div className="flex justify-end gap-2 mt-6">
                            <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-sm text-slate-400 hover:text-foreground">İptal</button>
                            <button className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium">Oluştur</button>
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Printer, Search, CheckCircle, Package, Truck,
    MapPin, Phone, FileText, Loader2, X, RefreshCw, ShoppingBag
} from 'lucide-react';
import { useOrders } from '@/lib/hooks';

const platformColors: Record<string, string> = {
    TRENDYOL: 'bg-orange-500/10 text-orange-400 border-orange-500/20',
    HEPSIBURADA: 'bg-red-500/10 text-red-400 border-red-500/20',
    AMAZON: 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20',
    N11: 'bg-purple-500/10 text-purple-400 border-purple-500/20',
    TRENDYOL_INTERNATIONAL: 'bg-orange-500/10 text-orange-400 border-orange-500/20',
};

interface Order {
    id: string;
    marketplaceOrderId?: string;
    customerName: string;
    customerPhone?: string;
    shippingAddress?: string;
    platform: string;
    status: string;
    orderDate?: string;
    createdAt: string;
}

export default function BulkLabelsPage() {
    const { getOrders, loading } = useOrders();
    const [orders, setOrders] = useState<Order[]>([]);
    const [printedIds, setPrintedIds] = useState<string[]>([]);
    const [selected, setSelected] = useState<string[]>([]);
    const [search, setSearch] = useState('');
    const [filterPlatform, setFilterPlatform] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    const [printing, setPrinting] = useState(false);
    const [printDone, setPrintDone] = useState(false);
    const [printError, setPrintError] = useState<string | null>(null);

    const loadOrders = async () => {
        const filters: Record<string, string> = { status: 'CONFIRMED', limit: '100' };
        if (filterPlatform !== 'all') filters.platform = filterPlatform;
        const response = await getOrders(filters) as { orders: Order[] } | null;
        if (response) {
            setOrders(response.orders || []);
        }
    };

    useEffect(() => {
        loadOrders();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filterPlatform]);

    // Map real order statuses to label statuses
    const getLabelStatus = (order: Order): 'ready' | 'printed' | 'shipped' => {
        if (printedIds.includes(order.id)) return 'printed';
        if (order.status === 'SHIPPED' || order.status === 'DELIVERED') return 'shipped';
        return 'ready';
    };

    const filtered = orders.filter(o => {
        const labelStatus = getLabelStatus(o);
        const matchSearch = !search ||
            (o.customerName || '').toLowerCase().includes(search.toLowerCase()) ||
            (o.marketplaceOrderId || '').toLowerCase().includes(search.toLowerCase());
        const matchPlatform = filterPlatform === 'all' || o.platform === filterPlatform;
        const matchStatus = filterStatus === 'all' || labelStatus === filterStatus;
        return matchSearch && matchPlatform && matchStatus;
    });

    const toggle = (id: string) =>
        setSelected(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
    const toggleAll = (e: React.ChangeEvent<HTMLInputElement>) =>
        setSelected(e.target.checked ? filtered.map(o => o.id) : []);

    const handlePrint = async () => {
        setPrintError(null);
        setPrinting(true);
        try {
            window.print();
            setPrintDone(true);
            setPrintedIds(prev => [...new Set([...prev, ...selected])]);
            setSelected([]);
        } catch {
            setPrintDone(false);
            setPrintError('Yazdırma işlemi başlatılamadı. Tarayıcı izinlerini kontrol edin.');
        } finally {
            setPrinting(false);
        }
    };

    const readyCount = orders.filter(o => getLabelStatus(o) === 'ready').length;
    const printedCount = printedIds.length;
    const shippedCount = orders.filter(o => getLabelStatus(o) === 'shipped').length;

    const platforms = [...new Set(orders.map(o => o.platform).filter(Boolean))];

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <div className="flex items-center gap-3 mb-1">
                        <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/20">
                            <Printer className="w-6 h-6 text-rose-500" />
                        </div>
                        <h1 className="text-3xl font-black text-foreground">Toplu Kargo Etiketi</h1>
                    </div>
                    <p className="text-slate-500 font-medium ml-14">Siparişleri seçin, tek tıkla tüm kargo etiketlerini yazdırın</p>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={loadOrders}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all"
                    >
                        <RefreshCw size={16} className={loading ? "animate-spin" : ""} /> Yenile
                    </button>
                    <button
                        onClick={handlePrint}
                        disabled={selected.length === 0 || printing}
                        className="flex items-center gap-2 px-5 py-2.5 bg-rose-600 text-white rounded-xl text-sm font-bold hover:bg-rose-500 transition-all shadow-lg shadow-rose-500/20 disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                        {printing ? <><Loader2 size={16} className="animate-spin" /> Oluşturuluyor...</> : <><Printer size={16} /> {selected.length} Etiket Yazdır</>}
                    </button>
                </div>
            </div>

            {/* Success Toast */}
            <AnimatePresence>
                {printDone && (
                    <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}
                        className="bg-green-500/10 border border-green-500/30 rounded-2xl px-5 py-4 flex items-center gap-3">
                        <CheckCircle size={18} className="text-green-400" />
                        <span className="text-sm font-bold text-green-300">Yazdırma penceresi açıldı. Seçili siparişler basıldı olarak işaretlendi.</span>
                    </motion.div>
                )}
            </AnimatePresence>
            {printError && (
                <div className="bg-red-500/10 border border-red-500/30 rounded-2xl px-5 py-4 text-sm font-medium text-red-300">
                    {printError}
                </div>
            )}

            {/* Stats */}
            <div className="grid grid-cols-3 gap-4">
                {[
                    { label: 'Hazır Sipariş', value: readyCount, color: 'text-blue-500', bg: 'bg-blue-500/10', icon: Package },
                    { label: 'Etiket Basıldı', value: printedCount, color: 'text-yellow-500', bg: 'bg-yellow-500/10', icon: Printer },
                    { label: 'Kargoya Verildi', value: shippedCount, color: 'text-green-500', bg: 'bg-green-500/10', icon: Truck },
                ].map(s => (
                    <div key={s.label} className="bg-surface rounded-2xl border border-border p-5">
                        <div className={`p-2.5 rounded-xl ${s.bg} w-fit mb-3`}><s.icon className={`w-5 h-5 ${s.color}`} /></div>
                        <div className="text-2xl font-black text-foreground">{s.value}</div>
                        <div className="text-xs text-slate-500 mt-0.5">{s.label}</div>
                    </div>
                ))}
            </div>

            {/* Filters */}
            <div className="flex flex-col sm:flex-row gap-3">
                <div className="relative flex-1">
                    <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                    <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Müşteri adı veya sipariş no..."
                        className="w-full pl-11 pr-4 py-3 bg-surface border border-border rounded-xl text-sm text-foreground placeholder-slate-600 focus:border-rose-500 outline-none transition-colors" />
                </div>
                <div className="flex gap-2 flex-wrap">
                    {(['all', 'ready', 'printed', 'shipped'] as const).map(s => (
                        <button key={s} onClick={() => setFilterStatus(s)}
                            className={`px-3 py-2.5 rounded-xl text-xs font-bold border transition-all ${filterStatus === s ? 'bg-rose-600 text-white border-transparent' : 'bg-surface border-border text-slate-400 hover:text-foreground'}`}>
                            {s === 'all' ? 'Tümü' : s === 'ready' ? 'Hazır' : s === 'printed' ? 'Basıldı' : 'Kargoda'}
                        </button>
                    ))}
                    {platforms.length > 0 && (
                        <select value={filterPlatform} onChange={e => setFilterPlatform(e.target.value)}
                            className="px-3 py-2.5 rounded-xl text-xs font-bold border bg-surface border-border text-slate-400 focus:outline-none">
                            <option value="all">Tüm Platformlar</option>
                            {platforms.map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                    )}
                </div>
            </div>

            {/* Orders Table */}
            <div className="bg-surface border border-border rounded-2xl overflow-hidden">
                {/* Table Header */}
                <div className="grid grid-cols-12 gap-3 px-5 py-4 bg-background/50 border-b border-border">
                    <div className="col-span-1">
                        <input type="checkbox"
                            checked={selected.length === filtered.length && filtered.length > 0}
                            onChange={toggleAll} className="rounded" />
                    </div>
                    <div className="col-span-4 text-[10px] font-black text-slate-500 uppercase tracking-wider">Sipariş / Müşteri</div>
                    <div className="col-span-4 text-[10px] font-black text-slate-500 uppercase tracking-wider">Teslimat Adresi</div>
                    <div className="col-span-1 text-[10px] font-black text-slate-500 uppercase tracking-wider">Platform</div>
                    <div className="col-span-2 text-[10px] font-black text-slate-500 uppercase tracking-wider">Durum</div>
                </div>

                {loading && orders.length === 0 && (
                    <div className="py-20 flex items-center justify-center gap-3 text-slate-500">
                        <Loader2 size={20} className="animate-spin" />
                        <span className="text-sm font-medium">Siparişler yükleniyor...</span>
                    </div>
                )}

                {!loading && filtered.length === 0 && (
                    <div className="py-20 flex flex-col items-center justify-center gap-3 text-slate-500">
                        <ShoppingBag size={40} className="text-slate-300" />
                        <div className="text-center">
                            <p className="font-bold text-foreground">Etiket bekleyen sipariş bulunamadı</p>
                            <p className="text-sm mt-1">Kargo için hazır siparişler burada görüntülenecek.</p>
                        </div>
                    </div>
                )}

                {filtered.map((order, idx) => {
                    const labelStatus = getLabelStatus(order);
                    return (
                        <motion.div key={order.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: idx * 0.04 }}
                            className={`grid grid-cols-12 gap-3 items-center px-5 py-4 border-b border-border last:border-0 hover:bg-white/2 transition-colors ${selected.includes(order.id) ? 'bg-rose-500/5' : ''}`}>
                            <div className="col-span-1">
                                <input type="checkbox" checked={selected.includes(order.id)} onChange={() => toggle(order.id)} className="rounded" />
                            </div>
                            <div className="col-span-4">
                                <div className="text-xs font-mono text-slate-500">#{order.marketplaceOrderId || order.id.slice(0, 8).toUpperCase()}</div>
                                <div className="font-bold text-sm text-foreground mt-0.5">{order.customerName}</div>
                                <div className="text-[10px] text-slate-500 mt-0.5">
                                    {new Date(order.orderDate || order.createdAt).toLocaleDateString('tr-TR')}
                                </div>
                            </div>
                            <div className="col-span-4">
                                <div className="text-xs text-foreground">{order.shippingAddress || '—'}</div>
                                {order.customerPhone && (
                                    <div className="flex items-center gap-1 text-[10px] text-slate-500 mt-0.5">
                                        <Phone size={9} /> {order.customerPhone}
                                    </div>
                                )}
                            </div>
                            <div className="col-span-1">
                                <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border ${platformColors[order.platform] || 'bg-slate-500/10 text-slate-400 border-slate-500/20'}`}>
                                    {order.platform}
                                </span>
                            </div>
                            <div className="col-span-2">
                                {labelStatus === 'ready' && (
                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full bg-blue-500/10 text-blue-400 border border-blue-500/20">
                                        <Package size={9} /> Hazır
                                    </span>
                                )}
                                {labelStatus === 'printed' && (
                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full bg-yellow-500/10 text-yellow-400 border border-yellow-500/20">
                                        <Printer size={9} /> Basıldı
                                    </span>
                                )}
                                {labelStatus === 'shipped' && (
                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full bg-green-500/10 text-green-400 border border-green-500/20">
                                        <Truck size={9} /> Kargoda
                                    </span>
                                )}
                            </div>
                        </motion.div>
                    );
                })}
            </div>

            {/* Floating Action Bar */}
            {selected.length > 0 && (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
                    className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 bg-surface border border-border rounded-2xl shadow-2xl px-6 py-4 flex items-center gap-4">
                    <span className="text-sm font-bold text-foreground">{selected.length} sipariş seçili</span>
                    <div className="h-5 w-px bg-border" />
                    <button onClick={handlePrint} disabled={printing}
                        className="flex items-center gap-2 px-5 py-2.5 bg-rose-600 text-white rounded-xl text-sm font-bold hover:bg-rose-500 transition-all disabled:opacity-60">
                        {printing ? <Loader2 size={15} className="animate-spin" /> : <Printer size={15} />}
                        Etiketleri Yazdır
                    </button>
                    <button onClick={() => setSelected([])} className="p-2 rounded-xl hover:bg-background text-slate-400 transition-all">
                        <X size={16} />
                    </button>
                </motion.div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Megaphone, Plus, Calendar, Tag, Target, TrendingUp, Eye,
    Edit, Trash2, Copy, Play, Pause, CheckCircle, Clock,
    Percent, Gift, Zap, Users, BarChart3
} from 'lucide-react';
import { useCampaigns } from '@/lib/hooks';

interface Campaign {
    id: string;
    name: string;
    type: string;
    status: 'active' | 'scheduled' | 'ended' | 'draft';
    startDate: string;
    endDate: string;
    platform: string;
    discount: string;
    affectedProducts: number;
    totalSales: string;
    conversionRate: number;
}

const statusLabels: Record<string, string> = { active: 'Aktif', scheduled: 'Planlanmış', ended: 'Bitti', draft: 'Taslak' };
const statusColors: Record<string, string> = { active: 'emerald', scheduled: 'blue', ended: 'slate', draft: 'yellow' };

export default function CampaignManagerPage() {
    const { campaigns } = useCampaigns();
    const [filter, setFilter] = useState('all');
    const [showCreate, setShowCreate] = useState(false);

    const normalizedCampaigns: Campaign[] = (Array.isArray(campaigns) ? campaigns : []).map((c: any) => ({
        id: String(c.id),
        name: c.name,
        type: c.type,
        status: c.status === 'completed' ? 'ended' : c.status,
        startDate: c.startDate,
        endDate: c.endDate,
        platform: Array.isArray(c.platforms) && c.platforms.length > 0 ? c.platforms.join(', ') : 'Tümü',
        discount: c.discount !== undefined ? `%${c.discount}` : '-',
        affectedProducts: Array.isArray(c.products) ? c.products.length : 0,
        totalSales: `₺${Number(c.revenue || 0).toLocaleString('tr-TR')}`,
        conversionRate: Number(c.conversionRate || 0),
    }));

    const filtered = filter === 'all' ? normalizedCampaigns : normalizedCampaigns.filter(c => c.status === filter);

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <Megaphone className="w-8 h-8 text-pink-500" /> Kampanya Yönetimi
                    </h1>
                    <p className="text-slate-500 mt-1">İndirim, kupon ve kampanyalarınızı oluşturun ve yönetin</p>
                </div>
                <button onClick={() => setShowCreate(true)} className="flex items-center gap-2 px-4 py-2 bg-pink-600 hover:bg-pink-700 text-white rounded-xl text-sm font-medium">
                    <Plus className="w-4 h-4" /> Kampanya Oluştur
                </button>
            </div>

            <div className="grid grid-cols-4 gap-4">
                {[
                    { label: 'Aktif Kampanya', value: normalizedCampaigns.filter(c => c.status === 'active').length, icon: Play },
                    { label: 'Toplam Gelir', value: `₺${normalizedCampaigns.reduce((s, c) => s + Number(String(c.totalSales).replace(/[^\d]/g, '')), 0).toLocaleString('tr-TR')}`, icon: TrendingUp },
                    { label: 'Ort. Dönüşüm', value: normalizedCampaigns.length > 0 ? `%${(normalizedCampaigns.reduce((s, c) => s + c.conversionRate, 0) / normalizedCampaigns.length).toFixed(1)}` : '--', icon: Target },
                    { label: 'Etkilenen Ürün', value: normalizedCampaigns.reduce((s, c) => s + c.affectedProducts, 0), icon: Tag },
                ].map((s, i) => (
                    <div key={i} className="bg-surface rounded-2xl border border-border p-5">
                        <s.icon className="w-5 h-5 text-pink-500 mb-2" />
                        <div className="text-2xl font-bold text-foreground">{s.value}</div>
                        <div className="text-xs text-slate-500">{s.label}</div>
                    </div>
                ))}
            </div>

            <div className="flex gap-1 bg-surface border border-border rounded-xl p-1">
                {['all', 'active', 'scheduled', 'ended'].map(f => (
                    <button key={f} onClick={() => setFilter(f)}
                        className={`flex-1 py-2 text-xs rounded-lg font-medium transition-all ${filter === f ? 'bg-pink-500/20 text-pink-400' : 'text-slate-500 hover:text-foreground'}`}>
                        {f === 'all' ? 'Tümü' : statusLabels[f]}
                    </button>
                ))}
            </div>

            <div className="space-y-4">
                {filtered.length === 0 && (
                    <div className="bg-surface rounded-2xl border border-border p-6 text-sm text-slate-500">Kampanya verisi bulunamadı</div>
                )}
                {filtered.map((c, i) => (
                    <motion.div key={c.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}
                        className="bg-surface rounded-2xl border border-border p-5 hover:border-pink-500/30 transition-colors">
                        <div className="flex items-start justify-between">
                            <div>
                                <div className="flex items-center gap-3 mb-1">
                                    <h3 className="text-base font-bold text-foreground">{c.name}</h3>
                                    <span className={`px-2 py-0.5 text-xs rounded-full bg-${statusColors[c.status]}-500/20 text-${statusColors[c.status]}-400`}>
                                        {statusLabels[c.status]}
                                    </span>
                                </div>
                                <div className="flex items-center gap-4 text-xs text-slate-500">
                                    <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {c.startDate} → {c.endDate}</span>
                                    <span>{c.platform}</span>
                                    <span className="text-foreground font-medium">{c.discount}</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-1">
                                <button className="p-2 hover:bg-background rounded-lg text-slate-400"><Eye className="w-4 h-4" /></button>
                                <button className="p-2 hover:bg-background rounded-lg text-slate-400"><Edit className="w-4 h-4" /></button>
                                <button className="p-2 hover:bg-background rounded-lg text-slate-400 hover:text-red-400"><Trash2 className="w-4 h-4" /></button>
                            </div>
                        </div>
                        <div className="grid grid-cols-3 gap-3 mt-4 pt-4 border-t border-border">
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Satış</div><div className="text-sm font-bold text-foreground">{c.totalSales}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Dönüşüm</div><div className="text-sm font-bold text-foreground">%{c.conversionRate}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Ürün Sayısı</div><div className="text-sm font-bold text-foreground">{c.affectedProducts}</div></div>
                        </div>
                    </motion.div>
                ))}
            </div>

            {showCreate && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowCreate(false)}>
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl w-full max-w-lg border border-border p-6" onClick={e => e.stopPropagation()}>
                        <h3 className="text-xl font-bold text-foreground mb-4">Yeni Kampanya</h3>
                        <div className="space-y-4">
                            <input placeholder="Kampanya Adı" className="w-full px-4 py-2.5 bg-background rounded-xl text-sm text-foreground placeholder:text-slate-500 border border-border" />
                            <div className="grid grid-cols-2 gap-3">
                                <input type="date" className="px-3 py-2 bg-background rounded-xl text-sm text-foreground border border-border" />
                                <input type="date" className="px-3 py-2 bg-background rounded-xl text-sm text-foreground border border-border" />
                            </div>
                            <select className="w-full px-4 py-2.5 bg-background rounded-xl text-sm text-foreground border border-border">
                                <option>İndirim</option><option>Paket</option><option>Flash Sale</option><option>Kupon</option><option>Ücretsiz Kargo</option>
                            </select>
                            <input placeholder="İndirim Oranı/Miktarı" className="w-full px-4 py-2.5 bg-background rounded-xl text-sm text-foreground placeholder:text-slate-500 border border-border" />
                        </div>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setShowCreate(false)} className="flex-1 py-2.5 bg-background text-foreground rounded-xl text-sm font-medium">İptal</button>
                            <button onClick={() => setShowCreate(false)} className="flex-1 py-2.5 bg-pink-600 text-white rounded-xl text-sm font-medium">Oluştur</button>
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useCampaigns, Campaign } from '@/lib/hooks';
import {
    Megaphone,
    Plus,
    Calendar,
    Clock,
    Target,
    TrendingUp,
    DollarSign,
    Eye,
    MousePointer,
    ShoppingCart,
    Play,
    Pause,
    Edit,
    Trash2,
    Copy,
    BarChart3,
    Zap,
    Tag,
    Percent,
    Gift,
    Sparkles,
    ChevronRight,
    CheckCircle,
    XCircle,
    AlertTriangle
} from 'lucide-react';

// Campaign types
const campaignTypes = [
    { id: 'discount', name: 'İndirim', icon: <Percent size={16} />, color: 'bg-green-500' },
    { id: 'bundle', name: 'Bundle', icon: <Gift size={16} />, color: 'bg-purple-500' },
    { id: 'flash', name: 'Flash Sale', icon: <Zap size={16} />, color: 'bg-orange-500' },
    { id: 'coupon', name: 'Kupon', icon: <Tag size={16} />, color: 'bg-blue-500' }
];

export default function CampaignsPage() {
    const { campaigns: apiCampaigns, loading } = useCampaigns();
    const [selectedStatus, setSelectedStatus] = useState('all');
    const [selectedType, setSelectedType] = useState('all');

    const campaigns: Campaign[] = (Array.isArray(apiCampaigns) && apiCampaigns.length > 0) ? apiCampaigns : [];

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'active':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-green-500/10 text-green-500 border border-green-500/20">
                        <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" /> Aktif
                    </span>
                );
            case 'scheduled':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-blue-500/10 text-blue-500 border border-blue-500/20">
                        <Clock size={10} /> Planlandı
                    </span>
                );
            case 'paused':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-yellow-500/10 text-yellow-500 border border-yellow-500/20">
                        <Pause size={10} /> Duraklatıldı
                    </span>
                );
            case 'ended':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-slate-500/10 text-slate-500 border border-slate-500/20">
                        <CheckCircle size={10} /> Tamamlandı
                    </span>
                );
            default:
                return null;
        }
    };

    const getCampaignTypeConfig = (type: string) => {
        return campaignTypes.find(t => t.id === type) || campaignTypes[0];
    };

    const filteredCampaigns = campaigns.filter(campaign => {
        const matchesStatus = selectedStatus === 'all' || campaign.status === selectedStatus;
        const matchesType = selectedType === 'all' || campaign.type === selectedType;
        return matchesStatus && matchesType;
    });

    const activeCampaigns = campaigns.filter(c => c.status === 'active').length;
    const totalBudget = campaigns.reduce((sum, c) => sum + c.budget, 0);
    const totalSpent = campaigns.reduce((sum, c) => sum + c.spent, 0);
    const totalRevenue = campaigns.reduce((sum, c) => sum + (c.stats?.revenue ?? c.revenue ?? 0), 0);

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="flex flex-col items-center gap-3">
                    <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin" />
                    <span className="text-sm text-slate-500 font-medium">Kampanyalar yükleniyor...</span>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight">Kampanyalar</h1>
                    <p className="text-slate-500 font-medium">Pazaryeri kampanyalarınızı oluşturun ve yönetin</p>
                </div>
                <button className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl text-sm font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20">
                    <Plus size={16} /> Yeni Kampanya
                </button>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-green-500/10">
                            <Megaphone size={20} className="text-green-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">{activeCampaigns}</div>
                    <div className="text-xs text-slate-500 mt-1">Aktif Kampanya</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-blue-500/10">
                            <DollarSign size={20} className="text-blue-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(totalBudget / 1000).toFixed(0)}K</div>
                    <div className="text-xs text-slate-500 mt-1">Toplam Bütçe</div>
                    <div className="mt-2 h-1.5 bg-background rounded-full overflow-hidden">
                        <div
                            className="h-full bg-blue-500"
                            style={{ width: `${(totalSpent / totalBudget) * 100}%` }}
                        />
                    </div>
                    <div className="text-[10px] text-slate-500 mt-1">₺{(totalSpent / 1000).toFixed(0)}K harcandı</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-gradient-to-br from-green-500/10 to-emerald-500/5 p-6 rounded-2xl border border-green-500/20"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-green-500/10">
                            <TrendingUp size={20} className="text-green-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-green-600">₺{(totalRevenue / 1000).toFixed(0)}K</div>
                    <div className="text-xs text-green-600/70 mt-1">Toplam Gelir</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-purple-500/10">
                            <BarChart3 size={20} className="text-purple-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">
                        {(totalRevenue / totalSpent).toFixed(2)}x
                    </div>
                    <div className="text-xs text-slate-500 mt-1">Ortalama ROAS</div>
                </motion.div>
            </div>

            {/* Filters */}
            <div className="flex flex-col lg:flex-row gap-4">
                <div className="flex gap-2 overflow-x-auto pb-2 lg:pb-0">
                    {[
                        { id: 'all', label: 'Tümü' },
                        { id: 'active', label: 'Aktif' },
                        { id: 'scheduled', label: 'Planlandı' },
                        { id: 'paused', label: 'Duraklatıldı' },
                        { id: 'ended', label: 'Tamamlandı' }
                    ].map(filter => (
                        <button
                            key={filter.id}
                            onClick={() => setSelectedStatus(filter.id)}
                            className={`px-4 py-2.5 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${selectedStatus === filter.id
                                ? 'bg-primary text-white'
                                : 'bg-surface border border-border text-foreground hover:bg-background'
                                }`}
                        >
                            {filter.label}
                        </button>
                    ))}
                </div>
                <div className="flex gap-2">
                    {campaignTypes.map(type => (
                        <button
                            key={type.id}
                            onClick={() => setSelectedType(selectedType === type.id ? 'all' : type.id)}
                            className={`flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-medium transition-all ${selectedType === type.id
                                ? 'bg-primary text-white'
                                : 'bg-surface border border-border text-foreground hover:bg-background'
                                }`}
                        >
                            {type.icon}
                            {type.name}
                        </button>
                    ))}
                </div>
            </div>

            {/* Campaigns List */}
            <div className="space-y-4">
                {filteredCampaigns.map((campaign, idx) => {
                    const typeConfig = getCampaignTypeConfig(campaign.type);

                    return (
                        <motion.div
                            key={campaign.id}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: idx * 0.05 }}
                            className="bg-surface rounded-2xl border border-border overflow-hidden hover:border-primary/30 transition-all"
                        >
                            <div className="p-5">
                                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 mb-4">
                                    <div className="flex items-center gap-4">
                                        <div className={`p-3 rounded-xl ${typeConfig.color}`}>
                                            {typeConfig.icon}
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <h3 className="font-bold text-foreground">{campaign.name}</h3>
                                                {getStatusBadge(campaign.status)}
                                            </div>
                                            <div className="flex items-center gap-3 text-xs text-slate-500">
                                                <span className="flex items-center gap-1">
                                                    <Calendar size={10} />
                                                    {campaign.startDate} - {campaign.endDate}
                                                </span>
                                                <span className="flex items-center gap-1">
                                                    <Percent size={10} />
                                                    %{campaign.discount} indirim
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        {campaign.platforms.map((p: string) => (
                                            <span key={p} className="text-[10px] font-bold px-2 py-1 rounded-lg bg-background border border-border text-slate-500">
                                                {p}
                                            </span>
                                        ))}
                                    </div>
                                </div>

                                {/* Campaign Stats */}
                                <div className="grid grid-cols-2 lg:grid-cols-6 gap-4 p-4 bg-background rounded-xl">
                                    <div>
                                        <div className="text-xs text-slate-500 mb-1">Gösterim</div>
                                        <div className="text-lg font-bold text-foreground">
                                            {(campaign.stats?.impressions ?? campaign.impressions) > 0 ? `${((campaign.stats?.impressions ?? campaign.impressions) / 1000).toFixed(0)}K` : '-'}
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-500 mb-1">Tıklama</div>
                                        <div className="text-lg font-bold text-foreground">
                                            {(campaign.stats?.clicks ?? campaign.clicks) > 0 ? `${((campaign.stats?.clicks ?? campaign.clicks) / 1000).toFixed(1)}K` : '-'}
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-500 mb-1">Dönüşüm</div>
                                        <div className="text-lg font-bold text-foreground">
                                            {(campaign.stats?.conversions ?? campaign.conversions) > 0 ? (campaign.stats?.conversions ?? campaign.conversions) : '-'}
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-500 mb-1">Harcama</div>
                                        <div className="text-lg font-bold text-foreground">
                                            ₺{(campaign.spent / 1000).toFixed(1)}K
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-500 mb-1">Gelir</div>
                                        <div className="text-lg font-bold text-green-500">
                                            {(campaign.stats?.revenue ?? campaign.revenue) > 0 ? `₺${((campaign.stats?.revenue ?? campaign.revenue) / 1000).toFixed(0)}K` : '-'}
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-500 mb-1">ROAS</div>
                                        <div className="text-lg font-bold text-primary">
                                            {(campaign.stats?.roas ?? campaign.roas) > 0 ? `${(campaign.stats?.roas ?? campaign.roas).toFixed(2)}x` : '-'}
                                        </div>
                                    </div>
                                </div>

                                {/* Budget Progress */}
                                <div className="mt-4">
                                    <div className="flex items-center justify-between text-xs mb-2">
                                        <span className="text-slate-500">Bütçe Kullanımı</span>
                                        <span className="font-medium text-foreground">
                                            ₺{campaign.spent.toLocaleString('tr-TR')} / ₺{campaign.budget.toLocaleString('tr-TR')}
                                        </span>
                                    </div>
                                    <div className="h-2 bg-background rounded-full overflow-hidden">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${(campaign.spent / campaign.budget) * 100}%` }}
                                            transition={{ delay: idx * 0.1, duration: 0.5 }}
                                            className={`h-full ${campaign.spent / campaign.budget > 0.8 ? 'bg-red-500' : 'bg-primary'}`}
                                        />
                                    </div>
                                </div>

                                {/* Actions */}
                                <div className="flex items-center justify-end gap-2 mt-4 pt-4 border-t border-border">
                                    <button className="p-2 rounded-lg hover:bg-background text-slate-400 hover:text-foreground transition-all">
                                        <BarChart3 size={16} />
                                    </button>
                                    <button className="p-2 rounded-lg hover:bg-background text-slate-400 hover:text-foreground transition-all">
                                        <Copy size={16} />
                                    </button>
                                    <button className="p-2 rounded-lg hover:bg-background text-slate-400 hover:text-foreground transition-all">
                                        <Edit size={16} />
                                    </button>
                                    {campaign.status === 'active' ? (
                                        <button className="flex items-center gap-1.5 px-3 py-1.5 bg-yellow-500/10 border border-yellow-500/20 rounded-lg text-xs font-bold text-yellow-500 hover:bg-yellow-500/20 transition-all">
                                            <Pause size={12} /> Duraklat
                                        </button>
                                    ) : campaign.status === 'paused' || campaign.status === 'scheduled' ? (
                                        <button className="flex items-center gap-1.5 px-3 py-1.5 bg-green-500/10 border border-green-500/20 rounded-lg text-xs font-bold text-green-500 hover:bg-green-500/20 transition-all">
                                            <Play size={12} /> Başlat
                                        </button>
                                    ) : null}
                                </div>
                            </div>
                        </motion.div>
                    );
                })}
            </div>

            {/* Create Campaign CTA */}
            <div className="bg-gradient-to-br from-primary/10 to-purple-500/5 rounded-2xl border border-primary/20 p-6">
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                        <div className="p-3 rounded-xl bg-primary/10">
                            <Sparkles size={24} className="text-primary" />
                        </div>
                        <div>
                            <h3 className="font-bold text-foreground">AI Kampanya Önerisi</h3>
                            <p className="text-sm text-slate-500">Yapay zeka, verilerinize göre en uygun kampanya stratejisini önerir</p>
                        </div>
                    </div>
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl text-sm font-bold hover:bg-primary/90 transition-all">
                        AI Önerisi Al <ChevronRight size={14} />
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Tags, Search, CheckCircle, RefreshCw,
    TrendingUp, TrendingDown, Minus, Edit3, Save, X,
    Filter, Zap, BarChart3, Loader2, Package
} from 'lucide-react';
import { useProducts, Product } from '@/lib/hooks';
import { apiClient } from '@/lib/api-client';

const marketplaces = [
    { id: 'TRENDYOL', name: 'Trendyol', textColor: 'text-orange-500' },
    { id: 'HEPSIBURADA', name: 'Hepsiburada', textColor: 'text-red-500' },
    { id: 'AMAZON', name: 'Amazon', textColor: 'text-yellow-500' },
    { id: 'N11', name: 'N11', textColor: 'text-purple-500' },
];

export default function ChannelPricingPage() {
    const { data, loading, refetch } = useProducts();
    const rawProducts: Product[] = data ?? [];
    // Local prices overrides map: productId -> { CHANNEL: price }
    const [priceOverrides, setPriceOverrides] = useState<Record<string, Record<string, number>>>({});
    const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
    const [search, setSearch] = useState('');
    const [editingCell, setEditingCell] = useState<{ productId: string; channel: string } | null>(null);
    const [editValue, setEditValue] = useState('');
    const [showBulkModal, setShowBulkModal] = useState(false);
    const [bulkType, setBulkType] = useState<'percent' | 'fixed'>('percent');
    const [bulkValue, setBulkValue] = useState('');
    const [bulkChannel, setBulkChannel] = useState('TRENDYOL');
    const [bulkDirection, setBulkDirection] = useState<'increase' | 'decrease'>('increase');
    const [saving, setSaving] = useState<string | null>(null);

    const products = rawProducts.filter(p =>
        p.name.toLowerCase().includes(search.toLowerCase()) ||
        (p.brand || '').toLowerCase().includes(search.toLowerCase())
    );

    const getChannelPrice = (product: Product, channel: string): number => {
        return priceOverrides[product.id]?.[channel] ?? product.price ?? 0;
    };

    const toggle = (id: string) =>
        setSelectedProducts(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);

    const startEdit = (productId: string, channel: string, value: number) => {
        setEditingCell({ productId, channel });
        setEditValue(String(value));
    };

    const saveEdit = async (productId: string, channel: string) => {
        const newPrice = parseFloat(editValue);
        if (!isNaN(newPrice) && newPrice > 0) {
            setSaving(productId + channel);
            setPriceOverrides(prev => ({
                ...prev,
                [productId]: { ...(prev[productId] || {}), [channel]: newPrice }
            }));
            try {
                await apiClient.updateProduct(productId, { [`price_${channel.toLowerCase()}`]: newPrice });
            } catch { /* Price saved locally at minimum */ }
            setSaving(null);
        }
        setEditingCell(null);
    };

    const applyBulkUpdate = () => {
        const val = parseFloat(bulkValue);
        if (isNaN(val)) return;
        const targetIds = selectedProducts.length > 0 ? selectedProducts : products.map((p: Product) => p.id);
        const newOverrides = { ...priceOverrides };
        for (const pid of targetIds) {
            const product = rawProducts.find(p => p.id === pid);
            if (!product) continue;
            const current = getChannelPrice(product, bulkChannel);
            let newPrice = current;
            if (bulkType === 'percent') {
                newPrice = bulkDirection === 'increase' ? current * (1 + val / 100) : current * (1 - val / 100);
            } else {
                newPrice = bulkDirection === 'increase' ? current + val : current - val;
            }
            newOverrides[pid] = { ...(newOverrides[pid] || {}), [bulkChannel]: Math.max(0, Math.round(newPrice)) };
        }
        setPriceOverrides(newOverrides);
        setShowBulkModal(false);
        setBulkValue('');
    };

    const getPriceDiff = (base: number, channel: number) => {
        if (base === 0) return { diff: 0, higher: false, same: true };
        const diff = ((channel - base) / base) * 100;
        return { diff: Math.round(diff * 10) / 10, higher: channel > base, same: channel === base };
    };

    // Count products with differing channel prices
    const differentPricedCount = rawProducts.filter(p =>
        marketplaces.some(mp => (priceOverrides[p.id]?.[mp.id] ?? p.price) !== p.price)
    ).length;

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <div className="flex items-center gap-3 mb-1">
                        <div className="p-2.5 rounded-xl bg-emerald-500/10 border border-emerald-500/20">
                            <Tags className="w-6 h-6 text-emerald-500" />
                        </div>
                        <h1 className="text-3xl font-black text-foreground tracking-tight">Kanal Bazlı Fiyatlar</h1>
                    </div>
                    <p className="text-slate-500 font-medium ml-14">Her pazaryeri için özel fiyat belirleyin, rekabeti yönetin</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => refetch()}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <RefreshCw size={15} className={loading ? "animate-spin" : ""} /> Yenile
                    </button>
                    <button onClick={() => setShowBulkModal(true)}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <Zap size={15} /> Toplu Güncelle
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Ürün', value: rawProducts.length.toString(), icon: BarChart3, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
                    { label: 'Farklı Fiyatlı', value: differentPricedCount.toString(), icon: Tags, color: 'text-blue-500', bg: 'bg-blue-500/10' },
                    { label: 'Aktif Kanal', value: marketplaces.length.toString(), icon: CheckCircle, color: 'text-purple-500', bg: 'bg-purple-500/10' },
                    { label: 'Seçili', value: selectedProducts.length.toString(), icon: Filter, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
                ].map(s => (
                    <div key={s.label} className="bg-surface rounded-2xl border border-border p-5">
                        <div className={`p-2.5 rounded-xl ${s.bg} w-fit mb-3`}><s.icon className={`w-5 h-5 ${s.color}`} /></div>
                        <div className="text-2xl font-black text-foreground">{s.value}</div>
                        <div className="text-xs text-slate-500 mt-0.5">{s.label}</div>
                    </div>
                ))}
            </div>

            {/* Search */}
            <div className="relative">
                <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Ürün ara..."
                    className="w-full pl-11 pr-4 py-3 bg-surface border border-border rounded-xl text-sm text-foreground placeholder-slate-600 focus:border-emerald-500 outline-none transition-colors" />
            </div>

            {/* Pricing Matrix Table */}
            <div className="bg-surface border border-border rounded-2xl overflow-hidden">
                <div className="grid grid-cols-12 gap-3 px-5 py-4 bg-background/50 border-b border-border">
                    <div className="col-span-1">
                        <input type="checkbox"
                            checked={selectedProducts.length === products.length && products.length > 0}
                            onChange={e => setSelectedProducts(e.target.checked ? products.map((p: Product) => p.id) : [])}
                            className="rounded" />
                    </div>
                    <div className="col-span-3 text-[10px] font-black text-slate-500 uppercase tracking-wider">Ürün</div>
                    <div className="col-span-1 text-[10px] font-black text-slate-500 uppercase tracking-wider">Taban</div>
                    {marketplaces.map(mp => (
                        <div key={mp.id} className="col-span-1 text-center">
                            <span className={`text-[10px] font-black uppercase tracking-wider ${mp.textColor}`}>{mp.name}</span>
                        </div>
                    ))}
                    <div className="col-span-1 text-[10px] font-black text-slate-500 uppercase tracking-wider text-center">Stok</div>
                </div>

                {loading && rawProducts.length === 0 && (
                    <div className="py-20 flex items-center justify-center gap-3 text-slate-500">
                        <Loader2 size={20} className="animate-spin" />
                        <span className="text-sm font-medium">Ürünler yükleniyor...</span>
                    </div>
                )}

                {!loading && products.length === 0 && (
                    <div className="py-20 flex flex-col items-center justify-center gap-3 text-slate-500">
                        <Package size={40} className="text-slate-300" />
                        <div className="text-center">
                            <p className="font-bold text-foreground">Ürün bulunamadı</p>
                            <p className="text-sm mt-1">Fiyat matrisi ürünler eklendikçe dolar.</p>
                        </div>
                    </div>
                )}

                {products.map((product, idx) => (
                    <motion.div key={product.id}
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: idx * 0.03 }}
                        className={`grid grid-cols-12 gap-3 items-center px-5 py-4 border-b border-border last:border-0 hover:bg-white/2 transition-colors ${selectedProducts.includes(product.id) ? 'bg-emerald-500/3' : ''}`}>
                        <div className="col-span-1">
                            <input type="checkbox" checked={selectedProducts.includes(product.id)} onChange={() => toggle(product.id)} className="rounded" />
                        </div>
                        <div className="col-span-3">
                            <div className="font-bold text-sm text-foreground truncate">{product.name}</div>
                            <div className="text-[10px] text-slate-500">{product.brand} · {product.category}</div>
                        </div>
                        <div className="col-span-1">
                            <div className="text-sm font-black text-foreground">₺{product.price.toLocaleString('tr-TR')}</div>
                            <div className="text-[10px] text-slate-600">Taban</div>
                        </div>
                        {marketplaces.map(mp => {
                            const price = getChannelPrice(product, mp.id);
                            const { diff, higher, same } = getPriceDiff(product.price, price);
                            const isEditing = editingCell?.productId === product.id && editingCell?.channel === mp.id;
                            const isSaving = saving === product.id + mp.id;
                            return (
                                <div key={mp.id} className="col-span-1 text-center">
                                    {isEditing ? (
                                        <div className="flex items-center gap-1">
                                            <input autoFocus value={editValue} onChange={e => setEditValue(e.target.value)}
                                                onKeyDown={e => { if (e.key === 'Enter') saveEdit(product.id, mp.id); if (e.key === 'Escape') setEditingCell(null); }}
                                                className="w-full px-2 py-1 bg-background border border-emerald-500 rounded-lg text-xs text-foreground text-center focus:outline-none" />
                                            <button onClick={() => saveEdit(product.id, mp.id)} className="p-1 text-green-500 hover:text-green-400"><Save size={12} /></button>
                                            <button onClick={() => setEditingCell(null)} className="p-1 text-slate-500 hover:text-red-400"><X size={12} /></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => startEdit(product.id, mp.id, price)}
                                            className="group flex flex-col items-center w-full hover:bg-white/5 rounded-xl p-1.5 transition-all">
                                            {isSaving ? (
                                                <Loader2 size={16} className="animate-spin text-emerald-500" />
                                            ) : (
                                                <>
                                                    <div className="text-sm font-bold text-foreground group-hover:text-emerald-400 transition-colors">
                                                        ₺{price.toLocaleString('tr-TR')}
                                                    </div>
                                                    {!same && (
                                                        <div className={`flex items-center gap-0.5 text-[9px] font-bold ${higher ? 'text-green-500' : 'text-red-500'}`}>
                                                            {higher ? <TrendingUp size={8} /> : <TrendingDown size={8} />}
                                                            {higher ? '+' : ''}{diff}%
                                                        </div>
                                                    )}
                                                    {same && <div className="text-[9px] text-slate-600 flex items-center gap-0.5"><Minus size={8} /> Aynı</div>}
                                                    <Edit3 size={9} className="opacity-0 group-hover:opacity-100 text-slate-500 mt-0.5 transition-opacity" />
                                                </>
                                            )}
                                        </button>
                                    )}
                                </div>
                            );
                        })}
                        <div className="col-span-1 text-center">
                            <span className={`text-sm font-bold ${product.stock < 5 ? 'text-red-500' : 'text-foreground'}`}>{product.stock}</span>
                            {product.stock < 5 && <div className="text-[9px] text-red-500/70">Kritik</div>}
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Bulk Update Modal */}
            <AnimatePresence>
                {showBulkModal && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm"
                        onClick={() => setShowBulkModal(false)}>
                        <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }}
                            onClick={e => e.stopPropagation()}
                            className="bg-surface border border-border rounded-2xl p-6 w-full max-w-lg mx-4 shadow-2xl space-y-5">
                            <div className="flex items-center justify-between">
                                <h3 className="text-lg font-bold text-foreground">Toplu Fiyat Güncelleme</h3>
                                <button onClick={() => setShowBulkModal(false)} className="p-1.5 rounded-lg hover:bg-background text-slate-400"><X size={18} /></button>
                            </div>

                            {selectedProducts.length > 0 ? (
                                <div className="bg-emerald-500/5 border border-emerald-500/20 rounded-xl px-4 py-3 text-sm text-emerald-400">
                                    {selectedProducts.length} ürün seçili — sadece bunlar güncellenecek
                                </div>
                            ) : (
                                <div className="bg-yellow-500/5 border border-yellow-500/20 rounded-xl px-4 py-3 text-sm text-yellow-400">
                                    Tüm ürünler güncellenecek (filtreli)
                                </div>
                            )}

                            <div className="space-y-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">Hedef Kanal</label>
                                    <div className="grid grid-cols-4 gap-2">
                                        {marketplaces.map(mp => (
                                            <button key={mp.id} onClick={() => setBulkChannel(mp.id)}
                                                className={`py-2.5 rounded-xl text-xs font-bold border transition-all ${bulkChannel === mp.id ? `${mp.textColor} border-current bg-current/10` : 'border-border text-slate-400 hover:text-foreground'}`}>
                                                {mp.name}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">İşlem Yönü</label>
                                    <div className="grid grid-cols-2 gap-2">
                                        {[{ id: 'increase', label: 'Artır', icon: TrendingUp }, { id: 'decrease', label: 'Azalt', icon: TrendingDown }].map(d => (
                                            <button key={d.id} onClick={() => setBulkDirection(d.id as any)}
                                                className={`flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-bold border transition-all ${bulkDirection === d.id ? 'bg-emerald-600 text-white border-transparent' : 'border-border text-slate-400 hover:text-foreground'}`}>
                                                <d.icon size={14} /> {d.label}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">Güncelleme Tipi</label>
                                    <div className="grid grid-cols-2 gap-2">
                                        {[{ id: 'percent', label: '% Yüzde' }, { id: 'fixed', label: '₺ Sabit Miktar' }].map(t => (
                                            <button key={t.id} onClick={() => setBulkType(t.id as any)}
                                                className={`py-2.5 rounded-xl text-sm font-bold border transition-all ${bulkType === t.id ? 'bg-emerald-600 text-white border-transparent' : 'border-border text-slate-400 hover:text-foreground'}`}>
                                                {t.label}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">
                                        {bulkType === 'percent' ? 'Yüzde Değeri (%)' : 'Miktar (₺)'}
                                    </label>
                                    <input value={bulkValue} onChange={e => setBulkValue(e.target.value)} type="number" placeholder={bulkType === 'percent' ? 'Örn: 10' : 'Örn: 500'}
                                        className="w-full px-4 py-3 bg-background border border-border rounded-xl text-sm text-foreground placeholder-slate-600 focus:border-emerald-500 outline-none transition-colors" />
                                </div>
                                <button onClick={applyBulkUpdate} disabled={!bulkValue}
                                    className="w-full py-3 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-500 transition-all disabled:opacity-40">
                                    Fiyatları Güncelle
                                </button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion as m } from 'framer-motion';
import {
    Calculator, DollarSign, PieChart, ShoppingCart,
    ArrowRight, Info, AlertTriangle, CheckCircle2,
    Store, Truck, TrendingUp, Download, RefreshCw
} from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface CalculationResult {
    platform: string;
    commissionRate: number;
    commissionAmount: number;
    shippingFee: number;
    vatAmount: number;
    serviceFee: number;
    netProfit: number;
    margin: number;
}

const platforms = [
    { id: 'trendyol', name: 'Trendyol', logo: 'https://cdn.dsmcdn.com/sfid/production/trendyol-logo-2.png' },
    { id: 'hepsiburada', name: 'Hepsiburada', logo: 'https://images.hepsiburada.net/assets/sfid/production/hepsiburada-logo.png' },
    { id: 'amazon', name: 'Amazon', logo: 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Amazon_logo.svg' },
    { id: 'n11', name: 'N11', logo: 'https://n11scdn.akamaized.net/a1/org/logo/n11-logo.svg' }
];

export default function CommissionCalculatorPage() {
    const [price, setPrice] = useState<string>('500');
    const [cost, setCost] = useState<string>('200');
    const [category, setCategory] = useState<string>('Elektronik');
    const [isCalculating, setIsCalculating] = useState(false);
    const [results, setResults] = useState<CalculationResult[]>([]);

    const calculate = async () => {
        setIsCalculating(true);
        try {
            const payload = {
                price: parseFloat(price) || 0,
                cost: parseFloat(cost) || 0,
                category,
            };
            const data = await apiClient.request<any[]>('/finance/calculate-commission', {
                method: 'POST',
                body: JSON.stringify(payload),
            });

            const normalized: CalculationResult[] = Array.isArray(data)
                ? data.map((r) => ({
                    platform: String(r.platform || '-'),
                    commissionRate: Number(r.commissionRate || 0),
                    commissionAmount: Number(r.commissionAmount || 0),
                    shippingFee: Number(r.shippingFee || 0),
                    vatAmount: Number(r.vatAmount || 0),
                    serviceFee: Number(r.serviceFee || 0),
                    netProfit: Number(r.netProfit || 0),
                    margin: Number(r.margin || 0),
                }))
                : [];
            setResults(normalized);
        } catch {
            setResults([]);
        }
        setIsCalculating(false);
    };

    useEffect(() => {
        calculate();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div>
                <h1 className="text-3xl font-black text-foreground flex items-center gap-3">
                    <Calculator className="w-8 h-8 text-indigo-500" /> Komisyon Tahminleyici
                </h1>
                <p className="text-slate-500 mt-1 font-medium">Satış fiyatı ve maliyet üzerinden net kârınızı hesaplayın</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Input Section */}
                <div className="lg:col-span-1 space-y-6">
                    <div className="bg-surface rounded-2xl border border-border p-6 shadow-sm">
                        <h2 className="text-lg font-bold text-foreground mb-4">Girdi Bilgileri</h2>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Satış Fiyatı (₺)</label>
                                <div className="relative">
                                    <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                    <input
                                        type="number"
                                        value={price}
                                        onChange={(e) => setPrice(e.target.value)}
                                        className="w-full bg-background border border-border rounded-xl py-3 pl-10 pr-4 text-foreground focus:outline-none focus:border-indigo-500/50"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Ürün Maliyeti (₺)</label>
                                <div className="relative">
                                    <ShoppingCart className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                    <input
                                        type="number"
                                        value={cost}
                                        onChange={(e) => setCost(e.target.value)}
                                        className="w-full bg-background border border-border rounded-xl py-3 pl-10 pr-4 text-foreground focus:outline-none focus:border-indigo-500/50"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Ürün Kategorisi</label>
                                <select
                                    value={category}
                                    onChange={(e) => setCategory(e.target.value)}
                                    className="w-full bg-background border border-border rounded-xl py-3 px-4 text-foreground focus:outline-none focus:border-indigo-500/50"
                                >
                                    <option>Elektronik</option>
                                    <option>Moda & Giyim</option>
                                    <option>Ev & Yaşam</option>
                                    <option>Kozmetik</option>
                                    <option>Anne & Bebek</option>
                                </select>
                            </div>
                            <button
                                onClick={calculate}
                                disabled={isCalculating}
                                className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-indigo-600/20 flex items-center justify-center gap-2"
                            >
                                {isCalculating ? <RefreshCw className="w-4 h-4 animate-spin" /> : <TrendingUp className="w-4 h-4" />}
                                {isCalculating ? 'Hesaplanıyor...' : 'Kar Karşılaştır'}
                            </button>
                        </div>
                    </div>

                    <div className="bg-amber-500/5 border border-amber-500/20 rounded-2xl p-4 flex gap-3">
                        <Info className="w-5 h-5 text-amber-500 shrink-0" />
                        <p className="text-xs text-amber-600/80 leading-relaxed font-medium">
                            Hesaplamalar pazaryerlerinin standart komisyon oranları ve ortalama kargo maliyetleri üzerinden yapılmaktadır. Sözleşmenize özel oranlar farklılık gösterebilir.
                        </p>
                    </div>
                </div>

                {/* Results Section */}
                <div className="lg:col-span-2 space-y-4">
                    <h2 className="text-lg font-bold text-foreground">Karşılaştırmalı Analiz</h2>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {results.length === 0 && (
                            <div className="md:col-span-2 bg-surface rounded-2xl border border-border p-5 text-sm text-slate-500">
                                Komisyon hesaplama verisi bulunamadi
                            </div>
                        )}
                        {results.map((res, i) => (
                            <m.div
                                key={res.platform}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: i * 0.1 }}
                                className="bg-surface rounded-2xl border border-border overflow-hidden group hover:border-indigo-500/30 transition-all"
                            >
                                <div className="p-5 border-b border-border bg-background/30 flex items-center justify-between">
                                    <div className="font-black text-foreground">{res.platform}</div>
                                    <div className={`text-xs font-bold px-2 py-1 rounded-full ${res.margin > 20 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'}`}>
                                        %{res.margin.toFixed(1)} Marj
                                    </div>
                                </div>
                                <div className="p-5 space-y-3">
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500">Komisyon (%{res.commissionRate})</span>
                                        <span className="font-bold text-red-400">-₺{res.commissionAmount.toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500">Kargo Maliyeti</span>
                                        <span className="font-bold text-red-400">-₺{res.shippingFee.toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500">KDV (%20)</span>
                                        <span className="font-bold text-red-400">-₺{res.vatAmount.toFixed(2)}</span>
                                    </div>
                                    <div className="border-t border-border pt-3 flex justify-between">
                                        <span className="font-bold text-foreground">Net Kâr</span>
                                        <span className={`text-xl font-black ${res.netProfit > 0 ? 'text-emerald-500' : 'text-red-500'}`}>
                                            ₺{res.netProfit.toFixed(2)}
                                        </span>
                                    </div>
                                </div>
                            </m.div>
                        ))}
                    </div>

                    <div className="bg-surface rounded-2xl border border-border p-6 shadow-sm overflow-hidden relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10">
                            <PieChart size={120} className="text-indigo-500" />
                        </div>
                        <h3 className="text-sm font-bold text-foreground mb-4">Gider Dağılımı</h3>
                        <div className="space-y-4 relative z-10">
                            {results[0] && [
                                { label: 'Komisyon', val: results[0].commissionAmount, color: 'bg-indigo-500' },
                                { label: 'Kargo', val: results[0].shippingFee, color: 'bg-blue-500' },
                                { label: 'Vergi', val: results[0].vatAmount, color: 'bg-purple-500' }
                            ].map(item => {
                                const total = results[0].commissionAmount + results[0].shippingFee + results[0].vatAmount;
                                const pct = (item.val / total) * 100;
                                return (
                                    <div key={item.label} className="space-y-1">
                                        <div className="flex justify-between text-[10px] uppercase font-black tracking-widest text-slate-500">
                                            <span>{item.label}</span>
                                            <span>%{pct.toFixed(0)}</span>
                                        </div>
                                        <div className="h-2 bg-background rounded-full overflow-hidden">
                                            <m.div
                                                initial={{ width: 0 }}
                                                animate={{ width: `${pct}%` }}
                                                className={`h-full ${item.color}`}
                                            />
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Target, TrendingUp, TrendingDown, AlertTriangle,
    Search, Filter, RefreshCw, BarChart3, ArrowUpRight,
    ArrowDownRight, Eye, ExternalLink, ShieldAlert,
    Clock, Zap, ShoppingCart, Globe, Boxes, Edit2
} from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface CompetitorProduct {
    id: string;
    name: string;
    sku: string;
    myPrice: number;
    competitorPrice: number;
    diff: number;
    platform: string;
    competitorName: string;
    buyBox: boolean;
    status: 'under' | 'over' | 'equal';
    lastUpdate: string;
}

export default function CompetitorTrackingPage() {
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [products, setProducts] = useState<CompetitorProduct[]>([]);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                const data = await apiClient.getCompetitors() as any[];
                const normalized: CompetitorProduct[] = Array.isArray(data)
                    ? data.map((p, i) => {
                        const myPrice = Number(p.myPrice ?? p.ourPrice ?? 0);
                        const competitorPrice = Number(p.competitorPrice ?? p.price ?? 0);
                        const diff = competitorPrice - myPrice;
                        return {
                            id: String(p.id ?? i + 1),
                            name: p.name || p.productName || '-',
                            sku: p.sku || '-',
                            myPrice,
                            competitorPrice,
                            diff,
                            platform: p.platform || '-',
                            competitorName: p.competitorName || p.storeName || '-',
                            buyBox: Boolean(p.buyBox),
                            status: diff < 0 ? 'over' : diff > 0 ? 'under' : 'equal',
                            lastUpdate: p.lastUpdate || p.updatedAt || '-',
                        };
                    })
                    : [];
                setProducts(normalized);
            } catch {
                setProducts([]);
            }
            setLoading(false);
        };
        fetchData();
    }, []);

    const filtered = products.filter(p =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.sku.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const stats = {
        buyBoxCount: products.filter(p => p.buyBox).length,
        underPriced: products.filter(p => p.status === 'over').length,
        totalTracked: products.length
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="flex flex-col items-center gap-4">
                    <RefreshCw className="w-8 h-8 text-primary animate-spin" />
                    <p className="text-slate-500 font-medium">Rakip fiyatlar taranıyor...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground flex items-center gap-3">
                        <ShieldAlert className="w-8 h-8 text-red-500" /> Rakip Takibi
                    </h1>
                    <p className="text-slate-500 mt-1 font-medium">Rakiplerinizin fiyat hamlelerini anlık izleyin ve Buy Box&apos;ı koruyun</p>
                </div>
                <div className="flex items-center gap-3">
                    <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80">
                        <RefreshCw size={16} /> Anlık Tara
                    </button>
                    <button className="flex items-center gap-2 px-6 py-2.5 bg-primary text-white rounded-xl font-bold transition-all shadow-lg shadow-primary/20">
                        <Target size={18} /> Yeni Rakip İzle
                    </button>
                </div>
            </div>

            {/* Insight Grid */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-surface rounded-2xl border border-border p-6 shadow-sm relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:scale-110 transition-transform">
                        <BarChart3 size={100} className="text-emerald-500" />
                    </div>
                    <div className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Buy Box Sahipliği</div>
                    <div className="text-4xl font-black text-foreground">%{((stats.buyBoxCount / stats.totalTracked) * 100).toFixed(0)}</div>
                    <p className="text-xs text-slate-500 mt-2 font-medium">{stats.buyBoxCount} üründe Buy Box sizde</p>
                </div>

                <div className="bg-surface rounded-2xl border border-border p-6 shadow-sm relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:scale-110 transition-transform">
                        <TrendingDown size={100} className="text-red-500" />
                    </div>
                    <div className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Yüksek Fiyat Kalan</div>
                    <div className="text-4xl font-black text-red-500">{stats.underPriced} Ürün</div>
                    <p className="text-xs text-slate-500 mt-2 font-medium">Bu ürünlerde rakiplerinizden pahalısınız</p>
                </div>

                <div className="bg-gradient-to-br from-primary to-indigo-600 rounded-2xl p-6 text-white shadow-xl shadow-primary/20 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-8 opacity-10">
                        <Zap size={100} />
                    </div>
                    <h3 className="text-lg font-black mb-1">Akıllı Fiyatlama</h3>
                    <p className="text-primary-100 text-xs font-medium leading-relaxed mb-4">
                        Rakipleriniz fiyat değiştirdiğinde sistem sizin yerinize tepki versin ister misiniz?
                    </p>
                    <button className="px-5 py-2 bg-white text-primary font-black rounded-lg text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-lg">
