﻿"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  RefreshCw,
  TrendingUp,
  TrendingDown,
  DollarSign,
  ArrowRightLeft,
  Clock,
  BarChart3,
  Globe,
  Calculator,
  History,
  ArrowRight
} from 'lucide-react';

interface ExchangeRate {
  currency: string;
  rate: number;
  change: number;
  baseCurrency: string;
}

const currencyFlags: Record<string, string> = {
  USD: '🇺🇸',
  EUR: '🇪🇺',
  GBP: '🇬🇧',
  TRY: '🇹🇷',
};

const currencyNames: Record<string, string> = {
  USD: 'Amerikan Doları',
  EUR: 'Euro',
  GBP: 'İngiliz Sterlini',
  TRY: 'Türk Lirası',
};

export default function CurrencyPage() {
  const [rates, setRates] = useState<ExchangeRate[]>([]);
  const [loading, setLoading] = useState(true);
  const [fromCurrency, setFromCurrency] = useState('USD');
  const [toCurrency, setToCurrency] = useState('TRY');
  const [amount, setAmount] = useState(1);
  const [convertedAmount, setConvertedAmount] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());

  useEffect(() => {
    setRates([
      { currency: 'USD', rate: 38.50, change: 0.25, baseCurrency: 'TRY' },
      { currency: 'EUR', rate: 40.80, change: -0.15, baseCurrency: 'TRY' },
      { currency: 'GBP', rate: 48.50, change: 0.40, baseCurrency: 'TRY' },
    ]);
    setLoading(false);
    setLastUpdate(new Date());
  }, []);

  const handleConvert = () => {
    if (fromCurrency === toCurrency) {
      setConvertedAmount(amount);
      return;
    }
    const fromRate = fromCurrency === 'TRY' ? 1 : rates.find(r => r.currency === fromCurrency)?.rate || 1;
    const toRate = toCurrency === 'TRY' ? 1 : rates.find(r => r.currency === toCurrency)?.rate || 1;
    setConvertedAmount(Math.round((amount * fromRate / toRate) * 100) / 100);
  };

  useEffect(() => {
    handleConvert();
  }, [amount, fromCurrency, toCurrency, rates]);

  const formatCurrency = (amount: number, currency: string) =>
    new Intl.NumberFormat('tr-TR', { style: 'currency', currency, minimumFractionDigits: 2 }).format(amount);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-foreground tracking-tight">Döviz Kurları</h1>
          <p className="text-slate-500 font-medium">TCMB güncel kurları ve döviz çevirici</p>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-sm text-slate-400 flex items-center gap-1.5">
            <Clock size={14} />
            Son güncelleme: {lastUpdate.toLocaleTimeString('tr-TR')}
          </span>
          <button className="flex items-center gap-2 px-4 py-2.5 border border-border rounded-xl font-semibold hover:bg-surface transition-colors">
            <RefreshCw size={18} />
            Güncelle
          </button>
        </div>
      </div>

      {/* Rate Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {rates.map((rate, i) => (
          <motion.div
            key={rate.currency}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.1 }}
            className="bg-surface border border-border rounded-2xl p-6"
          >
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <span className="text-3xl">{currencyFlags[rate.currency]}</span>
                <div>
                  <p className="font-bold text-foreground text-lg">{rate.currency}/TRY</p>
                  <p className="text-xs text-slate-400">{currencyNames[rate.currency]}</p>
                </div>
              </div>
              <div className={`flex items-center gap-1 px-2 py-1 rounded-lg text-xs font-semibold ${rate.change >= 0 ? 'text-green-600 bg-green-100' : 'text-red-600 bg-red-100'}`}>
                {rate.change >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
                {rate.change >= 0 ? '+' : ''}{rate.change.toFixed(2)}%
              </div>
            </div>
            <p className="text-3xl font-black text-foreground">{rate.rate.toFixed(4)}</p>
            <p className="text-sm text-slate-400 mt-1">1 {rate.currency} = {rate.rate.toFixed(4)} TRY</p>
          </motion.div>
        ))}
      </div>

      {/* Currency Converter */}
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }} className="bg-surface border border-border rounded-2xl p-6">
        <div className="flex items-center gap-2 mb-6">
          <Calculator className="w-5 h-5 text-primary" />
          <h2 className="text-xl font-bold text-foreground">Döviz Çevirici</h2>
        </div>
        <div className="flex flex-col md:flex-row items-center gap-4">
          <div className="flex-1 w-full">
            <label className="text-sm font-medium text-slate-500 mb-1 block">Tutar</label>
            <div className="flex gap-2">
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(Number(e.target.value))}
                className="flex-1 px-4 py-3 border border-border rounded-xl bg-background text-foreground font-semibold text-lg focus:outline-none focus:ring-2 focus:ring-primary/20"
              />
              <select
                value={fromCurrency}
                onChange={(e) => setFromCurrency(e.target.value)}
                className="px-4 py-3 border border-border rounded-xl bg-background text-foreground font-semibold focus:outline-none focus:ring-2 focus:ring-primary/20"
              >
                <option value="USD">USD</option>
                <option value="EUR">EUR</option>
                <option value="GBP">GBP</option>
                <option value="TRY">TRY</option>
              </select>
            </div>
          </div>
          <div className="flex items-center justify-center">
            <div className="p-3 bg-primary/10 rounded-full">
              <ArrowRightLeft className="w-5 h-5 text-primary" />
            </div>
          </div>
          <div className="flex-1 w-full">
            <label className="text-sm font-medium text-slate-500 mb-1 block">Sonuç</label>
            <div className="flex gap-2">
              <div className="flex-1 px-4 py-3 border border-border rounded-xl bg-background/50 text-foreground font-semibold text-lg">
                {convertedAmount !== null ? convertedAmount.toLocaleString('tr-TR', { minimumFractionDigits: 2 }) : '-'}
              </div>
              <select
                value={toCurrency}
                onChange={(e) => setToCurrency(e.target.value)}
                className="px-4 py-3 border border-border rounded-xl bg-background text-foreground font-semibold focus:outline-none focus:ring-2 focus:ring-primary/20"
              >
                <option value="TRY">TRY</option>
                <option value="USD">USD</option>
                <option value="EUR">EUR</option>
                <option value="GBP">GBP</option>
              </select>
            </div>
          </div>
        </div>
        {convertedAmount !== null && (
          <p className="text-center text-sm text-slate-400 mt-4">
            {amount} {fromCurrency} = {convertedAmount.toLocaleString('tr-TR', { minimumFractionDigits: 2 })} {toCurrency}
          </p>
        )}
      </motion.div>

      {/* Rate History Placeholder */}
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }} className="bg-surface border border-border rounded-2xl p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-2">
            <History className="w-5 h-5 text-primary" />
            <h2 className="text-xl font-bold text-foreground">Kur Geçmişi</h2>
          </div>
          <select className="px-3 py-1.5 border border-border rounded-lg text-sm bg-background text-foreground">
            <option>Son 7 gün</option>
            <option>Son 30 gün</option>
            <option>Son 90 gün</option>
          </select>
        </div>
        <div className="h-48 flex items-center justify-center text-slate-400">
          <div className="text-center">
            <BarChart3 className="w-12 h-12 mx-auto mb-3 opacity-50" />
            <p className="font-semibold">Grafik yakında eklenecek</p>
            <p className="text-sm">TCMB kur geçmişi grafikleri burada gösterilecek</p>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Star, Users, TrendingUp, TrendingDown, Search, Filter,
    Eye, ShoppingCart, DollarSign, Heart, Award, Medal,
    ArrowUpRight, ArrowDownRight, ChevronDown
} from 'lucide-react';

const customers: any[] = [];

const tierConfig: Record<string, { color: string; bg: string; icon: typeof Star }> = {
    Platin: { color: 'text-violet-400', bg: 'bg-violet-500/10', icon: Award },
    Altın: { color: 'text-amber-400', bg: 'bg-amber-500/10', icon: Medal },
    Gümüş: { color: 'text-slate-300', bg: 'bg-slate-500/10', icon: Star },
    Bronz: { color: 'text-orange-400', bg: 'bg-orange-500/10', icon: Star },
};

const getScoreColor = (s: number) => s >= 80 ? 'text-emerald-400' : s >= 60 ? 'text-amber-400' : 'text-red-400';
const getScoreBg = (s: number) => s >= 80 ? 'bg-emerald-500' : s >= 60 ? 'bg-amber-500' : 'bg-red-500';

export default function CustomerScoringPage() {
    const [searchTerm, setSearchTerm] = useState('');
    const [tierFilter, setTierFilter] = useState('all');
    const [sortBy, setSortBy] = useState<'score' | 'spent'>('score');
    const [selectedCustomer, setSelectedCustomer] = useState<number | null>(null);

    const filtered = customers
        .filter(c => (tierFilter === 'all' || c.tier === tierFilter) && c.name.toLowerCase().includes(searchTerm.toLowerCase()))
        .sort((a, b) => sortBy === 'score' ? b.score - a.score : b.totalSpent - a.totalSpent);

    const avgScore = customers.length > 0 ? Math.round(customers.reduce((a, c) => a + c.score, 0) / customers.length) : 0;
    const totalSpent = customers.reduce((a, c) => a + c.totalSpent, 0);

    const selected = customers.find(c => c.id === selectedCustomer);

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                        <Star className="w-7 h-7 text-indigo-400" /> Müşteri Puanlama Sistemi
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">Müşterilerinizi puanlayın ve segmentleyin</p>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Müşteri', value: customers.length, icon: Users, color: 'text-indigo-400' },
                    { label: 'Ort. Puan', value: avgScore, icon: Star, color: getScoreColor(avgScore) },
                    { label: 'Platin Müşteri', value: customers.filter(c => c.tier === 'Platin').length, icon: Award, color: 'text-violet-400' },
                    { label: 'Toplam Gelir', value: `₺${(totalSpent / 1000).toFixed(0)}K`, icon: DollarSign, color: 'text-emerald-400' },
                ].map((stat, i) => (
                    <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                        className="bg-surface rounded-xl border border-border p-5">
                        <stat.icon className={`w-5 h-5 ${stat.color} mb-2`} />
                        <div className="text-2xl font-bold text-foreground">{stat.value}</div>
                        <div className="text-xs text-slate-500">{stat.label}</div>
                    </motion.div>
                ))}
            </div>

            {/* Tier Distribution */}
            <div className="bg-surface rounded-xl border border-border p-5">
                <h3 className="text-sm font-semibold text-foreground mb-3">Kademe Dağılımı</h3>
                <div className="flex gap-3">
                    {Object.entries(tierConfig).map(([tier, cfg]) => {
                        const count = customers.filter(c => c.tier === tier).length;
                        const pct = customers.length > 0 ? Math.round((count / customers.length) * 100) : 0;
                        return (
                            <div key={tier} className="flex-1 text-center p-3 rounded-xl bg-background">
                                <cfg.icon className={`w-5 h-5 ${cfg.color} mx-auto mb-1`} />
                                <div className="text-lg font-bold text-foreground">{count}</div>
                                <div className="text-xs text-slate-500">{tier} (%{pct})</div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Filters */}
            <div className="flex gap-3">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Müşteri ara..."
                        className="w-full pl-10 pr-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                </div>
                <select value={tierFilter} onChange={e => setTierFilter(e.target.value)}
                    className="px-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border">
                    <option value="all">Tüm Kademeler</option>
                    {Object.keys(tierConfig).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
                <select value={sortBy} onChange={e => setSortBy(e.target.value as 'score' | 'spent')}
                    className="px-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border">
                    <option value="score">Puan</option>
                    <option value="spent">Toplam Harcama</option>
                </select>
            </div>

            <div className="grid grid-cols-3 gap-6">
                {/* Customer List */}
                <div className="col-span-2 space-y-3">
                    {filtered.length === 0 && (
                        <div className="bg-surface rounded-xl border border-border p-6 text-sm text-slate-500">Müşteri puanlama verisi bulunamadı</div>
                    )}
                    {filtered.map((c, i) => {
                        const tCfg = tierConfig[c.tier];
                        return (
                            <motion.div key={c.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
                                onClick={() => setSelectedCustomer(c.id)}
                                className={`bg-surface rounded-xl border p-5 cursor-pointer transition-all ${selectedCustomer === c.id ? 'border-indigo-500/50' : 'border-border hover:border-indigo-500/20'}`}>
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-full ${tCfg.bg} flex items-center justify-center`}>
                                            <tCfg.icon className={`w-5 h-5 ${tCfg.color}`} />
                                        </div>
                                        <div>
                                            <div className="text-sm font-medium text-foreground">{c.name}</div>
                                            <div className="text-xs text-slate-500">{c.email}</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <span className={`px-2 py-0.5 rounded-full text-xs ${tCfg.bg} ${tCfg.color}`}>{c.tier}</span>
                                        <div className="text-right">
                                            <div className={`text-xl font-bold ${getScoreColor(c.score)}`}>{c.score}</div>
                                            <div className="flex items-center gap-0.5 text-[10px]">
                                                {c.trend === 'up' ? <ArrowUpRight className="w-3 h-3 text-emerald-400" /> : c.trend === 'down' ? <ArrowDownRight className="w-3 h-3 text-red-400" /> : null}
                                                <span className={c.trend === 'up' ? 'text-emerald-400' : c.trend === 'down' ? 'text-red-400' : 'text-slate-500'}>{c.trend === 'up' ? 'Yükseliyor' : c.trend === 'down' ? 'Düşüyor' : 'Sabit'}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex gap-4 text-xs text-slate-500">
                                    <span className="flex items-center gap-1"><ShoppingCart className="w-3 h-3" /> {c.orders} sipariş</span>
                                    <span className="flex items-center gap-1"><DollarSign className="w-3 h-3" /> ₺{c.totalSpent.toLocaleString()}</span>
                                    <span>Ort: ₺{c.avgOrder}</span>
                                    <span className="flex items-center gap-1"><Eye className="w-3 h-3" /> {c.lastOrder}</span>
                                </div>
                            </motion.div>
                        );
                    })}
                </div>

                {/* Detail */}
                <div>
                    {selected ? (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="bg-surface rounded-xl border border-border p-5 sticky top-6 space-y-4">
                            <div className="text-center">
                                <div className={`inline-flex p-3 rounded-full ${tierConfig[selected.tier].bg} mb-2`}>
                                    {React.createElement(tierConfig[selected.tier].icon, { className: `w-6 h-6 ${tierConfig[selected.tier].color}` })}
                                </div>
                                <h3 className="text-sm font-semibold text-foreground">{selected.name}</h3>
                                <p className="text-xs text-slate-500">{selected.tier} Müşteri</p>
                            </div>
                            <div className="text-center">
                                <div className={`text-4xl font-bold ${getScoreColor(selected.score)}`}>{selected.score}</div>
                                <div className="h-2 bg-background rounded-full mt-2">
                                    <div className={`h-full rounded-full ${getScoreBg(selected.score)}`} style={{ width: `${selected.score}%` }} />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <h4 className="text-xs text-slate-400 font-medium">RFM Skorları</h4>
                                {[
                                    { label: 'Recency (Yenilik)', value: selected.rfmR },
                                    { label: 'Frequency (Sıklık)', value: selected.rfmF },
                                    { label: 'Monetary (Tutar)', value: selected.rfmM },
                                ].map((r, i) => (
                                    <div key={i} className="flex items-center justify-between">
                                        <span className="text-xs text-slate-500">{r.label}</span>
                                        <div className="flex gap-0.5">
                                            {[1, 2, 3, 4, 5].map(s => (
                                                <div key={s} className={`w-4 h-4 rounded ${s <= r.value ? 'bg-indigo-500' : 'bg-background'}`} />
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <div className="pt-2 border-t border-border space-y-2 text-xs">
                                <div className="flex justify-between"><span className="text-slate-500">Toplam Harcama</span><span className="text-foreground">₺{selected.totalSpent.toLocaleString()}</span></div>
                                <div className="flex justify-between"><span className="text-slate-500">Sipariş Sayısı</span><span className="text-foreground">{selected.orders}</span></div>
                                <div className="flex justify-between"><span className="text-slate-500">Ort. Sepet</span><span className="text-foreground">₺{selected.avgOrder}</span></div>
                                <div className="flex justify-between"><span className="text-slate-500">Son Sipariş</span><span className="text-foreground">{selected.lastOrder}</span></div>
                            </div>
                        </motion.div>
                    ) : (
                        <div className="bg-surface rounded-xl border border-border p-5 text-center">
                            <Users className="w-8 h-8 text-slate-600 mx-auto mb-2" />
                            <p className="text-xs text-slate-500">Detay görmek için müşteri seçin</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { motion } from 'framer-motion';
import {
    Users, Target, TrendingUp, DollarSign, ShoppingCart,
    Crown, Heart, Award, Star, Download, Mail, Loader2, RefreshCw, BarChart3
} from 'lucide-react';
import { useRFMAnalysis } from '@/lib/hooks';

interface Segment {
    id: string;
    name: string;
    count: number;
    revenue: string | number;
    avgOrder: string | number;
    frequency: string | number;
    color: string;
    description?: string;
    percentage?: number;
}

interface RFMEntry {
    customer: string;
    recency: number;
    frequency: number;
    monetary: string | number;
    segment: string;
    score: number;
}

const SEGMENT_ICONS: Record<string, React.ComponentType> = {
    vip: Crown, VIP: Crown, 'VIP Müşteriler': Crown,
    'Sadık': Heart, 'Düzenli': ShoppingCart,
    'Yeni': Star, 'Uyuyan': Target,
    'Yüksek Potansiyel': Award,
};

const COLOR_CLASSES: Record<string, { bg: string; text: string; border: string; bar: string }> = {
    amber: { bg: 'bg-amber-500/10', text: 'text-amber-500', border: 'border-amber-500/20', bar: 'bg-amber-500' },
    blue: { bg: 'bg-blue-500/10', text: 'text-blue-500', border: 'border-blue-500/20', bar: 'bg-blue-500' },
    green: { bg: 'bg-green-500/10', text: 'text-green-500', border: 'border-green-500/20', bar: 'bg-green-500' },
    red: { bg: 'bg-red-500/10', text: 'text-red-500', border: 'border-red-500/20', bar: 'bg-red-500' },
    purple: { bg: 'bg-purple-500/10', text: 'text-purple-500', border: 'border-purple-500/20', bar: 'bg-purple-500' },
    pink: { bg: 'bg-pink-500/10', text: 'text-pink-500', border: 'border-pink-500/20', bar: 'bg-pink-500' },
    slate: { bg: 'bg-slate-500/10', text: 'text-slate-500', border: 'border-slate-500/20', bar: 'bg-slate-500' },
};
const COLOR_PALETTE = ['amber', 'blue', 'green', 'red', 'purple', 'pink'];

function getSegmentIcon(name: string) {
    for (const [key, Icon] of Object.entries(SEGMENT_ICONS)) {
        if (name.toLowerCase().includes(key.toLowerCase())) return Icon;
    }
    return Users;
}

export default function CustomerSegmentationPage() {
    const { data: rfmAnalysis, loading, error, refetch } = useRFMAnalysis();
    const [selectedSegment, setSelectedSegment] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState<'overview' | 'rfm' | 'actions'>('overview');

    const segments = useMemo(() => {
        if (!rfmAnalysis?.segments) return [];
        return rfmAnalysis.segments.map((s: any, i: number) => ({
            id: s.code,
            name: s.name,
            count: s.count,
            revenue: `₺${s.avgMonetary.toLocaleString('tr-TR')}`,
            avgOrder: `₺${s.avgMonetary.toLocaleString('tr-TR')}`,
            frequency: `${s.avgFrequency}x`,
            color: COLOR_PALETTE[i % COLOR_PALETTE.length],
            description: s.description,
            percentage: s.percentage
        }));
    }, [rfmAnalysis]);

    const rfmData = useMemo(() => {
        if (!rfmAnalysis?.customers) return [];
        return rfmAnalysis.customers.map((c: any) => ({
            customer: c.customerName,
            recency: c.recency,
            frequency: c.frequency,
            monetary: c.monetary,
            segment: c.segment,
            score: parseInt(c.rfmScore) || 0
        }));
    }, [rfmAnalysis]);

    const totalCustomers = rfmAnalysis?.summary?.totalCustomers || 0;
    const selected = selectedSegment ? segments.find(s => s.id === selectedSegment) : null;
    const filteredRfm = selectedSegment && selected
        ? rfmData.filter((r: any) => r.segment === selected.name)
        : rfmData;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-foreground flex items-center gap-3">
                        <Users className="w-8 h-8 text-violet-500" /> Müşteri Segmentleri
                    </h1>
                    <p className="text-slate-500 mt-1 font-medium">RFM analizi ile müşteri segmentasyonu ve hedefleme</p>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={() => refetch()} className="p-2 hover:bg-surface rounded-xl text-slate-400 hover:text-foreground transition-all">
                        <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
                    </button>
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-violet-600 rounded-xl text-white text-sm font-bold hover:bg-violet-700 transition-all">
                        <Download size={16} /> Dışa Aktar
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-3 gap-4">
                {[
                    { label: 'Toplam Müşteri', value: loading ? '—' : totalCustomers.toLocaleString('tr-TR'), color: 'violet', icon: Users },
                    { label: 'Toplam Segment', value: loading ? '—' : String(segments.length), color: 'blue', icon: Target },
                    { label: 'VIP Oranı', value: loading ? '—' : `%${segments.find((s: any) => s.name.includes('VIP'))?.percentage ?? '—'}`, color: 'amber', icon: Crown },
                ].map((s, i) => (
                    <motion.div key={s.label} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}
                        className="bg-surface rounded-2xl border border-border p-5">
                        <div className="flex items-center gap-3 mb-3">
                            <div className={`p-2.5 bg-${s.color}-500/10 rounded-xl`}>
                                <s.icon className={`w-5 h-5 text-${s.color}-500`} />
                            </div>
                            <span className="text-slate-500 text-sm font-medium">{s.label}</span>
                        </div>
                        <div className="text-2xl font-black text-foreground">{s.value}</div>
                    </motion.div>
                ))}
            </div>

            {/* Tabs */}
            <div className="flex gap-1 bg-surface border border-border rounded-xl p-1">
                {[{ id: 'overview', label: 'Segmentler' }, { id: 'rfm', label: 'RFM Analizi' }, { id: 'actions', label: 'Aksiyonlar' }].map(t => (
                    <button key={t.id} onClick={() => setActiveTab(t.id as any)}
                        className={`flex-1 py-2.5 text-sm rounded-lg font-medium transition-all ${activeTab === t.id ? 'bg-violet-500/20 text-violet-400' : 'text-slate-500 hover:text-foreground'}`}>
                        {t.label}
                    </button>
                ))}
            </div>

            {/* OVERVIEW */}
            {activeTab === 'overview' && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                    {loading && segments.length === 0 ? (
                        <div className="col-span-2 py-16 flex items-center justify-center gap-3 text-slate-500 bg-surface rounded-2xl border border-border">
                            <Loader2 size={20} className="animate-spin" /><span className="text-sm">Segmentler yükleniyor...</span>
                        </div>
                    ) : segments.length === 0 ? (
                        <div className="col-span-2 text-center py-16 bg-surface rounded-2xl border border-dashed border-border">
                            <Users size={40} className="mx-auto mb-3 text-slate-300" />
                            <p className="font-bold text-foreground">Henüz müşteri segmenti yok</p>
                            <p className="text-sm text-slate-500 mt-1">Yeterli müşteri verisi birikmesi bekleniyor</p>
                        </div>
                    ) : (
                        segments.map((segment: any, i: number) => {
                            const cls = COLOR_CLASSES[segment.color] || COLOR_CLASSES.slate;
                            const Icon = getSegmentIcon(segment.name);
                            const pct = segment.percentage ?? (totalCustomers > 0 ? Math.round(segment.count / totalCustomers * 100) : 0);
                            const isSelected = selectedSegment === segment.id;

                            return (
                                <motion.div key={segment.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}
                                    onClick={() => setSelectedSegment(isSelected ? null : segment.id)}
                                    className={`bg-surface rounded-2xl border p-6 cursor-pointer transition-all ${isSelected ? `${cls.border} shadow-lg` : 'border-border hover:border-slate-400/30'}`}>
                                    <div className="flex items-start justify-between mb-4">
                                        <div className="flex items-center gap-3">
                                            <div className={`p-3 rounded-xl ${cls.bg}`}><Icon className={`w-5 h-5 ${cls.text}`} /></div>
                                            <div>
                                                <h3 className="font-bold text-foreground">{segment.name}</h3>
                                                {segment.description && <p className="text-xs text-slate-500 mt-0.5">{segment.description}</p>}
                                            </div>
                                        </div>
                                        <span className={`px-2 py-1 rounded-full text-xs font-black ${cls.bg} ${cls.text}`}>%{pct}</span>
                                    </div>
                                    <div className="grid grid-cols-3 gap-3 mb-4">
                                        {[
                                            { label: 'Müşteri', value: segment.count.toLocaleString('tr-TR'), icon: Users },
                                            { label: 'Gelir', value: segment.revenue, icon: DollarSign },
                                            { label: 'Ort. Sipariş', value: segment.avgOrder, icon: ShoppingCart },
                                        ].map(m => (
                                            <div key={m.label} className="text-center p-2 bg-background/50 rounded-xl">
                                                <div className="text-[10px] text-slate-500 mb-0.5">{m.label}</div>
                                                <div className="text-sm font-black text-foreground">{typeof m.value === 'number' ? m.value.toLocaleString('tr-TR') : m.value}</div>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="space-y-1">
                                        <div className="flex justify-between text-[10px] text-slate-500 mb-1">
                                            <span>Müşteri oranı</span><span>%{pct}</span>
                                        </div>
                                        <div className="h-1.5 bg-background rounded-full overflow-hidden">
                                            <div className={`h-full rounded-full transition-all duration-700 ${cls.bar}`} style={{ width: `${pct}%` }} />
                                        </div>
                                    </div>
                                </motion.div>
                            );
                        })
                    )}
                </div>
            )}

            {/* RFM */}
            {activeTab === 'rfm' && (
                <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                    <div className="p-4 border-b border-border flex items-center justify-between">
                        <h3 className="font-bold text-foreground flex items-center gap-2"><BarChart3 size={16} className="text-violet-400" /> RFM Skoru</h3>
                        <button onClick={() => refetch()} className="text-xs text-slate-400 hover:text-foreground flex items-center gap-1 transition-all">
                            <RefreshCw size={12} className={loading ? 'animate-spin' : ''} /> Yenile
                        </button>
                    </div>
                    {loading && rfmData.length === 0 ? (
                        <div className="py-12 flex items-center justify-center gap-3 text-slate-500">
                            <Loader2 size={18} className="animate-spin" /><span className="text-sm">RFM analizi hesaplanıyor...</span>
                        </div>
                    ) : filteredRfm.length === 0 ? (
                        <div className="py-12 text-center text-slate-500">
                            <Target size={32} className="mx-auto mb-2 text-slate-300" />
                            <p className="text-sm">RFM verisi bulunamadı</p>
                        </div>
                    ) : (
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="border-b border-border text-left">
                                    {['Müşteri', 'Recency (gün)', 'Frequency', 'Monetary', 'Segment', 'Skor'].map(h => (
                                        <th key={h} className="p-4 text-xs font-bold text-slate-500">{h}</th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {filteredRfm.map((row: any, i: number) => {
                                    const scoreColor = row.score >= 90 ? 'text-amber-500' : row.score >= 70 ? 'text-blue-500' : row.score >= 50 ? 'text-green-500' : 'text-slate-500';
                                    return (
                                        <tr key={i} className="border-b border-border/50 hover:bg-background/50 transition-colors">
                                            <td className="p-4 font-bold text-foreground">{row.customer}</td>
                                            <td className="p-4 text-slate-400">{row.recency} gün</td>
                                            <td className="p-4 text-slate-400">{row.frequency}x</td>
                                            <td className="p-4 text-foreground font-bold">{typeof row.monetary === 'number' ? `₺${row.monetary.toLocaleString('tr-TR')}` : row.monetary}</td>
                                            <td className="p-4"><span className="px-2 py-1 bg-violet-500/10 text-violet-500 rounded-full text-xs font-bold">{row.segment}</span></td>
                                            <td className={`p-4 font-black ${scoreColor}`}>{row.score}</td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    )}
                </div>
            )}

            {/* ACTIONS */}
            {activeTab === 'actions' && (
                <div className="space-y-4">
                    {segments.map((segment: any, i: number) => {
                        const cls = COLOR_CLASSES[segment.color] || COLOR_CLASSES.slate;
                        const Icon = getSegmentIcon(segment.name);
                        return (
                            <motion.div key={segment.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}
                                className="bg-surface rounded-2xl border border-border p-5">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2.5 rounded-xl ${cls.bg}`}><Icon className={`w-4 h-4 ${cls.text}`} /></div>
                                        <div>
                                            <h4 className="font-bold text-foreground text-sm">{segment.name}</h4>
                                            <p className="text-xs text-slate-500">{segment.count.toLocaleString('tr-TR')} müşteri</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button className="flex items-center gap-1.5 px-3 py-2 bg-blue-500/10 text-blue-500 rounded-xl text-xs font-bold hover:bg-blue-500/20 transition-all">
                                            <Mail size={12} /> E-posta Kampanyası
                                        </button>
                                        <button className="flex items-center gap-1.5 px-3 py-2 bg-violet-500/10 text-violet-500 rounded-xl text-xs font-bold hover:bg-violet-500/20 transition-all">
                                            <Target size={12} /> Hedefle
                                        </button>
                                        <button className="flex items-center gap-1.5 px-3 py-2 bg-green-500/10 text-green-500 rounded-xl text-xs font-bold hover:bg-green-500/20 transition-all">
                                            <TrendingUp size={12} /> Analiz Et
                                        </button>
                                    </div>
                                </div>
                            </motion.div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

