            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input
              type="text"
              placeholder="VKN, TCKN, Alıcı veya Fatura No Ara..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-11 pr-4 py-3 border border-border rounded-xl bg-surface text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm font-medium"
            />
          </div>
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-4 py-3 border border-border rounded-xl bg-surface text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm font-bold min-w-[200px]"
          >
            <option value="all">Filtre: Tüm Durumlar</option>
            <option value="DRAFT">Taslak</option>
            <option value="PENDING">Sırada / Kesiliyor</option>
            <option value="SENT">GİB'e İletildi</option>
            <option value="ACCEPTED">Alıcı Kabul Etti</option>
            <option value="REJECTED">Reddedildi</option>
          </select>
        </div>
      )}

      {/* Table */}
      {!loading && (
        <div className="bg-surface border border-border rounded-2xl overflow-hidden shadow-sm">
          <div className="overflow-x-auto min-h-[300px]">
            <table className="w-full">
              <thead>
                <tr className="border-b border-border bg-slate-50 dark:bg-slate-900/50">
                  <th className="text-left px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest min-w-[140px]">Fatura No</th>
                  <th className="text-left px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest min-w-[120px]">Tarih</th>
                  <th className="text-left px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest min-w-[200px]">Alıcı Cari Bilgisi</th>
                  <th className="text-left px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest min-w-[100px]">Fatura Tipi</th>
                  <th className="text-left px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest min-w-[140px]">Güncel GİB Durumu</th>
                  <th className="text-right px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest min-w-[120px]">KDV Dahil Tutar</th>
                  <th className="text-center px-6 py-4 text-xs font-black text-slate-400 uppercase tracking-widest">Aksiyon</th>
                </tr>
              </thead>
              <tbody>
                {filteredInvoices.length > 0 ? filteredInvoices.map((inv) => {
                  const statusCfg = statusConfig[inv.status] || statusConfig.DRAFT;
                  const StatusIcon = statusCfg.icon;
                  return (
                    <tr key={inv.id} className="border-b border-border/50 hover:bg-slate-50 dark:hover:bg-slate-900/30 transition-colors group">
                      <td className="px-6 py-5 font-mono font-bold text-sm text-foreground">
                        {inv.invoiceNumber}
                      </td>
                      <td className="px-6 py-5 text-sm text-slate-500 font-medium">
                        {new Date(inv.invoiceDate).toLocaleDateString('tr-TR')}
                      </td>
                      <td className="px-6 py-5">
                        <p className="text-sm font-bold text-foreground mb-0.5 truncate max-w-[200px]" title={inv.buyerTitle}>{inv.buyerTitle}</p>
                        <p className="text-[11px] font-mono text-slate-400">VKN: {inv.buyerTaxNumber}</p>
                      </td>
                      <td className="px-6 py-5">
                        <span className="text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md">
                          {inv.type}
                        </span>
                      </td>
                      <td className="px-6 py-5">
                        <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[11px] font-bold ${statusCfg.color}`}>
                          <StatusIcon size={12} />
                          {statusCfg.label}
                        </span>
                      </td>
                      <td className="px-6 py-5 text-right font-black text-base text-foreground">
                        {formatCurrency(inv.totalAmount, inv.currency)}
                      </td>
                      <td className="px-6 py-5 text-center">
                        <button className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-primary hover:text-white text-slate-500 rounded-lg transition-colors font-bold text-xs" title="Görüntüle">
                          Detay
                        </button>
                      </td>
                    </tr>
                  );
                }) : (
                    <tr>
                        <td colSpan={7} className="text-center py-20 px-4">
                            <ShoppingCart className="w-12 h-12 text-slate-300 dark:text-slate-700 mx-auto mb-4" />
                            <p className="text-slate-500 font-bold mb-1">E-Fatura Bekleyen Kayıt Yok</p>
                            <p className="text-sm text-slate-400">Siparişleriniz otomasyon veya manuel yöntemle arşivlendiğinde burada listelenir.</p>
                        </td>
                    </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Bookmark, Plus, Star, Trash2, ExternalLink, ArrowRight,
    Package, ShoppingCart, BarChart3, Settings, Truck, Users,
    Globe, DollarSign, GripVertical, FolderOpen
} from 'lucide-react';

interface Favorite {
    id: string;
    title: string;
    url: string;
    icon: React.ElementType;
    category: string;
    color: string;
}

interface Shortcut {
    id: string;
    label: string;
    keys: string;
    action: string;
}

const defaultFavorites: Favorite[] = [
    { id: '1', title: 'Dashboard', url: '/dashboard', icon: BarChart3, category: 'Sayfa', color: 'blue' },
    { id: '2', title: 'Ürünler', url: '/dashboard/products', icon: Package, category: 'Sayfa', color: 'purple' },
    { id: '3', title: 'Siparişler', url: '/dashboard/orders', icon: ShoppingCart, category: 'Sayfa', color: 'emerald' },
    { id: '4', title: 'Raporlar', url: '/dashboard/advanced-reports', icon: BarChart3, category: 'Sayfa', color: 'cyan' },
    { id: '5', title: 'Tedarikçiler', url: '/dashboard/suppliers', icon: Truck, category: 'Sayfa', color: 'orange' },
];

const allPages = [
    { title: 'Dashboard', url: '/dashboard', icon: BarChart3 },
    { title: 'Ürünler', url: '/dashboard/products', icon: Package },
    { title: 'Siparişler', url: '/dashboard/orders', icon: ShoppingCart },
    { title: 'Müşteriler', url: '/dashboard/customers', icon: Users },
    { title: 'Raporlar', url: '/dashboard/advanced-reports', icon: BarChart3 },
    { title: 'Tedarikçiler', url: '/dashboard/suppliers', icon: Truck },
    { title: 'Kampanyalar', url: '/dashboard/campaign-manager', icon: Globe },
    { title: 'Fiyat Optimizasyonu', url: '/dashboard/price-optimization', icon: DollarSign },
    { title: 'Ayarlar', url: '/dashboard/settings', icon: Settings },
];

const shortcuts: Shortcut[] = [
    { id: '1', label: 'Yeni Ürün', keys: 'Alt+N', action: 'Ürün ekleme sayfasını aç' },
    { id: '2', label: 'Arama', keys: 'Ctrl+K', action: 'Global arama' },
    { id: '3', label: 'Dashboard', keys: 'Alt+D', action: 'Dashboard\'a git' },
    { id: '4', label: 'Siparişler', keys: 'Alt+O', action: 'Siparişlere git' },
    { id: '5', label: 'Bildirimler', keys: 'Alt+B', action: 'Bildirim panelini aç' },
];

export default function FavoritesPage() {
    const [favorites, setFavorites] = useState(defaultFavorites);
    const [showAddModal, setShowAddModal] = useState(false);
    const [tab, setTab] = useState<'favorites' | 'shortcuts'>('favorites');

    const removeFav = (id: string) => setFavorites(prev => prev.filter(f => f.id !== id));
    const addFav = (page: typeof allPages[0]) => {
        if (favorites.some(f => f.url === page.url)) return;
        setFavorites(prev => [...prev, { id: `f${Date.now()}`, title: page.title, url: page.url, icon: page.icon, category: 'Sayfa', color: 'indigo' }]);
        setShowAddModal(false);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <Bookmark className="w-8 h-8 text-yellow-500" /> Favoriler & Kısayollar
                    </h1>
                    <p className="text-slate-500 mt-1">Sık kullandığınız sayfaları ve kısayolları yönetin</p>
                </div>
            </div>

            <div className="flex gap-1 bg-surface border border-border rounded-xl p-1">
                <button onClick={() => setTab('favorites')} className={`flex-1 py-2.5 text-sm rounded-lg font-medium ${tab === 'favorites' ? 'bg-yellow-500/20 text-yellow-400' : 'text-slate-500'}`}>
                    <Star className="w-4 h-4 inline mr-2" />Favoriler ({favorites.length})
                </button>
                <button onClick={() => setTab('shortcuts')} className={`flex-1 py-2.5 text-sm rounded-lg font-medium ${tab === 'shortcuts' ? 'bg-yellow-500/20 text-yellow-400' : 'text-slate-500'}`}>
                    Klavye Kısayolları ({shortcuts.length})
                </button>
            </div>

            {tab === 'favorites' && (
                <>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {favorites.map((fav, i) => (
                            <motion.div key={fav.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}
                                className="bg-surface rounded-2xl border border-border p-5 group hover:border-yellow-500/30 transition-colors">
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 bg-${fav.color}-500/20 rounded-xl`}>
                                            <fav.icon className={`w-5 h-5 text-${fav.color}-500`} />
                                        </div>
                                        <div>
                                            <h3 className="text-sm font-bold text-foreground">{fav.title}</h3>
                                            <p className="text-xs text-slate-500">{fav.url}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button className="p-1.5 hover:bg-background rounded-lg text-slate-400"><ExternalLink className="w-3.5 h-3.5" /></button>
                                        <button onClick={() => removeFav(fav.id)} className="p-1.5 hover:bg-background rounded-lg text-slate-400 hover:text-red-400"><Trash2 className="w-3.5 h-3.5" /></button>
                                    </div>
                                </div>
                            </motion.div>
                        ))}

                        <button onClick={() => setShowAddModal(true)}
                            className="border-2 border-dashed border-border rounded-2xl p-5 flex items-center justify-center gap-2 text-sm text-slate-500 hover:text-yellow-400 hover:border-yellow-500/30 transition-colors">
                            <Plus className="w-5 h-5" /> Favori Ekle
                        </button>
                    </div>

                    {showAddModal && (
                        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowAddModal(false)}>
                            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                                className="bg-surface rounded-2xl w-full max-w-md border border-border p-6" onClick={e => e.stopPropagation()}>
                                <h3 className="text-xl font-bold text-foreground mb-4">Sayfa Ekle</h3>
                                <div className="space-y-2">
                                    {allPages.filter(p => !favorites.some(f => f.url === p.url)).map((page, i) => (
                                        <button key={i} onClick={() => addFav(page)}
                                            className="w-full flex items-center gap-3 p-3 hover:bg-background rounded-xl transition-colors text-left">
                                            <page.icon className="w-5 h-5 text-slate-400" />
                                            <span className="text-sm text-foreground">{page.title}</span>
                                            <ArrowRight className="w-4 h-4 text-slate-600 ml-auto" />
                                        </button>
                                    ))}
                                </div>
                            </motion.div>
                        </div>
                    )}
                </>
            )}

            {tab === 'shortcuts' && (
                <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                    {shortcuts.map((sc, i) => (
                        <div key={sc.id} className="flex items-center justify-between p-4 border-b border-border/50 last:border-0">
                            <div>
                                <div className="text-sm font-medium text-foreground">{sc.label}</div>
                                <div className="text-xs text-slate-500">{sc.action}</div>
                            </div>
                            <kbd className="px-3 py-1.5 bg-background rounded-lg text-sm text-slate-400 border border-border font-mono">{sc.keys}</kbd>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Lightbulb,
  Bug,
  TrendingUp,
  ChevronUp,
  MessageSquare,
  Plus,
  Search,
  Filter,
  Clock,
  CheckCircle2,
  XCircle,
  Eye,
  Calendar,
  Send,
  Sparkles,
  ArrowUpRight,
  Tag,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────
interface FeatureRequest {
  id: string;
  title: string;
  description: string;
  category: 'feature' | 'improvement' | 'bug';
  status: 'pending' | 'reviewing' | 'planned' | 'completed' | 'rejected';
  votes: number;
  priority: number;
  createdAt: string;
  hasVoted?: boolean;
}

const initialFeatures: FeatureRequest[] = [];

const categoryConfig = {
  feature: { label: 'Yeni Özellik', icon: Lightbulb, color: 'text-purple-400', bg: 'bg-purple-500/10', border: 'border-purple-500/20' },
  improvement: { label: 'İyileştirme', icon: TrendingUp, color: 'text-blue-400', bg: 'bg-blue-500/10', border: 'border-blue-500/20' },
  bug: { label: 'Hata Bildirimi', icon: Bug, color: 'text-red-400', bg: 'bg-red-500/10', border: 'border-red-500/20' },
};

const statusConfig = {
  pending: { label: 'Beklemede', icon: Clock, color: 'text-slate-400', bg: 'bg-slate-500/10' },
  reviewing: { label: 'İnceleniyor', icon: Eye, color: 'text-amber-400', bg: 'bg-amber-500/10' },
  planned: { label: 'Planlandı', icon: Calendar, color: 'text-blue-400', bg: 'bg-blue-500/10' },
  completed: { label: 'Tamamlandı', icon: CheckCircle2, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
  rejected: { label: 'Reddedildi', icon: XCircle, color: 'text-red-400', bg: 'bg-red-500/10' },
};

export default function FeedbackPage() {
  const [features, setFeatures] = useState<FeatureRequest[]>(initialFeatures);
  const [filter, setFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [showNewForm, setShowNewForm] = useState(false);
  const [sortBy, setSortBy] = useState<'votes' | 'date'>('votes');

  // New feature form state
  const [newTitle, setNewTitle] = useState('');
  const [newDescription, setNewDescription] = useState('');
  const [newCategory, setNewCategory] = useState<'feature' | 'improvement' | 'bug'>('feature');

  const handleVote = (id: string) => {
    setFeatures((prev) =>
      prev.map((f) =>
        f.id === id
          ? { ...f, votes: f.hasVoted ? f.votes - 1 : f.votes + 1, hasVoted: !f.hasVoted }
          : f
      )
    );
  };

  const handleSubmit = () => {
    if (!newTitle.trim()) return;
    const newFeature: FeatureRequest = {
      id: `new-${Date.now()}`,
      title: newTitle,
      description: newDescription,
      category: newCategory,
      status: 'pending',
      votes: 1,
      priority: 0,
      createdAt: new Date().toISOString().split('T')[0],
      hasVoted: true,
    };
    setFeatures((prev) => [newFeature, ...prev]);
    setNewTitle('');
    setNewDescription('');
    setNewCategory('feature');
    setShowNewForm(false);
  };

  const filtered = features
    .filter((f) => filter === 'all' || f.category === filter)
    .filter((f) => statusFilter === 'all' || f.status === statusFilter)
    .filter(
      (f) =>
        !searchQuery ||
        f.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        f.description.toLowerCase().includes(searchQuery.toLowerCase())
    )
    .sort((a, b) => (sortBy === 'votes' ? b.votes - a.votes : new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));

  const stats = {
    total: features.length,
    planned: features.filter((f) => f.status === 'planned').length,
    completed: features.filter((f) => f.status === 'completed').length,
    totalVotes: features.reduce((sum, f) => sum + f.votes, 0),
  };

  return (
    <div className="p-6 space-y-6 max-w-5xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-3">
            <div className="p-2 bg-purple-500/10 rounded-xl">
              <Sparkles size={24} className="text-purple-400" />
            </div>
            Özellik İstekleri & Geri Bildirim
          </h1>
          <p className="text-sm text-slate-400 mt-1">
            Yeni özellik öner, hata bildir veya mevcut isteklere oy ver
          </p>
        </div>
        <button
          onClick={() => setShowNewForm(true)}
          className="flex items-center gap-2 px-5 py-2.5 bg-purple-600 hover:bg-purple-700 text-white text-sm font-bold rounded-xl transition-colors"
        >
          <Plus size={16} />
          Yeni Öneri
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4">
        {[
          { label: 'Toplam Öneri', value: stats.total, icon: MessageSquare, color: 'text-blue-400' },
          { label: 'Planlandı', value: stats.planned, icon: Calendar, color: 'text-purple-400' },
          { label: 'Tamamlandı', value: stats.completed, icon: CheckCircle2, color: 'text-emerald-400' },
          { label: 'Toplam Oy', value: stats.totalVotes, icon: ChevronUp, color: 'text-amber-400' },
        ].map((stat) => (
          <div
            key={stat.label}
            className="p-4 bg-slate-900/50 border border-slate-800 rounded-2xl"
          >
            <div className="flex items-center justify-between mb-2">
              <stat.icon size={18} className={stat.color} />
            </div>
            <p className="text-2xl font-bold text-white">{stat.value}</p>
            <p className="text-xs text-slate-500">{stat.label}</p>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex items-center gap-4 flex-wrap">
        <div className="relative flex-1 max-w-sm">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input
            type="text"
            placeholder="Ara..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-slate-900 border border-slate-800 rounded-xl text-sm text-white placeholder-slate-500 focus:outline-none focus:border-purple-500"
          />
        </div>

        <div className="flex items-center gap-2">
          {[
            { key: 'all', label: 'Tümü' },
            { key: 'feature', label: '💡 Özellik' },
            { key: 'improvement', label: '📈 İyileştirme' },
            { key: 'bug', label: '🐛 Hata' },
          ].map((cat) => (
            <button
              key={cat.key}
              onClick={() => setFilter(cat.key)}
              className={`px-3 py-1.5 text-xs font-bold rounded-lg border transition-colors ${
                filter === cat.key
                  ? 'bg-purple-500/10 border-purple-500/30 text-purple-400'
                  : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2">
          {[
            { key: 'all', label: 'Tüm Durumlar' },
            { key: 'pending', label: 'Beklemede' },
            { key: 'reviewing', label: 'İnceleniyor' },
            { key: 'planned', label: 'Planlandı' },
            { key: 'completed', label: 'Tamamlandı' },
          ].map((s) => (
            <button
              key={s.key}
              onClick={() => setStatusFilter(s.key)}
              className={`px-3 py-1.5 text-xs font-bold rounded-lg border transition-colors ${
                statusFilter === s.key
                  ? 'bg-blue-500/10 border-blue-500/30 text-blue-400'
                  : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
              }`}
            >
              {s.label}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-1 ml-auto">
          <button
            onClick={() => setSortBy('votes')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg ${sortBy === 'votes' ? 'text-purple-400' : 'text-slate-500'}`}
          >
            En Çok Oy
          </button>
          <button
            onClick={() => setSortBy('date')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg ${sortBy === 'date' ? 'text-purple-400' : 'text-slate-500'}`}
          >
            En Yeni
          </button>
        </div>
      </div>

      {/* Feature List */}
      <div className="space-y-3">
        <AnimatePresence>
          {filtered.map((feature) => {
            const cat = categoryConfig[feature.category];
            const sta = statusConfig[feature.status];
            const CatIcon = cat.icon;
            const StaIcon = sta.icon;

            return (
              <motion.div
                key={feature.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
