          >
            <motion.div
              initial={{ scale: 0.95, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.95, y: 20 }}
              onClick={(e) => e.stopPropagation()}
              className="w-full max-w-lg bg-slate-900 border border-slate-800 rounded-2xl shadow-2xl overflow-hidden"
            >
              <div className="p-6 border-b border-slate-800">
                <h2 className="text-lg font-bold text-white flex items-center gap-2">
                  <Plus size={20} className="text-purple-400" />
                  Yeni Öneri Gönder
                </h2>
              </div>

              <div className="p-6 space-y-4">
                {/* Category */}
                <div>
                  <label className="text-xs font-bold text-slate-400 mb-2 block">Kategori</label>
                  <div className="flex gap-2">
                    {(
                      [
                        { key: 'feature', label: '💡 Yeni Özellik' },
                        { key: 'improvement', label: '📈 İyileştirme' },
                        { key: 'bug', label: '🐛 Hata Bildirimi' },
                      ] as const
                    ).map((cat) => (
                      <button
                        key={cat.key}
                        onClick={() => setNewCategory(cat.key)}
                        className={`flex-1 py-2 text-xs font-bold rounded-xl border transition-colors ${
                          newCategory === cat.key
                            ? 'bg-purple-500/10 border-purple-500/30 text-purple-400'
                            : 'bg-slate-800 border-slate-700 text-slate-400'
                        }`}
                      >
                        {cat.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Title */}
                <div>
                  <label className="text-xs font-bold text-slate-400 mb-2 block">Başlık</label>
                  <input
                    type="text"
                    value={newTitle}
                    onChange={(e) => setNewTitle(e.target.value)}
                    placeholder="Kısa ve açıklayıcı bir başlık..."
                    className="w-full px-4 py-2.5 bg-slate-800 border border-slate-700 rounded-xl text-sm text-white placeholder-slate-500 focus:outline-none focus:border-purple-500"
                  />
                </div>

                {/* Description */}
                <div>
                  <label className="text-xs font-bold text-slate-400 mb-2 block">Açıklama</label>
                  <textarea
                    value={newDescription}
                    onChange={(e) => setNewDescription(e.target.value)}
                    placeholder="Detayları açıklayın..."
                    rows={4}
                    className="w-full px-4 py-2.5 bg-slate-800 border border-slate-700 rounded-xl text-sm text-white placeholder-slate-500 focus:outline-none focus:border-purple-500 resize-none"
                  />
                </div>
              </div>

              <div className="p-6 border-t border-slate-800 flex items-center justify-end gap-3">
                <button
                  onClick={() => setShowNewForm(false)}
                  className="px-4 py-2 text-sm text-slate-400 hover:text-white transition-colors"
                >
                  İptal
                </button>
                <button
                  onClick={handleSubmit}
                  disabled={!newTitle.trim()}
                  className="flex items-center gap-2 px-5 py-2.5 bg-purple-600 hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-bold rounded-xl transition-colors"
                >
                  <Send size={14} />
                  Gönder
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {
    DollarSign, TrendingUp, TrendingDown, PieChart,
    BarChart3, Wallet, ArrowUpRight, ArrowDownRight,
    Filter, Download, Calendar, Zap, Scale, Percent,
    RefreshCw, Receipt, CreditCard, Package
} from 'lucide-react';
import { useFinance, usePlatformPerformance, useSalesForecast, FinanceStats } from '@/lib/hooks';

interface FinancePlatform {
    name: string;
    revenue: number;
    cost: number;
    margin: string;
    colors: { bg: string; bar: string; dot: string };
}

type Period = '7d' | '30d' | '90d' | '365d';

const PERIOD_LABELS: Record<Period, string> = {
    '7d': 'Son 7 Gün',
    '30d': 'Son 30 Gün',
    '90d': 'Son 90 Gün',
    '365d': 'Bu Yıl',
};

const platformColors: Record<string, { bg: string; bar: string; dot: string }> = {
    'Trendyol': { bg: 'bg-orange-500/10', bar: 'bg-orange-500', dot: 'bg-orange-500' },
    'Amazon': { bg: 'bg-amber-500/10', bar: 'bg-amber-500', dot: 'bg-amber-500' },
    'Hepsiburada': { bg: 'bg-red-500/10', bar: 'bg-red-500', dot: 'bg-red-500' },
    'N11': { bg: 'bg-purple-500/10', bar: 'bg-purple-500', dot: 'bg-purple-500' },
    'Çiçeksepeti': { bg: 'bg-pink-500/10', bar: 'bg-pink-500', dot: 'bg-pink-500' },
};

// Simple inline SVG sparkline chart
function SparkLine({ values, color = '#6366f1' }: { values: number[]; color?: string }) {
    if (!values || values.length < 2) return null;
    const max = Math.max(...values);
    const min = Math.min(...values);
    const range = max - min || 1;
    const w = 260; const h = 60;
    const pts = values.map((v, i) => {
        const x = (i / (values.length - 1)) * w;
        const y = h - ((v - min) / range) * h;
        return `${x},${y}`;
    }).join(' ');
    const areaPath = `M0,${h} ` + values.map((v, i) => {
        const x = (i / (values.length - 1)) * w;
        const y = h - ((v - min) / range) * (h - 4);
        return `L${x},${y}`;
    }).join(' ') + ` L${w},${h} Z`;
    return (
        <svg viewBox={`0 0 ${w} ${h}`} className="w-full h-14" preserveAspectRatio="none">
            <defs>
                <linearGradient id="sg" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={color} stopOpacity="0.25" />
                    <stop offset="100%" stopColor={color} stopOpacity="0" />
                </linearGradient>
            </defs>
            <path d={areaPath} fill="url(#sg)" />
            <polyline points={pts} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}

export default function FinancePage() {
    const [period, setPeriod] = useState<Period>('30d');
    const { getStats, loading } = useFinance();
    const { data: platformData } = usePlatformPerformance(period);
    const { data: forecastData } = useSalesForecast(30);
    const [stats, setStats] = useState<FinanceStats | null>(null);

    useEffect(() => {
