                                    </div>
                                    <div className="flex justify-between text-[10px] text-slate-600">
                                        <span>Maliyet: ₺{platform.cost.toLocaleString('tr-TR')}</span>
                                        <span>Kâr: ₺{(platform.revenue - platform.cost).toLocaleString('tr-TR')}</span>
                                    </div>
                                </div>
