                        </div>
                    )}
                </div>

                {/* AI Insights */}
                <div className="bg-surface rounded-2xl border border-primary/20 p-6 relative overflow-hidden group">
                    <div className="absolute top-[-20%] right-[-10%] opacity-5 group-hover:opacity-10 transition-opacity">
