}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { 
    AlertTriangle, RefreshCw, CheckCircle2, Search, XCircle, ChevronRight, Store, Database
} from 'lucide-react';
import Link from 'next/link';

// Mock data for discrepancies
const mockDiscrepancies = [
    { id: 1, sku: 'TSH-BLK-M', name: 'Siyah Tişört (Medium)', localStock: 45, marketStock: 50, marketplace: 'Trendyol', status: 'critical' },
    { id: 2, sku: 'SNK-WHT-42', name: 'Beyaz Sneaker (42 Nu.)', localStock: 12, marketStock: 12, marketplace: 'Hepsiburada', status: 'synced' },
    { id: 3, sku: 'SNK-WHT-43', name: 'Beyaz Sneaker (43 Nu.)', localStock: 0, marketStock: 2, marketplace: 'N11', status: 'critical' },
    { id: 4, sku: 'JCK-BLU-L', name: 'Mavi Ceket (Large)', localStock: 15, marketStock: 14, marketplace: 'Amazon', status: 'warning' }
];

export default function DiscrepancyManagerPage() {
    const [isScanning, setIsScanning] = useState(false);
    const [lastScan, setLastScan] = useState('2 Saat Önce');
    const [results, setResults] = useState(mockDiscrepancies);

    const handleScan = () => {
        setIsScanning(true);
        setTimeout(() => {
            setIsScanning(false);
            setLastScan('Şimdi');
            // Simulate resolving items randomly
            setResults(prev => prev.map(item => ({ ...item, marketStock: item.localStock, status: 'synced' })));
        }, 3000);
    };

    const handleSyncSpecific = (id: number) => {
        setResults(prev => prev.map(item => {
            if (item.id === id) {
                return { ...item, marketStock: item.localStock, status: 'synced' };
            }
            return item;
        }));
    };

    const criticalCount = results.filter(r => r.status === 'critical').length;
    const warningCount = results.filter(r => r.status === 'warning').length;

    return (
        <div className="max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black flex items-center gap-3">
                        <AlertTriangle className="w-8 h-8 text-orange-500" />
                        Ürün Farklılık Kontrolü
                    </h1>
                    <p className="text-slate-500 mt-2">Yerel stoklarınız ile pazaryerlerindeki stoklarınızı tarar, olası kaymaları ve hataları engeller.</p>
                </div>
                <div className="flex items-center gap-3">
                    <span className="text-xs font-bold text-slate-400">Son Tarama: {lastScan}</span>
                    <button 
                        onClick={handleScan}
                        disabled={isScanning}
                        className="px-6 py-2.5 bg-primary text-white rounded-xl font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20 flex items-center gap-2 disabled:opacity-50"
                    >
                        <RefreshCw className={`w-4 h-4 ${isScanning ? 'animate-spin' : ''}`} /> 
                        {isScanning ? 'Stoklar Taranıyor...' : 'Yeni Tarama Başlat'}
                    </button>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-surface border border-border rounded-3xl p-6 relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="text-sm font-bold text-slate-500 mb-2">Yüksek Risk(Kritik)</div>
                        <div className="text-4xl font-black text-red-500 flex items-center gap-2">
                            {criticalCount} <span className="text-sm text-red-500/50 mb-1">Ürün</span>
                        </div>
                    </div>
                </div>
                <div className="bg-surface border border-border rounded-3xl p-6 relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="text-sm font-bold text-slate-500 mb-2">Düşük Risk (Uyarı)</div>
                        <div className="text-4xl font-black text-amber-500 flex items-center gap-2">
                            {warningCount} <span className="text-sm text-amber-500/50 mb-1">Ürün</span>
                        </div>
                    </div>
                </div>
                <div className="bg-surface border border-border rounded-3xl p-6 relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="text-sm font-bold text-slate-500 mb-2">Eşitlenen Stoklar</div>
                        <div className="text-4xl font-black text-emerald-500 flex items-center gap-2">
                            {results.filter(r => r.status === 'synced').length} <span className="text-sm text-emerald-500/50 mb-1">Ürün</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Scanning Logic Board */}
            <div className="bg-surface border border-border rounded-[2rem] overflow-hidden">
                <div className="p-6 border-b border-border flex items-center justify-between">
                    <h3 className="text-lg font-bold">Risk Raporu ve Eşleştirme Detayları</h3>
                    <div className="relative w-64">
                        <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                        <input 
                            type="text" 
                            className="w-full bg-background border border-border rounded-xl pl-9 pr-4 py-2 text-sm focus:outline-none focus:ring-2 ring-primary/50"
                            placeholder="SKU veya Ürün Ara..."
                        />
                    </div>
                </div>

                <div className="overflow-x-auto w-full">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b border-border bg-slate-50 dark:bg-slate-900/50 text-slate-500 text-xs uppercase tracking-widest leading-loose">
                                <th className="px-6 py-4 font-bold">Stok Kodu (SKU)</th>
                                <th className="px-6 py-4 font-bold">Pazaryeri</th>
                                <th className="px-6 py-4 font-bold text-center">Yerel Stok (Sistem)</th>
                                <th className="px-6 py-4 font-bold text-center">Uzak Stok (Mağaza)</th>
                                <th className="px-6 py-4 font-bold">Durum</th>
                                <th className="px-6 py-4 font-bold text-right">Aksiyon</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {results.map((item) => (
                                <tr key={item.id} className="hover:bg-slate-50 dark:hover:bg-slate-900/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-900 dark:text-white">{item.sku}</div>
                                        <div className="text-xs text-slate-500">{item.name}</div>
                                    </td>
                                    <td className="px-6 py-4 font-bold flex items-center gap-2 mt-2">
                                        <Store className="w-4 h-4 text-slate-400" /> {item.marketplace}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-md font-bold text-slate-700 dark:text-slate-300">
                                            <Database className="w-3 h-3 text-slate-400" /> {item.localStock}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-md font-bold ${
                                            item.status === 'critical' ? 'bg-red-500/10 text-red-500' :
                                            item.status === 'warning' ? 'bg-amber-500/10 text-amber-500' :
                                            'bg-emerald-500/10 text-emerald-500'
                                        }`}>
                                            <Store className="w-3 h-3 opacity-50" /> {item.marketStock}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        {item.status === 'synced' && <span className="inline-flex items-center gap-1.5 text-xs font-bold text-emerald-500"><CheckCircle2 className="w-4 h-4" /> Senkron</span>}
                                        {item.status === 'warning' && <span className="inline-flex items-center gap-1.5 text-xs font-bold text-amber-500"><AlertTriangle className="w-4 h-4" /> 1 Stok Fark</span>}
                                        {item.status === 'critical' && <span className="inline-flex items-center gap-1.5 text-xs font-bold text-red-500"><XCircle className="w-4 h-4" /> Tehlikeli Hata</span>}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        {item.status !== 'synced' ? (
                                            <button 
                                                onClick={() => handleSyncSpecific(item.id)}
                                                className="px-4 py-2 border border-border rounded-xl text-xs font-bold hover:bg-primary/10 hover:text-primary transition-colors hover:border-primary/20"
                                            >
                                                Sistemi Eşitle
                                            </button>
                                        ) : (
                                            <span className="text-xs font-bold text-slate-400">Güncel</span>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
    FileText,
    Download,
    Printer,
    Send,
    Eye,
    Search,
    Filter,
    Calendar,
    CheckCircle2,
    Clock,
    AlertTriangle,
    XCircle,
    Plus,
    MoreVertical,
    Building2,
    CreditCard,
    ChevronDown,
    Mail,
    ArrowUpRight,
    DollarSign,
    RefreshCw
} from 'lucide-react';
import { useInvoices } from '@/lib/hooks';

interface Invoice {
    id: string;
    invoiceNumber: string;
    invoiceDate: string;
    status: 'PAID' | 'PENDING' | 'DRAFT' | 'CANCELLED';
    order?: {
        customerName?: string;
        marketplaceOrderId?: string;
        platform?: string;
        totalAmount?: number | string;
    };
}

export default function InvoicesPage() {
    const { getInvoices, generateInvoice, loading } = useInvoices();
    const [invoices, setInvoices] = useState<Invoice[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');

    const loadInvoices = async () => {
        const response = await getInvoices() as Invoice[] | null;
        if (response) {
            setInvoices(response);
        }
    };

    useEffect(() => {
        const timer = setTimeout(() => loadInvoices(), 0);
        return () => clearTimeout(timer);
    }, []);

    // Calculate stats locally from invoices if backend doesn't provide them
    const totalInvoiced = invoices.reduce((sum, inv) => sum + Number(inv.order?.totalAmount || 0), 0);
    const paidAmount = invoices.filter(inv => inv.status === 'PAID').reduce((sum, inv) => sum + Number(inv.order?.totalAmount || 0), 0);
    const pendingAmount = invoices.filter(inv => inv.status === 'PENDING' || inv.status === 'DRAFT').reduce((sum, inv) => sum + Number(inv.order?.totalAmount || 0), 0);
    const cancelledAmount = invoices.filter(inv => inv.status === 'CANCELLED').reduce((sum, inv) => sum + Number(inv.order?.totalAmount || 0), 0);

    const filteredInvoices = invoices.filter(inv => {
        const matchesSearch = inv.invoiceNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inv.order?.customerName?.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesStatus = statusFilter === 'all' || inv.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'PAID':
                return <span className="px-2 py-1 rounded-full text-[10px] font-black bg-green-500/10 text-green-500 border border-green-500/20 flex items-center gap-1 justify-center"><CheckCircle2 className="w-3 h-3" /> ÖDENDİ</span>;
            case 'PENDING':
                return <span className="px-2 py-1 rounded-full text-[10px] font-black bg-yellow-500/10 text-yellow-500 border border-yellow-500/20 flex items-center gap-1 justify-center"><Clock className="w-3 h-3" /> BEKLEMEDE</span>;
            case 'DRAFT':
                return <span className="px-2 py-1 rounded-full text-[10px] font-black bg-gray-500/10 text-gray-500 border border-gray-500/20 flex items-center gap-1 justify-center">TASLAK</span>;
            case 'CANCELLED':
                return <span className="px-2 py-1 rounded-full text-[10px] font-black bg-red-500/10 text-red-500 border border-red-500/20 flex items-center gap-1 justify-center"><XCircle className="w-3 h-3" /> İPTAL</span>;
            default:
                return <span className="px-2 py-1 rounded-full text-[10px] font-black bg-slate-500/10 text-slate-500 border border-slate-500/20 flex items-center gap-1 justify-center">{status}</span>;
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight flex items-center gap-3">
                        <FileText className="w-8 h-8 text-amber-500" />
                        Faturalar
                    </h1>
                    <p className="text-slate-500 font-medium">Finansal dökümanlarınızın ve faturalarınızın yönetimi</p>
                </div>
                <div className="flex items-center gap-3">
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <Download size={16} /> Toplu İndir
                    </button>
                    <button onClick={loadInvoices} className="p-2.5 bg-surface border border-border rounded-xl text-foreground hover:bg-surface/80">
                        <RefreshCw size={18} className={loading ? "animate-spin" : ""} />
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="bg-surface p-6 rounded-2xl border border-border">
                    <div className="text-3xl font-black text-foreground tabular-nums">₺{totalInvoiced.toLocaleString('tr-TR')}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider mt-1">Toplam Tutar</div>
                </div>
                <div className="bg-surface p-6 rounded-2xl border border-border">
                    <div className="text-3xl font-black text-green-500 tabular-nums">₺{paidAmount.toLocaleString('tr-TR')}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider mt-1">Tahsil Edilen</div>
                </div>
                <div className="bg-surface p-6 rounded-2xl border border-border">
                    <div className="text-3xl font-black text-yellow-500 tabular-nums">₺{pendingAmount.toLocaleString('tr-TR')}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider mt-1">Bekleyen Tevkifat</div>
                </div>
                <div className="bg-surface p-6 rounded-2xl border border-border">
                    <div className="text-3xl font-black text-red-500 tabular-nums">₺{cancelledAmount.toLocaleString('tr-TR')}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider mt-1">İptal Edilen</div>
                </div>
            </div>

            {/* Invoices List */}
            <div className="bg-surface rounded-2xl border border-border overflow-hidden shadow-sm">
                <div className="p-4 border-b border-border bg-background/30 flex flex-wrap items-center gap-4">
                    <div className="flex-1 min-w-[300px] relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                        <input
                            type="text"
                            placeholder="Fatura no veya müşteri ara..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-10 pr-4 py-2.5 bg-background border border-border rounded-xl text-sm focus:outline-none focus:border-primary/50"
                        />
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-background/50 border-b border-border">
                            <tr>
                                <th className="p-4 text-left font-black text-slate-500 uppercase tracking-widest text-[10px]">Fatura No</th>
                                <th className="p-4 text-left font-black text-slate-500 uppercase tracking-widest text-[10px]">Müşteri</th>
                                <th className="p-4 text-center font-black text-slate-500 uppercase tracking-widest text-[10px]">Platform</th>
                                <th className="p-4 text-center font-black text-slate-500 uppercase tracking-widest text-[10px]">Tarih</th>
                                <th className="p-4 text-right font-black text-slate-500 uppercase tracking-widest text-[10px]">Tutar</th>
                                <th className="p-4 text-center font-black text-slate-500 uppercase tracking-widest text-[10px]">Durum</th>
                                <th className="p-4 text-center font-black text-slate-500 uppercase tracking-widest text-[10px]">İşlemler</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {filteredInvoices.map((invoice) => (
                                <tr key={invoice.id} className="hover:bg-background/50 transition-colors group">
                                    <td className="p-4">
                                        <span className="font-mono text-amber-500 font-bold">#{invoice.invoiceNumber}</span>
                                    </td>
                                    <td className="p-4">
                                        <div className="font-bold text-foreground">{invoice.order?.customerName || 'Bilinmiyor'}</div>
                                        <div className="text-[10px] text-slate-500 font-bold tabular-nums">#{invoice.order?.marketplaceOrderId}</div>
                                    </td>
                                    <td className="p-4 text-center text-[10px] font-black">
                                        {invoice.order?.platform}
                                    </td>
                                    <td className="p-4 text-center tabular-nums">
                                        {new Date(invoice.invoiceDate).toLocaleDateString('tr-TR')}
                                    </td>
                                    <td className="p-4 text-right">
                                        <div className="font-black text-foreground tabular-nums">₺{Number(invoice.order?.totalAmount || 0).toLocaleString()}</div>
                                    </td>
                                    <td className="p-4">
                                        {getStatusBadge(invoice.status)}
                                    </td>
                                    <td className="p-4">
                                        <div className="flex items-center justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button className="p-2 text-slate-400 hover:text-primary hover:bg-primary/10 rounded-xl transition-all"><Eye size={16} /></button>
                                            <button className="p-2 text-slate-400 hover:text-foreground hover:bg-background rounded-xl transition-all"><Download size={16} /></button>
                                            <button className="p-2 text-slate-400 hover:text-foreground hover:bg-background rounded-xl transition-all"><Mail size={16} /></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {filteredInvoices.length === 0 && (
                                <tr>
                                    <td colSpan={7} className="p-20 text-center">
                                        <div className="text-slate-400 font-bold uppercase tracking-widest flex flex-col items-center gap-4">
                                            <FileText size={48} className="opacity-20" />
                                            Fatura bulunamadı
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

