    Palette, Workflow, Webhook, Activity, LayoutGrid,
    Image as ImageIcon, Sun, Moon, User, FileCode2,
    Printer, Gamepad2, Link as LinkIcon, Key,
    RefreshCw, Navigation, Star, ShieldAlert, Edit2,
    FlaskConical, Layers
} from 'lucide-react';
import LiveFeed from '@/components/LiveFeed';
import { motion, AnimatePresence, useReducedMotion } from 'framer-motion';
import { ModuleProvider, useModules, useAnnouncements } from '@/lib/modules';
import { useOrderStats } from '@/lib/hooks';
import { AnnouncementBanner, AnnouncementDropdown } from '@/components/announcements/AnnouncementComponents';
import { CommandPalette } from '@/components/CommandPalette';
import { useTheme } from '@/providers/theme-provider';
import { useKeyboardShortcuts, KeyboardShortcutsHelp } from '@/components/dashboard/KeyboardShortcuts';
import { WebSocketProvider } from '@/providers/websocket-provider';
import { ToastProvider } from '@/providers/toast-provider';
import NotificationBell from '@/components/dashboard/NotificationBell';
import { ErrorBoundary } from '@/components/ui/ErrorBoundary';
import MobileBottomNav from '@/components/dashboard/MobileBottomNav';
import MobileSidebar from '@/components/dashboard/MobileSidebar';
import { useIsMobile } from '@/hooks/useMediaQuery';
import { QuickActionsProvider, useQuickActions } from '@/providers/quick-actions-provider';
import AICopilot from '@/components/dashboard/AICopilot';
import { OnboardingProvider } from "@/components/onboarding/OnboardingProvider";

interface MenuItem {
    icon: React.ComponentType<{ className?: string; size?: number }>;
    label: string;
    href: string;
    badge?: string;
    pro?: boolean;
    moduleKey?: string;
}

interface Section {
    title: string;
    items: MenuItem[];
}

const sections: Section[] = [
    {
        title: "Genel",
        items: [
            { icon: LayoutDashboard, label: "Dashboard", href: "/dashboard", moduleKey: "DASHBOARD" },
            { icon: ShoppingCart, label: "Siparişler", href: "/dashboard/orders", moduleKey: "ORDERS" },
            { icon: RefreshCw, label: "İadeler", href: "/dashboard/returns", moduleKey: "ORDERS" },
            { icon: MessageSquare, label: "Değerlendirmeler", href: "/dashboard/reviews", moduleKey: "REVIEWS" },
            { icon: Package, label: "Ürünler", href: "/dashboard/products", moduleKey: "PRODUCTS" },
            { icon: Warehouse, label: "Stok Yönetimi", href: "/dashboard/inventory", badge: "!", moduleKey: "INVENTORY" },
            { icon: ShieldAlert, label: "Eksik/Hata Kontrolü", href: "/dashboard/inventory/discrepancy", pro: true, moduleKey: "INVENTORY" },
            { icon: Layers, label: "Ortak (Grup) Stok", href: "/dashboard/inventory/group-mapping", pro: true, moduleKey: "INVENTORY" },
            { icon: BellRing, label: "Kritik Stok Alarmı", href: "/dashboard/inventory/alerts", pro: true, moduleKey: "INVENTORY" },
            { icon: Users, label: "Müşteriler", href: "/dashboard/customers", moduleKey: "CUSTOMERS" },
            { icon: Target, label: "Müşteri Segmentleri", href: "/dashboard/customer-segments", moduleKey: "CUSTOMERS" },
        ]
    },
    {
        title: "AI & Pazarlama",
        items: [
            { icon: ImageIcon, label: "Görsel Editör", href: "/dashboard/image-editor", pro: true, moduleKey: "AI_CONTENT" },
            { icon: Bot, label: "AI Danışman", href: "/dashboard/ai-consultant", pro: true, moduleKey: "AI_INSIGHTS" },
            { icon: Megaphone, label: "Kampanyalar", href: "/dashboard/ad-campaigns", moduleKey: "MARKETING" },
            { icon: MessageCircle, label: "WhatsApp Ticaret", href: "/dashboard/whatsapp", moduleKey: "MARKETING" },
            { icon: Zap, label: "Fiyat Optimizasyonu", href: "/dashboard/price-optimization", pro: true, moduleKey: "PRICING_ENGINE" },
            { icon: ShieldAlert, label: "Rakip Takibi", href: "/dashboard/competitor-tracking", pro: true, moduleKey: "COMPETITOR_INTELLIGENCE" },
            { icon: FlaskConical, label: "İçerik Stüdyosu", href: "/dashboard/ai-tools/content-studio", pro: true, moduleKey: "AI_CONTENT" },
            { icon: Layers, label: "Toplu Optimizasyon", href: "/dashboard/ai-tools/batch-optimizer", pro: true, moduleKey: "AI_CONTENT" },
        ]
    },
    {
        title: "Finansal Araçlar",
        items: [
            { icon: Briefcase, label: "Finans & Karlılık", href: "/dashboard/finance", moduleKey: "PAYMENTS" },
            { icon: Calculator, label: "Komisyon Hesabı", href: "/dashboard/commission-calculator", moduleKey: "FINANCE" },
            { icon: LinkIcon, label: "Muhasebe", href: "/dashboard/accounting", moduleKey: "FINANCE" },
            { icon: Target, label: "Bütçe Planlama", href: "/dashboard/budget", moduleKey: "FINANCE" },
            { icon: CreditCard, label: "Ödemeler", href: "/dashboard/payments", moduleKey: "PAYMENTS" },
            { icon: FileText, label: "E-Fatura", href: "/dashboard/e-invoice", moduleKey: "FINANCE" },
            { icon: RefreshCw, label: "Döviz Kurları", href: "/dashboard/currency", moduleKey: "FINANCE" },
        ]
    },
    {
        title: "Mağaza & Lojistik",
        items: [
            { icon: Store, label: "Mağazalarım", href: "/dashboard/stores", moduleKey: "STORE_MANAGEMENT" },
            { icon: Globe, label: "Entegrasyonlar", href: "/dashboard/settings/integrations", moduleKey: "INTEGRATIONS" },
            { icon: Boxes, label: "Toplu İşlemler", href: "/dashboard/bulk-actions", pro: true, moduleKey: "BULK_ACTIONS" },
            { icon: Navigation, label: "Kargo Takip", href: "/dashboard/shipping-tracking", moduleKey: "STORE_MANAGEMENT" },
            { icon: Truck, label: "Kargo Ayarları", href: "/dashboard/shipping", moduleKey: "STORE_MANAGEMENT" },
            { icon: Truck, label: "Servis Entegrasyonları", href: "/dashboard/settings/service-integrations", moduleKey: "SETTINGS" },
        ]
    },
    {
        title: "B2B & İleri Düzey",
        items: [
            { icon: Users, label: "B2B Bayi Portalı", href: "/dashboard/b2b-portal", pro: true, moduleKey: "B2B" },
            { icon: FileCode2, label: "XML Dropshipping", href: "/dashboard/xml-supplier", pro: true, moduleKey: "B2B" },
            { icon: Key, label: "Dijital Kasa (E-Pin)", href: "/dashboard/digital-vault", pro: true, moduleKey: "B2B" },
        ]
    },
    {
        title: "Sistem",
        items: [
            { icon: Workflow, label: "Otomasyonlar", href: "/dashboard/automation", pro: true, moduleKey: "INTEGRATIONS" },
            { icon: Zap, label: "Akış Oluşturucu", href: "/dashboard/workflow-builder", pro: true, moduleKey: "INTEGRATIONS" },
            { icon: Activity, label: "Canlı Analitik", href: "/dashboard/live-analytics", moduleKey: "DASHBOARD" },
            { icon: Webhook, label: "Webhooks", href: "/dashboard/webhooks", pro: true, moduleKey: "INTEGRATIONS" },
            { icon: BarChart3, label: "Aktivite Logu", href: "/dashboard/activity", moduleKey: "DASHBOARD" },
            { icon: LayoutGrid, label: "Widget'lar", href: "/dashboard/widgets", moduleKey: "DASHBOARD" },
            { icon: Palette, label: "Tema", href: "/dashboard/theme", moduleKey: "SETTINGS" },
            { icon: Shield, label: "Güvenlik", href: "/dashboard/security", moduleKey: "SECURITY" },
            { icon: Settings, label: "Ayarlar", href: "/dashboard/settings", moduleKey: "SETTINGS" },
            { icon: Users, label: "Ekip Rolleri (RBAC)", href: "/dashboard/settings/team", pro: true, moduleKey: "SETTINGS" },
        ]
    }
];

function DashboardLayoutContent({ children }: { children: React.ReactNode }) {
    const pathname = usePathname();
    const router = useRouter();
    const { data: session, status } = useSession();
    const [expandedSection, setExpandedSection] = useState<string | null>('Genel');
    const { hasModuleAccess, tenantPlan } = useModules();
    const { data: orderStats } = useOrderStats();
    const { active: activeAnnouncements, unreadCount, markAsRead, dismiss } = useAnnouncements();
    const { theme, toggleTheme, resolvedMode } = useTheme();
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [profileMenuOpen, setProfileMenuOpen] = useState(false);
    const [isCompactHeader, setIsCompactHeader] = useState(false);
    const [showLiveFeed, setShowLiveFeed] = useState(true);
    const [platformTransitionDuration, setPlatformTransitionDuration] = useState(0.24);
    const prefersReducedMotion = useReducedMotion();
    const shouldReduceMotion = prefersReducedMotion || !theme.animations;
    const { openQuickSale, openAddProduct } = useQuickActions();
    const [creditMenuOpen, setCreditMenuOpen] = useState(false);
    useKeyboardShortcuts();

    const currentPageTitle = useMemo(() => {
        const allItems = sections.flatMap(section => section.items);
        const exactMatch = allItems.find(item => item.href === pathname);
        if (exactMatch) return exactMatch.label;

        const startsWithMatch = allItems.find(item => pathname?.startsWith(item.href) && item.href !== '/dashboard');
        if (startsWithMatch) return startsWithMatch.label;

        return 'Dashboard';
    }, [pathname]);

    const triggerHaptic = () => {
        if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
            navigator.vibrate(8);
        }
    };

    // Auth guard - redirect to login if not authenticated
    useEffect(() => {
        if (status === 'unauthenticated') {
            router.replace('/login?callbackUrl=' + encodeURIComponent(pathname ?? '/dashboard'));
        }
    }, [status, router, pathname]);

    // Sayfa yüklendiğinde aktif olan bölümü açık getir
    useEffect(() => {
        const activeSection = sections.find(s => s.items.some(i => i.href === pathname));
        if (activeSection) {
            const timer = setTimeout(() => setExpandedSection(activeSection.title), 0);
            return () => clearTimeout(timer);
        }
    }, [pathname]);

    // Persist LiveFeed preference
    useEffect(() => {
        const saved = localStorage.getItem('dashboard_show_live_feed');
        if (saved !== null) {
            setShowLiveFeed(saved === 'true');
        }
    }, []);

    const toggleLiveFeed = () => {
        const newVal = !showLiveFeed;
        setShowLiveFeed(newVal);
        localStorage.setItem('dashboard_show_live_feed', String(newVal));
        triggerHaptic();
    };

    useEffect(() => {
        const onScroll = () => {
            setIsCompactHeader(window.scrollY > 24);
        };

        onScroll();
        window.addEventListener('scroll', onScroll, { passive: true });
        return () => window.removeEventListener('scroll', onScroll);
    }, []);

    useEffect(() => {
        const userAgent = navigator.userAgent.toLowerCase();
        const isIOS = /iphone|ipad|ipod/.test(userAgent);
        const isAndroid = /android/.test(userAgent);

        if (isIOS) {
            setPlatformTransitionDuration(0.3);
            return;
        }

        if (isAndroid) {
            setPlatformTransitionDuration(0.22);
            return;
        }

        setPlatformTransitionDuration(0.24);
    }, []);

    // Show loading skeleton while checking auth status
    if (status !== 'authenticated' || !session) {
        return (
            <div className="min-h-screen bg-[#0B1121] flex items-center justify-center">
                <div className="flex flex-col items-center gap-4">
                    <div className="relative w-12 h-12">
                        <div className="absolute inset-0 rounded-full border-[3px] border-slate-800" />
                        <div className="absolute inset-0 rounded-full border-[3px] border-transparent border-t-blue-600 animate-spin" />
                    </div>
                    <p className="text-sm font-medium text-slate-400 animate-pulse">
                        Yetkilendiriliyor...
                    </p>
                </div>
            </div>
        );
    }

    const toggleSection = (title: string) => {
        setExpandedSection(prev => prev === title ? null : title);
    };

    return (
        <div className="dashboard-mobile-shell flex min-h-[100dvh] bg-background text-foreground font-sans selection:bg-primary/30 overflow-x-hidden">
            {/* Sidebar - sadece desktop'ta görünür */}
            <aside
                role="navigation"
                aria-label="Ana menü"
                className="hidden lg:flex w-72 bg-surface border-r border-border flex-col fixed inset-y-0 z-50"
            >
                <div className="p-6 border-b border-border">
                    <Link href="/" className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-purple-600 flex items-center justify-center shadow-lg shadow-primary/30">
                            <span className="text-xl font-black italic text-white">P</span>
                        </div>
                        <div>
                            <span className="text-lg font-black tracking-tight text-white">PAZARYONETIMI</span>
                            <div className="text-[10px] font-bold text-primary uppercase tracking-widest">Pro Dashboard</div>
                        </div>
                    </Link>
                </div>

                {/* Quick Actions */}
                <div className="px-4 py-4 border-b border-border">
                    <div className="flex gap-2">
                        <button
                            onClick={openQuickSale}
                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2.5 bg-primary/10 hover:bg-primary/20 border border-primary/20 rounded-xl text-xs font-bold text-primary transition-all"
                        >
                            <Zap size={14} /> Hızlı Satış
                        </button>
                        <button
                            onClick={openAddProduct}
                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2.5 bg-green-500/10 hover:bg-green-500/20 border border-green-500/20 rounded-xl text-xs font-bold text-green-500 transition-all"
                        >
                            <Package size={14} /> Ürün Ekle
                        </button>
                    </div>
                </div>

                <div className="flex-1 px-3 py-4 space-y-2 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
                    {sections.map((section) => (
                        <div key={section.title} className="mb-1">
                            <button
                                onClick={() => toggleSection(section.title)}
                                aria-expanded={expandedSection === section.title}
                                aria-controls={`nav-section-${section.title}`}
                                className="w-full flex items-center justify-between px-3 py-2 text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-slate-400 transition-colors"
                            >
                                {section.title}
                                <ChevronDown
                                    size={14}
                                    aria-hidden="true"
                                    className={`transition-transform duration-200 ${expandedSection === section.title ? 'rotate-180' : ''}`}
                                />
                            </button>
                            <AnimatePresence>
                                {expandedSection === section.title && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: 'auto', opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        transition={{ duration: 0.2 }}
                                        className="overflow-hidden"
                                    >
                                        {section.items.map((item) => {
                                            const isActive = pathname === item.href;
                                            return (
                                                <Link
                                                    key={item.href}
                                                    href={item.href}
                                                    className={`flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all group mb-1 ${isActive
                                                        ? 'bg-primary/10 text-primary border border-primary/20 shadow-lg shadow-primary/5'
                                                        : 'text-slate-400 hover:bg-white/5 hover:text-foreground'
                                                        }`}
                                                >
                                                    <item.icon className={`w-4 h-4 ${isActive ? 'text-primary' : 'group-hover:text-primary transition-colors'}`} />
                                                    <span className="text-sm font-medium flex-1">{item.label}</span>
                                                    {item.label === 'Siparişler' ? (
                                                        <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-primary/20 text-primary">
                                                            {orderStats?.today?.total || '0'}
                                                        </span>
                                                    ) : item.badge && (
                                                        <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${item.badge === '!'
                                                            ? 'bg-orange-500/20 text-orange-400'
                                                            : 'bg-primary/20 text-primary'
                                                            }`}>
                                                            {item.badge}
                                                        </span>
                                                    )}
                                                    {item.pro && !hasModuleAccess(item.moduleKey || '') && (
                                                        <span className="text-[8px] font-black px-1.5 py-0.5 rounded bg-gradient-to-r from-yellow-500 to-orange-500 text-white uppercase flex items-center gap-1">
                                                            <Lock size={8} /> Pro
                                                        </span>
                                                    )}
                                                    {item.pro && hasModuleAccess(item.moduleKey || '') && (
                                                        <span className="text-[8px] font-black px-1.5 py-0.5 rounded bg-gradient-to-r from-green-500 to-emerald-500 text-white uppercase flex items-center gap-1">
                                                            <Crown size={8} /> Aktif
                                                        </span>
                                                    )}
                                                </Link>
                                            );
                                        })}
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>
                    ))}
                </div>

                <div className="p-4 mt-auto border-t border-border">
                    {/* Subscription Card */}
                    <div className="bg-gradient-to-br from-primary/20 to-purple-600/20 rounded-2xl p-4 border border-primary/20">
                        <div className="flex items-center gap-2 mb-2">
                            <Sparkles size={14} className="text-primary" />
                            <span className="text-xs font-black text-primary uppercase">{tenantPlan} Plan</span>
                        </div>
                        <div className="text-sm font-bold text-foreground mb-3">Tüm özelliklere erişin</div>
                        <div className="w-full bg-background/50 h-2 rounded-full overflow-hidden mb-2">
                            <div className="bg-gradient-to-r from-primary to-purple-500 w-3/4 h-full rounded-full" />
                        </div>
                        <div className="flex justify-between text-[10px] text-slate-500">
                            <span>75/100 Modül</span>
                            <Link href="/dashboard/upgrade" className="text-primary font-bold hover:underline">Yükselt →</Link>
                        </div>
                    </div>
                </div>
            </aside>

            {/* Main Content Area */}
            <div className="flex-1 lg:ml-72 flex flex-col min-h-[100dvh]">
                {/* Header */}
                <header role="banner" aria-label="Üst menü" className={`dashboard-mobile-header h-20 border-b border-border bg-background/80 backdrop-blur-xl sticky top-0 z-40 safe-area-top ${isCompactHeader ? 'dashboard-mobile-header-compact' : ''}`}>
                    <div className="h-full px-4 lg:px-8 flex items-center justify-between max-w-screen-2xl mx-auto w-full">
                        {/* Mobile: Page title area / Desktop: Command Palette */}
                        <div className="hidden lg:block flex-1 max-w-md">
                            <CommandPalette />
                        </div>
                        <div className="lg:hidden flex items-center gap-3">
                            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-primary to-purple-600 flex items-center justify-center shadow-lg shadow-primary/20">
                                <span className="text-sm font-black italic text-white">P</span>
                            </div>
                            <div className="dashboard-mobile-title-chip flex flex-col leading-tight">
                                <span className={`text-[10px] font-black uppercase tracking-widest text-primary/80 transition-all duration-200 ${isCompactHeader ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
                                    Pazar Yonetimi
                                </span>
                                <span className="text-sm font-black text-foreground">{currentPageTitle}</span>
                            </div>
                        </div>

                        <div className="flex items-center gap-4 lg:gap-8">
                            {/* System Status - sadece desktop */}
                            <div className="hidden xl:flex items-center gap-2.5 px-4 py-2 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 transition-all hover:bg-emerald-500/10">
                                <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)] animate-pulse" />
                                <span className="text-[11px] font-black text-emerald-500 uppercase tracking-wider">Sistemler Aktif</span>
                            </div>

                            {/* AI Kredileri */}
                            <div className="relative hidden sm:block">
                                <button
                                    onClick={() => setCreditMenuOpen(!creditMenuOpen)}
                                    className="flex items-center gap-2 px-3 py-1.5 bg-gradient-to-r from-amber-500/10 to-orange-500/10 border border-amber-500/20 hover:border-amber-500/40 rounded-xl transition-all group"
                                >
                                    <Zap size={16} className="text-amber-500 fill-amber-500/50 group-hover:scale-110 transition-transform" />
                                    <span className="text-xs font-bold text-amber-600 dark:text-amber-400">124 Kredi</span>
                                </button>

                                <AnimatePresence>
                                    {creditMenuOpen && (
                                        <>
                                            <div className="fixed inset-0 z-[60]" onClick={() => setCreditMenuOpen(false)} />
                                            <motion.div
                                                initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                                animate={{ opacity: 1, y: 0, scale: 1 }}
                                                exit={{ opacity: 0, y: 10, scale: 0.95 }}
                                                className="absolute right-0 mt-2 w-72 bg-surface border border-border rounded-2xl shadow-2xl z-[61] overflow-hidden"
                                            >
                                                <div className="p-4 bg-gradient-to-br from-amber-500/5 to-orange-500/10 border-b border-border">
                                                    <div className="flex items-center justify-between mb-2">
                                                        <div className="text-sm font-bold text-foreground">AI Üretim Kredisi</div>
                                                        <Zap size={16} className="text-amber-500" />
                                                    </div>
                                                    <div className="flex items-end gap-1 mb-3">
                                                        <span className="text-2xl font-black text-amber-600">124</span>
                                                        <span className="text-xs font-medium text-slate-500 mb-1">/ 200 Aylık</span>
                                                    </div>
                                                    <div className="w-full bg-black/5 dark:bg-white/5 rounded-full h-1.5 mb-2">
                                                        <div className="bg-gradient-to-r from-amber-400 to-orange-500 h-full rounded-full" style={{ width: '62%' }} />
                                                    </div>
                                                    <div className="text-[10px] text-slate-500">Kredileriniz <span className="font-bold text-slate-700 dark:text-slate-300">12 gün</span> içinde yenilenecek.</div>
                                                </div>
                                                <div className="p-3 bg-background/50">
                                                    <Link href="/dashboard/upgrade" onClick={() => setCreditMenuOpen(false)}>
                                                        <button className="w-full py-2.5 bg-gradient-to-r from-primary to-purple-600 hover:from-primary/90 hover:to-purple-600/90 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-primary/20 flex items-center justify-center gap-2">
                                                            <Sparkles size={14} /> Paketi Yükselt
                                                        </button>
                                                    </Link>
                                                </div>
                                            </motion.div>
                                        </>
                                    )}
                                </AnimatePresence>
                            </div>

                            <div className="flex items-center gap-1.5 lg:gap-2">
                                <NotificationBell />
                                <AnnouncementDropdown
                                    announcements={activeAnnouncements}
                                    unreadCount={unreadCount}
                                    onRead={markAsRead}
                                    onDismiss={dismiss}
                                />
                                <button
                                    aria-label="Yardım"
                                    onClick={triggerHaptic}
                                    className="hidden sm:flex p-2.5 rounded-xl hover:bg-surface text-slate-400 hover:text-foreground transition-all group haptic-tap"
                                >
                                    <HelpCircle className="w-5 h-5 group-hover:scale-110 transition-transform" aria-hidden="true" />
                                </button>
                                <button
                                    onClick={() => {
                                        triggerHaptic();
                                        toggleTheme();
                                    }}
                                    aria-label="Tema değiştir"
                                    className="p-2.5 rounded-xl hover:bg-surface text-slate-400 hover:text-foreground transition-all group haptic-tap"
                                    title={resolvedMode === 'dark' ? 'Açık moda geç' : 'Koyu moda geç'}
                                >
                                    {resolvedMode === 'dark' ?
                                        <Sun className="w-5 h-5 group-hover:rotate-45 transition-transform" /> :
                                        <Moon className="w-5 h-5 group-hover:-rotate-12 transition-transform" />
                                    }
                                </button>
                                <button
                                    onClick={toggleLiveFeed}
                                    aria-label="Canlı akışı göster/gizle"
                                    className={`hidden xl:flex p-2.5 rounded-xl transition-all group haptic-tap ${showLiveFeed ? 'bg-primary/10 text-primary border border-primary/20' : 'hover:bg-surface text-slate-400 hover:text-foreground'}`}
                                    title="Canlı Akış"
                                >
                                    <Activity className={`w-5 h-5 ${showLiveFeed ? 'animate-pulse' : 'group-hover:scale-110'}`} aria-hidden="true" />
                                </button>
                            </div>

                            <div className="hidden lg:block h-8 w-px bg-border/60 mx-1" />

                            <div className="relative">
                                <button
                                    onClick={() => setProfileMenuOpen(!profileMenuOpen)}
                                    className="flex items-center gap-2 lg:gap-4 group p-1 lg:p-1.5 lg:pr-3 rounded-2xl hover:bg-surface transition-all active:scale-95 border border-transparent hover:border-border"
                                >
                                    <div className="w-9 h-9 lg:w-10 lg:h-10 rounded-xl bg-gradient-to-br from-primary to-purple-600 flex items-center justify-center text-xs lg:text-sm font-black text-white shadow-lg shadow-primary/20 group-hover:scale-105 transition-transform ring-2 ring-background">
                                        {session?.user?.name ?
                                            (session.user.name as string).split(' ').map((n: string) => n[0]).join('').toUpperCase() :
                                            'AY'}
                                    </div>
                                    <div className="text-left hidden lg:block">
                                        <div className="text-sm font-black text-foreground group-hover:text-primary transition-colors leading-tight">{session?.user?.name || 'Kullanıcı'}</div>
                                        <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">Yönetici</div>
                                    </div>
                                    <ChevronDown size={14} className={`text-slate-500 transition-transform ${profileMenuOpen ? 'rotate-180' : ''} hidden sm:block`} />
                                </button>

                                <AnimatePresence>
                                    {profileMenuOpen && (
                                        <>
                                            <div
                                                className="fixed inset-0 z-[60]"
                                                onClick={() => setProfileMenuOpen(false)}
                                            />
                                            <motion.div
                                                initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                                animate={{ opacity: 1, y: 0, scale: 1 }}
                                                exit={{ opacity: 0, y: 10, scale: 0.95 }}
                                                className="absolute right-0 mt-2 w-64 bg-surface border border-border rounded-2xl shadow-2xl z-[61] overflow-hidden"
                                            >
                                                <div className="p-4 bg-background/50 border-b border-border">
                                                    <div className="text-sm font-bold text-foreground">{session.user?.name}</div>
                                                    <div className="text-xs text-slate-500 truncate">{session.user?.email}</div>
                                                </div>
                                                <div className="p-2">
                                                    <Link
                                                        href="/dashboard/settings/profile"
                                                        onClick={() => setProfileMenuOpen(false)}
                                                        className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-white/5 text-sm font-medium text-slate-400 hover:text-foreground transition-all"
                                                    >
                                                        <User size={16} /> Profil Düzenle
                                                    </Link>
                                                    <Link
                                                        href="/dashboard/settings"
                                                        onClick={() => setProfileMenuOpen(false)}
                                                        className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-white/5 text-sm font-medium text-slate-400 hover:text-foreground transition-all"
                                                    >
                                                        <Settings size={16} /> Hesap Ayarları
                                                    </Link>
                                                    <div className="h-px bg-border my-2 mx-1" />
                                                    <button
                                                        onClick={() => signOut()}
                                                        className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-red-500/10 text-sm font-medium text-red-400 transition-all"
                                                    >
                                                        <LogOut size={16} /> Çıkış Yap
                                                    </button>
                                                </div>
                                            </motion.div>
                                        </>
                                    )}
                                </AnimatePresence>
                            </div>
                        </div>
                    </div>
                </header>

                {/* Content with Sidebar */}
                <div className="flex flex-1 flex-col lg:flex-row min-h-0">
                    <main id="main-content" role="main" aria-label="Ana içerik" className="dashboard-mobile-content flex-1 p-4 lg:p-8 overflow-x-hidden pb-40 lg:pb-8">
                        <AnimatePresence mode="wait" initial={false}>
                            <motion.div
                                key={pathname}
                                initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 12, scale: 0.995 }}
                                animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0, scale: 1 }}
                                exit={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: -8, scale: 0.995 }}
                                transition={{ duration: shouldReduceMotion ? 0.01 : platformTransitionDuration, ease: [0.22, 1, 0.36, 1] }}
                            >
                                {/* Announcement Banner - Sabit Duyurular */}
                                <AnnouncementBanner
                                    announcements={activeAnnouncements}
                                    onDismiss={dismiss}
                                    onRead={markAsRead}
                                />
                                {children}
                            </motion.div>
                        </AnimatePresence>
                    </main>
                    <LiveFeed isOpen={showLiveFeed} onToggle={toggleLiveFeed} />
                </div>
            </div>

            {/* Mobile Bottom Navigation */}
            <MobileBottomNav onMenuOpen={() => setMobileMenuOpen(true)} onHaptic={triggerHaptic} />

            {/* Mobile Sidebar Drawer */}
            <MobileSidebar
                isOpen={mobileMenuOpen}
                onClose={() => setMobileMenuOpen(false)}
                onHaptic={triggerHaptic}
            />

            <KeyboardShortcutsHelp />
            <AICopilot />
        </div>
    );
}

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
    return (
        <ModuleProvider>
            <WebSocketProvider>
                <ToastProvider>
                    <QuickActionsProvider>
                        <ErrorBoundary>
                            <OnboardingProvider>
                                <DashboardLayoutContent>{children}</DashboardLayoutContent>
                            </OnboardingProvider>
                        </ErrorBoundary>
                    </QuickActionsProvider>
                </ToastProvider>
            </WebSocketProvider>
        </ModuleProvider>
    );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    MessageCircle, Send, Search, Phone, Video, MoreVertical,
    Paperclip, Smile, Image, Star, Archive, Clock, Check, CheckCheck,
    User, Circle, ChevronDown
} from 'lucide-react';

interface Message {
    id: string;
    text: string;
    sender: 'me' | 'customer';
    time: string;
    status: 'sent' | 'delivered' | 'read';
}

interface Chat {
    id: string;
    customer: string;
    avatar: string;
    lastMessage: string;
    time: string;
    unread: number;
    online: boolean;
    platform: string;
    messages: Message[];
}

import { useLiveChat } from '@/lib/hooks';

export default function LiveChatPage() {
    const { data: chatData, loading } = useLiveChat();
    const [selectedChatId, setSelectedChatId] = useState<string | null>(null);
    const [message, setMessage] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [showQuickReplies, setShowQuickReplies] = useState(false);
    const [filter, setFilter] = useState<'all' | 'unread' | 'online'>('all');
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const [chats, setChats] = useState<Chat[]>([]);

    useEffect(() => {
        if (chatData && Array.isArray(chatData)) {
            // Using a short timeout fixes the React synchronous state update warning during render phase
            const timer = setTimeout(() => {
                setChats(chatData as Chat[]);
            }, 0);
            return () => clearTimeout(timer);
        }
    }, [chatData]);

    const selectedChat = chats.find(c => c.id === (selectedChatId || chats[0]?.id));

    const filteredChats = chats.filter(chat => {
        if (searchTerm && !chat.customer.toLowerCase().includes(searchTerm.toLowerCase())) return false;
        if (filter === 'unread' && chat.unread === 0) return false;
        if (filter === 'online' && !chat.online) return false;
        return true;
    });

    const sendMessage = () => {
        if (!message.trim() || !selectedChat) return;

        const timestamp = Date.now();
        const newMsg: Message = {
            id: `m${timestamp}`,
            text: message,
            sender: 'me',
            time: new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }),
            status: 'sent',
        };

        const updatedChats = chats.map(c => {
            if (c.id === selectedChat.id) {
                return { ...c, messages: [...c.messages, newMsg], lastMessage: message, time: 'Şimdi' };
            }
            return c;
        });

        setChats(updatedChats);
        setMessage('');
        setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    };

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [selectedChat]);

    const totalUnread = chats.reduce((s, c) => s + c.unread, 0);

    const quickReplies = [
        'Merhaba! Size nasıl yardımcı olabilirim?',
        'Sipariş numaranızı paylaşır mısınız?',
        'Siparişiniz kargoya verilmiştir.',
        'İade talebiniz onaylanmıştır.',
        'Stok durumunu kontrol ediyorum.',
        'Yardımcı olabildiysem ne mutlu! İyi günler.',
    ];

    return (
        <div className="h-[calc(100vh-8rem)] flex rounded-2xl overflow-hidden border border-border bg-surface animate-in fade-in duration-500">
            {/* Sidebar */}
            <div className="w-80 border-r border-border flex flex-col">
                <div className="p-4 border-b border-border">
                    <div className="flex items-center justify-between mb-3">
                        <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                            <MessageCircle className="w-5 h-5 text-indigo-500" />
                            Mesajlar
                            {totalUnread > 0 && (
                                <span className="px-2 py-0.5 bg-red-500 text-white text-xs rounded-full">{totalUnread}</span>
                            )}
                        </h2>
                    </div>
                    <div className="relative mb-3">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                        <input
                            type="text"
                            placeholder="Müşteri ara..."
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full pl-9 pr-4 py-2 bg-background rounded-xl text-sm text-foreground placeholder:text-slate-500 border border-border focus:border-indigo-500 focus:outline-none"
                        />
                    </div>
                    <div className="flex gap-1">
                        {['all', 'unread', 'online'].map(f => (
                            <button
                                key={f}
                                onClick={() => setFilter(f as typeof filter)}
                                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-colors ${filter === f ? 'bg-indigo-500/20 text-indigo-400' : 'text-slate-500 hover:text-foreground'}`}
                            >
                                {f === 'all' ? 'Tümü' : f === 'unread' ? 'Okunmamış' : 'Çevrimiçi'}
                            </button>
                        ))}
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto">
                    {filteredChats.map(chat => (
                        <button
                            key={chat.id}
                            onClick={() => setSelectedChatId(chat.id)}
                            className={`w-full p-4 flex items-start gap-3 hover:bg-background/50 transition-colors border-b border-border/50 ${selectedChat?.id === chat.id ? 'bg-indigo-500/5 border-l-2 border-l-indigo-500' : ''}`}
                        >
                            <div className="relative flex-shrink-0">
                                <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-full flex items-center justify-center text-xs font-bold text-white">
                                    {chat.avatar}
                                </div>
                                {chat.online && <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 rounded-full border-2 border-surface" />}
                            </div>
                            <div className="flex-1 min-w-0 text-left">
                                <div className="flex items-center justify-between">
                                    <span className="text-sm font-semibold text-foreground">{chat.customer}</span>
                                    <span className="text-xs text-slate-500">{chat.time}</span>
                                </div>
                                <p className="text-xs text-slate-400 truncate mt-0.5">{chat.lastMessage}</p>
                                <span className="text-[10px] px-1.5 py-0.5 bg-background rounded text-slate-500 mt-1 inline-block">{chat.platform}</span>
                            </div>
                            {chat.unread > 0 && (
                                <span className="px-1.5 py-0.5 bg-indigo-500 text-white text-xs rounded-full flex-shrink-0">{chat.unread}</span>
                            )}
                        </button>
                    ))}
                </div>
            </div>

            {/* Chat Area */}
            <div className="flex-1 flex flex-col">
                {!selectedChat ? (
                    <div className="flex-1 flex items-center justify-center text-slate-400">
                        <p className="text-sm">Bir konuşma seçin</p>
                    </div>
                ) : (
                <>
                {/* Chat Header */}
                <div className="p-4 border-b border-border flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="relative">
                            <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-full flex items-center justify-center text-xs font-bold text-white">
                                {selectedChat.avatar}
                            </div>
                            {selectedChat.online && <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 rounded-full border-2 border-surface" />}
                        </div>
                        <div>
                            <h3 className="text-sm font-bold text-foreground">{selectedChat.customer}</h3>
                            <span className="text-xs text-slate-500">{selectedChat.online ? 'Çevrimiçi' : 'Çevrimdışı'} · {selectedChat.platform}</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <button className="p-2 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><Star className="w-4 h-4" /></button>
                        <button className="p-2 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><Archive className="w-4 h-4" /></button>
                        <button className="p-2 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><MoreVertical className="w-4 h-4" /></button>
                    </div>
                </div>

                {/* Messages */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {selectedChat.messages.map((msg: Message) => (
                        <div key={msg.id} className={`flex ${msg.sender === 'me' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[70%] px-4 py-2.5 rounded-2xl ${msg.sender === 'me' ? 'bg-indigo-600 text-white rounded-br-md' : 'bg-background text-foreground rounded-bl-md'}`}>
                                <p className="text-sm">{msg.text}</p>
                                <div className={`flex items-center gap-1 mt-1 ${msg.sender === 'me' ? 'justify-end' : ''}`}>
                                    <span className={`text-[10px] ${msg.sender === 'me' ? 'text-indigo-200' : 'text-slate-500'}`}>{msg.time}</span>
                                    {msg.sender === 'me' && (
                                        msg.status === 'read' ? <CheckCheck className="w-3 h-3 text-blue-300" /> :
                                            msg.status === 'delivered' ? <CheckCheck className="w-3 h-3 text-indigo-200" /> :
                                                <Check className="w-3 h-3 text-indigo-200" />
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                    <div ref={messagesEndRef} />
                </div>

                {/* Quick Replies */}
                <AnimatePresence>
                    {showQuickReplies && (
                        <motion.div
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: 'auto', opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            className="border-t border-border overflow-hidden"
                        >
                            <div className="p-3 flex flex-wrap gap-2">
                                {quickReplies.map((reply, i) => (
                                    <button
                                        key={i}
                                        onClick={() => { setMessage(reply); setShowQuickReplies(false); }}
                                        className="px-3 py-1.5 text-xs bg-background rounded-full text-slate-300 hover:bg-indigo-500/20 hover:text-indigo-400 transition-colors border border-border"
                                    >
                                        {reply}
                                    </button>
                                ))}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Input */}
                <div className="p-4 border-t border-border">
                    <div className="flex items-center gap-2">
                        <button className="p-2 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><Paperclip className="w-4 h-4" /></button>
                        <button className="p-2 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><Image className="w-4 h-4" /></button>
                        <button
                            onClick={() => setShowQuickReplies(!showQuickReplies)}
                            className={`p-2 hover:bg-background rounded-lg transition-colors ${showQuickReplies ? 'text-indigo-400 bg-indigo-500/10' : 'text-slate-400 hover:text-foreground'}`}
                        >
                            <ChevronDown className="w-4 h-4" />
                        </button>
                        <input
                            type="text"
                            value={message}
                            onChange={e => setMessage(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && sendMessage()}
                            placeholder="Mesajınızı yazın..."
                            className="flex-1 px-4 py-2.5 bg-background rounded-xl text-sm text-foreground placeholder:text-slate-500 border border-border focus:border-indigo-500 focus:outline-none"
                        />
                        <button
                            onClick={sendMessage}
                            disabled={!message.trim()}
                            className="p-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-40 rounded-xl text-white transition-colors"
                        >
                            <Send className="w-4 h-4" />
                        </button>
                    </div>
                </div>
                </>
                )}
            </div>
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Bell, BellRing, CheckCircle2, AlertTriangle, Info, XCircle,
    Package, ShoppingCart, TrendingUp, Users, Settings, X,
    Check, Trash2, Filter, MailOpen, Clock
} from 'lucide-react';

type NotifType = 'order' | 'stock' | 'system' | 'marketing' | 'alert';
type NotifPriority = 'info' | 'warning' | 'critical' | 'success';

const priorityConfig: Record<NotifPriority, { color: string; bg: string; icon: typeof Info }> = {
    info: { color: 'text-blue-400', bg: 'bg-blue-500/10', icon: Info },
    warning: { color: 'text-amber-400', bg: 'bg-amber-500/10', icon: AlertTriangle },
    critical: { color: 'text-red-400', bg: 'bg-red-500/10', icon: XCircle },
    success: { color: 'text-emerald-400', bg: 'bg-emerald-500/10', icon: CheckCircle2 },
};

const typeConfig: Record<NotifType, { label: string; icon: typeof Bell; color: string }> = {
    order: { label: 'Sipariş', icon: ShoppingCart, color: 'text-blue-400' },
    stock: { label: 'Stok', icon: Package, color: 'text-amber-400' },
    system: { label: 'Sistem', icon: Settings, color: 'text-slate-400' },
    marketing: { label: 'Pazarlama', icon: TrendingUp, color: 'text-indigo-400' },
    alert: { label: 'Uyarı', icon: AlertTriangle, color: 'text-red-400' },
};

import { useNotifications } from '@/lib/hooks';

export default function NotificationCenterPage() {
    const { notifications, setNotifications, loading, markAsRead, clearAllRead } = useNotifications();
    const [typeFilter, setTypeFilter] = useState<'all' | NotifType>('all');
    const [showSettings, setShowSettings] = useState(false);

    const filtered = notifications.filter(n => typeFilter === 'all' || n.type === typeFilter);
    const unreadCount = notifications.filter(n => !n.read).length;

    const deleteNotif = (id: string) => {
        setNotifications(prev => prev.filter(n => n.id !== id));
    };

    const markAllRead = () => {
        setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    };

    const clearAll = () => {
        setNotifications(prev => prev.filter(n => !n.read));
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                        <BellRing className="w-7 h-7 text-indigo-400" /> Bildirim Merkezi
                        {unreadCount > 0 && (
                            <span className="px-2.5 py-1 bg-red-500 text-white text-xs rounded-full font-bold">{unreadCount}</span>
                        )}
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">Tüm bildirimlerinizi tek yerden yönetin</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={markAllRead} className="flex items-center gap-2 px-3 py-2 text-slate-400 hover:text-foreground text-xs border border-border rounded-xl">
                        <MailOpen className="w-4 h-4" /> Tümünü Oku
                    </button>
                    <button onClick={clearAll} className="flex items-center gap-2 px-3 py-2 text-slate-400 hover:text-foreground text-xs border border-border rounded-xl">
                        <Trash2 className="w-4 h-4" /> Okunmuşları Sil
                    </button>
                    <button onClick={() => setShowSettings(true)} className="p-2 text-slate-400 hover:text-foreground border border-border rounded-xl">
                        <Settings className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-5 gap-3">
                {[
                    { id: 'all' as const, label: 'Tümü', count: notifications.length },
                    ...Object.entries(typeConfig).map(([id, cfg]) => ({ id: id as NotifType, label: cfg.label, count: notifications.filter(n => n.type === id).length })),
                ].map(f => (
                    <button key={f.id} onClick={() => setTypeFilter(f.id)}
                        className={`p-3 rounded-xl border text-center transition-all ${typeFilter === f.id ? 'bg-indigo-600/10 border-indigo-500/30' : 'border-border hover:border-indigo-500/20'}`}>
                        <div className="text-lg font-bold text-foreground">{f.count}</div>
                        <div className="text-xs text-slate-500">{f.label}</div>
                    </button>
                ))}
            </div>

            {/* Notification List */}
            <div className="space-y-2">
                <AnimatePresence>
                    {filtered.map((notif, i) => {
                        const pCfg = priorityConfig[notif.priority as NotifPriority];
                        const tCfg = typeConfig[notif.type as NotifType];
                        return (
                            <motion.div key={notif.id} layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, x: -100 }}
                                transition={{ delay: i * 0.02 }}
                                className={`flex items-start gap-4 p-4 rounded-xl border transition-all ${notif.read ? 'bg-surface border-border' : 'bg-indigo-500/5 border-indigo-500/20'}`}>
                                <div className={`p-2.5 rounded-xl ${pCfg.bg} mt-0.5`}>
                                    <pCfg.icon className={`w-5 h-5 ${pCfg.color}`} />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-0.5">
                                        <h4 className={`text-sm font-medium ${notif.read ? 'text-slate-400' : 'text-foreground'}`}>{notif.title}</h4>
                                        {!notif.read && <div className="w-2 h-2 bg-indigo-500 rounded-full" />}
                                    </div>
                                    <p className="text-xs text-slate-500">{notif.message}</p>
                                    <div className="flex items-center gap-3 mt-2 text-[10px] text-slate-600">
                                        <span className={`flex items-center gap-1 ${tCfg.color}`}>
                                            <tCfg.icon className="w-3 h-3" /> {tCfg.label}
                                        </span>
                                        <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {notif.time}</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-1">
                                    {!notif.read && (
                                        <button onClick={() => markAsRead(notif.id)} className="p-1.5 text-slate-500 hover:text-emerald-400" title="Okundu işaretle">
                                            <Check className="w-4 h-4" />
                                        </button>
                                    )}
                                    <button onClick={() => deleteNotif(notif.id)} className="p-1.5 text-slate-500 hover:text-red-400" title="Sil">
                                        <X className="w-4 h-4" />
                                    </button>
                                </div>
                            </motion.div>
                        );
                    })}
                </AnimatePresence>

                {filtered.length === 0 && (
                    <div className="text-center py-12">
                        <Bell className="w-12 h-12 text-slate-700 mx-auto mb-3" />
                        <p className="text-sm text-slate-500">Bildirim bulunmuyor</p>
                    </div>
                )}
            </div>

            {/* Settings Modal */}
            {showSettings && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50" onClick={() => setShowSettings(false)}>
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl border border-border p-6 w-full max-w-md" onClick={e => e.stopPropagation()}>
                        <h3 className="text-lg font-semibold text-foreground mb-4">Bildirim Ayarları</h3>
                        <div className="space-y-3">
                            {Object.entries(typeConfig).map(([id, cfg]) => (
                                <div key={id} className="flex items-center justify-between p-3 bg-background rounded-xl">
                                    <div className="flex items-center gap-2">
                                        <cfg.icon className={`w-4 h-4 ${cfg.color}`} />
                                        <span className="text-sm text-foreground">{cfg.label}</span>
                                    </div>
                                    <div className="flex gap-3">
                                        {['E-posta', 'Push', 'SMS'].map(ch => (
                                            <label key={ch} className="flex items-center gap-1 text-xs text-slate-500">
                                                <input type="checkbox" defaultChecked={ch !== 'SMS'} className="rounded border-border" />
                                                {ch}
                                            </label>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="flex justify-end gap-2 mt-6">
                            <button onClick={() => setShowSettings(false)} className="px-4 py-2 text-sm text-slate-400">İptal</button>
                            <button onClick={() => setShowSettings(false)} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-sm">Kaydet</button>
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Rocket, ArrowRight, ArrowLeft, Check, Store, Package,
    Globe, CreditCard, Bell, Users, Sparkles, ChevronRight, Truck
} from 'lucide-react';

const STEPS = [
    { id: 1, title: 'Hoş Geldiniz', icon: Rocket, description: 'PazarYönetimi.com hesabınızı kuralım' },
    { id: 2, title: 'Mağaza Bilgileri', icon: Store, description: 'Mağazanız hakkında bilgi verin' },
    { id: 3, title: 'Platform Bağlantısı', icon: Globe, description: 'Pazaryeri hesaplarınızı bağlayın' },
    { id: 4, title: 'Servis Entegrasyonları', icon: Truck, description: 'Kargo, ödeme ve e-fatura servislerini yapılandırın' },
    { id: 5, title: 'Ürün İçe Aktarım', icon: Package, description: 'İlk ürünlerinizi ekleyin' },
    { id: 6, title: 'Bildirim Ayarları', icon: Bell, description: 'Bildirim tercihlerinizi belirleyin' },
    { id: 7, title: 'Hazırsınız!', icon: Sparkles, description: 'Her şey tamam, başlayalım' },
];

const platforms = [
    { id: 'trendyol', name: 'Trendyol', connected: false },
    { id: 'hepsiburada', name: 'Hepsiburada', connected: false },
    { id: 'amazon', name: 'Amazon', connected: false },
    { id: 'n11', name: 'N11', connected: false },
    { id: 'ciceksepeti', name: 'Çiçeksepeti', connected: false },
];

export default function OnboardingPage() {
    const [step, setStep] = useState(1);
    const [storeName, setStoreName] = useState('');
    const [storeCategory, setStoreCategory] = useState('');
    const [connectedPlatforms, setConnectedPlatforms] = useState<string[]>([]);
    const [importMethod, setImportMethod] = useState<string>('');
    const [notifications, setNotifications] = useState({ email: true, push: true, sms: false });

    const currentStep = STEPS.find(s => s.id === step)!;
    const Icon = currentStep.icon;
    const progress = ((step - 1) / (STEPS.length - 1)) * 100;

    const togglePlatform = (id: string) => {
        setConnectedPlatforms(prev => prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]);
    };

    const canNext = () => {
        if (step === 2) return storeName.length > 0;
        return true;
    };

    return (
        <div className="min-h-[calc(100vh-8rem)] flex flex-col items-center justify-center animate-in fade-in duration-500">
            {/* Progress */}
            <div className="w-full max-w-2xl mb-8">
                <div className="flex items-center justify-between mb-3">
                    {STEPS.map(s => (
                        <div key={s.id} className={`flex items-center gap-1.5 ${s.id <= step ? 'text-indigo-400' : 'text-slate-600'}`}>
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold border-2 transition-all ${s.id < step ? 'bg-indigo-600 border-indigo-600 text-white' : s.id === step ? 'border-indigo-500 text-indigo-400' : 'border-slate-700 text-slate-600'}`}>
                                {s.id < step ? <Check className="w-4 h-4" /> : s.id}
                            </div>
                        </div>
                    ))}
                </div>
                <div className="h-1.5 bg-background rounded-full">
                    <motion.div className="h-full bg-indigo-600 rounded-full" initial={{ width: 0 }} animate={{ width: `${progress}%` }} transition={{ duration: 0.3 }} />
                </div>
            </div>

            {/* Card */}
            <AnimatePresence mode="wait">
                <motion.div key={step} initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -50 }}
                    className="w-full max-w-2xl bg-surface rounded-2xl border border-border p-8">

                    <div className="text-center mb-8">
                        <div className="inline-flex p-4 bg-indigo-500/20 rounded-2xl mb-4">
                            <Icon className="w-10 h-10 text-indigo-400" />
                        </div>
                        <h2 className="text-2xl font-bold text-foreground">{currentStep.title}</h2>
                        <p className="text-slate-500 mt-1">{currentStep.description}</p>
                    </div>

                    {/* Step 1: Welcome */}
                    {step === 1 && (
                        <div className="space-y-4 text-center">
                            <p className="text-sm text-slate-400 max-w-md mx-auto">
                                Bu kurulum sihirbazı sizi adım adım yönlendirecek. Hesabınızı birkaç dakika içinde hazırlayabilirsiniz.
                            </p>
                            <div className="grid grid-cols-3 gap-3 mt-6">
                                {['Kolay Kurulum', 'Hızlı Entegrasyon', 'Anında Başla'].map((t, i) => (
                                    <div key={i} className="p-4 bg-background rounded-xl text-center">
                                        <Sparkles className="w-5 h-5 text-indigo-400 mx-auto mb-2" />
                                        <div className="text-xs text-foreground">{t}</div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Step 2: Store Info */}
                    {step === 2 && (
                        <div className="space-y-4 max-w-md mx-auto">
                            <div>
                                <label className="text-sm text-slate-400 block mb-2">Mağaza Adı *</label>
                                <input value={storeName} onChange={e => setStoreName(e.target.value)} placeholder="Mağazanızın adı"
                                    className="w-full px-4 py-3 bg-background rounded-xl text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none placeholder:text-slate-500" />
                            </div>
                            <div>
                                <label className="text-sm text-slate-400 block mb-2">Kategori</label>
                                <select value={storeCategory} onChange={e => setStoreCategory(e.target.value)}
                                    className="w-full px-4 py-3 bg-background rounded-xl text-sm text-foreground border border-border">
                                    <option value="">Seçin...</option>
                                    <option>Elektronik</option>
                                    <option>Giyim</option>
                                    <option>Ev & Yaşam</option>
                                    <option>Kozmetik</option>
                                    <option>Spor</option>
                                    <option>Diğer</option>
                                </select>
                            </div>
                        </div>
                    )}

                    {/* Step 3: Platform Connection */}
                    {step === 3 && (
                        <div className="space-y-3 max-w-md mx-auto">
                            {platforms.map(p => (
                                <button key={p.id} onClick={() => togglePlatform(p.id)}
                                    className={`w-full flex items-center justify-between p-4 rounded-xl border transition-all ${connectedPlatforms.includes(p.id) ? 'bg-emerald-500/10 border-emerald-500/30' : 'border-border hover:border-indigo-500/30'}`}>
                                    <span className="text-sm text-foreground font-medium">{p.name}</span>
                                    {connectedPlatforms.includes(p.id) ? (
                                        <span className="text-xs text-emerald-400 flex items-center gap-1"><Check className="w-4 h-4" /> Bağlı</span>
                                    ) : (
                                        <span className="text-xs text-slate-500">Bağla →</span>
                                    )}
                                </button>
                            ))}
                            <p className="text-xs text-slate-600 text-center mt-3">Daha sonra da bağlayabilirsiniz</p>
                        </div>
                    )}

                    {/* Step 4: Service Integrations */}
                    {step === 4 && (
                        <div className="space-y-4 max-w-md mx-auto">
                            <p className="text-xs text-slate-400 text-center">
                                Bir veya birden fazla servis ekleyin. Daha sonra <strong>Ayarlar → Servis Entegrasyonları</strong> sayfasından değiştirebilirsiniz.
                            </p>
                            {[
                                { id: 'SHIPPING_ARAS', label: 'Aras Kargo', category: 'Kargo', color: 'blue' },
                                { id: 'SHIPPING_YURTICI', label: 'Yurtiçi Kargo', category: 'Kargo', color: 'blue' },
                                { id: 'SHIPPING_MNG', label: 'MNG Kargo', category: 'Kargo', color: 'blue' },
                                { id: 'PAYMENT_IYZICO', label: 'iyzico', category: 'Ödeme', color: 'green' },
                                { id: 'EINVOICE_FORIBA', label: 'Foriba E-Fatura', category: 'E-Fatura', color: 'purple' },
                            ].map((svc) => (
                                <div key={svc.id} className="flex items-center justify-between p-3 rounded-xl bg-background border border-border">
                                    <div>
                                        <span className="text-sm font-medium text-foreground">{svc.label}</span>
                                        <span className={`ml-2 text-xs ${
                                            svc.color === 'blue' ? 'text-blue-400 bg-blue-400/10' :
                                            svc.color === 'green' ? 'text-green-400 bg-green-400/10' :
                                            'text-purple-400 bg-purple-400/10'
                                        } px-1.5 py-0.5 rounded`}>{svc.category}</span>
                                    </div>
                                    <span className="text-xs text-slate-500">Ayarlardan ekle →</span>
                                </div>
                            ))}
                            <button
                                onClick={() => setStep(s => s + 1)}
                                className="w-full text-center text-sm text-slate-500 hover:text-slate-300 py-2"
                            >
                                Şimdi atla, daha sonra ekleyeyim
                            </button>
                        </div>
                    )}

                    {/* Step 5: Import */}
                    {step === 5 && (
                        <div className="grid grid-cols-2 gap-3 max-w-md mx-auto">
                            {[
                                { id: 'platform', label: 'Platformdan Çek', desc: 'Bağlı platformlardan otomatik aktar' },
                                { id: 'csv', label: 'CSV/Excel Yükle', desc: 'Dosyadan toplu içe aktar' },
                                { id: 'manual', label: 'Manuel Ekle', desc: 'Tek tek ürün ekle' },
                                { id: 'skip', label: 'Sonra Yapacağım', desc: 'Bu adımı atla' },
                            ].map(m => (
                                <button key={m.id} onClick={() => setImportMethod(m.id)}
                                    className={`p-4 rounded-xl border text-left transition-all ${importMethod === m.id ? 'bg-indigo-500/10 border-indigo-500/30' : 'border-border hover:border-indigo-500/30'}`}>
                                    <div className="text-sm font-medium text-foreground">{m.label}</div>
                                    <div className="text-xs text-slate-500 mt-1">{m.desc}</div>
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Step 6: Notifications */}
                    {step === 6 && (
                        <div className="space-y-4 max-w-md mx-auto">
                            {[
                                { key: 'email', label: 'E-posta Bildirimleri', desc: 'Sipariş ve stok bildirimleri' },
                                { key: 'push', label: 'Push Bildirimleri', desc: 'Tarayıcı anlık bildirimleri' },
                                { key: 'sms', label: 'SMS Bildirimleri', desc: 'Kritik uyarılar için SMS' },
                            ].map(n => (
                                <div key={n.key} className="flex items-center justify-between p-4 bg-background rounded-xl">
                                    <div>
                                        <div className="text-sm text-foreground">{n.label}</div>
                                        <div className="text-xs text-slate-500">{n.desc}</div>
                                    </div>
                                    <button onClick={() => setNotifications(prev => ({ ...prev, [n.key]: !prev[n.key as keyof typeof prev] }))}
                                        className={`w-12 h-6 rounded-full ${notifications[n.key as keyof typeof notifications] ? 'bg-indigo-600' : 'bg-slate-700'}`}>
                                        <div className={`w-5 h-5 bg-white rounded-full transition-transform ${notifications[n.key as keyof typeof notifications] ? 'translate-x-6' : 'translate-x-0.5'}`} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Step 7: Done */}
                    {step === 7 && (
                        <div className="text-center space-y-4">
                            <div className="text-6xl mb-4">🎉</div>
                            <p className="text-sm text-slate-400 max-w-sm mx-auto">Kurulum tamamlandı! Dashboard&apos;unuza yönlendirileceksiniz.</p>
                            <div className="grid grid-cols-3 gap-3 mt-6">
                                <div className="p-3 bg-background rounded-xl text-center">
                                    <div className="text-lg font-bold text-foreground">{connectedPlatforms.length}</div>
                                    <div className="text-xs text-slate-500">Platform</div>
                                </div>
                                <div className="p-3 bg-background rounded-xl text-center">
                                    <div className="text-lg font-bold text-foreground">{storeName || '-'}</div>
                                    <div className="text-xs text-slate-500">Mağaza</div>
                                </div>
                                <div className="p-3 bg-background rounded-xl text-center">
                                    <div className="text-lg font-bold text-emerald-400">✓</div>
                                    <div className="text-xs text-slate-500">Hazır</div>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Navigation */}
                    <div className="flex items-center justify-between mt-8 pt-6 border-t border-border">
                        {step > 1 ? (
                            <button onClick={() => setStep(s => s - 1)} className="flex items-center gap-2 px-4 py-2 text-sm text-slate-400 hover:text-foreground">
                                <ArrowLeft className="w-4 h-4" /> Geri
                            </button>
                        ) : <div />}
                        {step < STEPS.length ? (
                            <button onClick={() => setStep(s => s + 1)} disabled={!canNext()}
                                className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-40 text-white rounded-xl text-sm font-medium transition-colors">
                                Devam <ArrowRight className="w-4 h-4" />
                            </button>
                        ) : (
                            <button className="flex items-center gap-2 px-6 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-sm font-medium transition-colors">
                                Dashboard&apos;a Git <Sparkles className="w-4 h-4" />
                            </button>
                        )}
                    </div>
                </motion.div>
            </AnimatePresence>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    ShoppingBag,
    Search,
    Filter,
    Download,
    Eye,
    Truck,
    CheckCircle,
    Clock,
    XCircle,
    AlertTriangle,
    Package,
    RefreshCw,
    ChevronDown,
    ArrowUpDown,
    Calendar,
    MapPin,
    Phone,
    User,
    CreditCard,
    MoreVertical,
    Printer,
    MessageSquare,
    ExternalLink
} from 'lucide-react';

import { useOrders, Order, OrderItem } from '@/lib/hooks';

interface OrderPagination {
    total: number;
    page: number;
    limit: number;
    pages: number;
}

// Platform labels
const platformColors: Record<string, string> = {
    "TRENDYOL": "bg-orange-500",
    "AMAZON": "bg-amber-500",
    "HEPSIBURADA": "bg-orange-600",
    "N11": "bg-purple-500",
    "GITTIGIDIYOR": "bg-yellow-500"
};

const statusFilters = ["Tümü", "PENDING", "CONFIRMED", "SHIPPED", "DELIVERED", "CANCELLED", "RETURNED"];
const platformFilters = ["Tümü", "TRENDYOL", "AMAZON", "HEPSIBURADA", "N11"];

export default function OrdersPage() {
    const { getOrders, updateStatus, loading } = useOrders();
    const [orders, setOrders] = useState<Order[]>([]);
    const [pagination, setPagination] = useState<OrderPagination | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedStatus, setSelectedStatus] = useState('Tümü');
    const [selectedPlatform, setSelectedPlatform] = useState('Tümü');
    const [expandedOrder, setExpandedOrder] = useState<string | null>(null);
    const [selectedOrders, setSelectedOrders] = useState<string[]>([]);
    const [dateRange, setDateRange] = useState('today');

    const fetchOrders = async () => {
        const filters: Record<string, string> = {};
        if (searchTerm) filters.search = searchTerm;
        if (selectedStatus !== 'Tümü') filters.status = selectedStatus;
        if (selectedPlatform !== 'Tümü') filters.platform = selectedPlatform;

        const response = await getOrders(filters) as { orders: Order[], pagination: OrderPagination };
        if (response) {
            setOrders(response.orders || []);
            setPagination(response.pagination);
        }
    };

    useEffect(() => {
        fetchOrders();
    }, [searchTerm, selectedStatus, selectedPlatform, dateRange]);

    // fetchOrders definition moved above

    const getStatusConfig = (status: string) => {
        const configs: Record<string, { label: string; color: string; icon: React.ReactNode; bgColor: string }> = {
            PENDING: { label: 'Beklemede', color: 'text-yellow-500', icon: <Clock size={14} />, bgColor: 'bg-yellow-500/10 border-yellow-500/20' },
            CONFIRMED: { label: 'Hazırlanıyor', color: 'text-blue-500', icon: <Package size={14} />, bgColor: 'bg-blue-500/10 border-blue-500/20' },
            SHIPPED: { label: 'Kargoda', color: 'text-purple-500', icon: <Truck size={14} />, bgColor: 'bg-purple-500/10 border-purple-500/20' },
            DELIVERED: { label: 'Teslim Edildi', color: 'text-green-500', icon: <CheckCircle size={14} />, bgColor: 'bg-green-500/10 border-green-500/20' },
            CANCELLED: { label: 'İptal', color: 'text-red-500', icon: <XCircle size={14} />, bgColor: 'bg-red-500/10 border-red-500/20' },
            RETURNED: { label: 'İade', color: 'text-orange-500', icon: <AlertTriangle size={14} />, bgColor: 'bg-orange-500/10 border-orange-500/20' }
        };
        return configs[status] || configs.PENDING;
    };

    const stats = {
        total: orders.length,
        pending: orders.filter(o => o.status === 'PENDING').length,
        preparing: orders.filter(o => o.status === 'CONFIRMED').length,
        shipped: orders.filter(o => o.status === 'SHIPPED').length,
        totalRevenue: orders.filter(o => o.status !== 'CANCELLED' && o.status !== 'RETURNED').reduce((sum, o) => sum + Number(o.totalAmount), 0)
    };

    const formatDate = (dateStr: string) => {
        const date = new Date(dateStr);
        return date.toLocaleDateString('tr-TR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
    };

    const toggleOrderSelect = (orderId: string) => {
        setSelectedOrders(prev =>
            prev.includes(orderId) ? prev.filter(id => id !== orderId) : [...prev, orderId]
        );
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight">Sipariş Yönetimi</h1>
                    <p className="text-slate-500 font-medium">Tüm pazaryerlerinden gelen siparişlerinizi yönetin</p>
                </div>
                <div className="flex items-center gap-3">
                    <select
                        value={dateRange}
                        onChange={(e) => setDateRange(e.target.value)}
                        className="bg-surface border border-border rounded-xl px-4 py-2.5 text-sm font-bold text-foreground focus:outline-none focus:border-primary/50"
                    >
                        <option value="today">Bugün</option>
                        <option value="week">Bu Hafta</option>
                        <option value="month">Bu Ay</option>
                        <option value="custom">Özel Tarih</option>
                    </select>
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <Download size={16} /> Rapor İndir
                    </button>
                    <button onClick={fetchOrders} className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <RefreshCw size={16} className={loading ? "animate-spin" : ""} /> Senkronize Et
                    </button>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-surface p-5 rounded-2xl border border-border">
                    <div className="flex items-center justify-between mb-2">
                        <div className="p-2 rounded-xl bg-blue-500/10"><ShoppingBag size={18} className="text-blue-500" /></div>
                    </div>
                    <div className="text-xl font-black text-foreground">{stats.total}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">Toplam Sipariş</div>
                </motion.div>
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }} className="bg-surface p-5 rounded-2xl border border-border">
                    <div className="flex items-center justify-between mb-2">
                        <div className="p-2 rounded-xl bg-yellow-500/10"><Clock size={18} className="text-yellow-500" /></div>
                    </div>
                    <div className="text-xl font-black text-foreground">{stats.pending}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">Bekleyen</div>
                </motion.div>
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="bg-surface p-5 rounded-2xl border border-border">
                    <div className="flex items-center justify-between mb-2">
                        <div className="p-2 rounded-xl bg-blue-500/10"><Package size={18} className="text-blue-500" /></div>
                    </div>
                    <div className="text-xl font-black text-foreground">{stats.preparing}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">Hazırlanıyor</div>
                </motion.div>
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }} className="bg-surface p-5 rounded-2xl border border-border">
                    <div className="flex items-center justify-between mb-2">
                        <div className="p-2 rounded-xl bg-purple-500/10"><Truck size={18} className="text-purple-500" /></div>
                    </div>
                    <div className="text-xl font-black text-foreground">{stats.shipped}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">Kargoda</div>
                </motion.div>
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }} className="bg-surface p-5 rounded-2xl border border-border">
                    <div className="flex items-center justify-between mb-2">
                        <div className="p-2 rounded-xl bg-emerald-500/10"><CreditCard size={18} className="text-emerald-500" /></div>
                    </div>
                    <div className="text-xl font-black text-foreground">₺{stats.totalRevenue.toLocaleString('tr-TR')}</div>
                    <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">Toplam Ciro</div>
                </motion.div>
            </div>

            {/* Filters */}
            <div className="bg-surface p-4 rounded-2xl border border-border flex flex-wrap items-center gap-4">
                <div className="flex-1 min-w-[300px] relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                    <input
                        type="text"
                        placeholder="Sipariş no veya müşteri ara..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2.5 bg-background border border-border rounded-xl text-sm focus:outline-none focus:border-primary/50"
                    />
                </div>
                <div className="flex items-center gap-2">
                    {platformFilters.map(p => (
                        <button
                            key={p}
                            onClick={() => setSelectedPlatform(p)}
                            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${selectedPlatform === p ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-background text-slate-500 hover:bg-background/80'}`}
                        >
                            {p}
                        </button>
                    ))}
                </div>
                <div className="h-8 w-px bg-border" />
                <div className="flex items-center gap-2">
                    {statusFilters.map(s => (
                        <button
                            key={s}
                            onClick={() => setSelectedStatus(s)}
                            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${selectedStatus === s ? 'bg-foreground text-surface' : 'bg-background text-slate-500 hover:bg-background/80'}`}
                        >
                            {s === 'PENDING' ? 'Bekleyen' : s === 'CONFIRMED' ? 'Hazırlanan' : s === 'SHIPPED' ? 'Kargoda' : s === 'DELIVERED' ? 'Teslim' : s === 'CANCELLED' ? 'İptal' : s === 'RETURNED' ? 'İade' : 'Tümü'}
                        </button>
                    ))}
                </div>
            </div>

            {/* Orders List */}
            <div className="space-y-4">
                {orders.map((order) => {
                    const statusConfig = getStatusConfig(order.status);
                    const isExpanded = expandedOrder === order.id;

                    return (
                        <motion.div
                            key={order.id}
                            layout
                            className={`bg-surface border rounded-2xl overflow-hidden transition-all ${isExpanded ? 'border-primary/30 ring-1 ring-primary/10' : 'border-border hover:border-border/80'}`}
                        >
                            <div className="p-4 flex items-center gap-4 cursor-pointer" onClick={() => setExpandedOrder(isExpanded ? null : order.id)}>
                                <div className="flex items-center gap-3 min-w-[140px]">
                                    <input
                                        type="checkbox"
                                        checked={selectedOrders.includes(order.id)}
                                        onChange={() => toggleOrderSelect(order.id)}
                                        onClick={(e) => e.stopPropagation()}
                                        className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
                                    />
                                    <span className="text-sm font-black text-foreground tabular-nums">#{order.marketplaceOrderId}</span>
                                </div>

                                <div className="flex items-center gap-2 w-32">
                                    <div className={`w-2 h-2 rounded-full ${platformColors[order.platform] || 'bg-slate-400'}`} />
                                    <span className="text-xs font-bold text-slate-600">{order.platform}</span>
                                </div>

                                <div className="flex-1">
                                    <div className="text-sm font-bold text-foreground">{order.customerName}</div>
                                    <div className="text-[10px] text-slate-500 font-medium">{formatDate(order.orderDate)}</div>
                                </div>

                                <div className="w-40">
                                    <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl border text-[10px] font-black uppercase tracking-tight ${statusConfig.bgColor} ${statusConfig.color}`}>
                                        {statusConfig.icon}
                                        {statusConfig.label}
                                    </div>
                                </div>

                                <div className="w-32 text-right">
                                    <div className="text-sm font-black text-foreground">₺{Number(order.totalAmount).toLocaleString('tr-TR')}</div>
                                    <div className="text-[10px] text-slate-500 font-bold uppercase">{order.paymentStatus === 'PAID' ? 'ÖDENDİ' : 'BEKLİYOR'}</div>
                                </div>

                                <ChevronDown size={20} className={`text-slate-400 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} />
                            </div>

                            <AnimatePresence>
                                {isExpanded && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: 'auto', opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        className="border-t border-border bg-background/50"
                                    >
                                        <div className="p-6 grid grid-cols-1 lg:grid-cols-12 gap-8">
                                            <div className="lg:col-span-8 space-y-6">
                                                <div className="space-y-4">
                                                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Sipariş İçeriği</h4>
                                                    <div className="bg-surface rounded-xl border border-border overflow-hidden">
                                                        <table className="w-full text-sm">
                                                            <thead className="bg-background/80 border-b border-border">
                                                                <tr>
                                                                    <th className="px-4 py-2 text-left text-[10px] font-black text-slate-500 uppercase">Ürün</th>
                                                                    <th className="px-4 py-2 text-center text-[10px] font-black text-slate-500 uppercase">Adet</th>
                                                                    <th className="px-4 py-2 text-right text-[10px] font-black text-slate-500 uppercase">Birim Fiyat</th>
                                                                    <th className="px-4 py-2 text-right text-[10px] font-black text-slate-500 uppercase">Toplam</th>
                                                                </tr>
                                                            </thead>
                                                            <tbody className="divide-y divide-border">
                                                                {order.items?.map((item, i: number) => (
                                                                    <tr key={i}>
                                                                        <td className="px-4 py-3 font-bold text-foreground">{item.title}</td>
                                                                        <td className="px-4 py-3 text-center tabular-nums">{item.quantity}</td>
                                                                        <td className="px-4 py-3 text-right tabular-nums">₺{Number(item.unitPrice).toLocaleString()}</td>
                                                                        <td className="px-4 py-3 text-right font-black tabular-nums">₺{(item.quantity * Number(item.unitPrice)).toLocaleString()}</td>
                                                                    </tr>
                                                                ))}
                                                            </tbody>
                                                        </table>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="lg:col-span-4 space-y-6 text-sm">
                                                <div className="bg-surface p-4 rounded-xl border border-border space-y-4">
                                                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Müşteri & Teslimat</h4>
                                                    <div className="space-y-3">
                                                        <div className="flex items-start gap-3">
                                                            <User size={16} className="text-slate-400 mt-0.5" />
                                                            <div>
                                                                <div className="font-bold text-foreground">{order.customerName}</div>
                                                                <div className="text-xs text-slate-500">{order.customerEmail}</div>
                                                            </div>
                                                        </div>
                                                        <div className="flex items-start gap-3">
                                                            <Phone size={16} className="text-slate-400 mt-0.5" />
                                                            <div className="font-medium text-slate-600">{order.customerPhone || 'Bilgi yok'}</div>
                                                        </div>
                                                        <div className="flex items-start gap-3">
                                                            <MapPin size={16} className="text-slate-400 mt-0.5" />
                                                            <div className="text-xs text-slate-600 font-medium leading-relaxed">{order.shippingAddress}</div>
                                                        </div>
                                                    </div>
                                                </div>

                                                <div className="flex gap-2">
                                                    <button className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-primary text-white rounded-xl text-xs font-black shadow-lg shadow-primary/20 hover:bg-primary/90 transition-all">
                                                        <Printer size={14} /> Fatura Yazdır
                                                    </button>
                                                    <button className="px-4 py-2.5 bg-surface border border-border rounded-xl text-slate-600 hover:text-foreground transition-all">
                                                        <MoreVertical size={14} />
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    );
                })}

                {orders.length === 0 && !loading && (
                    <div className="p-20 text-center bg-surface border border-border border-dashed rounded-3xl">
                        <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
                            <ShoppingBag className="text-slate-400" size={32} />
                        </div>
                        <h3 className="text-lg font-black text-foreground">Sipariş Bulunamadı</h3>
                        <p className="text-slate-500 font-medium max-w-xs mx-auto mt-2">Seçili kriterlere uygun herhangi bir siparişiniz bulunmamaktadır.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
    DollarSign,
    TrendingUp,
    TrendingDown,
    CreditCard,
    Wallet,
    ArrowUpRight,
    ArrowDownLeft,
    Calendar,
    Download,
    Filter,
    ChevronDown,
    Building2,
    Receipt,
    Clock,
    CheckCircle,
    AlertTriangle,
    RefreshCw,
    PieChart,
    BarChart3,
    LineChart,
    Target,
    Percent
} from 'lucide-react';
import { usePayments, Payment, PaymentStats as HookPaymentStats, PendingPayment } from '@/lib/hooks';

interface Transaction extends Payment {
    type: 'income' | 'expense' | 'refund';
    description: string;
}

export default function PaymentsPage() {
    const [dateRange, setDateRange] = useState('month');
    const [selectedPlatform, setSelectedPlatform] = useState('all');
    const [apiPayments, setApiPayments] = useState<Transaction[]>([]);
    const [paymentStats, setPaymentStats] = useState<HookPaymentStats | null>(null);
    const [pendingPaymentsList, setPendingPaymentsList] = useState<PendingPayment[]>([]);

    const { fetchPayments: getPayments, fetchStats: getPaymentStats, fetchPending: getPending, loading } = usePayments();

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [paymentsData, statsData, pendingData] = await Promise.allSettled([
                    getPayments(),
                    getPaymentStats(),
                    getPending()
                ]);
                if (paymentsData.status === 'fulfilled' && paymentsData.value) setApiPayments(paymentsData.value as Transaction[]);
                if (statsData.status === 'fulfilled' && statsData.value) setPaymentStats(statsData.value);
                if (pendingData.status === 'fulfilled' && pendingData.value) setPendingPaymentsList(pendingData.value);
            } catch (error) {
                console.error('Ödemeler yüklenirken hata:', error);
            }
        };
        fetchData();
    }, []);

    const payments = apiPayments;

    const financialSummary = paymentStats || {
        totalRevenue: 0,
        netProfit: 0,
        pendingPayments: 0,
        expectedPayments: 0,
        platformFees: 0,
        shippingCosts: 0,
        refunds: 0,
        profitMargin: 0
    };

    const platformBreakdown: { platform: string; revenue: number; fees: number; net: number; color: string; percentage: number }[] = (paymentStats?.platformBreakdown || []).map((p: any, idx: number) => ({
        platform: p.platform,
        revenue: p.revenue || 0,
        fees: p.commission || 0,
        net: p.net || 0,
        color: ['bg-orange-500', 'bg-amber-500', 'bg-orange-600', 'bg-purple-500'][idx] || 'bg-slate-500',
        percentage: p.revenue && financialSummary.totalRevenue ? Math.round((p.revenue / financialSummary.totalRevenue) * 100) : 0
    }));

    const upcomingPayments = pendingPaymentsList;

    const getTransactionIcon = (type: string) => {
        switch (type) {
            case 'income':
                return <ArrowDownLeft size={14} className="text-green-500" />;
            case 'expense':
                return <ArrowUpRight size={14} className="text-red-500" />;
            case 'refund':
                return <RefreshCw size={14} className="text-orange-500" />;
            default:
                return <DollarSign size={14} />;
        }
    };

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'completed':
                return <span className="px-2 py-1 rounded-lg text-[10px] font-bold bg-green-500/10 text-green-500 border border-green-500/20">Tamamlandı</span>;
            case 'pending':
                return <span className="px-2 py-1 rounded-lg text-[10px] font-bold bg-yellow-500/10 text-yellow-500 border border-yellow-500/20">Beklemede</span>;
            default:
                return null;
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="flex flex-col items-center gap-4">
                    <div className="w-10 h-10 border-4 border-primary/30 border-t-primary rounded-full animate-spin" />
                    <p className="text-slate-500 font-medium">Ödemeler yükleniyor...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight">Finans & Ödemeler</h1>
                    <p className="text-slate-500 font-medium">Tüm pazaryerlerinden gelir ve giderlerinizi takip edin</p>
                </div>
                <div className="flex flex-wrap items-center gap-3">
                    <select
                        value={dateRange}
                        onChange={(e) => setDateRange(e.target.value)}
                        className="bg-surface border border-border rounded-xl px-4 py-2.5 text-sm font-bold text-foreground focus:outline-none focus:border-primary/50"
                    >
                        <option value="week">Bu Hafta</option>
                        <option value="month">Bu Ay</option>
                        <option value="quarter">Bu Çeyrek</option>
                        <option value="year">Bu Yıl</option>
                    </select>
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <Download size={16} /> Rapor İndir
                    </button>
                </div>
            </div>

            {/* Main Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-gradient-to-br from-green-500/10 to-emerald-500/5 p-6 rounded-2xl border border-green-500/20"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-green-500/10">
                            <DollarSign size={20} className="text-green-500" />
                        </div>
                        <div className="flex items-center gap-1 text-xs font-bold text-green-500">
                            <TrendingUp size={12} /> +12.5%
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(financialSummary.totalRevenue / 1000).toFixed(1)}K</div>
                    <div className="text-xs text-slate-500 mt-1">Toplam Gelir</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-blue-500/10">
                            <Wallet size={20} className="text-blue-500" />
                        </div>
                        <div className="flex items-center gap-1 text-xs font-bold text-green-500">
                            <TrendingUp size={12} /> +8.3%
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(financialSummary.netProfit / 1000).toFixed(1)}K</div>
                    <div className="text-xs text-slate-500 mt-1">Net Kar</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-yellow-500/10">
                            <Clock size={20} className="text-yellow-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(financialSummary.pendingPayments / 1000).toFixed(1)}K</div>
                    <div className="text-xs text-slate-500 mt-1">Bekleyen Ödemeler</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-purple-500/10">
                            <Percent size={20} className="text-purple-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">%{financialSummary.profitMargin}</div>
                    <div className="text-xs text-slate-500 mt-1">Kar Marjı</div>
                </motion.div>
            </div>

            {/* Secondary Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="bg-surface p-4 rounded-xl border border-border flex items-center gap-4">
                    <div className="p-2 rounded-lg bg-red-500/10">
                        <ArrowUpRight size={16} className="text-red-500" />
                    </div>
                    <div>
                        <div className="text-xs text-slate-500">Platform Komisyonları</div>
                        <div className="text-lg font-bold text-foreground">₺{(financialSummary.platformFees / 1000).toFixed(1)}K</div>
                    </div>
                </div>
                <div className="bg-surface p-4 rounded-xl border border-border flex items-center gap-4">
                    <div className="p-2 rounded-lg bg-orange-500/10">
                        <Receipt size={16} className="text-orange-500" />
                    </div>
                    <div>
                        <div className="text-xs text-slate-500">Kargo Maliyetleri</div>
                        <div className="text-lg font-bold text-foreground">₺{(financialSummary.shippingCosts / 1000).toFixed(1)}K</div>
                    </div>
                </div>
                <div className="bg-surface p-4 rounded-xl border border-border flex items-center gap-4">
                    <div className="p-2 rounded-lg bg-slate-500/10">
                        <RefreshCw size={16} className="text-slate-500" />
                    </div>
                    <div>
                        <div className="text-xs text-slate-500">İadeler</div>
                        <div className="text-lg font-bold text-foreground">₺{(financialSummary.refunds / 1000).toFixed(1)}K</div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Platform Breakdown */}
                <div className="lg:col-span-2 bg-surface rounded-2xl border border-border p-6">
                    <h3 className="font-bold text-foreground mb-4">Pazaryeri Bazlı Gelir</h3>
                    <div className="space-y-4">
                        {platformBreakdown.map((item, idx) => (
                            <motion.div
                                key={item.platform}
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: idx * 0.1 }}
                                className="bg-background p-4 rounded-xl"
                            >
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-8 h-8 rounded-lg ${item.color} flex items-center justify-center`}>
                                            <span className="text-white text-xs font-black">{item.platform[0]}</span>
                                        </div>
                                        <span className="font-medium text-foreground">{item.platform}</span>
                                    </div>
                                    <span className="text-lg font-black text-foreground">₺{(item.revenue / 1000).toFixed(1)}K</span>
                                </div>
                                <div className="h-2 bg-surface rounded-full overflow-hidden">
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${item.percentage}%` }}
                                        transition={{ delay: idx * 0.1 + 0.3, duration: 0.5 }}
                                        className={`h-full ${item.color}`}
                                    />
                                </div>
                                <div className="flex items-center justify-between mt-2 text-xs text-slate-500">
                                    <span>Komisyon: ₺{(item.fees / 1000).toFixed(1)}K</span>
                                    <span>Net: ₺{(item.net / 1000).toFixed(1)}K</span>
                                    <span>{item.percentage}%</span>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                </div>

                {/* Upcoming Payments */}
                <div className="bg-surface rounded-2xl border border-border p-6">
                    <h3 className="font-bold text-foreground mb-4">Yaklaşan Ödemeler</h3>
                    <div className="space-y-3">
                        {upcomingPayments.map((payment, idx) => (
                            <motion.div
                                key={idx}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: idx * 0.1 }}
                                className="bg-background p-4 rounded-xl"
                            >
                                <div className="flex items-center justify-between mb-2">
                                    <span className="font-medium text-foreground">{payment.platform}</span>
                                    <span className="text-lg font-black text-green-500">₺{(payment.amount / 1000).toFixed(1)}K</span>
                                </div>
                                <div className="flex items-center justify-between text-xs text-slate-500">
                                    <span className="flex items-center gap-1">
                                        <Calendar size={10} /> {payment.expectedDate}
                                    </span>
                                    <span className={`px-2 py-0.5 rounded-full ${payment.daysLeft <= 3 ? 'bg-green-500/10 text-green-500' : 'bg-slate-500/10 text-slate-500'}`}>
                                        {payment.daysLeft} gün
                                    </span>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                    <div className="mt-4 p-3 bg-primary/5 border border-primary/20 rounded-xl">
                        <div className="text-xs text-slate-500 mb-1">Toplam Beklenen</div>
                        <div className="text-xl font-black text-primary">
                            ₺{(upcomingPayments.reduce((sum, p) => sum + p.amount, 0) / 1000).toFixed(1)}K
                        </div>
                    </div>
                </div>
            </div>

            {/* Recent Transactions */}
            <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                <div className="p-4 border-b border-border flex items-center justify-between">
                    <h3 className="font-bold text-foreground">Son İşlemler</h3>
                    <button className="text-xs font-bold text-primary hover:text-primary/80 transition-all">
                        Tümünü Gör
                    </button>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="bg-background/50">
                                <th className="px-4 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">İşlem</th>
                                <th className="px-4 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Açıklama</th>
                                <th className="px-4 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Tarih</th>
                                <th className="px-4 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Durum</th>
                                <th className="px-4 py-3 text-right text-[10px] font-black text-slate-500 uppercase tracking-wider">Tutar</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {payments.map((tx, idx) => (
                                <motion.tr
                                    key={tx.id}
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    transition={{ delay: idx * 0.05 }}
                                    className="hover:bg-background/50 transition-all"
                                >
                                    <td className="px-4 py-4">
                                        <div className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${tx.type === 'income' ? 'bg-green-500/10' :
                                            tx.type === 'expense' ? 'bg-red-500/10' : 'bg-orange-500/10'
                                            }`}>
                                            {getTransactionIcon(tx.type)}
                                        </div>
                                    </td>
                                    <td className="px-4 py-4">
                                        <div className="text-sm font-medium text-foreground">{tx.description}</div>
                                        <div className="text-xs text-slate-500">{tx.id}</div>
                                    </td>
                                    <td className="px-4 py-4 text-sm text-slate-500">{tx.date}</td>
                                    <td className="px-4 py-4">{getStatusBadge(tx.status)}</td>
                                    <td className={`px-4 py-4 text-right text-sm font-bold ${tx.amount >= 0 ? 'text-green-500' : 'text-red-500'
                                        }`}>
                                        {tx.amount >= 0 ? '+' : ''}₺{Math.abs(tx.amount).toLocaleString('tr-TR')}
                                    </td>
                                </motion.tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
    Activity, Cpu, MemoryStick, HardDrive, Gauge, Clock,
    TrendingUp, TrendingDown, ArrowUpRight, ArrowDownRight,
    RefreshCw, Zap, Server, Globe, Database, AlertTriangle
} from 'lucide-react';

import { useSystemPerformance } from '@/lib/hooks';

export default function PerformanceMonitorPage() {
    const { data: metricsData, loading } = useSystemPerformance();
    const [timeRange, setTimeRange] = useState<'5m' | '1h' | '24h' | '7d'>('1h');
    const [autoRefresh, setAutoRefresh] = useState(true);

    const metrics = metricsData || {
        cpu: 0,
        memory: 0,
        disk: 0,
        uptime: 'Yükleniyor...',
        responseTime: 0,
        requestsPerSec: 0,
        errorRate: 0,
        activeConnections: 0,
        timeSeries: [],
        memoryTimeSeries: [],
    };

    const timeSeries = metrics.timeSeries || [];
    const memoryTimeSeries = metrics.memoryTimeSeries || [];
    const maxCpu = timeSeries.length > 0 ? Math.max(...timeSeries) : 100;

    const endpointPerf = [
        { path: '/api/products', avg: 42, p95: 120, p99: 250, rpm: 450, errors: 0 },
        { path: '/api/orders', avg: 67, p95: 180, p99: 380, rpm: 320, errors: 2 },
        { path: '/api/sync', avg: 540, p95: 1100, p99: 2500, rpm: 45, errors: 5 },
        { path: '/api/reports', avg: 1450, p95: 3200, p99: 5800, rpm: 12, errors: 0 },
        { path: '/api/customers', avg: 55, p95: 140, p99: 290, rpm: 180, errors: 1 },
        { path: '/api/auth', avg: 28, p95: 65, p99: 120, rpm: 560, errors: 0 },
    ];

    const alerts = [
        { message: 'API yanıt süresi normal seyrediyor', severity: 'info', time: 'Şimdi' },
        { message: 'SSL sertifikası 7 gün sonra sona erecek', severity: 'info', time: '3 saat önce' },
    ];

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                        <Activity className="w-7 h-7 text-indigo-400" /> Performans Monitörü
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">Sistem performansını gerçek zamanlı izleyin</p>
                </div>
                <div className="flex items-center gap-2">
                    {(['5m', '1h', '24h', '7d'] as const).map(r => (
                        <button key={r} onClick={() => setTimeRange(r)}
                            className={`px-3 py-1.5 rounded-lg text-xs font-medium ${timeRange === r ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-foreground'}`}>
                            {r}
                        </button>
                    ))}
                    <button onClick={() => setAutoRefresh(!autoRefresh)}
                        className={`p-2 rounded-lg border ${autoRefresh ? 'border-emerald-500/30 text-emerald-400' : 'border-border text-slate-500'}`}>
                        <RefreshCw className={`w-4 h-4 ${autoRefresh ? 'animate-spin' : ''}`} style={{ animationDuration: '3s' }} />
                    </button>
                </div>
            </div>

            {/* Main Gauges */}
            <div className="grid grid-cols-4 gap-4">
                {[
                    { label: 'CPU Kullanımı', value: metrics.cpu, suffix: '%', icon: Cpu, color: metrics.cpu > 80 ? 'text-red-400' : metrics.cpu > 60 ? 'text-amber-400' : 'text-emerald-400', barColor: metrics.cpu > 80 ? 'bg-red-500' : metrics.cpu > 60 ? 'bg-amber-500' : 'bg-emerald-500' },
                    { label: 'Bellek', value: metrics.memory, suffix: '%', icon: MemoryStick, color: metrics.memory > 80 ? 'text-red-400' : metrics.memory > 60 ? 'text-amber-400' : 'text-emerald-400', barColor: metrics.memory > 80 ? 'bg-red-500' : metrics.memory > 60 ? 'bg-amber-500' : 'bg-emerald-500' },
                    { label: 'Disk', value: metrics.disk, suffix: '%', icon: HardDrive, color: 'text-emerald-400', barColor: 'bg-emerald-500' },
                    { label: 'Uptime', value: metrics.uptime, suffix: '', icon: Clock, color: 'text-blue-400', barColor: 'bg-blue-500' },
                ].map((g, i) => (
                    <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                        className="bg-surface rounded-xl border border-border p-5">
                        <div className="flex items-center justify-between mb-3">
                            <g.icon className={`w-5 h-5 ${g.color}`} />
                            {typeof g.value === 'number' && (
                                <span className={`text-xs ${g.color}`}>{g.value > 60 ? <ArrowUpRight className="w-3 h-3 inline" /> : <ArrowDownRight className="w-3 h-3 inline" />}</span>
                            )}
                        </div>
                        <div className={`text-2xl font-bold ${g.color}`}>{g.value}{g.suffix}</div>
                        <div className="text-xs text-slate-500 mb-2">{g.label}</div>
                        {typeof g.value === 'number' && (
                            <div className="h-1.5 bg-background rounded-full overflow-hidden">
                                <motion.div initial={{ width: 0 }} animate={{ width: `${g.value}%` }}
                                    className={`h-full rounded-full ${g.barColor}`} />
                            </div>
                        )}
                    </motion.div>
                ))}
            </div>

            {/* Secondary Stats */}
            <div className="grid grid-cols-4 gap-4">
                {[
                    { label: 'Yanıt Süresi', value: `${metrics.responseTime}ms`, icon: Gauge, color: 'text-indigo-400', change: '-12ms' },
                    { label: 'İstek/sn', value: metrics.requestsPerSec.toString(), icon: Zap, color: 'text-blue-400', change: '+18' },
                    { label: 'Hata Oranı', value: `%${metrics.errorRate}`, icon: AlertTriangle, color: metrics.errorRate > 1 ? 'text-red-400' : 'text-emerald-400', change: '-0.1%' },
                    { label: 'Aktif Bağlantı', value: metrics.activeConnections.toString(), icon: Globe, color: 'text-amber-400', change: '+5' },
                ].map((stat, i) => (
                    <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 + i * 0.05 }}
                        className="bg-surface rounded-xl border border-border p-4">
                        <div className="flex items-center justify-between">
                            <stat.icon className={`w-4 h-4 ${stat.color}`} />
                            <span className="text-xs text-emerald-400">{stat.change}</span>
                        </div>
                        <div className="text-lg font-bold text-foreground mt-1">{stat.value}</div>
                        <div className="text-[10px] text-slate-500">{stat.label}</div>
                    </motion.div>
                ))}
            </div>

            {/* Charts */}
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-surface rounded-xl border border-border p-5">
                    <h3 className="text-sm font-semibold text-foreground mb-4 flex items-center gap-2">
                        <Cpu className="w-4 h-4 text-indigo-400" /> CPU Kullanım Grafiği
                    </h3>
                    <div className="flex items-end gap-1 h-24">
                        {timeSeries.map((val: number, i: number) => (
                            <motion.div key={i} initial={{ height: 0 }} animate={{ height: `${(val / maxCpu) * 100}%` }}
                                transition={{ delay: i * 0.02 }}
                                className={`flex-1 rounded-t ${val > 70 ? 'bg-red-500/60' : val > 50 ? 'bg-amber-500/60' : 'bg-emerald-500/60'}`} />
                        ))}
                    </div>
                </div>
                <div className="bg-surface rounded-xl border border-border p-5">
                    <h3 className="text-sm font-semibold text-foreground mb-4 flex items-center gap-2">
                        <MemoryStick className="w-4 h-4 text-blue-400" /> Bellek Kullanım Grafiği
                    </h3>
                    <div className="flex items-end gap-1 h-24">
                        {memoryTimeSeries.map((val: number, i: number) => (
                            <motion.div key={i} initial={{ height: 0 }} animate={{ height: `${val}%` }}
                                transition={{ delay: i * 0.02 }}
                                className={`flex-1 rounded-t ${val > 80 ? 'bg-red-500/60' : val > 65 ? 'bg-amber-500/60' : 'bg-blue-500/60'}`} />
                        ))}
                    </div>
                </div>
            </div>

            {/* Endpoint Performance */}
            <div className="bg-surface rounded-xl border border-border overflow-hidden">
                <div className="px-6 py-4 border-b border-border flex items-center gap-2">
                    <Server className="w-4 h-4 text-indigo-400" />
                    <h3 className="text-sm font-semibold text-foreground">Endpoint Performansı</h3>
                </div>
                <table className="w-full text-sm">
                    <thead>
                        <tr className="text-slate-500 text-xs border-b border-border">
                            <th className="text-left px-6 py-3 font-medium">Endpoint</th>
                            <th className="text-left px-4 py-3 font-medium">Ort. (ms)</th>
                            <th className="text-left px-4 py-3 font-medium">P95 (ms)</th>
                            <th className="text-left px-4 py-3 font-medium">P99 (ms)</th>
                            <th className="text-left px-4 py-3 font-medium">İstek/dk</th>
                            <th className="text-left px-4 py-3 font-medium">Hata</th>
                        </tr>
                    </thead>
                    <tbody>
                        {endpointPerf.map((ep, i) => (
                            <motion.tr key={i} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03 }}
                                className="border-b border-border/50 hover:bg-background/50">
                                <td className="px-6 py-3 font-mono text-xs text-indigo-400">{ep.path}</td>
                                <td className={`px-4 py-3 text-xs ${ep.avg > 500 ? 'text-red-400' : ep.avg > 200 ? 'text-amber-400' : 'text-emerald-400'}`}>{ep.avg}</td>
                                <td className={`px-4 py-3 text-xs ${ep.p95 > 1000 ? 'text-red-400' : 'text-slate-400'}`}>{ep.p95}</td>
                                <td className={`px-4 py-3 text-xs ${ep.p99 > 3000 ? 'text-red-400' : 'text-slate-400'}`}>{ep.p99}</td>
                                <td className="px-4 py-3 text-xs text-foreground">{ep.rpm}</td>
                                <td className="px-4 py-3">
                                    <span className={`text-xs ${ep.errors > 0 ? 'text-red-400' : 'text-emerald-400'}`}>{ep.errors}</span>
                                </td>
                            </motion.tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Alerts */}
            {alerts.length > 0 && (
                <div className="bg-surface rounded-xl border border-border p-5">
                    <h3 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
                        <AlertTriangle className="w-4 h-4 text-amber-400" /> Uyarılar
                    </h3>
                    <div className="space-y-2">
                        {alerts.map((alert, i) => (
                            <div key={i} className={`flex items-center justify-between p-3 rounded-lg ${alert.severity === 'warning' ? 'bg-amber-500/5 border border-amber-500/10' : 'bg-blue-500/5 border border-blue-500/10'}`}>
                                <div className="flex items-center gap-2">
                                    <AlertTriangle className={`w-4 h-4 ${alert.severity === 'warning' ? 'text-amber-400' : 'text-blue-400'}`} />
                                    <span className="text-xs text-foreground">{alert.message}</span>
                                </div>
                                <span className="text-[10px] text-slate-500">{alert.time}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Brain,
    TrendingUp,
    TrendingDown,
    Calendar,
    Target,
    Zap,
    AlertCircle,
    CheckCircle2,
    Clock,
    RefreshCw,
    Download,
    ChevronRight,
    Sparkles,
    BarChart3,
    ArrowUpRight,
    ArrowDownRight,
    Eye,
    ShoppingCart,
    DollarSign
} from 'lucide-react';
import { useMarketIntelForecast, usePredictions, Prediction } from '@/lib/hooks';

interface PredictionInsight {
    type: string;
    title: string;
    description: string;
    action: string;
    impact: string;
}

interface PredictionSummary {
    expectedRevenue: number;
    growthRate: number;
}

interface PredictionProduct {
    id: string;
    product: string;
    currentSales: number;
    predictedSales: number;
    change: number;
    confidence: number;
    trend: string;
    factors: string[];
}

export default function PredictionsPage() {
    const [selectedPeriod, setSelectedPeriod] = useState('weekly');
    const [showDetails, setShowDetails] = useState<string | null>(null);

    const { data: realForecast, loading: forecastLoading } = useMarketIntelForecast('general');
    const { predictions: apiPredictions, loading: predictionsLoading } = usePredictions();

    const salesPredictions: PredictionProduct[] = (Array.isArray(apiPredictions) && apiPredictions.length > 0) ? (apiPredictions as Prediction[]).map((p) => ({
        id: p.id,
        product: p.productName || p.productId,
        currentSales: p.currentValue || 0,
        predictedSales: p.predictedValue || 0,
        change: p.predictedValue && p.currentValue ? ((p.predictedValue - p.currentValue) / p.currentValue * 100) : 0,
        confidence: p.confidence || 0,
        trend: p.trend || 'stable',
        factors: p.insights || []
    })) : [];

    const forecastFirst = Array.isArray(realForecast) && realForecast.length > 0 ? realForecast[0] : null;

    const weeklyForecast = (Array.isArray((forecastFirst as any)?.forecast) ? (forecastFirst as any).forecast : []).map((f: any) => ({
        day: f.date || '',
        predicted: f.predicted || 0,
        actual: null
    }));

    const insights: PredictionInsight[] = (Array.isArray((forecastFirst as any)?.insights) ? (forecastFirst as any).insights : []).map((i: any) => ({
        type: i.type || 'info',
        title: i.title || '',
        description: i.description || '',
        action: 'Detayları Gör',
        impact: 'medium'
    }));

    const forecastSummary = (forecastFirst as any)?.summary;
    const totalPredictedRevenue = forecastSummary?.expectedRevenue || 0;
    const accuracy = forecastSummary?.growthRate ? Math.min(Math.round(forecastSummary.growthRate), 100) : 0;
    const activeModels = salesPredictions.length || 0;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="mb-8">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                            <Brain className="w-8 h-8 text-purple-500" />
                            Satış Tahminleri
                        </h1>
                        <p className="text-slate-500 dark:text-slate-400 mt-1">
                            AI destekli satış öngörüleri ve tahminler
                        </p>
                    </div>
                    <div className="flex items-center gap-3">
                        <motion.button
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-slate-600 dark:text-slate-300 hover:text-foreground transition-colors"
                        >
                            <RefreshCw className="w-4 h-4" />
                            Tahminleri Güncelle
                        </motion.button>
                        <motion.button
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            className="flex items-center gap-2 px-4 py-2 bg-purple-600 rounded-lg text-white hover:bg-purple-700 transition-colors"
                        >
                            <Download className="w-4 h-4" />
                            Rapor İndir
                        </motion.button>
                    </div>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-gradient-to-br from-purple-500/10 to-purple-600/5 dark:from-purple-900/40 dark:to-purple-800/20 rounded-2xl p-5 border border-purple-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-purple-500/20 rounded-xl">
                            <DollarSign className="w-5 h-5 text-purple-600 dark:text-purple-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Tahmini Gelir (7 Gün)</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">
                        ₺{totalPredictedRevenue.toLocaleString('tr-TR')}
                    </div>
                    <div className="flex items-center gap-1 mt-2 text-green-400 text-sm">
                        <ArrowUpRight className="w-4 h-4" />
                        <span>+12.5% önceki haftaya göre</span>
                    </div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-gradient-to-br from-green-500/10 to-green-600/5 dark:from-green-900/40 dark:to-green-800/20 rounded-2xl p-5 border border-green-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-green-500/20 rounded-xl">
                            <Target className="w-5 h-5 text-green-600 dark:text-green-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Tahmin Doğruluğu</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">%{accuracy}</div>
                    <div className="w-full bg-slate-200 dark:bg-slate-700 rounded-full h-2 mt-3">
                        <div
                            className="bg-green-500 h-2 rounded-full transition-all duration-500"
                            style={{ width: `${accuracy}%` }}
                        />
                    </div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-gradient-to-br from-blue-500/10 to-blue-600/5 dark:from-blue-900/40 dark:to-blue-800/20 rounded-2xl p-5 border border-blue-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-blue-500/20 rounded-xl">
                            <Brain className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Aktif AI Modelleri</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">{activeModels}</div>
                    <div className="flex items-center gap-1 mt-2 text-blue-400 text-sm">
                        <Sparkles className="w-4 h-4" />
                        <span>Tüm modeller aktif</span>
                    </div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-gradient-to-br from-orange-500/10 to-orange-600/5 dark:from-orange-900/40 dark:to-orange-800/20 rounded-2xl p-5 border border-orange-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-orange-500/20 rounded-xl">
                            <Clock className="w-5 h-5 text-orange-600 dark:text-orange-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Son Güncelleme</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">2 saat önce</div>
                    <div className="flex items-center gap-1 mt-2 text-orange-400 text-sm">
                        <RefreshCw className="w-4 h-4" />
                        <span>Otomatik güncelleme aktif</span>
                    </div>
                </motion.div>
            </div>

            {/* Period Selection */}
            <div className="flex items-center gap-2 mb-6">
                {['daily', 'weekly', 'monthly'].map((period) => (
                    <button
                        key={period}
                        onClick={() => setSelectedPeriod(period)}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${selectedPeriod === period
                            ? 'bg-purple-600 text-white'
                            : 'bg-surface border border-border text-slate-500 hover:text-foreground'
                            }`}
                    >
                        {period === 'daily' && 'Günlük'}
                        {period === 'weekly' && 'Haftalık'}
                        {period === 'monthly' && 'Aylık'}
                    </button>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                {/* Weekly Forecast Chart */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="lg:col-span-2 bg-surface rounded-2xl p-6 border border-border"
                >
                    <h2 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
                        <BarChart3 className="w-5 h-5 text-purple-500" />
                        Haftalık Satış Tahmini
                    </h2>
                    <div className="space-y-4">
                        {weeklyForecast.map((day: any, index: number) => (
                            <div key={day.day} className="flex items-center gap-4">
                                <div className="w-24 text-sm text-slate-600 dark:text-slate-400">{day.day}</div>
                                <div className="flex-1 relative">
                                    <div className="h-8 bg-background rounded-xl border border-border overflow-hidden relative">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${(day.predicted / 25000) * 100}%` }}
                                            transition={{ delay: index * 0.1, duration: 0.5 }}
                                            className="h-full bg-purple-500/40 rounded-lg"
                                        />
                                        {day.actual && (
                                            <motion.div
                                                initial={{ width: 0 }}
                                                animate={{ width: `${(day.actual / 25000) * 100}%` }}
                                                transition={{ delay: index * 0.1 + 0.2, duration: 0.5 }}
                                                className="absolute top-0 left-0 h-full bg-green-500/60 rounded-lg"
                                            />
                                        )}
                                    </div>
                                </div>
                                <div className="w-28 text-right">
                                    <div className="text-sm font-medium text-foreground">
                                        ₺{day.predicted.toLocaleString('tr-TR')}
                                    </div>
                                    {day.actual && (
                                        <div className={`text-xs ${day.actual >= day.predicted ? 'text-green-400' : 'text-red-400'}`}>
                                            Gerçek: ₺{day.actual.toLocaleString('tr-TR')}
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="flex items-center gap-6 mt-6 pt-4 border-t border-border">
                        <div className="flex items-center gap-2">
                            <div className="w-3 h-3 rounded-full bg-purple-500/40" />
                            <span className="text-sm text-slate-600 dark:text-slate-400">Tahmin</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-3 h-3 rounded-full bg-green-500/60" />
                            <span className="text-sm text-slate-600 dark:text-slate-400">Gerçekleşen</span>
                        </div>
                    </div>
                </motion.div>

                {/* AI Insights */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-surface rounded-2xl p-6 border border-border"
                >
                    <h2 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
                        <Zap className="w-5 h-5 text-yellow-500" />
                        AI İçgörüleri
                    </h2>
                    <div className="space-y-4">
                        {insights.map((insight, index: number) => (
                            <motion.div
                                key={index}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: index * 0.1 }}
                                className={`p-4 rounded-lg border ${insight.type === 'opportunity'
                                    ? 'bg-green-900/20 border-green-500/30'
                                    : insight.type === 'warning'
                                        ? 'bg-yellow-900/20 border-yellow-500/30'
                                        : 'bg-blue-900/20 border-blue-500/30'
                                    }`}
                            >
                                <div className="flex items-start gap-3">
                                    {insight.type === 'opportunity' && (
                                        <CheckCircle2 className="w-5 h-5 text-green-400 flex-shrink-0 mt-0.5" />
                                    )}
                                    {insight.type === 'warning' && (
                                        <AlertCircle className="w-5 h-5 text-yellow-400 flex-shrink-0 mt-0.5" />
                                    )}
                                    {insight.type === 'info' && (
                                        <Eye className="w-5 h-5 text-blue-400 flex-shrink-0 mt-0.5" />
                                    )}
                                    <div className="flex-1">
                                        <h3 className="text-sm font-medium text-foreground">{insight.title}</h3>
                                        <p className="text-xs text-slate-500 mt-1">{insight.description}</p>
                                        <button className="mt-2 text-xs text-purple-400 hover:text-purple-300 flex items-center gap-1">
                                            {insight.action}
                                            <ChevronRight className="w-3 h-3" />
                                        </button>
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                </motion.div>
            </div>

            {/* Product Predictions Table */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-surface rounded-2xl border border-border overflow-hidden"
            >
                <div className="p-6 border-b border-border">
                    <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                        <ShoppingCart className="w-5 h-5 text-purple-500" />
                        Ürün Bazlı Satış Tahminleri
                    </h2>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead className="bg-background">
                            <tr>
                                <th className="text-left p-4 text-slate-500 text-sm font-bold">Ürün</th>
                                <th className="text-right p-4 text-slate-500 text-sm font-bold">Mevcut Satış</th>
                                <th className="text-right p-4 text-slate-500 text-sm font-bold">Tahmini Satış</th>
                                <th className="text-right p-4 text-slate-500 text-sm font-bold">Değişim</th>
                                <th className="text-center p-4 text-slate-500 text-sm font-bold">Güven Oranı</th>
                                <th className="text-center p-4 text-slate-500 text-sm font-bold">Detay</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {salesPredictions.map((item) => (
                                <React.Fragment key={item.id}>
                                    <tr className="hover:bg-background/50 transition-colors">
                                        <td className="p-4">
                                            <span className="text-foreground font-medium">{item.product}</span>
                                        </td>
                                        <td className="p-4 text-right text-slate-600 dark:text-slate-300">{item.currentSales} adet</td>
                                        <td className="p-4 text-right text-foreground font-medium">{item.predictedSales} adet</td>
                                        <td className="p-4 text-right">
                                            <span className={`flex items-center justify-end gap-1 ${item.trend === 'up' ? 'text-green-400' : 'text-red-400'
                                                }`}>
                                                {item.trend === 'up' ? (
                                                    <TrendingUp className="w-4 h-4" />
                                                ) : (
                                                    <TrendingDown className="w-4 h-4" />
                                                )}
                                                {item.change > 0 ? '+' : ''}{item.change}%
                                            </span>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex items-center justify-center gap-2">
                                                <div className="w-16 bg-slate-200 dark:bg-slate-700 rounded-full h-2">
                                                    <div
                                                        className={`h-2 rounded-full ${item.confidence >= 90
                                                            ? 'bg-green-500'
                                                            : item.confidence >= 80
                                                                ? 'bg-blue-500'
                                                                : 'bg-yellow-500'
                                                            }`}
                                                        style={{ width: `${item.confidence}%` }}
                                                    />
                                                </div>
                                                <span className="text-sm text-slate-500">%{item.confidence}</span>
                                            </div>
                                        </td>
                                        <td className="p-4 text-center">
                                            <button
                                                onClick={() => setShowDetails(showDetails === String(item.id) ? null : String(item.id))}
                                                className="p-2 text-slate-500 hover:text-foreground hover:bg-background rounded-lg transition-colors"
                                            >
                                                <ChevronRight className={`w-4 h-4 transition-transform ${showDetails === String(item.id) ? 'rotate-90' : ''}`} />
                                            </button>
                                        </td>
                                    </tr>
                                    {showDetails === String(item.id) && (
                                        <tr>
                                            <td colSpan={6} className="p-4 bg-slate-100 dark:bg-slate-800/30">
                                                <div className="flex items-start gap-3">
                                                    <Brain className="w-5 h-5 text-purple-400 mt-0.5" />
                                                    <div>
                                                        <h4 className="text-sm font-medium text-foreground mb-2">Tahmin Faktörleri:</h4>
                                                        <ul className="space-y-1">
                                                            {item.factors.map((factor, i: number) => (
                                                                <li key={i} className="text-sm text-slate-500 flex items-center gap-2">
                                                                    <span className="w-1.5 h-1.5 bg-purple-400 rounded-full" />
                                                                    {factor}
                                                                </li>
                                                            ))}
                                                        </ul>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                        </tbody>
                    </table>
                </div>
            </motion.div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Target, Zap, Check, X, Settings, TrendingUp, TrendingDown,
    RefreshCw, Plus, Loader2, ChevronRight, Shield, Globe, Bell,
    Clock, BarChart3, ArrowRight, Play, Pause, Trash2
} from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface PriceRule {
    id: string;
    name: string;
    platform: string;
    type: 'min_margin' | 'competitor_match' | 'dynamic' | 'time_based';
    status: 'active' | 'paused';
    affectedProducts: number;
    avgPriceChange: number;
    description: string;
    minMargin?: number;
}

interface PriceSuggestion {
    id: string;
    product: string;
    currentPrice: number;
    suggestedPrice: number;
    competitorPrice: number;
    margin: number;
    reason: string;
    impact: string;
    platform: string;
}

interface PriceHistory {
    id: string;
    date: string;
    product: string;
    oldPrice: number;
    newPrice: number;
    source: string;
    platform: string;
}

const RULE_TYPE_LABELS: Record<string, string> = {
    min_margin: 'Min. Marj',
    competitor_match: 'Rakip Eşleştir',
    dynamic: 'Dinamik',
    time_based: 'Zamanlı',
};

const RULE_TYPE_ICONS: Record<string, any> = {
    min_margin: Shield,
    competitor_match: Globe,
    dynamic: Zap,
    time_based: Clock,
};

export default function PriceOptimizationPage() {
    const [tab, setTab] = useState<'suggestions' | 'rules' | 'history'>('suggestions');

    // Suggestions state
    const [suggestions, setSuggestions] = useState<PriceSuggestion[]>([]);
    const [sugLoading, setSugLoading] = useState(true);
    const [approvedIds, setApprovedIds] = useState<string[]>([]);
    const [rejectedIds, setRejectedIds] = useState<string[]>([]);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    // Rules state
    const [rules, setRules] = useState<PriceRule[]>([]);
    const [rulesLoading, setRulesLoading] = useState(true);
    const [showNewRule, setShowNewRule] = useState(false);

    // History state
    const [history, setHistory] = useState<PriceHistory[]>([]);
    const [histLoading, setHistLoading] = useState(false);

    const loadSuggestions = async () => {
        setSugLoading(true);
        try {
            const data = await apiClient.request<PriceSuggestion[]>('/price-suggestions');
            setSuggestions(data || []);
        } catch { setSuggestions([]); }
        setSugLoading(false);
    };

    const loadRules = async () => {
        setRulesLoading(true);
        try {
            const data = await apiClient.request<PriceRule[]>('/price-rules');
            setRules(data || []);
        } catch { setRules([]); }
        setRulesLoading(false);
    };

    const loadHistory = async () => {
        setHistLoading(true);
        try {
            const data = await apiClient.request<PriceHistory[]>('/price-history');
            setHistory(data || []);
        } catch { setHistory([]); }
        setHistLoading(false);
    };

    useEffect(() => { loadSuggestions(); loadRules(); }, []);
    useEffect(() => { if (tab === 'history' && history.length === 0) loadHistory(); }, [tab]);

    // Load functions hoisted above

    const approve = async (id: string) => {
        setActionLoading(id);
        try {
            await apiClient.request(`/price-suggestions/${id}/approve`, { method: 'POST' });
            setApprovedIds(prev => [...prev, id]);
        } catch { setApprovedIds(prev => [...prev, id]); }
        setActionLoading(null);
    };

    const reject = async (id: string) => {
        setActionLoading(id);
        try {
            await apiClient.request(`/price-suggestions/${id}/reject`, { method: 'POST' });
            setRejectedIds(prev => [...prev, id]);
        } catch { setRejectedIds(prev => [...prev, id]); }
        setActionLoading(null);
    };

    const toggleRule = async (rule: PriceRule) => {
        const newStatus = rule.status === 'active' ? 'paused' : 'active';
        try {
            await apiClient.request(`/price-rules/${rule.id}`, { method: 'PATCH', body: JSON.stringify({ status: newStatus }) });
            setRules(prev => prev.map(r => r.id === rule.id ? { ...r, status: newStatus } : r));
        } catch { /* ignore */ }
    };

    const deleteRule = async (id: string) => {
        try {
            await apiClient.request(`/price-rules/${id}`, { method: 'DELETE' });
            setRules(prev => prev.filter(r => r.id !== id));
        } catch { /* ignore */ }
    };

    const pendingSuggestions = suggestions.filter(s => !approvedIds.includes(s.id) && !rejectedIds.includes(s.id));
    const activeRules = rules.filter(r => r.status === 'active').length;

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-foreground flex items-center gap-3">
                        <Target className="w-8 h-8 text-emerald-500" /> Fiyat Optimizasyonu
                    </h1>
                    <p className="text-slate-500 mt-1 font-medium">AI destekli fiyat önerileri ve otomatik fiyatlandırma kuralları</p>
                </div>
                <div className="flex items-center gap-2">
                    <span className="px-3 py-1.5 bg-emerald-500/20 text-emerald-400 text-xs rounded-full font-bold flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" /> AI Aktif
                    </span>
                    <button onClick={loadSuggestions} className="p-2 hover:bg-surface rounded-xl text-slate-400 hover:text-foreground transition-all">
                        <RefreshCw className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex gap-1 bg-surface border border-border rounded-xl p-1">
                {[
                    { id: 'suggestions', label: 'Fiyat Önerileri', count: pendingSuggestions.length },
                    { id: 'rules', label: 'Fiyat Kuralları', count: activeRules },
                    { id: 'history', label: 'Değişiklik Geçmişi' },
                ].map(t => (
                    <button key={t.id} onClick={() => setTab(t.id as typeof tab)}
                        className={`flex-1 py-2.5 text-sm rounded-lg font-medium transition-all flex items-center justify-center gap-2 ${tab === t.id ? 'bg-emerald-500/20 text-emerald-400' : 'text-slate-500 hover:text-foreground'}`}>
                        {t.label}
                        {t.count !== undefined && t.count > 0 && (
                            <span className="px-1.5 py-0.5 bg-background rounded-full text-xs font-bold">{t.count}</span>
                        )}
                    </button>
                ))}
            </div>

            {/* SUGGESTIONS */}
            {tab === 'suggestions' && (
                <div className="space-y-4">
                    {/* Summary cards */}
                    <div className="grid grid-cols-3 gap-4">
                        <div className="bg-surface rounded-2xl border border-border p-5">
                            <div className="text-xs text-slate-500 mb-1">Potansiyel Kâr Artışı</div>
                            <div className="text-2xl font-black text-emerald-500">
                                {sugLoading ? '—' : `+₺${(pendingSuggestions.reduce((s, p) => s + Math.abs(p.suggestedPrice - p.currentPrice) * 30, 0)).toLocaleString('tr-TR')}/ay`}
                            </div>
                        </div>
                        <div className="bg-surface rounded-2xl border border-border p-5">
                            <div className="text-xs text-slate-500 mb-1">Bekleyen Öneriler</div>
                            <div className="text-2xl font-black text-foreground">{sugLoading ? '—' : pendingSuggestions.length}</div>
                        </div>
                        <div className="bg-surface rounded-2xl border border-border p-5">
                            <div className="text-xs text-slate-500 mb-1">Ort. Marj İyileşme</div>
                            <div className="text-2xl font-black text-blue-500">
                                {pendingSuggestions.length > 0
                                    ? `+${(pendingSuggestions.reduce((s, p) => s + p.margin, 0) / pendingSuggestions.length).toFixed(1)}%`
                                    : '—'}
                            </div>
                        </div>
                    </div>

                    {sugLoading ? (
                        <div className="py-16 flex items-center justify-center gap-3 text-slate-500 bg-surface rounded-2xl border border-border">
                            <Loader2 size={20} className="animate-spin" /><span className="text-sm">Öneriler yükleniyor...</span>
                        </div>
                    ) : pendingSuggestions.length === 0 ? (
                        <div className="text-center py-16 bg-surface rounded-2xl border border-dashed border-border">
                            <Target size={40} className="mx-auto mb-3 text-slate-300" />
                            <p className="font-bold text-foreground">Tüm öneriler değerlendirildi ✓</p>
                            <p className="text-sm text-slate-500 mt-1">Yeni öneriler için AI tarama yapılıyor</p>
                        </div>
                    ) : (
                        pendingSuggestions.map((s, i) => (
                            <motion.div key={s.id} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.08 }}
                                className="bg-surface rounded-2xl border border-border p-5 hover:border-emerald-500/30 transition-all">
                                <div className="flex items-start justify-between">
                                    <div className="flex-1">
                                        <div className="flex items-center gap-3 mb-3">
                                            <h3 className="text-sm font-bold text-foreground">{s.product}</h3>
                                            <span className="px-2 py-0.5 bg-background text-slate-500 text-xs rounded border border-border">{s.platform}</span>
                                        </div>
                                        <div className="flex items-center gap-8 mb-3">
                                            {[
                                                { label: 'Mevcut', value: `₺${s.currentPrice}`, cls: 'text-foreground' },
                                                { label: '', value: <ArrowRight size={16} className="text-slate-500" />, cls: '' },
                                                { label: 'Önerilen', value: `₺${s.suggestedPrice}`, cls: s.suggestedPrice < s.currentPrice ? 'text-red-500' : 'text-emerald-500' },
                                                { label: 'Rakip', value: `₺${s.competitorPrice}`, cls: 'text-slate-400' },
                                                { label: 'Marj', value: `%${s.margin}`, cls: 'text-blue-500' },
                                            ].map((f, fi) => (
                                                <div key={fi}>
                                                    {f.label && <div className="text-[10px] text-slate-500 mb-1">{f.label}</div>}
                                                    <div className={`text-base font-black ${f.cls}`}>{f.value}</div>
                                                </div>
                                            ))}
                                        </div>
                                        <div className="flex items-center gap-4 text-xs">
                                            <span className="flex items-center gap-1 text-amber-500"><Bell size={10} /> {s.reason}</span>
                                            <span className="flex items-center gap-1 text-emerald-500"><TrendingUp size={10} /> {s.impact}</span>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2 ml-4">
                                        {actionLoading === s.id ? (
                                            <div className="p-2"><Loader2 size={18} className="animate-spin text-slate-400" /></div>
                                        ) : (
                                            <>
                                                <button onClick={() => approve(s.id)} className="p-2.5 bg-emerald-500/15 hover:bg-emerald-500/30 text-emerald-500 rounded-xl transition-all"><Check className="w-4 h-4" /></button>
                                                <button onClick={() => reject(s.id)} className="p-2.5 bg-red-500/15 hover:bg-red-500/30 text-red-500 rounded-xl transition-all"><X className="w-4 h-4" /></button>
                                            </>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        ))
                    )}
                </div>
            )}

            {/* RULES */}
            {tab === 'rules' && (
                <div className="space-y-4">
                    <div className="flex justify-end">
                        <button onClick={() => setShowNewRule(true)}
                            className="flex items-center gap-2 px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-sm font-bold transition-all">
                            <Plus size={16} /> Yeni Kural
                        </button>
                    </div>

                    {rulesLoading ? (
                        <div className="py-16 flex items-center justify-center gap-3 text-slate-500 bg-surface rounded-2xl border border-border">
                            <Loader2 size={20} className="animate-spin" /><span className="text-sm">Kurallar yükleniyor...</span>
                        </div>
                    ) : rules.length === 0 ? (
                        <div className="text-center py-16 bg-surface rounded-2xl border border-dashed border-border">
                            <Shield size={40} className="mx-auto mb-3 text-slate-300" />
                            <p className="font-bold text-foreground">Henüz fiyat kuralı yok</p>
                            <p className="text-sm text-slate-500 mt-1">İlk kuralı oluşturun</p>
                        </div>
                    ) : (
                        rules.map((rule, i) => {
                            const Icon = RULE_TYPE_ICONS[rule.type] || Shield;
                            return (
                                <motion.div key={rule.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}
                                    className="bg-surface rounded-2xl border border-border p-5 hover:border-slate-400/30 transition-all">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-4">
                                            <div className={`p-2.5 rounded-xl ${rule.status === 'active' ? 'bg-emerald-500/10' : 'bg-slate-500/10'}`}>
                                                <Icon className={`w-5 h-5 ${rule.status === 'active' ? 'text-emerald-500' : 'text-slate-500'}`} />
                                            </div>
                                            <div>
                                                <div className="flex items-center gap-2 mb-1">
                                                    <h3 className="text-sm font-bold text-foreground">{rule.name}</h3>
                                                    <span className={`px-2 py-0.5 text-[10px] font-bold rounded-full ${rule.status === 'active' ? 'bg-emerald-500/15 text-emerald-500' : 'bg-slate-500/15 text-slate-400'}`}>
                                                        {rule.status === 'active' ? 'Aktif' : 'Duraklatıldı'}
                                                    </span>
                                                    <span className="px-2 py-0.5 bg-background text-slate-500 text-[10px] rounded border border-border">{rule.platform}</span>
                                                    <span className="px-2 py-0.5 bg-background text-slate-500 text-[10px] rounded border border-border">{RULE_TYPE_LABELS[rule.type]}</span>
                                                </div>
                                                <p className="text-xs text-slate-500">{rule.description}</p>
                                                <div className="flex items-center gap-4 mt-1 text-[10px] text-slate-600">
                                                    <span>{rule.affectedProducts} ürün</span>
                                                    <span className={rule.avgPriceChange > 0 ? 'text-emerald-500' : 'text-red-500'}>
                                                        {rule.avgPriceChange > 0 ? '+' : ''}{rule.avgPriceChange}% ort.
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <button onClick={() => toggleRule(rule)}
                                                className={`p-2 rounded-xl transition-all ${rule.status === 'active' ? 'text-yellow-500 hover:bg-yellow-500/10' : 'text-emerald-500 hover:bg-emerald-500/10'}`}>
                                                {rule.status === 'active' ? <Pause size={16} /> : <Play size={16} />}
                                            </button>
                                            <button className="p-2 hover:bg-background rounded-xl text-slate-400 hover:text-foreground transition-all">
                                                <Settings size={16} />
                                            </button>
                                            <button onClick={() => deleteRule(rule.id)} className="p-2 hover:bg-red-500/10 rounded-xl text-slate-400 hover:text-red-500 transition-all">
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    </div>
                                </motion.div>
                            );
                        })
                    )}

                    {/* New Rule Modal */}
                    <AnimatePresence>
                        {showNewRule && (
                            <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowNewRule(false)}>
                                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }}
                                    onClick={e => e.stopPropagation()}
                                    className="bg-surface rounded-2xl w-full max-w-md border border-border shadow-2xl">
                                    <div className="p-5 border-b border-border flex items-center justify-between">
                                        <h2 className="text-lg font-bold text-foreground">Yeni Fiyat Kuralı</h2>
                                        <button onClick={() => setShowNewRule(false)} className="p-2 hover:bg-background rounded-xl"><X size={18} className="text-slate-400" /></button>
                                    </div>
                                    <div className="p-5 space-y-4">
                                        <div>
                                            <label className="text-xs font-bold text-slate-500 mb-1 block">Kural Adı</label>
                                            <input className="w-full px-3 py-2.5 bg-background border border-border rounded-xl text-sm text-foreground focus:border-emerald-500 focus:outline-none" placeholder="Örn: Minimum Marj Koruması" />
                                        </div>
                                        <div>
                                            <label className="text-xs font-bold text-slate-500 mb-1 block">Kural Türü</label>
                                            <select className="w-full px-3 py-2.5 bg-background border border-border rounded-xl text-sm text-foreground focus:border-emerald-500 focus:outline-none">
                                                {Object.entries(RULE_TYPE_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="text-xs font-bold text-slate-500 mb-1 block">Platform</label>
                                            <select className="w-full px-3 py-2.5 bg-background border border-border rounded-xl text-sm text-foreground focus:border-emerald-500 focus:outline-none">
                                                {['Tümü', 'Trendyol', 'Hepsiburada', 'Amazon', 'N11'].map(p => <option key={p}>{p}</option>)}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="text-xs font-bold text-slate-500 mb-1 block">Eşik Değeri (%)</label>
                                            <input type="number" className="w-full px-3 py-2.5 bg-background border border-border rounded-xl text-sm text-foreground focus:border-emerald-500 focus:outline-none" placeholder="15" min="0" max="100" />
                                        </div>
                                        <div>
                                            <label className="text-xs font-bold text-slate-500 mb-1 block">Açıklama</label>
                                            <textarea className="w-full px-3 py-2.5 bg-background border border-border rounded-xl text-sm text-foreground focus:border-emerald-500 focus:outline-none resize-none" rows={2} placeholder="Bu kural ne yapar?" />
                                        </div>
                                        <button className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold transition-all text-sm">Kaydet ve Etkinleştir</button>
                                    </div>
                                </motion.div>
                            </div>
                        )}
                    </AnimatePresence>
                </div>
            )}

            {/* HISTORY */}
            {tab === 'history' && (
                <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                    <div className="p-4 border-b border-border flex items-center justify-between">
                        <h3 className="font-bold text-foreground">Fiyat Değişiklikleri</h3>
                        <button onClick={loadHistory} className="text-xs font-bold text-slate-400 hover:text-foreground flex items-center gap-1 transition-all">
                            <RefreshCw size={12} className={histLoading ? 'animate-spin' : ''} /> Yenile
                        </button>
                    </div>
                    {histLoading ? (
                        <div className="py-12 flex items-center justify-center gap-3 text-slate-500">
                            <Loader2 size={18} className="animate-spin" /><span className="text-sm">Yükleniyor...</span>
                        </div>
                    ) : history.length === 0 ? (
                        <div className="py-12 text-center text-slate-500">
                            <BarChart3 size={32} className="mx-auto mb-2 text-slate-300" />
                            <p className="text-sm">Henüz fiyat değişikliği yok</p>
                        </div>
                    ) : (
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="border-b border-border text-left">
                                    {['Tarih', 'Ürün', 'Platform', 'Eski Fiyat', 'Yeni Fiyat', 'Kaynak'].map(h => (
                                        <th key={h} className="p-4 text-xs font-bold text-slate-500">{h}</th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {history.map((row, i) => (
                                    <tr key={row.id || i} className="border-b border-border/50 hover:bg-background/50 transition-colors">
                                        <td className="p-4 text-slate-500 text-xs">{row.date}</td>
                                        <td className="p-4 text-foreground font-medium">{row.product}</td>
                                        <td className="p-4 text-slate-500 text-xs">{row.platform}</td>
                                        <td className="p-4 text-slate-400">₺{row.oldPrice}</td>
                                        <td className={`p-4 font-bold ${row.newPrice > row.oldPrice ? 'text-emerald-500' : 'text-red-500'}`}>₺{row.newPrice}</td>
                                        <td className="p-4 text-xs text-slate-500">{row.source}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Tag,
    TrendingUp,
    TrendingDown,
    AlertTriangle,
    CheckCircle2,
    RefreshCw,
    Download,
    Search,
    Filter,
    Edit3,
    Eye,
    Clock,
    Zap,
    Target,
    BarChart3,
    ArrowUpRight,
    ArrowDownRight,
    ChevronDown,
    Globe,
    Settings,
    Sparkles
} from 'lucide-react';
import { usePricingAnalysis, PricingItem } from '@/lib/hooks';

interface PricingRule {
    id: number;
    name: string;
    description: string;
    active: boolean;
    products: number;
}

interface PricingPlatformData {
    price: number;
    buyBox: boolean;
    competitors: number[];
}

interface PricingProduct extends Omit<Partial<PricingItem>, 'id'> {
    id: string | number;
    name: string;
    sku: string;
    cost: number;
    myPrice: number;
    margin: number;
    status: string;
    image: string;
    platforms: Record<string, PricingPlatformData>;
    lastUpdate: string;
}

export default function PricingPage() {
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedPlatform, setSelectedPlatform] = useState('all');
    const [editingProduct, setEditingProduct] = useState<number | null>(null);
    const [showRules, setShowRules] = useState(false);
    const { analysis: apiPricing, loading } = usePricingAnalysis();

    const activeProducts = (Array.isArray(apiPricing) && apiPricing.length > 0) ? apiPricing : [];
    const activePricingRules: PricingRule[] = [
        { id: 1, name: 'Buy Box Takibi', description: 'Rakip fiyatının %2 altına otomatik indir', active: true, products: 0 },
        { id: 2, name: 'Minimum Kar Marjı', description: 'Kar marjı %40\'un altına düşmesin', active: true, products: 0 },
        { id: 3, name: 'Dinamik Fiyatlama', description: 'Talebe göre fiyatı optimize et', active: false, products: 0 },
        { id: 4, name: 'Stok Bazlı Fiyat', description: 'Stok azaldıkça fiyatı artır', active: true, products: 0 }
    ];

    const filteredProducts = (activeProducts as PricingProduct[]).filter((p) =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.sku.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'optimal': return 'bg-green-500/20 text-green-400 border-green-500/30';
            case 'competitive': return 'bg-blue-500/20 text-blue-400 border-blue-500/30';
            case 'high': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30';
            case 'undercut': return 'bg-red-500/20 text-red-400 border-red-500/30';
            default: return 'bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
        }
    };

    const getStatusText = (status: string) => {
        switch (status) {
            case 'optimal': return 'Optimal';
            case 'competitive': return 'Rekabetçi';
            case 'high': return 'Yüksek';
            case 'undercut': return 'Alt Fiyatlı Rakip';
            default: return 'Bilinmiyor';
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="flex flex-col items-center gap-4">
                    <RefreshCw className="w-8 h-8 text-emerald-500 animate-spin" />
                    <p className="text-slate-500">Fiyat verileri yükleniyor...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="mb-8">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                            <Tag className="w-8 h-8 text-emerald-500" />
