                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </motion.div>
            )}

            {/* Search and Filters */}
            <div className="flex items-center gap-4 mb-6">
                <div className="flex-1 relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
                    <input
                        type="text"
                        placeholder="Ürün veya SKU ara..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-background rounded-xl text-foreground placeholder-slate-500 border border-border focus:border-emerald-500 focus:outline-none"
                    />
                </div>
                <select
                    value={selectedPlatform}
                    onChange={(e) => setSelectedPlatform(e.target.value)}
                    className="px-4 py-2 bg-background rounded-xl text-foreground border border-border focus:border-emerald-500 focus:outline-none"
                >
                    <option value="all">Tüm Platformlar</option>
                    <option value="trendyol">Trendyol</option>
                    <option value="hepsiburada">Hepsiburada</option>
                    <option value="amazon">Amazon</option>
                    <option value="n11">N11</option>
                </select>
                <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-slate-600 dark:text-slate-300 hover:text-foreground transition-colors">
                    <RefreshCw className="w-4 h-4" />
                    Fiyat Tara
                </button>
            </div>

            {/* Products Grid */}
            <div className="space-y-4">
                {filteredProducts.map((product, index: number) => (
                    <motion.div
                        key={product.id}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: index * 0.05 }}
                        className="bg-surface rounded-2xl border border-border overflow-hidden"
                    >
                        <div className="p-4">
                            <div className="flex items-start justify-between">
                                <div className="flex items-start gap-4">
                                    <div className="text-4xl">{product.image}</div>
                                    <div>
                                        <h3 className="text-lg font-bold text-foreground">{product.name}</h3>
                                        <p className="text-sm text-slate-500 font-mono">{product.sku}</p>
                                        <div className="flex items-center gap-4 mt-2">
                                            <div className="text-sm">
                                                <span className="text-slate-500">Maliyet:</span>
                                                <span className="text-slate-600 dark:text-slate-300 ml-1">₺{product.cost}</span>
                                            </div>
                                            <div className="text-sm">
                                                <span className="text-slate-500">Benim Fiyatım:</span>
                                                <span className="text-emerald-400 font-bold ml-1">₺{product.myPrice}</span>
                                            </div>
                                            <div className="text-sm">
                                                <span className="text-slate-500">Marj:</span>
                                                <span className="text-purple-400 ml-1">%{product.margin}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <span className={`px-3 py-1 rounded-full text-xs font-medium border ${getStatusColor(product.status)}`}>
                                        {getStatusText(product.status)}
                                    </span>
                                    <button className="p-2 text-slate-500 hover:text-foreground hover:bg-background rounded-lg transition-colors">
                                        <Edit3 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>

                            {/* Platform Prices */}
                            <div className="mt-4 grid grid-cols-1 md:grid-cols-3 gap-4">
                                {Object.entries(product.platforms).map(([platform, data]) => (
                                    <div
                                        key={platform}
                                        className={`p-3 rounded-lg ${data.buyBox ? 'bg-emerald-900/20 border border-emerald-500/30' : 'bg-background rounded-xl border border-border'}`}
                                    >
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="text-sm font-medium text-foreground capitalize">{platform}</span>
                                            {data.buyBox && (
                                                <span className="px-2 py-0.5 bg-emerald-500/30 text-emerald-400 text-xs rounded-full">
                                                    Buy Box ✓
                                                </span>
                                            )}
                                        </div>
                                        <div className="text-lg font-bold text-foreground">₺{data.price}</div>
                                        <div className="mt-2">
                                            <span className="text-xs text-slate-500">Rakip fiyatları:</span>
                                            <div className="flex items-center gap-2 mt-1 flex-wrap">
                                                {data.competitors.map((price: number, i: number) => (
                                                    <span
                                                        key={i}
                                                        className={`text-xs px-2 py-0.5 rounded ${price < data.price
                                                            ? 'bg-red-500/20 text-red-600 dark:text-red-400'
                                                            : 'bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400'
                                                            }`}
                                                    >
                                                        ₺{price}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="mt-3 flex items-center justify-between text-xs text-slate-500">
                                <div className="flex items-center gap-1">
                                    <Clock className="w-3 h-3" />
                                    Son güncelleme: {product.lastUpdate}
                                </div>
                                <div className="flex items-center gap-3">
                                    <button className="text-emerald-400 hover:text-emerald-300 flex items-center gap-1">
                                        <Zap className="w-3 h-3" />
                                        Otomatik Fiyatla
                                    </button>
                                    <button className="text-blue-400 hover:text-blue-300 flex items-center gap-1">
                                        <Eye className="w-3 h-3" />
                                        Detay
                                    </button>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                ))}
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Boxes, Plus, Search, X, ChevronDown, ChevronUp,
    Barcode, ArrowRight, AlertTriangle, CheckCircle, Edit3, Trash2, Loader2, RefreshCw
} from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface SubBarcode {
    id: string; barcode: string; channel: string; note: string;
}
interface ProductGroup {
    id: string; name: string; primaryBarcode: string; brand: string;
    category: string; totalStock: number; subBarcodes: SubBarcode[];
    channels: string[];
}

const channelColors: Record<string, string> = {
    TRENDYOL: 'bg-orange-500/10 text-orange-400 border-orange-500/20',
    HEPSIBURADA: 'bg-red-500/10 text-red-400 border-red-500/20',
    AMAZON: 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20',
    N11: 'bg-purple-500/10 text-purple-400 border-purple-500/20',
    CICEKSEPETI: 'bg-pink-500/10 text-pink-400 border-pink-500/20',
    trendyol: 'bg-orange-500/10 text-orange-400 border-orange-500/20',
    hepsiburada: 'bg-red-500/10 text-red-400 border-red-500/20',
    amazon: 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20',
    n11: 'bg-purple-500/10 text-purple-400 border-purple-500/20',
};
const channelName = (ch: string) =>
    ({ TRENDYOL: 'Trendyol', HEPSIBURADA: 'Hepsiburada', AMAZON: 'Amazon', N11: 'N11', CICEKSEPETI: 'Çiçeksepeti' }[ch.toUpperCase()] || ch);

export default function ProductGroupsPage() {
    const [groups, setGroups] = useState<ProductGroup[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [search, setSearch] = useState('');
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [showAddModal, setShowAddModal] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [newBarcode, setNewBarcode] = useState('');
    const [creating, setCreating] = useState(false);

    useEffect(() => { loadGroups(); }, []);

    const loadGroups = async () => {
        setLoading(true);
        setError(null);
        try {
            const result = await apiClient.request<ProductGroup[]>('/product-groups');
            setGroups(result || []);
        } catch (err) {
            setError('Ürün grupları yüklenemedi.');
            setGroups([]);
        } finally {
            setLoading(false);
        }
    };

    const createGroup = async () => {
        if (!newGroupName || !newBarcode) return;
        setCreating(true);
        try {
            await apiClient.request('/product-groups', {
                method: 'POST',
                body: JSON.stringify({ name: newGroupName, primaryBarcode: newBarcode }),
            });
            setNewGroupName('');
            setNewBarcode('');
            setShowAddModal(false);
            await loadGroups();
        } catch { /* ignore */ }
        setCreating(false);
    };

    const deleteGroup = async (id: string) => {
        try {
            await apiClient.request(`/product-groups/${id}`, { method: 'DELETE' });
            setGroups(prev => prev.filter(g => g.id !== id));
        } catch { /* ignore */ }
    };

    const filtered = groups.filter(g =>
        g.name.toLowerCase().includes(search.toLowerCase()) ||
        (g.primaryBarcode || '').includes(search) ||
        (g.brand || '').toLowerCase().includes(search.toLowerCase())
    );

    const totalBarcodes = groups.reduce((sum, g) => sum + (g.subBarcodes?.length || 0), 0);
    const totalStock = groups.reduce((sum, g) => sum + (g.totalStock || 0), 0);

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <div className="flex items-center gap-3 mb-1">
                        <div className="p-2.5 rounded-xl bg-violet-500/10 border border-violet-500/20">
                            <Boxes className="w-6 h-6 text-violet-500" />
                        </div>
                        <h1 className="text-3xl font-black text-foreground">Grup Ürün Yönetimi</h1>
                    </div>
                    <p className="text-slate-500 font-medium ml-14">Aynı ürünün farklı barkodlarını gruplandırın, ortak stok düşümü sağlayın</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={loadGroups}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <RefreshCw size={15} className={loading ? "animate-spin" : ""} />
                    </button>
                    <button onClick={() => setShowAddModal(true)}
                        className="flex items-center gap-2 px-5 py-2.5 bg-violet-600 text-white rounded-xl text-sm font-bold hover:bg-violet-500 transition-all shadow-lg shadow-violet-500/20">
                        <Plus size={16} /> Yeni Grup Oluştur
                    </button>
                </div>
            </div>

            {/* Info Banner */}
            <div className="bg-violet-500/5 border border-violet-500/20 rounded-2xl px-5 py-4 flex items-start gap-3">
                <AlertTriangle size={18} className="text-violet-400 flex-shrink-0 mt-0.5" />
                <div>
                    <div className="text-sm font-bold text-violet-300">Nasıl Çalışır?</div>
                    <div className="text-xs text-slate-500 mt-0.5">Aynı fiziksel ürün farklı platformlarda farklı barkodlarla listeleniyor olabilir. Bu grupları oluşturarak, herhangi bir kanaldan sipariş geldiğinde stok otomatik olarak tek bir havuzdan düşülür. Böylece aşım satış hataları önlenir.</div>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-3 gap-4">
                {[
                    { label: 'Ürün Grubu', value: groups.length, color: 'text-violet-500' },
                    { label: 'Toplam Barkod', value: totalBarcodes, color: 'text-blue-500' },
                    { label: 'Toplam Stok', value: totalStock, color: 'text-green-500' },
                ].map(s => (
                    <div key={s.label} className="bg-surface rounded-2xl border border-border p-5">
                        <div className="text-2xl font-black text-foreground">{s.value}</div>
                        <div className={`text-xs font-bold ${s.color} mt-0.5`}>{s.label}</div>
                    </div>
                ))}
            </div>

            {/* Search */}
            <div className="relative">
                <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Ürün adı, barkod veya marka ara..."
                    className="w-full pl-11 pr-4 py-3 bg-surface border border-border rounded-xl text-sm text-foreground placeholder-slate-600 focus:border-violet-500 outline-none transition-colors" />
            </div>

            {/* Loading & Error & Empty */}
            {loading && (
                <div className="bg-surface border border-border rounded-2xl py-20 flex items-center justify-center gap-3 text-slate-500">
                    <Loader2 size={20} className="animate-spin" />
                    <span className="text-sm font-medium">Ürün grupları yükleniyor...</span>
                </div>
            )}

            {!loading && error && (
                <div className="bg-red-500/10 border border-red-500/20 rounded-2xl px-5 py-4 flex items-center justify-between">
                    <span className="text-sm text-red-400">{error}</span>
                    <button onClick={loadGroups} className="text-xs font-bold text-red-400 hover:text-red-300">Tekrar Dene</button>
                </div>
            )}

            {/* Groups List */}
            {!loading && (
                <div className="space-y-4">
                    {filtered.map((group, idx) => (
                        <motion.div key={group.id} initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: idx * 0.06 }}
                            className="bg-surface border border-border rounded-2xl overflow-hidden">
                            {/* Group Header */}
                            <button onClick={() => setExpandedId(expandedId === group.id ? null : group.id)}
                                className="w-full flex items-center justify-between p-5 hover:bg-white/2 transition-colors">
                                <div className="flex items-center gap-4">
                                    <div className="p-3 rounded-xl bg-violet-500/10">
                                        <Boxes className="w-5 h-5 text-violet-500" />
                                    </div>
                                    <div className="text-left">
                                        <div className="font-bold text-foreground">{group.name}</div>
                                        <div className="flex items-center gap-3 mt-1">
                                            <span className="text-[10px] text-slate-500 font-mono">{group.primaryBarcode}</span>
                                            {group.brand && <span className="text-[10px] text-slate-600">{group.brand} · {group.category}</span>}
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <div className="flex gap-1.5">
                                        {(group.channels || []).slice(0, 4).map(ch => (
                                            <span key={ch} className={`text-[9px] font-bold px-2 py-0.5 rounded-full border ${channelColors[ch] || 'bg-slate-500/10 text-slate-400 border-slate-500/20'}`}>
                                                {channelName(ch)}
                                            </span>
                                        ))}
                                    </div>
                                    <div className="text-right mr-2">
                                        <div className="text-lg font-black text-foreground">{group.totalStock || 0}</div>
                                        <div className="text-[10px] text-slate-500">Stok</div>
                                    </div>
                                    <button onClick={e => { e.stopPropagation(); deleteGroup(group.id); }}
                                        className="p-1.5 rounded-lg hover:bg-red-500/10 text-slate-500 hover:text-red-400 transition-colors">
                                        <Trash2 size={14} />
                                    </button>
                                    {expandedId === group.id ? <ChevronUp size={18} className="text-slate-500" /> : <ChevronDown size={18} className="text-slate-500" />}
                                </div>
                            </button>

                            {/* Expanded: Barcodes */}
                            <AnimatePresence>
                                {expandedId === group.id && (
                                    <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.2 }}
                                        className="overflow-hidden">
                                        <div className="border-t border-border p-5 space-y-3">
                                            <div className="flex items-center justify-between mb-1">
                                                <h4 className="text-xs font-black text-slate-400 uppercase tracking-wider">Kanal Barkodları ({(group.subBarcodes || []).length})</h4>
                                                <button className="flex items-center gap-1 text-xs font-bold text-violet-400 hover:text-violet-300 transition-colors">
                                                    <Plus size={12} /> Barkod Ekle
                                                </button>
                                            </div>
                                            {(group.subBarcodes || []).map(sub => (
                                                <div key={sub.id} className="flex items-center gap-4 p-3 bg-background rounded-xl border border-border">
                                                    <Barcode size={14} className="text-slate-500 flex-shrink-0" />
                                                    <div className="font-mono text-sm text-foreground font-bold">{sub.barcode}</div>
                                                    <ArrowRight size={12} className="text-slate-600 flex-shrink-0" />
                                                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${channelColors[sub.channel] || 'bg-slate-500/10 text-slate-400 border-slate-500/20'}`}>
                                                        {channelName(sub.channel)}
                                                    </span>
                                                    <span className="text-xs text-slate-500 flex-1">{sub.note}</span>
                                                    <div className="flex items-center gap-1">
                                                        <button className="p-1.5 rounded-lg hover:bg-violet-500/10 text-slate-500 hover:text-violet-400 transition-colors">
                                                            <Edit3 size={12} />
                                                        </button>
                                                        <button className="p-1.5 rounded-lg hover:bg-red-500/10 text-slate-500 hover:text-red-400 transition-colors">
                                                            <Trash2 size={12} />
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                            {(group.subBarcodes || []).length === 0 && (
                                                <p className="text-sm text-slate-500 text-center py-4">Henüz alt barkod eklenmemiş.</p>
                                            )}

                                            {/* Shared Stock Info */}
                                            <div className="bg-green-500/5 border border-green-500/20 rounded-xl p-4 flex items-center gap-3 mt-2">
                                                <CheckCircle size={16} className="text-green-500 flex-shrink-0" />
                                                <div className="text-xs text-green-300">
                                                    <span className="font-bold">Ortak stok aktif:</span> Herhangi bir kanaldan sipariş geldiğinde, stok ortak havuzdan ({group.totalStock || 0} adet) otomatik düşülür.
                                                </div>
                                            </div>
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    ))}

                    {/* Empty state */}
                    {filtered.length === 0 && !loading && !error && (
                        <div className="bg-surface border border-dashed border-border rounded-2xl py-16 flex flex-col items-center justify-center gap-3 text-slate-500">
                            <Boxes size={40} className="text-slate-300" />
                            <div className="text-center">
                                <p className="font-bold text-foreground">Henüz ürün grubu yok</p>
                                <p className="text-sm mt-1">İlk grubunuzu oluşturarak aynı ürünün farklı barkodlarını birleştirin.</p>
                            </div>
                        </div>
                    )}

                    {/* Add Group Card */}
                    <button onClick={() => setShowAddModal(true)}
                        className="w-full bg-surface border border-dashed border-border rounded-2xl p-6 flex items-center justify-center gap-3 text-slate-500 hover:text-foreground hover:border-violet-500/40 hover:bg-violet-500/5 transition-all">
                        <Plus size={18} /> <span className="text-sm font-bold">Yeni Ürün Grubu Oluştur</span>
                    </button>
                </div>
            )}

            {/* Add Group Modal */}
            <AnimatePresence>
                {showAddModal && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm"
                        onClick={() => setShowAddModal(false)}>
                        <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }}
                            onClick={e => e.stopPropagation()}
                            className="bg-surface border border-border rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl space-y-4">
                            <div className="flex items-center justify-between">
                                <h3 className="text-lg font-bold text-foreground">Yeni Ürün Grubu</h3>
                                <button onClick={() => setShowAddModal(false)} className="p-1.5 rounded-lg hover:bg-background text-slate-400"><X size={18} /></button>
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">Ürün Adı</label>
                                <input value={newGroupName} onChange={e => setNewGroupName(e.target.value)} placeholder="Örn: Samsung Galaxy S24"
                                    className="w-full px-4 py-3 bg-background border border-border rounded-xl text-sm text-foreground placeholder-slate-600 focus:border-violet-500 outline-none transition-colors" />
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">Ana Barkod</label>
                                <input value={newBarcode} onChange={e => setNewBarcode(e.target.value)} placeholder="8690000000000"
                                    className="w-full px-4 py-3 bg-background border border-border rounded-xl text-sm text-foreground placeholder-slate-600 focus:border-violet-500 outline-none transition-colors font-mono" />
                            </div>
                            <button onClick={createGroup} disabled={!newGroupName || !newBarcode || creating}
                                className="w-full py-3 bg-violet-600 text-white rounded-xl font-bold hover:bg-violet-500 transition-all disabled:opacity-40 flex items-center justify-center gap-2">
                                {creating ? <><Loader2 size={16} className="animate-spin" /> Oluşturuluyor...</> : 'Grup Oluştur'}
                            </button>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import {
    ChevronLeft,
    Sparkles,
    Image as ImageIcon,
    Type,
    TrendingUp,
    BarChart3,
    RefreshCcw,
    Check,
    Zap,
    Maximize2,
    Palette,
    ArrowRight,
    Globe
} from 'lucide-react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';

export default function ProductDetail() {
    const params = useParams<{ id: string }>();
    const productId = params?.id ?? '';
    const [activeTab, setActiveTab] = useState('details');
    const [isAiProcessing, setIsAiProcessing] = useState(false);
    const [product, setProduct] = useState({
        id: productId,
        name: '',
        sku: '',
        price: 0,
        stock: 0,
        category: '',
        description: '',
        platforms: [] as string[],
        seoScore: 0,
        image: '',
    });
    const [hasLoaded, setHasLoaded] = useState(false);

    useEffect(() => {
        const loadProduct = async () => {
            if (!productId) {
                setHasLoaded(true);
                return;
            }

            const candidates = [`/api/products/${productId}`, `/api/product/${productId}`];

            for (const url of candidates) {
                try {
                    const res = await fetch(url, { cache: 'no-store' });
                    if (!res.ok) continue;
                    const payload = await res.json();
                    const data = payload?.data ?? payload ?? {};

                    setProduct({
                        id: String(data.id ?? productId),
                        name: String(data.name ?? ''),
                        sku: String(data.sku ?? ''),
                        price: Number(data.price ?? 0),
                        stock: Number(data.stock ?? 0),
                        category: String(data.category ?? ''),
                        description: String(data.description ?? ''),
                        platforms: Array.isArray(data.platforms) ? data.platforms.map(String) : [],
                        seoScore: Number(data.seoScore ?? 0),
                        image: String(data.image ?? ''),
                    });
                    setHasLoaded(true);
                    return;
                } catch {
                    continue;
                }
            }

            setHasLoaded(true);
        };

        void loadProduct();
    }, [productId]);

    const handleAiSEO = async () => {
        setIsAiProcessing(true);
        try {
            await fetch('/api/ai/copilot/quick-action', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-tenant-id': 'default' },
                body: JSON.stringify({
                    action: 'optimize_seo',
                    context: { page: `/dashboard/products/${productId}`, productId },
                }),
            });
        } finally {
            setIsAiProcessing(false);
        }
    };

    const hasProductData = Boolean(product.name || product.sku || product.description || product.image);

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-20">
            {/* Header */}
            <div className="flex items-center justify-between">
                <Link href="/dashboard" className="flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-primary transition-colors">
                    <ChevronLeft size={16} /> Ürün Listesine Dön
                </Link>
                <div className="flex items-center gap-3">
                    <button className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-white/5 rounded-xl text-xs font-bold transition-all">
                        <RefreshCcw size={14} /> Senkronize Et
                    </button>
                    <button className="flex items-center gap-2 px-6 py-2 bg-primary text-white rounded-xl text-xs font-bold shadow-lg shadow-primary/20 hover:scale-105 transition-all">
                        Kaydet
                    </button>
                </div>
            </div>

            {/* Main Content Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                {/* Visual Section */}
                <div className="lg:col-span-1 space-y-6">
                    <div className="bg-surface rounded-3xl border border-border p-4 relative group overflow-hidden">
                        <div className="aspect-square rounded-2xl overflow-hidden bg-background relative">
                            {product.image ? (
                                <Image src={product.image} alt={product.name || 'Urun'} fill className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-slate-500 text-xs font-bold">Gorsel verisi bulunamadi</div>
                            )}
                        </div>
                        <div className="absolute top-8 right-8 flex flex-col gap-2">
                            <button className="p-2.5 rounded-xl bg-white/90 dark:bg-black/90 backdrop-blur-md shadow-xl text-blue-500 hover:scale-110 transition-all border border-blue-500/20">
                                <Maximize2 size={18} />
                            </button>
                            <button className="p-2.5 rounded-xl bg-white/90 dark:bg-black/90 backdrop-blur-md shadow-xl text-purple-500 hover:scale-110 transition-all border border-purple-500/20">
                                <Palette size={18} />
                            </button>
                        </div>

                        {/* Background Removal Panel */}
                        <div className="mt-4 p-4 rounded-2xl bg-slate-50 dark:bg-white/[0.02] border border-border flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <Sparkles size={16} className="text-yellow-500" />
                                <span className="text-xs font-bold lowercase tracking-tight">AI Arka Plan Silici</span>
                            </div>
                            <button className="px-3 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-colors">Sihri Başlat</button>
                        </div>
                    </div>

                    {/* Sync Status */}
                    <div className="bg-surface rounded-2xl border border-border p-6 space-y-4">
                        <h4 className="text-sm font-black uppercase tracking-widest text-slate-500">Pazaryeri Durumu</h4>
                        <div className="space-y-3">
                            {product.platforms.map(p => (
                                <div key={p} className="flex items-center justify-between p-3 rounded-xl bg-background/50 border border-border">
                                    <div className="flex items-center gap-2">
                                        <div className="w-2 h-2 rounded-full bg-green-500" />
                                        <span className="text-xs font-bold">{p}</span>
                                    </div>
                                    <span className="text-[10px] text-slate-500 font-bold tracking-widest uppercase">AKTİF</span>
                                </div>
                            ))}
                            {product.platforms.length === 0 && (
                                <div className="text-xs text-slate-500">Platform verisi bulunamadi.</div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Info Section */}
                <div className="lg:col-span-2 space-y-8">
                    {/* Tabs */}
                    <div className="flex border-b border-border gap-8">
                        {['details', 'ai-tools', 'analytics'].map(tab => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab)}
                                className={`pb-4 text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === tab ? 'text-primary' : 'text-slate-400'}`}
                            >
                                {tab === 'details' ? 'Detaylar' : tab === 'ai-tools' ? 'AI Araçları' : 'Analitik'}
                                {activeTab === tab && <motion.div layoutId="activeTab" className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary" />}
                            </button>
                        ))}
                    </div>

                    <AnimatePresence mode="wait">
                        {activeTab === 'details' && (
                            <motion.div
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="space-y-6"
                            >
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Ürün Adı</label>
                                    <input value={product.name} readOnly className="w-full bg-surface border border-border rounded-xl p-4 text-xl font-black outline-none focus:border-primary transition-all shadow-sm" />
                                </div>

                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Fiyat</label>
                                        <div className="relative">
                                            <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-slate-400 uppercase">₺</span>
                                            <input value={product.price} readOnly className="w-full bg-surface border border-border rounded-xl py-4 pl-10 pr-4 font-black outline-none focus:border-primary transition-all" />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Stok</label>
                                        <input value={product.stock} readOnly className="w-full bg-surface border border-border rounded-xl p-4 font-black outline-none focus:border-primary transition-all" />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Açıklama</label>
                                    <textarea rows={5} value={product.description} readOnly className="w-full bg-surface border border-border rounded-2xl p-4 text-sm leading-relaxed outline-none focus:border-primary transition-all custom-scrollbar" />
                                </div>
                                {hasLoaded && !hasProductData && (
                                    <div className="text-xs text-slate-500">Urun verisi bulunamadi.</div>
                                )}
                            </motion.div>
                        )}

                        {activeTab === 'ai-tools' && (
                            <motion.div
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="grid grid-cols-1 md:grid-cols-2 gap-6"
                            >
                                <div className="bg-gradient-to-br from-indigo-500 to-purple-700 p-8 rounded-[32px] text-white shadow-2xl relative overflow-hidden group">
                                    <div className="relative z-10">
                                        <div className="flex items-center gap-2 mb-6">
                                            <Sparkles size={20} className="text-yellow-300" />
                                            <span className="text-xs font-black uppercase tracking-widest opacity-80">AI SEO GENERATOR</span>
                                        </div>
                                        <h3 className="text-2xl font-black mb-4 leading-tight italic">Ürününüze Turbo Modu Açın.</h3>
                                        <p className="text-sm text-indigo-100/80 mb-8 leading-relaxed">Gemini AI ürün detaylarınızı analiz eder ve en yüksek dönüşüm getirecek başlıkları/anahtar kelimeleri anında üretir.</p>
                                        <button
                                            onClick={handleAiSEO}
                                            disabled={isAiProcessing}
                                            className="w-full py-4 bg-white text-indigo-600 rounded-2xl text-xs font-black tracking-widest uppercase hover:scale-105 transition-all shadow-xl flex items-center justify-center gap-2"
                                        >
                                            {isAiProcessing ? (
                                                <> <RefreshCcw size={16} className="animate-spin" /> ANALİZ EDİLİYOR... </>
                                            ) : (
                                                <> <Zap size={16} className="fill-indigo-600" /> SİHİRLİ DOKUNUŞ </>
                                            )}
                                        </button>
                                    </div>
                                    {/* Abstract icons pattern */}
                                    <div className="absolute -bottom-10 -right-10 opacity-10 group-hover:scale-110 transition-transform duration-1000">
                                        <Bot size={200} />
                                    </div>
                                </div>

                                <div className="bg-surface border border-border p-8 rounded-[32px] space-y-6">
                                    <div className="flex items-center justify-between">
                                        <span className="text-xs font-black text-slate-500 uppercase tracking-widest">SEO SKORUNUZ</span>
                                        <div className="w-12 h-12 rounded-full border-4 border-blue-500/20 flex items-center justify-center text-sm font-black text-blue-500">
                                            {product.seoScore}
                                        </div>
                                    </div>
                                    <div className="space-y-4">
                                        {[
                                            { l: "Başlık Optimizasyonu", v: true },
                                            { l: "Anahtar Kelime Yoğunluğu", v: true },
                                            { l: "Görsel Alt Etiketleri", v: false },
                                            { l: "Platform Uyumluluğu", v: true }
                                        ].map((check, i) => (
                                            <div key={i} className="flex items-center justify-between">
                                                <span className="text-xs font-medium text-slate-600 dark:text-slate-400">{check.l}</span>
                                                {check.v ? <Check size={16} className="text-green-500" /> : <RefreshCcw size={14} className="text-orange-400" />}
                                            </div>
                                        ))}
                                    </div>
                                    <div className="pt-4 border-t border-border">
                                        <p className="text-[10px] text-slate-500 leading-relaxed italic">"Ürün açıklamasına 3 adet 'Kablosuz' anahtar kelimesi ekleyerek skoru %95'e çıkarabilirsiniz."</p>
                                    </div>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>
        </div>
    );
}

const Bot = ({ size }: { size: number }) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 8V4H8" /><rect width="16" height="12" x="4" y="8" rx="2" /><path d="M2 14h2" /><path d="M20 14h2" /><path d="M15 13v2" /><path d="M9 13v2" />
    </svg>
);

