"use client";

import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import {
    TrendingUp, TrendingDown, DollarSign, Percent, Package,
    BarChart3, ArrowUpRight, ArrowDownRight, Filter, Download,
    PieChart, Calculator, AlertTriangle, Star, ChevronDown
} from 'lucide-react';
import { ExportButton } from '@/lib/export-utils';

import { useProfitability } from '@/lib/hooks';

type SortField = 'name' | 'revenue' | 'profit' | 'margin' | 'quantity' | 'roi';
type SortDir = 'desc' | 'asc';

interface ProfitabilityProduct {
    id: string;
    sku: string;
    name: string;
    platform: string;
    salePrice: number;
    costPrice: number;
    quantity: number;
    returns: number;
    commission: number;
    shipping: number;
    tax: number;
    // Enriched fields
    netQuantity: number;
    revenue: number;
    totalCost: number;
    totalCommission: number;
    totalShipping: number;
    totalTax: number;
    returnCost: number;
    totalExpenses: number;
    profit: number;
    margin: number;
    roi: number;
}

export default function ProfitabilityPage() {
    const { data: profitabilityDataFromApi, loading } = useProfitability();
    const [period, setPeriod] = useState('30d');
    const [sortField, setSortField] = useState<SortField>('profit');
    const [sortDir, setSortDir] = useState<SortDir>('desc');
    const [platformFilter, setPlatformFilter] = useState('all');
    const [showLossOnly, setShowLossOnly] = useState(false);

    const profitabilityData = profitabilityDataFromApi?.products || [];

    const enrichedProducts = useMemo(() => {
        if (!profitabilityData || !Array.isArray(profitabilityData)) return [];
        return profitabilityData.map((p: any) => {
            const netQuantity = p.quantity - p.returns;
            const revenue = p.salePrice * netQuantity;
            const totalCost = p.costPrice * p.quantity; // cost for all, including returns
            const totalCommission = p.commission * netQuantity;
            const totalShipping = p.shipping * netQuantity;
            const totalTax = p.tax * netQuantity;
            const returnCost = p.returns * (p.shipping + p.costPrice * 0.1); // return logistics
            const totalExpenses = totalCost + totalCommission + totalShipping + totalTax + returnCost;
            const profit = revenue - totalExpenses;
            const margin = revenue > 0 ? (profit / revenue) * 100 : 0;
            const roi = totalCost > 0 ? (profit / totalCost) * 100 : 0;

            return {
                ...p,
                netQuantity,
                revenue,
                totalCost,
                totalCommission,
                totalShipping,
                totalTax,
                returnCost,
                totalExpenses,
                profit,
                margin,
                roi,
            };
        });
    }, []);

    const filtered = useMemo(() => {
        let data = enrichedProducts;
        if (platformFilter !== 'all') data = data.filter(p => p.platform === platformFilter);
        if (showLossOnly) data = data.filter(p => p.profit < 0);
        data.sort((a, b) => {
            const aVal = a[sortField] ?? 0;
            const bVal = b[sortField] ?? 0;
            return sortDir === 'desc' ? (bVal > aVal ? 1 : -1) : (aVal > bVal ? 1 : -1);
        });
        return data;
    }, [enrichedProducts, platformFilter, showLossOnly, sortField, sortDir]);

    const totals = useMemo(() => {
        return enrichedProducts.reduce((acc, p) => ({
            revenue: acc.revenue + p.revenue,
            cost: acc.cost + p.totalCost,
            commission: acc.commission + p.totalCommission,
            shipping: acc.shipping + p.totalShipping,
            tax: acc.tax + p.totalTax,
            profit: acc.profit + p.profit,
            quantity: acc.quantity + p.netQuantity,
            returns: acc.returns + p.returns,
        }), { revenue: 0, cost: 0, commission: 0, shipping: 0, tax: 0, profit: 0, quantity: 0, returns: 0 });
    }, [enrichedProducts]);

    const overallMargin = totals.revenue > 0 ? (totals.profit / totals.revenue) * 100 : 0;

    const platformBreakdown = useMemo(() => {
        const platforms: Record<string, { revenue: number; profit: number; count: number }> = {};
        enrichedProducts.forEach(p => {
            if (!platforms[p.platform]) platforms[p.platform] = { revenue: 0, profit: 0, count: 0 };
            platforms[p.platform].revenue += p.revenue;
            platforms[p.platform].profit += p.profit;
            platforms[p.platform].count += p.netQuantity;
        });
        return Object.entries(platforms).map(([name, data]) => ({
            name,
            ...data,
            margin: data.revenue > 0 ? (data.profit / data.revenue) * 100 : 0,
        })).sort((a, b) => b.profit - a.profit);
    }, [enrichedProducts]);

    const toggleSort = (field: SortField) => {
        if (sortField === field) setSortDir(d => d === 'desc' ? 'asc' : 'desc');
        else { setSortField(field); setSortDir('desc'); }
    };

    const fmt = (n: number) => n.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    const lossProducts = enrichedProducts.filter(p => p.margin < 0).length;
    const lowMarginProducts = enrichedProducts.filter(p => p.margin >= 0 && p.margin < 10).length;

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <Calculator className="w-8 h-8 text-emerald-500" />
                        Kârlılık Analizi
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-1">
                        Ürün bazlı gelir, gider ve kâr/zarar analizi
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="flex bg-background rounded-xl border border-border p-1">
                        {['7d', '30d', '90d', '1y'].map(p => (
                            <button
                                key={p}
                                onClick={() => setPeriod(p)}
                                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${period === p ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:text-foreground'}`}
                            >
                                {p === '7d' ? '7 Gün' : p === '30d' ? '30 Gün' : p === '90d' ? '90 Gün' : '1 Yıl'}
                            </button>
                        ))}
                    </div>
                    <ExportButton
                        data={filtered.map((p: any) => ({
                            'SKU': p.sku,
                            'Ürün': p.name,
                            'Platform': p.platform,
                            'Satış Fiyatı': p.salePrice,
                            'Maliyet': p.costPrice,
                            'Adet': p.netQuantity,
                            'Ciro': fmt(p.revenue),
                            'Toplam Gider': fmt(p.totalExpenses),
                            'Net Kâr': fmt(p.profit),
                            'Marj (%)': p.margin.toFixed(1),
                            'ROI (%)': p.roi.toFixed(1),
                        }))}
                        filename="karlilik-analizi"
                        title="Kârlılık Analizi Raporu"
                    />
                </div>
            </div>

            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
                {[
                    { label: 'Toplam Ciro', value: `₺${fmt(totals.revenue)}`, icon: DollarSign, color: 'blue', sub: `${totals.quantity} adet satış` },
                    { label: 'Net Kâr', value: `₺${fmt(totals.profit)}`, icon: totals.profit >= 0 ? TrendingUp : TrendingDown, color: totals.profit >= 0 ? 'emerald' : 'red', sub: `Marj: %${overallMargin.toFixed(1)}` },
                    { label: 'Toplam Gider', value: `₺${fmt(totals.cost + totals.commission + totals.shipping + totals.tax)}`, icon: ArrowDownRight, color: 'orange', sub: `Komisyon: ₺${fmt(totals.commission)}` },
                    { label: 'İade Maliyeti', value: `${totals.returns} adet`, icon: Package, color: 'red', sub: `%${((totals.returns / (totals.quantity + totals.returns)) * 100).toFixed(1)} iade oranı` },
                    { label: 'Zarar Eden Ürün', value: `${lossProducts}`, icon: AlertTriangle, color: 'red', sub: `${lowMarginProducts} düşük marjlı` },
                ].map((card, i) => (
                    <motion.div
                        key={card.label}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: i * 0.08 }}
                        className="bg-surface rounded-2xl p-5 border border-border"
                    >
                        <div className="flex items-center gap-3">
                            <div className={`p-2 bg-${card.color}-500/20 rounded-xl`}>
                                <card.icon className={`w-5 h-5 text-${card.color}-500`} />
                            </div>
                            <div>
                                <div className="text-sm text-slate-500">{card.label}</div>
                                <div className="text-xl font-black text-foreground">{card.value}</div>
                                <div className="text-xs text-slate-400 mt-0.5">{card.sub}</div>
                            </div>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Platform Breakdown */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="lg:col-span-1 bg-surface rounded-2xl p-6 border border-border"
                >
                    <h3 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
                        <PieChart className="w-5 h-5 text-indigo-400" />
                        Platform Kârlılığı
                    </h3>
                    <div className="space-y-4">
                        {platformBreakdown.map((pl, i) => {
                            const maxRevenue = Math.max(...platformBreakdown.map(p => p.revenue));
                            const width = maxRevenue > 0 ? (pl.revenue / maxRevenue) * 100 : 0;
                            return (
                                <div key={pl.name}>
                                    <div className="flex items-center justify-between mb-1">
                                        <span className="text-sm font-medium text-foreground">{pl.name}</span>
                                        <span className={`text-sm font-bold ${pl.margin >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
                                            %{pl.margin.toFixed(1)}
                                        </span>
                                    </div>
                                    <div className="w-full bg-background rounded-full h-2">
                                        <div
                                            className={`h-2 rounded-full transition-all ${pl.margin >= 15 ? 'bg-emerald-500' : pl.margin >= 5 ? 'bg-yellow-500' : 'bg-red-500'}`}
                                            style={{ width: `${width}%` }}
                                        />
                                    </div>
                                    <div className="flex items-center justify-between mt-1 text-xs text-slate-500">
                                        <span>Ciro: ₺{fmt(pl.revenue)}</span>
                                        <span>Kâr: ₺{fmt(pl.profit)}</span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </motion.div>

                {/* Cost Breakdown */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.4 }}
                    className="lg:col-span-2 bg-surface rounded-2xl p-6 border border-border"
                >
                    <h3 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
                        <BarChart3 className="w-5 h-5 text-blue-400" />
                        Gider Dağılımı
                    </h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                        {[
                            { label: 'Ürün Maliyeti', value: totals.cost, color: 'bg-blue-500', pct: totals.cost / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100 },
                            { label: 'Komisyonlar', value: totals.commission, color: 'bg-orange-500', pct: totals.commission / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100 },
                            { label: 'Kargo', value: totals.shipping, color: 'bg-purple-500', pct: totals.shipping / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100 },
                            { label: 'Vergi', value: totals.tax, color: 'bg-red-500', pct: totals.tax / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100 },
                        ].map(item => (
                            <div key={item.label} className="p-4 bg-background rounded-xl border border-border">
                                <div className="flex items-center gap-2 mb-2">
                                    <div className={`w-3 h-3 rounded-full ${item.color}`} />
                                    <span className="text-xs text-slate-500">{item.label}</span>
                                </div>
                                <div className="text-lg font-bold text-foreground">₺{fmt(item.value)}</div>
                                <div className="text-xs text-slate-400">%{item.pct.toFixed(1)}</div>
                            </div>
                        ))}
                    </div>

                    {/* Visual bar */}
                    <div className="flex rounded-full h-4 overflow-hidden">
                        <div className="bg-blue-500" style={{ width: `${totals.cost / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100}%` }} />
                        <div className="bg-orange-500" style={{ width: `${totals.commission / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100}%` }} />
                        <div className="bg-purple-500" style={{ width: `${totals.shipping / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100}%` }} />
                        <div className="bg-red-500" style={{ width: `${totals.tax / (totals.cost + totals.commission + totals.shipping + totals.tax) * 100}%` }} />
                    </div>
                </motion.div>
            </div>

            {/* Filters */}
            <div className="flex items-center gap-4 flex-wrap">
                <div className="flex items-center gap-2">
                    <Filter className="w-4 h-4 text-slate-400" />
                    <select
                        value={platformFilter}
                        onChange={(e) => setPlatformFilter(e.target.value)}
                        className="bg-surface border border-border rounded-xl px-3 py-2 text-sm text-foreground focus:border-emerald-500 focus:outline-none"
                    >
                        <option value="all">Tüm Platformlar</option>
                        <option value="Trendyol">Trendyol</option>
                        <option value="Amazon">Amazon</option>
                        <option value="Hepsiburada">Hepsiburada</option>
                        <option value="N11">N11</option>
                        <option value="Çiçeksepeti">Çiçeksepeti</option>
                    </select>
                </div>

                <label className="flex items-center gap-2 cursor-pointer">
                    <input
                        type="checkbox"
                        checked={showLossOnly}
                        onChange={(e) => setShowLossOnly(e.target.checked)}
                        className="w-4 h-4 rounded border-slate-600 text-red-500 focus:ring-red-500"
                    />
                    <span className="text-sm text-slate-500">Sadece zarar eden ürünler</span>
                </label>
            </div>

            {/* Products P&L Table */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.5 }}
                className="bg-surface rounded-2xl border border-border overflow-hidden"
            >
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-slate-100 dark:bg-slate-800/50">
                            <tr>
                                <th className="text-left p-4 text-slate-500 font-bold">Ürün</th>
                                <th className="text-center p-4 text-slate-500 font-bold">Platform</th>
                                <th
                                    className="text-right p-4 text-slate-500 font-bold cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort('quantity')}
                                >
                                    Adet {sortField === 'quantity' && (sortDir === 'desc' ? '↓' : '↑')}
                                </th>
                                <th
                                    className="text-right p-4 text-slate-500 font-bold cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort('revenue')}
                                >
                                    Ciro {sortField === 'revenue' && (sortDir === 'desc' ? '↓' : '↑')}
                                </th>
                                <th className="text-right p-4 text-slate-500 font-bold">Maliyet</th>
                                <th className="text-right p-4 text-slate-500 font-bold">Komisyon</th>
                                <th
                                    className="text-right p-4 text-slate-500 font-bold cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort('profit')}
                                >
                                    Net Kâr {sortField === 'profit' && (sortDir === 'desc' ? '↓' : '↑')}
                                </th>
                                <th
                                    className="text-right p-4 text-slate-500 font-bold cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort('margin')}
                                >
                                    Marj {sortField === 'margin' && (sortDir === 'desc' ? '↓' : '↑')}
                                </th>
                                <th
                                    className="text-right p-4 text-slate-500 font-bold cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort('roi')}
                                >
                                    ROI {sortField === 'roi' && (sortDir === 'desc' ? '↓' : '↑')}
                                </th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {filtered.map((product: any) => (
                                <tr key={product.id} className="hover:bg-background/50 transition-colors">
                                    <td className="p-4">
                                        <div className="font-medium text-foreground">{product.name}</div>
                                        <div className="text-xs text-slate-500 font-mono">{product.sku}</div>
                                    </td>
                                    <td className="p-4 text-center">
                                        <span className="px-2 py-1 bg-background rounded-lg text-xs text-slate-500 border border-border">
                                            {product.platform}
                                        </span>
                                    </td>
                                    <td className="p-4 text-right text-foreground">
                                        {product.netQuantity}
                                        {product.returns > 0 && (
                                            <span className="text-xs text-red-400 ml-1">(-{product.returns})</span>
                                        )}
                                    </td>
                                    <td className="p-4 text-right text-foreground font-medium">₺{fmt(product.revenue)}</td>
                                    <td className="p-4 text-right text-slate-400">₺{fmt(product.totalCost)}</td>
                                    <td className="p-4 text-right text-slate-400">₺{fmt(product.totalCommission)}</td>
                                    <td className={`p-4 text-right font-bold ${product.profit >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
                                        {product.profit >= 0 ? '+' : ''}₺{fmt(product.profit)}
                                    </td>
                                    <td className="p-4 text-right">
                                        <span className={`px-2 py-1 rounded-full text-xs font-bold ${product.margin >= 20
                                            ? 'bg-emerald-500/10 text-emerald-500'
                                            : product.margin >= 10
                                                ? 'bg-yellow-500/10 text-yellow-500'
                                                : product.margin >= 0
                                                    ? 'bg-orange-500/10 text-orange-500'
                                                    : 'bg-red-500/10 text-red-500'
                                            }`}>
                                            %{product.margin.toFixed(1)}
                                        </span>
                                    </td>
                                    <td className={`p-4 text-right font-medium ${product.roi >= 0 ? 'text-blue-400' : 'text-red-400'}`}>
                                        %{product.roi.toFixed(0)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                        <tfoot className="bg-slate-100 dark:bg-slate-800/50 font-bold">
                            <tr>
                                <td className="p-4 text-foreground" colSpan={2}>TOPLAM</td>
                                <td className="p-4 text-right text-foreground">{totals.quantity}</td>
                                <td className="p-4 text-right text-foreground">₺{fmt(totals.revenue)}</td>
                                <td className="p-4 text-right text-slate-400">₺{fmt(totals.cost)}</td>
                                <td className="p-4 text-right text-slate-400">₺{fmt(totals.commission)}</td>
                                <td className={`p-4 text-right ${totals.profit >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
                                    {totals.profit >= 0 ? '+' : ''}₺{fmt(totals.profit)}
                                </td>
                                <td className="p-4 text-right">
                                    <span className={`px-2 py-1 rounded-full text-xs font-bold ${overallMargin >= 10 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
                                        %{overallMargin.toFixed(1)}
                                    </span>
                                </td>
                                <td className="p-4 text-right text-blue-400">
                                    %{(totals.cost > 0 ? (totals.profit / totals.cost * 100) : 0).toFixed(0)}
                                </td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            </motion.div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
    BarChart3,
    TrendingUp,
    TrendingDown,
    Download,
    Calendar,
    Filter,
    FileSpreadsheet,
    FileText,
    PieChart,
    LineChart,
    ArrowUpRight,
    ArrowDownRight,
    RefreshCw,
    Mail,
    Clock,
    Target,
    DollarSign,
    Package,
    ShoppingCart,
    Users,
    Percent,
    Eye,
    LucideIcon
} from 'lucide-react';
import { useReports, Report, ScheduledReport as HookScheduledReport } from '@/lib/hooks';

interface FinancialData extends Partial<Report> {
    month: string;
    revenue: number;
    orders: number;
    profit: number;
}

interface ScheduledReport extends HookScheduledReport {
    active: boolean; // Field name difference fix if any
}

interface RecentReport extends Partial<Report> {
    id: string;
    name: string;
    date: string;
    size: string;
    format: string;
}

interface ReportType {
    id: string;
    name: string;
    icon: LucideIcon;
    description: string;
    color: string;
}

// Report type definitions
const reportTypes = [
    { id: 'sales', name: 'Satış Raporu', icon: ShoppingCart, description: 'Satış performansı ve trendler', color: 'emerald' },
    { id: 'revenue', name: 'Gelir Raporu', icon: DollarSign, description: 'Gelir analizi ve kar marjları', color: 'blue' },
    { id: 'products', name: 'Ürün Raporu', icon: Package, description: 'Ürün performansı ve stok analizi', color: 'purple' },
    { id: 'customers', name: 'Müşteri Raporu', icon: Users, description: 'Müşteri segmentasyonu ve davranışları', color: 'orange' },
    { id: 'platforms', name: 'Platform Raporu', icon: BarChart3, description: 'Platform bazlı karşılaştırmalı analiz', color: 'cyan' },
    { id: 'tax', name: 'Vergi Raporu', icon: FileText, description: 'KDV ve vergi hesaplamaları', color: 'red' }
];

export default function ReportsPage() {
    const [selectedPeriod, setSelectedPeriod] = useState('month');
    const [selectedReportType, setSelectedReportType] = useState<string | null>(null);
    const [showExportModal, setShowExportModal] = useState(false);
    const { fetchReports: getReports, fetchScheduled: getScheduled, loading } = useReports();
    const [apiReports, setApiReports] = useState<any[] | null>(null);
    const [apiScheduled, setApiScheduled] = useState<any[]>([]);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [reportsData, scheduledData] = await Promise.allSettled([
                    getReports(),
                    getScheduled()
                ]);
                if (reportsData.status === 'fulfilled' && reportsData.value) setApiReports(reportsData.value);
                if (scheduledData.status === 'fulfilled' && scheduledData.value) setApiScheduled(scheduledData.value);
            } catch (error) {
                console.error('Raporlar yüklenirken hata:', error);
            }
        };
        fetchData();
    }, []);

    const activeMonthlyData = (Array.isArray(apiReports) ? apiReports : []) as FinancialData[];
    const activeReportTypes = reportTypes;
    const activeScheduledReports = apiScheduled as ScheduledReport[];
    const activeRecentReports = (Array.isArray(apiReports) ? apiReports.slice(0, 4) : []) as RecentReport[];

    const totalRevenue = activeMonthlyData.reduce((sum: number, m: FinancialData) => sum + m.revenue, 0);
    const totalOrders = activeMonthlyData.reduce((sum: number, m: FinancialData) => sum + m.orders, 0);
    const totalProfit = activeMonthlyData.reduce((sum: number, m: FinancialData) => sum + m.profit, 0);
    const avgProfitMargin = ((totalProfit / totalRevenue) * 100).toFixed(1);

    const maxRevenue = Math.max(...activeMonthlyData.map((m: FinancialData) => m.revenue));

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="flex flex-col items-center gap-4">
                    <RefreshCw className="w-8 h-8 text-violet-500 animate-spin" />
                    <p className="text-slate-500">Raporlar yükleniyor...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="mb-8">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                            <BarChart3 className="w-8 h-8 text-violet-500" />
                            Finansal Raporlar
                        </h1>
                        <p className="text-slate-500 dark:text-slate-400 mt-1">
                            Detaylı analiz ve raporlar
                        </p>
                    </div>
                    <div className="flex items-center gap-3">
                        <motion.button
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-slate-600 dark:text-slate-300 hover:text-foreground transition-colors"
                        >
                            <Calendar className="w-4 h-4" />
                            Dönem Seç
                        </motion.button>
                        <motion.button
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => setShowExportModal(true)}
                            className="flex items-center gap-2 px-4 py-2 bg-violet-600 rounded-lg text-white hover:bg-violet-700 transition-colors"
                        >
                            <Download className="w-4 h-4" />
                            Rapor Oluştur
                        </motion.button>
                    </div>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-gradient-to-br from-emerald-500/10 to-emerald-600/5 dark:from-emerald-900/40 dark:to-emerald-800/20 rounded-2xl p-5 border border-emerald-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-emerald-500/20 rounded-xl">
                            <DollarSign className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Toplam Gelir (6 Ay)</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(totalRevenue / 1000).toFixed(0)}K</div>
                    <div className="flex items-center gap-1 mt-2 text-green-400 text-sm">
                        <ArrowUpRight className="w-4 h-4" />
                        <span>+18.5% önceki döneme göre</span>
                    </div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-gradient-to-br from-blue-500/10 to-blue-600/5 dark:from-blue-900/40 dark:to-blue-800/20 rounded-2xl p-5 border border-blue-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-blue-500/20 rounded-xl">
                            <ShoppingCart className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Toplam Sipariş</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">{totalOrders.toLocaleString('tr-TR')}</div>
                    <div className="flex items-center gap-1 mt-2 text-blue-400 text-sm">
                        <ArrowUpRight className="w-4 h-4" />
                        <span>+12.3% artış</span>
                    </div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-gradient-to-br from-purple-500/10 to-purple-600/5 dark:from-purple-900/40 dark:to-purple-800/20 rounded-2xl p-5 border border-purple-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-purple-500/20 rounded-xl">
                            <TrendingUp className="w-5 h-5 text-purple-600 dark:text-purple-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Toplam Kar</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(totalProfit / 1000).toFixed(0)}K</div>
                    <div className="flex items-center gap-1 mt-2 text-purple-400 text-sm">
                        <ArrowUpRight className="w-4 h-4" />
                        <span>+21.7% artış</span>
                    </div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-gradient-to-br from-orange-500/10 to-orange-600/5 dark:from-orange-900/40 dark:to-orange-800/20 rounded-2xl p-5 border border-orange-500/20"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-orange-500/20 rounded-xl">
                            <Percent className="w-5 h-5 text-orange-600 dark:text-orange-400" />
                        </div>
                        <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">Kar Marjı</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">%{avgProfitMargin}</div>
                    <div className="flex items-center gap-1 mt-2 text-orange-400 text-sm">
                        <Target className="w-4 h-4" />
                        <span>Hedef: %40</span>
                    </div>
                </motion.div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                {/* Revenue Chart */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="lg:col-span-2 bg-surface rounded-2xl p-6 border border-border"
                >
                    <div className="flex items-center justify-between mb-6">
                        <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                            <LineChart className="w-5 h-5 text-violet-500" />
                            Aylık Gelir Trendi
                        </h2>
                        <div className="flex items-center gap-2">
                            {['3m', '6m', '1y'].map((period) => (
                                <button
                                    key={period}
                                    onClick={() => setSelectedPeriod(period)}
                                    className={`px-3 py-1 rounded text-sm transition-colors ${selectedPeriod === period
                                        ? 'bg-violet-600 text-white'
                                        : 'text-slate-500 hover:text-foreground'
                                        }`}
                                >
                                    {period}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-4">
                        {activeMonthlyData.map((data: FinancialData, index: number) => (
                            <div key={data.month} className="flex items-center gap-4">
                                <div className="w-16 text-sm text-slate-600 dark:text-slate-400">{data.month}</div>
                                <div className="flex-1 relative">
                                    <div className="h-8 bg-background rounded-xl border border-border overflow-hidden">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${(data.revenue / maxRevenue) * 100}%` }}
                                            transition={{ delay: index * 0.1, duration: 0.5 }}
                                            className="h-full bg-gradient-to-r from-violet-600 to-violet-400 rounded-lg"
                                        />
                                    </div>
                                </div>
                                <div className="w-24 text-right">
                                    <div className="text-sm font-medium text-foreground">₺{(data.revenue / 1000).toFixed(0)}K</div>
                                    <div className="text-xs text-slate-500">{data.orders} sipariş</div>
                                </div>
                            </div>
                        ))}
                    </div>
                </motion.div>

                {/* Report Types */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-surface rounded-2xl p-6 border border-border"
                >
                    <h2 className="text-lg font-bold text-foreground mb-4">Hızlı Rapor</h2>
                    <div className="space-y-2">
                        {activeReportTypes.map((report: any) => (
                            <motion.button
                                key={report.id}
                                whileHover={{ scale: 1.01 }}
                                whileTap={{ scale: 0.99 }}
                                onClick={() => setSelectedReportType(report.id)}
                                className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all ${selectedReportType === report.id
                                    ? 'bg-violet-600/20 border border-violet-500/50'
                                    : 'bg-background rounded-xl border border-border hover:bg-background/80'
                                    }`}
                            >
                                <div className={`p-2 rounded-lg bg-${report.color}-500/20`}>
                                    <report.icon className={`w-4 h-4 text-${report.color}-400`} />
                                </div>
                                <div className="text-left flex-1">
                                    <div className="text-sm font-medium text-foreground">{report.name}</div>
                                    <div className="text-xs text-slate-500">{report.description}</div>
                                </div>
                            </motion.button>
                        ))}
                    </div>
                </motion.div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Scheduled Reports */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-surface rounded-2xl border border-border overflow-hidden"
                >
                    <div className="p-4 border-b border-border flex items-center justify-between">
                        <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                            <Clock className="w-5 h-5 text-violet-500" />
                            Zamanlanmış Raporlar
                        </h2>
                        <button className="text-sm text-violet-400 hover:text-violet-300">
                            + Yeni Zamanlama
                        </button>
                    </div>
                    <div className="divide-y divide-border">
                        {activeScheduledReports.map((report: ScheduledReport) => (
                            <div key={report.id} className="p-4 hover:bg-background/50 transition-colors">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-2 h-2 rounded-full ${report.active ? 'bg-green-500' : 'bg-slate-400 dark:bg-slate-600'}`} />
                                        <div>
                                            <h3 className="text-sm font-medium text-white">{report.name}</h3>
                                            <p className="text-xs text-gray-500">
                                                {report.frequency} • Sonraki: {report.nextRun}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <span className="flex items-center gap-1 text-xs text-slate-500 dark:text-slate-400">
                                            <Mail className="w-3 h-3" />
                                            {report.recipients}
                                        </span>
                                        <button className={`relative w-10 h-5 rounded-full transition-colors ${report.active ? 'bg-violet-600' : 'bg-slate-300 dark:bg-slate-700'
                                            }`}>
                                            <span className={`absolute top-0.5 w-4 h-4 bg-white rounded-full transition-transform ${report.active ? 'translate-x-5' : 'translate-x-0.5'
                                                }`} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </motion.div>

                {/* Recent Reports */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-surface rounded-2xl border border-border overflow-hidden"
                >
                    <div className="p-4 border-b border-border">
                        <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                            <FileSpreadsheet className="w-5 h-5 text-violet-500" />
                            Son Oluşturulan Raporlar
                        </h2>
                    </div>
                    <div className="divide-y divide-border">
                        {activeRecentReports.map((report: RecentReport) => (
                            <div key={report.id} className="p-4 hover:bg-background/50 transition-colors">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${report.format === 'PDF' ? 'bg-red-500/20' : 'bg-green-500/20'
                                            }`}>
                                            <FileText className={`w-4 h-4 ${report.format === 'PDF' ? 'text-red-400' : 'text-green-400'
                                                }`} />
                                        </div>
                                        <div>
                                            <h3 className="text-sm font-medium text-foreground">{report.name}</h3>
                                            <p className="text-xs text-slate-500">
                                                {report.date} • {report.size}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button className="p-1.5 text-slate-500 hover:text-foreground hover:bg-background rounded transition-colors">
                                            <Eye className="w-4 h-4" />
                                        </button>
                                        <button className="p-1.5 text-slate-500 hover:text-foreground hover:bg-background rounded transition-colors">
                                            <Download className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </motion.div>
            </div>

            {/* Export Modal */}
            {showExportModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl p-6 w-full max-w-md border border-border"
                    >
                        <h3 className="text-xl font-bold text-foreground mb-4">Rapor Oluştur</h3>

                        <div className="space-y-4">
                            <div>
                                <label className="text-sm text-slate-600 dark:text-slate-400 block mb-2">Rapor Türü</label>
                                <select className="w-full px-4 py-2 bg-background rounded-xl text-foreground border border-border focus:border-violet-500 focus:outline-none">
                                    {activeReportTypes.map((type: any) => (
                                        <option key={type.id} value={type.id}>{type.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="text-sm text-slate-600 dark:text-slate-400 block mb-2">Tarih Aralığı</label>
                                <div className="flex gap-2">
                                    <input
                                        type="date"
                                        className="flex-1 px-4 py-2 bg-background rounded-xl text-foreground border border-border focus:border-violet-500 focus:outline-none"
                                    />
                                    <input
                                        type="date"
                                        className="flex-1 px-4 py-2 bg-background rounded-xl text-foreground border border-border focus:border-violet-500 focus:outline-none"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="text-sm text-slate-600 dark:text-slate-400 block mb-2">Format</label>
                                <div className="flex gap-2">
                                    <button className="flex-1 py-2 bg-violet-600 text-white rounded-lg">PDF</button>
                                    <button className="flex-1 py-2 bg-background text-slate-500 rounded-lg hover:text-foreground border border-border">Excel</button>
                                    <button className="flex-1 py-2 bg-background text-slate-500 rounded-lg hover:text-foreground border border-border">CSV</button>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-3 mt-6">
                            <button
                                onClick={() => setShowExportModal(false)}
