"use client";

import React, { useState, useEffect } from 'react';
import { 
    Undo2, ScanLine, Box, ArrowUpCircle, AlertTriangle, 
    CheckCircle2, Search, PackageOpen, Truck, RefreshCw
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { getReturns, processReturnScan } from '../../actions/returns';

const DEMO_TENANT_ID = 'demo-tenant-123';

export default function ReturnsManagementPage() {
    const [barcode, setBarcode] = useState('');
    const [isScanning, setIsScanning] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [scanResult, setScanResult] = useState<null | 'success' | 'not_found' | 'already_processed'>(null);
    const [returns, setReturns] = useState<any[]>([]);

    // Stats
    const pendingCount = returns.filter(r => r.status === 'PENDING').length;
    const completedCount = returns.filter(r => r.status === 'COMPLETED' || r.status === 'REFUNDED').length;

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        const data = await getReturns(DEMO_TENANT_ID);
        setReturns(data);
        setIsLoading(false);
    };

    const handleScan = async (e: React.FormEvent) => {
        e.preventDefault();
        if(!barcode.trim()) return;

        setIsScanning(true);
        setScanResult(null);

        const response = await processReturnScan(DEMO_TENANT_ID, barcode.trim());

        setIsScanning(false);
        if (response.success) {
            setScanResult('success');
            fetchData();
        } else {
            setScanResult(response.error as any);
        }
        setBarcode('');
    };

    const handleManualProcess = async (id: string) => {
        setIsScanning(true);
        const response = await processReturnScan(DEMO_TENANT_ID, id);
        setIsScanning(false);
        if(response.success) {
            fetchData();
        }
    };

    return (
        <div className="max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black flex items-center gap-3">
                        <Undo2 className="w-8 h-8 text-orange-500" />
                        Gelişmiş İade & Stok Yönetimi
                    </h1>
                    <p className="text-slate-500 mt-2">
                        Pazaryerlerinden dönen iadelerin barkodunu okutarak Prisma DB üzerinden onaylayın ve stokları anında eski haline getirin.
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Left Side: Scanner UI */}
                <div className="lg:col-span-4 space-y-6">
                    <div className="bg-surface border border-border rounded-[2rem] p-6 lg:p-8 relative overflow-hidden shadow-sm">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-orange-500/10 rounded-full blur-3xl pointer-events-none" />

                        <div className="text-center mb-6">
                            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-2xl mx-auto flex items-center justify-center mb-4">
                                <ScanLine className={`w-8 h-8 text-slate-500 ${isScanning ? 'animate-pulse text-orange-500' : ''}`} />
                            </div>
                            <h2 className="text-xl font-bold">Kargo Barkodu Okutun</h2>
                            <p className="text-xs text-slate-500 mt-2">Takip numarası veya Sipariş No taratın.</p>
                        </div>

                        <form onSubmit={handleScan} className="relative mb-6">
                            <input 
                                type="text"
                                autoFocus
                                value={barcode}
                                onChange={(e) => setBarcode(e.target.value)}
                                placeholder="Barkod veya İade Kodu..."
                                disabled={isScanning}
                                className="w-full bg-slate-50 dark:bg-background border-2 border-border rounded-xl px-4 py-4 font-mono text-center text-lg focus:outline-none focus:border-orange-500 transition-colors disabled:opacity-50"
                            />
                            <button type="submit" className="hidden">Tara</button>
                        </form>

                        <AnimatePresence>
                            {scanResult === 'success' && (
                                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="bg-emerald-500/10 border border-emerald-500/20 p-4 rounded-xl flex items-start gap-3">
                                    <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" />
                                    <div>
                                        <div className="text-sm font-bold text-emerald-600 dark:text-emerald-400">İade Eşleşti & Stok İşlendi</div>
                                        <div className="text-xs text-emerald-600/70 dark:text-emerald-400/70 mt-1">Veritabanına iade onaylandı bilgisi düşüldü.</div>
                                    </div>
                                </motion.div>
                            )}
                            {scanResult === 'not_found' && (
                                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl flex items-start gap-3">
                                    <AlertTriangle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                                    <div>
                                        <div className="text-sm font-bold text-red-600 dark:text-red-400">Kayıt Bulunamadı</div>
                                        <div className="text-xs text-red-600/70 dark:text-red-400/70 mt-1">Sistemde bu koda ait bir iade işlemi bulunamadı.</div>
                                    </div>
                                </motion.div>
                            )}
                            {scanResult === 'already_processed' && (
                                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="bg-blue-500/10 border border-blue-500/20 p-4 rounded-xl flex items-start gap-3">
                                    <AlertTriangle className="w-5 h-5 text-blue-500 shrink-0 mt-0.5" />
                                    <div>
                                        <div className="text-sm font-bold text-blue-600 dark:text-blue-400">Zaten Onaylanmış</div>
                                        <div className="text-xs text-blue-600/70 dark:text-blue-400/70 mt-1">Bu ürün iadesi zaten sisteme başarılı girilmiştir.</div>
                                    </div>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-surface border border-border rounded-2xl p-4 text-center">
                            <div className="text-2xl font-black text-slate-900 dark:text-white mb-1">
                                {isLoading ? '-' : pendingCount}
                            </div>
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Bekleyen İade</div>
                        </div>
                        <div className="bg-surface border border-border rounded-2xl p-4 text-center">
                            <div className="text-2xl font-black text-emerald-500 mb-1">
                                {isLoading ? '-' : completedCount}
                            </div>
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Geri Kazanılan Stok</div>
                        </div>
                    </div>
                </div>

                {/* Right Side: Log Data */}
                <div className="lg:col-span-8">
                    <div className="bg-surface border border-border rounded-[2rem] overflow-hidden flex flex-col h-full min-h-[400px]">
                        <div className="p-6 border-b border-border flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                            <h3 className="text-lg font-bold flex items-center gap-2">
                                Gelen İade Beklemeleri (Prisma DB)
                            </h3>
                            <div className="relative w-full sm:w-64">
                                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input 
                                    type="text" 
                                    className="w-full bg-background border border-border rounded-xl pl-9 pr-4 py-2 text-sm focus:outline-none focus:ring-2 ring-orange-500/50"
                                    placeholder="Sipariş no ara..."
                                />
                            </div>
                        </div>

                        <div className="flex-1 overflow-x-auto p-0">
                            {isLoading ? (
                                <div className="flex flex-col items-center justify-center h-[300px] text-slate-400">
                                    <RefreshCw className="w-8 h-8 animate-spin mx-auto mb-4" />
                                    Veritabanından İadeler Çekiliyor...
                                </div>
                            ) : returns.length === 0 ? (
                                <div className="text-center py-20 text-slate-500">
                                    <PackageOpen className="w-12 h-12 mx-auto mb-4 opacity-50" />
                                    <p className="font-bold">Henüz kaydedilmiş bir iade yok.</p>
                                </div>
                            ) : (
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 text-xs font-bold uppercase tracking-widest">
                                            <th className="px-6 py-4 border-b border-border">Sipariş (ID)</th>
                                            <th className="px-6 py-4 border-b border-border">İade Sebebi</th>
                                            <th className="px-6 py-4 border-b border-border text-center">Durum</th>
                                            <th className="px-6 py-4 border-b border-border text-right">Manuel Aksiyon</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-border">
                                        {returns.map(item => (
                                            <tr key={item.id} className="hover:bg-slate-50 dark:hover:bg-slate-900/50 transition-colors">
                                                <td className="px-6 py-4">
                                                    <div className="font-bold text-slate-900 dark:text-white flex items-center gap-2">
                                                        {item.orderId}
                                                    </div>
                                                    <div className="text-xs text-slate-500 mt-1 font-mono flex items-center gap-1">
                                                        <Box className="w-3 h-3" /> Trk: {item.trackingNumber}
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4">
                                                    <div className="text-sm font-medium text-slate-700 dark:text-slate-300">{item.reason}</div>
                                                    <div className="text-xs text-slate-400 mt-1">{item.marketplace} ({item.date})</div>
                                                </td>
                                                <td className="px-6 py-4 text-center">
                                                    {item.status === 'PENDING' ? (
                                                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-500/10 text-amber-600 rounded-full text-xs font-bold">
                                                            <Truck className="w-3 h-3" /> Kargo Bekleniyor
                                                        </span>
                                                    ) : (
                                                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-500/10 text-emerald-500 rounded-full text-xs font-bold">
                                                            <CheckCircle2 className="w-3 h-3" /> Stoklara Eklendi
                                                        </span>
                                                    )}
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    {item.status === 'PENDING' && (
                                                        <button disabled={isScanning} onClick={() => handleManualProcess(item.id)} className="px-4 py-2 border border-border rounded-xl text-xs font-bold hover:bg-orange-50 hover:text-orange-600 dark:hover:bg-orange-500/10 transition-colors flex items-center gap-2 ml-auto disabled:opacity-50">
                                                            <ArrowUpCircle className="w-4 h-4" /> Elle Kurtar
                                                        </button>
                                                    )}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { apiClient } from '@/lib/api-client';
import { useReviews, useReviewStats } from '@/lib/hooks';
import {
    MessageSquare, Star, ThumbsUp, Search,
    RefreshCw, Reply, Flag, CheckCircle2, Clock,
    AlertTriangle, TrendingUp, Eye, ExternalLink,
    Sparkles, Send, Loader2, BarChart3, X
} from 'lucide-react';

interface Review {
    id: string | number;
    customer?: string; customerName?: string;
    avatar?: string;
    product?: string; productName?: string;
    platform: string;
    rating: number;
    date: string;
    title?: string;
    comment: string;
    helpful?: number;
    status: 'pending' | 'replied' | 'flagged';
    reply?: string | null;
}

const PLATFORM_COLORS: Record<string, string> = {
    Trendyol: 'bg-orange-500/10 text-orange-500 border-orange-500/20',
    Hepsiburada: 'bg-red-500/10 text-red-500 border-red-500/20',
    Amazon: 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    N11: 'bg-purple-500/10 text-purple-500 border-purple-500/20',
    Çiçeksepeti: 'bg-pink-500/10 text-pink-500 border-pink-500/20',
};

function StarRow({ rating }: { rating: number }) {
    return (
        <div className="flex gap-0.5">
            {Array.from({ length: 5 }, (_, i) => (
                <Star key={i} className={`w-3.5 h-3.5 ${i < rating ? 'text-yellow-400 fill-yellow-400' : 'text-slate-300 dark:text-slate-600'}`} />
            ))}
        </div>
    );
}

export default function ReviewsPage() {
    const { data: statsData, loading: statsLoading } = useReviewStats();
    const { data: reviewsData, loading: reviewsLoading, error, refetch: fetchReviews } = useReviews();
    const [searchQuery, setSearchQuery] = useState('');
    const [ratingFilter, setRatingFilter] = useState('all');
    const [statusFilter, setStatusFilter] = useState('all');
    const [platformFilter, setPlatformFilter] = useState('all');
    const [openReplyId, setOpenReplyId] = useState<string | number | null>(null);
    const [replyText, setReplyText] = useState('');
    const [aiLoading, setAiLoading] = useState(false);
    const [sendingId, setSendingId] = useState<string | number | null>(null);
    const [localReviews, setLocalReviews] = useState<Review[]>([]);

    useEffect(() => {
        if (reviewsData && (reviewsData as any).data) {
            setLocalReviews((reviewsData as any).data);
        }
    }, [reviewsData]);

    const reviews = localReviews;
    const apiLoading = statsLoading || reviewsLoading;

    const filteredReviews = reviews.filter(review => {
        const product = review.product || review.productName || '';
        const customer = review.customer || review.customerName || '';
        if (searchQuery && !product.toLowerCase().includes(searchQuery.toLowerCase()) &&
            !customer.toLowerCase().includes(searchQuery.toLowerCase()) &&
            !review.comment.toLowerCase().includes(searchQuery.toLowerCase())) return false;
        if (ratingFilter !== 'all' && review.rating !== parseInt(ratingFilter)) return false;
        if (statusFilter !== 'all' && review.status !== statusFilter) return false;
        if (platformFilter !== 'all' && review.platform !== platformFilter) return false;
        return true;
    });

    const stats = useMemo(() => {
        const s = statsData as any;
        return {
            total: s?.totalReviews || 0,
            avgRating: s?.averageRating || '0.0',
            pending: s?.pendingCount || 0,
            positivePercent: s?.positivePercent || 0,
            platformBreakdown: s?.platformBreakdown || []
        };
    }, [statsData]);

    const totalReviews = stats.total;
    const avgRating = stats.avgRating;
    const pendingCount = stats.pending;
    const positivePercent = stats.positivePercent;
    const platformBreakdown = stats.platformBreakdown;
    const platforms = useMemo(() => platformBreakdown.map((p: any) => p.platform), [platformBreakdown]);

    const generateAiReply = async (review: Review) => {
        setAiLoading(true);
        try {
            const res = await apiClient.request<{ reply: string }>('/ai/review-reply', {
                method: 'POST',
                body: JSON.stringify({
                    rating: review.rating,
                    comment: review.comment,
                    product: review.product || review.productName || '',
                    platform: review.platform,
                }),
            });
            if (res?.reply) setReplyText(res.reply);
        } catch {
            setReplyText('AI yanit onerisi alinamadi. Lutfen daha sonra tekrar deneyin.');
        } finally { setAiLoading(false); }
    };

    const submitReply = async (reviewId: string | number) => {
        if (!replyText.trim()) return;
        setSendingId(reviewId);
        try {
            await apiClient.replyToReview(String(reviewId), replyText);
            // Optimistic update
            setLocalReviews(prev => prev.map(r =>
                r.id === reviewId ? { ...r, reply: replyText, status: 'replied' } : r
            ));
            fetchReviews();
        } catch { /* ignore */ }
        setOpenReplyId(null);
        setReplyText('');
        setSendingId(null);
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight flex items-center gap-3">
                        <MessageSquare className="w-8 h-8 text-pink-500" /> Müşteri Yorumları
                    </h1>
                    <p className="text-slate-500 mt-1 font-medium">Yorum yönetimi, analizi ve AI destekli yanıtlar</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => fetchReviews()}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-slate-500 hover:text-foreground transition-all">
                        <RefreshCw className={`w-4 h-4 ${apiLoading ? 'animate-spin' : ''}`} /> Senkronize Et
                    </button>
                    <button
                        className="flex items-center gap-2 px-4 py-2.5 bg-pink-600 rounded-xl text-white text-sm font-bold hover:bg-pink-700 transition-all shadow-lg shadow-pink-500/20">
                        <Sparkles className="w-4 h-4" /> AI Toplu Yanıt
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Yorum', value: totalReviews, sub: '+23 bu hafta', color: 'pink', icon: MessageSquare, up: true },
                    { label: 'Ort. Puan', value: avgRating + ' ★', sub: 'tüm platformlar', color: 'yellow', icon: Star, up: true },
                    { label: 'Yanıt Bekleyen', value: pendingCount, sub: 'Hızlı yanıt önemli!', color: 'orange', icon: Clock, up: false },
                    { label: 'Pozitif Oran', value: `%${positivePercent}`, sub: '4-5 yıldız', color: 'green', icon: ThumbsUp, up: true },
                ].map((s, i) => (
                    <motion.div key={s.label} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}
                        className={`bg-gradient-to-br from-${s.color}-500/10 to-${s.color}-600/5 rounded-2xl p-5 border border-${s.color}-500/20`}>
                        <div className="flex items-center gap-3 mb-3">
                            <div className={`p-2.5 bg-${s.color}-500/20 rounded-xl`}><s.icon className={`w-5 h-5 text-${s.color}-500`} /></div>
                            <span className="text-slate-600 dark:text-slate-400 text-sm font-medium">{s.label}</span>
                        </div>
                        {apiLoading ? (
                            <div className="h-7 bg-white/20 rounded-lg animate-pulse" />
                        ) : (
                            <div className="text-2xl font-black text-foreground">{s.value}</div>
                        )}
                        <div className={`text-xs mt-1 font-bold text-${s.color}-600 dark:text-${s.color}-400`}>{s.sub}</div>
                    </motion.div>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {/* Sidebar */}
                <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="space-y-4">
                    {/* Platform Stats */}
                    <div className="bg-surface rounded-2xl p-5 border border-border">
                        <h3 className="text-base font-bold text-foreground mb-4 flex items-center gap-2">
                            <BarChart3 size={16} className="text-pink-500" /> Platform Puanları
                        </h3>
                        {platformBreakdown.length === 0 ? (
                            <p className="text-xs text-slate-500">Henüz veri yok</p>
                        ) : (
                            <div className="space-y-3">
                                {platformBreakdown.map((p: any) => (
                                    <div key={p.platform} className="p-3 bg-background rounded-xl border border-border">
                                        <div className="flex justify-between mb-1">
                                            <span className="text-sm font-bold text-foreground">{p.platform}</span>
                                            <div className="flex items-center gap-1">
                                                <Star className="w-3.5 h-3.5 text-yellow-500 fill-yellow-500" />
                                                <span className="text-sm font-bold">{p.avgRating}</span>
                                            </div>
                                        </div>
                                        <div className="flex justify-between text-[10px] text-slate-500">
                                            <span>{p.totalReviews} yorum</span>
                                            <span className="text-green-500 font-bold">%{p.positive} pozitif</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Filters */}
                    <div className="bg-surface rounded-2xl p-5 border border-border space-y-4">
                        <h3 className="text-sm font-bold text-foreground">Filtrele</h3>
                        <select value={platformFilter} onChange={e => setPlatformFilter(e.target.value)}
                            className="w-full px-3 py-2 bg-background rounded-xl text-sm border border-border text-foreground focus:border-pink-500 focus:outline-none">
                            <option value="all">Tüm Platformlar</option>
                            {platforms.map((p: string) => <option key={p} value={p}>{p}</option>)}
                        </select>
                        <select value={ratingFilter} onChange={e => setRatingFilter(e.target.value)}
                            className="w-full px-3 py-2 bg-background rounded-xl text-sm border border-border text-foreground focus:border-pink-500 focus:outline-none">
                            <option value="all">Tüm Puanlar</option>
                            {[5, 4, 3, 2, 1].map(n => <option key={n} value={n}>{n} Yıldız</option>)}
                        </select>
                        <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)}
                            className="w-full px-3 py-2 bg-background rounded-xl text-sm border border-border text-foreground focus:border-pink-500 focus:outline-none">
                            <option value="all">Tüm Durumlar</option>
                            <option value="pending">Yanıt Bekleyen</option>
                            <option value="replied">Yanıtlandı</option>
                            <option value="flagged">İşaretli</option>
                        </select>
                    </div>
                </motion.div>

                {/* Reviews List */}
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="lg:col-span-3 space-y-4">
                    {/* Search */}
                    <div className="relative">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input type="text" placeholder="Yorum, ürün veya müşteri ara..."
                            value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
                            className="w-full pl-11 pr-4 py-3 bg-surface rounded-2xl text-foreground placeholder-slate-500 border border-border focus:border-pink-500 focus:outline-none" />
                    </div>

                    {apiLoading && (
                        <div className="py-16 flex items-center justify-center gap-3 text-slate-500 bg-surface rounded-2xl border border-border">
                            <Loader2 size={20} className="animate-spin" />
