                        </div>
                    )}

                    {!apiLoading && filteredReviews.length === 0 && (
                        <div className="text-center py-16 bg-surface rounded-2xl border border-dashed border-border">
                            <MessageSquare size={40} className="mx-auto mb-3 text-slate-300" />
                            <p className="font-bold text-foreground">Yorum bulunamadı</p>
                            <p className="text-sm text-slate-500 mt-1">Filtre veya arama terimini değiştirmeyi deneyin</p>
                        </div>
                    )}

                    {filteredReviews.map((review, index) => {
                        const customer = review.customer || review.customerName || '?';
                        const product = review.product || review.productName || '';
                        const initials = customer.split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);
                        const platformCls = PLATFORM_COLORS[review.platform] || 'bg-slate-500/10 text-slate-500 border-slate-500/20';

                        return (
                            <motion.div key={review.id} initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * 0.04 }}
                                className={`bg-surface rounded-2xl border overflow-hidden ${review.status === 'flagged' ? 'border-red-500/40' : 'border-border'}`}>
                                <div className="p-5">
                                    {/* Header row */}
                                    <div className="flex items-start justify-between mb-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-pink-500/20 to-purple-500/20 flex items-center justify-center text-sm font-black text-pink-600">
                                                {review.avatar || initials}
                                            </div>
                                            <div>
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    <span className="font-bold text-foreground text-sm">{customer}</span>
                                                    <span className={`px-2 py-0.5 rounded-md text-[10px] font-bold border ${platformCls}`}>{review.platform}</span>
                                                </div>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <StarRow rating={review.rating} />
                                                    <span className="text-[10px] text-slate-500">{review.date}</span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            {review.status === 'pending' && (
                                                <span className="px-2 py-1 bg-yellow-500/10 text-yellow-500 rounded-full text-[10px] font-bold flex items-center gap-1 border border-yellow-500/20">
                                                    <Clock size={10} /> Bekliyor
                                                </span>
                                            )}
                                            {review.status === 'replied' && (
                                                <span className="px-2 py-1 bg-green-500/10 text-green-500 rounded-full text-[10px] font-bold flex items-center gap-1 border border-green-500/20">
                                                    <CheckCircle2 size={10} /> Yanıtlandı
                                                </span>
                                            )}
                                            {review.status === 'flagged' && (
                                                <span className="px-2 py-1 bg-red-500/10 text-red-500 rounded-full text-[10px] font-bold flex items-center gap-1 border border-red-500/20">
                                                    <AlertTriangle size={10} /> Dikkat
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    {product && <p className="text-xs text-slate-500 mb-2 font-medium">{product}</p>}
                                    {review.title && <h4 className="font-bold text-foreground mb-1 text-sm">{review.title}</h4>}
                                    <p className="text-slate-600 dark:text-slate-300 text-sm leading-relaxed">{review.comment}</p>

                                    {/* Existing reply */}
                                    {review.reply && (
                                        <div className="mt-4 p-3 bg-pink-500/8 border border-pink-500/20 rounded-xl">
                                            <div className="flex items-center gap-2 mb-2">
                                                <Reply className="w-3.5 h-3.5 text-pink-500" />
                                                <span className="text-xs font-bold text-pink-500">Satıcı Yanıtı</span>
                                            </div>
                                            <p className="text-xs text-slate-600 dark:text-slate-300">{review.reply}</p>
                                        </div>
                                    )}

                                    {/* Footer */}
                                    <div className="flex items-center justify-between mt-4 pt-4 border-t border-border">
                                        <span className="text-xs text-slate-500 flex items-center gap-1">
                                            <ThumbsUp size={12} /> {review.helpful || 0} faydalı
                                        </span>
                                        <div className="flex items-center gap-2">
                                            {!review.reply && (
                                                <button onClick={() => { setOpenReplyId(openReplyId === review.id ? null : review.id); setReplyText(''); }}
                                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-pink-600 text-white rounded-lg text-xs font-bold hover:bg-pink-700 transition-all">
                                                    <Reply size={12} /> Yanıtla
                                                </button>
                                            )}
                                            <button className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-background rounded-lg transition-all">
                                                <Flag size={14} />
                                            </button>
                                            <button className="p-1.5 text-slate-400 hover:text-foreground hover:bg-background rounded-lg transition-all">
                                                <ExternalLink size={14} />
                                            </button>
                                        </div>
                                    </div>

                                    {/* Reply form */}
                                    <AnimatePresence>
                                        {openReplyId === review.id && !review.reply && (
                                            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}
                                                className="mt-4 pt-4 border-t border-border overflow-hidden">
                                                <div className="relative">
                                                    <textarea value={replyText} onChange={e => setReplyText(e.target.value)}
                                                        placeholder="Yanıtınızı yazın..."
                                                        className="w-full px-4 py-3 bg-background rounded-xl text-foreground placeholder-slate-500 border border-border focus:border-pink-500 focus:outline-none resize-none text-sm"
                                                        rows={3} />
                                                    {aiLoading && (
                                                        <div className="absolute inset-0 bg-surface/80 rounded-xl flex items-center justify-center gap-2 text-pink-500 text-sm font-bold">
                                                            <Loader2 size={16} className="animate-spin" /> AI yazıyor...
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="flex items-center justify-between mt-3">
                                                    <button onClick={() => generateAiReply(review)} disabled={aiLoading}
                                                        className="flex items-center gap-1.5 text-sm text-pink-500 hover:text-pink-400 font-bold disabled:opacity-50 transition-all">
                                                        <Sparkles size={14} /> AI ile Yanıt Oluştur
                                                    </button>
                                                    <div className="flex items-center gap-2">
                                                        <button onClick={() => { setOpenReplyId(null); setReplyText(''); }}
                                                            className="px-4 py-2 text-slate-500 hover:text-foreground transition-colors font-bold text-sm">İptal</button>
                                                        <button onClick={() => submitReply(review.id)} disabled={!replyText.trim() || !!sendingId}
                                                            className="flex items-center gap-1.5 px-4 py-2 bg-pink-600 text-white rounded-xl font-bold hover:bg-pink-700 transition-all text-sm disabled:opacity-50">
                                                            {sendingId === review.id ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />} Gönder
                                                        </button>
                                                    </div>
                                                </div>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>
                            </motion.div>
                        );
                    })}
                </motion.div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Search, Command, FileText, Package, ShoppingCart, Users,
    Settings, BarChart3, Truck, ArrowRight, Clock, Star,
    Hash, X, Keyboard
} from 'lucide-react';

interface SearchResult {
    id: string;
    type: 'product' | 'order' | 'customer' | 'page' | 'setting';
    title: string;
    subtitle: string;
    icon: React.ElementType;
    url: string;
}

const allResults: SearchResult[] = [
    { id: '1', type: 'product', title: 'iPhone 15 Pro Max Kılıf', subtitle: 'SKU: IP15PM-001 · ₺89.90', icon: Package, url: '/dashboard/products/1' },
    { id: '2', type: 'product', title: 'Galaxy S24 Ekran Koruyucu', subtitle: 'SKU: GS24-EC-01 · ₺49.90', icon: Package, url: '/dashboard/products/2' },
    { id: '3', type: 'product', title: 'AirPods Pro 2 Kılıf', subtitle: 'SKU: APP2-K-01 · ₺69.90', icon: Package, url: '/dashboard/products/3' },
    { id: '4', type: 'order', title: 'Sipariş #ORD-2025-001245', subtitle: 'Ahmet Yılmaz · ₺342.00 · Kargoda', icon: ShoppingCart, url: '/dashboard/orders/1245' },
    { id: '5', type: 'order', title: 'Sipariş #ORD-2025-001244', subtitle: 'Fatma Demir · ₺189.00 · Teslim Edildi', icon: ShoppingCart, url: '/dashboard/orders/1244' },
    { id: '6', type: 'customer', title: 'Ahmet Yılmaz', subtitle: 'ahmet@email.com · 12 sipariş', icon: Users, url: '/dashboard/customers/1' },
    { id: '7', type: 'customer', title: 'Fatma Demir', subtitle: 'fatma@email.com · 8 sipariş', icon: Users, url: '/dashboard/customers/2' },
    { id: '8', type: 'page', title: 'Dashboard', subtitle: 'Ana sayfa', icon: BarChart3, url: '/dashboard' },
    { id: '9', type: 'page', title: 'Ürünler', subtitle: 'Ürün listesi', icon: Package, url: '/dashboard/products' },
    { id: '10', type: 'page', title: 'Siparişler', subtitle: 'Sipariş yönetimi', icon: ShoppingCart, url: '/dashboard/orders' },
    { id: '11', type: 'page', title: 'Raporlar', subtitle: 'Gelişmiş raporlama', icon: BarChart3, url: '/dashboard/advanced-reports' },
    { id: '12', type: 'page', title: 'Tedarikçiler', subtitle: 'Tedarikçi yönetimi', icon: Truck, url: '/dashboard/suppliers' },
    { id: '13', type: 'page', title: 'Ayarlar', subtitle: 'Hesap ayarları', icon: Settings, url: '/dashboard/settings' },
    { id: '14', type: 'setting', title: 'Bildirim Ayarları', subtitle: 'E-posta ve push bildirimleri', icon: Settings, url: '/dashboard/settings#notifications' },
    { id: '15', type: 'setting', title: 'API Anahtarları', subtitle: 'API erişim yönetimi', icon: Settings, url: '/dashboard/settings#api' },
];

const recentSearches = ['iPhone kılıf', 'sipariş #1245', 'stok kontrol', 'fatma demir'];

const typeLabels: Record<string, string> = { product: 'Ürün', order: 'Sipariş', customer: 'Müşteri', page: 'Sayfa', setting: 'Ayar' };

export default function AdvancedSearchPage() {
    const [query, setQuery] = useState('');
    const [isOpen, setIsOpen] = useState(true);
    const [selectedIndex, setSelectedIndex] = useState(0);
    const [typeFilter, setTypeFilter] = useState<string | null>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    const results = query.length > 0
        ? allResults.filter(r => {
            if (typeFilter && r.type !== typeFilter) return false;
            const q = query.toLowerCase();
            return r.title.toLowerCase().includes(q) || r.subtitle.toLowerCase().includes(q);
        })
        : [];

    const groupedResults = results.reduce((acc, r) => {
        if (!acc[r.type]) acc[r.type] = [];
        acc[r.type].push(r);
        return acc;
    }, {} as Record<string, SearchResult[]>);

    useEffect(() => {
        const timer = setTimeout(() => {
            setSelectedIndex(0);
        }, 0);
        return () => clearTimeout(timer);
    }, [query]);

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') { e.preventDefault(); setSelectedIndex(prev => Math.min(prev + 1, results.length - 1)); }
        if (e.key === 'ArrowUp') { e.preventDefault(); setSelectedIndex(prev => Math.max(prev - 1, 0)); }
        if (e.key === 'Escape') setQuery('');
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            <div>
                <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                    <Search className="w-8 h-8 text-cyan-500" /> Gelişmiş Arama
                </h1>
                <p className="text-slate-500 mt-1">Ürün, sipariş, müşteri ve sayfaları hızlıca arayın</p>
            </div>

            {/* Search Box */}
            <div className="bg-surface rounded-2xl border border-border p-2">
                <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                    <input
                        ref={inputRef}
                        type="text"
                        value={query}
                        onChange={e => setQuery(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder="Ürün, sipariş, müşteri veya sayfa ara... (Ctrl+K)"
                        className="w-full pl-12 pr-20 py-4 bg-transparent text-lg text-foreground placeholder:text-slate-600 focus:outline-none"
                        autoFocus
                    />
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
                        {query && <button onClick={() => setQuery('')} className="p-1 hover:bg-background rounded text-slate-500"><X className="w-4 h-4" /></button>}
                        <kbd className="px-2 py-1 bg-background rounded text-xs text-slate-500 border border-border">Ctrl+K</kbd>
                    </div>
                </div>

                {/* Type Filters */}
                <div className="flex items-center gap-2 px-2 pb-2">
                    <span className="text-xs text-slate-600">Filtre:</span>
                    {[null, 'product', 'order', 'customer', 'page', 'setting'].map(t => (
                        <button key={t ?? 'all'} onClick={() => setTypeFilter(t)}
                            className={`px-2.5 py-1 text-xs rounded-lg transition-all ${typeFilter === t ? 'bg-cyan-500/20 text-cyan-400' : 'text-slate-500 hover:text-foreground hover:bg-background'}`}>
                            {t ? typeLabels[t] : 'Tümü'}
                        </button>
                    ))}
                </div>
            </div>

            {/* Results */}
            {query.length > 0 && results.length > 0 && (
                <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                    {Object.entries(groupedResults).map(([type, items]) => (
                        <div key={type}>
                            <div className="px-4 py-2 bg-background/50 text-xs font-medium text-slate-500 uppercase tracking-wider">
                                {typeLabels[type]} ({items.length})
                            </div>
                            {items.map((item, i) => (
                                <motion.div
                                    key={item.id}
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    className="flex items-center gap-3 px-4 py-3 hover:bg-background/50 cursor-pointer transition-colors border-b border-border/30"
                                >
                                    <item.icon className="w-5 h-5 text-slate-500" />
                                    <div className="flex-1">
                                        <div className="text-sm text-foreground font-medium">{item.title}</div>
                                        <div className="text-xs text-slate-500">{item.subtitle}</div>
                                    </div>
                                    <ArrowRight className="w-4 h-4 text-slate-600" />
                                </motion.div>
                            ))}
                        </div>
                    ))}
                </div>
            )}

            {query.length > 0 && results.length === 0 && (
                <div className="bg-surface rounded-2xl border border-border p-12 text-center">
                    <Search className="w-12 h-12 text-slate-700 mx-auto mb-3" />
                    <p className="text-sm text-slate-500">&quot;{query}&quot; için sonuç bulunamadı</p>
                </div>
            )}

            {/* Recent & Shortcuts */}
            {query.length === 0 && (
                <div className="grid grid-cols-2 gap-6">
                    <div className="bg-surface rounded-2xl border border-border p-5">
                        <h3 className="text-sm font-bold text-foreground flex items-center gap-2 mb-4"><Clock className="w-4 h-4 text-slate-400" /> Son Aramalar</h3>
                        <div className="space-y-2">
                            {recentSearches.map((s, i) => (
                                <button key={i} onClick={() => setQuery(s)} className="w-full text-left px-3 py-2 hover:bg-background rounded-lg text-sm text-slate-400 hover:text-foreground flex items-center gap-2 transition-colors">
                                    <Clock className="w-3.5 h-3.5" /> {s}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="bg-surface rounded-2xl border border-border p-5">
                        <h3 className="text-sm font-bold text-foreground flex items-center gap-2 mb-4"><Keyboard className="w-4 h-4 text-slate-400" /> Kısayollar</h3>
                        <div className="space-y-2">
                            {[
                                { keys: 'Ctrl+K', desc: 'Aramayı aç' },
                                { keys: '↑ ↓', desc: 'Sonuçlarda gezin' },
                                { keys: 'Enter', desc: 'Seçili sonuca git' },
                                { keys: 'Esc', desc: 'Aramayı temizle' },
                            ].map((s, i) => (
                                <div key={i} className="flex items-center justify-between px-3 py-2 text-sm">
                                    <span className="text-slate-400">{s.desc}</span>
                                    <kbd className="px-2 py-0.5 bg-background rounded text-xs text-slate-500 border border-border">{s.keys}</kbd>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Search, Globe, TrendingUp, AlertTriangle, CheckCircle2,
    XCircle, ArrowUpRight, BarChart3, FileText, Link, Eye,
    RefreshCw, ChevronDown
} from 'lucide-react';

import { useSeoPages, useSeoStats, SeoPageData } from '@/lib/hooks';

const getScoreColor = (score: number) => score >= 80 ? 'text-emerald-400' : score >= 60 ? 'text-amber-400' : 'text-red-400';
const getScoreBg = (score: number) => score >= 80 ? 'bg-emerald-500' : score >= 60 ? 'bg-amber-500' : 'bg-red-500';

export default function SeoAnalysisPage() {
    const { data: pagesData, loading: pagesLoading } = useSeoPages();
    const { data: statsData, loading: statsLoading } = useSeoStats();

    const [searchTerm, setSearchTerm] = useState('');
    const [selectedPageId, setSelectedPageId] = useState<string | null>(null);
    const [sortBy, setSortBy] = useState<'score' | 'path'>('score');

    const pages = pagesData?.pages || [];
    const isLoading = pagesLoading || statsLoading;

    const filtered = pages
        .filter(p => p.path.toLowerCase().includes(searchTerm.toLowerCase()) || p.title.toLowerCase().includes(searchTerm.toLowerCase()))
        .sort((a, b) => sortBy === 'score' ? b.seoScore - a.seoScore : a.path.localeCompare(b.path));

    const stats = statsData || {
        overallScore: 0,
        totalPages: 0,
        indexedPages: 0,
        notIndexedPages: 0,
        avgTitleLength: 0,
        avgDescriptionLength: 0,
        pagesWithoutMeta: 0,
        pagesWithLowScore: 0,
        totalKeywords: 0,
        totalRedirects: 0,
        sitemapPages: 0,
        robotsRules: 0,
        structuredDataTypes: 0,
        lastCrawlDate: '',
        crawlErrors: 0,
        mobileScore: 0,
        performanceScore: 0,
        accessibilityScore: 0,
        bestPracticesScore: 0,
        scoreHistory: []
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                        <Globe className="w-7 h-7 text-indigo-400" /> SEO Analiz Aracı
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">Ürün sayfalarınızın SEO performansını analiz edin</p>
                </div>
                <button className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm transition-colors">
                    <RefreshCw className="w-4 h-4" /> Yeniden Tara
                </button>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-4">
                {[
                    { label: 'Ort. SEO Skoru', value: stats.overallScore, icon: BarChart3, color: getScoreColor(stats.overallScore), suffix: '/100' },
                    { label: 'Endekslenen', value: stats.indexedPages, icon: CheckCircle2, color: 'text-emerald-400', suffix: ` / ${stats.totalPages}` },
                    { label: 'Düşük Skorlu', value: stats.pagesWithLowScore, icon: AlertTriangle, color: 'text-amber-400', suffix: ' sayfa' },
                    { label: 'Mobil Skor', value: stats.mobileScore, icon: Eye, color: 'text-blue-400', suffix: '/100' },
                ].map((stat, i) => (
                    <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                        className="bg-surface rounded-xl border border-border p-5">
                        <stat.icon className={`w-5 h-5 ${stat.color} mb-2`} />
                        <div className="text-2xl font-bold text-foreground">{stat.value}<span className="text-sm text-slate-500">{stat.suffix}</span></div>
                        <div className="text-xs text-slate-500">{stat.label}</div>
                    </motion.div>
                ))}
            </div>

            {/* Search & Filter */}
            <div className="flex gap-3">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Sayfa veya başlık ara..."
                        className="w-full pl-10 pr-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                </div>
                <select value={sortBy} onChange={e => setSortBy(e.target.value as 'score' | 'path')}
                    className="px-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border focus:outline-none">
                    <option value="score">SEO Skoru</option>
                    <option value="path">URL Yolu</option>
                </select>
            </div>

            <div className="grid grid-cols-3 gap-6">
                {/* Product/Page List */}
                <div className="col-span-2 space-y-3">
                    {filtered.map((p, i) => (
                        <motion.div key={p.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
                            onClick={() => setSelectedPageId(selectedPageId === p.id ? null : p.id)}
                            className={`bg-surface rounded-xl border p-5 cursor-pointer transition-all ${selectedPageId === p.id ? 'border-indigo-500/50' : 'border-border hover:border-indigo-500/20'}`}>
                            <div className="flex items-start justify-between mb-3">
                                <div>
                                    <h3 className="text-sm font-semibold text-foreground">{p.title}</h3>
                                    <div className="flex items-center gap-2 mt-1">
                                        <span className="text-xs text-slate-500">{p.path}</span>
                                        <span className="text-xs text-slate-600">•</span>
                                        <span className={`text-[10px] px-1.5 py-0.5 rounded ${p.indexable ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'}`}>
                                            {p.indexable ? 'Endekslenebilir' : 'no-index'}
                                        </span>
                                    </div>
                                </div>
                                <div className={`text-2xl font-bold ${getScoreColor(p.seoScore)}`}>{p.seoScore}</div>
                            </div>

                            <p className="text-xs text-slate-400 line-clamp-1 mb-3">{p.description}</p>

                            {/* Keywords */}
                            <div className="flex flex-wrap gap-1.5">
                                {p.keywords.slice(0, 5).map((kw, j) => (
                                    <span key={j} className="text-[10px] px-2 py-0.5 rounded-full bg-indigo-500/10 text-indigo-400">
                                        {kw}
                                    </span>
                                ))}
                                {p.keywords.length > 5 && <span className="text-[10px] text-slate-500">+{p.keywords.length - 5}</span>}
                            </div>

                            {/* Meta info */}
                            <div className="flex gap-4 mt-3 pt-3 border-t border-border/50 text-xs text-slate-500">
                                <span className="flex items-center gap-1"><RefreshCw className="w-3 h-3" /> Son Modifikasyon: {new Date(p.lastModified).toLocaleDateString('tr-TR')}</span>
                                <span className="flex items-center gap-1"><Link className="w-3 h-3" /> Canonical: {p.canonical.replace('https://pazaryonetimi.com', '')}</span>
                            </div>
                        </motion.div>
                    ))}
                    {filtered.length === 0 && !isLoading && (
                        <div className="p-10 text-center bg-surface rounded-xl border border-dashed border-border text-slate-500">
                            Sayfa bulunamadı.
                        </div>
                    )}
                </div>

                {/* Detail & Tips */}
                <div className="space-y-4">
                    {selectedPageId && (() => {
                        const p = pages.find(pr => pr.id === selectedPageId)!;
                        return (
                            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="bg-surface rounded-xl border border-border p-5">
                                <h3 className="text-sm font-semibold text-foreground mb-3">Tüm Anahtar Kelimeler</h3>
                                <div className="flex flex-wrap gap-2">
                                    {p.keywords.map((kw, i) => (
                                        <span key={i} className="px-3 py-1 bg-indigo-500/10 text-indigo-400 rounded-full text-xs">{kw}</span>
                                    ))}
                                </div>
                                <div className="mt-4 pt-4 border-t border-border/50">
                                    <h4 className="text-xs font-semibold text-foreground mb-2">OG Image</h4>
                                    <div className="aspect-video relative rounded-lg bg-background border border-border flex items-center justify-center overflow-hidden">
                                        <span className="text-[10px] text-slate-500">{p.ogImage}</span>
                                    </div>
                                </div>
                                <button className="w-full mt-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs transition-colors">
                                    Detaylı Analiz Al
                                </button>
                            </motion.div>
                        );
                    })()}

                    <div className="bg-surface rounded-xl border border-border p-5">
                        <h3 className="text-sm font-semibold text-foreground mb-3">SEO İpuçları</h3>
                        <div className="space-y-3">
                            {[
                                { icon: FileText, text: 'Başlıklar 60-70 karakter arası olmalı', color: 'text-blue-400' },
                                { icon: FileText, text: 'Açıklamalar en az 160 karakter olmalı', color: 'text-emerald-400' },
                                { icon: Link, text: 'URL\'ler kısa ve açıklayıcı olmalı', color: 'text-amber-400' },
                                { icon: Eye, text: 'Canonical etiketlerini kontrol edin', color: 'text-indigo-400' },
                                { icon: Search, text: 'Anahtar kelime yoğunluğunu optimize edin', color: 'text-rose-400' },
                            ].map((tip, i) => (
                                <div key={i} className="flex items-start gap-2">
                                    <tip.icon className={`w-4 h-4 mt-0.5 ${tip.color}`} />
                                    <span className="text-xs text-slate-400">{tip.text}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="bg-surface rounded-xl border border-border p-5">
                        <h3 className="text-sm font-semibold text-foreground mb-3">Skor Geçmişi</h3>
                        <div className="space-y-3">
                            {stats.scoreHistory.map((h, i) => (
                                <div key={i} className="flex items-center justify-between">
                                    <span className="text-xs text-slate-400">{h.date}</span>
                                    <div className="flex items-center gap-2">
                                        <div className="w-24 h-1.5 bg-background rounded-full overflow-hidden">
                                            <div className={`h-full ${getScoreBg(h.score)}`} style={{ width: `${h.score}%` }} />
                                        </div>
                                        <span className={`text-xs font-medium ${getScoreColor(h.score)}`}>{h.score}</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Search,
    Target,
    TrendingUp,
    AlertTriangle,
    CheckCircle,
    RefreshCw,
    Download,
    Lightbulb,
    Eye,
    MousePointer,
    ShoppingCart,
    ChevronDown,
    Sparkles,
    Zap
} from 'lucide-react';
import { useSeoAnalysis } from '@/lib/hooks';

export default function SEOPage() {
    const [selectedProduct, setSelectedProduct] = useState<number | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [filterScore, setFilterScore] = useState('all');
    const { analysis: apiSeoData, loading } = useSeoAnalysis();

    const activeProductsData = (Array.isArray(apiSeoData) && apiSeoData.length > 0) ? apiSeoData : [];
    const activeSeoTips = [
        "Başlıklarda ilk 60 karakteri optimize edin - bu alan arama sonuçlarında görünür",
        "En az 5 yüksek kaliteli ürün görseli ekleyin",
        "Ürün açıklamasında anahtar kelimeleri doğal şekilde kullanın",
        "Müşteri sorularını açıklamada yanıtlayın",
        "Teknik özellikleri bullet point olarak listeleyin"
    ];

    const getScoreColor = (score: number) => {
        if (score >= 80) return 'text-green-500';
        if (score >= 60) return 'text-yellow-500';
        return 'text-red-500';
    };

    const getScoreBg = (score: number) => {
        if (score >= 80) return 'bg-green-500';
        if (score >= 60) return 'bg-yellow-500';
        return 'bg-red-500';
    };

    const getImpactBadge = (impact: string) => {
        switch (impact) {
            case 'high':
                return <span className="px-2 py-1 rounded text-[10px] font-bold bg-red-500/10 text-red-500">Yüksek</span>;
            case 'medium':
                return <span className="px-2 py-1 rounded text-[10px] font-bold bg-yellow-500/10 text-yellow-500">Orta</span>;
            default:
                return <span className="px-2 py-1 rounded text-[10px] font-bold bg-blue-500/10 text-blue-500">Düşük</span>;
        }
    };

    const getTypeIcon = (type: string) => {
        switch (type) {
            case 'error':
                return <AlertTriangle size={14} className="text-red-500" />;
            case 'warning':
                return <AlertTriangle size={14} className="text-yellow-500" />;
            default:
                return <Lightbulb size={14} className="text-blue-500" />;
        }
    };

    const averageScore = Math.round(activeProductsData.reduce((sum: number, p: any) => sum + p.score, 0) / activeProductsData.length);
    const totalIssues = activeProductsData.reduce((sum: number, p: any) => sum + p.issues, 0);

    const filteredProducts = activeProductsData.filter((product: any) => {
        const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesScore = filterScore === 'all' ||
            (filterScore === 'good' && product.score >= 80) ||
            (filterScore === 'warning' && product.score >= 60 && product.score < 80) ||
            (filterScore === 'bad' && product.score < 60);
        return matchesSearch && matchesScore;
    });

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="flex flex-col items-center gap-4">
                    <RefreshCw className="w-8 h-8 text-primary animate-spin" />
                    <p className="text-slate-500">SEO verileri yükleniyor...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight">SEO Optimizasyonu</h1>
                    <p className="text-slate-500 font-medium">Ürünlerinizin arama görünürlüğünü artırın</p>
                </div>
                <div className="flex items-center gap-3">
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all">
                        <Download size={16} /> Rapor İndir
                    </button>
                    <button className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl text-sm font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20">
                        <Sparkles size={16} /> Toplu Optimizasyon
                    </button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-primary/10">
                            <Target size={20} className="text-primary" />
                        </div>
                        <div className="flex items-center gap-1 text-xs font-bold text-green-500">
                            <TrendingUp size={12} /> +5
                        </div>
                    </div>
                    <div className={`text-2xl font-black ${getScoreColor(averageScore)}`}>{averageScore}</div>
                    <div className="text-xs text-slate-500 mt-1">Ortalama SEO Skoru</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-red-500/10">
                            <AlertTriangle size={20} className="text-red-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">{totalIssues}</div>
                    <div className="text-xs text-slate-500 mt-1">Kritik Sorun</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-blue-500/10">
                            <Eye size={20} className="text-blue-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">51.2K</div>
                    <div className="text-xs text-slate-500 mt-1">Toplam Görüntüleme</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-green-500/10">
                            <MousePointer size={20} className="text-green-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">%3.4</div>
                    <div className="text-xs text-slate-500 mt-1">Ort. Tıklama Oranı</div>
                </motion.div>
            </div>

            {/* Filters */}
            <div className="bg-surface p-4 rounded-2xl border border-border flex flex-col lg:flex-row gap-4">
                <div className="flex-1 relative">
                    <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                    <input
                        type="text"
                        placeholder="Ürün ara..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full bg-background border border-border rounded-xl py-2.5 pl-10 pr-4 text-sm text-foreground placeholder:text-slate-500 focus:outline-none focus:border-primary/50"
                    />
                </div>
                <div className="flex gap-2">
                    {[
                        { id: 'all', label: 'Tümü' },
                        { id: 'bad', label: 'Kritik', color: 'text-red-500' },
                        { id: 'warning', label: 'Uyarı', color: 'text-yellow-500' },
                        { id: 'good', label: 'İyi', color: 'text-green-500' }
                    ].map(filter => (
                        <button
                            key={filter.id}
                            onClick={() => setFilterScore(filter.id)}
                            className={`px-4 py-2.5 rounded-xl text-sm font-medium transition-all ${filterScore === filter.id
                                    ? 'bg-primary text-white'
                                    : 'bg-background border border-border text-foreground hover:bg-surface'
                                }`}
                        >
                            {filter.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Products List */}
                <div className="lg:col-span-2 space-y-4">
                    {filteredProducts.map((product: any, idx: number) => (
                        <motion.div
                            key={product.id}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: idx * 0.05 }}
                            className={`bg-surface rounded-2xl border ${selectedProduct === product.id ? 'border-primary/50' : 'border-border'
                                } overflow-hidden cursor-pointer hover:border-primary/30 transition-all`}
                            onClick={() => setSelectedProduct(selectedProduct === product.id ? null : product.id)}
                        >
                            <div className="p-5">
                                <div className="flex items-start justify-between mb-4">
                                    <div className="flex-1">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="text-xs font-bold px-2 py-0.5 rounded bg-background border border-border text-slate-500">
                                                {product.platform}
                                            </span>
                                            {product.issues > 0 && (
                                                <span className="text-xs font-bold px-2 py-0.5 rounded bg-red-500/10 border border-red-500/20 text-red-500">
                                                    {product.issues} sorun
                                                </span>
                                            )}
                                        </div>
                                        <h3 className="font-bold text-foreground line-clamp-1">{product.name}</h3>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <div className={`text-2xl font-black ${getScoreColor(product.score)}`}>
                                            {product.score}
                                        </div>
                                        <ChevronDown
                                            size={16}
                                            className={`text-slate-400 transition-transform ${selectedProduct === product.id ? 'rotate-180' : ''}`}
                                        />
                                    </div>
                                </div>

                                <div className="h-2 bg-background rounded-full overflow-hidden mb-4">
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${product.score}%` }}
                                        transition={{ delay: idx * 0.1, duration: 0.5 }}
                                        className={`h-full ${getScoreBg(product.score)}`}
                                    />
                                </div>

                                <div className="flex items-center gap-6 text-sm">
                                    <div className="flex items-center gap-1">
                                        <Eye size={14} className="text-slate-400" />
                                        <span className="text-slate-500">{product.views.toLocaleString('tr-TR')}</span>
                                    </div>
                                    <div className="flex items-center gap-1">
                                        <MousePointer size={14} className="text-slate-400" />
                                        <span className="text-slate-500">%{product.ctr}</span>
                                    </div>
                                    <div className="flex items-center gap-1">
                                        <ShoppingCart size={14} className="text-slate-400" />
                                        <span className="text-slate-500">%{product.conversion}</span>
                                    </div>
                                </div>
                            </div>

                            <AnimatePresence>
                                {selectedProduct === product.id && product.improvements.length > 0 && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: 'auto', opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        className="border-t border-border"
                                    >
                                        <div className="p-5 space-y-3">
                                            <h4 className="text-xs font-black text-slate-500 uppercase tracking-wider">İyileştirme Önerileri</h4>
                                            {product.improvements.map((improvement: any, i: number) => (
                                                <div key={i} className="flex items-start gap-3 p-3 bg-background rounded-xl">
                                                    {getTypeIcon(improvement.type)}
                                                    <div className="flex-1">
                                                        <p className="text-sm text-foreground">{improvement.message}</p>
                                                    </div>
                                                    {getImpactBadge(improvement.impact)}
                                                </div>
                                            ))}
                                            <button className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl text-sm font-bold hover:bg-primary/90 transition-all">
                                                <Zap size={14} /> AI ile Otomatik Düzelt
                                            </button>
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    ))}
                </div>

                {/* SEO Tips */}
                <div className="space-y-4">
                    <div className="bg-gradient-to-br from-primary/10 to-purple-500/5 rounded-2xl border border-primary/20 p-5">
                        <div className="flex items-center gap-2 mb-4">
                            <Sparkles size={18} className="text-primary" />
                            <h3 className="font-bold text-foreground">SEO İpuçları</h3>
                        </div>
                        <div className="space-y-3">
                            {activeSeoTips.map((tip: string, idx: number) => (
                                <motion.div
                                    key={idx}
                                    initial={{ opacity: 0, x: 20 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: idx * 0.1 }}
                                    className="flex items-start gap-2 text-sm"
                                >
                                    <CheckCircle size={14} className="text-green-500 mt-0.5 shrink-0" />
                                    <span className="text-slate-500">{tip}</span>
                                </motion.div>
                            ))}
                        </div>
                    </div>

                    <div className="bg-surface rounded-2xl border border-border p-5">
                        <h3 className="font-bold text-foreground mb-4">Skor Dağılımı</h3>
                        <div className="space-y-3">
                            {[
                                { label: 'Mükemmel (80+)', count: activeProductsData.filter((p: any) => p.score >= 80).length, color: 'bg-green-500' },
                                { label: 'İyi (60-79)', count: activeProductsData.filter((p: any) => p.score >= 60 && p.score < 80).length, color: 'bg-yellow-500' },
                                { label: 'Kötü (0-59)', count: activeProductsData.filter((p: any) => p.score < 60).length, color: 'bg-red-500' }
                            ].map(item => (
                                <div key={item.label} className="flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <div className={`w-3 h-3 rounded ${item.color}`} />
                                        <span className="text-sm text-slate-500">{item.label}</span>
                                    </div>
                                    <span className="text-sm font-bold text-foreground">{item.count}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useCallback } from 'react';
