                                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${cfg.bg} ${cfg.color} border ${cfg.bg.replace('bg-', 'border-').replace('/10', '/30')}`}>
