export default function StoresPage() {
    const { stores, loading, error, fetchStores, connectStore, disconnectStore, syncStore } = useStores();

    const [syncingStoreId, setSyncingStoreId] = useState<string | null>(null);
    const [confirmDialog, setConfirmDialog] = useState<{ type: 'connect' | 'disconnect'; storeId: string; platform: string } | null>(null);
    const [settingsPanelId, setSettingsPanelId] = useState<string | null>(null);

    const displayStores = stores;

    const connectedStores = displayStores.filter(s => s.status === 'connected');
    const totalRevenue = displayStores.reduce((sum, s) => sum + s.revenue, 0);
    const totalProducts = displayStores.reduce((sum, s) => sum + s.totalProducts, 0);
    const totalOrders = displayStores.reduce((sum, s) => sum + s.totalOrders, 0);

    // Sync handler with progress
    const handleSync = useCallback(async (storeId: string) => {
        setSyncingStoreId(storeId);
        try {
            await syncStore(storeId);
            await fetchStores();
        } catch {
            // error handled by hook
        } finally {
            setSyncingStoreId(null);
        }
    }, [syncStore, fetchStores]);

    // Sync all connected stores
    const handleSyncAll = useCallback(async () => {
        for (const s of connectedStores) {
            await handleSync(s.id);
        }
    }, [connectedStores, handleSync]);

    // Confirm connect
    const handleConfirmConnect = useCallback(async () => {
        if (!confirmDialog || confirmDialog.type !== 'connect') return;
        await connectStore(confirmDialog.platform, {});
        setConfirmDialog(null);
    }, [confirmDialog, connectStore]);

    // Confirm disconnect
    const handleConfirmDisconnect = useCallback(async () => {
        if (!confirmDialog || confirmDialog.type !== 'disconnect') return;
        await disconnectStore(confirmDialog.storeId);
        setConfirmDialog(null);
    }, [confirmDialog, disconnectStore]);

    const getStatusBadge = (status: Store['status']) => {
        switch (status) {
            case 'connected':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-green-500/10 text-green-500 border border-green-500/20">
                        <CheckCircle size={10} /> Bağlı
                    </span>
                );
            case 'syncing':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-blue-500/10 text-blue-500 border border-blue-500/20 animate-pulse">
                        <Loader2 size={10} className="animate-spin" /> Senkronize Ediliyor
                    </span>
                );
            case 'error':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-red-500/10 text-red-500 border border-red-500/20">
                        <AlertTriangle size={10} /> Hata
                    </span>
                );
            default:
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-slate-500/10 text-slate-500 border border-slate-500/20">
                        <XCircle size={10} /> Bağlı Değil
                    </span>
                );
        }
    };

    // Loading state
    if (loading && stores.length === 0) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="text-center space-y-4">
                    <Loader2 size={40} className="animate-spin text-primary mx-auto" />
                    <div className="text-lg font-bold text-foreground">Mağazalar yükleniyor...</div>
                    <p className="text-sm text-slate-500">Pazaryeri bağlantıları kontrol ediliyor</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Confirm Dialog */}
            <AnimatePresence>
                {confirmDialog && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm"
                        onClick={() => setConfirmDialog(null)}
                    >
                        <motion.div
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.9, opacity: 0 }}
                            onClick={e => e.stopPropagation()}
                            className="bg-surface border border-border rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl"
                        >
                            <div className="flex items-center justify-between mb-4">
                                <h3 className="text-lg font-bold text-foreground">
                                    {confirmDialog.type === 'connect' ? 'Pazaryeri Bağla' : 'Bağlantıyı Kes'}
                                </h3>
                                <button onClick={() => setConfirmDialog(null)} className="p-1 rounded-lg hover:bg-background text-slate-400">
                                    <X size={18} />
                                </button>
                            </div>
                            <div className="flex items-center gap-3 mb-6">
                                <div className={`w-10 h-10 rounded-xl ${getPlatformVisuals(confirmDialog.platform).color} flex items-center justify-center`}>
                                    <span className="text-white font-black">
                                        {(platformDisplayName[confirmDialog.platform] ?? confirmDialog.platform)[0]}
                                    </span>
                                </div>
                                <div>
                                    <div className="font-bold text-foreground">{platformDisplayName[confirmDialog.platform] ?? confirmDialog.platform}</div>
                                    <div className="text-xs text-slate-500">
                                        {confirmDialog.type === 'connect'
                                            ? 'Bu pazaryerine bağlanmak istediğinizden emin misiniz?'
                                            : 'Bu mağazanın bağlantısını kesmek istediğinizden emin misiniz?'}
                                    </div>
                                </div>
                            </div>
                            {confirmDialog.type === 'disconnect' && (
                                <div className="bg-red-500/5 border border-red-500/20 rounded-xl p-3 mb-4 text-xs text-red-500">
                                    <AlertTriangle size={12} className="inline mr-1" />
                                    Bağlantı kesildiğinde senkronizasyon duracak ve bekleyen siparişler etkilenebilir.
                                </div>
                            )}
                            <div className="flex items-center gap-3">
                                <button
                                    onClick={() => setConfirmDialog(null)}
                                    className="flex-1 px-4 py-2.5 bg-background border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface transition-all"
                                >
                                    İptal
                                </button>
                                <button
                                    onClick={confirmDialog.type === 'connect' ? handleConfirmConnect : handleConfirmDisconnect}
                                    className={`flex-1 px-4 py-2.5 rounded-xl text-sm font-bold text-white transition-all ${
                                        confirmDialog.type === 'connect'
                                            ? 'bg-primary hover:bg-primary/90'
                                            : 'bg-red-500 hover:bg-red-600'
                                    }`}
                                >
                                    {loading ? <Loader2 size={16} className="animate-spin mx-auto" /> : confirmDialog.type === 'connect' ? 'Bağla' : 'Bağlantıyı Kes'}
                                </button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Header */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-foreground tracking-tight">Mağazalarım</h1>
                    <p className="text-slate-500 font-medium">Bağlı pazaryerlerini ve performanslarını yönetin</p>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={handleSyncAll}
                        disabled={!!syncingStoreId || connectedStores.length === 0}
                        className="flex items-center gap-2 px-4 py-2.5 bg-surface border border-border rounded-xl text-sm font-bold text-foreground hover:bg-surface/80 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        <RefreshCw size={16} className={syncingStoreId ? 'animate-spin' : ''} /> Tümünü Senkronize Et
                    </button>
                    <button
                        onClick={() => setConfirmDialog({ type: 'connect', storeId: '', platform: 'trendyol' })}
                        className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl text-sm font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20"
                    >
                        <Plus size={16} /> Pazaryeri Bağla
                    </button>
                </div>
            </div>

            {/* Summary Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-gradient-to-br from-primary/10 to-purple-500/5 p-6 rounded-2xl border border-primary/20"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-primary/10">
                            <StoreIcon size={20} className="text-primary" />
                        </div>
                        <span className="text-xs font-bold text-primary">{connectedStores.length} Aktif</span>
                    </div>
                    <div className="text-2xl font-black text-foreground">{displayStores.length}</div>
                    <div className="text-xs text-slate-500 mt-1">Toplam Mağaza</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-green-500/10">
                            <PlugZap size={20} className="text-green-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">{connectedStores.length}</div>
                    <div className="text-xs text-slate-500 mt-1">Aktif Entegrasyon</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-blue-500/10">
                            <Package size={20} className="text-blue-500" />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">{totalProducts.toLocaleString('tr-TR')}</div>
                    <div className="text-xs text-slate-500 mt-1">Senkronize Edilen Ürün</div>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-surface p-6 rounded-2xl border border-border"
                >
                    <div className="flex items-center justify-between mb-3">
                        <div className="p-2.5 rounded-xl bg-green-500/10">
                            <DollarSign size={20} className="text-green-500" />
                        </div>
                        <div className="flex items-center gap-1 text-xs font-bold text-green-500">
                            <TrendingUp size={12} />
                        </div>
                    </div>
                    <div className="text-2xl font-black text-foreground">₺{(totalRevenue / 1000).toFixed(0)}K</div>
                    <div className="text-xs text-slate-500 mt-1">Toplam Ciro</div>
                </motion.div>
            </div>

            {/* Platform Cards */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {displayStores.map((store, idx) => {
                    const visuals = getPlatformVisuals(store.platform);
                    const isSyncing = syncingStoreId === store.id || store.status === 'syncing';
                    const isSettingsOpen = settingsPanelId === store.id;

                    return (
                        <motion.div
                            key={store.id}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: idx * 0.08 }}
                            className={`bg-surface rounded-2xl border ${
                                store.status === 'connected' ? 'border-border' :
                                store.status === 'syncing' ? 'border-blue-500/30' :
                                store.status === 'error' ? 'border-red-500/20' : 'border-dashed border-slate-600'
                            } overflow-hidden`}
                        >
                            {/* Platform Header */}
                            <div className="p-5 border-b border-border">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-12 h-12 rounded-xl ${visuals.color} flex items-center justify-center relative overflow-hidden`}>
                                            <span className="text-white text-lg font-black">
                                                {(platformDisplayName[store.platform] ?? store.platform)[0]}
                                            </span>
                                            {isSyncing && (
                                                <div className="absolute inset-0 bg-white/20 animate-pulse" />
                                            )}
                                        </div>
                                        <div>
                                            <div className="font-bold text-foreground">
                                                {platformDisplayName[store.platform] ?? store.platform}
                                            </div>
                                            <div className="text-xs text-slate-500">{store.storeName}</div>
                                            <div className="text-[10px] text-slate-400 flex items-center gap-1 mt-0.5">
                                                <Clock size={9} /> {store.lastSync}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {getStatusBadge(isSyncing ? 'syncing' : store.status)}
                                        {(store.status === 'connected' || store.status === 'syncing') && (
                                            <button
                                                onClick={() => handleSync(store.id)}
                                                disabled={isSyncing}
                                                className="p-2 rounded-lg hover:bg-background text-slate-400 hover:text-foreground transition-all disabled:opacity-50"
                                            >
                                                <RefreshCw size={14} className={isSyncing ? 'animate-spin' : ''} />
                                            </button>
                                        )}
                                    </div>
                                </div>
                                {/* Sync progress bar */}
                                {isSyncing && syncingStoreId === store.id && (
                                    <div className="mt-3">
                                        <div className="flex items-center justify-between text-[10px] text-blue-500 mb-1">
                                            <span>Senkronize ediliyor...</span>
                                        </div>
                                        <div className="w-full h-1.5 bg-blue-500/10 rounded-full overflow-hidden">
                                            <motion.div
                                                className="h-full w-1/3 bg-blue-500 rounded-full"
                                                initial={{ x: '-100%' }}
                                                animate={{ x: '100%' }}
                                                transition={{ duration: 1.1, repeat: Infinity, ease: 'linear' }}
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Platform Body */}
                            {store.status === 'connected' || store.status === 'syncing' ? (
                                <div className="p-5">
                                    {/* Stats Grid */}
                                    <div className="grid grid-cols-3 gap-3 mb-4">
                                        <div className="bg-background p-3 rounded-xl">
                                            <div className="text-[10px] text-slate-500 mb-1">Ciro</div>
                                            <div className="text-sm font-black text-foreground">
                                                ₺{store.revenue >= 1000 ? `${(store.revenue / 1000).toFixed(0)}K` : store.revenue}
                                            </div>
                                        </div>
                                        <div className="bg-background p-3 rounded-xl">
                                            <div className="text-[10px] text-slate-500 mb-1">Ürün</div>
                                            <div className="text-sm font-black text-foreground">{store.totalProducts.toLocaleString('tr-TR')}</div>
                                        </div>
                                        <div className="bg-background p-3 rounded-xl">
                                            <div className="text-[10px] text-slate-500 mb-1">Sipariş</div>
                                            <div className="text-sm font-black text-foreground">{store.totalOrders}</div>
                                        </div>
                                    </div>

                                    {/* Rating */}
                                    {store.rating > 0 && (
                                        <div className="flex items-center gap-2 mb-4 text-sm">
                                            <span className="text-yellow-500">★</span>
                                            <span className="font-bold text-foreground">{store.rating}</span>
                                            <span className="text-slate-500">puan</span>
                                        </div>
                                    )}

                                    {/* Action Buttons */}
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => setSettingsPanelId(isSettingsOpen ? null : store.id)}
                                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-background border border-border rounded-lg text-xs font-bold text-foreground hover:bg-surface transition-all"
                                        >
                                            <Settings size={14} /> Ayarlar {isSettingsOpen ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
                                        </button>
                                        <button
                                            onClick={() => setConfirmDialog({ type: 'disconnect', storeId: store.id, platform: store.platform })}
                                            className="flex items-center justify-center gap-2 px-3 py-2 bg-red-500/5 border border-red-500/20 rounded-lg text-xs font-bold text-red-500 hover:bg-red-500/10 transition-all"
                                        >
                                            <WifiOff size={14} /> Kes
                                        </button>
                                        <button className="flex items-center justify-center gap-2 px-3 py-2 bg-background border border-border rounded-lg text-xs font-bold text-foreground hover:bg-surface transition-all">
                                            <ExternalLink size={14} />
                                        </button>
                                    </div>

                                    {/* Settings Panel */}
                                    <AnimatePresence>
                                        {isSettingsOpen && (
                                            <motion.div
                                                initial={{ height: 0, opacity: 0 }}
                                                animate={{ height: 'auto', opacity: 1 }}
                                                exit={{ height: 0, opacity: 0 }}
                                                transition={{ duration: 0.2 }}
                                                className="overflow-hidden"
                                            >
                                                <div className="mt-4 bg-background rounded-xl p-4 space-y-3 border border-border">
                                                    <h4 className="text-xs font-bold text-foreground flex items-center gap-2">
                                                        <Settings size={12} /> Mağaza Ayarları
                                                    </h4>
                                                    <div className="space-y-2">
                                                        <div className="flex items-center justify-between">
                                                            <span className="text-xs text-slate-500">Mağaza Adı</span>
                                                            <span className="text-xs font-medium text-foreground">{store.storeName}</span>
                                                        </div>
                                                        <div className="flex items-center justify-between">
                                                            <span className="text-xs text-slate-500">Platform</span>
                                                            <span className="text-xs font-medium text-foreground">{platformDisplayName[store.platform] ?? store.platform}</span>
                                                        </div>
                                                        <div className="flex items-center justify-between">
                                                            <span className="text-xs text-slate-500">Durum</span>
                                                            <span className="text-xs font-medium text-green-500">Aktif</span>
                                                        </div>
                                                        <div className="flex items-center justify-between">
                                                            <span className="text-xs text-slate-500">Son Senkronizasyon</span>
                                                            <span className="text-xs font-medium text-foreground">{store.lastSync}</span>
                                                        </div>
                                                        <div className="flex items-center justify-between">
                                                            <span className="text-xs text-slate-500">Otomatik Senkronizasyon</span>
                                                            <div className="w-8 h-4 bg-green-500 rounded-full relative cursor-pointer">
                                                                <div className="w-3 h-3 bg-white rounded-full absolute right-0.5 top-0.5" />
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <button
                                                        onClick={() => handleSync(store.id)}
                                                        disabled={isSyncing}
                                                        className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-primary/10 border border-primary/20 rounded-lg text-xs font-bold text-primary hover:bg-primary/20 transition-all disabled:opacity-50"
                                                    >
                                                        <RefreshCw size={12} className={isSyncing ? 'animate-spin' : ''} /> Şimdi Senkronize Et
                                                    </button>
                                                </div>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>
                            ) : store.status === 'error' ? (
                                <div className="p-5">
                                    <div className="bg-red-500/5 border border-red-500/20 rounded-xl p-4 mb-4">
                                        <div className="flex items-start gap-3">
                                            <AlertTriangle size={16} className="text-red-500 mt-0.5" />
                                            <div>
                                                <div className="text-sm font-bold text-red-500">Bağlantı Hatası</div>
                                                <div className="text-xs text-red-500/70">API yanıt vermiyor. Kimlik bilgilerinizi kontrol edin.</div>
                                            </div>
                                        </div>
                                    </div>
                                    {/* Stats even in error state */}
                                    {store.totalProducts > 0 && (
                                        <div className="grid grid-cols-2 gap-3 mb-4">
                                            <div className="bg-background p-3 rounded-xl">
                                                <div className="text-[10px] text-slate-500 mb-1">Son Bilinen Ürün</div>
                                                <div className="text-sm font-black text-foreground">{store.totalProducts}</div>
                                            </div>
                                            <div className="bg-background p-3 rounded-xl">
                                                <div className="text-[10px] text-slate-500 mb-1">Son Bilinen Ciro</div>
                                                <div className="text-sm font-black text-foreground">₺{(store.revenue / 1000).toFixed(0)}K</div>
                                            </div>
                                        </div>
                                    )}
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => handleSync(store.id)}
                                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-red-500/10 border border-red-500/20 rounded-lg text-xs font-bold text-red-500 hover:bg-red-500/20 transition-all"
                                        >
                                            <RefreshCw size={14} /> Yeniden Dene
                                        </button>
                                        <button
                                            onClick={() => setConfirmDialog({ type: 'disconnect', storeId: store.id, platform: store.platform })}
                                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-background border border-border rounded-lg text-xs font-bold text-foreground hover:bg-surface transition-all"
                                        >
                                            <WifiOff size={14} /> Bağlantıyı Kes
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <div className="p-5">
                                    <div className="text-center py-4">
                                        <div className={`w-12 h-12 rounded-xl ${visuals.bgColor} flex items-center justify-center mx-auto mb-3`}>
                                            <Unlink size={20} className={visuals.textColor} />
                                        </div>
                                        <div className="text-sm text-slate-500 mb-4">Bu pazaryerine henüz bağlı değilsiniz</div>
                                        <button
                                            onClick={() => setConfirmDialog({ type: 'connect', storeId: store.id, platform: store.platform })}
                                            className={`flex items-center justify-center gap-2 px-4 py-2 ${visuals.color} text-white rounded-lg text-sm font-bold hover:opacity-90 transition-all mx-auto`}
                                        >
                                            <LinkIcon size={14} /> Hemen Bağla
                                        </button>
                                    </div>
                                </div>
                            )}
                        </motion.div>
                    );
                })}
            </div>

            {/* Connect More Platforms */}
            <div className="bg-gradient-to-br from-primary/5 to-purple-500/5 rounded-2xl border border-primary/20 p-6">
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                        <div className="p-3 rounded-xl bg-primary/10">
                            <Zap size={24} className="text-primary" />
                        </div>
                        <div>
                            <h3 className="font-bold text-foreground">Daha Fazla Pazaryeri Bağlayın</h3>
                            <p className="text-sm text-slate-500">Satışlarınızı artırmak için yeni pazaryerlerini entegre edin</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        {Object.entries(platformConfig).map(([key, cfg]) => (
                            <div
                                key={key}
                                onClick={() => setConfirmDialog({ type: 'connect', storeId: '', platform: key })}
                                className={`w-12 h-12 rounded-xl bg-surface border border-border flex items-center justify-center hover:${cfg.borderColor} cursor-pointer transition-all group`}
                            >
                                <span className={`text-slate-500 group-hover:${cfg.textColor} font-bold`}>
                                    {(platformDisplayName[key] ?? key)[0]}
                                </span>
                            </div>
                        ))}
                        <button className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl text-sm font-bold hover:bg-primary/90 transition-all">
                            Tümünü Gör <ChevronRight size={14} />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    Truck, Plus, Search, Star, Phone, Mail, Globe, MapPin,
    Edit, Trash2, Eye, Package, TrendingUp, Clock, AlertTriangle,
    CheckCircle, XCircle, MoreVertical, Filter, Download
} from 'lucide-react';

interface Supplier {
    id: string;
    name: string;
    contactPerson: string;
    email: string;
    phone: string;
    city: string;
    rating: number;
    totalProducts: number;
    avgDeliveryDays: number;
    status: 'active' | 'inactive' | 'pending';
    totalOrders: number;
    lastOrderDate: string;
    paymentTerms: string;
}

import { useSuppliers, SupplierData } from '@/lib/hooks';

export default function SuppliersPage() {
    const { data: suppliersData, loading: isLoading } = useSuppliers();
    const suppliers = (suppliersData || []) as SupplierData[];
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [showAddModal, setShowAddModal] = useState(false);
    const [selectedSupplier, setSelectedSupplier] = useState<SupplierData | null>(null);

    const filtered = suppliers.filter((s) => {
        if (search && !s.name.toLowerCase().includes(search.toLowerCase()) && !s.contact.toLowerCase().includes(search.toLowerCase())) return false;
        if (statusFilter !== 'all' && s.status !== statusFilter) return false;
        return true;
    });

    const stats = {
        total: suppliers.length,
        active: suppliers.filter(s => s.status === 'active').length,
        avgRating: suppliers.length > 0
            ? (suppliers.reduce((s, sup) => s + sup.rating, 0) / suppliers.length).toFixed(1)
            : '0.0',
        totalProducts: suppliers.reduce((s, sup) => s + sup.activeProducts, 0),
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <Truck className="w-8 h-8 text-orange-500" /> Tedarikçi Yönetimi
                    </h1>
                    <p className="text-slate-500 mt-1">Tedarikçilerinizi yönetin ve performanslarını takip edin</p>
                </div>
                <button onClick={() => setShowAddModal(true)} className="flex items-center gap-2 px-4 py-2 bg-orange-600 hover:bg-orange-700 text-white rounded-xl text-sm font-medium transition-colors">
                    <Plus className="w-4 h-4" /> Tedarikçi Ekle
                </button>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Toplam Tedarikçi', value: stats.total, icon: Truck, color: 'orange' },
                    { label: 'Aktif', value: stats.active, icon: CheckCircle, color: 'emerald' },
                    { label: 'Ort. Puan', value: stats.avgRating, icon: Star, color: 'yellow' },
                    { label: 'Toplam Ürün', value: stats.totalProducts, icon: Package, color: 'blue' },
                ].map((stat, i) => (
                    <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.1 }}
                        className="bg-surface rounded-2xl border border-border p-5">
                        <stat.icon className={`w-5 h-5 text-${stat.color}-500 mb-2`} />
                        <div className="text-2xl font-bold text-foreground">{stat.value}</div>
                        <div className="text-xs text-slate-500">{stat.label}</div>
                    </motion.div>
                ))}
            </div>

            {/* Filters */}
            <div className="flex items-center gap-3">
                <div className="relative flex-1 max-w-md">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input type="text" placeholder="Tedarikçi ara..." value={search} onChange={e => setSearch(e.target.value)}
                        className="w-full pl-9 pr-4 py-2.5 bg-surface rounded-xl text-sm text-foreground placeholder:text-slate-500 border border-border focus:border-orange-500 focus:outline-none" />
                </div>
                <div className="flex gap-1 bg-surface border border-border rounded-xl p-1">
                    {['all', 'active', 'inactive'].map(f => (
                        <button key={f} onClick={() => setStatusFilter(f)}
                            className={`px-3 py-1.5 text-xs rounded-lg transition-all ${statusFilter === f ? 'bg-orange-500/20 text-orange-400' : 'text-slate-500 hover:text-foreground'}`}>
                            {f === 'all' ? 'Tümü' : f === 'active' ? 'Aktif' : 'Pasif'}
                        </button>
                    ))}
                </div>
            </div>

            {/* Suppliers Table */}
            <div className="bg-surface rounded-2xl border border-border overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead>
                            <tr className="border-b border-border">
                                <th className="text-left p-4 text-xs font-medium text-slate-500">Tedarikçi</th>
                                <th className="text-left p-4 text-xs font-medium text-slate-500">İletişim</th>
                                <th className="text-center p-4 text-xs font-medium text-slate-500">Puan</th>
                                <th className="text-center p-4 text-xs font-medium text-slate-500">Ürün</th>
                                <th className="text-center p-4 text-xs font-medium text-slate-500">Son Sipariş</th>
                                <th className="text-center p-4 text-xs font-medium text-slate-500">Durum</th>
                                <th className="text-right p-4 text-xs font-medium text-slate-500">İşlem</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filtered.map(s => (
                                <tr key={s.id} className="border-b border-border/50 hover:bg-background/50 transition-colors">
                                    <td className="p-4">
                                        <div className="font-medium text-foreground">{s.name}</div>
                                        <div className="text-xs text-slate-500 flex items-center gap-1"><MapPin className="w-3 h-3" /> Bilinmiyor</div>
                                    </td>
                                    <td className="p-4">
                                        <div className="text-foreground text-xs">{s.contact}</div>
                                        <div className="text-slate-500 text-xs">{s.email}</div>
                                    </td>
                                    <td className="p-4 text-center">
                                        <div className="flex items-center justify-center gap-1">
                                            <Star className="w-3.5 h-3.5 text-yellow-500 fill-yellow-500" />
                                            <span className="text-foreground font-medium">{s.rating}</span>
                                        </div>
                                    </td>
                                    <td className="p-4 text-center text-foreground">{s.activeProducts}</td>
                                    <td className="p-4 text-center text-foreground">{s.lastOrder}</td>
                                    <td className="p-4 text-center">
                                        <span className={`px-2 py-1 text-xs rounded-full ${s.status === 'active' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                                            {s.status === 'active' ? 'Aktif' : 'Pasif'}
                                        </span>
                                    </td>
                                    <td className="p-4 text-right">
                                        <div className="flex items-center justify-end gap-1">
                                            <button onClick={() => setSelectedSupplier(s)} className="p-1.5 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><Eye className="w-4 h-4" /></button>
                                            <button className="p-1.5 hover:bg-background rounded-lg text-slate-400 hover:text-foreground"><Edit className="w-4 h-4" /></button>
                                            <button className="p-1.5 hover:bg-background rounded-lg text-slate-400 hover:text-red-400"><Trash2 className="w-4 h-4" /></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {filtered.length === 0 && !isLoading && (
                                <tr>
                                    <td colSpan={7} className="p-10 text-center text-slate-500">
                                        Tedarikçi bulunamadı.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Supplier Detail Modal */}
            {selectedSupplier && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setSelectedSupplier(null)}>
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl w-full max-w-lg border border-border p-6" onClick={e => e.stopPropagation()}>
                        <h3 className="text-xl font-bold text-foreground mb-4">{selectedSupplier.name}</h3>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">İletişim</div><div className="text-sm text-foreground mt-1">{selectedSupplier.contact}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Telefon</div><div className="text-sm text-foreground mt-1">{selectedSupplier.phone}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">E-posta</div><div className="text-sm text-foreground mt-1">{selectedSupplier.email}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Şehir</div><div className="text-sm text-foreground mt-1 text-slate-500">Bilinmiyor</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Aktif Ürünler</div><div className="text-sm text-foreground mt-1">{selectedSupplier.activeProducts}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Son Sipariş</div><div className="text-sm text-foreground mt-1">{selectedSupplier.lastOrder}</div></div>
                            <div className="p-3 bg-background rounded-xl"><div className="text-xs text-slate-500">Puan</div><div className="text-sm text-foreground mt-1 flex items-center gap-1"><Star className="w-4 h-4 text-yellow-500 fill-yellow-500" />{selectedSupplier.rating}</div></div>
                        </div>
                        <button onClick={() => setSelectedSupplier(null)} className="mt-4 w-full py-2 bg-background text-foreground rounded-xl text-sm font-medium hover:bg-background/80">Kapat</button>
                    </motion.div>
                </div>
            )}

            {/* Add Modal */}
            {showAddModal && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowAddModal(false)}>
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl w-full max-w-lg border border-border p-6" onClick={e => e.stopPropagation()}>
                        <h3 className="text-xl font-bold text-foreground mb-4">Yeni Tedarikçi Ekle</h3>
                        <div className="space-y-3">
                            {['Firma Adı', 'İletişim Kişisi', 'E-posta', 'Telefon', 'Şehir'].map(field => (
                                <input key={field} placeholder={field}
                                    className="w-full px-4 py-2.5 bg-background rounded-xl text-sm text-foreground placeholder:text-slate-500 border border-border focus:border-orange-500 focus:outline-none" />
                            ))}
                        </div>
                        <div className="flex gap-3 mt-4">
                            <button onClick={() => setShowAddModal(false)} className="flex-1 py-2 bg-background text-foreground rounded-xl text-sm font-medium">İptal</button>
                            <button onClick={() => setShowAddModal(false)} className="flex-1 py-2 bg-orange-600 text-white rounded-xl text-sm font-medium">Kaydet</button>
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import {
    Search,
    Filter,
    MessageSquare,
    Clock,
    CheckCircle2,
    AlertCircle,
    User,
    Send,
    Bot,
    MoreVertical,
    Paperclip,
    ExternalLink,
    ChevronRight,
    Sparkles,
    Plus,
    X
} from "lucide-react";
import { useSupport } from "@/lib/hooks";
import { format } from "date-fns";
import { tr } from "date-fns/locale";
import { motion, AnimatePresence } from "framer-motion";

interface SupportMessage {
    id?: string;
    content: string;
    senderType: 'AGENT' | 'CUSTOMER';
    createdAt: string;
    aiSuggestion?: string;
}

interface SupportTicket {
    id: string;
    subject: string;
    customerName: string;
    status: 'OPEN' | 'PENDING' | 'RESOLVED';
    platform: string;
    updatedAt: string;
    orderId?: string;
    messages?: SupportMessage[];
}

export default function SupportHub() {
    const { getTickets, getTicketDetails, sendMessage, createTicket, loading } = useSupport();
    const [tickets, setTickets] = useState<SupportTicket[]>([]);
    const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
    const [messages, setMessages] = useState<SupportMessage[]>([]);
    const [newMessage, setNewMessage] = useState("");
    const [searchQuery, setSearchQuery] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");
    const [isCreatingTicket, setIsCreatingTicket] = useState(false);
    const [newTicketForm, setNewTicketForm] = useState({ subject: '', platform: 'TRENDYOL', message: '' });

    const loadTicketDetails = async (id: string) => {
        const response = await getTicketDetails(id) as SupportTicket;
        if (response) {
            setSelectedTicket(response);
            setMessages(response.messages || []);
        }
    };

    const loadTickets = async () => {
        const response = await getTickets() as SupportTicket[];
        if (response) {
            setTickets(response);
            if (response.length > 0 && !selectedTicket) {
                loadTicketDetails(response[0].id);
            }
        }
    };

    useEffect(() => {
        loadTickets();
    }, []);

    // load functions hoisted above

    const handleSendMessage = async () => {
        if (!newMessage.trim() || !selectedTicket) return;

        const content = newMessage;
        setNewMessage("");

        const response = await sendMessage({
            ticketId: selectedTicket.id,
            content,
            senderType: "AGENT"
        }) as SupportMessage;

        if (response) {
            setMessages(prev => [...prev, response]);
        }
    };

    const handleCreateTicket = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newTicketForm.subject.trim() || !newTicketForm.message.trim()) return;

        const response = await createTicket({
            subject: newTicketForm.subject,
            platform: newTicketForm.platform,
            message: newTicketForm.message
        });

        if (response) {
            setIsCreatingTicket(false);
            setNewTicketForm({ subject: '', platform: 'TRENDYOL', message: '' });
            loadTickets(); // Refresh tickets and select the new one
        }
    };

    const filteredTickets = tickets.filter(t => {
        const matchesSearch = t.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
            t.customerName?.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesStatus = statusFilter === "all" || t.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const getStatusIcon = (status: string) => {
        switch (status) {
            case "OPEN": return <Clock size={14} className="text-blue-500" />;
            case "PENDING": return <AlertCircle size={14} className="text-yellow-500" />;
            case "RESOLVED": return <CheckCircle2 size={14} className="text-green-500" />;
            default: return <Clock size={14} />;
        }
    };

    return (
        <div className="flex h-[calc(100vh-8rem)] bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-2xl">
            {/* Sidebar: Ticket List */}
            <div className="w-96 border-r border-slate-200 dark:border-slate-800 flex flex-col bg-slate-50/50 dark:bg-slate-900/50">
                <div className="p-6 space-y-4">
                    <div className="flex items-center justify-between">
                        <h1 className="text-xl font-black text-slate-900 dark:text-white flex items-center gap-2">
                            <MessageSquare className="text-orange-600" /> Destek Merkezi
                        </h1>
                        <button
                            onClick={() => setIsCreatingTicket(true)}
                            className="p-2 bg-orange-600 hover:bg-orange-500 text-white rounded-xl shadow-lg shadow-orange-600/20 transition-all focus:outline-none focus:ring-2 focus:ring-orange-500/50"
                            title="Yeni Talep Oluştur"
                        >
                            <Plus size={18} />
                        </button>
                    </div>

                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input
                            type="text"
                            placeholder="Mesajlarda ara..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none transition-all"
                        />
                    </div>

                    <div className="flex gap-2">
                        {['all', 'OPEN', 'PENDING', 'RESOLVED'].map(status => (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-wider border transition-all ${statusFilter === status
                                    ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 border-transparent'
                                    : 'bg-white dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700 hover:border-orange-500/50'
                                    }`}
                            >
                                {status === 'all' ? 'Tümü' : status}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto px-4 pb-4 space-y-2">
                    {filteredTickets.map(ticket => (
                        <button
                            key={ticket.id}
                            onClick={() => loadTicketDetails(ticket.id)}
                            className={`w-full p-4 rounded-2xl border transition-all text-left flex flex-col gap-2 group ${selectedTicket?.id === ticket.id
                                ? 'bg-white dark:bg-slate-800 border-orange-500 shadow-lg shadow-orange-500/5'
                                : 'bg-transparent border-transparent hover:bg-white dark:hover:bg-slate-800/50 hover:border-slate-200 dark:hover:border-slate-700'
                                }`}
                        >
                            <div className="flex justify-between items-start w-full">
                                <span className={`text-[10px] font-black px-2 py-0.5 rounded-full border ${ticket.platform === 'TRENDYOL' ? 'bg-orange-500/10 text-orange-600 border-orange-500/20' :
                                    ticket.platform === 'AMAZON' ? 'bg-yellow-500/10 text-yellow-600 border-yellow-500/20' :
                                        'bg-blue-500/10 text-blue-600 border-blue-500/20'
                                    }`}>
                                    {ticket.platform}
                                </span>
                                <span className="text-[10px] font-medium text-slate-400">
                                    {format(new Date(ticket.updatedAt), 'HH:mm', { locale: tr })}
                                </span>
                            </div>
                            <h3 className="font-bold text-slate-900 dark:text-white text-sm line-clamp-1 group-hover:text-orange-600 transition-colors">
                                {ticket.subject}
                            </h3>
                            <div className="flex items-center gap-2 text-xs text-slate-500 dark:text-slate-400">
                                <User size={12} />
                                <span className="truncate">{ticket.customerName}</span>
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* Main Content: Chat View */}
            {selectedTicket ? (
                <div className="flex-1 flex flex-col bg-slate-50/30 dark:bg-slate-900/30">
                    {/* Chat Header */}
                    <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-white dark:bg-slate-900">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-orange-100 dark:bg-orange-900/30 rounded-2xl flex items-center justify-center text-orange-600">
                                <User size={24} />
                            </div>
                            <div>
                                <h2 className="font-black text-slate-900 dark:text-white uppercase tracking-tight flex items-center gap-2">
                                    {selectedTicket.customerName}
                                    <span className="flex items-center gap-1 px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] text-slate-500 font-bold border border-slate-200 dark:border-slate-700">
                                        ID: #{selectedTicket.id.split('-')[0]}
                                    </span>
                                </h2>
                                <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{selectedTicket.subject}</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            {selectedTicket.orderId && (
                                <button className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-xs font-black text-slate-600 dark:text-slate-300 transition-all border border-slate-200 dark:border-slate-700">
                                    <ExternalLink size={14} /> Siparişi Gör
                                </button>
                            )}
                            <button className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-all border border-transparent hover:border-slate-200 dark:hover:border-slate-700 text-slate-500">
                                <MoreVertical size={20} />
                            </button>
                        </div>
                    </div>

                    {/* Messages Area */}
                    <div className="flex-1 overflow-y-auto p-8 space-y-6">
                        {messages.map((msg, idx) => (
                            <div key={msg.id || idx} className={`flex ${msg.senderType === 'AGENT' ? 'justify-end' : 'justify-start'}`}>
                                <div className={`max-w-[70%] space-y-2 ${msg.senderType === 'AGENT' ? 'items-end' : 'items-start'} flex flex-col`}>
                                    <div className={`p-4 rounded-3xl text-sm leading-relaxed shadow-sm ${msg.senderType === 'AGENT'
                                        ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900 rounded-tr-none'
                                        : 'bg-white text-slate-900 dark:bg-slate-800 dark:text-white border border-slate-200 dark:border-slate-700 rounded-tl-none'
                                        }`}>
                                        {msg.content}
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest px-1">
                                        {format(new Date(msg.createdAt), 'HH:mm', { locale: tr })} • {msg.senderType}
                                    </span>

                                    {msg.aiSuggestion && msg.senderType === 'CUSTOMER' && (
                                        <div className="mt-3 p-4 bg-orange-50 dark:bg-orange-500/5 border border-orange-200 dark:border-orange-500/20 rounded-2xl space-y-3">
                                            <div className="flex items-center gap-2 text-orange-600">
                                                <Bot size={16} />
                                                <span className="text-[10px] font-black uppercase tracking-widest">AI Önerisi</span>
                                            </div>
                                            <p className="text-xs italic text-slate-600 dark:text-slate-300">"{msg.aiSuggestion}"</p>
                                            <button className="text-[10px] font-black text-orange-600 hover:text-orange-700 flex items-center gap-1 uppercase tracking-wider">
                                                Taslağı Kullan <ChevronRight size={12} />
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Chat Input */}
                    <div className="p-6 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800">
                        <div className="relative group">
                            <div className="absolute inset-0 bg-gradient-to-r from-orange-500/5 to-purple-500/5 opacity-0 group-focus-within:opacity-100 transition-opacity rounded-[2rem]" />
                            <div className="relative bg-slate-50 dark:bg-slate-800/50 rounded-[2rem] p-3 border border-slate-200 dark:border-slate-700 focus-within:border-orange-500/50 transition-all flex items-end gap-3 shadow-sm">
                                <button className="p-3 text-slate-400 hover:text-orange-500 transition-colors">
                                    <Paperclip size={20} />
                                </button>
                                <textarea
                                    rows={1}
                                    placeholder="Mesajınızı buraya yazın..."
                                    value={newMessage}
                                    onChange={(e) => setNewMessage(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                                    className="flex-1 bg-transparent border-none focus:ring-0 text-sm py-3 text-slate-900 dark:text-white resize-none max-h-48 scrollbar-none"
                                />
                                <div className="flex items-center gap-2">
                                    <button className="p-3 text-orange-600 hover:bg-orange-500/10 rounded-2xl transition-all" title="AI Yardımı">
                                        <Sparkles size={20} />
                                    </button>
                                    <button
                                        onClick={handleSendMessage}
                                        disabled={!newMessage.trim()}
                                        className="p-3 bg-orange-600 text-white rounded-2xl shadow-lg shadow-orange-600/20 hover:scale-105 active:scale-95 disabled:opacity-50 disabled:scale-100 transition-all"
                                    >
                                        <Send size={20} />
                                    </button>
                                </div>
                            </div>
                        </div>
                        <p className="text-[10px] text-center text-slate-400 mt-4 font-medium uppercase tracking-widest">Shift + Enter ile alt satıra geçebilirsiniz</p>
                    </div>
                </div>
            ) : (
                <div className="flex-1 flex flex-col items-center justify-center bg-slate-50/20 dark:bg-slate-900/20 pb-12">
                    <div className="w-32 h-32 bg-slate-100 dark:bg-slate-800/50 rounded-[3rem] flex items-center justify-center text-slate-300 dark:text-slate-700 mb-6 border-2 border-dashed border-slate-200 dark:border-slate-800">
                        <MessageSquare size={48} />
                    </div>
                    <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Destek Merkezi</h2>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-2">Mesajları görüntülemek için sol taraftan bir görüşme seçin.</p>
                </div>
            )}

            {/* Create Ticket Modal */}
            <AnimatePresence>
                {isCreatingTicket && (
                    <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-[2rem] shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800"
                        >
                            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
                                <h3 className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2">
                                    <MessageSquare className="text-orange-600" size={20} /> Yeni Destek Talebi
                                </h3>
                                <button
                                    onClick={() => setIsCreatingTicket(false)}
                                    className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-all"
                                >
                                    <X size={20} />
                                </button>
                            </div>

                            <form onSubmit={handleCreateTicket} className="p-6 space-y-6">
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider mb-2">Platform</label>
                                        <div className="grid grid-cols-3 gap-2">
                                            {['TRENDYOL', 'HEPSIBURADA', 'AMAZON'].map(platform => (
                                                <button
                                                    key={platform}
                                                    type="button"
                                                    onClick={() => setNewTicketForm(prev => ({ ...prev, platform }))}
                                                    className={`px-3 py-2.5 rounded-xl text-[10px] sm:text-xs font-black uppercase tracking-wider border transition-all ${newTicketForm.platform === platform
                                                        ? platform === 'TRENDYOL' ? 'bg-orange-50 dark:bg-orange-500/10 text-orange-600 border-orange-500/30' :
                                                            platform === 'AMAZON' ? 'bg-yellow-50 dark:bg-yellow-500/10 text-yellow-600 border-yellow-500/30' :
                                                                'bg-blue-50 dark:bg-blue-500/10 text-blue-600 border-blue-500/30'
                                                        : 'bg-white dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'
                                                        }`}
                                                >
                                                    {platform}
                                                </button>
                                            ))}
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider mb-2">Konu Başığı</label>
                                        <input
                                            type="text"
                                            required
                                            value={newTicketForm.subject}
                                            onChange={(e) => setNewTicketForm(prev => ({ ...prev, subject: e.target.value }))}
                                            placeholder="Talebinizi özetleyen kısa bir başlık..."
                                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none transition-all dark:text-white"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider mb-2">Mesajınız</label>
                                        <textarea
                                            required
                                            rows={5}
                                            value={newTicketForm.message}
                                            onChange={(e) => setNewTicketForm(prev => ({ ...prev, message: e.target.value }))}
                                            placeholder="Detaylı olarak sorununuzu veya talebinizi açıklayın..."
                                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none transition-all resize-none dark:text-white"
                                        />
                                    </div>
                                </div>

                                <div className="pt-2 flex justify-end gap-3">
                                    <button
                                        type="button"
                                        onClick={() => setIsCreatingTicket(false)}
                                        className="px-6 py-3 rounded-xl text-sm font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                                    >
                                        İptal
                                    </button>
                                    <button
                                        type="submit"
                                        disabled={loading || !newTicketForm.subject || !newTicketForm.message}
                                        className="px-6 py-3 bg-orange-600 hover:bg-orange-500 active:scale-95 disabled:opacity-50 disabled:active:scale-100 text-white rounded-xl text-sm font-bold shadow-lg shadow-orange-600/20 transition-all flex items-center gap-2"
                                    >
                                        <Send size={16} /> Gönder
                                    </button>
                                </div>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
    ClipboardList, PlusCircle, CheckCircle2, Clock, AlertTriangle,
    Users, Calendar, Tag, MoreHorizontal, Filter, Search,
    Circle, ArrowUpRight, BarChart3,
    LucideIcon
} from 'lucide-react';

type Priority = 'high' | 'medium' | 'low';
type Status = 'todo' | 'in-progress' | 'review' | 'done';

const priorityConfig: Record<Priority, { label: string; color: string; bg: string }> = {
    high: { label: 'Yüksek', color: 'text-red-400', bg: 'bg-red-500/10' },
    medium: { label: 'Orta', color: 'text-amber-400', bg: 'bg-amber-500/10' },
    low: { label: 'Düşük', color: 'text-blue-400', bg: 'bg-blue-500/10' },
};

const statusConfig: Record<Status, { label: string; color: string; bg: string; icon: typeof Circle }> = {
    todo: { label: 'Yapılacak', color: 'text-slate-400', bg: 'bg-slate-500/10', icon: Circle },
    'in-progress': { label: 'Devam Ediyor', color: 'text-blue-400', bg: 'bg-blue-500/10', icon: Clock },
    review: { label: 'İncelemede', color: 'text-amber-400', bg: 'bg-amber-500/10', icon: AlertTriangle },
    done: { label: 'Tamamlandı', color: 'text-emerald-400', bg: 'bg-emerald-500/10', icon: CheckCircle2 },
};

interface Task {
    id: number | string;
    title: string;
    description: string;
    status: Status;
    priority: Priority;
    assignee: string;
    dueDate: string;
    tags: string[];
    progress: number;
}

import { useTasks } from '@/lib/hooks';

export default function TaskManagerPage() {
    const { data: tasksData, loading: isLoading } = useTasks();
    const [view, setView] = useState<'board' | 'list'>('board');
    const [searchTerm, setSearchTerm] = useState('');
    const [showCreate, setShowCreate] = useState(false);

    const tasks = Array.isArray(tasksData) ? (tasksData as Task[]) : [];
    const columns: Status[] = ['todo', 'in-progress', 'review', 'done'];

    const filteredTasks = tasks.filter(t => t.title.toLowerCase().includes(searchTerm.toLowerCase()));

    const totalTasks = tasks.length;
    const doneTasks = tasks.filter(t => t.status === 'done').length;
    const progressPct = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-foreground flex items-center gap-3">
                        <ClipboardList className="w-7 h-7 text-indigo-400" /> Görev & Proje Yönetimi
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">Ekip görevlerini takip edin ve yönetin</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="flex gap-1 bg-surface rounded-xl p-1 border border-border">
                        <button onClick={() => setView('board')} className={`px-3 py-1.5 rounded-lg text-xs font-medium ${view === 'board' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Board</button>
                        <button onClick={() => setView('list')} className={`px-3 py-1.5 rounded-lg text-xs font-medium ${view === 'list' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Liste</button>
                    </div>
                    <button onClick={() => setShowCreate(true)} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm transition-colors">
                        <PlusCircle className="w-4 h-4" /> Yeni Görev
                    </button>
                </div>
            </div>

            {/* Progress & Search */}
            <div className="flex gap-4 items-center">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Görev ara..."
                        className="w-full pl-10 pr-4 py-2.5 bg-surface rounded-xl text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                </div>
                <div className="flex items-center gap-3 bg-surface rounded-xl border border-border px-4 py-2.5">
                    <BarChart3 className="w-4 h-4 text-indigo-400" />
                    <div className="w-32 h-2 bg-background rounded-full">
                        <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${progressPct}%` }} />
                    </div>
                    <span className="text-xs text-foreground font-medium">{progressPct}%</span>
                    <span className="text-xs text-slate-500">{doneTasks}/{totalTasks}</span>
                </div>
            </div>

            {/* Board View */}
            {view === 'board' && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {columns.map(col => {
                        const cfg = statusConfig[col];
                        const colTasks = filteredTasks.filter((t) => t.status === col);
                        return (
                            <div key={col} className="space-y-3">
                                <div className="flex items-center justify-between px-1">
                                    <div className="flex items-center gap-2">
                                        <cfg.icon className={`w-4 h-4 ${cfg.color}`} />
                                        <span className="text-sm font-medium text-foreground">{cfg.label}</span>
                                        <span className="text-xs text-slate-600 bg-background px-2 py-0.5 rounded-full">{colTasks.length}</span>
                                    </div>
                                </div>
                                {colTasks.map((task, i) => {
                                    const prCfg = priorityConfig[task.priority as Priority];
                                    return (
                                        <motion.div key={task.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                                            className="bg-surface rounded-xl border border-border p-4 hover:border-indigo-500/20 transition-all cursor-pointer">
                                            <div className="flex items-start justify-between mb-2">
                                                <span className={`px-2 py-0.5 rounded text-[10px] ${prCfg.bg} ${prCfg.color}`}>{prCfg.label}</span>
                                                <button className="text-slate-600 hover:text-foreground"><MoreHorizontal className="w-4 h-4" /></button>
                                            </div>
                                            <h4 className="text-sm font-medium text-foreground mb-1">{task.title}</h4>
                                            <p className="text-[10px] text-slate-500 mb-3">{task.description}</p>
                                            {task.progress > 0 && task.progress < 100 && (
                                                <div className="mb-3">
                                                    <div className="h-1 bg-background rounded-full">
                                                        <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${task.progress}%` }} />
                                                    </div>
                                                    <div className="text-[10px] text-slate-500 mt-1">{task.progress}%</div>
                                                </div>
                                            )}
                                            <div className="flex flex-wrap gap-1 mb-3">
                                                {task.tags.map((tag: string) => (
                                                    <span key={tag} className="px-1.5 py-0.5 rounded bg-indigo-500/10 text-indigo-400 text-[10px]">{tag}</span>
                                                ))}
                                            </div>
                                            <div className="flex items-center justify-between text-[10px] text-slate-500">
                                                <span className="flex items-center gap-1"><Users className="w-3 h-3" /> {task.assignee}</span>
                                                <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {task.dueDate}</span>
                                            </div>
                                        </motion.div>
                                    );
                                })}
                                {colTasks.length === 0 && !isLoading && (
                                    <div className="text-center py-8 bg-background/20 rounded-xl border border-dashed border-border/50">
                                        <p className="text-[10px] text-slate-500">Bu aşamada görev yok</p>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {/* List View */}
            {view === 'list' && (
                <div className="bg-surface rounded-xl border border-border overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="text-slate-500 text-xs border-b border-border">
                                    <th className="text-left px-4 py-3 font-medium">Görev</th>
                                    <th className="text-left px-4 py-3 font-medium">Durum</th>
                                    <th className="text-left px-4 py-3 font-medium">Öncelik</th>
                                    <th className="text-left px-4 py-3 font-medium">Atanan</th>
                                    <th className="text-left px-4 py-3 font-medium">İlerleme</th>
                                    <th className="text-left px-4 py-3 font-medium">Bitiş</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredTasks.map((task, i) => {
                                    const sCfg = statusConfig[task.status as Status];
                                    const pCfg = priorityConfig[task.priority as Priority];
                                    return (
                                        <motion.tr key={task.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03 }}
                                            className="border-b border-border/50 hover:bg-background/50">
                                            <td className="px-4 py-3">
                                                <div className="text-xs text-foreground font-medium">{task.title}</div>
                                                <div className="flex gap-1 mt-1">{task.tags.map((t: string) => <span key={t} className="px-1.5 py-0.5 rounded bg-indigo-500/10 text-indigo-400 text-[10px]">{t}</span>)}</div>
                                            </td>
                                            <td className="px-4 py-3"><span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs ${sCfg.bg} ${sCfg.color}`}><sCfg.icon className="w-3 h-3" /> {sCfg.label}</span></td>
                                            <td className="px-4 py-3"><span className={`text-xs ${pCfg.color}`}>{pCfg.label}</span></td>
                                            <td className="px-4 py-3 text-xs text-slate-400">{task.assignee}</td>
                                            <td className="px-4 py-3">
                                                <div className="flex items-center gap-2">
                                                    <div className="w-16 h-1.5 bg-background rounded-full"><div className="h-full bg-indigo-500 rounded-full" style={{ width: `${task.progress}%` }} /></div>
                                                    <span className="text-xs text-slate-400">{task.progress}%</span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-xs text-slate-400">{task.dueDate}</td>
                                        </motion.tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* Create Modal */}
            {showCreate && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowCreate(false)}>
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                        className="bg-surface rounded-2xl border border-border p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                        <h3 className="text-lg font-semibold text-foreground mb-4">Yeni Görev Oluştur</h3>
                        <div className="space-y-3">
                            <div>
                                <label className="text-xs text-slate-400 block mb-1">Başlık</label>
                                <input placeholder="Görev başlığı" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none" />
                            </div>
                            <div>
                                <label className="text-xs text-slate-400 block mb-1">Açıklama</label>
                                <textarea placeholder="Detaylı açıklama..." rows={2}
                                    className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border focus:border-indigo-500 focus:outline-none resize-none" />
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Öncelik</label>
                                    <select className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border">
                                        <option>Yüksek</option><option>Orta</option><option>Düşük</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Atanan</label>
                                    <input placeholder="Kişi" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border" />
                                </div>
                                <div>
                                    <label className="text-xs text-slate-400 block mb-1">Bitiş Tarihi</label>
                                    <input type="date" className="w-full px-3 py-2 bg-background rounded-lg text-sm text-foreground border border-border" />
                                </div>
                            </div>
                        </div>
                        <div className="flex justify-end gap-2 mt-6">
                            <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-sm text-slate-400 hover:text-foreground">İptal</button>
                            <button className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium">Oluştur</button>
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Sun, Moon, Monitor, Palette, Check, Eye, Paintbrush, Sliders, RotateCcw, Sparkles } from 'lucide-react';

type ThemeMode = 'dark' | 'light' | 'system';

const colorSchemes = [
    { id: 'indigo', name: 'İndigo', primary: '#6366f1', accent: '#818cf8', bg: '#0a0a0f', surface: '#111118', preview: ['#6366f1', '#818cf8', '#4f46e5'] },
    { id: 'emerald', name: 'Zümrüt', primary: '#10b981', accent: '#34d399', bg: '#0a0f0a', surface: '#111811', preview: ['#10b981', '#34d399', '#059669'] },
    { id: 'rose', name: 'Gül', primary: '#f43f5e', accent: '#fb7185', bg: '#0f0a0a', surface: '#181111', preview: ['#f43f5e', '#fb7185', '#e11d48'] },
    { id: 'amber', name: 'Amber', primary: '#f59e0b', accent: '#fbbf24', bg: '#0f0d0a', surface: '#181611', preview: ['#f59e0b', '#fbbf24', '#d97706'] },
    { id: 'cyan', name: 'Cyan', primary: '#06b6d4', accent: '#22d3ee', bg: '#0a0d0f', surface: '#111518', preview: ['#06b6d4', '#22d3ee', '#0891b2'] },
    { id: 'violet', name: 'Mor', primary: '#8b5cf6', accent: '#a78bfa', bg: '#0d0a0f', surface: '#151118', preview: ['#8b5cf6', '#a78bfa', '#7c3aed'] },
];

export default function ThemeSettingsPage() {
    const [mode, setMode] = useState<ThemeMode>('dark');
    const [selectedScheme, setSelectedScheme] = useState('indigo');
    const [fontSize, setFontSize] = useState(14);
    const [borderRadius, setBorderRadius] = useState(12);
    const [compactMode, setCompactMode] = useState(false);
    const currentScheme = colorSchemes.find(s => s.id === selectedScheme)!;

    return (
        <div className="space-y-6 animate-in fade-in duration-500 pb-20">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <Palette className="w-8 h-8 text-pink-500" /> Tema Ayarları
                    </h1>
                    <p className="text-slate-500 mt-1">Arayüzü kendi zevkinize göre özelleştirin</p>
                </div>
                <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-xl text-sm text-slate-300"><RotateCcw className="w-4 h-4" /> Varsayılana Dön</button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 space-y-6">
                    {/* Mode */}
                    <div className="bg-surface rounded-2xl border border-border p-6">
                        <h2 className="text-lg font-bold text-foreground mb-4"><Sparkles className="w-5 h-5 inline mr-2 text-slate-400" />Tema Modu</h2>
                        <div className="grid grid-cols-3 gap-3">
                            {([{ id: 'dark', icon: Moon, label: 'Koyu' }, { id: 'light', icon: Sun, label: 'Açık' }, { id: 'system', icon: Monitor, label: 'Sistem' }] as const).map(m => (
                                <button key={m.id} onClick={() => setMode(m.id)}
                                    className={`p-4 rounded-xl border text-center transition-all ${mode === m.id ? 'bg-indigo-500/20 border-indigo-500' : 'border-border'}`}>
                                    <m.icon className={`w-6 h-6 mx-auto mb-2 ${mode === m.id ? 'text-indigo-400' : 'text-slate-400'}`} />
                                    <div className="text-sm">{m.label}</div>
                                </button>
                            ))}
                        </div>
                    </div>
                    {/* Color */}
                    <div className="bg-surface rounded-2xl border border-border p-6">
                        <h2 className="text-lg font-bold text-foreground mb-4"><Paintbrush className="w-5 h-5 inline mr-2 text-slate-400" />Renk Şeması</h2>
                        <div className="grid grid-cols-3 gap-3">
                            {colorSchemes.map(s => (
                                <button key={s.id} onClick={() => setSelectedScheme(s.id)}
                                    className={`p-4 rounded-xl border text-center ${selectedScheme === s.id ? 'border-white/20 ring-2' : 'border-border'}`}
                                    style={{ '--tw-ring-color': selectedScheme === s.id ? s.primary : undefined } as any}>
                                    <div className="flex justify-center gap-1 mb-2">{s.preview.map((c, i) => (<div key={i} className="w-6 h-6 rounded-full" style={{ backgroundColor: c }} />))}</div>
                                    <div className="text-sm text-foreground">{s.name}</div>
                                    {selectedScheme === s.id && <Check className="w-4 h-4 mx-auto mt-1" style={{ color: s.primary }} />}
                                </button>
                            ))}
                        </div>
                    </div>
                    {/* Fine tune */}
                    <div className="bg-surface rounded-2xl border border-border p-6">
                        <h2 className="text-lg font-bold text-foreground mb-4"><Sliders className="w-5 h-5 inline mr-2 text-slate-400" />İnce Ayarlar</h2>
                        <div className="space-y-6">
                            <div>
                                <div className="flex justify-between mb-2"><span className="text-sm text-foreground">Yazı Boyutu</span><span className="text-sm text-slate-400">{fontSize}px</span></div>
                                <input type="range" min={12} max={18} value={fontSize} onChange={e => setFontSize(+e.target.value)} className="w-full accent-indigo-500" />
                            </div>
                            <div>
                                <div className="flex justify-between mb-2"><span className="text-sm text-foreground">Köşe Yuvarlaklığı</span><span className="text-sm text-slate-400">{borderRadius}px</span></div>
                                <input type="range" min={0} max={20} value={borderRadius} onChange={e => setBorderRadius(+e.target.value)} className="w-full accent-indigo-500" />
                            </div>
                            <div className="flex items-center justify-between">
                                <div><div className="text-sm text-foreground">Kompakt Mod</div><div className="text-xs text-slate-500">Daha sıkı yerleşim</div></div>
                                <button onClick={() => setCompactMode(!compactMode)} className={`w-12 h-6 rounded-full ${compactMode ? 'bg-indigo-600' : 'bg-slate-700'}`}>
                                    <div className={`w-5 h-5 bg-white rounded-full transition-transform ${compactMode ? 'translate-x-6' : 'translate-x-0.5'}`} />
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
                {/* Preview */}
                <div className="bg-surface rounded-2xl border border-border p-6 sticky top-4 h-fit">
                    <h2 className="text-lg font-bold text-foreground mb-4"><Eye className="w-5 h-5 inline mr-2 text-slate-400" />Önizleme</h2>
                    <div className="p-4 rounded-xl space-y-4" style={{ backgroundColor: currentScheme.bg, borderRadius: `${borderRadius}px` }}>
                        <div className="p-3 rounded-lg" style={{ backgroundColor: currentScheme.surface }}>
                            <div className="w-20 h-2 rounded mb-2" style={{ backgroundColor: currentScheme.primary }} /><div className="w-full h-2 rounded bg-white/5 mb-1" /><div className="w-3/4 h-2 rounded bg-white/5" />
                        </div>
                        <div className="flex gap-2">
                            {[currentScheme.primary, currentScheme.accent].map((c, i) => (
                                <div key={i} className="flex-1 p-3 rounded-lg" style={{ backgroundColor: currentScheme.surface }}><div className="w-8 h-8 rounded-lg mb-2" style={{ backgroundColor: c, opacity: 0.2 }} /><div className="w-12 h-2 rounded bg-white/10" /></div>
                            ))}
                        </div>
                        <button className="w-full py-2 text-white text-xs font-medium" style={{ backgroundColor: currentScheme.primary, borderRadius: `${borderRadius}px` }}>Kaydet</button>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
