        name: 'Profesyonel',
        icon: '💼',
        settings: { mode: 'dark', color: 'blue', font: 'inter', radius: 'lg', compactMode: false, animations: true },
    },
    {
        name: 'Enerji',
        icon: '⚡',
        settings: { mode: 'dark', color: 'orange', font: 'montserrat', radius: 'md', compactMode: false, animations: true },
