'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import { Camera, X, Flashlight, FlashlightOff, RotateCcw } from 'lucide-react';

interface BarcodeScannerProps {
  onScan: (barcode: string) => void;
  onClose: () => void;
  acceptedFormats?: string[];
}

export function BarcodeScanner({ onScan, onClose, acceptedFormats = ['ean_13', 'ean_8', 'code_128', 'qr_code'] }: BarcodeScannerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasFlash, setHasFlash] = useState(false);
  const [flashOn, setFlashOn] = useState(false);
  const [lastScanned, setLastScanned] = useState<string | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startScanner = useCallback(async () => {
    try {
      setError(null);
      setIsScanning(true);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 },
        },
      });

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
      }

      // Flash kontrolü
      const track = stream.getVideoTracks()[0];
      const capabilities = track.getCapabilities() as MediaTrackCapabilities & { torch?: boolean };
      setHasFlash(!!capabilities.torch);

      // BarcodeDetector API (Chrome/Edge)
      if ('BarcodeDetector' in window) {
        scanWithBarcodeDetector();
      } else {
        // Fallback: Manuel tarama uyarısı
        setError('Barkod algılama desteklenmiyor. Lütfen barkodu manuel girin.');
      }
    } catch (err) {
      console.error('Kamera erişim hatası:', err);
      setError('Kamera erişimi sağlanamadı. Lütfen izinleri kontrol edin.');
      setIsScanning(false);
    }
  }, []);

  const scanWithBarcodeDetector = async () => {
    // @ts-ignore - BarcodeDetector henüz tüm tarayıcılarda tanımlı değil
    const barcodeDetector = new window.BarcodeDetector({
      formats: acceptedFormats,
    });

    const detectLoop = async () => {
      if (!videoRef.current || !isScanning) return;

      try {
        const barcodes = await barcodeDetector.detect(videoRef.current);

        if (barcodes.length > 0) {
          const barcode = barcodes[0];
          if (barcode.rawValue !== lastScanned) {
            setLastScanned(barcode.rawValue);

            // Başarı titreşimi
            if ('vibrate' in navigator) {
              navigator.vibrate(100);
            }

            onScan(barcode.rawValue);
          }
        }
      } catch (err) {
        console.error('Barkod algılama hatası:', err);
      }

      if (isScanning) {
        requestAnimationFrame(detectLoop);
      }
    };

    detectLoop();
  };

  const stopScanner = useCallback(() => {
    setIsScanning(false);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  }, []);

  const toggleFlash = async () => {
    if (!streamRef.current) return;

    const track = streamRef.current.getVideoTracks()[0];
    const newFlashState = !flashOn;

    try {
      await track.applyConstraints({
        // @ts-ignore
        advanced: [{ torch: newFlashState }],
      });
      setFlashOn(newFlashState);
    } catch (err) {
      console.error('Flash toggle hatası:', err);
    }
  };

  useEffect(() => {
    let mounted = true;

    const startCamera = async () => {
      if (!mounted) return;
      try {
        setError(null);
        setIsScanning(true);

        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'environment',
            width: { ideal: 1280 },
            height: { ideal: 720 },
          },
        });

        if (!mounted) {
          stream.getTracks().forEach(track => track.stop());
          return;
        }

        streamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }

        // Flash kontrolü
        const track = stream.getVideoTracks()[0];
        const capabilities = track.getCapabilities() as MediaTrackCapabilities & { torch?: boolean };
        setHasFlash(!!capabilities.torch);

        // BarcodeDetector API (Chrome/Edge)
        if ('BarcodeDetector' in window) {
          scanWithBarcodeDetector();
        } else {
          // Fallback: Manuel tarama uyarısı
          setError('Barkod algılama desteklenmiyor. Lütfen barkodu manuel girin.');
        }
      } catch (err) {
        console.error('Kamera erişim hatası:', err);
        setError('Kamera erişimi sağlanamadı. Lütfen izinleri kontrol edin.');
        setIsScanning(false);
      }
    };

    startCamera();

    return () => {
      mounted = false;
      stopScanner();
    };
  }, []);

  const handleClose = () => {
    stopScanner();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-black">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 z-10 flex items-center justify-between p-4 bg-gradient-to-b from-black/70 to-transparent">
        <button
          onClick={handleClose}
          className="p-2 rounded-full bg-white/20 backdrop-blur-sm"
        >
          <X className="w-6 h-6 text-white" />
        </button>

        <span className="text-white font-medium">Barkod Tara</span>

        <div className="flex gap-2">
          {hasFlash && (
            <button
              onClick={toggleFlash}
              className="p-2 rounded-full bg-white/20 backdrop-blur-sm"
            >
              {flashOn ? (
                <FlashlightOff className="w-6 h-6 text-white" />
              ) : (
                <Flashlight className="w-6 h-6 text-white" />
              )}
            </button>
          )}

          <button
            onClick={() => { stopScanner(); startScanner(); }}
            className="p-2 rounded-full bg-white/20 backdrop-blur-sm"
          >
            <RotateCcw className="w-6 h-6 text-white" />
          </button>
        </div>
      </div>

      {/* Video */}
      <video
        ref={videoRef}
        className="w-full h-full object-cover"
        playsInline
        muted
        autoPlay
      />
      <canvas ref={canvasRef} className="hidden" />

      {/* Tarama alanı göstergesi */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <div className="w-72 h-48 border-2 border-white/50 rounded-lg relative">
          {/* Köşe çizgileri */}
          <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-primary-500 rounded-tl-lg" />
          <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-primary-500 rounded-tr-lg" />
          <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-primary-500 rounded-bl-lg" />
          <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-primary-500 rounded-br-lg" />

          {/* Tarama çizgisi animasyonu */}
          {isScanning && (
            <div className="absolute inset-x-0 h-0.5 bg-primary-500 animate-scan" />
          )}
        </div>
      </div>

      {/* Alt bilgi */}
      <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-black/70 to-transparent">
        {error ? (
          <div className="bg-red-500/20 backdrop-blur-sm rounded-lg p-4 text-center">
            <p className="text-white text-sm">{error}</p>
          </div>
        ) : lastScanned ? (
          <div className="bg-green-500/20 backdrop-blur-sm rounded-lg p-4 text-center">
            <p className="text-white text-sm">Tespit edildi:</p>
            <p className="text-white font-mono font-bold text-lg">{lastScanned}</p>
          </div>
        ) : (
          <p className="text-white/80 text-center text-sm">
            Barkodu çerçeve içine getirin
          </p>
        )}
      </div>

      {/* CSS for scan animation */}
      <style jsx>{`
        @keyframes scan {
          0%, 100% { top: 0; }
          50% { top: calc(100% - 2px); }
        }
        .animate-scan {
          animation: scan 2s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
}

// Barkod tarama butonu bileşeni
export function BarcodeScanButton({ onScan }: { onScan: (barcode: string) => void }) {
  const [showScanner, setShowScanner] = useState(false);

  const handleScan = (barcode: string) => {
    onScan(barcode);
    setShowScanner(false);
  };

  return (
    <>
      <button
        onClick={() => setShowScanner(true)}
        className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors"
      >
        <Camera className="w-5 h-5" />
        <span>Barkod Tara</span>
      </button>

      {showScanner && (
        <BarcodeScanner
          onScan={handleScan}
          onClose={() => setShowScanner(false)}
        />
      )}
    </>
  );
}

import { useRef, useState, useEffect } from 'react';
import { Bot, Zap, Globe, ArrowRight, CheckCircle2, ShoppingBag, BarChart3, TrendingUp, Search, Code2 } from 'lucide-react';
import { motion, useMotionTemplate, useMotionValue, useTransform } from 'framer-motion';

// Combined 3D Tilt + Spotlight Component
const SpotlightCard = ({ children, className = "" }: { children: React.ReactNode, className?: string }) => {
    const divRef = useRef<HTMLDivElement>(null);
    const [isFocused, setIsFocused] = useState(false);

    // Spotlight Values
    const mouseX = useMotionValue(0);
    const mouseY = useMotionValue(0);

    // Tilt Values (driven by drag)
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const rotateX = useTransform(y, [-100, 100], [15, -15]); // Reduced rotation for cleaner feel
    const rotateY = useTransform(x, [-100, 100], [-15, 15]);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        if (!divRef.current) return;
        const rect = divRef.current.getBoundingClientRect();
        mouseX.set(e.clientX - rect.left);
        mouseY.set(e.clientY - rect.top);
    };

    return (
        <motion.div
            ref={divRef}
            style={{ x, y, rotateX, rotateY, z: 100, perspective: 1000 }}
            drag
            dragElastic={0.16}
            dragConstraints={{ top: 0, left: 0, right: 0, bottom: 0 }}
            whileTap={{ cursor: "grabbing" }}
            onMouseMove={handleMouseMove}
            onMouseEnter={() => setIsFocused(true)}
            onMouseLeave={() => setIsFocused(false)}
            className={`relative overflow-hidden rounded-[32px] border border-slate-200 dark:border-white/10 bg-white dark:bg-white/5 backdrop-blur-xl transition-colors duration-500 hover:border-blue-300 dark:hover:border-blue-500/30 hover:shadow-2xl hover:shadow-blue-500/10 dark:hover:shadow-blue-900/20 group ${className}`}
        >
            {/* Spotlight Gradient */}
            <motion.div
                className="pointer-events-none absolute -inset-px opacity-0 transition duration-500 group-hover:opacity-100 z-10"
                style={{
                    background: useMotionTemplate`
                        radial-gradient(
                          650px circle at ${mouseX}px ${mouseY}px,
                          rgba(59, 130, 246, 0.15),
                          transparent 80%
                        )
                      `,
                }}
            />

            {/* Noise Texture */}
            <div className="absolute inset-0 opacity-[0.03] dark:opacity-[0.05] pointer-events-none z-0" style={{ backgroundImage: 'url("data:image/svg+xml,%3Csvg viewBox=\'0 0 256 256\' xmlns=\'http://www.w3.org/2000/svg\'%3E%3Cfilter id=\'noise\'%3E%3CfeTurbulence type=\'fractalNoise\' baseFrequency=\'0.65\' numOctaves=\'3\' stitchTiles=\'stitch\'/%3E%3C/filter%3E%3Crect width=\'100%25\' height=\'100%25\' filter=\'url(%23noise)\'/%3E%3C/svg%3E")' }} />

            <div className="relative h-full z-20 pointer-events-auto">{children}</div>
        </motion.div>
    );
};

