            style={{
                x,
                y,
                scale,
                zIndex,
                opacity
            }}
            whileHover={{ scale: 1.5, zIndex: 50, opacity: 1 }}
        >
            {/* Planet Body */}
            <div className="relative w-full h-full z-10">
