                            animate={{ opacity: 1, scale: 1, y: 0, rotateX: 0 }}
                            exit={{ opacity: 0, scale: 0.95, y: 20, rotateX: -5 }}
                            transition={{ type: 'spring', stiffness: 260, damping: 25 }}
