                                                    transition={{ duration: 2, delay: 4.5, repeat: Infinity }}
                                                />
                                            </svg>
                                        </div>

                                        {/* Mini marketplace row */}
                                        <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-200/60 dark:border-white/[0.04]">
