            </motion.div>
        </section>
    );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    MessageCircle, X, Send, Minimize2, Maximize2, Bot, User,
    Phone, Mail, HelpCircle
} from 'lucide-react';

interface Message {
    id: string;
    type: 'bot' | 'user';
    content: string;
    timestamp: Date;
}

const quickReplies = [
    'Fiyatlar hakkında bilgi',
    'Demo talep etmek istiyorum',
    'Teknik destek',
    'Entegrasyonlar hakkında',
];

export default function LiveChatWidget() {
    const [isOpen, setIsOpen] = useState(false);
    const [isMinimized, setIsMinimized] = useState(false);
    const [messages, setMessages] = useState<Message[]>([
        {
            id: '1',
            type: 'bot',
            content: 'Merhaba! 👋 Ben Pazaryonetimi\'nin asistanıyım. Size nasıl yardımcı olabilirim?',
            timestamp: new Date()
        }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [isTyping, setIsTyping] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    useEffect(() => {
        if (isOpen && !isMinimized) {
            inputRef.current?.focus();
        }
    }, [isOpen, isMinimized]);

    const sendMessage = async (content: string) => {
        if (!content.trim()) return;

        // Add user message
        const now = new Date();
        const userMessage: Message = {
            id: `user-${now.getTime()}`,
            type: 'user',
            content: content.trim(),
            timestamp: now
        };
        setMessages(prev => [...prev, userMessage]);
        setInputValue('');

        setIsTyping(true);
        try {
            const res = await fetch('/api/ai/copilot/chat', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-tenant-id': 'default',
                },
                body: JSON.stringify({ message: content, context: '/live-chat-widget' }),
            });

            let reply = 'Canli destek servisi su anda yanit veremiyor. Lutfen daha sonra tekrar deneyin.';
            if (res.ok) {
                const data = await res.json();
                reply = typeof data?.message === 'string' && data.message.trim()
                    ? data.message
                    : reply;
            }

            const botMessage: Message = {
                id: `bot-${Date.now()}`,
                type: 'bot',
                content: reply,
                timestamp: new Date()
            };
            setMessages(prev => [...prev, botMessage]);
        } catch {
            const botMessage: Message = {
                id: `bot-${Date.now()}`,
                type: 'bot',
                content: 'Canli destek servisine ulasilamadi. Lutfen tekrar deneyin.',
                timestamp: new Date()
            };
            setMessages(prev => [...prev, botMessage]);
        } finally {
            setIsTyping(false);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        sendMessage(inputValue);
    };

    const handleQuickReply = (reply: string) => {
        sendMessage(reply);
    };

    const formatTime = (date: Date) => {
        return date.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
    };

    return (
        <>
            {/* Chat Button */}
            <AnimatePresence>
                {!isOpen && (
                    <motion.button
                        initial={{ scale: 0, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        exit={{ scale: 0, opacity: 0 }}
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        onClick={() => setIsOpen(true)}
                        className="fixed bottom-32 lg:bottom-6 right-6 z-[110] w-16 h-16 rounded-full bg-gradient-to-r from-emerald-600 to-teal-600 text-white shadow-2xl flex items-center justify-center hover:shadow-emerald-500/30 transition-shadow"
                    >
                        <MessageCircle size={28} />
                        {/* Notification Dot */}
                        <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 rounded-full border-2 border-white animate-pulse" />
                    </motion.button>
                )}
            </AnimatePresence>

            {/* Chat Window */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 20, scale: 0.95 }}
                        animate={{
                            opacity: 1,
                            y: 0,
                            scale: 1,
                            height: isMinimized ? 'auto' : 500
                        }}
                        exit={{ opacity: 0, y: 20, scale: 0.95 }}
                        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
                        className="fixed bottom-32 lg:bottom-6 right-6 z-[110] w-[380px] max-w-[calc(100vw-48px)] bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl rounded-2xl shadow-2xl overflow-hidden flex flex-col"
                    >
                        {/* Header */}
                        <div className="bg-gradient-to-r from-emerald-600 to-teal-600 p-4">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full bg-white/20 flex items-center justify-center">
                                        <Bot size={20} className="text-white" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-white">Pazaryonetimi</h3>
                                        <div className="flex items-center gap-1 text-xs text-white/80">
                                            <span className="w-2 h-2 rounded-full bg-green-400" />
                                            Çevrimiçi
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => setIsMinimized(!isMinimized)}
                                        className="w-8 h-8 rounded-lg bg-white/20 flex items-center justify-center text-white hover:bg-white/30 transition-colors"
                                    >
                                        {isMinimized ? <Maximize2 size={16} /> : <Minimize2 size={16} />}
                                    </button>
                                    <button
                                        onClick={() => setIsOpen(false)}
                                        className="w-8 h-8 rounded-lg bg-white/20 flex items-center justify-center text-white hover:bg-white/30 transition-colors"
                                    >
                                        <X size={16} />
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Chat Content */}
                        <AnimatePresence>
                            {!isMinimized && (
                                <motion.div
                                    initial={{ height: 0 }}
                                    animate={{ height: 'auto' }}
                                    exit={{ height: 0 }}
                                    className="flex-1 flex flex-col overflow-hidden"
                                >
                                    {/* Messages */}
                                    <div className="flex-1 overflow-y-auto p-4 space-y-4 max-h-[300px]">
                                        {messages.map((message) => (
                                            <motion.div
                                                key={message.id}
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
                                            >
                                                <div className={`flex items-end gap-2 max-w-[85%] ${message.type === 'user' ? 'flex-row-reverse' : ''}`}>
                                                    {/* Avatar */}
                                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${message.type === 'bot'
                                                        ? 'bg-gradient-to-br from-emerald-500 to-teal-600'
                                                        : 'bg-slate-200 dark:bg-slate-700'
                                                        }`}>
                                                        {message.type === 'bot' ? (
                                                            <Bot size={16} className="text-white" />
                                                        ) : (
                                                            <User size={16} className="text-slate-600 dark:text-slate-400" />
                                                        )}
                                                    </div>

                                                    {/* Message Bubble */}
                                                    <div>
                                                        <div className={`p-3 rounded-2xl ${message.type === 'bot'
                                                            ? 'bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-white rounded-bl-md'
                                                            : 'bg-gradient-to-r from-emerald-600 to-teal-600 text-white rounded-br-md'
                                                            }`}>
                                                            <p className="text-sm">{message.content}</p>
                                                        </div>
                                                        <p className={`text-xs text-slate-400 mt-1 ${message.type === 'user' ? 'text-right' : ''}`}>
                                                            {formatTime(message.timestamp)}
                                                        </p>
                                                    </div>
                                                </div>
                                            </motion.div>
                                        ))}

                                        {/* Typing Indicator */}
                                        {isTyping && (
                                            <motion.div
                                                initial={{ opacity: 0 }}
                                                animate={{ opacity: 1 }}
                                                className="flex items-center gap-2"
                                            >
                                                <div className="w-8 h-8 rounded-full bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center">
                                                    <Bot size={16} className="text-white" />
                                                </div>
                                                <div className="p-3 rounded-2xl bg-slate-100 dark:bg-white/10 rounded-bl-md">
                                                    <div className="flex gap-1">
                                                        <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '0ms' }} />
                                                        <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '150ms' }} />
                                                        <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '300ms' }} />
                                                    </div>
                                                </div>
                                            </motion.div>
                                        )}
                                        <div ref={messagesEndRef} />
                                    </div>

                                    {/* Quick Replies */}
                                    {messages.length <= 2 && (
                                        <div className="px-4 pb-2">
                                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-2">Hızlı Yanıtlar:</p>
                                            <div className="flex flex-wrap gap-2">
                                                {quickReplies.map((reply, i) => (
                                                    <button
                                                        key={i}
                                                        onClick={() => handleQuickReply(reply)}
                                                        className="px-3 py-1.5 text-xs bg-slate-100 dark:bg-white/10 text-slate-600 dark:text-slate-300 rounded-full hover:bg-slate-200 dark:hover:bg-white/20 transition-colors"
                                                    >
                                                        {reply}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Input */}
                                    <div className="p-4 border-t border-slate-200 dark:border-white/10">
                                        <form onSubmit={handleSubmit} className="flex items-center gap-2">
                                            <input
                                                ref={inputRef}
                                                type="text"
                                                value={inputValue}
                                                onChange={(e) => setInputValue(e.target.value)}
                                                placeholder="Mesajınızı yazın..."
                                                className="flex-1 px-4 py-2 rounded-xl bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-white placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-sm"
                                            />
                                            <button
                                                type="submit"
                                                disabled={!inputValue.trim()}
                                                className="w-10 h-10 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-600 text-white flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:from-emerald-700 hover:to-teal-700 transition-all"
                                            >
                                                <Send size={18} />
                                            </button>
                                        </form>
                                    </div>

                                    {/* Footer */}
                                    <div className="px-4 pb-3 flex items-center justify-center gap-4 text-xs text-slate-400">
                                        <a href="tel:+902121234567" className="flex items-center gap-1 hover:text-emerald-600 transition-colors">
                                            <Phone size={12} />
                                            Ara
                                        </a>
                                        <a href="mailto:destek@pazaryonetimi.com" className="flex items-center gap-1 hover:text-emerald-600 transition-colors">
                                            <Mail size={12} />
                                            E-posta
                                        </a>
                                        <a href="/support" className="flex items-center gap-1 hover:text-emerald-600 transition-colors">
                                            <HelpCircle size={12} />
                                            Yardım
                                        </a>
                                    </div>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </motion.div>
                )}
            </AnimatePresence>
        </>
    );
}

'use client';

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Activity, ShoppingCart, AlertCircle, CheckCircle2, RefreshCcw, Truck, MessageSquare, Boxes, Zap, Loader2, X } from 'lucide-react';
import { useActivityFeed, useAiSummary } from '@/lib/hooks';

interface LiveFeedProps {
    isOpen: boolean;
    onToggle: () => void;
}

const TYPE_CONFIG: Record<string, { icon: any; color: string; bg: string }> = {
    order: { icon: ShoppingCart, color: 'text-blue-500', bg: 'bg-blue-500/10' },
    sale: { icon: Zap, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
    stock: { icon: AlertCircle, color: 'text-orange-500', bg: 'bg-orange-500/10' },
    shipping: { icon: Truck, color: 'text-purple-500', bg: 'bg-purple-500/10' },
    review: { icon: MessageSquare, color: 'text-pink-500', bg: 'bg-pink-500/10' },
    campaign: { icon: Boxes, color: 'text-violet-500', bg: 'bg-violet-500/10' },
    system: { icon: RefreshCcw, color: 'text-slate-500', bg: 'bg-slate-500/10' },
};

export default function LiveFeed({ isOpen, onToggle }: LiveFeedProps) {
    const { data: activities, loading: feedLoading } = useActivityFeed(8);
    const { data: aiSummary, loading: summaryLoading } = useAiSummary();

    const formatTime = (dateStr: string) => {
        const date = new Date(dateStr);
        const now = new Date();
        const diffInMins = Math.floor((now.getTime() - date.getTime()) / (1000 * 60));

        if (diffInMins < 1) return 'Az önce';
        if (diffInMins < 60) return `${diffInMins} dk önce`;
        if (diffInMins < 1440) return `${Math.floor(diffInMins / 60)} sa önce`;
        return date.toLocaleDateString('tr-TR');
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ width: 0, opacity: 0, x: 20 }}
                    animate={{ width: 320, opacity: 1, x: 0 }}
                    exit={{ width: 0, opacity: 0, x: 20 }}
                    transition={{ type: "spring", damping: 25, stiffness: 200 }}
                    className="border-l border-border bg-surface/30 backdrop-blur-md sticky top-20 h-[calc(100vh-80px)] overflow-y-auto hidden xl:flex flex-col p-6 z-30"
                >
                    <div className="flex items-center justify-between mb-8">
                        <div className="flex items-center gap-2">
                            <Activity size={18} className="text-primary animate-pulse" />
                            <h3 className="text-sm font-black uppercase tracking-widest text-foreground">Canlı Akış</h3>
                        </div>
                        <div className="flex items-center gap-3">
                            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                            <button
                                onClick={onToggle}
                                className="p-1.5 hover:bg-white/5 rounded-lg text-slate-400 hover:text-foreground transition-all"
                                title="Kapat"
                            >
                                <X size={16} />
                            </button>
                        </div>
                    </div>

            <div className="space-y-6 flex-1">
                {feedLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 gap-3 opacity-50">
                        <Loader2 className="w-6 h-6 animate-spin text-primary" />
                        <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Yükleniyor...</span>
                    </div>
                ) : activities && activities.length > 0 ? (
                    activities.map((activity, idx) => {
                        const config = TYPE_CONFIG[activity.type] || TYPE_CONFIG.system;
                        const Icon = config.icon;

                        return (
                            <motion.div
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: idx * 0.05 }}
                                key={activity.id}
                                className="relative pl-6 group"
                            >
                                {/* Line */}
                                {idx !== activities.length - 1 && (
                                    <div className="absolute left-[11px] top-6 bottom-[-24px] w-px bg-border group-hover:bg-primary/30 transition-colors" />
                                )}

                                <div className={`absolute left-0 top-1 w-6 h-6 rounded-lg ${config.bg} flex items-center justify-center border border-white/5`}>
                                    <Icon size={12} className={config.color} />
                                </div>

                                <div className="space-y-1">
                                    <p className="text-xs font-bold text-foreground leading-tight">
                                        {activity.title}
                                        {activity.value && <span className="ml-1 text-primary">({activity.value})</span>}
                                    </p>
                                    <p className="text-[10px] text-slate-500 line-clamp-1">{activity.description}</p>
                                    <span className="text-[9px] font-bold text-slate-600 uppercase tracking-tighter">{formatTime(activity.time)}</span>
                                </div>
                            </motion.div>
                        );
                    })
                ) : (
                    <div className="text-center py-10">
                        <p className="text-xs text-slate-500 italic">Henüz aktivite bulunmuyor.</p>
                    </div>
                )}
            </div>

            <div className="mt-auto pt-8">
                <AnimatePresence mode="wait">
                    {summaryLoading ? (
                        <div className="h-20 bg-white/5 rounded-2xl animate-pulse" />
                    ) : aiSummary?.predictionText && (
                        <motion.div
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="bg-gradient-to-br from-blue-600/10 to-purple-600/10 border border-blue-500/20 rounded-2xl p-4"
                        >
                            <div className="flex items-center gap-2 mb-2">
                                <Zap className="w-3 h-3 text-blue-400" />
                                <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest">AI İÇGÖRÜSÜ</p>
                            </div>
                            <p className="text-xs font-medium text-slate-300 leading-relaxed italic">
                                "{aiSummary.predictionText}"
                            </p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </motion.div>
    )}
</AnimatePresence>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Link from 'next/link';
import {
    ArrowRight, Moon, Sun, Menu, X, ChevronDown, ChevronRight,
    Zap, BarChart3, Package, Users, Globe, Shield, Layers, Cpu,
    BookOpen, Video, Calendar, Award, FileText, HelpCircle, GraduationCap,
    Building2, Newspaper, Briefcase, Gift, MessageCircle, Heart, Target,
    ShoppingBag, Store, Boxes, TrendingUp, PieChart, ClipboardList,
    Truck, CreditCard, Bell, Settings, Sparkles, Play, ArrowUpRight,
    ExternalLink, Rocket, Star, Hexagon, Brain, DollarSign, Shirt,
    Laptop, Apple, LayoutDashboard, LogOut
} from 'lucide-react';
import { useTheme } from '@/providers/theme-provider';
import { motion, AnimatePresence } from 'framer-motion';
import { useSession, signOut } from 'next-auth/react';

// ─── Types ────────────────────────────────────────────
interface MegaMenuColumn {
    title: string;
    icon?: React.ElementType;
    items: {
        label: string;
        href: string;
        description?: string;
        icon?: React.ElementType;
        badge?: string;
        isNew?: boolean;
        color?: string;
    }[];
}

interface MegaMenuItem {
    label: string;
    megaMenu?: {
        columns: MegaMenuColumn[];
        featured?: {
            title: string;
            description: string;
            href: string;
            image?: string;
            badge?: string;
            gradient?: string;
        };
