        <div>
          <h4 className="font-semibold">{schedule.name}</h4>
          <p className="text-xs text-gray-500 mt-1">
            {schedule.frequency === 'daily' ? 'Her Gün' : schedule.frequency === 'weekly' ? 'Haftalık' : 'Aylık'}
          </p>
        </div>
        <button
          onClick={() => onToggle(schedule.id)}
          className={`p-2 rounded-lg ${
            schedule.enabled
              ? 'bg-green-100 dark:bg-green-500/20 text-green-600 dark:text-green-400'
              : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'
          }`}
        >
          {schedule.enabled ? <Play className="w-5 h-5" /> : <Pause className="w-5 h-5" />}
        </button>
      </div>

      <div className="space-y-2 text-sm mb-3">
        <div className="flex items-center justify-between">
          <span className="text-gray-600 dark:text-gray-400">Saat</span>
          <span className="font-semibold">{schedule.time}</span>
        </div>
        <div className="flex items-center justify-between">
          <span className="text-gray-600 dark:text-gray-400">Saklama</span>
          <span className="font-semibold">{schedule.retentionDays} gün</span>
        </div>
        <div className="flex items-center justify-between">
          <span className="text-gray-600 dark:text-gray-400">Son Çalışma</span>
          <span className="font-semibold">{schedule.lastRun.toLocaleDateString('tr-TR')}</span>
        </div>
      </div>

      <button className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 text-sm font-medium">
        Düzenle
      </button>
    </motion.div>
  );
}

// Main Component
export function BackupManagement() {
  const [activeTab, setActiveTab] = useState<'backups' | 'schedules' | 'restore'>('backups');
  const [localBackups, setLocalBackups] = useState(backups);
  const [localSchedules, setLocalSchedules] = useState(schedules);
  const [showNewBackupModal, setShowNewBackupModal] = useState(false);
  const [showRestoreModal, setShowRestoreModal] = useState(false);

  const totalBackupSize = localBackups.reduce((sum, b) => sum + b.compressedSize, 0);
  const completedBackups = localBackups.filter(b => b.status === 'completed').length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold flex items-center gap-2">
            <HardDrive className="w-8 h-8 text-blue-600" />
            Yedek & Kurtarma
          </h2>
          <p className="text-gray-500 mt-1">Otomatik yedekleme ve afet kurtarma yönetimi</p>
        </div>

        <div className="flex gap-2">
          <button
            onClick={() => setShowNewBackupModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            <Plus className="w-4 h-4" />
            Manuel Yedek
          </button>
          <button
            onClick={() => setShowRestoreModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
          >
            <RotateCcw className="w-4 h-4" />
            Geri Yükle
          </button>
        </div>
      </div>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
        >
          <p className="text-gray-600 dark:text-gray-400 text-sm">Toplam Yedek Boyutu</p>
          <p className="text-2xl font-bold mt-2">{(totalBackupSize / 1024).toFixed(1)} GB</p>
          <p className="text-xs text-gray-500 mt-1">3 yedekten</p>
        </motion.div>

        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
        >
          <p className="text-gray-600 dark:text-gray-400 text-sm">Başarılı Yedekler</p>
          <p className="text-2xl font-bold mt-2">{completedBackups}</p>
          <p className="text-xs text-green-600 dark:text-green-400 mt-1">Son 30 gün</p>
        </motion.div>

        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
        >
          <p className="text-gray-600 dark:text-gray-400 text-sm">RTO (Kurtarma Süresi)</p>
          <p className="text-2xl font-bold mt-2">4 saat</p>
          <p className="text-xs text-gray-500 mt-1">Maksimum hedef</p>
        </motion.div>

        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
        >
          <p className="text-gray-600 dark:text-gray-400 text-sm">RPO (Veri Kaybı)</p>
          <p className="text-2xl font-bold mt-2">1 saat</p>
          <p className="text-xs text-gray-500 mt-1">Hedef veri kaybı</p>
        </motion.div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-gray-200 dark:border-gray-700">
        {[
          { id: 'backups', label: '📦 Yedekler', icon: Archive },
          { id: 'schedules', label: '⏰ Zamanlamalar', icon: Calendar },
          { id: 'restore', label: '↩️ Geri Yükleme', icon: RotateCcw },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-4 py-3 font-medium border-b-2 transition-colors ${
              activeTab === tab.id
                ? 'border-blue-600 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-300'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content */}
      <AnimatePresence mode="wait">
        {activeTab === 'backups' && (
          <motion.div
            key="backups"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-4"
          >
            {localBackups.map(backup => (
              <BackupCard key={backup.id} backup={backup} />
            ))}
          </motion.div>
        )}

        {activeTab === 'schedules' && (
          <motion.div
            key="schedules"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="grid grid-cols-1 md:grid-cols-2 gap-4"
          >
            {localSchedules.map(schedule => (
              <ScheduleCard
                key={schedule.id}
                schedule={schedule}
                onToggle={(id) =>
                  setLocalSchedules(prev =>
                    prev.map(s => (s.id === id ? { ...s, enabled: !s.enabled } : s))
                  )
                }
              />
            ))}
          </motion.div>
        )}

        {activeTab === 'restore' && (
          <motion.div
            key="restore"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-4"
          >
            {restorePoints.map(point => (
              <div
                key={point.id}
                className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
              >
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <h4 className="font-semibold">{point.description}</h4>
                    <p className="text-xs text-gray-500 mt-1">
                      {point.timestamp.toLocaleString('tr-TR')}
                    </p>
                  </div>
                  <button className="px-3 py-1 bg-green-100 dark:bg-green-500/20 text-green-700 dark:text-green-400 rounded-lg text-sm font-medium hover:bg-green-200 dark:hover:bg-green-500/30">
                    Geri Yükle
                  </button>
                </div>

                <div className="grid grid-cols-3 gap-3 text-sm">
                  <div>
                    <p className="text-gray-500 dark:text-gray-400">Boyut</p>
                    <p className="font-semibold">{point.sizeGB} GB</p>
                  </div>
                  <div>
                    <p className="text-gray-500 dark:text-gray-400">RTO</p>
                    <p className="font-semibold">{point.rto} dk</p>
                  </div>
                  <div>
                    <p className="text-gray-500 dark:text-gray-400">RPO</p>
                    <p className="font-semibold">{point.rpo} dk</p>
                  </div>
                </div>
              </div>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Info Box */}
      <div className="bg-blue-50 dark:bg-blue-500/10 rounded-lg p-4 border border-blue-200 dark:border-blue-500/30">
        <p className="text-sm text-blue-800 dark:text-blue-300">
          <strong>Bilgi:</strong> Sistem otomatik olarak günde 1 tam ve saatte 1 artımsal yedek alıyor. Tüm yedekler coğrafik olarak farklı veri merkezlerinde depolanıyor.
        </p>
      </div>
    </div>
  );
}

export default BackupManagement;

"use client";

import React, { useState } from 'react';
import {
    Bell,
    Settings,
    Check,
    Clock,
    ShoppingBag,
    AlertTriangle,
    TrendingUp,
    MessageSquare,
    Globe,
    Zap,
    Trash2
} from 'lucide-react';
import { useNotifications, RealtimeNotification } from '@/providers/notification-provider';
import { formatDistanceToNow } from 'date-fns';
import { tr } from 'date-fns/locale';

export const NotificationCenter = () => {
    const [isOpen, setIsOpen] = useState(false);
    const { notifications, unreadCount, markAsRead, markAllAsRead, clearAll } = useNotifications();

    const getIcon = (type: RealtimeNotification['type'], severity: RealtimeNotification['severity']) => {
        switch (type) {
            case 'order': return <ShoppingBag className="text-green-500" size={16} />;
            case 'stock': return <AlertTriangle className="text-amber-500" size={16} />;
            case 'price': return <TrendingUp className="text-blue-500" size={16} />;
            case 'review': return <MessageSquare className="text-purple-500" size={16} />;
            case 'system': return <Zap className="text-orange-500" size={16} />;
            case 'integration': return <Globe className="text-slate-500" size={16} />;
            default: return <Bell className="text-slate-400" size={16} />;
        }
    };

    return (
        <div className="relative">
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="p-2 rounded-lg bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 transition-colors relative group"
            >
                <Bell size={18} className="text-slate-600 dark:text-slate-400 group-hover:scale-110 transition-transform" />
                {unreadCount > 0 && (
                    <span className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white dark:border-slate-900 animate-in zoom-in">
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </span>
                )}
            </button>

            {isOpen && (
                <>
                    <div
                        className="fixed inset-0 z-40"
                        onClick={() => setIsOpen(false)}
                    />
                    <div className="absolute right-0 mt-2 w-80 bg-white dark:bg-slate-950 border border-slate-200 dark:border-white/10 rounded-2xl shadow-2xl z-50 overflow-hidden animate-in slide-in-from-top-2 duration-200">
                        {/* Header */}
                        <div className="p-4 border-b border-slate-100 dark:border-white/5 flex items-center justify-between bg-slate-50/50 dark:bg-white/5">
                            <h3 className="text-xs font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">BİLDİRİMLER</h3>
                            <div className="flex gap-2">
                                <button
                                    onClick={markAllAsRead}
                                    title="Tümünü okundu işaretle"
                                    className="p-1.5 hover:bg-slate-200 dark:hover:bg-white/10 rounded-lg text-slate-500 transition-colors"
                                >
                                    <Check size={14} />
                                </button>
                                <button
                                    onClick={clearAll}
                                    title="Tümünü temizle"
                                    className="p-1.5 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg text-red-500 transition-colors"
                                >
                                    <Trash2 size={14} />
                                </button>
                            </div>
                        </div>

                        {/* List */}
                        <div className="max-h-[400px] overflow-y-auto scrollbar-thin">
                            {notifications.length === 0 ? (
                                <div className="p-12 flex flex-col items-center justify-center text-center">
                                    <div className="w-12 h-12 rounded-full bg-slate-100 dark:bg-white/5 flex items-center justify-center mb-3">
                                        <Bell size={20} className="text-slate-300" />
                                    </div>
                                    <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Henüz bildirim yok</p>
                                </div>
                            ) : (
                                notifications.map((notification) => (
                                    <div
                                        key={notification.id}
                                        onClick={() => markAsRead(notification.id)}
                                        className={`p-4 border-b border-slate-100 dark:border-white/5 flex gap-3 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors cursor-pointer relative group ${!notification.read ? 'bg-purple-50/30 dark:bg-purple-500/5' : ''}`}
                                    >
                                        {!notification.read && (
                                            <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-purple-500" />
                                        )}
                                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${notification.severity === 'success' ? 'bg-green-100 dark:bg-green-500/10' :
                                                notification.severity === 'error' ? 'bg-red-100 dark:bg-red-500/10' :
                                                    notification.severity === 'warning' ? 'bg-amber-100 dark:bg-amber-500/10' : 'bg-blue-100 dark:bg-blue-500/10'
                                            }`}>
                                            {getIcon(notification.type, notification.severity)}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center justify-between gap-2">
                                                <h4 className="text-[13px] font-bold text-slate-900 dark:text-white truncate">{notification.title}</h4>
                                                <span className="text-[10px] text-slate-400 whitespace-nowrap">
                                                    {formatDistanceToNow(new Date(notification.timestamp), { addSuffix: true, locale: tr })}
                                                </span>
                                            </div>
                                            <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5 line-clamp-2">{notification.message}</p>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>

                        {/* Footer */}
                        <div className="p-3 border-t border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5 text-center">
                            <button className="text-[11px] font-black uppercase tracking-widest text-purple-600 dark:text-purple-400 hover:text-purple-700 dark:hover:text-purple-300 transition-colors">
                                TÜM BİLDİRİMLERİ GÖR
                            </button>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
};

