                  </label>
                  <select
                    value={filters.action || ''}
                    onChange={e => setFilters({ ...filters, action: e.target.value || undefined })}
                    className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-transparent"
