// Types
export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  image?: string;
  variant?: string;
}

export interface CustomerInfo {
  fullName: string;
  email: string;
  phone: string;
  companyName?: string;
}

export interface OrderData {
  items: CartItem[];
  customer: CustomerInfo;
  paymentMethod: 'credit_card' | 'bank_transfer';
  subtotal: number;
  discount: number;
  shippingCost: number;
  total: number;
  couponCode?: string;
}

type CheckoutStep = 'cart' | 'shipping' | 'payment' | 'confirmation' | 'result';

// Step indicator component
function StepIndicator({
  steps,
  currentStep
}: {
  steps: { id: CheckoutStep; label: string; icon: any }[];
  currentStep: CheckoutStep;
}) {
  const currentIndex = steps.findIndex(s => s.id === currentStep);

  return (
    <div className="flex items-center justify-center mb-8">
      {steps.map((step, index) => {
        const Icon = step.icon;
        const isActive = index === currentIndex;
        const isCompleted = index < currentIndex;

        return (
          <div key={step.id} className="flex items-center">
            <motion.div
              initial={false}
              animate={{
                scale: isActive ? 1.1 : 1,
                backgroundColor: isCompleted
                  ? '#10B981'
                  : isActive
                    ? '#3B82F6'
                    : '#E5E7EB',
              }}
              className={`
                relative flex items-center justify-center w-12 h-12 rounded-full
                ${isActive || isCompleted ? 'text-white' : 'text-gray-500'}
                transition-colors duration-300
              `}
            >
              {isCompleted ? (
                <Check className="w-6 h-6" />
              ) : (
                <Icon className="w-5 h-5" />
              )}

              {isActive && (
                <motion.div
                  layoutId="activeStep"
                  className="absolute inset-0 rounded-full border-4 border-blue-300"
                  initial={false}
                  animate={{ scale: [1, 1.2, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
              )}
            </motion.div>

            <span className={`
              hidden sm:block ml-2 text-sm font-medium
              ${isActive ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500'}
            `}>
              {step.label}
            </span>

            {index < steps.length - 1 && (
              <div className="w-8 sm:w-16 h-1 mx-2 sm:mx-4 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
                <motion.div
                  initial={{ width: 0 }}
                  animate={{ width: isCompleted ? '100%' : '0%' }}
                  className="h-full bg-green-500"
                  transition={{ duration: 0.5 }}
                />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

