                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.8 }}
                      transition={{ type: "spring", stiffness: 200, damping: 15 }}
                      className="text-center py-10 px-4 relative overflow-hidden"
