import { motion, AnimatePresence } from 'framer-motion';
import {
  Send,
  Sparkles,
  MessageSquare,
  History,
  Plus,
  MoreVertical,
  Archive,
  Trash2,
  Edit3,
  Bot,
  User,
  Loader2,
  CheckCircle2,
  AlertCircle,
  Clock,
  RefreshCw,
  ChevronRight,
  Tag,
  Layers,
  Package,
  Palette,
  Upload,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
  metadata?: {
    action?: string;
    data?: any;
    status?: 'pending' | 'completed' | 'failed';
  };
}

interface Conversation {
  id: string;
  title: string;
  messages: Message[];
  status: 'active' | 'archived';
  createdAt: Date;
  updatedAt: Date;
}

interface QuickAction {
  id: string;
  label: string;
  icon: React.ReactNode;
  description: string;
  onClick: () => void;
}

interface AIAssistantChatProps {
  className?: string;
}

export function AIAssistantChat({ className }: AIAssistantChatProps) {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [activeConversation, setActiveConversation] = useState<Conversation | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [activeConversation?.messages]);

  // Load conversations on mount
  useEffect(() => {
    loadConversations();
  }, []);

  const loadConversations = async () => {
    try {
      const response = await fetch('/api/ai-assistant/conversations');
      if (response.ok) {
        const data = await response.json();
        setConversations(data);
      }
    } catch (error) {
      console.error('Failed to load conversations:', error);
    }
  };

  const createNewConversation = async () => {
    try {
      const response = await fetch('/api/ai-assistant/conversations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: 'Yeni Konuşma' }),
      });

      if (response.ok) {
        const newConversation = await response.json();
        setConversations(prev => [newConversation, ...prev]);
        setActiveConversation(newConversation);
      }
    } catch (error) {
      console.error('Failed to create conversation:', error);
    }
  };

  const sendMessage = async () => {
    if (!input.trim() || isLoading) return;

    const messageContent = input.trim();
    setInput('');
    setIsLoading(true);

    try {
      const response = await fetch('/api/ai-assistant/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content: messageContent,
          conversationId: activeConversation?.id,
        }),
      });

      if (response.ok) {
        const data = await response.json();

        if (!activeConversation) {
          // New conversation was created
          setActiveConversation({
            id: data.conversationId,
            title: 'Yeni Konuşma',
            messages: [
              { id: '1', role: 'user', content: messageContent, timestamp: new Date() },
              { id: '2', role: 'assistant', content: data.message.content, timestamp: new Date(), metadata: data.message.metadata },
            ],
            status: 'active',
            createdAt: new Date(),
            updatedAt: new Date(),
          });
        } else {
          // Add to existing conversation
          setActiveConversation(prev => {
            if (!prev) return null;
            return {
              ...prev,
              messages: [
                ...prev.messages,
                { id: Date.now().toString(), role: 'user', content: messageContent, timestamp: new Date() },
                { id: (Date.now() + 1).toString(), role: 'assistant', content: data.message.content, timestamp: new Date(), metadata: data.message.metadata },
              ],
              updatedAt: new Date(),
            };
          });
        }

        loadConversations(); // Refresh sidebar
      }
    } catch (error) {
      console.error('Failed to send message:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const quickActions: QuickAction[] = [
    {
      id: 'brand-sync',
      label: 'Marka Eşitleme',
      icon: <Tag className="w-4 h-4" />,
      description: 'Pazaryerlerinden markaları çek ve senkronize et',
      onClick: () => handleQuickAction('Marka eşitleme işlemi başlatıldı. Hangi pazaryerinden marka eşitlemek istediğinizi belirtin? (Trendyol, Amazon, vb.)'),
    },
    {
      id: 'category-sync',
      label: 'Kategori Eşitleme',
      icon: <Layers className="w-4 h-4" />,
      description: 'Kategori hiyerarşilerini ve özelliklerini eşitle',
      onClick: () => handleQuickAction('Kategori eşitleme işlemi başlatıldı. Hangi pazaryerinden kategori eşitlemek istediğinizi belirtin?'),
    },
    {
      id: 'product-upload',
      label: 'Ürün Yükleme',
      icon: <Package className="w-4 h-4" />,
      description: 'Tekli veya toplu ürün yükleme işlemi yap',
      onClick: () => handleQuickAction('Ürün yükleme işlemi başlatıldı. Yüklemek istediğiniz ürünün SKU veya ID\'sini belirtin.'),
    },
    {
      id: 'variant-manage',
      label: 'Varyant İşlemleri',
      icon: <Palette className="w-4 h-4" />,
      description: 'Varyant senkronizasyonu ve yönetimi',
      onClick: () => handleQuickAction('Varyant yönetimi başlatıldı. Hangi ürünün varyantlarını yönetmek istediğinizi belirtin.'),
    },
    {
      id: 'bulk-upload',
      label: 'Toplu Yükleme',
      icon: <Upload className="w-4 h-4" />,
      description: 'Excel/CSV ile toplu ürün yükleme',
      onClick: () => handleQuickAction('Toplu yükleme işlemi başlatıldı. Excel veya CSV dosyanızı yükleyebilirsiniz.'),
    },
  ];

  const handleQuickAction = async (initialMessage: string) => {
    await createNewConversation();
    // The user will see the initial message and can respond
  };

  const executeQuickAction = async (actionId: string, platform?: string) => {
    const action = quickActions.find(a => a.id === actionId);
    if (!action) return;

    let endpoint = '';
    switch (actionId) {
      case 'brand-sync':
        endpoint = '/api/ai-assistant/quick/brand-sync';
        break;
      case 'category-sync':
        endpoint = '/api/ai-assistant/quick/category-sync';
        break;
      case 'product-upload':
        endpoint = '/api/ai-assistant/quick/product-upload';
        break;
      default:
        return;
    }

    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ platform }),
      });

      if (response.ok) {
        const data = await response.json();
        setActiveConversation({
          id: data.conversationId,
          title: action.label,
          messages: [
            { id: '1', role: 'assistant', content: data.message.content, timestamp: new Date(), metadata: data.message.metadata },
          ],
          status: 'active',
          createdAt: new Date(),
          updatedAt: new Date(),
        });
        loadConversations();
      }
    } catch (error) {
      console.error('Quick action failed:', error);
    }
  };

  return (
    <div className={cn('flex h-full bg-white dark:bg-slate-900 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700 shadow-xl', className)}>
      {/* Sidebar */}
      <AnimatePresence mode="wait">
        {sidebarOpen && (
          <motion.div
            initial={{ width: 0, opacity: 0 }}
            animate={{ width: 320, opacity: 1 }}
            exit={{ width: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="border-r border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 flex flex-col"
          >
            {/* Header */}
            <div className="p-4 border-b border-slate-200 dark:border-slate-700">
              <button
                onClick={createNewConversation}
                className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-lg font-medium transition-colors"
              >
                <Plus className="w-5 h-5" />
                Yeni Konuşma
              </button>
            </div>

            {/* Conversations List */}
            <div className="flex-1 overflow-y-auto p-3 space-y-1">
              <div className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider px-2 py-2">
                Konuşmalar
              </div>
              {conversations.map((conv) => (
                <button
                  key={conv.id}
                  onClick={() => setActiveConversation(conv)}
                  className={cn(
                    'w-full flex items-start gap-3 p-3 rounded-lg text-left transition-colors',
                    activeConversation?.id === conv.id
                      ? 'bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800'
                      : 'hover:bg-slate-100 dark:hover:bg-slate-700/50'
                  )}
                >
                  <MessageSquare className="w-4 h-4 mt-0.5 text-slate-400" />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-slate-900 dark:text-slate-100 truncate">
                      {conv.title}
                    </p>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                      {new Date(conv.updatedAt).toLocaleDateString('tr-TR')}
                    </p>
                  </div>
                  {conv.status === 'archived' && <Archive className="w-3 h-3 text-slate-400" />}
                </button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Chat Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setSidebarOpen(!sidebarOpen)}
              className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
            >
              <History className="w-5 h-5 text-slate-600 dark:text-slate-400" />
            </button>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center">
                <Sparkles className="w-4 h-4 text-white" />
              </div>
              <div>
                <h2 className="font-semibold text-slate-900 dark:text-slate-100">
                  Sopyo AI Asistan
                </h2>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  Pazaryeri Yönetimi AI
                </p>
              </div>
            </div>
          </div>

          {activeConversation && (
            <div className="flex items-center gap-1">
              <button
                onClick={() => {}}
                className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                title="Konuşmayı düzenle"
              >
                <Edit3 className="w-4 h-4 text-slate-600 dark:text-slate-400" />
              </button>
              <button
                onClick={() => {}}
                className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                title="Arşivle"
              >
                <Archive className="w-4 h-4 text-slate-600 dark:text-slate-400" />
              </button>
              <button
                onClick={() => {}}
                className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                title="Sil"
              >
                <Trash2 className="w-4 h-4 text-red-500" />
              </button>
            </div>
          )}
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {!activeConversation ? (
            // Welcome Screen with Quick Actions
            <div className="h-full flex flex-col items-center justify-center max-w-2xl mx-auto">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-center mb-8"
              >
                <div className="w-16 h-16 bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                  <Bot className="w-8 h-8 text-white" />
                </div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100 mb-2">
                  Sopyo AI Asistan'a Hoş Geldiniz
                </h1>
                <p className="text-slate-600 dark:text-slate-400">
                  E-ticaret ve pazaryeri yönetiminde size yardımcı olmak için buradayım.
                </p>
              </motion.div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full">
                {quickActions.map((action) => (
                  <button
                    key={action.id}
                    onClick={() => executeQuickAction(action.id)}
                    className="flex items-start gap-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:border-blue-300 dark:hover:border-blue-700 hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all text-left group"
                  >
                    <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg group-hover:bg-blue-200 dark:group-hover:bg-blue-900/50 transition-colors">
                      {action.icon}
                    </div>
                    <div>
                      <h3 className="font-medium text-slate-900 dark:text-slate-100">
                        {action.label}
                      </h3>
                      <p className="text-sm text-slate-500 dark:text-slate-400 mt-0.5">
                        {action.description}
                      </p>
                    </div>
                    <ChevronRight className="w-4 h-4 text-slate-400 ml-auto self-center opacity-0 group-hover:opacity-100 transition-opacity" />
                  </button>
                ))}
              </div>
            </div>
          ) : (
            // Active Conversation
            <>
              {activeConversation.messages.map((message, index) => (
                <motion.div
                  key={message.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.05 }}
                  className={cn(
                    'flex gap-3',
                    message.role === 'user' ? 'justify-end' : 'justify-start'
                  )}
                >
                  {message.role === 'assistant' && (
                    <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center flex-shrink-0">
                      <Bot className="w-4 h-4 text-white" />
                    </div>
                  )}

                  <div
                    className={cn(
                      'max-w-[80%] rounded-2xl px-4 py-3',
                      message.role === 'user'
                        ? 'bg-blue-600 text-white rounded-br-md'
                        : 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-bl-md'
                    )}
                  >
                    <div className="prose prose-sm dark:prose-invert max-w-none">
                      {message.content.split('\n').map((line, i) => (
                        <p key={i} className={cn('mb-1 last:mb-0', line.startsWith('**') && 'font-semibold')}>
                          {line.replace(/\*\*/g, '')}
                        </p>
                      ))}
                    </div>

                    {/* Status Badge */}
                    {message.metadata?.status && (
                      <div className="flex items-center gap-1.5 mt-2 pt-2 border-t border-slate-200 dark:border-slate-700">
                        {message.metadata.status === 'pending' && (
                          <>
                            <Clock className="w-3 h-3 text-amber-500" />
                            <span className="text-xs text-amber-600 dark:text-amber-400">İşlem devam ediyor...</span>
                          </>
                        )}
                        {message.metadata.status === 'completed' && (
                          <>
                            <CheckCircle2 className="w-3 h-3 text-green-500" />
                            <span className="text-xs text-green-600 dark:text-green-400">İşlem tamamlandı</span>
                          </>
                        )}
                        {message.metadata.status === 'failed' && (
                          <>
                            <AlertCircle className="w-3 h-3 text-red-500" />
                            <span className="text-xs text-red-600 dark:text-red-400">İşlem başarısız</span>
                          </>
                        )}
                      </div>
                    )}

                    <p className={cn(
                      'text-xs mt-1',
                      message.role === 'user' ? 'text-blue-200' : 'text-slate-400'
                    )}>
                      {new Date(message.timestamp).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })}
                    </p>
                  </div>

                  {message.role === 'user' && (
                    <div className="w-8 h-8 bg-slate-300 dark:bg-slate-700 rounded-lg flex items-center justify-center flex-shrink-0">
                      <User className="w-4 h-4 text-slate-600 dark:text-slate-400" />
                    </div>
                  )}
                </motion.div>
              ))}

              {isLoading && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="flex gap-3 justify-start"
                >
                  <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center flex-shrink-0">
                    <Bot className="w-4 h-4 text-white" />
                  </div>
                  <div className="bg-slate-100 dark:bg-slate-800 rounded-2xl rounded-bl-md px-4 py-3">
                    <div className="flex items-center gap-2">
                      <Loader2 className="w-4 h-4 animate-spin text-blue-600" />
                      <span className="text-sm text-slate-600 dark:text-slate-400">Yanıt yazılıyor...</span>
                    </div>
                  </div>
                </motion.div>
              )}

              <div ref={messagesEndRef} />
            </>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 border-t border-slate-200 dark:border-slate-700">
          <div className="flex items-end gap-2 max-w-4xl mx-auto">
            <div className="flex-1 relative">
              <textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                  }
                }}
                placeholder={activeConversation ? "Mesajınızı yazın..." : "Yeni konuşma başlatmak için mesaj yazın..."}
                className="w-full px-4 py-3 pr-12 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl resize-none focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent min-h-[56px] max-h-[200px] text-slate-900 dark:text-slate-100 placeholder:text-slate-400"
                rows={1}
                style={{ height: 'auto' }}
              />
            </div>
            <button
              onClick={sendMessage}
              disabled={!input.trim() || isLoading}
              className="p-3 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl transition-colors"
            >
              {isLoading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <Send className="w-5 h-5" />
              )}
            </button>
          </div>

          <p className="text-xs text-center text-slate-400 mt-2">
            AI Asistan bazı hatalar yapabilir. Önemli kararlar için lütfen bilgileri kontrol edin.
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { usePathname } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Bot, X, Send, Sparkles, Minimize2, Maximize2,
    RotateCcw, Zap, MessageSquare, TrendingUp,
    Package, ShoppingCart, DollarSign, Clipboard,
    ChevronDown, Loader2, ThumbsUp, ThumbsDown,
    ArrowRight, BarChart3, AlertTriangle, Users,
} from 'lucide-react';
import { useIsMobile } from '@/hooks/useMediaQuery';

interface Message {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    timestamp: Date;
    suggestions?: string[];
    type?: 'text' | 'briefing' | 'data';
    isLoading?: boolean;
}

interface QuickAction {
    id: string;
    icon: React.ComponentType<{ size?: number; className?: string }>;
    label: string;
    action: string;
    color: string;
}

const QUICK_ACTIONS: QuickAction[] = [
    { id: 'daily', icon: Sparkles, label: 'Günlük Brifing', action: 'daily-summary', color: 'from-blue-500 to-purple-500' },
    { id: 'orders', icon: ShoppingCart, label: 'Bekleyen Siparişler', action: 'pending-orders', color: 'from-orange-500 to-red-500' },
    { id: 'revenue', icon: DollarSign, label: 'Bugünkü Ciro', action: 'revenue-today', color: 'from-green-500 to-emerald-500' },
    { id: 'stock', icon: Package, label: 'Düşük Stok', action: 'low-stock-alert', color: 'from-yellow-500 to-orange-500' },
    { id: 'top', icon: TrendingUp, label: 'En İyi Ürünler', action: 'top-products', color: 'from-pink-500 to-rose-500' },
    { id: 'competitor', icon: BarChart3, label: 'Rakip Analizi', action: 'competitor-check', color: 'from-cyan-500 to-blue-500' },
];

export default function AICopilot() {
    const [isOpen, setIsOpen] = useState(false);
    const [isMinimized, setIsMinimized] = useState(false);
    const [messages, setMessages] = useState<Message[]>([]);
    const [input, setInput] = useState('');
    const [isTyping, setIsTyping] = useState(false);
    const [suggestions, setSuggestions] = useState<string[]>([]);
    const [showQuickActions, setShowQuickActions] = useState(true);
    const [unreadCount, setUnreadCount] = useState(0);
    const [pulseAnimation, setPulseAnimation] = useState(true);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLTextAreaElement>(null);
    const pathname = usePathname();
    const isMobile = useIsMobile();

    // Scroll to bottom
    const scrollToBottom = useCallback(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, []);

    useEffect(() => {
        scrollToBottom();
    }, [messages, scrollToBottom]);

    // Load contextual suggestions when page changes
    useEffect(() => {
        loadSuggestions();
    }, [pathname]);

    // Pulse animation timer
    useEffect(() => {
        const timer = setTimeout(() => setPulseAnimation(false), 10000);
        return () => clearTimeout(timer);
    }, []);

    const loadSuggestions = async () => {
        try {
            const res = await fetch('/api/ai/copilot/suggestions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-tenant-id': 'default' },
                body: JSON.stringify({ currentPage: pathname }),
            });
            if (res.ok) {
                const data = await res.json();
                setSuggestions(data.suggestions || []);
            }
        } catch {
            setSuggestions([]);
        }
    };

    const sendMessage = async (text: string) => {
        if (!text.trim() || isTyping) return;

        const userMessage: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: text.trim(),
            timestamp: new Date(),
        };

        setMessages(prev => [...prev, userMessage]);
        setInput('');
        setShowQuickActions(false);
        setIsTyping(true);

        // Add loading message
        const loadingId = (Date.now() + 1).toString();
        setMessages(prev => [...prev, {
            id: loadingId,
            role: 'assistant',
            content: '',
            timestamp: new Date(),
            isLoading: true,
        }]);

        try {
            const history = messages
                .filter(m => !m.isLoading)
                .slice(-10)
                .map(m => ({ role: m.role, content: m.content }));

            const res = await fetch('/api/ai/copilot/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-tenant-id': 'default' },
                body: JSON.stringify({ message: text.trim(), history, context: pathname }),
            });

            const data = res.ok
                ? await res.json()
                : { message: 'Şu anda yanıt veremiyorum. Lütfen tekrar deneyin.', suggestions: [] };

            setMessages(prev => prev.map(m =>
                m.id === loadingId
                    ? { ...m, content: data.message, isLoading: false, suggestions: data.suggestions, type: data.type }
                    : m
            ));
        } catch {
            setMessages(prev => prev.map(m =>
                m.id === loadingId
                    ? { ...m, content: 'Bağlantı hatası oluştu. Lütfen tekrar deneyin.', isLoading: false }
                    : m
            ));
        } finally {
            setIsTyping(false);
        }
    };

    const handleQuickAction = async (action: string) => {
        setShowQuickActions(false);
        setIsTyping(true);

        const loadingId = Date.now().toString();
        setMessages(prev => [...prev, {
            id: loadingId,
            role: 'assistant',
            content: '',
            timestamp: new Date(),
            isLoading: true,
        }]);

        try {
            const res = await fetch('/api/ai/copilot/quick-action', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-tenant-id': 'default' },
                body: JSON.stringify({ action }),
            });

            const data = res.ok ? await res.json() : { message: 'Aksiyon yürütülemedi.' };

            setMessages(prev => prev.map(m =>
                m.id === loadingId
                    ? { ...m, content: data.message, isLoading: false, type: data.type }
                    : m
            ));
        } catch {
            setMessages(prev => prev.map(m =>
                m.id === loadingId
                    ? { ...m, content: 'Bağlantı hatası.', isLoading: false }
                    : m
            ));
        } finally {
            setIsTyping(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage(input);
        }
    };

    const clearChat = () => {
        setMessages([]);
        setShowQuickActions(true);
    };

    const toggleOpen = () => {
        setIsOpen(!isOpen);
        setIsMinimized(false);
        setUnreadCount(0);
        if (!isOpen) {
            setPulseAnimation(false);
            setTimeout(() => inputRef.current?.focus(), 300);
        }
    };

    const renderMarkdown = (text: string) => {
        return text
            .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
            .replace(/\*(.*?)\*/g, '<em>$1</em>')
            .replace(/`(.*?)`/g, '<code class="bg-slate-700/50 px-1 py-0.5 rounded text-xs">$1</code>')
            .replace(/\n/g, '<br/>');
    };

    return (
        <>
            {/* Floating Button */}
            <AnimatePresence>
                {!isOpen && !isMobile && (
                    <motion.button
                        initial={{ scale: 0, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        exit={{ scale: 0, opacity: 0 }}
                        onClick={toggleOpen}
                        className={`fixed bottom-6 right-6 z-[100] w-14 h-14 rounded-2xl bg-gradient-to-br from-primary to-purple-600 text-white shadow-2xl shadow-primary/30 flex items-center justify-center hover:scale-110 transition-transform group ${pulseAnimation ? 'animate-bounce' : ''}`}
                    >
                        <Bot size={24} className="group-hover:rotate-12 transition-transform" />
                        {unreadCount > 0 && (
                            <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full text-[10px] font-bold flex items-center justify-center">
                                {unreadCount}
                            </span>
                        )}
                        {/* Glow ring */}
                        <div className="absolute inset-0 rounded-2xl bg-primary/20 animate-ping pointer-events-none" style={{ animationDuration: '3s' }} />
                    </motion.button>
                )}
            </AnimatePresence>

            {/* Chat Window */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 20, scale: 0.95 }}
                        animate={{
                            opacity: 1,
                            y: 0,
                            scale: 1,
                            height: isMinimized ? 60 : 'auto',
                        }}
                        exit={{ opacity: 0, y: 20, scale: 0.95 }}
                        transition={{ type: 'spring', damping: 25, stiffness: 300 }}
                        className="fixed bottom-6 right-6 z-[100] w-[420px] max-h-[680px] bg-[#0d1117] border border-slate-700/50 rounded-2xl shadow-2xl shadow-black/40 flex flex-col overflow-hidden"
                    >
                        {/* Header */}
                        <div className="flex items-center justify-between px-4 py-3 bg-gradient-to-r from-primary/10 to-purple-600/10 border-b border-slate-700/50 shrink-0">
                            <div className="flex items-center gap-3">
                                <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-primary to-purple-600 flex items-center justify-center shadow-lg shadow-primary/20">
                                    <Bot size={18} className="text-white" />
                                </div>
                                <div>
                                    <h3 className="text-sm font-black text-white">PazarBot</h3>
                                    <div className="flex items-center gap-1.5">
                                        <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
                                        <span className="text-[10px] text-green-400 font-bold">AI Asistan Aktif</span>
                                    </div>
                                </div>
                            </div>
                            <div className="flex items-center gap-1">
                                <button onClick={clearChat} className="p-1.5 rounded-lg text-slate-500 hover:text-white hover:bg-white/5 transition-all" title="Sohbeti Temizle">
                                    <RotateCcw size={14} />
                                </button>
                                <button onClick={() => setIsMinimized(!isMinimized)} className="p-1.5 rounded-lg text-slate-500 hover:text-white hover:bg-white/5 transition-all">
                                    {isMinimized ? <Maximize2 size={14} /> : <Minimize2 size={14} />}
                                </button>
                                <button onClick={toggleOpen} className="p-1.5 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-500/10 transition-all">
                                    <X size={14} />
                                </button>
                            </div>
                        </div>

                        {!isMinimized && (
                            <>
                                {/* Messages */}
                                <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-[300px] max-h-[440px] scrollbar-thin scrollbar-thumb-slate-700">
                                    {/* Welcome */}
                                    {messages.length === 0 && (
                                        <div className="text-center py-6">
                                            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-primary/20 to-purple-600/20 flex items-center justify-center mx-auto mb-4 border border-primary/20">
                                                <Bot size={28} className="text-primary" />
                                            </div>
                                            <h4 className="text-base font-black text-white mb-1">Merhaba! 👋</h4>
                                            <p className="text-xs text-slate-500 mb-6 max-w-[280px] mx-auto">
                                                E-ticaret operasyonlarınızda size yardımcı olabilirim. Satış analizi, stok yönetimi, fiyatlama ve daha fazlası...
                                            </p>

                                            {/* Quick Actions Grid */}
                                            {showQuickActions && (
                                                <div className="grid grid-cols-2 gap-2 mb-4">
                                                    {QUICK_ACTIONS.map(qa => (
                                                        <button
                                                            key={qa.id}
                                                            onClick={() => handleQuickAction(qa.action)}
                                                            className="flex items-center gap-2 px-3 py-2.5 rounded-xl border border-slate-700/50 hover:border-primary/30 hover:bg-white/[0.02] transition-all group text-left"
                                                        >
                                                            <div className={`w-7 h-7 rounded-lg bg-gradient-to-br ${qa.color} flex items-center justify-center shrink-0`}>
                                                                <qa.icon size={13} className="text-white" />
                                                            </div>
                                                            <span className="text-[11px] font-bold text-slate-400 group-hover:text-white transition-colors">{qa.label}</span>
                                                        </button>
                                                    ))}
                                                </div>
                                            )}

                                            {/* Contextual Suggestions */}
                                            {suggestions.length > 0 && (
                                                <div className="space-y-1.5">
                                                    <p className="text-[10px] text-slate-600 uppercase tracking-wider font-bold mb-2">Önerilen Sorular</p>
                                                    {suggestions.map((s, i) => (
                                                        <button
                                                            key={i}
                                                            onClick={() => sendMessage(s)}
                                                            className="w-full text-left px-3 py-2 rounded-xl border border-slate-800 hover:border-primary/30 hover:bg-primary/5 text-xs text-slate-400 hover:text-white transition-all flex items-center gap-2"
                                                        >
                                                            <ArrowRight size={10} className="text-primary shrink-0" />
                                                            {s}
                                                        </button>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    )}

                                    {/* Messages */}
                                    {messages.map(msg => (
                                        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                            <div className={`max-w-[85%] ${msg.role === 'user' ? 'order-last' : ''}`}>
                                                {msg.role === 'assistant' && (
                                                    <div className="flex items-center gap-1.5 mb-1">
                                                        <div className="w-5 h-5 rounded-md bg-gradient-to-br from-primary to-purple-600 flex items-center justify-center">
                                                            <Bot size={10} className="text-white" />
                                                        </div>
                                                        <span className="text-[10px] text-slate-600 font-bold">PazarBot</span>
                                                    </div>
                                                )}
                                                <div className={`px-3.5 py-2.5 rounded-2xl text-[13px] leading-relaxed ${
                                                    msg.role === 'user'
                                                        ? 'bg-primary text-white rounded-br-md'
                                                        : 'bg-slate-800/80 text-slate-200 rounded-bl-md border border-slate-700/30'
                                                }`}>
                                                    {msg.isLoading ? (
                                                        <div className="flex items-center gap-2 py-1">
                                                            <Loader2 size={14} className="animate-spin text-primary" />
                                                            <span className="text-xs text-slate-400">Düşünüyorum...</span>
                                                        </div>
                                                    ) : (
                                                        <div dangerouslySetInnerHTML={{ __html: renderMarkdown(msg.content) }} />
                                                    )}
                                                </div>

                                                {/* Follow-up suggestions */}
                                                {msg.suggestions && msg.suggestions.length > 0 && !msg.isLoading && (
                                                    <div className="flex flex-wrap gap-1 mt-2">
                                                        {msg.suggestions.map((s, i) => (
                                                            <button
                                                                key={i}
                                                                onClick={() => sendMessage(s)}
                                                                className="px-2.5 py-1 rounded-full bg-primary/10 border border-primary/20 text-[10px] font-bold text-primary hover:bg-primary/20 transition-colors"
                                                            >
                                                                {s}
                                                            </button>
                                                        ))}
                                                    </div>
                                                )}

                                                {/* Feedback */}
                                                {msg.role === 'assistant' && !msg.isLoading && (
                                                    <div className="flex items-center gap-1 mt-1.5">
                                                        <button className="p-1 rounded text-slate-600 hover:text-green-400 hover:bg-green-500/10 transition-all">
                                                            <ThumbsUp size={11} />
                                                        </button>
                                                        <button className="p-1 rounded text-slate-600 hover:text-red-400 hover:bg-red-500/10 transition-all">
                                                            <ThumbsDown size={11} />
                                                        </button>
                                                        <button
                                                            onClick={() => navigator.clipboard.writeText(msg.content)}
                                                            className="p-1 rounded text-slate-600 hover:text-blue-400 hover:bg-blue-500/10 transition-all"
                                                        >
                                                            <Clipboard size={11} />
                                                        </button>
                                                    </div>
                                                )}

                                                <div className="text-[9px] text-slate-700 mt-0.5 px-1">
                                                    {msg.timestamp.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                    <div ref={messagesEndRef} />
                                </div>

                                {/* Input Area */}
                                <div className="p-3 border-t border-slate-700/50 bg-[#0d1117] shrink-0">
                                    <div className="flex items-end gap-2">
                                        <div className="flex-1 relative">
                                            <textarea
                                                ref={inputRef}
                                                value={input}
                                                onChange={e => setInput(e.target.value)}
                                                onKeyDown={handleKeyDown}
                                                placeholder="Bir şey sorun..."
                                                rows={1}
                                                className="w-full px-4 py-2.5 bg-slate-800/60 border border-slate-700/50 rounded-xl text-sm text-white placeholder:text-slate-600 focus:outline-none focus:border-primary/50 resize-none max-h-24 scrollbar-thin"
                                                style={{ minHeight: '40px' }}
                                                onInput={(e) => {
                                                    const target = e.target as HTMLTextAreaElement;
                                                    target.style.height = '40px';
                                                    target.style.height = Math.min(target.scrollHeight, 96) + 'px';
                                                }}
                                            />
                                        </div>
                                        <button
                                            onClick={() => sendMessage(input)}
                                            disabled={!input.trim() || isTyping}
                                            className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-purple-600 text-white flex items-center justify-center hover:shadow-lg hover:shadow-primary/20 disabled:opacity-30 disabled:cursor-not-allowed transition-all hover:scale-105 active:scale-95 shrink-0"
                                        >
                                            {isTyping ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
                                        </button>
                                    </div>
                                    <div className="flex items-center justify-between mt-2 px-1">
                                        <span className="text-[9px] text-slate-700">AI yanıtları bilgi amaçlıdır</span>
                                        <div className="flex items-center gap-1 text-[9px] text-slate-700">
                                            <Sparkles size={8} /> Gemini AI
                                        </div>
                                    </div>
                                </div>
                            </>
                        )}
                    </motion.div>
                )}
            </AnimatePresence>
        </>
    );
}

"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Clock, TrendingUp, Package, ShoppingCart, DollarSign,
    Users, Star, AlertTriangle, Truck, Store, CheckCircle,
    ArrowRight, Eye, MessageSquare
} from 'lucide-react';

interface TimelineEvent {
    id: string;
    type: 'order' | 'sale' | 'stock' | 'review' | 'shipping' | 'campaign' | 'system';
    title: string;
    description: string;
    time: string;
    platform?: string;
    value?: string;
    status?: 'success' | 'warning' | 'info' | 'error';
}

interface ActivityTimelineProps {
    events?: TimelineEvent[];
}

export default function ActivityTimeline({ events: propEvents }: ActivityTimelineProps) {
    const events = Array.isArray(propEvents) ? propEvents : [];
    const [filter, setFilter] = useState<string>('all');
    const [visibleCount, setVisibleCount] = useState(5);

    const getEventIcon = (type: string) => {
        switch (type) {
            case 'order': return <ShoppingCart className="w-3.5 h-3.5" />;
            case 'sale': return <DollarSign className="w-3.5 h-3.5" />;
            case 'stock': return <Package className="w-3.5 h-3.5" />;
            case 'review': return <Star className="w-3.5 h-3.5" />;
            case 'shipping': return <Truck className="w-3.5 h-3.5" />;
            case 'campaign': return <TrendingUp className="w-3.5 h-3.5" />;
            case 'system': return <CheckCircle className="w-3.5 h-3.5" />;
            default: return <Eye className="w-3.5 h-3.5" />;
        }
    };

    const getEventColor = (status: string = 'info') => {
        switch (status) {
            case 'success': return 'bg-green-500 text-white';
            case 'warning': return 'bg-amber-500 text-white';
            case 'error': return 'bg-red-500 text-white';
            default: return 'bg-blue-500 text-white';
        }
    };

    const filters = [
        { key: 'all', label: 'Tümü' },
        { key: 'order', label: 'Siparişler' },
        { key: 'stock', label: 'Stok' },
        { key: 'review', label: 'Yorumlar' },
        { key: 'shipping', label: 'Kargo' },
    ];

    const filteredEvents = filter === 'all' ? events : events.filter(e => e.type === filter);

    return (
        <div className="bg-surface rounded-2xl border border-border p-5">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                    <Clock className="w-5 h-5 text-primary" />
                    <h3 className="text-sm font-bold text-foreground">Aktivite Akışı</h3>
                    <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                </div>
            </div>

            {/* Filters */}
            <div className="flex gap-1.5 mb-4 overflow-x-auto scrollbar-hide pb-1">
                {filters.map(f => (
                    <button
                        key={f.key}
                        onClick={() => setFilter(f.key)}
                        className={`px-3 py-1 rounded-lg text-[10px] font-bold whitespace-nowrap transition-all ${
                            filter === f.key
                                ? 'bg-primary text-white'
                                : 'bg-background/50 text-slate-500 hover:text-foreground border border-border'
                        }`}
                    >
                        {f.label}
                    </button>
                ))}
            </div>

            {/* Timeline */}
            {filteredEvents.length === 0 ? (
                <div className="p-4 rounded-xl bg-background/50 border border-border text-center">
                    <p className="text-sm font-semibold text-foreground">Aktivite verisi bulunamadı</p>
                    <p className="text-xs text-slate-500 mt-1">Yeni olaylar geldiğinde burada gerçek akış görünecek.</p>
                </div>
            ) : (
            <div className="relative">
                <div className="absolute left-4 top-0 bottom-0 w-px bg-border" />

                <div className="space-y-1">
                    <AnimatePresence>
                        {filteredEvents.slice(0, visibleCount).map((event, idx) => (
                            <motion.div
                                key={event.id}
                                initial={{ opacity: 0, x: -10 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -10 }}
                                transition={{ delay: idx * 0.05 }}
                                className="flex items-start gap-3 pl-1 py-2 group"
                            >
                                <div className={`relative z-10 w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${getEventColor(event.status)}`}>
                                    {getEventIcon(event.type)}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center justify-between">
                                        <span className="text-xs font-bold text-foreground">{event.title}</span>
                                        <span className="text-[10px] text-slate-500 flex-shrink-0 ml-2">{event.time}</span>
                                    </div>
                                    <p className="text-[10px] text-slate-500 mt-0.5 truncate">{event.description}</p>
                                    <div className="flex items-center gap-2 mt-1">
                                        {event.platform && (
                                            <span className="text-[9px] font-bold bg-background/50 border border-border px-1.5 py-0.5 rounded text-slate-500">
                                                {event.platform}
                                            </span>
                                        )}
                                        {event.value && (
                                            <span className="text-[10px] font-bold text-green-500">{event.value}</span>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                </div>
            </div>
            )}

            {filteredEvents.length > visibleCount && (
                <button
                    onClick={() => setVisibleCount(v => v + 5)}
                    className="w-full mt-3 py-2 text-xs font-bold text-primary hover:bg-primary/5 rounded-xl transition-colors flex items-center justify-center gap-1"
                >
                    Daha Fazla Göster
                    <ArrowRight className="w-3 h-3" />
                </button>
            )}
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Package, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface AddProductModalProps {
    isOpen: boolean;
    onClose: () => void;
}

export default function AddProductModal({ isOpen, onClose }: AddProductModalProps) {
    const [loading, setLoading] = useState(false);
    const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
    const [errorMessage, setErrorMessage] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        sku: '',
        barcode: '',
        price: '',
        stock: '',
        category: '',
        brand: '',
        description: ''
    });

    const reset = () => {
        setFormData({
            name: '',
            sku: '',
            barcode: '',
            price: '',
            stock: '',
            category: '',
            brand: '',
            description: ''
        });
        setStatus('idle');
        setErrorMessage('');
    };

    const handleClose = () => {
        if (status !== 'idle') reset();
        onClose();
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            await apiClient.request('/products', {
                method: 'POST',
                body: JSON.stringify({
                    ...formData,
                    price: parseFloat(formData.price),
                    stock: parseInt(formData.stock, 10),
                    status: 'active'
                })
            });
            setStatus('success');
            setTimeout(() => {
                handleClose();
            }, 2000);
        } catch (err: any) {
            setStatus('error');
            setErrorMessage(err.message || 'Ürün oluşturulurken bir hata oluştu.');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                className="bg-surface rounded-2xl w-full max-w-xl overflow-hidden border border-border shadow-2xl"
            >
                {/* Header */}
                <div className="flex items-center justify-between p-6 border-b border-border bg-background/50">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-green-500/20 rounded-xl">
                            <Package className="w-5 h-5 text-green-500" />
                        </div>
                        <div>
                            <h2 className="text-lg font-bold text-foreground">Yeni Ürün Ekle</h2>
                            <p className="text-sm text-slate-500">Kataloğunuza manuel ürün ekleyin</p>
                        </div>
                    </div>
                    <button onClick={handleClose} className="p-2 hover:bg-background rounded-lg transition-colors">
                        <X className="w-5 h-5 text-slate-400" />
                    </button>
                </div>

                {/* Content */}
                <div className="p-6">
                    {status === 'success' ? (
                        <div className="flex flex-col items-center justify-center py-10 space-y-4">
                            <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center">
                                <CheckCircle2 className="w-10 h-10 text-green-500" />
                            </div>
                            <h3 className="text-xl font-bold text-foreground">Ürün Oluşturuldu</h3>
                            <p className="text-slate-500 text-center">Ürün başarıyla kataloğa eklendi.</p>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="col-span-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Ürün Adı</label>
                                    <input
                                        required
                                        type="text"
                                        value={formData.name}
                                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                        className="w-full bg-background border border-border rounded-xl px-4 py-2.5 text-foreground placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-green-500/20 transition-all"
                                        placeholder="Örn: iPhone 15 Pro Max"
                                    />
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">SKU / Model Kodu</label>
                                    <input
                                        required
                                        type="text"
                                        value={formData.sku}
                                        onChange={(e) => setFormData({ ...formData, sku: e.target.value })}
