                                <div className="col-span-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Açıklama</label>
                                    <textarea
                                        value={formData.description}
                                        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                        rows={3}
                                        className="w-full bg-background border border-border rounded-xl px-4 py-2.5 text-foreground placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-green-500/20 transition-all resize-none"
                                        placeholder="Ürün açıklaması..."
                                    />
                                </div>
                            </div>

                            {status === 'error' && (
                                <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-sm text-red-500">
                                    <AlertCircle className="w-4 h-4 flex-shrink-0" />
                                    {errorMessage}
                                </div>
                            )}

                            <div className="flex items-center gap-3 pt-2">
                                <button
                                    type="button"
                                    onClick={handleClose}
                                    className="flex-1 py-3 bg-background rounded-xl text-slate-500 hover:text-foreground transition-all border border-border font-bold text-sm"
                                >
                                    Vazgeç
                                </button>
                                <button
                                    disabled={loading}
                                    type="submit"
                                    className="flex-1 py-3 bg-green-500 hover:bg-green-600 disabled:opacity-50 text-white rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 shadow-lg shadow-green-500/20"
                                >
                                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Package className="w-4 h-4" />}
                                    Ürün Oluştur
                                </button>
                            </div>
                        </form>
                    )}
                </div>
            </motion.div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Shield, ShieldAlert, ShieldCheck, Zap, Bell, Settings } from 'lucide-react';
import { apiClient } from '@/lib/api-client';

interface DefenseAction {
    id: string;
    product: string;
    competitor: string;
    action: string;
    impact: string;
    timestamp: string;
}

interface DefenseStats {
    securityScore: number;
    threatsBlocked: number;
    revenueProtected: number;
    isActive: boolean;
    recentActions: DefenseAction[];
}

export const DefenseShieldWidget = () => {
    const [isActive, setIsActive] = useState(true);
    const [stats, setStats] = useState<DefenseStats | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchDefenseStats = async () => {
            try {
                const data = await apiClient.getSecurityOverview();
                setStats({
                    securityScore: (data as any)?.securityScore || 98.4,
                    threatsBlocked: (data as any)?.threatsBlocked || 24,
                    revenueProtected: (data as any)?.revenueProtected || 14200,
                    isActive: true,
                    recentActions: (data as any)?.recentActions || []
                });
            } catch (err) {
                console.error('Defense stats fetch failed', err);
            } finally {
                setLoading(false);
            }
        };

        fetchDefenseStats();
        const interval = setInterval(fetchDefenseStats, 30000); // 30s refresh
        return () => clearInterval(interval);
    }, []);

    const actions = stats?.recentActions || [];

    return (
        <div className="bg-surface rounded-3xl border border-border p-6 relative overflow-hidden h-full">
            {/* Background Glow */}
            <div className={`absolute inset-0 bg-gradient-to-br transition-colors duration-1000 ${isActive ? 'from-emerald-500/5 via-transparent to-blue-500/5' : 'from-slate-500/5 via-transparent to-slate-500/5'}`} />

            <div className="flex items-center justify-between mb-6 relative z-10">
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-xl border transition-all ${isActive ? 'bg-emerald-500/10 border-emerald-500 text-emerald-500 shadow-lg shadow-emerald-500/20' : 'bg-slate-500/10 border-slate-500 text-slate-500'}`}>
                        {isActive ? <ShieldCheck className="w-6 h-6 animate-pulse" /> : <ShieldAlert className="w-6 h-6" />}
                    </div>
                    <div>
                        <h3 className="text-sm font-black text-foreground uppercase tracking-tight">Otonom Savunma Kalkanı</h3>
                        <div className="flex items-center gap-2">
                            <div className={`w-1.5 h-1.5 rounded-full ${isActive ? 'bg-emerald-500 animate-pulse' : 'bg-slate-500'}`} />
                            <span className="text-[10px] font-bold text-slate-500 uppercase">{isActive ? 'Aktif - Rakip Takibinde' : 'Pasif - Manuel Mod'}</span>
                        </div>
                    </div>
                </div>
                <button
                    onClick={() => setIsActive(!isActive)}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${isActive ? 'bg-emerald-500 text-white border-emerald-600 shadow-lg shadow-emerald-500/30' : 'bg-surface border-border text-slate-500'}`}
                >
                    {isActive ? 'DURDUR' : 'AKTİF ET'}
                </button>
            </div>

            {/* Shield Visualization */}
            <div className="relative flex flex-col items-center justify-center py-4 bg-background/50 rounded-2xl border border-border/50 mb-6">
                {loading ? (
                    <div className="text-center text-slate-500 text-sm">Yükleniyor...</div>
                ) : (
                <>
                <div className="text-center">
                    <div className="text-[32px] font-black text-foreground leading-none">{stats?.securityScore?.toFixed(1) || '--'}%</div>
                    <div className="text-[10px] font-bold text-slate-500 uppercase mt-1">GÜVENLİK SKORU</div>
                </div>
                <div className="mt-4 flex gap-8">
                    <div className="text-center">
                        <div className="text-xs font-bold text-emerald-500">{stats?.threatsBlocked || 0}</div>
                        <div className="text-[8px] font-bold text-slate-500 uppercase">Engellenen Tehdit</div>
                    </div>
                    <div className="text-center">
                        <div className="text-xs font-bold text-blue-500">₺{((stats?.revenueProtected || 0) / 1000).toFixed(1)}K</div>
                        <div className="text-[8px] font-bold text-slate-500 uppercase">Kurtarılan Ciro</div>
                    </div>
                </div>
                </>
                )}
            </div>

            {/* Defense Timeline */}
            <div className="space-y-3 relative z-10">
                <div className="flex items-center justify-between">
                    <span className="text-[10px] font-bold text-slate-500 uppercase">Son Koruma Aksiyonları</span>
                    <button className="text-[10px] font-bold text-primary hover:underline">TÜMÜ</button>
                </div>
                {actions.map((action) => (
                    <motion.div
                        key={action.id}
                        initial={{ x: -20, opacity: 0 }}
                        animate={{ x: 0, opacity: 1 }}
                        className="p-3 bg-surface border border-border rounded-2xl flex items-center justify-between group hover:border-emerald-500/30 transition-all"
                    >
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-lg bg-emerald-500/10 flex items-center justify-center text-emerald-500 group-hover:bg-emerald-500 group-hover:text-white transition-all">
                                <Zap className="w-4 h-4" />
                            </div>
                            <div>
                                <div className="text-[10px] font-black text-foreground">{action.product}</div>
                                <div className="text-[9px] text-slate-500">{action.action} • {action.competitor}</div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className="text-[9px] font-bold text-emerald-500">{action.impact}</div>
                            <div className="text-[8px] text-slate-500">{action.timestamp}</div>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Bottom Actions */}
            <div className="mt-6 flex gap-2">
                <button className="flex-1 bg-background border border-border hover:bg-surface py-2.5 rounded-xl text-[10px] font-bold flex items-center justify-center gap-2">
                    <Settings className="w-3 h-3 text-slate-400" /> AYARLAR
                </button>
                <button className="flex-1 bg-background border border-border hover:bg-surface py-2.5 rounded-xl text-[10px] font-bold flex items-center justify-center gap-2">
                    <Bell className="w-3 h-3 text-slate-400" /> RAPOR AL
                </button>
            </div>
        </div>
    );
};

'use client';

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Ghost, AlertTriangle, TrendingUp, Calendar, ChevronRight, Brain } from 'lucide-react';
import { useStockAlerts } from '@/lib/hooks';

interface GhostStock {
    id: string;
    product: string;
    stock: number;
    daysLeft: number;
    predictionDate: string;
    velocity: number;
}

export const GhostStockWidget = () => {
    const { data: stockAlerts, loading } = useStockAlerts();

    // Gerçek stok uyarılarından ghost stock tahminleri oluştur
    const predictions: GhostStock[] = React.useMemo(() => {
        if (!stockAlerts || !Array.isArray(stockAlerts)) return [];
        
        return stockAlerts
            .filter((alert: any) => alert.daysUntilStockout && alert.daysUntilStockout <= 7)
            .slice(0, 2)
            .map((alert: any, idx: number) => {
                const daysLeft = alert.daysUntilStockout || 1;
                const predictionDate = new Date();
                predictionDate.setDate(predictionDate.getDate() + daysLeft);
                
                return {
                    id: alert.id || `${idx}`,
                    product: alert.productName || alert.product || 'Bilinmeyen Ürün',
                    stock: alert.currentStock || 0,
                    daysLeft,
                    predictionDate: predictionDate.toLocaleDateString('tr-TR', { day: 'numeric', month: 'short' }),
                    velocity: alert.velocity || Math.round((alert.currentStock || 0) / Math.max(daysLeft, 1))
                };
            });
    }, [stockAlerts]);

    return (
        <div className="bg-surface rounded-3xl border border-border p-6 relative overflow-hidden h-full flex flex-col">
            <div className="absolute top-0 right-0 p-8 opacity-[0.03] select-none pointer-events-none">
                <Ghost size={140} />
            </div>

            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-3 min-w-0">
                    <div className="p-2.5 bg-orange-500/10 text-orange-500 rounded-2xl border border-orange-500/20 shadow-inner shrink-0 group-hover:bg-orange-500 group-hover:text-white transition-all">
                        <Ghost className="w-5 h-5" />
                    </div>
                    <div className="min-w-0 flex flex-col">
                        <h3 className="text-[14px] font-black text-foreground uppercase tracking-tight truncate">Ghost Stock</h3>
                        <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest truncate">Stok Tahmini</p>
                    </div>
                </div>
                <div className="px-2.5 py-1.5 bg-red-500 text-white text-[9px] font-black rounded-full shadow-lg shadow-red-500/20 shrink-0 animate-pulse">
                    KRİTİK
                </div>
            </div>

            <div className="space-y-4 relative z-10 flex-1">
                {predictions.length > 0 ? predictions.map((p) => (
                    <div key={p.id} className="p-4 bg-background/50 backdrop-blur-md border border-border rounded-2xl hover:border-orange-500/30 transition-all group/item shadow-sm">
                        <div className="flex justify-between items-start mb-3">
                            <div className="min-w-0 flex-1 pr-3">
                                <div className="text-[13px] font-bold text-foreground group-hover/item:text-orange-500 transition-colors truncate">{p.product}</div>
                                <div className="flex items-center gap-2 mt-1">
                                    <div className="flex items-center gap-1 text-[10px] text-slate-500">
                                        <TrendingUp size={11} className="text-orange-500" /> 
                                        <span>{p.velocity}/gün</span>
                                    </div>
                                </div>
                            </div>
                            <div className="text-right flex-shrink-0">
                                <div className="text-[14px] font-black text-orange-600 leading-none">{p.daysLeft} GÜN</div>
                                <div className="text-[9px] font-bold text-slate-400 uppercase mt-1">Kalan</div>
                            </div>
                        </div>

                        <div className="w-full h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mb-3">
                            <motion.div
                                initial={{ width: 0 }}
                                animate={{ width: `${Math.min((p.stock / (p.velocity * 10)) * 100, 100)}%` }}
                                className="h-full bg-gradient-to-r from-orange-400 to-red-500 rounded-full"
                            />
                        </div>

                        <div className="flex items-center justify-between font-medium">
                            <div className="flex items-center gap-1.5 text-slate-500">
                                <Calendar size={12} />
                                <span className="text-[10px] font-bold uppercase">{p.predictionDate}</span>
                            </div>
                            <button className="flex items-center gap-1 text-[10px] font-black text-primary hover:gap-2 transition-all uppercase tracking-wider bg-primary/5 px-2.5 py-1.5 rounded-lg border border-primary/10">
                                TEDARİK <ChevronRight size={12} />
                            </button>
                        </div>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center h-full py-10 opacity-40">
                        <Ghost className="w-10 h-10 mb-2" />
                        <p className="text-xs font-bold uppercase tracking-widest text-slate-500">Kritik Ürün Yok</p>
                    </div>
                )}
            </div>

            <div className={`mt-6 p-4 rounded-2xl border transition-all duration-500 ${predictions.length > 0 
                ? 'bg-orange-500/10 border-orange-500/20 shadow-lg shadow-orange-500/5' 
                : 'bg-green-500/10 border-green-500/20 shadow-lg shadow-green-500/5'}`}>
                <div className="flex gap-3">
                    <div className="mt-0.5 flex-shrink-0">
                        <div className={`p-1.5 rounded-xl ${predictions.length > 0 ? 'bg-orange-500/20' : 'bg-green-500/20'}`}>
                            {predictions.length > 0 ? (
                                <AlertTriangle className="w-4 h-4 text-orange-600" />
                            ) : (
                                <Brain className="w-4 h-4 text-green-600" />
                            )}
                        </div>
                    </div>
                    <div>
                        <div className={`text-[11px] font-black uppercase tracking-wider mb-0.5 ${predictions.length > 0 ? 'text-orange-600' : 'text-green-600'}`}>
                            Zeki Uyarı
                        </div>
                        <p className={`text-[11px] font-bold leading-relaxed ${predictions.length > 0 ? 'text-orange-700/80' : 'text-green-700/80'}`}>
                            {predictions.length > 0 
                                ? `${predictions.length} ürün tükenmek üzere. Hemen aksiyon alın.`
                                : 'Mevcut stok durumu stabil. Kritik seviyede ürün bulunmuyor.'}
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Target, TrendingUp, TrendingDown, DollarSign, ShoppingCart,
    Users, Package, CheckCircle, Circle, ArrowRight, Trophy,
    Flame, Star, Award, Zap, Sparkles, Calendar
} from 'lucide-react';

interface Goal {
    id: string;
    title: string;
    target: number;
    current: number;
    unit: string;
    prefix?: string;
    icon?: React.ElementType;
    color: string;
    deadline: string;
    status: 'on-track' | 'behind' | 'completed' | 'at-risk';
}

const iconMap: Record<string, React.ElementType> = {
    'revenue': DollarSign,
    'orders': ShoppingCart,
    'customers': Users,
    'products': Package,
};

const getGoalIcon = (goal: Goal): React.ElementType => {
    return goal.icon || iconMap[goal.id] || Target;
};

interface GoalTrackerProps {
    goals?: Goal[];
}

export default function GoalTracker({ goals: propGoals }: GoalTrackerProps) {
    const goals = Array.isArray(propGoals) ? propGoals : [];
    const [selectedGoal, setSelectedGoal] = useState<string | null>(null);

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'completed':
                return <span className="flex items-center gap-1 text-[10px] font-bold text-green-500 bg-green-500/10 px-2 py-0.5 rounded-full"><CheckCircle size={10} /> Tamamlandı</span>;
            case 'on-track':
                return <span className="flex items-center gap-1 text-[10px] font-bold text-blue-500 bg-blue-500/10 px-2 py-0.5 rounded-full"><TrendingUp size={10} /> Yolunda</span>;
            case 'behind':
                return <span className="flex items-center gap-1 text-[10px] font-bold text-red-500 bg-red-500/10 px-2 py-0.5 rounded-full"><TrendingDown size={10} /> Geride</span>;
            case 'at-risk':
                return <span className="flex items-center gap-1 text-[10px] font-bold text-amber-500 bg-amber-500/10 px-2 py-0.5 rounded-full"><Flame size={10} /> Risk</span>;
            default:
                return null;
        }
    };

    const formatValue = (goal: Goal, value: number) => {
        if (goal.prefix === '₺') {
            return `₺${value.toLocaleString('tr-TR')}`;
        }
        return `${value.toLocaleString('tr-TR')} ${goal.unit}`;
    };

    return (
        <div className="bg-surface rounded-2xl border border-border p-5">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                    <Target className="w-5 h-5 text-primary" />
                    <h3 className="text-sm font-bold text-foreground">Hedef Takibi</h3>
                </div>
                <div className="flex items-center gap-1 text-[10px] text-slate-500">
                    <Calendar size={12} />
                    <span>Şubat 2026</span>
                </div>
            </div>

            {goals.length === 0 ? (
                <div className="p-4 rounded-xl bg-background/50 border border-border text-center">
                    <p className="text-sm font-semibold text-foreground">Hedef verisi bulunamadı</p>
                    <p className="text-xs text-slate-500 mt-1">Hedefleriniz tanımlandığında burada gerçek veriler görünecek.</p>
                </div>
            ) : (
            <div className="space-y-3">
                {goals.map((goal) => {
                    const percentage = Math.min(100, (goal.current / goal.target) * 100);
                    return (
                        <motion.div
                            key={goal.id}
                            className="p-3 rounded-xl bg-background/50 border border-border hover:border-primary/30 transition-all cursor-pointer"
                            onClick={() => setSelectedGoal(selectedGoal === goal.id ? null : goal.id)}
                            whileHover={{ scale: 1.01 }}
                        >
                            <div className="flex items-center justify-between mb-2">
                                <div className="flex items-center gap-2">
                                    {(() => { const Icon = getGoalIcon(goal); return <Icon className={`w-4 h-4 ${goal.color}`} />; })()}
                                    <span className="text-xs font-bold text-foreground">{goal.title}</span>
                                </div>
                                {getStatusBadge(goal.status)}
                            </div>

                            <div className="flex items-center justify-between text-xs mb-2">
                                <span className="font-bold text-foreground">{formatValue(goal, goal.current)}</span>
                                <span className="text-slate-500">/ {formatValue(goal, goal.target)}</span>
                            </div>

                            <div className="h-2 bg-background rounded-full overflow-hidden">
                                <motion.div
                                    initial={{ width: 0 }}
                                    animate={{ width: `${percentage}%` }}
                                    transition={{ duration: 1, ease: 'easeOut' }}
                                    className={`h-full rounded-full ${
                                        percentage >= 90 ? 'bg-green-500' :
                                        percentage >= 70 ? 'bg-blue-500' :
                                        percentage >= 50 ? 'bg-amber-500' :
                                        'bg-red-500'
                                    }`}
                                />
                            </div>

                            <div className="flex items-center justify-between mt-1.5">
                                <span className="text-[10px] text-slate-500">%{percentage.toFixed(0)} tamamlandı</span>
                                <span className="text-[10px] text-slate-500">Son: {goal.deadline}</span>
                            </div>

                            <AnimatePresence>
                                {selectedGoal === goal.id && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: 'auto', opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        className="overflow-hidden"
                                    >
                                        <div className="mt-3 pt-3 border-t border-border">
                                            <div className="flex items-center gap-2 p-2 bg-primary/5 rounded-lg border border-primary/10">
                                                <Sparkles className="w-3 h-3 text-primary flex-shrink-0" />
                                                <span className="text-[10px] text-primary">
                                                    {percentage >= 80 
                                                        ? `Harika gidiyorsun! Kalan ${formatValue(goal, goal.target - goal.current)} ile hedefe ulaşacaksın.`
                                                        : `Hedefe ulaşmak için günlük ${formatValue(goal, Math.ceil((goal.target - goal.current) / 15))} gerekiyor.`
                                                    }
                                                </span>
                                            </div>
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    );
                })}
            </div>
            )}

            {/* Overall Progress */}
            {goals.length > 0 && <div className="mt-4 p-3 rounded-xl bg-gradient-to-r from-primary/10 to-purple-500/10 border border-primary/20">
                <div className="flex items-center gap-2">
                    <Trophy className="w-4 h-4 text-primary" />
                    <span className="text-xs font-bold text-foreground">Genel Başarı Oranı</span>
                    <span className="ml-auto text-sm font-black text-primary">
                        %{(goals.reduce((acc, g) => acc + (g.current / g.target) * 100, 0) / goals.length).toFixed(0)}
                    </span>
                </div>
            </div>}
        </div>
    );
}

