                                    </div>
                                </motion.div>
                            ) : (
                                <div className="grid grid-cols-1 lg:grid-cols-12 h-full">
                                    {/* Left: Product Selection (7 cols) */}
                                    <div className="lg:col-span-7 p-6 border-r border-border flex flex-col gap-6">

                                        {/* Search Bar */}
                                        <div className="relative z-20">
                                            <div className="relative">
                                                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                                                <input
                                                    ref={searchInputRef}
                                                    type="text"
                                                    value={searchQuery}
                                                    onChange={(e) => setSearchQuery(e.target.value)}
                                                    onKeyDown={(e) => {
                                                        // Pass to hook's handler
                                                        // @ts-ignore
                                                        if (typeof handleKeyDown === 'function') handleKeyDown(e);
                                                    }}
                                                    className="w-full bg-background border-2 border-border focus:border-primary/50 list-none rounded-2xl pl-12 pr-4 py-4 text-lg font-medium text-foreground placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-primary/10 transition-all shadow-sm"
                                                    placeholder="Ürün ara... (Enter ile ekle)"
                                                />
                                                <div className="absolute right-4 top-1/2 -translate-y-1/2 flex gap-2">
                                                    <kbd className="hidden sm:inline-flex items-center gap-1 px-2 py-1 bg-background border border-border rounded-lg text-xs text-slate-400 font-sans">
                                                        <span>↑</span><span>↓</span>
                                                    </kbd>
                                                    <kbd className="hidden sm:inline-flex items-center gap-1 px-2 py-1 bg-background border border-border rounded-lg text-xs text-slate-400 font-sans">
                                                        <span>↵</span>
                                                    </kbd>
                                                </div>
                                            </div>

                                            {/* Dropdown Results */}
                                            <AnimatePresence>
                                                {searchQuery && (
                                                    <motion.div
                                                        initial={{ opacity: 0, y: -10 }}
                                                        animate={{ opacity: 1, y: 0 }}
                                                        exit={{ opacity: 0, y: -10 }}
                                                        className="absolute top-full left-0 right-0 mt-2 bg-surface border border-border rounded-xl shadow-2xl overflow-hidden"
                                                    >
                                                        {filteredProducts.length > 0 ? (
                                                            filteredProducts.map((p: import("@/lib/hooks").Product, index: number) => (
                                                                <button
                                                                    key={p.id}
                                                                    onClick={() => addItem(p)}
                                                                    className={`w-full p-4 text-left flex items-center justify-between border-b border-border last:border-0 transition-colors ${index === focusedProductIndex ? 'bg-primary/10' : 'hover:bg-background'
                                                                        }`}
                                                                >
                                                                    <div className="flex items-center gap-4">
                                                                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${index === focusedProductIndex ? 'bg-primary/20 text-primary' : 'bg-slate-100 text-slate-400'}`}>
                                                                            <Package className="w-5 h-5" />
                                                                        </div>
                                                                        <div>
                                                                            <div className="text-base font-bold text-foreground">{p.name}</div>
                                                                            <div className="text-xs text-slate-500 font-mono">{p.sku}</div>
                                                                        </div>
                                                                    </div>
                                                                    <div className="flex items-center gap-4">
                                                                        <div className="text-base font-bold text-primary">{p.price.toLocaleString('tr-TR')} TL</div>
                                                                        {index === focusedProductIndex && <ArrowRight className="w-4 h-4 text-primary animate-pulse" />}
                                                                    </div>
                                                                </button>
                                                            ))
                                                        ) : (
                                                            <div className="p-8 text-center text-slate-500">
                                                                <Package className="w-8 h-8 mx-auto mb-2 opacity-20" />
                                                                <p>Ürün bulunamadı.</p>
                                                            </div>
                                                        )}
                                                    </motion.div>
                                                )}
                                            </AnimatePresence>
                                        </div>

                                        {/* Selected Items List */}
                                        <div className="flex-1 flex flex-col min-h-0 bg-background/50 rounded-2xl border border-border/50 overflow-hidden">
                                            <div className="p-4 border-b border-border/50 bg-background/80 backdrop-blur-sm sticky top-0 z-10 flex justify-between items-center">
                                                <h3 className="font-bold text-sm text-slate-500 uppercase tracking-wider">Sepet ({selectedItems.length})</h3>
                                                {selectedItems.length > 0 && (
                                                    <button onClick={() => selectedItems.forEach(i => removeItem(i.productId))} className="text-xs text-red-500 hover:underline">Sepeti Temizle</button>
                                                )}
                                            </div>

                                            <div className="overflow-y-auto p-2 space-y-2 flex-1">
                                                <AnimatePresence mode='popLayout'>
                                                    {selectedItems.length > 0 ? (
                                                        selectedItems.map(item => (
                                                            <motion.div
                                                                layout
                                                                initial={{ opacity: 0, x: -20 }}
                                                                animate={{ opacity: 1, x: 0 }}
                                                                exit={{ opacity: 0, x: 20 }}
                                                                key={item.productId}
                                                                className="flex items-center gap-3 p-3 bg-surface hover:bg-surface-hover rounded-xl border border-border group transition-colors shadow-sm"
                                                            >
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="font-bold text-foreground truncate">{item.name}</div>
                                                                    <div className="text-xs text-slate-500 font-mono">{item.price.toLocaleString('tr-TR')} TL x {item.quantity}</div>
                                                                </div>

                                                                <div className="flex items-center bg-background rounded-lg border border-border overflow-hidden">
                                                                    <button
                                                                        onClick={() => updateQuantity(item.productId, -1)}
                                                                        className="w-8 h-8 flex items-center justify-center hover:bg-slate-100 active:scale-95 transition-all text-slate-600"
                                                                    >-</button>
                                                                    <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                                                                    <button
                                                                        onClick={() => updateQuantity(item.productId, 1)}
                                                                        className="w-8 h-8 flex items-center justify-center hover:bg-slate-100 active:scale-95 transition-all text-slate-600"
                                                                    >+</button>
                                                                </div>

                                                                <div className="text-right min-w-[80px]">
                                                                    <div className="font-bold text-primary">{(item.price * item.quantity).toLocaleString('tr-TR')}</div>
                                                                    <div className="text-[10px] text-slate-400">TL</div>
                                                                </div>

                                                                <button
                                                                    onClick={() => removeItem(item.productId)}
                                                                    className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                                                                >
                                                                    <Trash2 className="w-4 h-4" />
                                                                </button>
                                                            </motion.div>
                                                        ))
                                                    ) : (
                                                        <div className="h-40 flex flex-col items-center justify-center text-slate-400 opacity-60">
                                                            <Package className="w-10 h-10 mb-2 stroke-1" />
                                                            <p className="text-sm">Henüz ürün eklenmedi</p>
                                                        </div>
                                                    )}
                                                </AnimatePresence>
                                            </div>

                                            {/* Footer Totals */}
                                            {selectedItems.length > 0 && (
                                                <div className="p-4 bg-surface border-t border-border mt-auto">
                                                    <div className="flex justify-between items-center mb-1">
                                                        <span className="text-sm text-slate-500">Ara Toplam</span>
                                                        <span className="text-foreground font-medium">{totalAmount.toLocaleString('tr-TR')} TL</span>
                                                    </div>
                                                    <div className="flex justify-between items-end">
                                                        <span className="text-lg font-bold text-foreground">Genel Toplam</span>
                                                        <span className="text-2xl font-black text-primary tracking-tight">{totalAmount.toLocaleString('tr-TR')} <span className="text-sm font-normal text-slate-500">TL</span></span>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Right: Customer Form & Actions (5 cols) */}
                                    <div className="lg:col-span-5 p-6 bg-surface shadow-inner flex flex-col h-full">
                                        <h3 className="font-bold text-sm text-slate-500 uppercase tracking-wider mb-4">Müşteri & Ödeme</h3>

                                        <form id="quick-sale-form" onSubmit={(e) => handleSubmit(e)} className="space-y-4 flex-1 overflow-y-auto pr-1">
                                            <div className="space-y-4">
                                                <div className="group">
                                                    <label className="text-xs font-bold text-slate-500 uppercase ml-1 mb-1.5 block group-focus-within:text-primary transition-colors">Ad Soyad</label>
                                                    <input
                                                        required
                                                        type="text"
                                                        value={customerData.name}
                                                        onChange={(e) => setCustomerData({ ...customerData, name: e.target.value })}
                                                        className="w-full bg-background border border-border rounded-xl px-4 py-3 text-foreground placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-primary/10 focus:border-primary/50 transition-all"
                                                        placeholder="Müşteri adı"
                                                    />
                                                </div>
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div className="group">
                                                        <label className="text-xs font-bold text-slate-500 uppercase ml-1 mb-1.5 block group-focus-within:text-primary transition-colors">Telefon</label>
                                                        <input
                                                            type="tel"
                                                            value={customerData.phone}
                                                            onChange={(e) => setCustomerData({ ...customerData, phone: e.target.value })}
                                                            className="w-full bg-background border border-border rounded-xl px-4 py-3 text-foreground placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-primary/10 focus:border-primary/50 transition-all"
                                                            placeholder="05..."
                                                        />
                                                    </div>
                                                    <div className="group">
                                                        <label className="text-xs font-bold text-slate-500 uppercase ml-1 mb-1.5 block group-focus-within:text-primary transition-colors">E-posta</label>
                                                        <input
                                                            type="email"
                                                            value={customerData.email}
                                                            onChange={(e) => setCustomerData({ ...customerData, email: e.target.value })}
                                                            className="w-full bg-background border border-border rounded-xl px-4 py-3 text-foreground placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-primary/10 focus:border-primary/50 transition-all"
                                                            placeholder="mail@"
                                                        />
                                                    </div>
                                                </div>
                                                <div className="group">
                                                    <label className="text-xs font-bold text-slate-500 uppercase ml-1 mb-1.5 block group-focus-within:text-primary transition-colors">Adres</label>
                                                    <textarea
                                                        value={customerData.address}
                                                        onChange={(e) => setCustomerData({ ...customerData, address: e.target.value })}
                                                        rows={3}
                                                        className="w-full bg-background border border-border rounded-xl px-4 py-3 text-foreground placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-primary/10 focus:border-primary/50 transition-all resize-none"
                                                        placeholder="Teslimat adresi..."
                                                    />
                                                </div>
                                            </div>

                                            {status === 'error' && (
                                                <motion.div
                                                    initial={{ opacity: 0, y: 10 }}
                                                    animate={{ opacity: 1, y: 0 }}
                                                    className="flex items-center gap-3 p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-sm text-red-500"
                                                >
                                                    <AlertCircle className="w-5 h-5 flex-shrink-0" />
                                                    {errorMessage}
                                                </motion.div>
                                            )}
                                        </form>

                                        <div className="pt-4 border-t border-border mt-auto">
                                            <button
                                                form="quick-sale-form"
                                                disabled={orderLoading || selectedItems.length === 0}
                                                type="submit"
                                                className="w-full py-4 bg-gradient-to-r from-primary to-blue-600 hover:from-primary/90 hover:to-blue-600/90 disabled:opacity-50 disabled:grayscale text-white rounded-xl font-bold text-lg transition-all flex items-center justify-center gap-2 shadow-lg shadow-primary/25 active:scale-[0.98]"
                                            >
                                                {orderLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Zap className="w-5 h-5 fill-current" />}
                                                Satışı Onayla
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Activity,
  Users,
  ShoppingCart,
  DollarSign,
  AlertTriangle,
  TrendingUp,
  Wifi,
  WifiOff,
  RefreshCw,
  Clock,
  Package,
  CreditCard,
  Bell
} from 'lucide-react';
import { useDashboardStats, useRecentOrders, useAiInsights, usePlatformPerformance, useActivityFeed } from '@/lib/hooks';

interface RealtimeEvent {
  type: 'order' | 'stock' | 'visitor' | 'payment' | 'alert';
  timestamp: Date;
  data: any;
}

export default function RealtimeDashboard() {
  const { data: statsData, loading: statsLoading } = useDashboardStats('30d');
  const { data: orders, loading: ordersLoading } = useRecentOrders(5);
  const { data: insights, loading: insightsLoading } = useAiInsights();
  const { data: platforms, loading: platformsLoading } = usePlatformPerformance();
  const { data: activities, loading: activitiesLoading } = useActivityFeed(10);

  const [showEvents, setShowEvents] = useState(true);
  const [isConnected, setIsConnected] = useState(true);
  const [events, setEvents] = useState<RealtimeEvent[]>([]);

  // Mock stats data for build
  const stats = [
    {
      label: 'Son 1 Saat Sipariş',
      value: 12,
      icon: ShoppingCart,
      color: 'from-green-500 to-emerald-500',
      suffix: ''
    },
    {
      label: 'Son 1 Saat Gelir',
      value: 3500,
      icon: DollarSign,
      color: 'from-purple-500 to-pink-500',
      suffix: '₺',
      prefix: true
    },
    {
      label: 'Bekleyen Sipariş',
      value: 5,
      icon: Package,
      color: 'from-orange-500 to-red-500',
      suffix: ''
    },
    {
      label: 'Düşük Stok',
      value: 2,
      icon: AlertTriangle,
      color: 'from-yellow-500 to-amber-500',
      suffix: ''
    },
    {
      label: 'Dönüşüm',
      value: 3.5,
      icon: TrendingUp,
      color: 'from-indigo-500 to-purple-500',
      suffix: '%'
    }
  ];

  const data = { lastUpdate: new Date() };

  const getEventIcon = (type: RealtimeEvent['type']) => {
    switch (type) {
      case 'order': return ShoppingCart;
      case 'stock': return Package;
      case 'visitor': return Users;
      case 'payment': return CreditCard;
      case 'alert': return Bell;
      default: return Activity;
    }
  };

  const getEventColor = (type: RealtimeEvent['type']) => {
    switch (type) {
      case 'order': return 'text-green-400 bg-green-500/10';
      case 'stock': return 'text-yellow-400 bg-yellow-500/10';
      case 'visitor': return 'text-blue-400 bg-blue-500/10';
      case 'payment': return 'text-purple-400 bg-purple-500/10';
      case 'alert': return 'text-red-400 bg-red-500/10';
      default: return 'text-slate-400 bg-slate-500/10';
    }
  };

  const formatEventMessage = (event: RealtimeEvent) => {
    switch (event.type) {
      case 'order':
        return `Yeni sipariş: ${event.data?.orderId || 'N/A'} - ₺${event.data?.amount || 0} (${event.data?.platform || 'Web'})`;
      case 'stock':
        return `Stok uyarısı: ${event.data?.product || 'Ürün'} - ${event.data?.remaining || 0} adet kaldı`;
      case 'visitor':
        return `${event.data?.count || 0} yeni ziyaretçi (${event.data?.source || 'Doğrudan'})`;
      case 'payment':
        return `Ödeme alındı: ₺${event.data?.amount || 0}`;
      case 'alert':
        return event.data?.message || 'Yeni uyarı';
      default:
        return 'Yeni olay';
    }
  };

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  const connect = () => setIsConnected(true);
  const disconnect = () => setIsConnected(false);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-green-500 to-emerald-500 flex items-center justify-center">
            <Activity className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="text-lg font-semibold text-white">Gerçek Zamanlı Dashboard</h2>
            <div className="flex items-center gap-2 text-sm">
              {isConnected ? (
                <>
                  <span className="flex items-center gap-1 text-green-400">
                    <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
                    Bağlı
                  </span>
                  <span className="text-slate-500">•</span>
                  <span className="text-slate-400">
                    Son güncelleme: {formatTime(data.lastUpdate)}
                  </span>
                </>
              ) : (
                <span className="flex items-center gap-1 text-red-400">
                  <WifiOff className="w-3 h-3" />
                  Bağlantı kesildi
                </span>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowEvents(!showEvents)}
            className={`px-3 py-1.5 rounded-lg text-sm transition-colors ${
              showEvents ? 'bg-purple-600 text-white' : 'bg-slate-800 text-slate-400'
            }`}
          >
            Olaylar
          </button>
          <button
            onClick={isConnected ? disconnect : connect}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm transition-colors ${
              isConnected
                ? 'bg-red-500/10 text-red-400 hover:bg-red-500/20'
                : 'bg-green-500/10 text-green-400 hover:bg-green-500/20'
            }`}
          >
            {isConnected ? <WifiOff className="w-4 h-4" /> : <Wifi className="w-4 h-4" />}
            {isConnected ? 'Durdur' : 'Bağlan'}
          </button>
        </div>
      </div>

      {/* Real-time Stats Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        {stats.map((stat, i) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.05 }}
            className="bg-slate-900/50 backdrop-blur-sm border border-slate-800 rounded-2xl p-4"
          >
            <div className="flex items-center gap-2 mb-2">
              <div className={`w-8 h-8 rounded-lg bg-gradient-to-br ${stat.color} flex items-center justify-center`}>
                <stat.icon className="w-4 h-4 text-white" />
              </div>
            </div>
            <motion.div
              key={String(stat.value)}
              initial={{ scale: 1.1 }}
              animate={{ scale: 1 }}
              className="text-2xl font-bold text-white"
            >
              {stat.prefix ? stat.suffix : ''}{typeof stat.value === 'number' ? stat.value.toLocaleString() : stat.value}{!stat.prefix ? stat.suffix : ''}
            </motion.div>
            <div className="text-xs text-slate-400 mt-1">{stat.label}</div>
          </motion.div>
        ))}
      </div>

      {/* Live Events Feed */}
      <AnimatePresence>
        {showEvents && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            <div className="bg-slate-900/50 backdrop-blur-sm border border-slate-800 rounded-2xl p-4">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-medium text-white flex items-center gap-2">
                  <RefreshCw className={`w-4 h-4 ${isConnected ? 'animate-spin' : ''}`} />
                  Canlı Olaylar
                </h3>
                <span className="text-xs text-slate-500">{events.length} olay</span>
              </div>

              <div className="space-y-2 max-h-64 overflow-y-auto">
                <AnimatePresence mode="popLayout">
                  {events.length === 0 ? (
                    <div className="text-center py-8 text-slate-500 text-sm">
                      Henüz olay yok...
                    </div>
                  ) : (
                    events.slice(0, 10).map((event, i) => {
                      const Icon = getEventIcon(event.type);
                      return (
                        <motion.div
                          key={`${event.type}-${event.timestamp.getTime()}-${i}`}
                          initial={{ opacity: 0, x: -20 }}
                          animate={{ opacity: 1, x: 0 }}
                          exit={{ opacity: 0, x: 20 }}
                          className="flex items-center gap-3 p-2 bg-slate-800/50 rounded-lg"
                        >
                          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${getEventColor(event.type)}`}>
                            <Icon className="w-4 h-4" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-sm text-slate-300 truncate">
                              {formatEventMessage(event)}
                            </p>
                          </div>
                          <span className="text-xs text-slate-500 flex items-center gap-1">
                            <Clock className="w-3 h-3" />
                            {formatTime(event.timestamp)}
                          </span>
                        </motion.div>
                      );
                    })
                  )}
                </AnimatePresence>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    TrendingUp, TrendingDown, DollarSign, ShoppingCart, Package,
    Users, AlertTriangle, CheckCircle2, ArrowUpRight, ArrowDownRight,
    Zap, Brain, Sparkles, Activity, Eye, Star, RefreshCw, Truck
} from 'lucide-react';
import { useActivityFeed, useDashboardStats } from '@/lib/hooks';

interface Notification {
    id: string;
    type: 'order' | 'sale' | 'stock' | 'review' | 'ai' | 'alert' | 'shipping' | 'system' | 'campaign';
    title: string;
    value?: string;
    time: string;
    platform?: string;
}

export function RealtimeNotificationToast() {
    const { data: activities } = useActivityFeed(1, { refetchInterval: 30000 }); // Her 30 sn'de bir yeni aktivite kontrol et
    const [visible, setVisible] = useState<Notification | null>(null);
    const lastActivityId = useRef<string | null>(null);

    useEffect(() => {
        if (activities && activities.length > 0) {
            const latest = activities[0];
            if (latest.id !== lastActivityId.current) {
                // Sadece yeni bir aktivite ise göster
                if (lastActivityId.current !== null) {
                    const timer = setTimeout(() => {
                        setVisible({
                            id: latest.id,
                            type: latest.type as any,
                            title: latest.title,
                            value: latest.value,
                            time: 'Az önce',
                            platform: latest.platform
                        });
                    }, 0);
                    lastActivityId.current = latest.id;
                    const clearTimer = setTimeout(() => setVisible(null), 5000);

                    return () => {
                        clearTimeout(timer);
                        clearTimeout(clearTimer);
                    }
                } else {
                    lastActivityId.current = latest.id; // İlk yüklemede sessizce kaydet
                }
            }
        }
    }, [activities]);

    const getIcon = (type: string) => {
        switch (type) {
            case 'sale': return <DollarSign className="w-4 h-4 text-green-500" />;
            case 'order': return <ShoppingCart className="w-4 h-4 text-blue-500" />;
            case 'stock': return <AlertTriangle className="w-4 h-4 text-amber-500" />;
            case 'review': return <Star className="w-4 h-4 text-yellow-500" />;
            case 'ai': return <Brain className="w-4 h-4 text-purple-500" />;
            case 'shipping': return <Truck size={16} className="text-purple-500" />;
            default: return <Activity className="w-4 h-4 text-slate-500" />;
        }
    };

    const getTypeColor = (type: string) => {
        switch (type) {
            case 'sale': return 'border-green-500/30 bg-green-500/5';
            case 'order': return 'border-blue-500/30 bg-blue-500/5';
            case 'stock': return 'border-amber-500/30 bg-amber-500/5';
            case 'review': return 'border-yellow-500/30 bg-yellow-500/5';
            case 'ai': return 'border-purple-500/30 bg-purple-500/5';
            default: return 'border-border bg-surface';
        }
    };

    return (
        <AnimatePresence>
            {visible && (
                <motion.div
                    initial={{ opacity: 0, y: 50, x: -50 }}
                    animate={{ opacity: 1, y: 0, x: 0 }}
                    exit={{ opacity: 0, y: -20, x: -50 }}
                    className={`fixed bottom-32 lg:bottom-6 left-6 z-[110] max-w-sm p-4 rounded-2xl border shadow-2xl backdrop-blur-xl ${getTypeColor(visible.type)}`}
                >
                    <div className="flex items-start gap-3">
                        <div className="p-2 rounded-xl bg-background/80">
                            {getIcon(visible.type)}
                        </div>
                        <div className="flex-1 min-w-0">
                            <div className="text-sm font-bold text-foreground">{visible.title}</div>
                            {visible.value && (
                                <div className="text-xs font-bold text-primary mt-0.5">{visible.value}</div>
                            )}
                            <div className="flex items-center gap-2 mt-1">
                                {visible.platform && (
                                    <span className="text-[10px] font-bold text-slate-500 bg-background/50 px-1.5 py-0.5 rounded">
                                        {visible.platform}
                                    </span>
                                )}
                                <span className="text-[10px] text-slate-500">{visible.time}</span>
                            </div>
                        </div>
                        <button
                            onClick={() => setVisible(null)}
                            className="text-slate-400 hover:text-foreground"
                        >
                            ×
                        </button>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    );
}


