                        </div>
                    </motion.div>
                </>
            )}
        </AnimatePresence>
    );
}

'use client';

import { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Upload,
  Download,
  FileSpreadsheet,
  X,
  Check,
  AlertCircle,
  Loader2,
  File,
  Trash2,
  Eye,
  ChevronDown
} from 'lucide-react';

export type ExportFormat = 'xlsx' | 'csv' | 'json';
export type DataType = 'products' | 'orders' | 'customers' | 'inventory';

interface ExportOptions {
  format: ExportFormat;
  dataType: DataType;
  columns?: string[];
  filters?: Record<string, any>;
  dateRange?: { start: Date; end: Date };
}

interface ImportResult {
  success: boolean;
  totalRows: number;
  successRows: number;
  errorRows: number;
  errors?: { row: number; message: string }[];
}

// Export Hook
export function useExport() {
  const [isExporting, setIsExporting] = useState(false);
  const [progress, setProgress] = useState(0);

  const exportData = async (options: ExportOptions): Promise<Blob | null> => {
    setIsExporting(true);
    setProgress(0);

    try {
      setProgress(30);
      const res = await fetch('/api/data/export', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(options),
      });

      if (!res.ok) {
        throw new Error('Disa aktarim servisi kullanilamiyor');
      }

      setProgress(80);
      const blob = await res.blob();
      const filename = `${options.dataType}_export_${Date.now()}.${options.format}`;
      setProgress(100);

      // Trigger download
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      return blob;
    } finally {
      setIsExporting(false);
      setProgress(0);
    }
  };

  return { exportData, isExporting, progress };
}

// Import Hook
export function useImport() {
  const [isImporting, setIsImporting] = useState(false);
  const [progress, setProgress] = useState(0);

  const importData = async (file: File, dataType: DataType): Promise<ImportResult> => {
    setIsImporting(true);
    setProgress(0);

    try {
      setProgress(25);
      const formData = new FormData();
      formData.append('file', file);
      formData.append('dataType', dataType);

      const res = await fetch('/api/data/import', {
        method: 'POST',
        body: formData,
      });

      if (!res.ok) {
        throw new Error('Ice aktarim servisi kullanilamiyor');
      }

      setProgress(75);
      const payload = await res.json();
      const data = payload?.data || payload;
      setProgress(100);

      return {
        success: Boolean(data?.success),
        totalRows: Number(data?.totalRows || 0),
        successRows: Number(data?.successRows || 0),
        errorRows: Number(data?.errorRows || 0),
        errors: Array.isArray(data?.errors) ? data.errors : [],
      };
    } catch {
      return {
        success: false,
        totalRows: 0,
        successRows: 0,
        errorRows: 1,
        errors: [{ row: 0, message: 'Ice aktarim servisine ulasilamadi' }],
      };
    } finally {
      setIsImporting(false);
      setProgress(0);
    }
  };

  return { importData, isImporting, progress };
}

// Export Modal Component
