export function useEditor() {
  const ctx = useContext(EditorContext);
  if (!ctx) throw new Error('useEditor must be used inside EditorProvider');
  return ctx;
}

// ─── History yardımcısı ─────────────────────────────────
const MAX_HISTORY = 50;

// ─── Provider ────────────────────────────────────────────
export function EditorProvider({ children }: { children: React.ReactNode }) {
  const canvasRef = useRef<any>(null);
  const [canvasReady, setCanvasReady] = useState(false);
  const [canvasSize, setCanvasSize] = useState({ width: 800, height: 800, name: 'Trendyol' });
  const [zoom, setZoomState] = useState(1);
  const [activeTool, setActiveToolState] = useState<EditorTool>('select');
  const [activePanel, setActivePanel] = useState<PanelType>('templates');
  const [activeObject, setActiveObject] = useState<any>(null);
  const [fillColor, setFillColor] = useState('#3b82f6');
  const [strokeColor, setStrokeColor] = useState('#000000');
  const [strokeWidth, setStrokeWidth] = useState(0);
  const [brushSize, setBrushSize] = useState(5);
  const [brushColor, setBrushColor] = useState('#000000');
  const [fontSize, setFontSize] = useState(32);
  const [fontFamily, setFontFamily] = useState('Arial');
  const [filterSettings, setFilterSettings] = useState<FilterSettings>(DEFAULT_FILTERS);
  const [canvasBackgroundColor, setCanvasBgColor] = useState('#ffffff');

  // History
  const historyRef = useRef<EditorHistoryEntry[]>([]);
  const historyIndexRef = useRef(-1);
  const isRestoringRef = useRef(false);
  const [canUndo, setCanUndo] = useState(false);
  const [canRedo, setCanRedo] = useState(false);

  const updateHistoryState = useCallback(() => {
    setCanUndo(historyIndexRef.current > 0);
    setCanRedo(historyIndexRef.current < historyRef.current.length - 1);
  }, []);

  const saveHistory = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || isRestoringRef.current) return;
    const json = JSON.stringify(canvas.toJSON(['selectable', 'evented', 'lockMovementX', 'lockMovementY', 'lockRotation', 'lockScalingX', 'lockScalingY', 'name']));
    const entry: EditorHistoryEntry = { json, timestamp: Date.now() };

    // Eğer geri almışsak, sonraki kayıtları sil
    if (historyIndexRef.current < historyRef.current.length - 1) {
      historyRef.current = historyRef.current.slice(0, historyIndexRef.current + 1);
    }

    historyRef.current.push(entry);
    if (historyRef.current.length > MAX_HISTORY) {
      historyRef.current.shift();
    }
    historyIndexRef.current = historyRef.current.length - 1;
    updateHistoryState();
  }, [updateHistoryState]);

  // ─── Canvas Başlatma ──────────────────────────────────
  const initCanvas = useCallback(async (element: HTMLCanvasElement) => {
    const fabric = await loadFabric();
    const { Canvas: FabricCanvas } = fabric;

    if (canvasRef.current) {
      canvasRef.current.dispose();
    }

    const canvas = new FabricCanvas(element, {
      width: canvasSize.width,
      height: canvasSize.height,
      backgroundColor: canvasBackgroundColor,
      selection: true,
      preserveObjectStacking: true,
      controlsAboveOverlay: true,
      centeredScaling: false,
      centeredRotation: true,
      stopContextMenu: true,
      fireRightClick: true,
    });

    // Seçim olayları
    canvas.on('selection:created', (e: any) => setActiveObject(e.selected?.[0] || null));
    canvas.on('selection:updated', (e: any) => setActiveObject(e.selected?.[0] || null));
    canvas.on('selection:cleared', () => setActiveObject(null));

    // Nesne değişim olayları → History kaydet
    canvas.on('object:modified', () => saveHistory());
    canvas.on('object:added', () => saveHistory());
    canvas.on('object:removed', () => saveHistory());

    canvasRef.current = canvas;
    setCanvasReady(true);

    // İlk history kaydı
    setTimeout(() => saveHistory(), 100);
  }, [canvasSize.width, canvasSize.height, canvasBackgroundColor, saveHistory]);

  // ─── Araç Değişimi ────────────────────────────────────
  const setActiveTool = useCallback((tool: EditorTool) => {
    setActiveToolState(tool);
    const canvas = canvasRef.current;
    if (!canvas) return;

    canvas.isDrawingMode = tool === 'draw' || tool === 'eraser';

    if (tool === 'draw' || tool === 'eraser') {
      loadFabric().then((fabric) => {
        const brush = new fabric.PencilBrush(canvas);
        brush.width = tool === 'eraser' ? brushSize * 3 : brushSize;
        brush.color = tool === 'eraser' ? canvasBackgroundColor : brushColor;
        canvas.freeDrawingBrush = brush;
      });
    }

    if (tool === 'hand') {
      canvas.defaultCursor = 'grab';
      canvas.selection = false;
    } else if (tool === 'select') {
      canvas.defaultCursor = 'default';
      canvas.selection = true;
    } else {
      canvas.defaultCursor = 'crosshair';
      canvas.selection = false;
    }
  }, [brushSize, brushColor, canvasBackgroundColor]);

  // ─── Zoom ─────────────────────────────────────────────
  const setZoom = useCallback((z: number) => {
    const clamped = Math.min(Math.max(z, 0.1), 5);
    setZoomState(clamped);
    const canvas = canvasRef.current;
    if (canvas) {
      canvas.setZoom(clamped);
      canvas.setWidth(canvasSize.width * clamped);
      canvas.setHeight(canvasSize.height * clamped);
      canvas.renderAll();
    }
  }, [canvasSize]);

  const zoomIn = useCallback(() => setZoom(zoom * 1.2), [zoom, setZoom]);
  const zoomOut = useCallback(() => setZoom(zoom / 1.2), [zoom, setZoom]);
  const resetZoom = useCallback(() => setZoom(1), [setZoom]);
  const zoomToFit = useCallback(() => {
    const container = document.getElementById('editor-canvas-container');
    if (!container) return;
    const padding = 80;
    const scaleX = (container.clientWidth - padding) / canvasSize.width;
    const scaleY = (container.clientHeight - padding) / canvasSize.height;
    setZoom(Math.min(scaleX, scaleY, 1));
  }, [canvasSize, setZoom]);

  // ─── Active Object Refresh ────────────────────────────
  const refreshActiveObject = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const obj = canvas.getActiveObject();
    setActiveObject(obj ? { ...obj } : null);
  }, []);

  // ─── Nesne Ekleme ─────────────────────────────────────
  const addText = useCallback((text?: string, options?: any) => {
    loadFabric().then((fabric) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const textbox = new fabric.Textbox(text || 'Metin yazın...', {
        left: canvasSize.width / 2 - 100,
        top: canvasSize.height / 2 - 20,
        fontSize: fontSize,
        fontFamily: fontFamily,
        fill: fillColor,
        textAlign: 'left',
        width: 300,
        editable: true,
        ...options,
      });
      canvas.add(textbox);
      canvas.setActiveObject(textbox);
      canvas.renderAll();
    });
  }, [canvasSize, fontSize, fontFamily, fillColor]);

  const addShape = useCallback((type: string, options?: any) => {
    loadFabric().then((fabric) => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const centerX = canvasSize.width / 2;
      const centerY = canvasSize.height / 2;
      let shape: any;

      const baseProps = {
        fill: fillColor,
        stroke: strokeWidth > 0 ? strokeColor : undefined,
        strokeWidth: strokeWidth,
        ...options,
      };

      switch (type) {
        case 'rectangle':
          shape = new fabric.Rect({ left: centerX - 75, top: centerY - 50, width: 150, height: 100, rx: 0, ry: 0, ...baseProps });
          break;
        case 'rounded-rectangle':
          shape = new fabric.Rect({ left: centerX - 75, top: centerY - 50, width: 150, height: 100, rx: 12, ry: 12, ...baseProps });
          break;
        case 'circle':
          shape = new fabric.Circle({ left: centerX - 50, top: centerY - 50, radius: 50, ...baseProps });
          break;
        case 'ellipse':
          shape = new fabric.Ellipse({ left: centerX - 75, top: centerY - 40, rx: 75, ry: 40, ...baseProps });
          break;
        case 'triangle':
          shape = new fabric.Triangle({ left: centerX - 50, top: centerY - 50, width: 100, height: 100, ...baseProps });
          break;
        case 'line':
          shape = new fabric.Line([centerX - 75, centerY, centerX + 75, centerY], {
            stroke: strokeColor || '#000000', strokeWidth: strokeWidth || 3, ...options,
          });
          break;
        case 'arrow': {
          const arrowPath = 'M 0 0 L 150 0 L 135 -15 M 150 0 L 135 15';
          shape = new fabric.Path(arrowPath, {
            left: centerX - 75, top: centerY,
            stroke: strokeColor || '#000000', strokeWidth: strokeWidth || 3,
            fill: 'transparent', ...options,
          });
          break;
        }
        case 'star': {
          const points = [];
          const outerR = 60, innerR = 30, spikes = 5;
          for (let i = 0; i < spikes * 2; i++) {
            const r = i % 2 === 0 ? outerR : innerR;
            const angle = (Math.PI / spikes) * i - Math.PI / 2;
            points.push({ x: centerX + r * Math.cos(angle), y: centerY + r * Math.sin(angle) });
          }
          shape = new fabric.Polygon(points, { ...baseProps });
          break;
        }
        case 'hexagon': {
          const hexPoints = [];
          for (let i = 0; i < 6; i++) {
            const angle = (Math.PI / 3) * i - Math.PI / 6;
            hexPoints.push({ x: centerX + 60 * Math.cos(angle), y: centerY + 60 * Math.sin(angle) });
          }
          shape = new fabric.Polygon(hexPoints, { ...baseProps });
          break;
        }
        case 'diamond': {
          const dPoints = [
            { x: centerX, y: centerY - 60 },
            { x: centerX + 45, y: centerY },
            { x: centerX, y: centerY + 60 },
            { x: centerX - 45, y: centerY },
          ];
          shape = new fabric.Polygon(dPoints, { ...baseProps });
          break;
        }
        default:
          shape = new fabric.Rect({ left: centerX - 50, top: centerY - 50, width: 100, height: 100, ...baseProps });
      }

      if (shape) {
        canvas.add(shape);
        canvas.setActiveObject(shape);
        canvas.renderAll();
      }
    });
  }, [canvasSize, fillColor, strokeColor, strokeWidth]);

  const addImageFromURL = useCallback(async (url: string) => {
    const fabric = await loadFabric();
    const canvas = canvasRef.current;
    if (!canvas) return;

    const img = await fabric.FabricImage.fromURL(url, { crossOrigin: 'anonymous' });
    // Görseli canvas'a sığdır
    const maxW = canvasSize.width * 0.8;
    const maxH = canvasSize.height * 0.8;
    const scale = Math.min(maxW / (img.width || 1), maxH / (img.height || 1), 1);
    img.set({
      left: (canvasSize.width - (img.width || 0) * scale) / 2,
      top: (canvasSize.height - (img.height || 0) * scale) / 2,
      scaleX: scale,
      scaleY: scale,
    });

    canvas.add(img);
    canvas.setActiveObject(img);
    canvas.renderAll();
  }, [canvasSize]);

  // ─── Nesne İşlemleri ──────────────────────────────────
  const deleteSelected = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const objs = canvas.getActiveObjects();
    objs.forEach((o: any) => canvas.remove(o));
    canvas.discardActiveObject();
    canvas.renderAll();
    setActiveObject(null);
  }, []);

  const duplicateSelected = useCallback(async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const obj = canvas.getActiveObject();
    if (!obj) return;
    const cloned = await obj.clone();
    cloned.set({ left: (obj.left || 0) + 20, top: (obj.top || 0) + 20 });
    canvas.add(cloned);
    canvas.setActiveObject(cloned);
    canvas.renderAll();
  }, []);

  const bringForward = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { canvas.bringObjectForward(obj); canvas.renderAll(); }
  }, []);

  const sendBackward = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { canvas.sendObjectBackwards(obj); canvas.renderAll(); }
  }, []);

  const bringToFront = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { canvas.bringObjectToFront(obj); canvas.renderAll(); }
  }, []);

  const sendToBack = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { canvas.sendObjectToBack(obj); canvas.renderAll(); }
  }, []);

  const groupSelected = useCallback(async () => {
    const fabric = await loadFabric();
    const canvas = canvasRef.current;
    if (!canvas) return;
    const activeSelection = canvas.getActiveObject();
    if (!activeSelection || activeSelection.type !== 'activeSelection') return;
    const group = new fabric.Group(activeSelection.getObjects(), {});
    canvas.discardActiveObject();
    activeSelection.getObjects().forEach((o: any) => canvas.remove(o));
    canvas.add(group);
    canvas.setActiveObject(group);
    canvas.renderAll();
  }, []);

  const ungroupSelected = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const obj = canvas.getActiveObject();
    if (!obj || obj.type !== 'group') return;
    const items = obj.getObjects();
    obj.destroy();
    canvas.remove(obj);
    items.forEach((item: any) => canvas.add(item));
    canvas.renderAll();
  }, []);

  const flipHorizontal = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { obj.set('flipX', !obj.flipX); canvas.renderAll(); saveHistory(); }
  }, [saveHistory]);

  const flipVertical = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { obj.set('flipY', !obj.flipY); canvas.renderAll(); saveHistory(); }
  }, [saveHistory]);

  const setOpacity = useCallback((opacity: number) => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) { obj.set('opacity', opacity); canvas.renderAll(); saveHistory(); }
  }, [saveHistory]);

  const alignObjects = useCallback((alignment: string) => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (!obj) return;
    switch (alignment) {
      case 'left': obj.set('left', 0); break;
      case 'center': obj.set('left', (canvasSize.width - (obj.width || 0) * (obj.scaleX || 1)) / 2); break;
      case 'right': obj.set('left', canvasSize.width - (obj.width || 0) * (obj.scaleX || 1)); break;
      case 'top': obj.set('top', 0); break;
      case 'middle': obj.set('top', (canvasSize.height - (obj.height || 0) * (obj.scaleY || 1)) / 2); break;
      case 'bottom': obj.set('top', canvasSize.height - (obj.height || 0) * (obj.scaleY || 1)); break;
    }
    canvas.renderAll();
    saveHistory();
  }, [canvasSize, saveHistory]);

  const selectAll = useCallback(async () => {
    const fabric = await loadFabric();
    const canvas = canvasRef.current;
    if (!canvas) return;
    const objs = canvas.getObjects();
    if (objs.length === 0) return;
    const selection = new fabric.ActiveSelection(objs, { canvas });
    canvas.setActiveObject(selection);
    canvas.renderAll();
  }, []);

  const deselectAll = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.discardActiveObject();
    canvas.renderAll();
    setActiveObject(null);
  }, []);

  const lockSelected = useCallback(() => {
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (obj) {
      obj.set({ lockMovementX: true, lockMovementY: true, lockRotation: true, lockScalingX: true, lockScalingY: true, selectable: false, evented: false });
      canvas.discardActiveObject();
      canvas.renderAll();
    }
  }, []);

  const unlockSelected = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.getObjects().forEach((obj: any) => {
      if (obj.lockMovementX) {
        obj.set({ lockMovementX: false, lockMovementY: false, lockRotation: false, lockScalingX: false, lockScalingY: false, selectable: true, evented: true });
      }
    });
    canvas.renderAll();
  }, []);

  // ─── Undo / Redo ──────────────────────────────────────
  const undo = useCallback(async () => {
    if (historyIndexRef.current <= 0) return;
    historyIndexRef.current--;
    isRestoringRef.current = true;
    const entry = historyRef.current[historyIndexRef.current];
    const canvas = canvasRef.current;
    if (canvas && entry) {
      await canvas.loadFromJSON(entry.json);
      canvas.renderAll();
    }
    isRestoringRef.current = false;
    updateHistoryState();
  }, [updateHistoryState]);

  const redo = useCallback(async () => {
    if (historyIndexRef.current >= historyRef.current.length - 1) return;
    historyIndexRef.current++;
    isRestoringRef.current = true;
    const entry = historyRef.current[historyIndexRef.current];
    const canvas = canvasRef.current;
    if (canvas && entry) {
      await canvas.loadFromJSON(entry.json);
      canvas.renderAll();
    }
    isRestoringRef.current = false;
    updateHistoryState();
  }, [updateHistoryState]);

  // ─── Export ────────────────────────────────────────────
  const exportCanvas = useCallback(async (options: ExportOptions): Promise<string> => {
    const canvas = canvasRef.current;
    if (!canvas) return '';
    canvas.discardActiveObject();
    canvas.renderAll();
    return canvas.toDataURL({
      format: options.format,
      quality: options.quality,
      multiplier: options.scale,
    });
  }, []);

  const exportCanvasBlob = useCallback(async (options: ExportOptions): Promise<Blob> => {
    const dataUrl = await exportCanvas(options);
    const response = await fetch(dataUrl);
    return response.blob();
  }, [exportCanvas]);

  // ─── Proje Kaydetme / Yükleme ─────────────────────────
  const saveProject = useCallback((): string => {
    const canvas = canvasRef.current;
    if (!canvas) return '{}';
    return JSON.stringify({
      version: '1.0',
      canvasSize,
      backgroundColor: canvasBackgroundColor,
      canvas: canvas.toJSON(['selectable', 'evented', 'lockMovementX', 'lockMovementY', 'lockRotation', 'lockScalingX', 'lockScalingY', 'name']),
    });
  }, [canvasSize, canvasBackgroundColor]);

  const loadProject = useCallback(async (json: string) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    try {
      const data = JSON.parse(json);
      if (data.canvasSize) setCanvasSize(data.canvasSize);
      if (data.backgroundColor) setCanvasBgColor(data.backgroundColor);
      if (data.canvas) {
        await canvas.loadFromJSON(data.canvas);
        canvas.renderAll();
        saveHistory();
      }
    } catch {
      console.error('Proje yüklenemedi');
    }
  }, [saveHistory]);

  // ─── Canvas temizle ────────────────────────────────────
  const clearCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.clear();
    canvas.backgroundColor = canvasBackgroundColor;
    canvas.renderAll();
    saveHistory();
    setActiveObject(null);
  }, [canvasBackgroundColor, saveHistory]);

  // ─── Filtre uygulama ──────────────────────────────────
  const applyFiltersToSelected = useCallback(async (settings: FilterSettings) => {
    const fabric = await loadFabric();
    const canvas = canvasRef.current;
    const obj = canvas?.getActiveObject();
    if (!obj || obj.type !== 'image') return;

    const imgObj = obj as any;
    imgObj.filters = [];

    if (settings.brightness !== 0) imgObj.filters.push(new fabric.filters.Brightness({ brightness: settings.brightness }));
    if (settings.contrast !== 0) imgObj.filters.push(new fabric.filters.Contrast({ contrast: settings.contrast }));
    if (settings.saturation !== 0) imgObj.filters.push(new fabric.filters.Saturation({ saturation: settings.saturation }));
    if (settings.blur > 0) imgObj.filters.push(new fabric.filters.Blur({ blur: settings.blur }));
    if (settings.grayscale) imgObj.filters.push(new fabric.filters.Grayscale());
    if (settings.sepia) imgObj.filters.push(new fabric.filters.Sepia());
    if (settings.invert) imgObj.filters.push(new fabric.filters.Invert());
    if (settings.hueRotation !== 0) imgObj.filters.push(new fabric.filters.HueRotation({ rotation: settings.hueRotation / 360 }));

    imgObj.applyFilters();
    canvas.renderAll();
    setFilterSettings(settings);
    saveHistory();
  }, [saveHistory]);

  // ─── Arkaplan rengi ────────────────────────────────────
  const setCanvasBackgroundColor = useCallback((color: string) => {
    setCanvasBgColor(color);
    const canvas = canvasRef.current;
    if (canvas) {
      canvas.backgroundColor = color;
      canvas.renderAll();
      saveHistory();
    }
  }, [saveHistory]);

  const getObjects = useCallback(() => {
    return canvasRef.current?.getObjects() || [];
  }, []);

  const cropToSelection = useCallback(() => {
    // Kırpma işlemi - seçili alanı kırp
  }, []);

  // ─── Klavye kısayolları ────────────────────────────────
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      // Input/textarea içindeyken kısayolları devre dışı bırak
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      const isCtrl = e.ctrlKey || e.metaKey;

      if (isCtrl && e.key === 'z' && !e.shiftKey) { e.preventDefault(); undo(); }
      if (isCtrl && (e.key === 'y' || (e.key === 'z' && e.shiftKey))) { e.preventDefault(); redo(); }
      if (e.key === 'Delete' || e.key === 'Backspace') {
        if (canvasRef.current?.getActiveObject()) { e.preventDefault(); deleteSelected(); }
      }
      if (isCtrl && e.key === 'a') { e.preventDefault(); selectAll(); }
      if (isCtrl && e.key === 'd') { e.preventDefault(); duplicateSelected(); }
      if (isCtrl && e.key === 'g' && !e.shiftKey) { e.preventDefault(); groupSelected(); }
      if (isCtrl && e.key === 'g' && e.shiftKey) { e.preventDefault(); ungroupSelected(); }
      if (e.key === 'Escape') { deselectAll(); }
      if (e.key === 'v' && !isCtrl) { setActiveTool('select'); }
      if (e.key === 'h' && !isCtrl) { setActiveTool('hand'); }
      if (e.key === 'b' && !isCtrl) { setActiveTool('draw'); }
      if (e.key === 't' && !isCtrl) { setActiveTool('text'); }
      if (e.key === 'r' && !isCtrl) { setActiveTool('rectangle'); }
      if (e.key === 'o' && !isCtrl) { setActiveTool('circle'); }
      if (e.key === 'l' && !isCtrl) { setActiveTool('line'); }
      if (e.key === '=' && isCtrl) { e.preventDefault(); zoomIn(); }
      if (e.key === '-' && isCtrl) { e.preventDefault(); zoomOut(); }
      if (e.key === '0' && isCtrl) { e.preventDefault(); resetZoom(); }
    };

    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [undo, redo, deleteSelected, selectAll, duplicateSelected, groupSelected, ungroupSelected, deselectAll, setActiveTool, zoomIn, zoomOut, resetZoom]);

  const value: EditorContextValue = {
    canvasRef, canvasSize, setCanvasSize, canvasReady, zoom, setZoom,
    activeTool, setActiveTool, activePanel, setActivePanel,
    activeObject, refreshActiveObject,
    fillColor, setFillColor, strokeColor, setStrokeColor, strokeWidth, setStrokeWidth,
    brushSize, setBrushSize, brushColor, setBrushColor,
    fontSize, setFontSize, fontFamily, setFontFamily,
    filterSettings, setFilterSettings,
    initCanvas, addText, addShape, addImageFromURL,
    deleteSelected, duplicateSelected, bringForward, sendBackward, bringToFront, sendToBack,
    groupSelected, ungroupSelected, alignObjects, flipHorizontal, flipVertical, setOpacity,
    undo, redo, canUndo, canRedo,
    exportCanvas, exportCanvasBlob, clearCanvas, saveProject, loadProject,
    applyFiltersToSelected, setCanvasBackgroundColor, canvasBackgroundColor,
    zoomIn, zoomOut, zoomToFit, resetZoom,
    selectAll, deselectAll, getObjects, cropToSelection, lockSelected, unlockSelected,
  };

  return <EditorContext.Provider value={value}>{children}</EditorContext.Provider>;
}

"use client";

import React, { useState, useEffect } from 'react';
import { useEditor } from './EditorContext';
import { COLOR_PALETTE } from './types';
import {
  Layers, Settings2, Move, RotateCw, Maximize2,
  Eye, EyeOff, Lock, Unlock, Trash2, Copy,
  ChevronUp, ChevronDown, ChevronsUp, ChevronsDown,
  FlipHorizontal, FlipVertical, AlignStartHorizontal,
  AlignCenterHorizontal, AlignEndHorizontal,
  AlignStartVertical, AlignCenterVertical, AlignEndVertical,
  Type, Square, Circle, ImageIcon, Pencil, Group, Ungroup,
  Palette,
} from 'lucide-react';

export default function EditorRightPanel() {
  const {
    activeObject, canvasRef,
    deleteSelected, duplicateSelected,
    bringForward, sendBackward, bringToFront, sendToBack,
    flipHorizontal, flipVertical, setOpacity, alignObjects,
    groupSelected, ungroupSelected, lockSelected, unlockSelected,
    getObjects, canvasBackgroundColor, setCanvasBackgroundColor,
    fillColor, setFillColor, strokeColor, setStrokeColor,
  } = useEditor();
  const [tab, setTab] = useState<'properties' | 'layers'>('properties');
  const [showBgPicker, setShowBgPicker] = useState(false);
  const [objects, setObjects] = useState<any[]>([]);

  // Nesneleri periyodik güncelle
  useEffect(() => {
    const interval = setInterval(() => {
      setObjects([...getObjects()]);
    }, 500);
    return () => clearInterval(interval);
  }, [getObjects]);

  const obj = activeObject;

  const updateProp = (prop: string, value: any) => {
    if (!obj || !canvasRef.current) return;
    obj.set(prop, value);
    canvasRef.current.renderAll();
  };

  const getObjTypeName = (o: any) => {
    switch (o?.type) {
      case 'textbox': case 'text': case 'i-text': return 'Metin';
      case 'rect': return 'Dikdörtgen';
      case 'circle': return 'Daire';
      case 'triangle': return 'Üçgen';
      case 'ellipse': return 'Elips';
      case 'polygon': return 'Çokgen';
      case 'line': return 'Çizgi';
      case 'path': return 'Yol';
      case 'image': return 'Görsel';
      case 'group': return 'Grup';
      default: return o?.type || 'Nesne';
    }
  };

  const getObjIcon = (o: any) => {
    switch (o?.type) {
      case 'textbox': case 'text': case 'i-text': return Type;
      case 'rect': return Square;
      case 'circle': case 'ellipse': return Circle;
      case 'image': return ImageIcon;
      case 'path': return Pencil;
      case 'group': return Group;
      default: return Square;
    }
  };

  return (
    <div className="w-64 bg-surface border-l border-border flex flex-col shrink-0 overflow-hidden">
      {/* Tab seçicileri */}
      <div className="flex border-b border-border shrink-0">
        <button
          onClick={() => setTab('properties')}
          className={`flex-1 py-3 text-xs font-bold flex items-center justify-center gap-1.5 transition-colors
            ${tab === 'properties' ? 'text-primary border-b-2 border-primary' : 'text-slate-500 hover:text-slate-300'}`}
        >
          <Settings2 size={14} /> Özellikler
        </button>
        <button
          onClick={() => setTab('layers')}
          className={`flex-1 py-3 text-xs font-bold flex items-center justify-center gap-1.5 transition-colors
            ${tab === 'layers' ? 'text-primary border-b-2 border-primary' : 'text-slate-500 hover:text-slate-300'}`}
        >
          <Layers size={14} /> Katmanlar
          <span className="text-[9px] bg-slate-700 px-1.5 py-0.5 rounded-full">{objects.length}</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto">
        {tab === 'properties' ? (
          <div className="p-3 space-y-3">
            {obj ? (
              <>
                {/* Nesne tipi */}
                <div className="flex items-center gap-2 py-2 px-3 bg-slate-800/50 rounded-lg">
                  {React.createElement(getObjIcon(obj), { size: 14, className: 'text-primary' })}
                  <span className="text-xs font-bold text-white">{getObjTypeName(obj)}</span>
                </div>

                {/* Konum */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1 flex items-center gap-1">
                    <Move size={10} /> Konum
                  </label>
                  <div className="grid grid-cols-2 gap-1.5">
                    <div>
                      <label className="text-[9px] text-slate-600">X</label>
                      <input type="number" value={Math.round(obj.left || 0)}
                        onChange={e => updateProp('left', parseInt(e.target.value) || 0)}
                        className="w-full px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white focus:outline-none focus:border-primary" />
                    </div>
                    <div>
                      <label className="text-[9px] text-slate-600">Y</label>
                      <input type="number" value={Math.round(obj.top || 0)}
                        onChange={e => updateProp('top', parseInt(e.target.value) || 0)}
                        className="w-full px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white focus:outline-none focus:border-primary" />
                    </div>
                  </div>
                </div>

                {/* Boyut */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1 flex items-center gap-1">
                    <Maximize2 size={10} /> Boyut
                  </label>
                  <div className="grid grid-cols-2 gap-1.5">
                    <div>
                      <label className="text-[9px] text-slate-600">Genişlik</label>
                      <input type="number"
                        value={Math.round((obj.width || 0) * (obj.scaleX || 1))}
                        onChange={e => {
                          const w = parseInt(e.target.value) || 1;
                          updateProp('scaleX', w / (obj.width || 1));
                        }}
                        className="w-full px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white focus:outline-none focus:border-primary" />
                    </div>
                    <div>
                      <label className="text-[9px] text-slate-600">Yükseklik</label>
                      <input type="number"
                        value={Math.round((obj.height || 0) * (obj.scaleY || 1))}
                        onChange={e => {
                          const h = parseInt(e.target.value) || 1;
                          updateProp('scaleY', h / (obj.height || 1));
                        }}
                        className="w-full px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white focus:outline-none focus:border-primary" />
                    </div>
                  </div>
                </div>

                {/* Döndürme */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1 flex items-center gap-1">
                    <RotateCw size={10} /> Döndürme
                  </label>
                  <div className="flex items-center gap-2">
                    <input type="range" min={0} max={360} step={1}
                      value={Math.round(obj.angle || 0)}
                      onChange={e => updateProp('angle', parseInt(e.target.value))}
                      className="flex-1 accent-primary" />
                    <input type="number" value={Math.round(obj.angle || 0)}
                      onChange={e => updateProp('angle', parseInt(e.target.value) || 0)}
                      className="w-14 px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white text-center focus:outline-none focus:border-primary"
                      min={0} max={360} />
                  </div>
                </div>

                {/* Opaklık */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1">Opaklık</label>
                  <div className="flex items-center gap-2">
                    <input type="range" min={0} max={1} step={0.05}
                      value={obj.opacity ?? 1}
                      onChange={e => setOpacity(parseFloat(e.target.value))}
                      className="flex-1 accent-primary" />
                    <span className="text-[10px] text-slate-400 w-8 text-right">{Math.round((obj.opacity ?? 1) * 100)}%</span>
                  </div>
                </div>

                <div className="h-px bg-slate-700" />

                {/* Dolgu rengi (şekiller için) */}
                {obj.type !== 'image' && obj.type !== 'line' && obj.type !== 'path' && (
                  <div>
                    <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1 flex items-center gap-1">
                      <Palette size={10} /> Dolgu Rengi
                    </label>
                    <div className="flex items-center gap-2">
                      <input type="color" value={obj.fill || fillColor}
                        onChange={e => { updateProp('fill', e.target.value); setFillColor(e.target.value); }}
                        className="w-8 h-8 rounded cursor-pointer border-0" />
                      <input type="text" value={obj.fill || fillColor}
                        onChange={e => { updateProp('fill', e.target.value); setFillColor(e.target.value); }}
                        className="flex-1 px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white focus:outline-none focus:border-primary" />
                    </div>
                  </div>
                )}

                {/* Çerçeve */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1">Çerçeve</label>
                  <div className="flex items-center gap-2">
                    <input type="color" value={obj.stroke || strokeColor}
                      onChange={e => { updateProp('stroke', e.target.value); setStrokeColor(e.target.value); }}
                      className="w-8 h-8 rounded cursor-pointer border-0" />
                    <input type="number"
                      value={obj.strokeWidth || 0}
                      onChange={e => updateProp('strokeWidth', parseInt(e.target.value) || 0)}
                      className="w-14 px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white text-center focus:outline-none focus:border-primary"
                      min={0} max={50} />
                  </div>
                </div>

                {/* Köşe yuvarlatma (rect için) */}
                {obj.type === 'rect' && (
                  <div>
                    <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1">Köşe Yuvarlatma</label>
                    <div className="flex items-center gap-2">
                      <input type="range" min={0} max={100} step={1}
                        value={obj.rx || 0}
                        onChange={e => { updateProp('rx', parseInt(e.target.value)); updateProp('ry', parseInt(e.target.value)); }}
                        className="flex-1 accent-primary" />
                      <span className="text-[10px] text-slate-400 w-8 text-right">{obj.rx || 0}</span>
                    </div>
                  </div>
                )}

                <div className="h-px bg-slate-700" />

                {/* Aynalama */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1">Çevir</label>
                  <div className="flex gap-1.5">
                    <button onClick={flipHorizontal}
                      className="flex-1 flex items-center justify-center gap-1 py-1.5 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors text-[10px]">
                      <FlipHorizontal size={13} /> Yatay
                    </button>
                    <button onClick={flipVertical}
                      className="flex-1 flex items-center justify-center gap-1 py-1.5 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors text-[10px]">
                      <FlipVertical size={13} /> Dikey
                    </button>
                  </div>
                </div>

                {/* Hizalama */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1">Hizala</label>
                  <div className="grid grid-cols-6 gap-1">
                    {[
                      { align: 'left', icon: AlignStartHorizontal },
                      { align: 'center', icon: AlignCenterHorizontal },
                      { align: 'right', icon: AlignEndHorizontal },
                      { align: 'top', icon: AlignStartVertical },
                      { align: 'middle', icon: AlignCenterVertical },
                      { align: 'bottom', icon: AlignEndVertical },
                    ].map(({ align, icon: Icon }) => (
                      <button key={align} onClick={() => alignObjects(align)}
                        className="p-1.5 text-slate-500 hover:text-primary hover:bg-primary/5 rounded-lg transition-colors" title={align}>
                        <Icon size={14} className="mx-auto" />
                      </button>
                    ))}
                  </div>
                </div>

                {/* Sıralama */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1">Sıralama</label>
                  <div className="grid grid-cols-4 gap-1">
                    <button onClick={bringToFront} title="En Öne" className="p-1.5 text-slate-500 hover:text-white hover:bg-white/5 rounded-lg transition-colors">
                      <ChevronsUp size={14} className="mx-auto" />
                    </button>
                    <button onClick={bringForward} title="Bir Öne" className="p-1.5 text-slate-500 hover:text-white hover:bg-white/5 rounded-lg transition-colors">
                      <ChevronUp size={14} className="mx-auto" />
                    </button>
                    <button onClick={sendBackward} title="Bir Arkaya" className="p-1.5 text-slate-500 hover:text-white hover:bg-white/5 rounded-lg transition-colors">
                      <ChevronDown size={14} className="mx-auto" />
                    </button>
                    <button onClick={sendToBack} title="En Arkaya" className="p-1.5 text-slate-500 hover:text-white hover:bg-white/5 rounded-lg transition-colors">
                      <ChevronsDown size={14} className="mx-auto" />
                    </button>
                  </div>
                </div>

                <div className="h-px bg-slate-700" />

                {/* İşlemler */}
                <div className="flex gap-1.5">
                  <button onClick={duplicateSelected}
                    className="flex-1 flex items-center justify-center gap-1 py-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors text-[10px]">
                    <Copy size={12} /> Kopyala
                  </button>
                  <button onClick={deleteSelected}
                    className="flex-1 flex items-center justify-center gap-1 py-2 text-red-400 hover:text-red-300 hover:bg-red-500/5 rounded-lg border border-slate-700 transition-colors text-[10px]">
                    <Trash2 size={12} /> Sil
                  </button>
                </div>
                <div className="flex gap-1.5">
                  <button onClick={groupSelected}
                    className="flex-1 flex items-center justify-center gap-1 py-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors text-[10px]">
                    <Group size={12} /> Grupla
                  </button>
                  <button onClick={ungroupSelected}
                    className="flex-1 flex items-center justify-center gap-1 py-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors text-[10px]">
                    <Ungroup size={12} /> Ayır
                  </button>
                </div>
              </>
            ) : (
              /* Hiçbir nesne seçili değil - canvas özellikleri */
              <div className="space-y-3">
                <div className="text-center py-4">
                  <Settings2 size={24} className="mx-auto text-slate-600 mb-2" />
                  <p className="text-sm text-slate-400">Nesne Seçin</p>
                  <p className="text-[10px] text-slate-600 mt-1">Özelliklerini düzenlemek için bir nesne seçin</p>
                </div>

                <div className="h-px bg-slate-700" />

                {/* Canvas arka plan rengi */}
                <div>
                  <label className="text-[10px] text-slate-500 uppercase tracking-wider font-bold mb-1 block">Canvas Arkaplanı</label>
                  <div className="flex items-center gap-2">
                    <div className="relative">
                      <button onClick={() => setShowBgPicker(!showBgPicker)}
                        className="w-8 h-8 rounded border border-slate-600" style={{ backgroundColor: canvasBackgroundColor }} />
                      {showBgPicker && (
                        <>
                          <div className="fixed inset-0 z-30" onClick={() => setShowBgPicker(false)} />
                          <div className="absolute bottom-full left-0 mb-1 bg-slate-800 border border-slate-700 rounded-xl shadow-2xl z-40 p-2 w-52">
                            <div className="grid grid-cols-8 gap-1 mb-2">
                              {COLOR_PALETTE.slice(0, 24).map(color => (
                                <button key={color} onClick={() => { setCanvasBackgroundColor(color); setShowBgPicker(false); }}
                                  className="w-full aspect-square rounded border border-slate-600 hover:scale-110 transition-transform"
                                  style={{ backgroundColor: color }} />
                              ))}
                            </div>
                            <input type="color" value={canvasBackgroundColor}
                              onChange={e => setCanvasBackgroundColor(e.target.value)}
                              className="w-full h-7 rounded cursor-pointer" />
                          </div>
                        </>
                      )}
                    </div>
                    <input type="text" value={canvasBackgroundColor}
                      onChange={e => setCanvasBackgroundColor(e.target.value)}
                      className="flex-1 px-2 py-1 bg-slate-800 border border-slate-700 rounded text-xs text-white focus:outline-none focus:border-primary" />
                  </div>
                </div>
              </div>
            )}
          </div>
        ) : (
          /* Katmanlar paneli */
          <div className="p-2">
            {objects.length === 0 ? (
              <div className="text-center py-8">
                <Layers size={24} className="mx-auto text-slate-600 mb-2" />
                <p className="text-sm text-slate-400">Katman Yok</p>
                <p className="text-[10px] text-slate-600 mt-1">Kanvasa nesne ekleyerek başlayın</p>
              </div>
            ) : (
              <div className="space-y-0.5">
                {[...objects].reverse().map((o, i) => {
                  const Icon = getObjIcon(o);
                  const isActive = obj === o;
                  const isLocked = o.lockMovementX;
                  return (
                    <button
                      key={i}
                      onClick={() => {
                        canvasRef.current?.setActiveObject(o);
                        canvasRef.current?.renderAll();
                      }}
                      className={`w-full flex items-center gap-2 px-2 py-2 rounded-lg transition-all text-left
                        ${isActive ? 'bg-primary/15 text-primary border border-primary/30' : 'text-slate-400 hover:bg-white/5 border border-transparent'}`}
                    >
                      <Icon size={14} className="shrink-0" />
                      <span className="text-[11px] font-medium truncate flex-1">
                        {o.text?.substring(0, 20) || getObjTypeName(o)}
                      </span>
                      {isLocked && <Lock size={10} className="text-slate-600 shrink-0" />}
                      {!o.visible && <EyeOff size={10} className="text-slate-600 shrink-0" />}
                    </button>
                  );
                })}
              </div>
            )}

            {/* Kilitle/Aç butonları */}
            {objects.length > 0 && (
              <div className="mt-3 flex gap-1.5">
                <button onClick={lockSelected}
                  className="flex-1 flex items-center justify-center gap-1 py-1.5 text-[10px] text-slate-500 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors">
                  <Lock size={10} /> Kilitle
                </button>
                <button onClick={unlockSelected}
                  className="flex-1 flex items-center justify-center gap-1 py-1.5 text-[10px] text-slate-500 hover:text-white hover:bg-white/5 rounded-lg border border-slate-700 transition-colors">
                  <Unlock size={10} /> Tümünü Aç
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React from 'react';
import { useEditor } from './EditorContext';
import type { EditorTool, PanelType } from './types';
import {
  MousePointer2, Hand, Pencil, Type, Square, Circle,
  Triangle, Minus, ArrowRight, Star, Eraser, Hexagon,
  Diamond, RectangleHorizontal,
  // Panel ikonları
  LayoutTemplate, TypeIcon, Shapes, ImageIcon, Sparkles,
  Download, Paintbrush, Smile, Frame,
} from 'lucide-react';

interface ToolDef {
  id: EditorTool;
  icon: React.ComponentType<{ size?: number; className?: string }>;
  label: string;
  shortcut?: string;
}

const tools: ToolDef[] = [
  { id: 'select', icon: MousePointer2, label: 'Seç', shortcut: 'V' },
  { id: 'hand', icon: Hand, label: 'El Aracı', shortcut: 'H' },
  { id: 'draw', icon: Pencil, label: 'Çizim', shortcut: 'B' },
  { id: 'eraser', icon: Eraser, label: 'Silgi', shortcut: 'E' },
  { id: 'text', icon: Type, label: 'Metin', shortcut: 'T' },
  { id: 'rectangle', icon: Square, label: 'Dikdörtgen', shortcut: 'R' },
  { id: 'circle', icon: Circle, label: 'Daire', shortcut: 'O' },
  { id: 'triangle', icon: Triangle, label: 'Üçgen' },
  { id: 'line', icon: Minus, label: 'Çizgi', shortcut: 'L' },
  { id: 'arrow', icon: ArrowRight, label: 'Ok' },
  { id: 'star', icon: Star, label: 'Yıldız' },
  { id: 'polygon', icon: Hexagon, label: 'Çokgen' },
];

interface PanelDef {
  id: PanelType;
  icon: React.ComponentType<{ size?: number; className?: string }>;
  label: string;
}

const panels: PanelDef[] = [
  { id: 'templates', icon: LayoutTemplate, label: 'Şablonlar' },
  { id: 'text', icon: TypeIcon, label: 'Metin' },
  { id: 'elements', icon: Shapes, label: 'Elemanlar' },
  { id: 'backgrounds', icon: Paintbrush, label: 'Arka Plan' },
  { id: 'stickers', icon: Smile, label: 'Çıkartmalar' },
  { id: 'frames', icon: Frame, label: 'Çerçeveler' },
  { id: 'images', icon: ImageIcon, label: 'Görseller' },
  { id: 'filters', icon: Sparkles, label: 'Filtreler' },
  { id: 'export', icon: Download, label: 'Dışa Aktar' },
];

export default function EditorToolbar() {
  const { activeTool, setActiveTool, activePanel, setActivePanel } = useEditor();

  return (
    <div className="w-16 bg-surface border-r border-border flex flex-col items-center py-3 gap-1 shrink-0 overflow-y-auto">
      {/* Panel sekmeleri */}
      <div className="flex flex-col items-center gap-0.5 w-full px-1 mb-2">
        {panels.map(panel => (
          <button
            key={panel.id}
            onClick={() => setActivePanel(activePanel === panel.id ? null : panel.id)}
            className={`w-full flex flex-col items-center gap-0.5 py-2 px-1 rounded-lg transition-all text-[10px] font-medium
              ${activePanel === panel.id
                ? 'bg-primary/15 text-primary shadow-sm'
                : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
              }`}
            title={panel.label}
          >
            <panel.icon size={18} />
            <span className="truncate w-full text-center">{panel.label}</span>
          </button>
        ))}
      </div>

      <div className="w-10 h-px bg-slate-700 mb-2" />

      {/* Araçlar */}
      <div className="flex flex-col items-center gap-0.5 w-full px-1">
        {tools.map(tool => (
          <button
            key={tool.id}
            onClick={() => setActiveTool(tool.id)}
            className={`w-full flex items-center justify-center p-2 rounded-lg transition-all group relative
              ${activeTool === tool.id
                ? 'bg-primary/20 text-primary shadow-sm'
                : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
              }`}
            title={`${tool.label}${tool.shortcut ? ` (${tool.shortcut})` : ''}`}
          >
            <tool.icon size={17} />
            {/* Tooltip */}
            <div className="absolute left-full ml-2 px-2.5 py-1 bg-slate-900 text-white text-xs rounded-lg whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-50 border border-slate-700 shadow-xl">
              {tool.label}
              {tool.shortcut && <span className="ml-2 text-slate-400">({tool.shortcut})</span>}
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useEditor } from './EditorContext';
import {
  Undo2, Redo2, ZoomIn, ZoomOut, Maximize2,
  Download, Save, FolderOpen, Trash2, RotateCcw,
  ChevronDown, FileImage, Share2, Monitor,
} from 'lucide-react';
import { CANVAS_PRESETS } from './types';

export default function EditorTopBar() {
  const {
    undo, redo, canUndo, canRedo,
    zoom, zoomIn, zoomOut, zoomToFit, resetZoom,
    canvasSize, setCanvasSize, clearCanvas,
    saveProject, loadProject, setActivePanel,
  } = useEditor();

  const [showSizeMenu, setShowSizeMenu] = useState(false);
  const [showFileMenu, setShowFileMenu] = useState(false);
  const [customW, setCustomW] = useState('');
  const [customH, setCustomH] = useState('');

  const handleSaveJSON = () => {
    const json = saveProject();
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `gorsel-proje-${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadJSON = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const text = await file.text();
      loadProject(text);
    };
    input.click();
  };

  const handleCustomSize = () => {
    const w = parseInt(customW);
    const h = parseInt(customH);
    if (w > 0 && h > 0 && w <= 8000 && h <= 8000) {
      setCanvasSize({ width: w, height: h, name: `Özel (${w}×${h})` });
      setShowSizeMenu(false);
      setCustomW('');
      setCustomH('');
    }
  };

  const sizeCategories = {
    marketplace: CANVAS_PRESETS.filter(p => p.category === 'marketplace'),
    social: CANVAS_PRESETS.filter(p => p.category === 'social'),
    custom: CANVAS_PRESETS.filter(p => p.category === 'custom'),
  };

  return (
    <div className="h-14 bg-surface border-b border-border flex items-center justify-between px-4 gap-2 shrink-0">
      {/* Sol: Dosya + Geri Al / Yinele */}
      <div className="flex items-center gap-1">
        {/* Dosya menüsü */}
        <div className="relative">
          <button
            onClick={() => setShowFileMenu(!showFileMenu)}
            className="flex items-center gap-1.5 px-3 py-1.5 text-sm text-slate-300 hover:text-white hover:bg-white/5 rounded-lg transition-colors"
          >
            <FileImage size={16} />
            <span className="hidden sm:inline">Dosya</span>
            <ChevronDown size={12} />
          </button>
          {showFileMenu && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setShowFileMenu(false)} />
              <div className="absolute top-full left-0 mt-1 w-56 bg-slate-800 border border-slate-700 rounded-xl shadow-2xl z-50 py-1 overflow-hidden">
                <button onClick={() => { clearCanvas(); setShowFileMenu(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-slate-300 hover:bg-white/5 hover:text-white transition-colors">
                  <RotateCcw size={15} /> Yeni Proje
                </button>
                <button onClick={() => { handleLoadJSON(); setShowFileMenu(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-slate-300 hover:bg-white/5 hover:text-white transition-colors">
                  <FolderOpen size={15} /> Proje Aç
                </button>
                <button onClick={() => { handleSaveJSON(); setShowFileMenu(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-slate-300 hover:bg-white/5 hover:text-white transition-colors">
                  <Save size={15} /> Proje Kaydet
                  <span className="ml-auto text-xs text-slate-500">Ctrl+S</span>
                </button>
                <div className="h-px bg-slate-700 my-1" />
                <button onClick={() => { setActivePanel('export'); setShowFileMenu(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-slate-300 hover:bg-white/5 hover:text-white transition-colors">
                  <Download size={15} /> Dışa Aktar
                  <span className="ml-auto text-xs text-slate-500">Ctrl+E</span>
                </button>
                <div className="h-px bg-slate-700 my-1" />
                <button onClick={() => { clearCanvas(); setShowFileMenu(false); }} className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-red-400 hover:bg-red-500/10 hover:text-red-300 transition-colors">
                  <Trash2 size={15} /> Tümünü Temizle
                </button>
              </div>
            </>
          )}
        </div>

        <div className="w-px h-6 bg-slate-700 mx-1" />

        {/* Undo / Redo */}
        <button onClick={undo} disabled={!canUndo} className="p-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors" title="Geri Al (Ctrl+Z)">
          <Undo2 size={16} />
        </button>
        <button onClick={redo} disabled={!canRedo} className="p-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors" title="Yinele (Ctrl+Y)">
          <Redo2 size={16} />
        </button>
      </div>

      {/* Orta: Canvas boyutu */}
      <div className="flex items-center gap-2">
        <div className="relative">
          <button
            onClick={() => setShowSizeMenu(!showSizeMenu)}
            className="flex items-center gap-2 px-3 py-1.5 text-sm text-slate-300 hover:text-white bg-slate-800/50 hover:bg-slate-700/50 rounded-lg border border-slate-700 transition-colors"
          >
            <Monitor size={14} />
            <span>{canvasSize.name}</span>
            <span className="text-slate-500 text-xs">({canvasSize.width}×{canvasSize.height})</span>
            <ChevronDown size={12} />
          </button>

          {showSizeMenu && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setShowSizeMenu(false)} />
              <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-80 bg-slate-800 border border-slate-700 rounded-xl shadow-2xl z-50 py-2 max-h-[70vh] overflow-y-auto">
                {/* Pazaryeri */}
                <div className="px-3 py-1.5 text-xs font-bold text-primary uppercase tracking-wider">Pazaryeri</div>
                {sizeCategories.marketplace.map(p => (
                  <button key={p.name} onClick={() => { setCanvasSize({ ...p }); setShowSizeMenu(false); }}
                    className={`w-full flex items-center justify-between px-4 py-2 text-sm hover:bg-white/5 transition-colors ${canvasSize.name === p.name ? 'text-primary bg-primary/5' : 'text-slate-300'}`}>
                    <span>{p.name}</span>
                    <span className="text-xs text-slate-500">{p.width}×{p.height}</span>
                  </button>
                ))}

                <div className="h-px bg-slate-700 my-1" />
                <div className="px-3 py-1.5 text-xs font-bold text-green-400 uppercase tracking-wider">Sosyal Medya</div>
                {sizeCategories.social.map(p => (
                  <button key={p.name} onClick={() => { setCanvasSize({ ...p }); setShowSizeMenu(false); }}
                    className={`w-full flex items-center justify-between px-4 py-2 text-sm hover:bg-white/5 transition-colors ${canvasSize.name === p.name ? 'text-primary bg-primary/5' : 'text-slate-300'}`}>
                    <span>{p.name}</span>
                    <span className="text-xs text-slate-500">{p.width}×{p.height}</span>
                  </button>
                ))}

                <div className="h-px bg-slate-700 my-1" />
                <div className="px-3 py-1.5 text-xs font-bold text-purple-400 uppercase tracking-wider">Standart Boyutlar</div>
                {sizeCategories.custom.map(p => (
                  <button key={p.name} onClick={() => { setCanvasSize({ ...p }); setShowSizeMenu(false); }}
                    className={`w-full flex items-center justify-between px-4 py-2 text-sm hover:bg-white/5 transition-colors ${canvasSize.name === p.name ? 'text-primary bg-primary/5' : 'text-slate-300'}`}>
                    <span>{p.name}</span>
                    <span className="text-xs text-slate-500">{p.width}×{p.height}</span>
                  </button>
                ))}

                <div className="h-px bg-slate-700 my-1" />
                <div className="px-3 py-1.5 text-xs font-bold text-orange-400 uppercase tracking-wider">Özel Boyut</div>
                <div className="px-3 py-2 flex items-center gap-2">
                  <input type="number" placeholder="Genişlik" value={customW} onChange={e => setCustomW(e.target.value)}
                    className="w-24 px-2 py-1.5 text-sm bg-slate-900 border border-slate-600 rounded-lg text-white placeholder:text-slate-500 focus:outline-none focus:border-primary" />
                  <span className="text-slate-500">×</span>
                  <input type="number" placeholder="Yükseklik" value={customH} onChange={e => setCustomH(e.target.value)}
                    className="w-24 px-2 py-1.5 text-sm bg-slate-900 border border-slate-600 rounded-lg text-white placeholder:text-slate-500 focus:outline-none focus:border-primary" />
                  <button onClick={handleCustomSize}
                    className="px-3 py-1.5 text-xs font-bold bg-primary hover:bg-primary/80 text-white rounded-lg transition-colors">
                    Uygula
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Sağ: Zoom + Export */}
      <div className="flex items-center gap-1">
        <button onClick={zoomOut} className="p-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors" title="Uzaklaştır">
          <ZoomOut size={16} />
        </button>
        <button onClick={resetZoom} className="px-2 py-1 text-xs text-slate-400 hover:text-white hover:bg-white/5 rounded-lg min-w-[48px] text-center transition-colors">
          {Math.round(zoom * 100)}%
        </button>
        <button onClick={zoomIn} className="p-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors" title="Yakınlaştır">
          <ZoomIn size={16} />
        </button>
        <button onClick={zoomToFit} className="p-2 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors" title="Sığdır">
          <Maximize2 size={16} />
        </button>

        <div className="w-px h-6 bg-slate-700 mx-1" />

        <button
          onClick={() => setActivePanel('export')}
          className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-primary to-purple-600 hover:from-primary/90 hover:to-purple-500 text-white text-sm font-bold rounded-xl shadow-lg shadow-primary/25 transition-all hover:shadow-primary/40"
        >
          <Share2 size={15} />
          <span className="hidden sm:inline">Dışa Aktar</span>
        </button>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useEditor } from '../EditorContext';
import { COLOR_PALETTE, GRADIENT_PRESETS, PATTERN_PRESETS } from '../types';
import type { GradientDef, PatternDef } from '../types';
import { Droplets, Palette, Grid3X3, Paintbrush } from 'lucide-react';

type BgTab = 'solid' | 'gradient' | 'pattern';

// SVG pattern generators
function generatePatternSVG(pattern: PatternDef, size: number = 20): string {
  const s = size * pattern.scale;
  switch (pattern.type) {
    case 'dots':
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><circle cx="${s / 2}" cy="${s / 2}" r="${s / 6}" fill="${pattern.color}"/></svg>`;
    case 'stripes':
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="${s / 3}" height="${s}" fill="${pattern.color}"/></svg>`;
    case 'grid':
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="${s}" height="1" fill="${pattern.color}"/><rect x="0" y="0" width="1" height="${s}" fill="${pattern.color}"/></svg>`;
    case 'diagonal':
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><line x1="0" y1="${s}" x2="${s}" y2="0" stroke="${pattern.color}" stroke-width="2"/></svg>`;
    case 'checkerboard':
      return `<svg width="${s * 2}" height="${s * 2}" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="${s}" height="${s}" fill="${pattern.color}"/><rect x="${s}" y="${s}" width="${s}" height="${s}" fill="${pattern.color}"/></svg>`;
    case 'diamond':
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><polygon points="${s / 2},0 ${s},${s / 2} ${s / 2},${s} 0,${s / 2}" fill="none" stroke="${pattern.color}" stroke-width="1"/></svg>`;
    case 'cross':
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><line x1="${s / 2}" y1="0" x2="${s / 2}" y2="${s}" stroke="${pattern.color}" stroke-width="1"/><line x1="0" y1="${s / 2}" x2="${s}" y2="${s / 2}" stroke="${pattern.color}" stroke-width="1"/></svg>`;
    default:
      return `<svg width="${s}" height="${s}" xmlns="http://www.w3.org/2000/svg"><circle cx="${s / 2}" cy="${s / 2}" r="${s / 6}" fill="${pattern.color}"/></svg>`;
  }
}

const SOLID_COLORS = [
  { name: 'Beyaz', color: '#ffffff' },
  { name: 'Açık Gri', color: '#f1f5f9' },
  { name: 'Gri', color: '#94a3b8' },
  { name: 'Koyu', color: '#1e293b' },
  { name: 'Siyah', color: '#000000' },
  { name: 'Krem', color: '#fef9f0' },
  { name: 'Açık Pembe', color: '#fce4ec' },
  { name: 'Açık Mavi', color: '#e3f2fd' },
  { name: 'Açık Yeşil', color: '#ecfdf5' },
  { name: 'Açık Sarı', color: '#fefce8' },
  { name: 'Açık Mor', color: '#f3e8ff' },
  { name: 'Açık Turuncu', color: '#fff7ed' },
  { name: 'Kırmızı', color: '#ef4444' },
  { name: 'Mavi', color: '#3b82f6' },
  { name: 'Yeşil', color: '#22c55e' },
  { name: 'Mor', color: '#8b5cf6' },
  { name: 'Turuncu', color: '#f97316' },
  { name: 'Pembe', color: '#ec4899' },
  { name: 'Turkuaz', color: '#06b6d4' },
  { name: 'Sarı', color: '#eab308' },
  { name: 'Lacivert', color: '#1e3a5f' },
  { name: 'Bordo', color: '#7f1d1d' },
  { name: 'Zümrüt', color: '#065f46' },
  { name: 'Kahverengi', color: '#78350f' },
];

export default function BackgroundsPanel() {
  const { setCanvasBackgroundColor, canvasBackgroundColor, addShape, canvasSize } = useEditor();
  const [activeTab, setActiveTab] = useState<BgTab>('solid');
  const [customColor, setCustomColor] = useState(canvasBackgroundColor);

  const handleGradient = (gradient: GradientDef) => {
    // Gradient'i çubuklara dönüştür (canvas üzerine rect olarak uygula)
    const stops = gradient.stops;
    const stepCount = stops.length;
    const height = canvasSize.height;
    const width = canvasSize.width;

    // Canvas arka planını ilk renkle ayarla
    setCanvasBackgroundColor(stops[0].color);

    // Gradient efekti için şeritler ekle
    const totalSteps = 20;
    for (let i = 0; i < totalSteps; i++) {
      const progress = i / totalSteps;
      // Renk interpolasyonu - basit geçiş
      let colorIdx = 0;
      for (let j = 0; j < stops.length - 1; j++) {
        if (progress >= stops[j].offset && progress <= stops[j + 1].offset) {
          colorIdx = j;
          break;
        }
      }
      const stop1 = stops[colorIdx];
      const stop2 = stops[Math.min(colorIdx + 1, stops.length - 1)];
      const localProgress = stop2.offset === stop1.offset ? 0 : (progress - stop1.offset) / (stop2.offset - stop1.offset);

      const color = interpolateColor(stop1.color, stop2.color, localProgress);

      const isVertical = (gradient.angle || 180) >= 135 && (gradient.angle || 180) <= 225;

      if (isVertical) {
        addShape('rectangle', {
          left: 0,
          top: (height / totalSteps) * i,
          width: width,
          height: height / totalSteps + 1,
          fill: color,
          strokeWidth: 0,
          selectable: false,
          evented: false,
        });
      } else {
        addShape('rectangle', {
          left: (width / totalSteps) * i,
          top: 0,
          width: width / totalSteps + 1,
          height: height,
          fill: color,
          strokeWidth: 0,
          selectable: false,
          evented: false,
        });
      }
    }
  };

  const handlePattern = (pattern: PatternDef) => {
    setCanvasBackgroundColor(pattern.backgroundColor);
    // Overlay pattern rects
    const patternSize = 40 * pattern.scale;
    const cols = Math.ceil(canvasSize.width / patternSize);
    const rows = Math.ceil(canvasSize.height / patternSize);

    // Sadece basit bir pattern overlay kullanalım - max 100 eleman
    const maxElements = 80;
    const step = Math.max(1, Math.floor((cols * rows) / maxElements));

    let count = 0;
    for (let r = 0; r < rows && count < maxElements; r++) {
      for (let c = 0; c < cols && count < maxElements; c++) {
        if ((r * cols + c) % step !== 0) continue;
        count++;

        if (pattern.type === 'dots') {
          addShape('circle', {
            left: c * patternSize + patternSize / 2 - 3,
            top: r * patternSize + patternSize / 2 - 3,
            radius: 3,
            fill: pattern.color,
            strokeWidth: 0,
            selectable: false,
            evented: false,
          });
        } else if (pattern.type === 'checkerboard') {
          if ((r + c) % 2 === 0) {
            addShape('rectangle', {
              left: c * patternSize,
              top: r * patternSize,
              width: patternSize,
              height: patternSize,
              fill: pattern.color,
              strokeWidth: 0,
              selectable: false,
              evented: false,
            });
          }
        }
      }
    }
  };

  const tabs: { id: BgTab; label: string; icon: React.ComponentType<{ size?: number; className?: string }> }[] = [
    { id: 'solid', label: 'Düz Renk', icon: Palette },
    { id: 'gradient', label: 'Gradient', icon: Droplets },
    { id: 'pattern', label: 'Desen', icon: Grid3X3 },
  ];

  return (
    <div className="flex flex-col h-full overflow-y-auto">
      {/* Tabs */}
      <div className="flex gap-1 p-3">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex-1 flex items-center justify-center gap-1 py-2 text-[11px] font-bold rounded-lg transition-colors
              ${activeTab === tab.id ? 'bg-primary/20 text-primary' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
          >
            <tab.icon size={13} />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="h-px bg-slate-700 mx-3" />

      {/* Düz Renk */}
      {activeTab === 'solid' && (
        <div className="p-3 space-y-3">
          {/* Mevcut renk */}
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 rounded-lg border border-slate-600" style={{ backgroundColor: canvasBackgroundColor }} />
            <span className="text-xs text-slate-400">{canvasBackgroundColor}</span>
          </div>

          {/* Hazır renkler */}
          <h4 className="text-[10px] font-bold text-slate-500 uppercase">Önerilen Renkler</h4>
          <div className="grid grid-cols-6 gap-1.5">
            {SOLID_COLORS.map(c => (
              <button
                key={c.color}
                onClick={() => { setCanvasBackgroundColor(c.color); setCustomColor(c.color); }}
                className={`aspect-square rounded-lg border transition-transform hover:scale-110 ${
                  canvasBackgroundColor === c.color ? 'border-primary ring-2 ring-primary/30' : 'border-slate-600'
                }`}
                style={{ backgroundColor: c.color }}
                title={c.name}
              />
            ))}
          </div>

          <div className="h-px bg-slate-700" />

          {/* Tüm palet */}
          <h4 className="text-[10px] font-bold text-slate-500 uppercase">Renk Paleti</h4>
          <div className="grid grid-cols-10 gap-1">
            {COLOR_PALETTE.map(color => (
              <button
                key={color}
                onClick={() => { setCanvasBackgroundColor(color); setCustomColor(color); }}
                className="w-full aspect-square rounded border border-slate-600/50 hover:scale-125 transition-transform"
                style={{ backgroundColor: color }}
              />
            ))}
          </div>

          <div className="h-px bg-slate-700" />

          {/* Özel renk */}
          <h4 className="text-[10px] font-bold text-slate-500 uppercase">Özel Renk</h4>
          <div className="flex items-center gap-2">
            <input
              type="color"
              value={customColor}
              onChange={e => { setCustomColor(e.target.value); setCanvasBackgroundColor(e.target.value); }}
              className="w-10 h-10 rounded-lg cursor-pointer border border-slate-600"
            />
            <input
              type="text"
              value={customColor}
              onChange={e => {
                setCustomColor(e.target.value);
                if (/^#[0-9A-Fa-f]{6}$/.test(e.target.value)) {
                  setCanvasBackgroundColor(e.target.value);
                }
              }}
              className="flex-1 bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-xs text-white font-mono"
              placeholder="#000000"
            />
          </div>
        </div>
      )}

      {/* Gradient */}
      {activeTab === 'gradient' && (
        <div className="p-3 space-y-3">
          <p className="text-[10px] text-slate-500">Gradient arka plan uygulandığında canvas üzerine şeritler eklenir.</p>
          <div className="grid grid-cols-2 gap-2">
            {GRADIENT_PRESETS.map(gradient => {
              const gradientCSS = gradient.type === 'linear'
                ? `linear-gradient(${gradient.angle || 180}deg, ${gradient.stops.map(s => `${s.color} ${s.offset * 100}%`).join(', ')})`
                : `radial-gradient(circle, ${gradient.stops.map(s => `${s.color} ${s.offset * 100}%`).join(', ')})`;

              return (
                <button
                  key={gradient.id}
                  onClick={() => handleGradient(gradient)}
                  className="flex flex-col rounded-xl overflow-hidden border border-slate-700 hover:border-primary/50 transition-all hover:shadow-md group"
                >
                  <div
                    className="h-16 w-full"
                    style={{ background: gradientCSS }}
                  />
                  <div className="px-2 py-1.5 bg-slate-800/50">
                    <span className="text-[10px] text-slate-300 font-medium">{gradient.name}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Pattern */}
      {activeTab === 'pattern' && (
        <div className="p-3 space-y-3">
          <p className="text-[10px] text-slate-500">Desen arka planları küçük şekiller olarak canvas üzerine eklenir.</p>
          <div className="grid grid-cols-2 gap-2">
            {PATTERN_PRESETS.map(pattern => (
              <button
                key={pattern.id}
                onClick={() => handlePattern(pattern)}
                className="flex flex-col rounded-xl overflow-hidden border border-slate-700 hover:border-primary/50 transition-all group"
              >
                <div
                  className="h-14 w-full"
                  style={{ backgroundColor: pattern.backgroundColor }}
                >
                  {/* Mini pattern preview */}
                  <svg className="w-full h-full" viewBox="0 0 100 56">
                    {pattern.type === 'dots' && Array.from({ length: 5 }, (_, r) =>
                      Array.from({ length: 8 }, (_, c) => (
                        <circle key={`${r}-${c}`} cx={c * 12 + 6} cy={r * 12 + 6} r={2} fill={pattern.color} />
                      ))
                    ).flat()}
                    {pattern.type === 'stripes' && Array.from({ length: 10 }, (_, i) => (
                      <rect key={i} x={i * 10} y={0} width={4} height={56} fill={pattern.color} />
                    ))}
                    {pattern.type === 'grid' && (
                      <>
                        {Array.from({ length: 6 }, (_, i) => (
                          <line key={`h${i}`} x1={0} y1={i * 12} x2={100} y2={i * 12} stroke={pattern.color} strokeWidth={0.5} />
                        ))}
                        {Array.from({ length: 9 }, (_, i) => (
                          <line key={`v${i}`} x1={i * 12} y1={0} x2={i * 12} y2={56} stroke={pattern.color} strokeWidth={0.5} />
                        ))}
                      </>
                    )}
                    {pattern.type === 'checkerboard' && Array.from({ length: 5 }, (_, r) =>
                      Array.from({ length: 8 }, (_, c) => (r + c) % 2 === 0 ? (
                        <rect key={`${r}-${c}`} x={c * 12} y={r * 12} width={12} height={12} fill={pattern.color} />
                      ) : null)
                    ).flat()}
                    {pattern.type === 'diagonal' && Array.from({ length: 12 }, (_, i) => (
                      <line key={i} x1={i * 10 - 10} y1={56} x2={i * 10 + 40} y2={0} stroke={pattern.color} strokeWidth={1} />
                    ))}
                    {(pattern.type === 'diamond' || pattern.type === 'cross' || pattern.type === 'zigzag' || pattern.type === 'waves') && Array.from({ length: 5 }, (_, r) =>
                      Array.from({ length: 8 }, (_, c) => (
                        <circle key={`${r}-${c}`} cx={c * 14 + 7} cy={r * 14 + 7} r={1.5} fill={pattern.color} />
                      ))
                    ).flat()}
                  </svg>
                </div>
                <div className="px-2 py-1.5 bg-slate-800/50">
                  <span className="text-[10px] text-slate-300 font-medium">{pattern.name}</span>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Yardımcı: Renk interpolasyonu ─────────────────────
function interpolateColor(color1: string, color2: string, factor: number): string {
  const hex = (c: string) => parseInt(c, 16);
  const r1 = hex(color1.slice(1, 3)), g1 = hex(color1.slice(3, 5)), b1 = hex(color1.slice(5, 7));
  const r2 = hex(color2.slice(1, 3)), g2 = hex(color2.slice(3, 5)), b2 = hex(color2.slice(5, 7));
  const r = Math.round(r1 + (r2 - r1) * factor);
  const g = Math.round(g1 + (g2 - g1) * factor);
  const b = Math.round(b1 + (b2 - b1) * factor);
  return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
}

