"use client";

import React, { useState, useEffect } from 'react';
import { useEditor } from '../EditorContext';
import { FILTER_PRESETS, DEFAULT_FILTERS } from '../types';
import type { FilterSettings } from '../types';
import {
  Sparkles, RotateCcw, SunMedium, Contrast, Droplets,
  CircleDot, Palette, Eye, Sliders,
} from 'lucide-react';

export default function FiltersPanel() {
  const { activeObject, applyFiltersToSelected, filterSettings, setFilterSettings } = useEditor();
  const [localSettings, setLocalSettings] = useState<FilterSettings>({ ...DEFAULT_FILTERS });
  const isImage = activeObject && activeObject.type === 'image';

  // Seçili nesne değiştiğinde filtre ayarlarını sıfırla
  useEffect(() => {
    if (isImage) {
      setLocalSettings({ ...filterSettings });
    }
  }, [activeObject]);

  const handleSliderChange = (key: keyof FilterSettings, value: number | boolean) => {
    const newSettings = { ...localSettings, [key]: value };
    setLocalSettings(newSettings);
    if (isImage) {
      applyFiltersToSelected(newSettings);
    }
  };

  const handlePresetApply = (preset: typeof FILTER_PRESETS[0]) => {
    const newSettings = { ...DEFAULT_FILTERS, ...preset.settings };
    setLocalSettings(newSettings);
    if (isImage) {
      applyFiltersToSelected(newSettings);
    }
  };

  const handleReset = () => {
    setLocalSettings({ ...DEFAULT_FILTERS });
    if (isImage) {
      applyFiltersToSelected({ ...DEFAULT_FILTERS });
    }
  };

  interface SliderDef {
    key: keyof FilterSettings;
    label: string;
    icon: React.ComponentType<{ size?: number; className?: string }>;
    min: number;
    max: number;
    step: number;
    unit?: string;
  }

  const sliders: SliderDef[] = [
    { key: 'brightness', label: 'Parlaklık', icon: SunMedium, min: -1, max: 1, step: 0.05 },
    { key: 'contrast', label: 'Kontrast', icon: Contrast, min: -1, max: 1, step: 0.05 },
    { key: 'saturation', label: 'Doygunluk', icon: Palette, min: -1, max: 1, step: 0.05 },
    { key: 'blur', label: 'Bulanıklık', icon: Droplets, min: 0, max: 1, step: 0.02 },
    { key: 'hueRotation', label: 'Renk Tonu', icon: CircleDot, min: -180, max: 180, step: 5, unit: '°' },
  ];

  interface ToggleDef {
    key: keyof FilterSettings;
    label: string;
  }

  const toggles: ToggleDef[] = [
    { key: 'grayscale', label: 'Siyah & Beyaz' },
    { key: 'sepia', label: 'Sepya' },
    { key: 'invert', label: 'Negatif' },
  ];

  return (
    <div className="flex flex-col h-full overflow-y-auto">
      {/* Uyarı - görsel seçili değilse */}
      {!isImage && (
        <div className="p-3">
          <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-4 text-center">
            <Eye size={24} className="mx-auto text-amber-400 mb-2" />
            <p className="text-sm font-medium text-amber-300">Filtre Uygulamak İçin</p>
            <p className="text-[11px] text-amber-400/70 mt-1">
              Kanvasta bir görsel seçin,<br />sonra filtre uygulayın.
            </p>
          </div>
        </div>
      )}

      {/* Filtre presetleri */}
      <div className="p-3">
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Filtre Presetleri</h3>
          <button onClick={handleReset} className="text-[10px] text-slate-500 hover:text-primary flex items-center gap-1 transition-colors">
            <RotateCcw size={10} /> Sıfırla
          </button>
        </div>
        <div className="grid grid-cols-3 gap-1.5">
          {FILTER_PRESETS.map(preset => (
            <button
              key={preset.id}
              onClick={() => handlePresetApply(preset)}
              disabled={!isImage}
              className={`flex flex-col items-center gap-1 p-2 rounded-lg border transition-all
                ${!isImage ? 'opacity-40 cursor-not-allowed border-slate-800' :
                  'border-slate-700 hover:border-primary/50 hover:bg-primary/5 cursor-pointer'}`}
            >
              {/* Mini önizleme */}
              <div className="w-full aspect-square rounded-md overflow-hidden bg-slate-700/50 relative">
                <div
                  className="w-full h-full bg-gradient-to-br from-blue-400 via-purple-400 to-pink-400"
                  style={{
                    filter: [
                      preset.settings.brightness ? `brightness(${1 + (preset.settings.brightness || 0)})` : '',
                      preset.settings.contrast ? `contrast(${1 + (preset.settings.contrast || 0)})` : '',
                      preset.settings.saturation ? `saturate(${1 + (preset.settings.saturation || 0)})` : '',
                      preset.settings.grayscale ? 'grayscale(1)' : '',
                      preset.settings.sepia ? 'sepia(1)' : '',
                      preset.settings.invert ? 'invert(1)' : '',
                      preset.settings.hueRotation ? `hue-rotate(${preset.settings.hueRotation}deg)` : '',
                    ].filter(Boolean).join(' ') || 'none',
                  }}
                />
              </div>
              <span className="text-[9px] text-slate-400 font-medium">{preset.name}</span>
            </button>
          ))}
        </div>
      </div>

      <div className="h-px bg-slate-700 mx-3" />

      {/* Manuel ayarlar */}
      <div className="p-3 space-y-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
          <Sliders size={12} />
          Detaylı Ayarlar
        </h3>

        {sliders.map(slider => (
          <div key={slider.key}>
            <div className="flex items-center justify-between mb-1">
              <label className="text-[11px] text-slate-400 flex items-center gap-1.5">
                <slider.icon size={12} />
                {slider.label}
              </label>
              <span className="text-[10px] text-slate-500 tabular-nums">
                {typeof localSettings[slider.key] === 'number'
                  ? slider.unit
                    ? `${localSettings[slider.key]}${slider.unit}`
                    : (localSettings[slider.key] as number).toFixed(2)
                  : ''}
              </span>
            </div>
            <input
              type="range"
              min={slider.min}
              max={slider.max}
              step={slider.step}
              value={localSettings[slider.key] as number}
              onChange={e => handleSliderChange(slider.key, parseFloat(e.target.value))}
              disabled={!isImage}
              className="w-full accent-primary disabled:opacity-40"
            />
          </div>
        ))}

        <div className="h-px bg-slate-700" />

        {/* Toggle efektler */}
        <div className="space-y-2">
          {toggles.map(toggle => (
            <label key={toggle.key} className={`flex items-center justify-between py-1.5 ${!isImage ? 'opacity-40' : 'cursor-pointer'}`}>
              <span className="text-[11px] text-slate-400">{toggle.label}</span>
              <button
                onClick={() => isImage && handleSliderChange(toggle.key, !localSettings[toggle.key])}
                disabled={!isImage}
                className={`w-9 h-5 rounded-full transition-colors relative ${localSettings[toggle.key] ? 'bg-primary' : 'bg-slate-700'}`}
              >
                <div className={`w-3.5 h-3.5 rounded-full bg-white absolute top-0.5 transition-transform ${localSettings[toggle.key] ? 'translate-x-[18px]' : 'translate-x-0.5'}`} />
              </button>
            </label>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useCallback } from 'react';
import { useEditor } from '../EditorContext';
import {
  Upload, Link, ImageIcon, Package, X, Loader2,
  Search, RefreshCw, Store,
} from 'lucide-react';

interface ImportedImage {
  id: string;
  url: string;
  name: string;
  isMain?: boolean;
}

export default function ImagesPanel() {
  const { addImageFromURL, canvasSize } = useEditor();
  const [urlInput, setUrlInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [productId, setProductId] = useState('');
  const [productImages, setProductImages] = useState<ImportedImage[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [recentImages, setRecentImages] = useState<ImportedImage[]>([]);
  const [dragOver, setDragOver] = useState(false);

  const handleAddFromURL = async () => {
    if (!urlInput.trim()) return;
    setIsLoading(true);
    try {
      await addImageFromURL(urlInput.trim());
      setRecentImages(prev => [{ id: Date.now().toString(), url: urlInput.trim(), name: 'URL Görseli' }, ...prev].slice(0, 20));
      setUrlInput('');
    } catch {
      alert('Görsel yüklenemedi. URL\'yi kontrol edin.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleFileUpload = useCallback(async (files: FileList | null) => {
    if (!files) return;
    setIsLoading(true);
    for (const file of Array.from(files)) {
      if (!file.type.startsWith('image/')) continue;
      const reader = new FileReader();
      reader.onload = async (e) => {
        const url = e.target?.result as string;
        await addImageFromURL(url);
        setRecentImages(prev => [{ id: Date.now().toString(), url, name: file.name }, ...prev].slice(0, 20));
      };
      reader.readAsDataURL(file);
    }
    setIsLoading(false);
  }, [addImageFromURL]);

  const triggerFileUpload = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.multiple = true;
    input.onchange = (e: any) => handleFileUpload(e.target.files);
    input.click();
  };

  // Ürün görsellerini çekme (pazaryeri entegrasyonu)
  const fetchProductImages = async () => {
    if (!productId.trim()) return;
    setLoadingProducts(true);
    try {
      const API_URL = process.env.NEXT_PUBLIC_API_URL || '';
      const response = await fetch(`${API_URL}/products/${productId.trim()}`, {
        headers: { 'Content-Type': 'application/json' },
      });
      if (response.ok) {
        const product = await response.json();
        const images = (product.images || []).map((img: any) => ({
          id: img.id,
          url: img.url,
          name: `${product.title || 'Ürün'} - Görsel`,
          isMain: img.isMain,
        }));
        setProductImages(images);
      }
    } catch {
      // API erişilemiyorsa demo görseller göster
      setProductImages([]);
    } finally {
      setLoadingProducts(false);
    }
  };

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    handleFileUpload(e.dataTransfer.files);
  }, [handleFileUpload]);

  return (
    <div className="flex flex-col h-full overflow-y-auto">
      {/* Dosya yükleme alanı */}
      <div className="p-3">
        <div
          className={`border-2 border-dashed rounded-xl p-6 text-center transition-all cursor-pointer
            ${dragOver ? 'border-primary bg-primary/10' : 'border-slate-700 hover:border-slate-500 hover:bg-slate-800/50'}`}
          onClick={triggerFileUpload}
          onDragOver={e => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={handleDrop}
        >
          {isLoading ? (
            <Loader2 size={28} className="mx-auto text-primary animate-spin mb-2" />
          ) : (
            <Upload size={28} className="mx-auto text-slate-400 mb-2" />
          )}
          <p className="text-sm font-medium text-slate-300">
            {dragOver ? 'Bırakın...' : 'Görsel Yükle'}
          </p>
          <p className="text-[10px] text-slate-500 mt-1">Sürükle & Bırak veya Tıkla</p>
          <p className="text-[10px] text-slate-600 mt-0.5">PNG, JPG, WebP, SVG</p>
        </div>
      </div>

      {/* URL ile ekleme */}
      <div className="px-3 pb-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">URL ile Ekle</h3>
        <div className="flex gap-1.5">
          <div className="relative flex-1">
            <Link size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" />
            <input
              type="url"
              value={urlInput}
              onChange={e => setUrlInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleAddFromURL()}
              placeholder="https://..."
              className="w-full pl-8 pr-3 py-2 bg-slate-800 border border-slate-700 rounded-lg text-xs text-white placeholder:text-slate-500 focus:outline-none focus:border-primary"
            />
          </div>
          <button
            onClick={handleAddFromURL}
            disabled={!urlInput.trim() || isLoading}
            className="px-3 py-2 bg-primary hover:bg-primary/80 disabled:bg-slate-700 text-white text-xs font-bold rounded-lg transition-colors disabled:opacity-50"
          >
            Ekle
          </button>
        </div>
      </div>

      <div className="h-px bg-slate-700 mx-3" />

      {/* Pazaryeri ürün görselleri */}
      <div className="p-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-1.5">
          <Store size={12} />
          Pazaryeri Ürün Görselleri
        </h3>
        <div className="flex gap-1.5 mb-3">
          <div className="relative flex-1">
            <Package size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" />
            <input
              type="text"
              value={productId}
              onChange={e => setProductId(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && fetchProductImages()}
              placeholder="Ürün ID girin..."
              className="w-full pl-8 pr-3 py-2 bg-slate-800 border border-slate-700 rounded-lg text-xs text-white placeholder:text-slate-500 focus:outline-none focus:border-primary"
            />
          </div>
          <button
            onClick={fetchProductImages}
            disabled={!productId.trim() || loadingProducts}
            className="px-3 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-700 text-white text-xs font-bold rounded-lg transition-colors disabled:opacity-50"
          >
            {loadingProducts ? <Loader2 size={14} className="animate-spin" /> : <Search size={14} />}
          </button>
        </div>

        {productImages.length > 0 && (
          <div className="grid grid-cols-3 gap-1.5 mb-3">
            {productImages.map(img => (
              <button
                key={img.id}
                onClick={() => addImageFromURL(img.url)}
                className="aspect-square rounded-lg overflow-hidden border border-slate-700 hover:border-primary/50 transition-all relative group"
              >
                <img src={img.url} alt={img.name} className="w-full h-full object-cover" crossOrigin="anonymous" />
                {img.isMain && (
                  <span className="absolute top-1 right-1 px-1 py-0.5 bg-primary text-white text-[8px] font-bold rounded">
                    ANA
                  </span>
                )}
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                  <ImageIcon size={16} className="text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
              </button>
            ))}
          </div>
        )}

        {productImages.length === 0 && productId && !loadingProducts && (
          <p className="text-[11px] text-slate-500 text-center py-3">
            Ürün görseli bulunamadı veya API erişilemiyor.
          </p>
        )}
      </div>

      <div className="h-px bg-slate-700 mx-3" />

      {/* Son yüklenenler */}
      {recentImages.length > 0 && (
        <div className="p-3">
          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Son Yüklenenler</h3>
          <div className="grid grid-cols-3 gap-1.5">
            {recentImages.map(img => (
              <button
                key={img.id}
                onClick={() => addImageFromURL(img.url)}
                className="aspect-square rounded-lg overflow-hidden border border-slate-700 hover:border-primary/50 transition-all group"
              >
                <img src={img.url} alt={img.name} className="w-full h-full object-cover" crossOrigin="anonymous" />
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Stok görselleri ipucu */}
      <div className="p-3 mt-auto">
        <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-3">
          <p className="text-[11px] text-slate-400 leading-relaxed">
            💡 <strong>İpucu:</strong> Ürünlerinizin pazaryeri görsellerini ID ile çekip doğrudan editörde düzenleyebilirsiniz. Düzenleme sonrası <strong>Dışa Aktar</strong> ile kaydedip tekrar platformlara yükleyebilirsiniz.
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useMemo } from 'react';
import { useEditor } from '../EditorContext';
import { CANVAS_PRESETS } from '../types';
import { ADVANCED_TEMPLATES, TEMPLATE_CATEGORIES } from '../templates/advanced-templates';
import {
  Store, Instagram, Monitor, Search, X, Sparkles, Eye,
} from 'lucide-react';

const categoryIcons: Record<string, React.ComponentType<{ size?: number; className?: string }>> = {
  marketplace: Store,
  social: Instagram,
  custom: Monitor,
};

const categoryLabels: Record<string, string> = {
  marketplace: 'Pazaryeri',
  social: 'Sosyal Medya',
  custom: 'Standart',
};

export default function TemplatesPanel() {
  const { setCanvasSize, setCanvasBackgroundColor, addText, addShape, clearCanvas } = useEditor();
  const [presetCategory, setPresetCategory] = useState<string>('all');
  const [templateCategory, setTemplateCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [showPresets, setShowPresets] = useState(false);
  const [hoveredTemplate, setHoveredTemplate] = useState<string | null>(null);

  const handleSelectPreset = (preset: typeof CANVAS_PRESETS[0]) => {
    setCanvasSize({ width: preset.width, height: preset.height, name: preset.name });
  };

  const handleApplyTemplate = async (template: typeof ADVANCED_TEMPLATES[0]) => {
    // Canvas boyutunu ayarla
    setCanvasSize({
      width: template.canvasWidth,
      height: template.canvasHeight,
      name: template.name,
    });

    clearCanvas();
    setCanvasBackgroundColor(template.backgroundColor);

    // Tüm elementleri sırayla ekle
    let delay = 100;
    for (const element of template.elements) {
      await new Promise(resolve => setTimeout(resolve, delay));
      delay = 30; // İlk eleman sonrası daha hızlı
      
      if (element.type === 'text') {
        const { text, ...props } = element.props;
        addText(text, props);
      } else {
        const typeMap: Record<string, string> = {
          rect: 'rectangle',
          circle: 'circle',
          triangle: 'triangle',
          ellipse: 'ellipse',
          line: 'line',
          polygon: 'polygon',
        };
        const shapeName = typeMap[element.type] || element.type;
        addShape(shapeName, element.props);
      }
    }
  };

  const filteredPresets = CANVAS_PRESETS.filter(p =>
    presetCategory === 'all' || p.category === presetCategory
  );

  const filteredTemplates = useMemo(() => {
    return ADVANCED_TEMPLATES.filter(t => {
      const matchesCategory = templateCategory === 'all' || t.category === templateCategory;
      const matchesSearch = searchQuery === '' ||
        t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        t.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        t.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()));
      return matchesCategory && matchesSearch;
    });
  }, [templateCategory, searchQuery]);

  // Basit template thumbnail renderer
  const renderMiniPreview = (template: typeof ADVANCED_TEMPLATES[0]) => {
    const scaleX = 120 / template.canvasWidth;
    const scaleY = 80 / template.canvasHeight;
    const scale = Math.min(scaleX, scaleY);
    const w = template.canvasWidth * scale;
    const h = template.canvasHeight * scale;

    return (
      <div
        className="relative overflow-hidden rounded-lg flex items-center justify-center"
        style={{ width: '100%', aspectRatio: `${template.canvasWidth}/${template.canvasHeight}`, maxHeight: 100, backgroundColor: template.backgroundColor }}
      >
        {/* Basitleştirilmiş mini önizleme - ilk birkaç elemanı göster */}
        <svg width="100%" height="100%" viewBox={`0 0 ${template.canvasWidth} ${template.canvasHeight}`} preserveAspectRatio="xMidYMid meet">
          {template.elements.slice(0, 8).map((el, i) => {
            if (el.type === 'rect') {
              return (
                <rect
                  key={i}
                  x={el.props.left || 0}
                  y={el.props.top || 0}
                  width={el.props.width || 100}
                  height={el.props.height || 100}
                  fill={el.props.fill || 'transparent'}
                  rx={el.props.rx || 0}
                  opacity={el.props.opacity || 1}
                />
              );
            }
            if (el.type === 'circle') {
              return (
                <circle
                  key={i}
                  cx={(el.props.left || 0) + (el.props.radius || 0)}
                  cy={(el.props.top || 0) + (el.props.radius || 0)}
                  r={el.props.radius || 20}
                  fill={el.props.fill || '#ccc'}
                  opacity={el.props.opacity || 1}
                />
              );
            }
            if (el.type === 'text' && el.props.fontSize >= 32) {
              return (
                <text
                  key={i}
                  x={el.props.left || 0}
                  y={(el.props.top || 0) + (el.props.fontSize || 16)}
                  fill={el.props.fill || '#000'}
                  fontSize={el.props.fontSize || 16}
                  fontWeight={el.props.fontWeight || 'normal'}
                  opacity={el.props.opacity || 1}
                >
                  {(el.props.text || '').split('\n')[0].substring(0, 20)}
                </text>
              );
            }
            return null;
          })}
        </svg>
        {hoveredTemplate === template.id && (
          <div className="absolute inset-0 bg-black/40 flex items-center justify-center backdrop-blur-sm transition-all">
            <div className="flex items-center gap-1 text-white text-[10px] font-bold bg-primary/80 px-2 py-1 rounded-full">
              <Eye size={10} /> Uygula
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full">
      {/* Arama */}
      <div className="p-3">
        <div className="relative">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input
            type="text"
            placeholder="Şablon ara... (ör: indirim, story, trendyol)"
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-8 py-2 bg-slate-800 border border-slate-700 rounded-lg text-sm text-white placeholder:text-slate-500 focus:outline-none focus:border-primary"
          />
          {searchQuery && (
            <button
              onClick={() => setSearchQuery('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white"
            >
              <X size={14} />
            </button>
          )}
        </div>
      </div>

      {/* Boyut preset'leri toggle */}
      <div className="px-3 pb-2">
        <button
          onClick={() => setShowPresets(!showPresets)}
          className="w-full flex items-center justify-between px-3 py-2 bg-slate-800/50 border border-slate-700 rounded-lg text-sm text-slate-300 hover:border-slate-600 transition-colors"
        >
          <span className="text-xs font-bold">📐 Canvas Boyutu Seç</span>
          <span className="text-[10px] text-slate-500">{showPresets ? '▲' : '▼'}</span>
        </button>

        {showPresets && (
          <div className="mt-2 p-2 bg-slate-800/80 border border-slate-700 rounded-lg">
            <div className="flex gap-1 mb-2">
              {['all', 'marketplace', 'social', 'custom'].map(cat => (
                <button
                  key={cat}
                  onClick={() => setPresetCategory(cat)}
                  className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-colors
                    ${presetCategory === cat ? 'bg-primary/20 text-primary' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
                >
                  {cat === 'all' ? 'Tümü' : categoryLabels[cat]}
                </button>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-1.5 max-h-36 overflow-y-auto scrollbar-thin">
              {filteredPresets.map(preset => (
                <button
                  key={preset.name}
                  onClick={() => handleSelectPreset(preset)}
                  className="flex flex-col items-center gap-0.5 p-1.5 rounded-lg border border-slate-700 hover:border-primary/50 hover:bg-primary/5 transition-all"
                >
                  <div className="w-full flex items-center justify-center h-6">
                    <div className="bg-slate-600 rounded-sm" style={{ aspectRatio: `${preset.width}/${preset.height}`, height: 20 }} />
                  </div>
                  <span className="text-[9px] text-slate-300 truncate w-full text-center">{preset.name}</span>
                  <span className="text-[8px] text-slate-500">{preset.width}×{preset.height}</span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="h-px bg-slate-700 mx-3" />

      {/* Şablon Kategorileri */}
      <div className="px-3 py-2">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-1.5">
          <Sparkles size={12} /> Gelişmiş Şablonlar
          <span className="ml-auto text-[10px] font-normal text-slate-500">{filteredTemplates.length} şablon</span>
        </h3>
        <div className="flex gap-1 overflow-x-auto pb-1 scrollbar-thin">
          {TEMPLATE_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setTemplateCategory(cat.id)}
              className={`flex items-center gap-1 px-2.5 py-1.5 rounded-full text-[10px] font-bold whitespace-nowrap transition-colors shrink-0
                ${templateCategory === cat.id
                  ? 'bg-primary/20 text-primary border border-primary/30'
                  : 'text-slate-500 hover:text-slate-300 hover:bg-white/5 border border-transparent'
                }`}
            >
              <span>{cat.icon}</span>
              {cat.name}
            </button>
          ))}
        </div>
      </div>

      {/* Şablon Grid */}
      <div className="flex-1 overflow-y-auto px-3 py-1 scrollbar-thin">
        {filteredTemplates.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <Search size={32} className="text-slate-600 mb-3" />
            <p className="text-sm text-slate-500">Şablon bulunamadı</p>
            <p className="text-[11px] text-slate-600 mt-1">Farklı anahtar kelimeler deneyin</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-2 pb-4">
            {filteredTemplates.map(template => (
              <button
                key={template.id}
                onClick={() => handleApplyTemplate(template)}
                onMouseEnter={() => setHoveredTemplate(template.id)}
                onMouseLeave={() => setHoveredTemplate(null)}
                className="group flex flex-col rounded-xl overflow-hidden border border-slate-700 hover:border-primary/50 transition-all hover:shadow-lg hover:shadow-primary/10 hover:scale-[1.02]"
              >
                {renderMiniPreview(template)}
                <div className="p-2 bg-slate-800/50">
                  <p className="text-[11px] font-bold text-slate-200 truncate">{template.name}</p>
                  <p className="text-[9px] text-slate-500 truncate">{template.description}</p>
                  <div className="flex gap-1 mt-1 flex-wrap">
                    {template.tags.slice(0, 2).map(tag => (
                      <span
                        key={tag}
                        className="text-[8px] bg-slate-700/60 text-slate-400 px-1.5 py-0.5 rounded-full"
                      >
                        {tag}
                      </span>
                    ))}
                    <span className="text-[8px] text-slate-600">
                      {template.canvasWidth}×{template.canvasHeight}
                    </span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useEditor } from '../EditorContext';
import { FONT_LIST, COLOR_PALETTE } from '../types';
import {
  Type, Bold, Italic, Underline, AlignLeft, AlignCenter,
  AlignRight, AlignJustify, Strikethrough, ChevronDown,
  Plus, Minus, Palette, Sparkles,
} from 'lucide-react';

interface TextPreset {
  label: string;
  fontSize: number;
  fontWeight: string;
  fontStyle: string;
  text: string;
  fill?: string;
  shadow?: { color: string; blur: number; offsetX: number; offsetY: number };
  stroke?: string;
  strokeWidth?: number;
}

const TEXT_PRESETS: TextPreset[] = [
  { label: 'Başlık', fontSize: 56, fontWeight: 'bold', fontStyle: 'normal', text: 'Başlık ekleyin' },
  { label: 'Alt Başlık', fontSize: 36, fontWeight: '600', fontStyle: 'normal', text: 'Alt başlık ekleyin' },
  { label: 'Gövde Metni', fontSize: 20, fontWeight: 'normal', fontStyle: 'normal', text: 'Gövde metni ekleyin' },
  { label: 'Küçük Metin', fontSize: 14, fontWeight: 'normal', fontStyle: 'normal', text: 'Küçük metin ekleyin' },
  { label: 'Etkileyici Başlık', fontSize: 72, fontWeight: '900', fontStyle: 'normal', text: 'WOW!' },
  { label: 'İndirim Etiketi', fontSize: 48, fontWeight: 'bold', fontStyle: 'normal', text: '%50 İNDİRİM', fill: '#ef4444' },
  { label: 'Ürün Fiyatı', fontSize: 42, fontWeight: 'bold', fontStyle: 'normal', text: '₺199.99', fill: '#22c55e' },
  { label: 'CTA Butonu Metni', fontSize: 24, fontWeight: 'bold', fontStyle: 'normal', text: 'HEMEN AL' },
  { label: 'Altyazı', fontSize: 16, fontWeight: 'normal', fontStyle: 'italic', text: 'Altyazı metni...' },
  { label: 'Logo Metni', fontSize: 40, fontWeight: '800', fontStyle: 'normal', text: 'MARKA' },
  { label: 'Neon Metin', fontSize: 48, fontWeight: 'bold', fontStyle: 'normal', text: 'NEON', fill: '#00ff88', shadow: { color: '#00ff88', blur: 20, offsetX: 0, offsetY: 0 } },
  { label: 'Gölgeli Başlık', fontSize: 52, fontWeight: '900', fontStyle: 'normal', text: 'GÖLGE', shadow: { color: 'rgba(0,0,0,0.5)', blur: 8, offsetX: 4, offsetY: 4 } },
  { label: 'Konturlu Metin', fontSize: 56, fontWeight: 'bold', fontStyle: 'normal', text: 'KONTUR', fill: 'transparent', stroke: '#ffffff', strokeWidth: 3 },
  { label: '3D Metin', fontSize: 48, fontWeight: '900', fontStyle: 'normal', text: '3D ETKİSİ', shadow: { color: 'rgba(0,0,0,0.6)', blur: 1, offsetX: 3, offsetY: 3 } },
  { label: 'Altın Metin', fontSize: 44, fontWeight: 'bold', fontStyle: 'normal', text: 'PREMIUM', fill: '#d4a853', shadow: { color: 'rgba(0,0,0,0.4)', blur: 6, offsetX: 2, offsetY: 2 } },
];

interface TextEffectDef {
  id: string;
  name: string;
  preview: string;
  apply: { shadow?: any; stroke?: string; strokeWidth?: number; fill?: string };
}

const TEXT_EFFECTS: TextEffectDef[] = [
  { id: 'none', name: 'Yok', preview: 'Aa', apply: { shadow: null, stroke: '', strokeWidth: 0 } },
  { id: 'shadow-soft', name: 'Yumuşak Gölge', preview: 'Aa', apply: { shadow: { color: 'rgba(0,0,0,0.4)', blur: 10, offsetX: 3, offsetY: 3 } } },
  { id: 'shadow-hard', name: 'Keskin Gölge', preview: 'Aa', apply: { shadow: { color: 'rgba(0,0,0,0.7)', blur: 1, offsetX: 4, offsetY: 4 } } },
  { id: 'glow-white', name: 'Beyaz Işıltı', preview: 'Aa', apply: { shadow: { color: 'rgba(255,255,255,0.8)', blur: 15, offsetX: 0, offsetY: 0 } } },
  { id: 'glow-blue', name: 'Mavi Işıltı', preview: 'Aa', apply: { shadow: { color: '#3b82f6', blur: 20, offsetX: 0, offsetY: 0 } } },
  { id: 'glow-green', name: 'Yeşil Neon', preview: 'Aa', apply: { shadow: { color: '#00ff88', blur: 20, offsetX: 0, offsetY: 0 } } },
  { id: 'glow-pink', name: 'Pembe Neon', preview: 'Aa', apply: { shadow: { color: '#ff00ff', blur: 20, offsetX: 0, offsetY: 0 } } },
  { id: 'stroke-white', name: 'Beyaz Kontur', preview: 'Aa', apply: { stroke: '#ffffff', strokeWidth: 2 } },
  { id: 'stroke-black', name: 'Siyah Kontur', preview: 'Aa', apply: { stroke: '#000000', strokeWidth: 2 } },
  { id: '3d-effect', name: '3D Efekti', preview: 'Aa', apply: { shadow: { color: 'rgba(0,0,0,0.6)', blur: 0, offsetX: 3, offsetY: 3 } } },
  { id: 'retro', name: 'Retro', preview: 'Aa', apply: { shadow: { color: '#ef4444', blur: 0, offsetX: 3, offsetY: 3 }, stroke: '#1a1a1a', strokeWidth: 1 } },
  { id: 'emboss', name: 'Kabartma', preview: 'Aa', apply: { shadow: { color: 'rgba(255,255,255,0.5)', blur: 2, offsetX: -1, offsetY: -1 } } },
];

export default function TextPanel() {
  const {
    addText, activeObject, canvasRef,
    fontSize, setFontSize, fontFamily, setFontFamily, fillColor, setFillColor,
  } = useEditor();
  const [showFontPicker, setShowFontPicker] = useState(false);
  const [showColorPicker, setShowColorPicker] = useState(false);
  const [fontSearch, setFontSearch] = useState('');

  const isTextSelected = activeObject && (activeObject.type === 'textbox' || activeObject.type === 'text' || activeObject.type === 'i-text');

  const handlePresetAdd = (preset: TextPreset) => {
    addText(preset.text, {
      fontSize: preset.fontSize,
      fontWeight: preset.fontWeight,
      fontStyle: preset.fontStyle,
      fill: preset.fill || fillColor,
      fontFamily: fontFamily,
      ...(preset.shadow ? { shadow: preset.shadow } : {}),
      ...(preset.stroke ? { stroke: preset.stroke, strokeWidth: preset.strokeWidth || 2 } : {}),
    });
  };

  const updateTextProp = (prop: string, value: any) => {
    if (!isTextSelected || !canvasRef.current) return;
    activeObject.set(prop, value);
    canvasRef.current.renderAll();
  };

  const toggleBold = () => {
    const current = activeObject?.fontWeight;
    updateTextProp('fontWeight', current === 'bold' || current >= 700 ? 'normal' : 'bold');
  };

  const toggleItalic = () => {
    updateTextProp('fontStyle', activeObject?.fontStyle === 'italic' ? 'normal' : 'italic');
  };

  const toggleUnderline = () => {
    updateTextProp('underline', !activeObject?.underline);
  };

  const toggleStrikethrough = () => {
    updateTextProp('linethrough', !activeObject?.linethrough);
  };

  const filteredFonts = FONT_LIST.filter(f =>
    f.toLowerCase().includes(fontSearch.toLowerCase())
  );

  return (
    <div className="flex flex-col h-full overflow-y-auto">
      {/* Metin ekleme presetleri */}
      <div className="p-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Metin Ekle</h3>
        <div className="space-y-1.5">
          {TEXT_PRESETS.map(preset => (
            <button
              key={preset.label}
              onClick={() => handlePresetAdd(preset)}
              className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg border border-slate-700 hover:border-primary/50 hover:bg-primary/5 transition-all text-left group"
            >
              <div className="w-8 h-8 rounded-lg bg-slate-700/50 flex items-center justify-center shrink-0 group-hover:bg-primary/10">
                <Type size={14} className="text-slate-400 group-hover:text-primary" />
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-[11px] text-slate-500">{preset.label}</p>
                <p className="text-sm text-slate-200 truncate" style={{
                  fontWeight: preset.fontWeight as any,
                  fontStyle: preset.fontStyle as any,
                  fontSize: Math.min(preset.fontSize / 3, 18),
                }}>
                  {preset.text}
                </p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Metin düzenleme - sadece metin seçiliyse */}
      {isTextSelected && (
        <>
          <div className="h-px bg-slate-700 mx-3" />
          <div className="p-3 space-y-3">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Metin Düzenleme</h3>

            {/* Font seçici */}
            <div className="relative">
              <button
                onClick={() => setShowFontPicker(!showFontPicker)}
                className="w-full flex items-center justify-between px-3 py-2 bg-slate-800 border border-slate-700 rounded-lg text-sm text-white hover:border-slate-600 transition-colors"
              >
                <span style={{ fontFamily: activeObject.fontFamily || fontFamily }}>
                  {activeObject.fontFamily || fontFamily}
                </span>
                <ChevronDown size={14} className="text-slate-400" />
              </button>
              {showFontPicker && (
                <>
                  <div className="fixed inset-0 z-30" onClick={() => setShowFontPicker(false)} />
                  <div className="absolute top-full left-0 right-0 mt-1 bg-slate-800 border border-slate-700 rounded-xl shadow-2xl z-40 max-h-60 overflow-hidden flex flex-col">
                    <div className="p-2 border-b border-slate-700">
                      <input
                        type="text"
                        placeholder="Font ara..."
                        value={fontSearch}
                        onChange={e => setFontSearch(e.target.value)}
                        className="w-full px-2 py-1.5 bg-slate-900 border border-slate-600 rounded-lg text-xs text-white placeholder:text-slate-500 focus:outline-none focus:border-primary"
                      />
                    </div>
                    <div className="overflow-y-auto">
                      {filteredFonts.map(font => (
                        <button
                          key={font}
                          onClick={() => {
                            updateTextProp('fontFamily', font);
                            setFontFamily(font);
                            setShowFontPicker(false);
                          }}
                          className={`w-full text-left px-3 py-2 text-sm hover:bg-white/5 transition-colors
                            ${(activeObject.fontFamily || fontFamily) === font ? 'text-primary bg-primary/5' : 'text-slate-300'}`}
                          style={{ fontFamily: font }}
                        >
                          {font}
                        </button>
                      ))}
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* Font boyutu */}
            <div className="flex items-center gap-2">
              <button onClick={() => { const s = Math.max(8, (activeObject.fontSize || 32) - 2); updateTextProp('fontSize', s); setFontSize(s); }}
                className="p-1.5 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors">
                <Minus size={14} />
              </button>
              <input
                type="number"
                value={activeObject.fontSize || fontSize}
                onChange={e => { const s = parseInt(e.target.value) || 16; updateTextProp('fontSize', s); setFontSize(s); }}
                className="flex-1 px-2 py-1.5 bg-slate-800 border border-slate-700 rounded-lg text-sm text-center text-white focus:outline-none focus:border-primary"
                min={8}
                max={200}
              />
              <button onClick={() => { const s = Math.min(200, (activeObject.fontSize || 32) + 2); updateTextProp('fontSize', s); setFontSize(s); }}
                className="p-1.5 text-slate-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors">
                <Plus size={14} />
              </button>
            </div>

            {/* Stil butonları */}
            <div className="flex gap-1">
              <button onClick={toggleBold}
                className={`flex-1 p-2 rounded-lg transition-colors ${activeObject.fontWeight === 'bold' || activeObject.fontWeight >= 700 ? 'bg-primary/20 text-primary' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                <Bold size={15} className="mx-auto" />
              </button>
              <button onClick={toggleItalic}
                className={`flex-1 p-2 rounded-lg transition-colors ${activeObject.fontStyle === 'italic' ? 'bg-primary/20 text-primary' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                <Italic size={15} className="mx-auto" />
              </button>
              <button onClick={toggleUnderline}
                className={`flex-1 p-2 rounded-lg transition-colors ${activeObject.underline ? 'bg-primary/20 text-primary' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                <Underline size={15} className="mx-auto" />
              </button>
              <button onClick={toggleStrikethrough}
                className={`flex-1 p-2 rounded-lg transition-colors ${activeObject.linethrough ? 'bg-primary/20 text-primary' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                <Strikethrough size={15} className="mx-auto" />
              </button>
            </div>

            {/* Hizalama */}
            <div className="flex gap-1">
              {[
                { align: 'left', icon: AlignLeft },
                { align: 'center', icon: AlignCenter },
                { align: 'right', icon: AlignRight },
                { align: 'justify', icon: AlignJustify },
              ].map(({ align, icon: Icon }) => (
                <button
                  key={align}
                  onClick={() => updateTextProp('textAlign', align)}
                  className={`flex-1 p-2 rounded-lg transition-colors ${activeObject.textAlign === align ? 'bg-primary/20 text-primary' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                >
                  <Icon size={15} className="mx-auto" />
                </button>
              ))}
            </div>

            {/* Metin rengi */}
            <div>
              <label className="text-[11px] text-slate-500 mb-1 block">Metin Rengi</label>
              <div className="relative">
                <button
                  onClick={() => setShowColorPicker(!showColorPicker)}
                  className="w-full flex items-center gap-2 px-3 py-2 bg-slate-800 border border-slate-700 rounded-lg hover:border-slate-600 transition-colors"
                >
                  <div className="w-5 h-5 rounded-md border border-slate-600" style={{ backgroundColor: activeObject.fill || fillColor }} />
                  <span className="text-xs text-slate-300">{activeObject.fill || fillColor}</span>
                </button>
                {showColorPicker && (
                  <>
                    <div className="fixed inset-0 z-30" onClick={() => setShowColorPicker(false)} />
                    <div className="absolute top-full left-0 right-0 mt-1 bg-slate-800 border border-slate-700 rounded-xl shadow-2xl z-40 p-3">
                      <div className="grid grid-cols-10 gap-1 mb-3">
                        {COLOR_PALETTE.map(color => (
                          <button
                            key={color}
                            onClick={() => { updateTextProp('fill', color); setFillColor(color); }}
                            className="w-full aspect-square rounded-md border border-slate-600 hover:scale-110 transition-transform"
                            style={{ backgroundColor: color }}
                          />
                        ))}
                      </div>
                      <input
                        type="color"
                        value={activeObject.fill || fillColor}
                        onChange={e => { updateTextProp('fill', e.target.value); setFillColor(e.target.value); }}
                        className="w-full h-8 rounded-lg cursor-pointer"
                      />
                    </div>
                  </>
                )}
              </div>
            </div>

            {/* Satır aralığı */}
            <div>
              <label className="text-[11px] text-slate-500 mb-1 block">Satır Aralığı</label>
              <input
                type="range"
                min={0.5}
                max={3}
                step={0.1}
                value={activeObject.lineHeight || 1.16}
                onChange={e => updateTextProp('lineHeight', parseFloat(e.target.value))}
                className="w-full accent-primary"
              />
              <span className="text-[10px] text-slate-500">{(activeObject.lineHeight || 1.16).toFixed(1)}</span>
            </div>

            {/* Harf aralığı */}
            <div>
              <label className="text-[11px] text-slate-500 mb-1 block">Harf Aralığı</label>
              <input
                type="range"
                min={-200}
                max={800}
                step={10}
                value={activeObject.charSpacing || 0}
                onChange={e => updateTextProp('charSpacing', parseInt(e.target.value))}
                className="w-full accent-primary"
              />
              <span className="text-[10px] text-slate-500">{activeObject.charSpacing || 0}</span>
            </div>

            {/* Metin Efektleri */}
            <div>
              <h4 className="text-[11px] text-slate-500 mb-2 flex items-center gap-1">
                <Sparkles size={12} /> Metin Efektleri
              </h4>
              <div className="grid grid-cols-3 gap-1">
                {TEXT_EFFECTS.map(effect => (
                  <button
                    key={effect.id}
                    onClick={() => {
                      if (effect.apply.shadow) {
                        updateTextProp('shadow', effect.apply.shadow);
                      } else if (effect.apply.shadow === null) {
                        updateTextProp('shadow', null);
                      }
                      if (effect.apply.stroke !== undefined) {
                        updateTextProp('stroke', effect.apply.stroke || null);
                        updateTextProp('strokeWidth', effect.apply.strokeWidth || 0);
                      }
                    }}
                    className="p-2 rounded-lg border border-slate-700 hover:border-primary/50 hover:bg-primary/5 transition-all text-center"
                    title={effect.name}
                  >
                    <span
                      className="text-sm font-bold text-white block"
                      style={{
                        textShadow: effect.apply.shadow
                          ? `${effect.apply.shadow.offsetX}px ${effect.apply.shadow.offsetY}px ${effect.apply.shadow.blur}px ${effect.apply.shadow.color}`
                          : 'none',
                        WebkitTextStroke: effect.apply.stroke ? `${effect.apply.strokeWidth || 1}px ${effect.apply.stroke}` : undefined,
                      }}
                    >
                      {effect.preview}
                    </span>
                    <span className="text-[7px] text-slate-500 mt-0.5 block truncate">{effect.name}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

