  const sizes = {
    sm: 'w-2 h-2',
    md: 'w-3 h-3',
    lg: 'w-4 h-4',
  };

  return (
    <span className={`relative flex items-center gap-2`}>
      <span className={`${sizes[size]} ${config.bg} rounded-full ring-4 ${config.ring}`}>
        {config.pulse && (
          <span className={`absolute inset-0 ${config.bg} rounded-full animate-ping opacity-75`} />
        )}
      </span>
      {size === 'lg' && (
        <span className="text-sm font-medium text-gray-600 dark:text-gray-400">
          {config.label}
        </span>
      )}
    </span>
  );
};

// Single Integration Status Card
const IntegrationStatusCard: React.FC<{
  integration: IntegrationStatusData;
  onViewDetails: () => void;
  onToggleNotifications: (enabled: boolean) => void;
}> = ({ integration, onViewDetails, onToggleNotifications }) => {
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [showActivity, setShowActivity] = useState(false);

  const orderChange =
    integration.metrics.ordersYesterday > 0
      ? ((integration.metrics.ordersToday - integration.metrics.ordersYesterday) /
          integration.metrics.ordersYesterday) *
        100
      : 0;

  const revenueChange =
    integration.metrics.revenueYesterday > 0
      ? ((integration.metrics.revenueToday - integration.metrics.revenueYesterday) /
          integration.metrics.revenueYesterday) *
        100
      : 0;

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 overflow-hidden"
    >
      {/* Header */}
      <div
        className="px-4 py-3 flex items-center justify-between border-b border-gray-100 dark:border-gray-800"
        style={{ background: `linear-gradient(135deg, ${integration.brandColor}08, transparent)` }}
      >
        <div className="flex items-center gap-3">
          <div
            className="w-10 h-10 rounded-lg flex items-center justify-center"
            style={{ backgroundColor: `${integration.brandColor}15` }}
          >
            <img
              src={integration.logo}
              alt={integration.name}
              className="w-6 h-6 object-contain"
              onError={(e) => {
                (e.target as HTMLImageElement).src = `https://ui-avatars.com/api/?name=${integration.name}&background=${integration.brandColor.replace('#', '')}&color=fff&size=40`;
              }}
            />
          </div>
          <div>
            <h3 className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
              {integration.name}
              <StatusIndicator status={integration.status} size="sm" />
            </h3>
            <p className="text-xs text-gray-500 dark:text-gray-400">
              Son senkronizasyon: {new Date(integration.lastSync).toLocaleString('tr-TR')}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => {
              setNotificationsEnabled(!notificationsEnabled);
              onToggleNotifications(!notificationsEnabled);
            }}
            className={`p-2 rounded-lg transition-colors ${
              notificationsEnabled
                ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                : 'bg-gray-100 dark:bg-gray-800 text-gray-400'
            }`}
            title={notificationsEnabled ? 'Bildirimleri Kapat' : 'Bildirimleri Aç'}
          >
            {notificationsEnabled ? (
              <Bell className="w-4 h-4" />
            ) : (
              <BellOff className="w-4 h-4" />
            )}
          </button>
          <button
            onClick={onViewDetails}
            className="p-2 rounded-lg bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
            title="Detayları Görüntüle"
          >
            <Eye className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Sync Progress (if syncing) */}
      {integration.status === 'syncing' && integration.syncProgress !== undefined && (
        <div className="px-4 py-2 bg-blue-50 dark:bg-blue-900/20 border-b border-blue-100 dark:border-blue-800">
          <div className="flex items-center justify-between mb-1">
            <span className="text-xs font-medium text-blue-700 dark:text-blue-400 flex items-center gap-1">
              <Loader2 className="w-3 h-3 animate-spin" />
              Senkronize ediliyor...
            </span>
            <span className="text-xs font-bold text-blue-700 dark:text-blue-400">
              %{integration.syncProgress}
            </span>
          </div>
          <div className="w-full h-1.5 bg-blue-200 dark:bg-blue-800 rounded-full overflow-hidden">
            <motion.div
              initial={{ width: 0 }}
              animate={{ width: `${integration.syncProgress}%` }}
              transition={{ duration: 0.5 }}
              className="h-full bg-blue-600 dark:bg-blue-400 rounded-full"
            />
          </div>
        </div>
      )}

      {/* Metrics */}
      <div className="p-4">
        <div className="grid grid-cols-4 gap-4">
          <div>
            <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mb-1">
              <Package className="w-3 h-3" />
              <span>Ürünler</span>
            </div>
            <p className="font-semibold text-gray-900 dark:text-white">
              {integration.metrics.productsSynced.toLocaleString('tr-TR')}
              <span className="text-xs font-normal text-gray-400">
                /{integration.metrics.productsTotal.toLocaleString('tr-TR')}
              </span>
            </p>
          </div>

          <div>
            <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mb-1">
              <ShoppingCart className="w-3 h-3" />
              <span>Bugünkü Sipariş</span>
            </div>
            <p className="font-semibold text-gray-900 dark:text-white flex items-center gap-1">
              {integration.metrics.ordersToday}
              {orderChange !== 0 && (
                <span
                  className={`text-xs flex items-center ${
                    orderChange > 0 ? 'text-green-600' : 'text-red-600'
                  }`}
                >
                  {orderChange > 0 ? (
                    <TrendingUp className="w-3 h-3" />
                  ) : (
                    <TrendingDown className="w-3 h-3" />
                  )}
                  {Math.abs(Math.round(orderChange))}%
                </span>
              )}
            </p>
          </div>

          <div>
            <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mb-1">
              <DollarSign className="w-3 h-3" />
              <span>Bugünkü Ciro</span>
            </div>
            <p className="font-semibold text-gray-900 dark:text-white flex items-center gap-1">
              ₺{(integration.metrics.revenueToday / 1000).toFixed(1)}K
              {revenueChange !== 0 && (
                <span
                  className={`text-xs flex items-center ${
                    revenueChange > 0 ? 'text-green-600' : 'text-red-600'
                  }`}
                >
                  {revenueChange > 0 ? (
                    <TrendingUp className="w-3 h-3" />
                  ) : (
                    <TrendingDown className="w-3 h-3" />
                  )}
                  {Math.abs(Math.round(revenueChange))}%
                </span>
              )}
            </p>
          </div>

          <div>
            <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mb-1">
              <AlertTriangle className="w-3 h-3" />
              <span>Hatalar</span>
            </div>
            <p className="font-semibold flex items-center gap-2">
              <span className={integration.metrics.errorCount > 0 ? 'text-red-600' : 'text-gray-900 dark:text-white'}>
                {integration.metrics.errorCount}
              </span>
              {integration.metrics.warningCount > 0 && (
                <span className="text-amber-500 text-xs">
                  +{integration.metrics.warningCount} uyarı
                </span>
              )}
            </p>
          </div>
        </div>
      </div>

      {/* Recent Activity Toggle */}
      <div className="border-t border-gray-100 dark:border-gray-800">
        <button
          onClick={() => setShowActivity(!showActivity)}
          className="w-full px-4 py-2 flex items-center justify-between text-sm text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors"
        >
          <span className="flex items-center gap-2">
            <Activity className="w-4 h-4" />
            Son Aktiviteler
            {integration.recentActivity.length > 0 && (
              <span className="px-1.5 py-0.5 bg-gray-100 dark:bg-gray-800 rounded-full text-xs font-medium">
                {integration.recentActivity.length}
              </span>
            )}
          </span>
          <motion.div animate={{ rotate: showActivity ? 90 : 0 }}>
            <ChevronRight className="w-4 h-4" />
          </motion.div>
        </button>

        <AnimatePresence>
          {showActivity && integration.recentActivity.length > 0 && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden"
            >
              <div className="px-4 pb-3 space-y-2">
                {integration.recentActivity.slice(0, 5).map((activity, index) => (
                  <div
                    key={index}
                    className="flex items-start gap-3 text-sm p-2 bg-gray-50 dark:bg-gray-800/50 rounded-lg"
                  >
                    <div
                      className={`p-1 rounded ${
                        activity.type === 'error'
                          ? 'bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400'
                          : activity.type === 'order'
                            ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400'
                            : activity.type === 'product'
                              ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                              : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400'
                      }`}
                    >
                      {activity.type === 'error' && <XCircle className="w-3 h-3" />}
                      {activity.type === 'order' && <ShoppingCart className="w-3 h-3" />}
                      {activity.type === 'product' && <Package className="w-3 h-3" />}
                      {activity.type === 'inventory' && <BarChart3 className="w-3 h-3" />}
                      {activity.type === 'sync' && <RefreshCw className="w-3 h-3" />}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-gray-700 dark:text-gray-300 truncate">
                        {activity.message}
                      </p>
                      <p className="text-xs text-gray-400 dark:text-gray-500">
                        {new Date(activity.time).toLocaleString('tr-TR')}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
};

// Main Panel Component
export const RealTimeStatusPanel: React.FC<RealTimeStatusPanelProps> = ({
  integrations,
  onRefresh,
  onViewDetails,
  onToggleNotifications,
}) => {
  const [lastRefresh, setLastRefresh] = useState(new Date());
  const [isRefreshing, setIsRefreshing] = useState(false);

  const handleRefresh = React.useCallback(async () => {
    setIsRefreshing(true);
    await onRefresh();
    setLastRefresh(new Date());
    setTimeout(() => setIsRefreshing(false), 1000);
  }, [onRefresh]);

  // Auto refresh every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      handleRefresh();
    }, 30000);
    return () => clearInterval(interval);
  }, [handleRefresh]);

  // Calculate summary stats
  const stats = {
    total: integrations.length,
    healthy: integrations.filter((i) => i.status === 'healthy').length,
    warning: integrations.filter((i) => i.status === 'warning').length,
    error: integrations.filter((i) => i.status === 'error').length,
    syncing: integrations.filter((i) => i.status === 'syncing').length,
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <Activity className="w-5 h-5 text-blue-500" />
            Gerçek Zamanlı Durum
          </h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            Son güncelleme: {lastRefresh.toLocaleTimeString('tr-TR')}
          </p>
        </div>

        <button
          onClick={handleRefresh}
          disabled={isRefreshing}
          className={`px-4 py-2 rounded-xl font-medium flex items-center gap-2 transition-all ${
            isRefreshing
              ? 'bg-gray-100 dark:bg-gray-800 text-gray-400 cursor-not-allowed'
              : 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 hover:bg-blue-200 dark:hover:bg-blue-900/50'
          }`}
        >
          <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
          {isRefreshing ? 'Yenileniyor...' : 'Yenile'}
        </button>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-5 gap-3">
        <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 p-3 text-center">
          <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.total}</p>
          <p className="text-xs text-gray-500 dark:text-gray-400">Toplam</p>
        </div>
        <div className="bg-green-50 dark:bg-green-900/20 rounded-xl border border-green-200 dark:border-green-800 p-3 text-center">
          <p className="text-2xl font-bold text-green-700 dark:text-green-400">{stats.healthy}</p>
          <p className="text-xs text-green-600 dark:text-green-500">Sağlıklı</p>
        </div>
        <div className="bg-amber-50 dark:bg-amber-900/20 rounded-xl border border-amber-200 dark:border-amber-800 p-3 text-center">
          <p className="text-2xl font-bold text-amber-700 dark:text-amber-400">{stats.warning}</p>
          <p className="text-xs text-amber-600 dark:text-amber-500">Uyarı</p>
        </div>
        <div className="bg-red-50 dark:bg-red-900/20 rounded-xl border border-red-200 dark:border-red-800 p-3 text-center">
          <p className="text-2xl font-bold text-red-700 dark:text-red-400">{stats.error}</p>
          <p className="text-xs text-red-600 dark:text-red-500">Hata</p>
        </div>
        <div className="bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-200 dark:border-blue-800 p-3 text-center">
          <p className="text-2xl font-bold text-blue-700 dark:text-blue-400">{stats.syncing}</p>
          <p className="text-xs text-blue-600 dark:text-blue-500">Senkronize</p>
        </div>
      </div>

      {/* Integration Status Cards */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {integrations.map((integration) => (
          <IntegrationStatusCard
            key={integration.id}
            integration={integration}
            onViewDetails={() => onViewDetails(integration.id)}
            onToggleNotifications={(enabled) => onToggleNotifications(integration.id, enabled)}
          />
        ))}
      </div>

      {/* Empty State */}
      {integrations.length === 0 && (
        <div className="text-center py-12 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-gray-200 dark:border-gray-700 border-dashed">
          <Zap className="w-12 h-12 mx-auto mb-4 text-gray-400" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
            Henüz aktif entegrasyon yok
          </h3>
          <p className="text-gray-500 dark:text-gray-400 mb-4">
            Pazaryerlerine bağlanarak gerçek zamanlı verileri görüntüleyin
          </p>
          <button className="px-6 py-2.5 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl font-medium flex items-center gap-2 mx-auto">
            <Zap className="w-4 h-4" />
            Entegrasyon Ekle
          </button>
        </div>
      )}
    </div>
  );
};

export default RealTimeStatusPanel;

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Package,
  AlertTriangle,
  TrendingDown,
  Zap,
  BarChart3,
  RefreshCw,
  Plus,
  Minus,
  Filter,
  Download,
  Eye,
  Settings,
  Clock,
  DollarSign,
  Truck,
  CheckCircle,
  XCircle,
  Info,
} from 'lucide-react';

// Types & Data
interface InventoryItem {
  productId: string;
  productName: string;
  sku: string;
  currentStock: number;
  minimumStock: number;
  reorderPoint: number;
  status: 'normal' | 'low' | 'critical' | 'out_of_stock';
  daysUntilStockout: number;
  value: number;
  turnoverRate: number;
}

// Demo data
function generateInventoryData(): InventoryItem[] {
  return [
    { productId: 'p1', productName: 'Elektronik A', sku: 'SKU001', currentStock: 45, minimumStock: 20, reorderPoint: 30, status: 'normal', daysUntilStockout: 45, value: 6750, turnoverRate: 3.2 },
    { productId: 'p2', productName: 'Tekstil B', sku: 'SKU002', currentStock: 8, minimumStock: 15, reorderPoint: 50, status: 'critical', daysUntilStockout: 3, value: 240, turnoverRate: 4.1 },
    { productId: 'p3', productName: 'Aksesuar C', sku: 'SKU003', currentStock: 0, minimumStock: 10, reorderPoint: 25, status: 'out_of_stock', daysUntilStockout: 0, value: 0, turnoverRate: 2.8 },
    { productId: 'p4', productName: 'Kitap D', sku: 'SKU004', currentStock: 234, minimumStock: 50, reorderPoint: 100, status: 'normal', daysUntilStockout: 180, value: 11700, turnoverRate: 1.5 },
    { productId: 'p5', productName: 'Spor E', sku: 'SKU005', currentStock: 12, minimumStock: 25, reorderPoint: 75, status: 'low', daysUntilStockout: 8, value: 1200, turnoverRate: 3.8 },
  ];
}

// Hooks
export function useInventoryManagement() {
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [alerts, setAlerts] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'critical' | 'low' | 'optimal'>('all');
  
  useEffect(() => {
    setTimeout(() => {
      const data = generateInventoryData();
      setItems(data);
      setAlerts(data.filter(item => item.status === 'critical' || item.status === 'out_of_stock'));
      setLoading(false);
    }, 300);
  }, []);
  
  const filteredItems = items.filter(item => {
    if (filter === 'all') return true;
    return item.status === filter;
  });
  
  return { items: filteredItems, allItems: items, alerts, loading, filter, setFilter };
}

// Status Badge
function StatusBadge({ status }: { status: string }) {
  const config = {
    normal: { bg: 'bg-green-100', text: 'text-green-700', label: 'Normal', icon: CheckCircle },
    low: { bg: 'bg-yellow-100', text: 'text-yellow-700', label: 'Düşük', icon: AlertTriangle },
    critical: { bg: 'bg-red-100', text: 'text-red-700', label: 'Kritik', icon: AlertTriangle },
    out_of_stock: { bg: 'bg-red-200', text: 'text-red-800', label: 'Tükendi', icon: XCircle },
  } as any;
  
  const cfg = config[status];
  const Icon = cfg.icon;
  
  return (
    <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${cfg.bg} ${cfg.text}`}>
      <Icon className="w-3 h-3" />
      {cfg.label}
    </span>
  );
}

// Inventory Item Card
function InventoryCard({ item, onRestock }: { item: InventoryItem; onRestock: (id: string) => void }) {
  const stockPercentage = Math.min(100, (item.currentStock / (item.reorderPoint * 2)) * 100);
  
  return (
    <motion.div
      whileHover={{ translateY: -2 }}
      className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700"
    >
      <div className="flex items-start justify-between mb-3">
        <div>
          <p className="font-semibold text-gray-900 dark:text-white">{item.productName}</p>
          <p className="text-xs text-gray-500">{item.sku}</p>
        </div>
        <StatusBadge status={item.status} />
      </div>
      
      {/* Stock Progress */}
      <div className="mb-3">
        <div className="flex items-center justify-between mb-1">
          <span className="text-sm text-gray-600 dark:text-gray-400">Stok</span>
          <span className="font-semibold">{item.currentStock}</span>
        </div>
        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${stockPercentage}%` }}
            className={`h-2 rounded-full ${
              item.status === 'normal' ? 'bg-green-500' :
              item.status === 'low' ? 'bg-yellow-500' :
              'bg-red-500'
            }`}
          />
        </div>
        <p className="text-xs text-gray-500 mt-1">
          Minimum: {item.minimumStock} | Yeniden sipariş: {item.reorderPoint}
        </p>
      </div>
      
      {/* Stats */}
      <div className="grid grid-cols-2 gap-2 mb-3 text-xs">
        <div className="p-2 bg-gray-50 dark:bg-gray-700 rounded">
          <p className="text-gray-500 dark:text-gray-400">Değer</p>
          <p className="font-semibold">₺{(item.value / 1000).toFixed(0)}K</p>
        </div>
        <div className="p-2 bg-gray-50 dark:bg-gray-700 rounded">
          <p className="text-gray-500 dark:text-gray-400">Bitişe Kalan</p>
          <p className="font-semibold">{item.daysUntilStockout}g</p>
        </div>
      </div>
      
      {/* Action Button */}
      {item.status !== 'normal' && (
        <button
          onClick={() => onRestock(item.productId)}
          className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition"
        >
          <Truck className="w-4 h-4" />
          Yeniden Sipariş
        </button>
      )}
    </motion.div>
  );
}

// Main Component
export function InventoryManagementDashboard() {
  const { items, allItems, alerts, loading, filter, setFilter } = useInventoryManagement();
  const [showDetailModal, setShowDetailModal] = useState<string | null>(null);
  
  const totalValue = allItems.reduce((sum, item) => sum + item.value, 0);
  const alertCount = alerts.length;
  
  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold flex items-center gap-2">
            <Package className="w-8 h-8 text-blue-600" />
            Envanter Yönetimi
          </h2>
          <p className="text-gray-500 mt-1">Stok seviyeleri, tahminleri ve otomatik yeniden sipariş</p>
        </div>
        
        <div className="flex items-center gap-2">
          <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            <Plus className="w-4 h-4" />
            Yeni Stok
          </button>
        </div>
      </div>
      
      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 mb-1">Toplam Ürün</p>
          <p className="text-3xl font-bold">{allItems.length}</p>
          <p className="text-xs text-gray-500 mt-1">Değer: ₺{(totalValue / 1000).toFixed(0)}K</p>
        </motion.div>
        
        <motion.div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 mb-1">Kritik Uyarılar</p>
          <p className={`text-3xl font-bold ${alertCount > 0 ? 'text-red-600' : 'text-green-600'}`}>
            {alertCount}
          </p>
          <p className="text-xs text-gray-500 mt-1">Acil eylem gerekli</p>
        </motion.div>
        
        <motion.div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 mb-1">Düşük Stok</p>
          <p className="text-3xl font-bold text-yellow-600">
            {allItems.filter(i => i.status === 'low').length}
          </p>
          <p className="text-xs text-gray-500 mt-1">Uyarı durumunda</p>
        </motion.div>
        
        <motion.div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 mb-1">Tükenen Ürünler</p>
          <p className="text-3xl font-bold text-red-600">
            {allItems.filter(i => i.status === 'out_of_stock').length}
          </p>
          <p className="text-xs text-gray-500 mt-1">Stok dışında</p>
        </motion.div>
      </div>
      
      {/* Filters */}
      <div className="flex items-center gap-2">
        {(['all', 'optimal', 'low', 'critical'] as const).map(f => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
              filter === f
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'
            }`}
          >
            {f === 'all' ? 'Tümü' : f === 'optimal' ? 'Optimal' : f === 'low' ? 'Düşük' : 'Kritik'}
          </button>
        ))}
      </div>
      
      {/* Inventory Grid */}
      {loading ? (
        <div className="text-center py-8">
          <div className="animate-spin w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full mx-auto" />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {items.map(item => (
            <InventoryCard
              key={item.productId}
              item={item}
              onRestock={() => alert(`${item.productName} için yeniden sipariş oluşturuldu`)}
            />
          ))}
        </div>
      )}
      
      {/* Alerts Section */}
      {alerts.length > 0 && (
        <motion.div className="bg-white dark:bg-gray-800 rounded-lg p-6 border border-red-200 dark:border-red-500/30">
          <h3 className="font-semibold mb-4 flex items-center gap-2 text-red-600">
            <AlertTriangle className="w-5 h-5" />
            Acil Uyarılar ({alerts.length})
          </h3>
          <div className="space-y-2">
            {alerts.map(alert => (
              <div key={alert.productId} className="flex items-center justify-between p-3 bg-red-50 dark:bg-red-500/10 rounded">
                <div>
                  <p className="font-medium">{alert.productName}</p>
                  <p className="text-sm text-gray-500">
                    {alert.status === 'out_of_stock' ? 'Stok tükendi' : `${alert.daysUntilStockout} gün içinde tükenir`}
                  </p>
                </div>
                <button className="px-3 py-1 bg-red-600 text-white rounded text-sm hover:bg-red-700">
                  Sipariş Ver
                </button>
              </div>
            ))}
          </div>
        </motion.div>
      )}
    </div>
  );
}

