'use client';

import React, { useEffect, useRef, useState } from 'react';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { ArrowRight, Sparkles, Zap, Target, Play } from 'lucide-react';

interface Hero3DProps {
    features?: {
        hero3D?: {
            enabled: boolean;
            particleCount: number;
            waveIntensity: number;
            interactive: boolean;
        };
    };
}

export const Hero3D = ({ features }: Hero3DProps) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [isLoaded, setIsLoaded] = useState(false);
    const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

    // Motion values for smooth interactions
    const mouseX = useMotionValue(0);
    const mouseY = useMotionValue(0);
    const smoothX = useSpring(mouseX, { stiffness: 100, damping: 30 });
    const smoothY = useSpring(mouseY, { stiffness: 100, damping: 30 });

    const particleCount = features?.hero3D?.particleCount || 150;
    const waveIntensity = features?.hero3D?.waveIntensity || 0.5;
    const interactive = features?.hero3D?.interactive !== false;

    useEffect(() => {
        if (!canvasRef.current || !features?.hero3D?.enabled) return;

        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Set canvas size
        const resizeCanvas = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        resizeCanvas();
        window.addEventListener('resize', resizeCanvas);

        // Particle system
        class Particle {
            x: number;
            y: number;
            vx: number;
            vy: number;
            size: number;
            color: string;
            life: number;
            maxLife: number;

            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.vx = (Math.random() - 0.5) * 0.5;
                this.vy = (Math.random() - 0.5) * 0.5;
                this.size = Math.random() * 3 + 1;
                this.color = [
                    'rgba(59, 130, 246, 0.6)',  // blue
                    'rgba(147, 51, 234, 0.6)',  // purple
                    'rgba(34, 197, 94, 0.6)',   // emerald
                    'rgba(251, 146, 60, 0.6)'   // orange
                ][Math.floor(Math.random() * 4)];
                this.life = 0;
                this.maxLife = Math.random() * 100 + 100;
            }

            update(mouseX: number, mouseY: number) {
                // Basic movement
                this.x += this.vx;
                this.y += this.vy;

                // Mouse interaction
                if (interactive) {
                    const dx = mouseX - this.x;
                    const dy = mouseY - this.y;
                    const distance = Math.sqrt(dx * dx + dy * dy);

                    if (distance < 100) {
                        const force = (100 - distance) / 100;
                        this.vx -= (dx / distance) * force * 0.5;
                        this.vy -= (dy / distance) * force * 0.5;
                    }
                }

                // Wave effect
                this.vy += Math.sin(Date.now() * 0.001 + this.x * 0.01) * waveIntensity * 0.1;

                // Damping
                this.vx *= 0.99;
                this.vy *= 0.99;

                // Boundaries
                if (this.x < 0 || this.x > canvas.width) this.vx *= -1;
                if (this.y < 0 || this.y > canvas.height) this.vy *= -1;

                // Life cycle
                this.life++;
                if (this.life > this.maxLife) {
                    this.x = Math.random() * canvas.width;
                    this.y = Math.random() * canvas.height;
                    this.life = 0;
                    this.maxLife = Math.random() * 100 + 100;
                }
            }

            draw(ctx: CanvasRenderingContext2D) {
                const opacity = 1 - (this.life / this.maxLife);
                ctx.globalAlpha = opacity * 0.6;
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();

                // Glow effect
                ctx.globalAlpha = opacity * 0.2;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size * 3, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        // Create particles
        const particles: Particle[] = [];
        for (let i = 0; i < particleCount; i++) {
            particles.push(new Particle());
        }

        // Animation loop
        let animationId: number;
        const animate = () => {
            ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw connections
            ctx.globalAlpha = 0.1;
            ctx.strokeStyle = 'rgba(59, 130, 246, 0.3)';
            ctx.lineWidth = 1;

            for (let i = 0; i < particles.length; i++) {
                for (let j = i + 1; j < particles.length; j++) {
                    const dx = particles[i].x - particles[j].x;
                    const dy = particles[i].y - particles[j].y;
                    const distance = Math.sqrt(dx * dx + dy * dy);

                    if (distance < 100) {
                        ctx.globalAlpha = (1 - distance / 100) * 0.2;
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.stroke();
                    }
                }
            }

            // Update and draw particles
            particles.forEach(particle => {
                particle.update(mousePosition.x, mousePosition.y);
                particle.draw(ctx);
            });

            animationId = requestAnimationFrame(animate);
        };

        animate();
        setIsLoaded(true);

        // Mouse tracking
        const handleMouseMove = (e: MouseEvent) => {
            setMousePosition({ x: e.clientX, y: e.clientY });
            mouseX.set(e.clientX);
            mouseY.set(e.clientY);
        };

        if (interactive) {
            window.addEventListener('mousemove', handleMouseMove);
        }

        return () => {
            cancelAnimationFrame(animationId);
            window.removeEventListener('resize', resizeCanvas);
            if (interactive) {
                window.removeEventListener('mousemove', handleMouseMove);
            }
        };
    }, [particleCount, waveIntensity, interactive, mouseX, mouseY, features?.hero3D?.enabled]);

    if (!features?.hero3D?.enabled) return null;

