// Main Onboarding Component
export function UserOnboarding() {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [isVisible, setIsVisible] = useState(true);
  const [isCompleted, setIsCompleted] = useState(false);
  const router = useRouter();

  const steps: OnboardingStep[] = [
    {
      id: "welcome",
      title: "Hoş Geldiniz",
      description: "Platformu keşfedin",
      icon: Sparkles,
      component: WelcomeStep,
      skippable: false,
    },
    {
      id: "profile",
      title: "Profil",
      subtitle: "Kişisel bilgiler",
      description: "Profil bilgilerinizi girin",
      icon: User,
      component: ProfileSetupStep,
      skippable: true,
    },
    {
      id: "tenant",
      title: "Mağaza",
      subtitle: "İşletme kurulumu",
      description: "Mağazanızı oluşturun",
      icon: Building2,
      component: TenantSetupStep,
      skippable: true,
    },
    {
      id: "platforms",
      title: "Pazaryerleri",
      subtitle: "Platform bağlantıları",
      description: "Pazaryerlerinizi bağlayın",
      icon: Store,
      component: PlatformConnectStep,
      skippable: true,
    },
    {
      id: "tour",
      title: "Dashboard",
      subtitle: "Özellik tanıtımı",
      description: "Dashboard turu",
      icon: BarChart3,
      component: DashboardTourStep,
      skippable: false,
    },
    {
      id: "complete",
      title: "Tebrikler!",
      description: "Onboarding tamamlandı",
      icon: Trophy,
      component: CompletionStep,
      skippable: false,
    },
  ];

  const currentStep = steps[currentStepIndex];
  const progress = ((currentStepIndex + 1) / steps.length) * 100;

  const handleNext = useCallback(() => {
    if (currentStepIndex < steps.length - 1) {
      setCurrentStepIndex(currentStepIndex + 1);
    } else {
      handleComplete();
    }
  }, [currentStepIndex, steps.length]);

  const handleBack = useCallback(() => {
    if (currentStepIndex > 0) {
      setCurrentStepIndex(currentStepIndex - 1);
    }
  }, [currentStepIndex]);

  const handleSkip = useCallback(() => {
    if (currentStep.skippable) {
      handleNext();
    }
  }, [currentStep.skippable, handleNext]);

  const handleComplete = useCallback(async () => {
    setIsCompleted(true);

    // Save onboarding completion to API
    try {
      await fetch("/api/onboarding/complete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          completedSteps: steps.map((s) => s.id),
          totalTimeSpent: 0, // Calculate if needed
        }),
      });
    } catch (error) {
      console.error("Failed to save onboarding completion:", error);
    }

    // Close onboarding and redirect to dashboard
    setTimeout(() => {
      setIsVisible(false);
      router.push("/dashboard");
    }, 500);
  }, [router, steps]);

  const handleClose = useCallback(() => {
    setIsVisible(false);
  }, []);

  if (!isVisible) return null;

  const StepComponent = currentStep.component;

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm"
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            className="w-full max-w-lg bg-white rounded-3xl shadow-2xl overflow-hidden"
          >
            {/* Header with progress */}
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-slate-600">
                    Adım {currentStepIndex + 1} / {steps.length}
                  </span>
                </div>
                <button
                  onClick={handleClose}
                  className="p-2 hover:bg-slate-200 rounded-full transition-colors"
                >
                  <X className="w-4 h-4 text-slate-500" />
                </button>
              </div>

              {/* Progress bar */}
              <div className="h-2 bg-slate-200 rounded-full overflow-hidden">
                <motion.div
                  className="h-full bg-gradient-to-r from-blue-500 to-purple-600"
                  initial={{ width: 0 }}
                  animate={{ width: `${progress}%` }}
                  transition={{ duration: 0.3 }}
                />
              </div>
            </div>

            {/* Step content */}
            <div className="p-6">
              <StepComponent
                onNext={handleNext}
                onBack={handleBack}
                onSkip={handleSkip}
                isFirst={currentStepIndex === 0}
                isLast={currentStepIndex === steps.length - 1}
                progress={progress}
              />
            </div>

            {/* Step indicators */}
            <div className="px-6 pb-4">
              <div className="flex justify-center gap-2">
                {steps.map((step, index) => (
                  <div
                    key={step.id}
                    className={`w-2 h-2 rounded-full transition-all ${
                      index === currentStepIndex
                        ? "w-6 bg-blue-500"
                        : index < currentStepIndex
                        ? "bg-green-500"
                        : "bg-slate-300"
                    }`}
                  />
                ))}
              </div>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

