          </div>
          <button onClick={onClose} className="p-2 hover:bg-blue-600 rounded-lg">
            <X className="w-5 h-5" />
          </button>
        </div>
        
        <div className="p-6 space-y-4">
          {step === 'method' && (
            <>
              <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
