  color?: string;
}

export function StatCardWithSparkline({ title, value, change, data, color = '#3b82f6' }: StatCardProps) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  return (
    <motion.div
      className="glass-panel rounded-xl p-4"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
    >
      <p className="text-sm text-white/60">{title}</p>
      <div className="flex items-end justify-between mt-1">
        <span className="text-2xl font-bold text-white">{value}</span>
        {change !== undefined && (
          <span className={`text-sm ${change >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
            {change >= 0 ? '+' : ''}{change}%
          </span>
        )}
      </div>

      {/* Sparkline */}
      <svg className="w-full h-12 mt-3" viewBox={`0 0 ${data.length - 1} 50`} preserveAspectRatio="none">
        <motion.path
          d={`M0,${50 - ((data[0] - min) / range) * 50} ${data
            .slice(1)
            .map((d, i) => `L${i + 1},${50 - ((d - min) / range) * 50}`)
            .join(' ')}`}
          fill="none"
          stroke={color}
          strokeWidth="2"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{ duration: 1.5, ease: 'easeInOut' }}
        />
        <motion.path
          d={`M0,${50 - ((data[0] - min) / range) * 50} ${data
            .slice(1)
            .map((d, i) => `L${i + 1},${50 - ((d - min) / range) * 50}`)
            .join(' ')} L${data.length - 1},50 L0,50 Z`}
          fill={color}
          fillOpacity="0.1"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5, duration: 0.5 }}
        />
      </svg>
    </motion.div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { cn } from '@/lib/utils';

interface DarkModeImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  invert?: boolean;
  brightness?: number;
  contrast?: number;
  saturate?: number;
}

export function DarkModeImage({
  className,
  invert = false,
  brightness = 0.9,
  contrast = 1.1,
  saturate = 0.9,
  style,
  ...props
}: DarkModeImageProps) {
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    const checkTheme = () => {
      const isDarkMode = document.documentElement.getAttribute('data-theme') === 'dark' ||
        window.matchMedia('(prefers-color-scheme: dark)').matches;
      setIsDark(isDarkMode);
    };

    checkTheme();

    const observer = new MutationObserver(checkTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });

    return () => observer.disconnect();
  }, []);

  const darkModeFilter = isDark
    ? `${invert ? 'invert(1) ' : ''}brightness(${brightness}) contrast(${contrast}) saturate(${saturate})`
    : undefined;

  return (
    <img
      className={cn('transition-all duration-300', className)}
      style={{
        ...style,
        filter: darkModeFilter,
      }}
      {...props}
    />
  );
}

// Container for images that applies consistent dark mode styling
interface DarkModeImageContainerProps {
  children: React.ReactNode;
  className?: string;
  preserveColors?: boolean;
}

export function DarkModeImageContainer({
  children,
  className,
  preserveColors = false,
}: DarkModeImageContainerProps) {
  return (
    <div
      className={cn(
        'relative overflow-hidden',
        !preserveColors && '[&:has(img)]:dark:[&_img]:brightness-90 [&:has(img)]:dark:[&_img]:contrast-110',
        className
      )}
    >
      {children}
    </div>
  );
}

// CSS-in-JS helper for global image styles
export function DarkModeImageStyles() {
  return (
    <style jsx global>{`
      [data-theme="dark"] img:not([data-preserve-colors]) {
        filter: brightness(0.9) contrast(1.05);
      }

      [data-theme="dark"] img[data-invert] {
        filter: invert(1) brightness(0.9) contrast(1.05);
      }

      [data-theme="dark"] .product-image {
        filter: brightness(0.95) contrast(1.02);
      }

      [data-theme="dark"] .avatar-image {
        filter: none;
      }

      [data-theme="dark"] .logo-image {
        filter: brightness(1.1);
      }
    `}</style>
  );
}

// Hook for detecting dark mode
export function useDarkMode() {
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    const checkDark = () => {
      const dark = document.documentElement.getAttribute('data-theme') === 'dark' ||
        window.matchMedia('(prefers-color-scheme: dark)').matches;
      setIsDark(dark);
    };

    checkDark();

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    mediaQuery.addEventListener('change', checkDark);

    const observer = new MutationObserver(checkDark);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });

    return () => {
      mediaQuery.removeEventListener('change', checkDark);
      observer.disconnect();
    };
  }, []);

  return isDark;
}

