    setLoading(true);
    try {
      return await apiClient.bulkApplyOptimizations(optimizationIds, syncToPlatform);
    } finally {
      setLoading(false);
    }
  };

  return { optimizeDeep, generateDesc, apply, bulkApply, result, loading };
}

