'use client';

import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { tr, Dictionary } from './dictionaries/tr';
import { en } from './dictionaries/en';

type Locale = 'tr' | 'en';

const dictionaries: Record<Locale, Dictionary> = {
  tr,
  en: en as Dictionary,
};

interface I18nContextType {
  locale: Locale;
  t: Dictionary;
  setLocale: (locale: Locale) => void;
  formatCurrency: (amount: number, currency?: string) => string;
  formatDate: (date: Date | string, options?: Intl.DateTimeFormatOptions) => string;
  formatNumber: (num: number) => string;
  formatRelativeTime: (date: Date | string) => string;
}

const I18nContext = createContext<I18nContextType | undefined>(undefined);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>('tr');
  const [dictionary, setDictionary] = useState<Dictionary>(tr);

  // İlk mount'da localStorage'dan dil oku
  useEffect(() => {
    const stored = localStorage.getItem('locale') as Locale | null;
    if (stored && ['tr', 'en'].includes(stored)) {
      setLocaleState(stored);
      setDictionary(dictionaries[stored]);
    }
  }, []);

  const setLocale = useCallback((newLocale: Locale) => {
    setLocaleState(newLocale);
    setDictionary(dictionaries[newLocale]);
    localStorage.setItem('locale', newLocale);
    document.documentElement.lang = newLocale;
  }, []);

  const formatCurrency = useCallback((amount: number, currency = 'TRY'): string => {
    return new Intl.NumberFormat(locale === 'tr' ? 'tr-TR' : 'en-US', {
      style: 'currency',
      currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);
  }, [locale]);

  const formatDate = useCallback((
    date: Date | string,
    options: Intl.DateTimeFormatOptions = { dateStyle: 'medium' }
  ): string => {
    const d = typeof date === 'string' ? new Date(date) : date;
    return new Intl.DateTimeFormat(locale === 'tr' ? 'tr-TR' : 'en-US', options).format(d);
  }, [locale]);

  const formatNumber = useCallback((num: number): string => {
    return new Intl.NumberFormat(locale === 'tr' ? 'tr-TR' : 'en-US').format(num);
  }, [locale]);

  const formatRelativeTime = useCallback((date: Date | string): string => {
    const d = typeof date === 'string' ? new Date(date) : date;
    const now = new Date();
    const diffMs = now.getTime() - d.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    const t = dictionary.time;

    if (diffMins < 1) return t.now;
    if (diffMins < 60) return `${diffMins} ${t.minutes} ${t.ago}`;
    if (diffHours < 24) return `${diffHours} ${t.hours} ${t.ago}`;
    if (diffDays === 1) return t.yesterday;
    if (diffDays < 7) return `${diffDays} ${t.days} ${t.ago}`;
    
    return formatDate(d);
  }, [dictionary, formatDate]);

  return (
    <I18nContext.Provider
      value={{
        locale,
        t: dictionary,
        setLocale,
        formatCurrency,
        formatDate,
        formatNumber,
        formatRelativeTime,
      }}
    >
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useI18n must be used within an I18nProvider');
  }
  return context;
}

// Dil seçici bileşeni
export function LanguageSelector() {
  const { locale, setLocale } = useI18n();

  return (
    <select
      value={locale}
      onChange={(e) => setLocale(e.target.value as Locale)}
      className="px-3 py-2 bg-gray-100 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-500"
    >
      <option value="tr">🇹🇷 Türkçe</option>
      <option value="en">🇬🇧 English</option>
    </select>
  );
}

"use client";

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useSession } from 'next-auth/react';
import { SystemModule, Plan, ModuleAccess, Announcement } from './types';
import apiClient from '../api-client';
import { DEFAULT_MODULES, getModuleByKey } from './default-modules';

interface ModuleContextType {
  // Tenant bilgileri
  tenantId: string;
  tenantPlan: Plan;
  
  // Modül bilgileri
  allModules: SystemModule[];
  enabledModules: string[];
  
  // Duyurular
  announcements: Announcement[];
  unreadAnnouncementCount: number;
  
  // Fonksiyonlar
  hasModuleAccess: (moduleKey: string) => boolean;
  getModuleAccess: (moduleKey: string) => ModuleAccess;
  isModuleEnabled: (moduleKey: string) => boolean;
  canAccessRoute: (path: string) => boolean;
  
  // Duyuru fonksiyonları
  markAnnouncementAsRead: (id: string) => void;
  dismissAnnouncement: (id: string) => void;
  
  // Admin fonksiyonları (sadece admin paneli için)
  toggleModule: (moduleKey: string, enabled: boolean) => Promise<void>;
  updateModuleConfig: (moduleKey: string, config: Record<string, unknown>) => Promise<void>;
  
  // Loading state
  isLoading: boolean;
}

const ModuleContext = createContext<ModuleContextType | undefined>(undefined);

// Duyurular API'den yüklenecek
// fetchAnnouncements API call kullanılmalı

export function ModuleProvider({ children }: { children: ReactNode }) {
  const { data: session } = useSession();
  const [isLoading, setIsLoading] = useState(true);
  const [tenantId, setTenantId] = useState<string>('');
  const [tenantPlan, setTenantPlan] = useState<Plan>('FREE');
  const [enabledModules, setEnabledModules] = useState<string[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  
  useEffect(() => {
    const loadData = async () => {
      if (!session?.user) {
        setIsLoading(false);
        return;
      }

      setIsLoading(true);
      try {
        // Session'dan tenantId al
        const tid = (session.user as any)?.tenantId;
        if (tid) {
          setTenantId(tid);
          try {
            apiClient.setTenantId(tid);
          } catch (e) {
            console.warn('Failed to set tenantId on apiClient', e);
          }
        } else {
          // clear any previous tenant on the client when no tenant in session
          try { apiClient.setTenantId(''); } catch {};
        }

        // TODO: API'den gerçek tenant bilgileri yükle
        // const response = await fetch(`/api/tenant/${tid}`);
        // const { tenant, announcements } = await response.json();
        // setTenantPlan(tenant.plan);
        // setEnabledModules(tenant.enabledModules);
        // setAnnouncements(announcements);

        setEnabledModules([]);
        setAnnouncements([]);
      } catch (error) {
        console.error('Failed to load tenant data:', error);
        setEnabledModules([]);
      } finally {
        setIsLoading(false);
      }
    };
    
    loadData();
  }, [session]);
  
  const hasModuleAccess = (moduleKey: string): boolean => {
    const sysModule = getModuleByKey(moduleKey);
    if (!sysModule) return false;
    
    // Core modüller her zaman erişilebilir
    if (sysModule.isCore) return true;
    
    // Plan kontrolü
    const planOrder: Plan[] = ['FREE', 'PRO', 'ENTERPRISE'];
    const currentPlanIndex = planOrder.indexOf(tenantPlan);
    const requiredPlanIndex = planOrder.indexOf(sysModule.requiredPlan);
    
    if (requiredPlanIndex > currentPlanIndex) return false;
    
    // Modül aktif mi kontrolü
    return enabledModules.includes(moduleKey);
  };
  
  const getModuleAccess = (moduleKey: string): ModuleAccess => {
    const sysModule = getModuleByKey(moduleKey);
    const planOrder: Plan[] = ['FREE', 'PRO', 'ENTERPRISE'];
    const currentPlanIndex = planOrder.indexOf(tenantPlan);
    
    if (!sysModule) {
      return {
        hasAccess: false,
        isEnabled: false,
        isTrial: false,
        requiredPlan: 'FREE',
        currentPlan: tenantPlan,
        canUpgrade: false,
      };
    }
    
    const requiredPlanIndex = planOrder.indexOf(sysModule.requiredPlan);
    const isEnabled = enabledModules.includes(moduleKey);
    const hasAccess = sysModule.isCore || (requiredPlanIndex <= currentPlanIndex && isEnabled);
    
    return {
      hasAccess,
      isEnabled,
      isTrial: false,
      requiredPlan: sysModule.requiredPlan,
      currentPlan: tenantPlan,
      canUpgrade: requiredPlanIndex > currentPlanIndex,
    };
  };
  
  const isModuleEnabled = (moduleKey: string): boolean => {
    return enabledModules.includes(moduleKey);
  };
  
  const canAccessRoute = (path: string): boolean => {
    const sysModule = DEFAULT_MODULES.find(m => m.menuPath === path);
    if (!sysModule) return true;
    return hasModuleAccess(sysModule.key);
  };
  
  const markAnnouncementAsRead = (id: string) => {
    setAnnouncements(prev => 
      prev.map(a => a.id === id ? { ...a, isRead: true } : a)
    );
  };
  
  const dismissAnnouncement = (id: string) => {
    setAnnouncements(prev => 
      prev.map(a => a.id === id ? { ...a, isDismissed: true } : a)
    );
  };
  
  const toggleModule = async (moduleKey: string, enabled: boolean) => {
    // TODO: API çağrısı yap module durumunu güncelle
    if (enabled) {
      setEnabledModules(prev => [...prev, moduleKey]);
    } else {
      setEnabledModules(prev => prev.filter(k => k !== moduleKey));
    }
  };
  
  const updateModuleConfig = async (moduleKey: string, config: Record<string, unknown>) => {
    // TODO: API çağrısı yap module config'i güncelle
  };
  
  const unreadAnnouncementCount = announcements.filter(
    a => !a.isRead && !a.isDismissed && a.isActive
  ).length;
  
  return (
    <ModuleContext.Provider
      value={{
        tenantId,
        tenantPlan,
        allModules: DEFAULT_MODULES as SystemModule[],
        enabledModules,
        announcements,
        unreadAnnouncementCount,
        hasModuleAccess,
        getModuleAccess,
        isModuleEnabled,
        canAccessRoute,
        markAnnouncementAsRead,
        dismissAnnouncement,
        toggleModule,
        updateModuleConfig,
        isLoading,
      }}
    >
      {children}
    </ModuleContext.Provider>
  );
}

export function useModules() {
  const context = useContext(ModuleContext);
  if (context === undefined) {
    throw new Error('useModules must be used within a ModuleProvider');
  }
  return context;
}

// Belirli bir modül için hook
export function useModule(moduleKey: string) {
  const { hasModuleAccess, getModuleAccess, isModuleEnabled } = useModules();
  
  return {
    hasAccess: hasModuleAccess(moduleKey),
    access: getModuleAccess(moduleKey),
    isEnabled: isModuleEnabled(moduleKey),
    module: getModuleByKey(moduleKey),
  };
}

// Duyurular için hook
export function useAnnouncements() {
  const { 
    announcements, 
    unreadAnnouncementCount, 
    markAnnouncementAsRead, 
    dismissAnnouncement 
  } = useModules();
  
  // Güvenli filter - announcements undefined olabilir
  const safeAnnouncements = announcements || [];
  
  const activeAnnouncements = safeAnnouncements.filter(
    a => a.isActive && !a.isDismissed && (!a.endsAt || new Date(a.endsAt) > new Date())
  );
  
  const pinnedAnnouncements = activeAnnouncements.filter(a => a.isPinned);
  const regularAnnouncements = activeAnnouncements.filter(a => !a.isPinned);
  
  return {
    all: safeAnnouncements,
    active: activeAnnouncements,
    pinned: pinnedAnnouncements,
    regular: regularAnnouncements,
    unreadCount: unreadAnnouncementCount,
    markAsRead: markAnnouncementAsRead,
    dismiss: dismissAnnouncement,
  };
}

// Modül Sistemi Type Tanımlamaları

export type ModuleCategory = 
  | 'AI_TOOLS'
  | 'ANALYTICS'
  | 'MARKETPLACE'
  | 'FINANCE'
  | 'MARKETING'
  | 'LOGISTICS'
  | 'AUTOMATION'
  | 'REPORTS';

export type Plan = 'FREE' | 'PRO' | 'ENTERPRISE';

export type AnnouncementType = 
  | 'INFO'
  | 'WARNING'
  | 'SUCCESS'
  | 'PROMOTION'
  | 'MAINTENANCE'
  | 'UPDATE';

export type AnnouncementTarget = 
  | 'ALL'
  | 'FREE_USERS'
  | 'PRO_USERS'
  | 'ENTERPRISE_USERS'
  | 'SPECIFIC_TENANTS';

export interface SystemModule {
  id: string;
  key: string;
  name: string;
  description?: string;
  icon?: string;
  category: ModuleCategory;
  
  // Fiyatlandırma
  basePrice: number;
  monthlyPrice: number;
  yearlyPrice?: number;
  
  // Plan kısıtlamaları
  requiredPlan: Plan;
  isCore: boolean;
  isActive: boolean;
  isBeta: boolean;
  isNew: boolean;
  
  // Özellikler
  features?: string[];
  config?: Record<string, any>;
  permissions?: string[];
  dependencies?: string[];
  
  // İstatistikler
  usageCount: number;
  rating?: number;
  
  // Menü
  sortOrder: number;
  showInMenu: boolean;
  menuPath?: string;
  
  createdAt: Date;
  updatedAt: Date;
}

export interface TenantModule {
  id: string;
  tenantId: string;
  moduleId: string;
  module?: SystemModule;
  
  isEnabled: boolean;
  customConfig?: Record<string, any>;
  
  startDate: Date;
  endDate?: Date;
  isTrial: boolean;
  trialEndsAt?: Date;
  
  lastUsedAt?: Date;
  usageCount: number;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  summary?: string;
  
  type: AnnouncementType;
  target: AnnouncementTarget;
  targetTenants?: string[];
  
  icon?: string;
  color?: string;
  imageUrl?: string;
  actionUrl?: string;
  actionText?: string;
  
  startsAt: Date;
  endsAt?: Date;
  
  isActive: boolean;
  isPinned: boolean;
  priority: number;
  
  viewCount: number;
  dismissCount: number;
  
  createdBy?: string;
  createdAt: Date;
  updatedAt: Date;
  
  isRead?: boolean;
  isDismissed?: boolean;
}

export interface ModuleAccess {
  hasAccess: boolean;
  isEnabled: boolean;
